    private struct AuthoritativeCyanPlaneTileKey : System.IEquatable<AuthoritativeCyanPlaneTileKey>
    {
        public int PlaneId;
        public int U;
        public int V;

        public bool Equals(AuthoritativeCyanPlaneTileKey other)
        {
            return PlaneId == other.PlaneId && U == other.U && V == other.V;
        }

        public override bool Equals(object obj)
        {
            return obj is AuthoritativeCyanPlaneTileKey other && Equals(other);
        }

        public override int GetHashCode()
        {
            unchecked
            {
                int hash = PlaneId;
                hash = hash * 397 ^ U;
                hash = hash * 397 ^ V;
                return hash;
            }
        }
    }

