    private sealed class CooperativeRebuildBudget
    {
        public readonly bool Enabled;
        public readonly double BudgetMilliseconds;
        public double SliceStart;
        public double CompletedComputeSeconds;
        public int YieldCount;
        public float MaxSliceMilliseconds;

        public CooperativeRebuildBudget(bool enabled, float budgetMilliseconds)
        {
            Enabled = enabled;
            BudgetMilliseconds = Mathf.Max(0.25f, budgetMilliseconds);
            SliceStart = Time.realtimeSinceStartupAsDouble;
        }

        public bool ShouldYield()
        {
            return Enabled &&
                   (Time.realtimeSinceStartupAsDouble - SliceStart) * 1000.0 >=
                   BudgetMilliseconds;
        }

        public void CompleteSliceForYield()
        {
            double now = Time.realtimeSinceStartupAsDouble;
            double sliceSeconds = now - SliceStart;
            CompletedComputeSeconds += sliceSeconds;
            MaxSliceMilliseconds = Mathf.Max(
                MaxSliceMilliseconds, (float)(sliceSeconds * 1000.0));
            YieldCount++;
        }

        public void Resume()
        {
            SliceStart = Time.realtimeSinceStartupAsDouble;
        }

        public double GetComputeSecondsSnapshot()
        {
            return CompletedComputeSeconds +
                   (Time.realtimeSinceStartupAsDouble - SliceStart);
        }

        public float CompleteAndGetComputeMilliseconds()
        {
            double sliceSeconds = Time.realtimeSinceStartupAsDouble - SliceStart;
            CompletedComputeSeconds += sliceSeconds;
            MaxSliceMilliseconds = Mathf.Max(
                MaxSliceMilliseconds, (float)(sliceSeconds * 1000.0));
            return (float)(CompletedComputeSeconds * 1000.0);
        }
    }

