    private sealed class AuthoritativeTsdfBlockMesh
    {
        public readonly List<Vector3> Vertices = new List<Vector3>(256);
        // Canonical spatial identity for every vertex.  Halo extraction may emit
        // the same cell/component in adjacent blocks; this key lets both blocks
        // consume one shared plane decision instead of deciding independently.
        public readonly List<AuthoritativeCellComponentKey> VertexKeys =
            new List<AuthoritativeCellComponentKey>(256);
        public readonly List<int> Triangles = new List<int>(512);
        public readonly List<AuthoritativeTriangleSource> TriangleSources = new List<AuthoritativeTriangleSource>(192);
        public int MultiComponentCells;
        public int SplitVertices;
        public int MissingRebuilds;
    }

    private static Dictionary<Vector3Int, AuthoritativeTsdfBlockMesh> CloneAuthoritativeTsdfBlockMeshes(
        IReadOnlyDictionary<Vector3Int, AuthoritativeTsdfBlockMesh> source)
    {
        Dictionary<Vector3Int, AuthoritativeTsdfBlockMesh> clone =
            new Dictionary<Vector3Int, AuthoritativeTsdfBlockMesh>(source != null ? source.Count : 0);
        if (source == null)
            return clone;
        foreach (KeyValuePair<Vector3Int, AuthoritativeTsdfBlockMesh> pair in source)
        {
            AuthoritativeTsdfBlockMesh input = pair.Value;
            if (input == null)
                continue;
            AuthoritativeTsdfBlockMesh copy = new AuthoritativeTsdfBlockMesh
            {
                MultiComponentCells = input.MultiComponentCells,
                SplitVertices = input.SplitVertices,
                MissingRebuilds = input.MissingRebuilds
            };
            copy.Vertices.AddRange(input.Vertices);
            copy.VertexKeys.AddRange(input.VertexKeys);
            copy.Triangles.AddRange(input.Triangles);
            copy.TriangleSources.AddRange(input.TriangleSources);
            clone[pair.Key] = copy;
        }
        return clone;
    }

    private sealed class PlaneConstrainedZeroCrossShadowStats
    {
        public readonly HashSet<AuthoritativeCellComponentKey> AppliedKeys =
            new HashSet<AuthoritativeCellComponentKey>();
        public readonly HashSet<AuthoritativeCellComponentKey> OverflowKeys =
            new HashSet<AuthoritativeCellComponentKey>();
        public readonly Dictionary<int, PlaneConstrainedZeroCrossPerPlaneStats> PerPlane =
            new Dictionary<int, PlaneConstrainedZeroCrossPerPlaneStats>();
        public int OwnedVertices;
        public int MovedVertices;
        public int OverflowVertices;
        public float ResidualBeforeSum;
        public float ResidualAfterSum;

        public PlaneConstrainedZeroCrossPerPlaneStats GetPlane(int planeId)
        {
            if (!PerPlane.TryGetValue(planeId, out PlaneConstrainedZeroCrossPerPlaneStats stats))
            {
                stats = new PlaneConstrainedZeroCrossPerPlaneStats { PlaneId = planeId };
                PerPlane[planeId] = stats;
            }
            return stats;
        }
    }

