    private void Awake()
    {
        ApplyStage03ADisplayPreset();
        ApplyContinuityBaseFillPreset();
        ApplyOutputDisplayPipelinePreset();
        ResolveRefs();
        EnsureObjects();
        ApplyOutputDisplayLayerVisibility();
    }

    private void OnEnable()
    {
        ApplyStage03ADisplayPreset();
        ApplyContinuityBaseFillPreset();
        ApplyOutputDisplayPipelinePreset();
        ResolveRefs();
        EnsureObjects();
        ApplyOutputDisplayLayerVisibility();
    }

    private bool UseLegacyAuthTsdfDisplay =>
        outputDisplayPipeline == OutputDisplayPipeline.LegacyAuthTsdf;

    private string OutputDisplayLayerViewName
    {
        get
        {
            switch (outputDisplayLayerView)
            {
                case OutputDisplayLayerView.Diagnostic: return "DIAG";
                case OutputDisplayLayerView.Reference: return "REFERENCE";
                default: return "RESULT";
            }
        }
    }

    [ContextMenu("Cycle Output Display Layer View")]
    public void CycleOutputDisplayLayerView()
    {
        // Runtime presentation is intentionally two-class only. Red/magenta/orange/
        // gray remain in the exported ledgers instead of becoming a headset view.
        outputDisplayLayerView = OutputDisplayLayerView.Result;
        RefreshOutputDisplayLayerView();
    }

    private void HandleOutputDisplayLayerCycleInput()
    {
        if (!enableOutputDisplayLayerCycleInput)
            return;
        if (OVRInput.GetDown(outputDisplayLayerCycleButton, OVRInput.Controller.RTouch))
            CycleOutputDisplayLayerView();
    }

    private void RefreshOutputDisplayLayerView()
    {
        // Only the lightweight wire presentation is rebuilt from the already finalized
        // ledgers.  TSDF fusion, extraction, classification, audit and export are untouched.
        if (_lastOutputDisplayTriangleLedger != null && _lastOutputDisplayTriangleLedger.Count > 0)
        {
            RebuildPlaneConstrainedZeroCrossIssueOverlay(
                _lastOutputDisplayTriangleLedger, _lastOutputDisplaySupportCellLedger);
            RebuildPlaneConstrainedZeroCrossShadowWire(_lastOutputDisplayTriangleLedger);
        }
        ApplyOutputDisplayLayerVisibility();
        _nextHudRefresh = 0f;
    }

    private void ApplyOutputDisplayPipelinePreset()
    {
        // The three-gear presentation is always driven by the finalized current
        // ledger.  Keep the old enum value only so existing serialized scenes migrate
        // without losing the component; do not let it bypass the promotion gate.
        outputDisplayPipeline = OutputDisplayPipeline.CurrentDiagnosticComposite;
        outputDisplayLayerView = OutputDisplayLayerView.Result;
        enableOutputDisplayLayerCycleInput = false;
        showAuthoritativeCyanOnly = false;
        enablePlaneConstrainedZeroCrossShadow = true;
        showPlaneConstrainedZeroCrossShadowWire = true;
        showPlaneReferenceAndZeroCrossShadowOnly = true;
        planeConstrainedNonplanarWireColor = new Color(0.08f, 0.92f, 0.24f, 0.96f);
        enableStablePlaneShadowTrial = true;
        showStablePlaneShadowWire = false;
        showPlaneConstrainedZeroCrossIssueOverlay = false;
        showPlaneConstrainedHeldOverlay = false;
    }

    private void ApplyOutputDisplayLayerVisibility()
    {
        bool showPlane = outputDisplayLayerView == OutputDisplayLayerView.Reference;
        bool showShadow = outputDisplayLayerView == OutputDisplayLayerView.Result ||
                          outputDisplayLayerView == OutputDisplayLayerView.Diagnostic;
        bool showIssues = outputDisplayLayerView == OutputDisplayLayerView.Diagnostic;

        if (_stablePlaneShadowObject != null)
        {
            bool hasPlaneMesh = _stablePlaneShadowMesh != null && _stablePlaneShadowMesh.vertexCount > 0;
            _stablePlaneShadowObject.SetActive(showStablePlaneShadowWire && showPlane && hasPlaneMesh);
        }

        if (_planeConstrainedZeroCrossShadowRenderer != null)
        {
            _planeConstrainedZeroCrossShadowRenderer.sharedMaterials = new[]
            {
                _planeConstrainedZeroCrossShadowMaterial,
                _planeConstrainedZeroCrossNonplanarMaterial,
                _planeConstrainedZeroCrossProvisionalMaterial,
                _planeConstrainedZeroCrossUnclassifiedMaterial
            };
        }
        bool usePersistentChunks =
            ShouldUsePersistentResultChunkPublishing() &&
            _persistentResultChunks.Count > 0;
        if (!usePersistentChunks)
            ApplyOutputDisplayShadowSubmeshFilter();
        if (_planeConstrainedZeroCrossShadowObject != null)
        {
            bool hasShadowMesh = HasVisibleOutputDisplayShadowLines();
            _planeConstrainedZeroCrossShadowObject.SetActive(
                !usePersistentChunks &&
                showPlaneConstrainedZeroCrossShadowWire && showShadow && hasShadowMesh);
        }
        if (usePersistentChunks)
            ApplyPersistentResultChunkVisibility();
        else if (_persistentResultChunkRoot != null)
            _persistentResultChunkRoot.SetActive(false);

        if (_planeConstrainedZeroCrossIssueRenderer != null)
        {
            _planeConstrainedZeroCrossIssueRenderer.sharedMaterials = new[]
            {
                _planeConstrainedZeroCrossIssueMaterials[0],
                _planeConstrainedZeroCrossIssueMaterials[1],
                _planeConstrainedZeroCrossIssueMaterials[2],
                _planeConstrainedZeroCrossIssueMaterials[3]
            };
        }
        ApplyOutputDisplayIssueSubmeshFilter();
        if (_planeConstrainedZeroCrossIssueObject != null)
        {
            bool hasIssueMesh = HasVisibleOutputDisplayIssueLines();
            _planeConstrainedZeroCrossIssueObject.SetActive(
                showPlaneConstrainedZeroCrossIssueOverlay && showIssues && hasIssueMesh);
        }
    }

    private static void ReplaceOutputDisplayLineIndices(List<int> destination, List<int> source)
    {
        destination.Clear();
        if (source != null && source.Count > 0)
            destination.AddRange(source);
    }

    private void ApplyOutputDisplayShadowSubmeshFilter()
    {
        if (_planeConstrainedZeroCrossShadowMesh == null ||
            _planeConstrainedZeroCrossShadowMesh.subMeshCount < 4)
            return;

        bool showResult = outputDisplayLayerView == OutputDisplayLayerView.Result;
        bool showDiagnostic = outputDisplayLayerView == OutputDisplayLayerView.Diagnostic;
        _planeConstrainedZeroCrossShadowMesh.SetIndices(
            showResult ? _outputDisplayStructuralLines : EmptyOutputDisplayLineIndices,
            MeshTopology.Lines, 0, false);
        _planeConstrainedZeroCrossShadowMesh.SetIndices(
            showResult ? _outputDisplayComplexLines : EmptyOutputDisplayLineIndices,
            MeshTopology.Lines, 1, false);
        _planeConstrainedZeroCrossShadowMesh.SetIndices(
            EmptyOutputDisplayLineIndices,
            MeshTopology.Lines, 2, false);
        _planeConstrainedZeroCrossShadowMesh.SetIndices(
            showDiagnostic ? _outputDisplayUnclassifiedLines : EmptyOutputDisplayLineIndices,
            MeshTopology.Lines, 3, false);
    }

    private bool HasVisibleOutputDisplayShadowLines()
    {
        if (ShouldUsePersistentResultChunkPublishing() &&
            _persistentResultChunks.Count > 0)
        {
            if (outputDisplayLayerView == OutputDisplayLayerView.Result)
                return LastOutputResultPromotedTriangleCount > 0;
            if (outputDisplayLayerView == OutputDisplayLayerView.Diagnostic)
                return LastOutputDiagnosticUnclassifiedTriangleCount > 0 ||
                       LastOutputDiagnosticPromotionBlockedTriangleCount > 0;
            return false;
        }
        if (outputDisplayLayerView == OutputDisplayLayerView.Result)
            return _outputDisplayStructuralLines.Count > 0 ||
                   _outputDisplayComplexLines.Count > 0;
        if (outputDisplayLayerView == OutputDisplayLayerView.Diagnostic)
            return _outputDisplayUnclassifiedLines.Count > 0;
        return false;
    }

    private void ApplyOutputDisplayIssueSubmeshFilter()
    {
        if (_planeConstrainedZeroCrossIssueMesh == null ||
            _planeConstrainedZeroCrossIssueMesh.subMeshCount < 4)
            return;

        bool showDiagnostic = outputDisplayLayerView == OutputDisplayLayerView.Diagnostic;
        bool showHeld = showDiagnostic;
        bool showHeldBounds = showHeld && showPlaneConstrainedHeldBoundsOverlay;
        bool showHardIllegal = showDiagnostic;
        bool showSupportGap = showDiagnostic;
        _planeConstrainedZeroCrossIssueMesh.SetIndices(
            showHeld ? _outputDisplayPendingIssueLines : EmptyOutputDisplayLineIndices,
            MeshTopology.Lines, 0, false);
        _planeConstrainedZeroCrossIssueMesh.SetIndices(
            showHeldBounds ? _outputDisplayBoundsIssueLines : EmptyOutputDisplayLineIndices,
            MeshTopology.Lines, 1, false);
        _planeConstrainedZeroCrossIssueMesh.SetIndices(
            showHardIllegal ? _outputDisplayHardAuditLines : EmptyOutputDisplayLineIndices,
            MeshTopology.Lines, 2, false);
        _planeConstrainedZeroCrossIssueMesh.SetIndices(
            showSupportGap ? _outputDisplaySupportGapLines : EmptyOutputDisplayLineIndices,
            MeshTopology.Lines, 3, false);
    }

    private bool HasVisibleOutputDisplayIssueLines()
    {
        if (outputDisplayLayerView == OutputDisplayLayerView.Diagnostic)
            return _outputDisplayPendingIssueLines.Count > 0 ||
                   (showPlaneConstrainedHeldBoundsOverlay &&
                    _outputDisplayBoundsIssueLines.Count > 0) ||
                   _outputDisplayHardAuditLines.Count > 0 ||
                   _outputDisplaySupportGapLines.Count > 0;
        return false;
    }

    private void ApplyStage03ADisplayPreset()
    {
        if (!forceMeshGridDisplayOnEnable && !useStage03ACleanIsoSurface)
            return;

        showRawDepthDebugView = false;
        showRawCoverageGridOverlay = false;
        showReferenceClassicBoundaryDiagnostics = false;
        showAcceptedReferenceClassicCompletionMesh = false;
        showReferenceVolumetricShadowMesh = false;
        hideMeshWhenRawCoverageGridOverlay = false;
        showExtractedSurfaceMesh = true;
        showPlanarCoverSurfaceFill = true;
        showMeshEdgeWireOverlay = true;
        showFallbackSurfaceSamples = false;
        showLayerDiagnosticPointOverlay = false;
        repairPersistentDoublePlaneCreases = false;
        if (useStage03ACleanIsoSurface)
        {
            DisableDiagnosticDiskWrites();
            useAtomicObservationTsdfBands = true;
            useV08DirectBandWriteForDiagnosis = false;
            useV09ExactCornerEligibilityForDiagnosis = false;
            useLegacyTsdfMeshDisplay = useV09LegacyExtractorForStage03A;
            suppressExtractionNearPendingTsdfCorrection = false;
            suppressExtractionNearDirtyTsdfQuarantine = false;
            suppressQuadOnPendingTsdfCorrectionEdge = false;
            suppressQuadOnDirtyTsdfQuarantineEdge = false;
            requireMainShellPromotionGate = false;
            bridgeCleanCoplanarBoundaryEdges = false;
            pruneSmallExtractedMeshComponents = false;
            pruneDanglingExtractedMeshTriangles = false;
            pruneSpikePatchTriangles = false;
            showMeshTumorSuspectOverlay = false;
            retainRecoveredPendingCommittedFaces = true;
            recoveredPendingFaceRetentionNeighborCells = 1;
            maxRecoveredPendingRetainedTriangles = Mathf.Max(4000, maxRecoveredPendingRetainedTriangles);
            minRecoveredPendingObservedCorners = 6;
            recoveredPendingVertexWeldToleranceVoxelScale = 0.08f;
            enableStableIncrementalQuadShadow = true;
            stableQuadShadowPromoteRebuilds = 2;
            stableQuadShadowRetainMissingRebuilds = 2;
        }
    }

    private void DisableDiagnosticDiskWrites()
    {
        writeConfidenceAuditOnCapture = false;
        if (_contributionLedgerWriter != null)
        {
            _contributionLedgerWriter.Dispose();
            _contributionLedgerWriter = null;
        }
        _confidenceAuditRows = null;
        _confidenceAuditFrameRows = null;
        _doubleLayerPairRows = null;
    }

    private void ApplyContinuityBaseFillPreset()
    {
        if (!fillCleanTsdfContinuityGaps)
            return;

        tsdfContinuityFillRadiusVoxels = Mathf.Max(tsdfContinuityFillRadiusVoxels, 2);
        minTsdfContinuityFaceNeighborVoxels = Mathf.Max(minTsdfContinuityFaceNeighborVoxels, 2);
        minTsdfContinuitySameSignNeighborVoxels = Mathf.Min(minTsdfContinuitySameSignNeighborVoxels, 10);
        maxTsdfContinuityNeighborAbsValue = Mathf.Max(maxTsdfContinuityNeighborAbsValue, 0.24f);
        maxTsdfContinuityFillVoxelsPerRebuild = Mathf.Max(maxTsdfContinuityFillVoxelsPerRebuild, 4096);
        allowSameSignContinuityBaseFill = true;
        allowStableProvisionalContinuitySources = true;
        fillBoundaryNoTsdfGaps = true;
        minBoundaryNoTsdfNeighborVoxels = Mathf.Min(minBoundaryNoTsdfNeighborVoxels, 8);
        minBoundaryNoTsdfFaceNeighborVoxels = Mathf.Max(minBoundaryNoTsdfFaceNeighborVoxels, 3);
        allowBoundaryNoTsdfProvisionalAnchor = true;
        minBoundaryNoTsdfCleanFaceAnchors = Mathf.Clamp(minBoundaryNoTsdfCleanFaceAnchors, 0, 6);
        minBoundaryNoTsdfProvisionalAnchors = Mathf.Clamp(minBoundaryNoTsdfProvisionalAnchors, 2, 12);
        minBoundaryNoTsdfProvisionalFaceAnchors = Mathf.Clamp(minBoundaryNoTsdfProvisionalFaceAnchors, 1, 6);
        maxBoundaryNoTsdfFillVoxelsPerRebuild = Mathf.Max(maxBoundaryNoTsdfFillVoxelsPerRebuild, 1024);
    }

    private void OnDisable()
    {
        if (_confidenceAuditRows != null)
            EndConfidenceAuditCapture(_confidenceAuditIntegratedFrames, "component disabled");
        _captureRoutine = null;
        _activeCaptureBatchTargetFrames = 0;
        _activeCaptureBatchIntegratedFrames = 0;
        _activeCaptureBatchUniqueRawFrames = 0;
        _activeCaptureBatchTimeouts = 0;
    }

