    private bool ShouldKeepDisplayedMesh(int previousTriangleCount, List<Vector3> candidateVertices, int newTriangleCount)
    {
        if (previousTriangleCount <= 0)
            return false;
        int newVertexCount = candidateVertices != null ? candidateVertices.Count : 0;
        if (newVertexCount <= 0 || newTriangleCount <= 0)
            return true;

        if (guardCommittedMeshSpatialCoverage)
        {
            EnsureCommittedMeshBlocksFromDisplayedMesh();
            BuildMeshBlockSet(candidateVertices, _candidateMeshBlocks);
            LastCommittedMeshBlockCount = _committedMeshBlocks.Count;
            LastCandidateMeshBlockCount = _candidateMeshBlocks.Count;
            LastRetainedCommittedMeshBlockCount = CountRetainedCommittedMeshBlocks();
            if (_committedMeshBlocks.Count > 0)
            {
                float retainedRatio = (float)LastRetainedCommittedMeshBlockCount / _committedMeshBlocks.Count;
                int newBlockCount = Mathf.Max(0, _candidateMeshBlocks.Count - LastRetainedCommittedMeshBlockCount);
                bool extendsObservedArea = newBlockCount >= Mathf.Max(4, _committedMeshBlocks.Count / 50);
                float requiredBlockRetention = useStrictCommittedMeshRetention
                    ? Mathf.Min(0.92f, Mathf.Clamp01(minCommittedMeshBlockRetention))
                    : Mathf.Clamp01(minCommittedMeshBlockRetention);
                float growthRetentionFloor = Mathf.Min(requiredBlockRetention, 0.82f);
                if (retainedRatio < requiredBlockRetention &&
                    (!extendsObservedArea || retainedRatio < growthRetentionFloor))
                {
                    LastCommittedMeshHoldSpatialCount++;
                    return true;
                }
            }
        }

        if (useStrictCommittedMeshRetention &&
            newTriangleCount < previousTriangleCount * Mathf.Min(0.92f, Mathf.Clamp(minCommittedMeshTriangleRetention, 0.8f, 1f)))
        {
            LastCommittedMeshHoldTriangleCount++;
            return true;
        }

        if (protectDisplayedMeshFromBadRebuild)
        {
            float minRatio = Mathf.Clamp(minAcceptedRebuildTriangleRatio, 0.1f, 1f);
            if (newTriangleCount < previousTriangleCount * minRatio)
                return true;

            int candidateTriangleBudget = newTriangleCount + LastPrunedMeshTriangleCount;
            if (candidateTriangleBudget > 0)
            {
                float prunedRatio = (float)LastPrunedMeshTriangleCount / candidateTriangleBudget;
                if (prunedRatio > Mathf.Clamp01(maxAcceptedPrunedTriangleRatio) &&
                    newTriangleCount < previousTriangleCount)
                {
                    return true;
                }
            }
        }

        return false;
    }

    private void EnsureCommittedMeshBlocksFromDisplayedMesh()
    {
        if (_committedMeshBlocks.Count > 0 || _mesh == null || _mesh.vertexCount <= 0)
            return;
        BuildMeshBlockSet(_mesh.vertices, _committedMeshBlocks);
    }

    private void CommitDisplayedMeshBlocks(IList<Vector3> vertices)
    {
        BuildMeshBlockSet(vertices, _committedMeshBlocks);
        LastCommittedMeshBlockCount = _committedMeshBlocks.Count;
        LastCandidateMeshBlockCount = _committedMeshBlocks.Count;
        LastRetainedCommittedMeshBlockCount = _committedMeshBlocks.Count;
    }

    private void BuildMeshBlockSet(IList<Vector3> vertices, HashSet<Vector3Int> destination)
    {
        destination.Clear();
        if (vertices == null)
            return;
        int blockVoxels = useStrictCommittedMeshRetention
            ? Mathf.Min(2, Mathf.Clamp(committedMeshBlockSizeVoxels, 1, 8))
            : Mathf.Clamp(committedMeshBlockSizeVoxels, 1, 8);
        float blockSize = Mathf.Max(0.001f, voxelSizeMeters * blockVoxels);
        for (int i = 0; i < vertices.Count; i++)
        {
            Vector3 local = (vertices[i] - _volumeOriginWorld) / blockSize;
            destination.Add(new Vector3Int(
                Mathf.FloorToInt(local.x),
                Mathf.FloorToInt(local.y),
                Mathf.FloorToInt(local.z)));
        }
    }

    private int CountRetainedCommittedMeshBlocks()
    {
        int retained = 0;
        foreach (Vector3Int block in _committedMeshBlocks)
        {
            if (_candidateMeshBlocks.Contains(block))
                retained++;
        }
        return retained;
    }

    private void RetainRecoveredPendingFaces(
        List<Vector3> candidateVertices,
        List<int> candidateTriangles,
        List<Color> candidateColors)
    {
        LastRecoveredPendingRetentionCellCount = 0;
        LastRecoveredPendingRetainedTriangleCount = 0;
        LastRecoveredPendingDuplicateTriangleCount = 0;
        LastRecoveredPendingRetentionBudgetCount = 0;
        LastRecoveredPendingWeldedVertexCount = 0;
        LastRecoveredPendingAddedVertexCount = 0;
        LastRecoveredPendingDegenerateTriangleCount = 0;
        LastRecoveredPendingBoundaryEdgesBefore = 0;
        LastRecoveredPendingBoundaryEdgesAfter = 0;
        LastRecoveredPendingNonManifoldEdgesBefore = 0;
        LastRecoveredPendingNonManifoldEdgesAfter = 0;
        LastRecoveredPendingSixCornerCellCount = 0;
        LastRecoveredPendingSevenCornerCellCount = 0;
        LastRecoveredPendingEightCornerCellCount = 0;
        LastRecoveredPendingTopologyBlockedTriangleCount = 0;
        if (!retainRecoveredPendingCommittedFaces ||
            _mesh == null || _mesh.vertexCount <= 0 || _mesh.triangles == null || _mesh.triangles.Length < 3 ||
            _holeCellLifecycles.Count <= 0)
        {
            return;
        }

        HashSet<Vector3Int> protectedCells = new HashSet<Vector3Int>();
        foreach (KeyValuePair<Vector3Int, HoleCellLifecycle> entry in _holeCellLifecycles)
        {
            HoleCellLifecycle lifecycle = entry.Value;
            if (!lifecycle.Active || lifecycle.RecoveryCount <= 0 || lifecycle.LastCause != HoleSupportCause.Pending)
                continue;
            if (!CellHasSafeRawZeroCrossForRetention(entry.Key.x, entry.Key.y, entry.Key.z, out int supportedCorners))
                continue;
            protectedCells.Add(entry.Key);
            if (supportedCorners == 6)
                LastRecoveredPendingSixCornerCellCount++;
            else if (supportedCorners == 7)
                LastRecoveredPendingSevenCornerCellCount++;
            else if (supportedCorners >= 8)
                LastRecoveredPendingEightCornerCellCount++;
        }
        LastRecoveredPendingRetentionCellCount = protectedCells.Count;
        if (protectedCells.Count <= 0)
            return;

        CountMeshEdgeTopology(
            candidateTriangles,
            out int boundaryEdgesBefore,
            out int nonManifoldEdgesBefore);
        LastRecoveredPendingBoundaryEdgesBefore = boundaryEdgesBefore;
        LastRecoveredPendingNonManifoldEdgesBefore = nonManifoldEdgesBefore;
        Dictionary<ulong, int> retainedEdgeUse = BuildMeshEdgeUseCounts(candidateTriangles);
        HashSet<Vector3Int> retainedTriangleKeys = BuildOrientedTriangleKeys(candidateTriangles);

        HashSet<Vector3Int> candidateTriangleCells = new HashSet<Vector3Int>();
        for (int i = 0; i + 2 < candidateTriangles.Count; i += 3)
        {
            int ia = candidateTriangles[i];
            int ib = candidateTriangles[i + 1];
            int ic = candidateTriangles[i + 2];
            if (!TriangleIndicesAreValid(ia, ib, ic, candidateVertices.Count))
                continue;
            Vector3 centroid = (candidateVertices[ia] + candidateVertices[ib] + candidateVertices[ic]) / 3f;
            if (TryWorldPointToSurfaceCell(centroid, out Vector3Int cell))
                candidateTriangleCells.Add(cell);
        }

        Vector3[] oldVertices = _mesh.vertices;
        int[] oldTriangles = _mesh.triangles;
        Color[] oldColors = _mesh.colors;
        int triangleBudget = Mathf.Max(64, maxRecoveredPendingRetainedTriangles);
        int neighborRadius = Mathf.Clamp(recoveredPendingFaceRetentionNeighborCells, 0, 2);
        float weldTolerance = Mathf.Max(0.00001f,
            voxelSizeMeters * Mathf.Clamp(recoveredPendingVertexWeldToleranceVoxelScale, 0.005f, 0.25f));
        Dictionary<Vector3Int, List<int>> weldBins = BuildVertexWeldBins(candidateVertices, weldTolerance);
        Dictionary<int, int> oldVertexRemap = new Dictionary<int, int>();
        for (int i = 0; i + 2 < oldTriangles.Length; i += 3)
        {
            int ia = oldTriangles[i];
            int ib = oldTriangles[i + 1];
            int ic = oldTriangles[i + 2];
            if (!TriangleIndicesAreValid(ia, ib, ic, oldVertices.Length))
                continue;
            Vector3 centroid = (oldVertices[ia] + oldVertices[ib] + oldVertices[ic]) / 3f;
            if (!TryWorldPointToSurfaceCell(centroid, out Vector3Int cell) ||
                !CellOrNeighborIsProtected(cell, protectedCells, neighborRadius))
            {
                continue;
            }
            if (candidateTriangleCells.Contains(cell))
            {
                LastRecoveredPendingDuplicateTriangleCount++;
                continue;
            }
            if (LastRecoveredPendingRetainedTriangleCount >= triangleBudget)
            {
                LastRecoveredPendingRetentionBudgetCount++;
                continue;
            }

            int ra = FindOrAddRetainedWeldedVertex(ia, oldVertices, oldColors, candidateVertices, candidateColors, oldVertexRemap, weldBins, weldTolerance);
            int rb = FindOrAddRetainedWeldedVertex(ib, oldVertices, oldColors, candidateVertices, candidateColors, oldVertexRemap, weldBins, weldTolerance);
            int rc = FindOrAddRetainedWeldedVertex(ic, oldVertices, oldColors, candidateVertices, candidateColors, oldVertexRemap, weldBins, weldTolerance);
            if (ra < 0 || rb < 0 || rc < 0)
            {
                LastRecoveredPendingRetentionBudgetCount++;
                continue;
            }
            if (ra == rb || rb == rc || rc == ra ||
                Vector3.Cross(candidateVertices[rb] - candidateVertices[ra], candidateVertices[rc] - candidateVertices[ra]).sqrMagnitude <= 0.0000000001f)
            {
                LastRecoveredPendingDegenerateTriangleCount++;
                continue;
            }
            Vector3Int triangleKey = OrientedTriangleKey(ra, rb, rc);
            if (retainedTriangleKeys.Contains(triangleKey))
            {
                LastRecoveredPendingDuplicateTriangleCount++;
                continue;
            }
            int manifoldUseLimit = doubleSidedTriangles ? 4 : 2;
            if (GetEdgeUseCount(retainedEdgeUse, ra, rb) >= manifoldUseLimit ||
                GetEdgeUseCount(retainedEdgeUse, rb, rc) >= manifoldUseLimit ||
                GetEdgeUseCount(retainedEdgeUse, rc, ra) >= manifoldUseLimit)
            {
                LastRecoveredPendingTopologyBlockedTriangleCount++;
                continue;
            }
            candidateTriangles.Add(ra);
            candidateTriangles.Add(rb);
            candidateTriangles.Add(rc);
            retainedTriangleKeys.Add(triangleKey);
            AddEdgeUse(retainedEdgeUse, ra, rb);
            AddEdgeUse(retainedEdgeUse, rb, rc);
            AddEdgeUse(retainedEdgeUse, rc, ra);
            LastRecoveredPendingRetainedTriangleCount++;
        }

        CountMeshEdgeTopology(
            candidateTriangles,
            out int boundaryEdgesAfter,
            out int nonManifoldEdgesAfter);
        LastRecoveredPendingBoundaryEdgesAfter = boundaryEdgesAfter;
        LastRecoveredPendingNonManifoldEdgesAfter = nonManifoldEdgesAfter;
    }

    private bool CellHasSafeRawZeroCrossForRetention(
        int cellX,
        int cellY,
        int cellZ,
        out int supportedCorners)
    {
        supportedCorners = 0;
        if (_tsdf == null || _weights == null ||
            cellX < 0 || cellY < 0 || cellZ < 0 ||
            cellX >= _dimX - 1 || cellY >= _dimY - 1 || cellZ >= _dimZ - 1)
        {
            return false;
        }
        bool positive = false;
        bool negative = false;
        for (int corner = 0; corner < 8; corner++)
        {
            int index = Index(
                cellX + CornerOffsetX[corner],
                cellY + CornerOffsetY[corner],
                cellZ + CornerOffsetZ[corner]);
            float value = _tsdf[index];
            if (float.IsNaN(value) || float.IsInfinity(value) || VoxelIsDirtyQuarantined(index))
                return false;
            if (_weights[index] < minSurfaceCornerWeight)
                continue;
            supportedCorners++;
            positive |= value > 0f;
            negative |= value < 0f;
        }
        return supportedCorners >= Mathf.Clamp(minRecoveredPendingObservedCorners, 4, 8) && positive && negative;
    }

    private Dictionary<Vector3Int, List<int>> BuildVertexWeldBins(List<Vector3> vertices, float tolerance)
    {
        Dictionary<Vector3Int, List<int>> bins = new Dictionary<Vector3Int, List<int>>(vertices.Count);
        for (int i = 0; i < vertices.Count; i++)
            AddVertexToWeldBin(bins, VertexWeldBin(vertices[i], tolerance), i);
        return bins;
    }

    private int FindOrAddRetainedWeldedVertex(
        int oldIndex,
        Vector3[] oldVertices,
        Color[] oldColors,
        List<Vector3> vertices,
        List<Color> colors,
        Dictionary<int, int> oldVertexRemap,
        Dictionary<Vector3Int, List<int>> weldBins,
        float tolerance)
    {
        if (oldVertexRemap.TryGetValue(oldIndex, out int remapped))
            return remapped;

        Vector3 point = oldVertices[oldIndex];
        Vector3Int centerBin = VertexWeldBin(point, tolerance);
        float maxDistanceSq = tolerance * tolerance;
        float bestDistanceSq = maxDistanceSq;
        int best = -1;
        for (int dz = -1; dz <= 1; dz++)
        for (int dy = -1; dy <= 1; dy++)
        for (int dx = -1; dx <= 1; dx++)
        {
            Vector3Int key = new Vector3Int(centerBin.x + dx, centerBin.y + dy, centerBin.z + dz);
            if (!weldBins.TryGetValue(key, out List<int> candidates))
                continue;
            for (int i = 0; i < candidates.Count; i++)
            {
                int candidate = candidates[i];
                float distanceSq = (vertices[candidate] - point).sqrMagnitude;
                if (distanceSq <= bestDistanceSq)
                {
                    bestDistanceSq = distanceSq;
                    best = candidate;
                }
            }
        }

        if (best >= 0)
        {
            oldVertexRemap[oldIndex] = best;
            LastRecoveredPendingWeldedVertexCount++;
            return best;
        }
        if (vertices.Count >= maxSurfaceVertices)
            return -1;

        int added = vertices.Count;
        vertices.Add(point);
        colors.Add(oldColors != null && oldColors.Length == oldVertices.Length
            ? oldColors[oldIndex]
            : cleanCoverCellColor);
        oldVertexRemap[oldIndex] = added;
        AddVertexToWeldBin(weldBins, centerBin, added);
        LastRecoveredPendingAddedVertexCount++;
        return added;
    }

    private static Vector3Int VertexWeldBin(Vector3 point, float tolerance)
    {
        float inverse = 1f / Mathf.Max(0.00001f, tolerance);
        return new Vector3Int(
            Mathf.FloorToInt(point.x * inverse),
            Mathf.FloorToInt(point.y * inverse),
            Mathf.FloorToInt(point.z * inverse));
    }

    private static void AddVertexToWeldBin(Dictionary<Vector3Int, List<int>> bins, Vector3Int key, int vertexIndex)
    {
        if (!bins.TryGetValue(key, out List<int> indices))
        {
            indices = new List<int>(2);
            bins[key] = indices;
        }
        indices.Add(vertexIndex);
    }

    private void ApplyFeaturePreservingMeshOptimization(
        List<Vector3> vertices,
        List<int> triangles,
        List<Color> colors)
    {
        if (!LastMeshUsedExtractedTsdf ||
            vertices == null || triangles == null || vertices.Count < 4 || triangles.Count < 6)
        {
            return;
        }

        if (enableQuestStyleDisplayRemesh)
        {
            ScanCoverQuestStyleMeshRemesher.Settings remeshSettings =
                new ScanCoverQuestStyleMeshRemesher.Settings
                {
                    TargetEdgeLengthMeters = voxelSizeMeters * questRemeshTargetEdgeVoxelScale,
                    CollapseBelowTargetScale = questRemeshCollapseBelowTargetScale,
                    MinPlanarNormalDot = meshOptimizationMinPlanarNormalDot,
                    FeatureAngleDegrees = meshOptimizationFeatureAngleDegrees,
                    MaxCollapseFraction = questRemeshMaxCollapseFraction,
                    MaxEdgeCollapses = questRemeshMaxEdgeCollapses,
                    MaxEdgeFlips = questRemeshMaxEdgeFlips,
                    MinFlipQualityGain = questRemeshMinFlipQualityGain,
                    MaxFlipEdgeTargetScale = questRemeshMaxFlipEdgeTargetScale,
                    MaxCollapseProjectionMeters = voxelSizeMeters * questRemeshMaxProjectionVoxelScale,
                    MinTriangleAreaMetersSquared = voxelSizeMeters * voxelSizeMeters * questRemeshMinTriangleAreaVoxelSquared,
                    MaxMeanQualityLoss = questRemeshMaxMeanQualityLoss
                };
            ScanCoverQuestStyleMeshRemesher.Remesh(
                vertices,
                triangles,
                colors,
                doubleSidedTriangles,
                remeshSettings,
                out ScanCoverQuestStyleMeshRemesher.Result remesh);
            LastQuestRemeshAppliedCount = remesh.Applied ? 1 : 0;
            LastQuestRemeshAtomicRollbackCount = remesh.AtomicRollback ? 1 : 0;
            LastQuestRemeshUniqueTrianglesBefore = remesh.UniqueTrianglesBefore;
            LastQuestRemeshUniqueTrianglesAfter = remesh.UniqueTrianglesAfter;
            LastQuestRemeshRenderTrianglesBefore = remesh.RenderTrianglesBefore;
            LastQuestRemeshRenderTrianglesAfter = remesh.RenderTrianglesAfter;
            LastQuestRemeshCandidateCollapseEdges = remesh.CandidateCollapseEdges;
            LastQuestRemeshCollapsedEdges = remesh.CollapsedEdges;
            LastQuestRemeshRejectedCollapseEligibility = remesh.RejectedCollapseEligibility;
            LastQuestRemeshRejectedCollapseGeometry = remesh.RejectedCollapseGeometry;
            LastQuestRemeshRejectedCollapseTopology = remesh.RejectedCollapseTopology;
            LastQuestRemeshRejectedCollapseQuality = remesh.RejectedCollapseQuality;
            LastQuestRemeshDegenerateTrianglesRemoved = remesh.DegenerateTrianglesRemoved;
            LastQuestRemeshDuplicateTrianglesRemoved = remesh.DuplicateTrianglesRemoved;
            LastQuestRemeshCandidateFlipEdges = remesh.CandidateFlipEdges;
            LastQuestRemeshFlippedEdges = remesh.FlippedEdges;
            LastQuestRemeshBoundaryEdgesBefore = remesh.BoundaryEdgesBefore;
            LastQuestRemeshBoundaryEdgesAfter = remesh.BoundaryEdgesAfter;
            LastQuestRemeshNonManifoldEdgesAfter = remesh.NonManifoldEdgesAfter;
            LastQuestRemeshProtectedBoundaryVertices = remesh.ProtectedBoundaryVertices;
            LastQuestRemeshProtectedCreaseVertices = remesh.ProtectedCreaseVertices;
            LastQuestRemeshMeanQualityBefore = remesh.MeanQualityBefore;
            LastQuestRemeshMeanQualityAfter = remesh.MeanQualityAfter;
            LastQuestRemeshMeanEdgeBeforeMeters = remesh.MeanEdgeLengthBeforeMeters;
            LastQuestRemeshMeanEdgeAfterMeters = remesh.MeanEdgeLengthAfterMeters;
        }

        if (!enableFeaturePreservingMeshOptimization)
            return;

        ScanCoverFeaturePreservingMeshOptimizer.Settings settings =
            new ScanCoverFeaturePreservingMeshOptimizer.Settings
            {
                Iterations = meshOptimizationIterations,
                MinPlanarNormalDot = meshOptimizationMinPlanarNormalDot,
                FeatureAngleDegrees = meshOptimizationFeatureAngleDegrees,
                TangentialRelaxation = meshOptimizationTangentialRelaxation,
                PlaneProjectionStrength = meshOptimizationPlaneProjectionStrength,
                MaxVertexMoveMeters = Mathf.Max(0.0001f, voxelSizeMeters * meshOptimizationMaxMoveVoxelScale),
                MinTriangleAreaRatio = meshOptimizationMinTriangleAreaRatio,
                MinTriangleNormalDot = meshOptimizationMinTriangleNormalDot,
                MaxMeanTriangleQualityLoss = meshOptimizationMaxMeanQualityLoss
            };

        ScanCoverFeaturePreservingMeshOptimizer.Optimize(
            vertices,
            triangles,
            settings,
            out ScanCoverFeaturePreservingMeshOptimizer.Result optimization);
        LastMeshOptimizationAppliedCount = optimization.Applied ? 1 : 0;
        LastMeshOptimizationAtomicRollbackCount = optimization.AtomicRollback ? 1 : 0;
        LastMeshOptimizationUniqueTriangleCount = optimization.UniqueTriangleCount;
        LastMeshOptimizationBoundaryVertexCount = optimization.BoundaryVertexCount;
        LastMeshOptimizationCreaseVertexCount = optimization.CreaseVertexCount;
        LastMeshOptimizationEligibleVertexCount = optimization.EligibleVertexCount;
        LastMeshOptimizationMovedVertexCount = optimization.MovedVertexCount;
        LastMeshOptimizationRevertedVertexCount = optimization.RevertedVertexCount;
        LastMeshOptimizationMeanQualityBefore = optimization.MeanTriangleQualityBefore;
        LastMeshOptimizationMeanQualityAfter = optimization.MeanTriangleQualityAfter;
        LastMeshOptimizationPlaneResidualBeforeMeters = optimization.MeanPlaneResidualBeforeMeters;
        LastMeshOptimizationPlaneResidualAfterMeters = optimization.MeanPlaneResidualAfterMeters;
        LastMeshOptimizationRmsDisplacementMeters = optimization.RmsDisplacementMeters;
        LastMeshOptimizationMaxDisplacementMeters = optimization.MaxDisplacementMeters;
    }

    private void CountMeshEdgeTopology(List<int> triangles, out int boundaryEdges, out int nonManifoldEdges)
    {
        Dictionary<ulong, int> edgeUse = BuildMeshEdgeUseCounts(triangles);
        boundaryEdges = 0;
        nonManifoldEdges = 0;
        int boundaryUseLimit = doubleSidedTriangles ? 2 : 1;
        int manifoldUseLimit = doubleSidedTriangles ? 4 : 2;
        foreach (int count in edgeUse.Values)
        {
            if (count <= boundaryUseLimit)
                boundaryEdges++;
            else if (count > manifoldUseLimit)
                nonManifoldEdges++;
        }
    }

    private static Dictionary<ulong, int> BuildMeshEdgeUseCounts(List<int> triangles)
    {
        Dictionary<ulong, int> edgeUse = new Dictionary<ulong, int>(triangles.Count);
        for (int i = 0; i + 2 < triangles.Count; i += 3)
        {
            int a = triangles[i];
            int b = triangles[i + 1];
            int c = triangles[i + 2];
            if (a == b || b == c || c == a)
                continue;
            AddEdgeUse(edgeUse, a, b);
            AddEdgeUse(edgeUse, b, c);
            AddEdgeUse(edgeUse, c, a);
        }
        return edgeUse;
    }

    private static HashSet<Vector3Int> BuildOrientedTriangleKeys(List<int> triangles)
    {
        HashSet<Vector3Int> keys = new HashSet<Vector3Int>();
        for (int i = 0; i + 2 < triangles.Count; i += 3)
        {
            int a = triangles[i];
            int b = triangles[i + 1];
            int c = triangles[i + 2];
            if (a != b && b != c && c != a)
                keys.Add(OrientedTriangleKey(a, b, c));
        }
        return keys;
    }

    private static Vector3Int OrientedTriangleKey(int a, int b, int c)
    {
        if (a <= b && a <= c)
            return new Vector3Int(a, b, c);
        if (b <= a && b <= c)
            return new Vector3Int(b, c, a);
        return new Vector3Int(c, a, b);
    }

    private bool TryWorldPointToSurfaceCell(Vector3 point, out Vector3Int cell)
    {
        float voxel = Mathf.Max(0.0001f, voxelSizeMeters);
        Vector3 local = (point - _volumeOriginWorld) / voxel - Vector3.one * 0.5f;
        cell = new Vector3Int(
            Mathf.FloorToInt(local.x),
            Mathf.FloorToInt(local.y),
            Mathf.FloorToInt(local.z));
        return cell.x >= 0 && cell.y >= 0 && cell.z >= 0 &&
               cell.x < _dimX - 1 && cell.y < _dimY - 1 && cell.z < _dimZ - 1;
    }

    private static bool CellOrNeighborIsProtected(
        Vector3Int cell,
        HashSet<Vector3Int> protectedCells,
        int radius)
    {
        for (int dz = -radius; dz <= radius; dz++)
        for (int dy = -radius; dy <= radius; dy++)
        for (int dx = -radius; dx <= radius; dx++)
        {
            if (protectedCells.Contains(new Vector3Int(cell.x + dx, cell.y + dy, cell.z + dz)))
                return true;
        }
        return false;
    }

    private static bool TriangleIndicesAreValid(int a, int b, int c, int vertexCount)
    {
        return a >= 0 && b >= 0 && c >= 0 && a < vertexCount && b < vertexCount && c < vertexCount;
    }

    private int AbsorbNewBlocksFromHeldCandidate(
        List<Vector3> candidateVertices,
        List<int> candidateTriangles,
        List<Color> candidateColors)
    {
        if (_mesh == null || candidateVertices == null || candidateTriangles == null || candidateTriangles.Count < 3)
            return 0;

        EnsureCommittedMeshBlocksFromDisplayedMesh();
        List<Vector3> mergedVertices = new List<Vector3>(_mesh.vertexCount + 1024);
        List<int> mergedTriangles = new List<int>(_mesh.triangles.Length + 3072);
        List<Color> mergedColors = new List<Color>(_mesh.vertexCount + 1024);
        _mesh.GetVertices(mergedVertices);
        _mesh.GetTriangles(mergedTriangles, 0);
        _mesh.GetColors(mergedColors);
        while (mergedColors.Count < mergedVertices.Count)
            mergedColors.Add(Color.white);

        Dictionary<int, int> remappedVertices = new Dictionary<int, int>();
        int addedTriangles = 0;
        int triangleBudget = Mathf.Clamp(maxHeldCandidateTrianglesToAbsorb, 256, 20000);
        for (int i = 0; i + 2 < candidateTriangles.Count && addedTriangles < triangleBudget; i += 3)
        {
            int ia = candidateTriangles[i];
            int ib = candidateTriangles[i + 1];
            int ic = candidateTriangles[i + 2];
            if (ia < 0 || ib < 0 || ic < 0 ||
                ia >= candidateVertices.Count || ib >= candidateVertices.Count || ic >= candidateVertices.Count)
            {
                continue;
            }

            Vector3 centroid = (candidateVertices[ia] + candidateVertices[ib] + candidateVertices[ic]) / 3f;
            if (_committedMeshBlocks.Contains(MeshBlockForPoint(centroid)))
                continue;
            if (mergedVertices.Count + 3 > maxSurfaceVertices)
                break;

            mergedTriangles.Add(RemapCandidateVertex(ia, candidateVertices, candidateColors, mergedVertices, mergedColors, remappedVertices));
            mergedTriangles.Add(RemapCandidateVertex(ib, candidateVertices, candidateColors, mergedVertices, mergedColors, remappedVertices));
            mergedTriangles.Add(RemapCandidateVertex(ic, candidateVertices, candidateColors, mergedVertices, mergedColors, remappedVertices));
            addedTriangles++;
        }

        if (addedTriangles <= 0)
            return 0;

        _mesh.Clear();
        _mesh.indexFormat = mergedVertices.Count > 65535 ? IndexFormat.UInt32 : IndexFormat.UInt16;
        _mesh.SetVertices(mergedVertices);
        _mesh.SetColors(mergedColors);
        _mesh.SetTriangles(mergedTriangles, 0, true);
        _mesh.RecalculateNormals();
        _mesh.RecalculateBounds();
        CommitDisplayedMeshBlocks(mergedVertices);
        RebuildWireOverlay(mergedVertices, mergedTriangles);
        return addedTriangles;
    }

    private int RemapCandidateVertex(
        int candidateIndex,
        List<Vector3> candidateVertices,
        List<Color> candidateColors,
        List<Vector3> mergedVertices,
        List<Color> mergedColors,
        Dictionary<int, int> remappedVertices)
    {
        if (remappedVertices.TryGetValue(candidateIndex, out int mergedIndex))
            return mergedIndex;
        mergedIndex = mergedVertices.Count;
        remappedVertices[candidateIndex] = mergedIndex;
        mergedVertices.Add(candidateVertices[candidateIndex]);
        mergedColors.Add(candidateColors != null && candidateIndex < candidateColors.Count
            ? candidateColors[candidateIndex]
            : Color.white);
        return mergedIndex;
    }

    private Vector3Int MeshBlockForPoint(Vector3 point)
    {
        int blockVoxels = useStrictCommittedMeshRetention
            ? Mathf.Min(2, Mathf.Clamp(committedMeshBlockSizeVoxels, 1, 8))
            : Mathf.Clamp(committedMeshBlockSizeVoxels, 1, 8);
        float blockSize = Mathf.Max(0.001f, voxelSizeMeters * blockVoxels);
        Vector3 local = (point - _volumeOriginWorld) / blockSize;
        return new Vector3Int(
            Mathf.FloorToInt(local.x),
            Mathf.FloorToInt(local.y),
            Mathf.FloorToInt(local.z));
    }

    private IEnumerator CaptureRawSnapshotAndIntegrateRoutine()
    {
        ResolveRefs();
        EnsureObjects();
        BeginConfidenceAuditCapture();

        bool fixedFrameBatch = useFixedIntegratedFrameBatch;
        int targetFrames = fixedFrameBatch
            ? Mathf.Max(1, targetIntegratedFramesPerTrigger)
            : Mathf.Max(1, maxFusionFramesPerTrigger);
        int maxConsumedFrames = Mathf.Max(targetFrames, maxRawFramesConsumedPerBatch);
        int maxTimeouts = Mathf.Max(1, maxConsecutiveRawFrameTimeouts);
        _activeCaptureBatchTargetFrames = targetFrames;
        _activeCaptureBatchIntegratedFrames = 0;
        _activeCaptureBatchUniqueRawFrames = 0;
        _activeCaptureBatchTimeouts = 0;
        LastCaptureBatchTargetFrames = targetFrames;
        LastCaptureBatchIntegratedFrames = 0;
        LastCaptureBatchUniqueRawFrames = 0;
        LastCaptureBatchTimeoutCount = 0;
        LastCaptureBatchMeshRebuildCount = 0;
        LastCaptureBatchMeshRebuildMilliseconds = 0f;
        LastCaptureBatchMeshRebuildWallMilliseconds = 0f;
        LastCaptureBatchBudgetedRebuildYieldCount = 0;
        LastCaptureBatchBudgetedRebuildMaxSliceMilliseconds = 0f;
        LastCaptureBatchMeshRebuildSettleFrames = 0;
        LastCaptureBatchUsedIncrementalProductionRebuild = false;
        LastCaptureBatchIncrementalProductionFallback = false;
        LastCaptureBatchIncrementalProductionVerdict = "not_run";
        LastCaptureBatchIntegrationMilliseconds = 0f;
        LastCaptureBatchMaxFrameIntegrationMilliseconds = 0f;
        LastCaptureBatchBudgetedFusionYieldCount = 0;
        LastCaptureBatchBudgetedFusionWallMilliseconds = 0f;
        LastCaptureBatchBudgetedFusionMaxSliceMilliseconds = 0f;
        LastCaptureBatchUniqueSurfaceVoxelWriteCount = 0;
        LastCaptureBatchMergedSurfaceVoxelWriteCount = 0;
        LastCaptureBatchComplete = false;
        LastCaptureBatchAtomicProvisionalPromotionCount = 0;
        LastCaptureBatchStrongProvisionalPromotionCount = 0;
        LastRebaselineValid = false;
        LastRebaselineWeightedVoxelCount = 0;
        LastRebaselineWeight1VoxelCount = 0;
        LastRebaselineWeight2To3VoxelCount = 0;
        LastRebaselineWeight4PlusVoxelCount = 0;
        LastRebaselineNewHoleCellCount = 0;
        LastRebaselineRecoveredHoleCellCount = 0;
        LastCaptureBatchTsdfGenerationStart = _authoritativeTsdfGeneration;
        LastCaptureBatchWeightedVoxelsStart = CountWeightedTsdfVoxels();
        LastCaptureBatchTsdfGenerationEnd = LastCaptureBatchTsdfGenerationStart;
        LastCaptureBatchWeightedVoxelsEnd = LastCaptureBatchWeightedVoxelsStart;
        LastCaptureBatchReusedAuthoritativeTsdf =
            _volumeInitialized && LastCaptureBatchWeightedVoxelsStart > 0;
        BeginFrameConvergenceDiagnostics(targetFrames, LastCaptureBatchWeightedVoxelsStart);
        BeginFastFusionShadowBatch();

        if (rawDepthSource == null)
        {
            Warn("Raw depth source is missing.");
            EndConfidenceAuditCapture(0, "raw depth source missing");
            _captureRoutine = null;
            yield break;
        }

        rawDepthSource.enabled = true;
        SuppressSourcePreview();

        int integratedFrames = 0;
        int uniqueRawFrames = 0;
        int consecutiveTimeouts = 0;
        HashSet<int> consumedFrameIndices = new HashSet<int>();
        float burstStart = Time.unscaledTime;
        float burstDuration = Mathf.Max(0.05f, fusionBurstDurationSeconds);

        while (integratedFrames < targetFrames)
        {
            if (!fixedFrameBatch && Time.unscaledTime - burstStart >= burstDuration)
                break;
            if (fixedFrameBatch && (uniqueRawFrames >= maxConsumedFrames || consecutiveTimeouts >= maxTimeouts))
                break;

            if (forceRawRefreshOnSnapshot && !rawDepthSource.HasPendingReadback)
                rawDepthSource.RefreshNow(forcePreprocessorRefresh: true);

            float frameStart = Time.unscaledTime;
            bool integratedThisFrame = false;
            bool consumedUniqueFrame = false;
            while (Time.unscaledTime - frameStart < waitForRawFrameTimeoutSeconds)
            {
                if (!rawDepthSource.HasPendingReadback &&
                    rawDepthSource.TryGetLatestRawDepthFrameSnapshot(out ScanCoverDepthGridPointCloud.RawDepthFrameSnapshot ready) &&
                    ready.worldPositions != null &&
                    ready.worldPositions.Length > 0 &&
                    consumedFrameIndices.Add(ready.frameIndex))
                {
                    consumedUniqueFrame = true;
                    uniqueRawFrames++;
                    int attemptOrdinal = uniqueRawFrames;
                    double integrationWallStart = Time.realtimeSinceStartupAsDouble;
                    IEnumerator integrationRoutine = IntegrateSnapshotBudgetedRoutine(ready, true);
                    while (integrationRoutine.MoveNext())
                        yield return integrationRoutine.Current;
                    integratedThisFrame = _budgetedSnapshotIntegratedResult;
                    LastBudgetedFusionWallMilliseconds =
                        (float)((Time.realtimeSinceStartupAsDouble - integrationWallStart) * 1000.0);
                    float integrationMilliseconds = LastBudgetedFusionComputeMilliseconds;
                    LastCaptureBatchIntegrationMilliseconds += integrationMilliseconds;
                    LastCaptureBatchMaxFrameIntegrationMilliseconds = Mathf.Max(
                        LastCaptureBatchMaxFrameIntegrationMilliseconds,
                        integrationMilliseconds);
                    LastCaptureBatchBudgetedFusionYieldCount += LastBudgetedFusionYieldCount;
                    LastCaptureBatchBudgetedFusionWallMilliseconds += LastBudgetedFusionWallMilliseconds;
                    LastCaptureBatchBudgetedFusionMaxSliceMilliseconds = Mathf.Max(
                        LastCaptureBatchBudgetedFusionMaxSliceMilliseconds,
                        LastBudgetedFusionMaxSliceMilliseconds);
                    LastCaptureBatchUniqueSurfaceVoxelWriteCount += LastBudgetedFusionUniqueSurfaceVoxelWriteCount;
                    LastCaptureBatchMergedSurfaceVoxelWriteCount += LastBudgetedFusionMergedSurfaceVoxelWriteCount;
                    QueueFastFusionShadowFrame(
                        ready,
                        attemptOrdinal,
                        ConsumeFastFusionDecisionJournal());
                    LastCaptureBatchAtomicProvisionalPromotionCount += LastAtomicPromotedProvisionalVoxelCount;
                    LastCaptureBatchStrongProvisionalPromotionCount += LastStrongCurrentProvisionalPromotedCount;
                    // A fully gated frame is still consumed; do not repeatedly reprocess it.
                    if (integratedThisFrame)
                        integratedFrames++;
                    RecordFrameConvergence(
                        attemptOrdinal, integratedFrames, ready.frameIndex,
                        integratedThisFrame, integrationMilliseconds);
                    if (!fixedFrameBatch && integratedThisFrame && rebuildMeshAfterEachCapture && !rebuildMeshAfterFusionBurstOnly)
                        RebuildMesh();
                    break;
                }

                yield return null;
            }

            if (consumedUniqueFrame)
                consecutiveTimeouts = 0;
            else
                consecutiveTimeouts++;

            _activeCaptureBatchIntegratedFrames = integratedFrames;
            _activeCaptureBatchUniqueRawFrames = uniqueRawFrames;
            _activeCaptureBatchTimeouts = consecutiveTimeouts;

            if (!consumedUniqueFrame || !integratedThisFrame)
                yield return null;
        }

        if (!fixedFrameBatch && integratedFrames <= 0)
        {
            bool integratedLatest = IntegrateLatestRawSnapshot();
            if (integratedLatest)
                integratedFrames = 1;
        }

        if (!enableLowOverheadPerformanceMeasurement &&
            enableFastFusionShadow && uniqueRawFrames > 0 && _volumeInitialized &&
            _tsdf != null && _weights != null)
        {
            float[] authorityTsdfSnapshot = (float[])_tsdf.Clone();
            byte[] authorityWeightSnapshot = (byte[])_weights.Clone();
            _fastFusionShadowAuthorityFingerprintBeforeFinalize =
                ComputeFastFusionAuthorityFingerprint(_tsdf, _weights);
            Task<ScanCoverFastFusionShadow.BatchMetrics> finalizeTask =
                QueueFastFusionShadowFinalize(authorityTsdfSnapshot, authorityWeightSnapshot);
            double shadowWaitStart = Time.realtimeSinceStartupAsDouble;
            while (finalizeTask != null && !finalizeTask.IsCompleted)
                yield return null;
            double shadowWaitMilliseconds =
                (Time.realtimeSinceStartupAsDouble - shadowWaitStart) * 1000.0;
            CompleteFastFusionShadowFinalize(finalizeTask, shadowWaitMilliseconds);
        }

        LastCaptureBatchIntegratedFrames = integratedFrames;
        LastCaptureBatchUniqueRawFrames = uniqueRawFrames;
        LastCaptureBatchTimeoutCount = consecutiveTimeouts;
        LastCaptureBatchComplete = fixedFrameBatch
            ? integratedFrames >= targetFrames
            : integratedFrames > 0;
        // Snapshot authoritative-volume diagnostics before RebuildMesh writes the batch
        // summary, otherwise the exported file would contain the preceding batch's end state.
        LastCaptureBatchTsdfGenerationEnd = _authoritativeTsdfGeneration;
        LastCaptureBatchWeightedVoxelsEnd = CountWeightedTsdfVoxels();
        FinalizePressureShadowMatrix(integratedFrames);

        bool shouldRebuildMesh =
            fixedFrameBatch && rebuildMeshAfterEachCapture && integratedFrames > 0 ||
            !fixedFrameBatch && rebuildMeshAfterEachCapture &&
            (rebuildMeshAfterFusionBurstOnly || integratedFrames <= 0);
        if (shouldRebuildMesh)
        {
            if (stageMeshRebuildAfterFusionBatch)
            {
                int settleFrames = Mathf.Clamp(meshRebuildSettleFrames, 0, 3);
                for (int frame = 0; frame < settleFrames; frame++)
                {
                    LastCaptureBatchMeshRebuildSettleFrames++;
                    yield return null;
                }
            }
            double rebuildWallStart = Time.realtimeSinceStartupAsDouble;
            IEnumerator rebuildRoutine =
                TryRebuildAuthoritativeIncrementalProductionRoutine();
            while (rebuildRoutine.MoveNext())
                yield return rebuildRoutine.Current;
            bool usedIncrementalProduction =
                _budgetedIncrementalProductionResult;
            LastCaptureBatchUsedIncrementalProductionRebuild =
                usedIncrementalProduction;
            if (!usedIncrementalProduction)
            {
                LastCaptureBatchIncrementalProductionFallback =
                    enableAuthoritativeIncrementalProductionRebuild;
                if (authoritativeIncrementalFallbackToFullRebuild ||
                    !enableAuthoritativeIncrementalProductionRebuild)
                    RebuildMesh();
            }
            LastCaptureBatchMeshRebuildWallMilliseconds =
                (float)((Time.realtimeSinceStartupAsDouble - rebuildWallStart) * 1000.0);
            if (_activeIncrementalRebuildBudget != null)
            {
                LastCaptureBatchMeshRebuildMilliseconds =
                    _activeIncrementalRebuildBudget.CompleteAndGetComputeMilliseconds();
                LastCaptureBatchBudgetedRebuildYieldCount =
                    _activeIncrementalRebuildBudget.YieldCount;
                LastCaptureBatchBudgetedRebuildMaxSliceMilliseconds =
                    _activeIncrementalRebuildBudget.MaxSliceMilliseconds;
            }
            else
            {
                LastCaptureBatchMeshRebuildMilliseconds =
                    LastCaptureBatchMeshRebuildWallMilliseconds;
            }
            LastCaptureBatchMeshRebuildCount = 1;
            if (stageMeshRebuildAfterFusionBatch)
                yield return null;
        }
        UpdateRebaselineDiagnostics();
        if (LastCaptureBatchComplete)
            CompletedCaptureBatchCount++;

        if (debugLog)
        {
            Debug.Log(
                $"[ScanCoverTsdfSingleShellPrototype] Capture batch complete={LastCaptureBatchComplete}: integratedFrames={integratedFrames}/{targetFrames} uniqueRawFrames={uniqueRawFrames} timeouts={consecutiveTimeouts} integrationMs={LastCaptureBatchIntegrationMilliseconds:F1} maxFrameMs={LastCaptureBatchMaxFrameIntegrationMilliseconds:F1} meshRebuilds={LastCaptureBatchMeshRebuildCount} rebuildMs={LastCaptureBatchMeshRebuildMilliseconds:F1} incremental={LastCaptureBatchUsedIncrementalProductionRebuild} fallback={LastCaptureBatchIncrementalProductionFallback} verdict={LastCaptureBatchIncrementalProductionVerdict} settleFrames={LastCaptureBatchMeshRebuildSettleFrames} totalFrames={IntegratedFrameCount} fallbackSamples={_fallbackSurfacePoints.Count} vertices={LastMeshVertexCount} triangles={LastMeshTriangleCount}",
                this);
        }

        string status = LastCaptureBatchComplete
            ? "complete"
            : integratedFrames > 0
                ? "partial_batch"
                : "no_integrated_frame";
        EndConfidenceAuditCapture(integratedFrames, status);
        _captureRoutine = null;
        _activeCaptureBatchTargetFrames = 0;
        _activeCaptureBatchIntegratedFrames = 0;
        _activeCaptureBatchUniqueRawFrames = 0;
        _activeCaptureBatchTimeouts = 0;
    }

    private void BeginFastFusionShadowBatch()
    {
        _lastFastFusionShadowBatch = null;
        _lastFastFusionIndependentBatch = null;
        _lastFastFusionIndependentResetBatch = null;
        _lastFastFusionShadowFrameCsvPath = null;
        _lastFastFusionShadowBlockAuditCsvPath = null;
        _lastFastFusionShadowAuthorityUnchanged = true;
        _fastFusionShadowAuthorityFingerprintBeforeFinalize = 0UL;
        if (enableLowOverheadPerformanceMeasurement)
        {
            _fastFusionPhaseOneDirtyBlocks.Clear();
            _fastFusionPhaseOnePromoted = false;
            _fastFusionPhaseOneConsecutiveExactBatches = 0;
            _fastFusionPhaseOneLastVerdict = "paused_for_performance_measurement";
            return;
        }
        _fastFusionShadowBatchId++;
    }

    private ScanCoverFastFusionShadow.Config BuildFastFusionShadowConfig()
    {
        return new ScanCoverFastFusionShadow.Config
        {
            BatchId = _fastFusionShadowBatchId,
            DimX = _dimX,
            DimY = _dimY,
            DimZ = _dimZ,
            Origin = _volumeOriginWorld,
            VoxelSize = Mathf.Max(0.0001f, voxelSizeMeters),
            Truncation = Mathf.Max(voxelSizeMeters, truncationMeters),
            MinDepth = Mathf.Max(0f, minDepthMeters),
            MaxDepth = Mathf.Max(minDepthMeters + 0.001f, maxDepthMeters),
            MaxWeight = Mathf.Max(1f, referenceClassicMaxVoxelWeight),
            MinimumAngleWeight = Mathf.Clamp01(referenceClassicMinimumAngleWeight),
            MinimumDistanceWeight = Mathf.Clamp01(referenceClassicMinimumDistanceWeight),
            ProjectiveLateralRadiusScale =
                Mathf.Clamp(projectiveVoxelCenterRadiusScale, 0.5f, 1.25f),
            PlaneStride = Mathf.Clamp(fastFusionShadowPlaneStride, 2, 4),
            DetailStride = Mathf.Clamp(fastFusionShadowDetailStride, 1, 3),
            BlockVoxels = Mathf.Clamp(fastFusionShadowBlockVoxels, 4, 16),
            PlaneNormalDot = Mathf.Clamp(fastFusionShadowPlaneNormalDot, 0.75f, 1f),
            PlaneResidualMeters = Mathf.Clamp(fastFusionShadowPlaneResidualMeters, 0.005f, 0.08f),
            MinimumPlaneNeighbors = Mathf.Clamp(fastFusionShadowMinimumPlaneNeighbors, 2, 8),
            // The sparse shadow may store weight-1 provisional voxels, but topology must be
            // compared with the same publishable-corner threshold as authority.
            ShadowComparisonMinWeight = Mathf.Max(
                minSurfaceCornerWeight,
                fastFusionShadowComparisonMinWeight),
            AuthorityComparisonMinWeight = Mathf.Max(1, minSurfaceCornerWeight),
            BlockAuditMinimumWeightedCoverage =
                Mathf.Clamp(fastFusionBlockAuditMinimumWeightedCoverage, 0.50f, 1f),
            BlockAuditMinimumSignAgreement =
                Mathf.Clamp(fastFusionBlockAuditMinimumSignAgreement, 0.50f, 1f),
            BlockAuditMinimumZeroCrossJaccard =
                Mathf.Clamp(fastFusionBlockAuditMinimumZeroCrossJaccard, 0.25f, 1f),
            BlockAuditMaximumMeanSurfaceDeltaMeters = Mathf.Max(
                0.0001f,
                voxelSizeMeters * Mathf.Clamp(
                    fastFusionBlockAuditMaximumMeanSurfaceDeltaVoxels, 0.1f, 2f)),
            EnableMismatchBlockReconciliation = fastFusionShadowEnableMismatchBlockReconciliation,
            EnableDepthSupportGate = false,
            DepthSupportRadiusPixels =
                Mathf.Clamp(depthDiscontinuityNeighborRadiusPixels, 1, 3),
            MinimumDepthConsistentNeighbors =
                Mathf.Clamp(minDepthConsistentNeighbors, 1, 8),
            MaximumDepthDiscontinuityMeters =
                Mathf.Max(0.001f, maxDepthDiscontinuityMeters),
            MaximumDepthDiscontinuityRatio =
                Mathf.Clamp(maxDepthDiscontinuityRatio, 0f, 0.2f),
            MinimumDepthConsistencyRatio =
                Mathf.Clamp01(minTsdfDepthConsistencyRatio),
            EnableConservativeFreeSpaceCarving = false,
            FreeSpaceWeightScale = 0f,
            FreeSpaceMaximumDistanceMeters = 0f,
            FreeSpaceMaximumExtraEdgeGrowthRatio = 0f,
            FreeSpaceMaximumExtraEdgeGrowthAbsolute = 0,
            EnableStableProjectiveOwnership = false,
            StableOwnershipSwitchConfirmations = 2,
            StableOwnershipPendingMaxGapFrames = 3,
            StableOwnershipLateralImprovementRatio = 0.65f,
            StableOwnershipPendingTsdfTolerance = 0.35f,
            StableOwnershipPendingSurfaceToleranceVoxels = 2f,
            ResetStateAtBatchBoundary = false
        };
    }

    private ScanCoverFastFusionShadow.Config BuildFastFusionIndependentConfig(
        ScanCoverFastFusionShadow.Config baseConfig,
        bool resetStateAtBatchBoundary)
    {
        ScanCoverFastFusionShadow.Config config = baseConfig;
        config.EnableMismatchBlockReconciliation = false;
        // The independent route must age observations under the same cap as authority.
        // The former reference-classic cap (32) froze stale signs while authority capped at 12.
        config.MaxWeight = Mathf.Max(1, maxFusionWeight);
        config.PlaneStride = Mathf.Clamp(fastFusionIndependentPlaneStride, 2, 6);
        config.DetailStride = Mathf.Clamp(fastFusionIndependentDetailStride, 1, 4);
        config.EnableDepthSupportGate = fastFusionIndependentEnableDepthSupportGate;
        config.EnableConservativeFreeSpaceCarving =
            fastFusionIndependentEnableConservativeFreeSpaceCarving;
        config.FreeSpaceWeightScale = Mathf.Clamp(
            fastFusionIndependentFreeSpaceWeightScale, 0.05f, 0.50f);
        config.FreeSpaceMaximumDistanceMeters = Mathf.Clamp(
            fastFusionIndependentFreeSpaceMaximumDistanceMeters, 0.20f, 1.50f);
        config.FreeSpaceMaximumExtraEdgeGrowthRatio = Mathf.Clamp(
            fastFusionIndependentMaximumExtraEdgeGrowthRatio, 0f, 0.25f);
        config.FreeSpaceMaximumExtraEdgeGrowthAbsolute = Mathf.Clamp(
            fastFusionIndependentMaximumExtraEdgeGrowthAbsolute, 0, 128);
        config.EnableStableProjectiveOwnership =
            fastFusionIndependentEnableStableProjectiveOwnership;
        config.StableOwnershipSwitchConfirmations = Mathf.Clamp(
            fastFusionIndependentStableOwnershipSwitchConfirmations, 2, 4);
        config.StableOwnershipPendingMaxGapFrames = Mathf.Clamp(
            fastFusionIndependentStableOwnershipPendingMaxGapFrames, 1, 8);
        config.StableOwnershipLateralImprovementRatio = Mathf.Clamp(
            fastFusionIndependentStableOwnershipLateralImprovementRatio,
            0.25f,
            1f);
        config.StableOwnershipPendingTsdfTolerance = Mathf.Clamp(
            fastFusionIndependentStableOwnershipPendingTsdfTolerance,
            0.10f,
            1f);
        config.StableOwnershipPendingSurfaceToleranceVoxels = Mathf.Clamp(
            fastFusionIndependentStableOwnershipPendingSurfaceToleranceVoxels,
            0.5f,
            3f);
        config.ResetStateAtBatchBoundary = resetStateAtBatchBoundary;
        return config;
    }

    private void QueueFastFusionShadowFrame(
        ScanCoverDepthGridPointCloud.RawDepthFrameSnapshot snapshot,
        int frameOrdinal,
        ScanCoverFastFusionShadow.VoxelWrite[] decisionJournal)
    {
        if (enableLowOverheadPerformanceMeasurement ||
            !enableFastFusionShadow || snapshot == null || !_volumeInitialized)
            return;

        ScanCoverFastFusionShadow.Config config = BuildFastFusionShadowConfig();
        Task antecedent = _fastFusionShadowTail ?? Task.CompletedTask;
        _fastFusionShadowTail = antecedent.ContinueWith(previous =>
        {
            previous.GetAwaiter().GetResult();
            int inputPixels = snapshot.resolutionWidth > 0 && snapshot.resolutionHeight > 0
                ? snapshot.resolutionWidth * snapshot.resolutionHeight
                : 0;
            _fastFusionShadow.ApplyDecisionJournalFrame(
                config,
                decisionJournal,
                snapshot.frameIndex,
                inputPixels,
                frameOrdinal);
            if (enableFastFusionIndependentDecisionShadow)
            {
                ScanCoverFastFusionShadow.Config independentConfig =
                    BuildFastFusionIndependentConfig(config, false);
                _fastFusionIndependentShadow.IntegrateFrame(
                    independentConfig, snapshot, frameOrdinal);
                if (enableFastFusionIndependentResetControlShadow)
                {
                    ScanCoverFastFusionShadow.Config resetConfig =
                        BuildFastFusionIndependentConfig(config, true);
                    _fastFusionIndependentResetShadow.IntegrateFrame(
                        resetConfig, snapshot, frameOrdinal);
                }
            }
        }, TaskScheduler.Default);
    }

    private void BeginFastFusionDecisionJournal(int rawFrameIndex)
    {
        _fastFusionDecisionJournal.Clear();
        _fastFusionDecisionJournalRawFrame = rawFrameIndex;
        _fastFusionDecisionJournalOpen =
            enableFastFusionShadow && !enableLowOverheadPerformanceMeasurement;
    }

    private ScanCoverFastFusionShadow.VoxelWrite[] ConsumeFastFusionDecisionJournal()
    {
        _fastFusionDecisionJournalOpen = false;
        if (_fastFusionDecisionJournal.Count <= 0)
            return System.Array.Empty<ScanCoverFastFusionShadow.VoxelWrite>();
        ScanCoverFastFusionShadow.VoxelWrite[] result = _fastFusionDecisionJournal.ToArray();
        _fastFusionDecisionJournal.Clear();
        return result;
    }

    private void RecordFastFusionDecisionWrite(
        int index,
        string operation,
        float newTsdf,
        int newWeight)
    {
        if (!_fastFusionDecisionJournalOpen || index < 0)
            return;
        _fastFusionDecisionJournal.Add(new ScanCoverFastFusionShadow.VoxelWrite
        {
            DenseIndex = index,
            Tsdf = newTsdf,
            Weight = (byte)Mathf.Clamp(newWeight, 0, byte.MaxValue),
            OperationCode = StableFastFusionOperationCode(operation)
        });
    }

    private static int StableFastFusionOperationCode(string operation)
    {
        unchecked
        {
            int hash = 17;
            if (!string.IsNullOrEmpty(operation))
            {
                for (int i = 0; i < operation.Length; i++)
                    hash = hash * 31 + operation[i];
            }
            return hash;
        }
    }

    private Task<ScanCoverFastFusionShadow.BatchMetrics> QueueFastFusionShadowFinalize(
        float[] authorityTsdfSnapshot,
        byte[] authorityWeightSnapshot)
    {
        if (enableLowOverheadPerformanceMeasurement ||
            !enableFastFusionShadow || !_volumeInitialized)
            return null;

        ScanCoverFastFusionShadow.Config config = BuildFastFusionShadowConfig();
        Task antecedent = _fastFusionShadowTail ?? Task.CompletedTask;
        Task<ScanCoverFastFusionShadow.BatchMetrics> finalizeTask = antecedent.ContinueWith(previous =>
        {
            previous.GetAwaiter().GetResult();
            ScanCoverFastFusionShadow.BatchMetrics journalReplay =
                _fastFusionShadow.FinalizeBatch(
                config, authorityTsdfSnapshot, authorityWeightSnapshot);
            if (enableFastFusionIndependentDecisionShadow)
            {
                ScanCoverFastFusionShadow.Config independentConfig =
                    BuildFastFusionIndependentConfig(config, false);
                _lastFastFusionIndependentBatch =
                    _fastFusionIndependentShadow.FinalizeBatch(
                        independentConfig,
                        authorityTsdfSnapshot,
                        authorityWeightSnapshot);
                if (enableFastFusionIndependentResetControlShadow)
                {
                    ScanCoverFastFusionShadow.Config resetConfig =
                        BuildFastFusionIndependentConfig(config, true);
                    _lastFastFusionIndependentResetBatch =
                        _fastFusionIndependentResetShadow.FinalizeBatch(
                            resetConfig,
                            authorityTsdfSnapshot,
                            authorityWeightSnapshot);
                }
            }
            return journalReplay;
        }, TaskScheduler.Default);
        _fastFusionShadowTail = finalizeTask;
        return finalizeTask;
    }

    private void CompleteFastFusionShadowFinalize(
        Task<ScanCoverFastFusionShadow.BatchMetrics> finalizeTask,
        double tailWaitMilliseconds)
    {
        try
        {
            if (finalizeTask == null)
                return;
            _lastFastFusionShadowBatch = finalizeTask.GetAwaiter().GetResult();
            _lastFastFusionShadowBatch.MainThreadTailWaitMilliseconds = tailWaitMilliseconds;
            _lastFastFusionShadowAuthorityUnchanged =
                _fastFusionShadowAuthorityFingerprintBeforeFinalize ==
                ComputeFastFusionAuthorityFingerprint(_tsdf, _weights);
            UpdateFastFusionPhaseOnePromotion();
            UpdateFastFusionIndependentReadiness();
        }
        catch (System.Exception exception)
        {
            _lastFastFusionShadowBatch = new ScanCoverFastFusionShadow.BatchMetrics
            {
                BatchId = _fastFusionShadowBatchId,
                Complete = false,
                Error = exception.GetBaseException().Message,
                MainThreadTailWaitMilliseconds = tailWaitMilliseconds
            };
            _lastFastFusionShadowAuthorityUnchanged =
                _fastFusionShadowAuthorityFingerprintBeforeFinalize ==
                ComputeFastFusionAuthorityFingerprint(_tsdf, _weights);
            ApplyFastFusionPhaseOneFallback("finalize_exception");
            _fastFusionIndependentReadyStreak = 0;
            _fastFusionIndependentPromotionCandidate = false;
            _fastFusionIndependentReadinessVerdict = "finalize_exception";
            Debug.LogWarning(
                "[ScanCoverTsdfSingleShellPrototype] Fast fusion shadow failed without touching authoritative output: " +
                _lastFastFusionShadowBatch.Error,
                this);
        }
        finally
        {
            _fastFusionShadowTail = Task.CompletedTask;
        }
    }

    private void QueueFastFusionShadowClear()
    {
        Task antecedent = _fastFusionShadowTail ?? Task.CompletedTask;
        _fastFusionShadowTail = antecedent.ContinueWith(previous =>
        {
            try
            {
                previous.GetAwaiter().GetResult();
            }
            catch
            {
                // A failed compare-only task must not prevent its private state from resetting.
            }
            _fastFusionShadow.Clear();
            _fastFusionIndependentShadow.Clear();
            _fastFusionIndependentResetShadow.Clear();
        }, TaskScheduler.Default);
        _lastFastFusionShadowBatch = null;
        _lastFastFusionIndependentBatch = null;
        _lastFastFusionIndependentResetBatch = null;
        _lastFastFusionShadowFrameCsvPath = null;
        _lastFastFusionShadowBlockAuditCsvPath = null;
        _fastFusionPhaseOneDirtyBlocks.Clear();
        _fastFusionPhaseOnePromoted = false;
        _fastFusionPhaseOneConsecutiveExactBatches = 0;
        _fastFusionPhaseOneFallbackCount = 0;
        _fastFusionPhaseOneLastVerdict = "cleared";
        _fastFusionPhaseOneScheduledPatchCount = 0;
        _fastFusionIndependentReadyStreak = 0;
        _fastFusionIndependentPromotionCandidate = false;
        _fastFusionIndependentReadinessVerdict = "cleared";
    }

    private void UpdateFastFusionPhaseOnePromotion()
    {
        ScanCoverFastFusionShadow.BatchMetrics batch = _lastFastFusionShadowBatch;
        bool exact =
            enableFastFusionPhaseOnePromotion &&
            batch != null &&
            batch.Complete &&
            _lastFastFusionShadowAuthorityUnchanged &&
            batch.PreRepairSurfaceBlocks > 0 &&
            batch.PreRepairEquivalentBlocks == batch.PreRepairSurfaceBlocks &&
            batch.PreRepairSignMismatchBlocks == 0 &&
            batch.PreRepairTopologyMismatchBlocks == 0 &&
            batch.ReconciliationSeedBlocks == 0;
        if (!exact)
        {
            ApplyFastFusionPhaseOneFallback("pre_repair_audit_mismatch");
            return;
        }

        _fastFusionPhaseOneConsecutiveExactBatches++;
        if (_fastFusionPhaseOneConsecutiveExactBatches >=
            Mathf.Clamp(fastFusionPhaseOneRequiredExactBatches, 1, 5))
            _fastFusionPhaseOnePromoted = true;
        _fastFusionPhaseOneLastVerdict = _fastFusionPhaseOnePromoted
            ? "active_exact" : "qualifying_exact";
        _fastFusionPhaseOneDirtyBlocks.Clear();
        if (_fastFusionPhaseOnePromoted)
        {
            Vector3Int[] dirty = _fastFusionShadow.GetDirtyBlocksSnapshot();
            for (int i = 0; i < dirty.Length; i++)
                _fastFusionPhaseOneDirtyBlocks.Add(dirty[i]);
        }
    }

    private void ApplyFastFusionPhaseOneFallback(string reason)
    {
        bool wasPromoted = _fastFusionPhaseOnePromoted;
        _fastFusionPhaseOneConsecutiveExactBatches = 0;
        _fastFusionPhaseOneDirtyBlocks.Clear();
        if (fastFusionPhaseOneAutoFallbackOnMismatch)
            _fastFusionPhaseOnePromoted = false;
        if (wasPromoted && !_fastFusionPhaseOnePromoted)
            _fastFusionPhaseOneFallbackCount++;
        _fastFusionPhaseOneLastVerdict = reason;
    }

    private void UpdateFastFusionIndependentReadiness()
    {
        ScanCoverFastFusionShadow.BatchMetrics batch = _lastFastFusionIndependentBatch;
        if (!enableFastFusionIndependentDecisionShadow || batch == null || !batch.Complete)
        {
            _fastFusionIndependentReadyStreak = 0;
            _fastFusionIndependentPromotionCandidate = false;
            _fastFusionIndependentReadinessVerdict = "incomplete";
            return;
        }
        if (!_lastFastFusionShadowAuthorityUnchanged || batch.PreRepairSurfaceBlocks <= 0)
        {
            _fastFusionIndependentReadyStreak = 0;
            _fastFusionIndependentPromotionCandidate = false;
            _fastFusionIndependentReadinessVerdict =
                !_lastFastFusionShadowAuthorityUnchanged
                    ? "authority_mutated_during_compare"
                    : "no_surface_blocks";
            return;
        }
        if (batch.SpatialFusionTrendGuardEvaluated &&
            !batch.SpatialFusionTrendGuardPass)
        {
            _fastFusionIndependentReadyStreak = 0;
            _fastFusionIndependentPromotionCandidate = false;
            _fastFusionIndependentReadinessVerdict =
                batch.MissingEdgeDeltaFromPreviousBatch >= 0
                    ? "spatial_fusion_missing_edges_not_decreasing"
                    : "spatial_fusion_extra_edge_guard";
            return;
        }

        float equivalentRatio =
            (float)batch.PreRepairEquivalentBlocks / batch.PreRepairSurfaceBlocks;
        bool equivalentPass = equivalentRatio >= Mathf.Clamp(
            fastFusionIndependentMinimumEquivalentBlockRatio, 0.80f, 1f);
        bool coveragePass = batch.AuthorityWeightedCoverage >= Mathf.Clamp(
            fastFusionIndependentMinimumWeightedCoverage, 0.90f, 1f);
        bool signPass = batch.CommonSignAgreement >= Mathf.Clamp(
            fastFusionIndependentMinimumSignAgreement, 0.90f, 1f);
        bool topologyPass = batch.ZeroCrossJaccard >= Mathf.Clamp(
            fastFusionIndependentMinimumZeroCrossJaccard, 0.80f, 1f);
        bool cpuPass = batch.IntegrationCpuMilliseconds <= Mathf.Max(
            1f, fastFusionIndependentMaximumBatchCpuMilliseconds);
        if (!equivalentPass || !coveragePass || !signPass || !topologyPass || !cpuPass)
        {
            _fastFusionIndependentReadyStreak = 0;
            _fastFusionIndependentPromotionCandidate = false;
            _fastFusionIndependentReadinessVerdict =
                !equivalentPass ? "equivalent_block_ratio" :
                !coveragePass ? "weighted_coverage" :
                !signPass ? "sign_agreement" :
                !topologyPass ? "zero_cross_topology" :
                "cpu_budget";
            return;
        }

        _fastFusionIndependentReadyStreak++;
        int required = Mathf.Clamp(
            fastFusionIndependentRequiredReadyBatches, 2, 10);
        _fastFusionIndependentPromotionCandidate =
            _fastFusionIndependentReadyStreak >= required;
        _fastFusionIndependentReadinessVerdict =
            _fastFusionIndependentPromotionCandidate
                ? "promotion_candidate_shadow_only"
                : "qualifying";
    }

    private static ulong ComputeFastFusionAuthorityFingerprint(float[] tsdf, byte[] weights)
    {
        if (tsdf == null || weights == null)
            return 0UL;
        int count = Mathf.Min(tsdf.Length, weights.Length);
        ulong hash = 1469598103934665603UL;
        for (int i = 0; i < count; i++)
        {
            uint bits = unchecked((uint)System.BitConverter.SingleToInt32Bits(tsdf[i]));
            hash ^= bits;
            hash *= 1099511628211UL;
            hash ^= weights[i];
            hash *= 1099511628211UL;
        }
        return hash;
    }

    private void BeginFrameConvergenceDiagnostics(int targetFrames, int weightedVoxelsStart)
    {
        ReleasePressureShadowSnapshots();
        _frameConvergenceRows.Clear();
        _frameConvergenceTargetFrames = Mathf.Max(1, targetFrames);
        _frameConvergencePreviousWeightedVoxels = Mathf.Max(0, weightedVoxelsStart);
        _frameConvergenceCumulativeIntegrationMilliseconds = 0f;
        LastFrameConvergenceObservedFrameCount = 0;
        LastFrameConvergenceEarliestStableFrame = 0;
        LastFrameConvergenceDiagnosticMilliseconds = 0f;
        if (enableLowOverheadPerformanceMeasurement)
            return;
        if ((enablePerFrameConvergenceDiagnostics || enablePressureShadowMatrix) &&
            _tsdf != null && _weights != null)
        {
            double diagnosticStart = Time.realtimeSinceStartupAsDouble;
            CaptureTsdfStateSignature(
                true, out _frameConvergencePreviousStates,
                out _, out _, out _, out _, out _);
            LastFrameConvergenceDiagnosticMilliseconds +=
                (float)((Time.realtimeSinceStartupAsDouble - diagnosticStart) * 1000.0);
        }
    }

    private void RecordFrameConvergence(
        int attemptOrdinal,
        int integratedOrdinal,
        int rawFrameIndex,
        bool integrated,
        float integrationMilliseconds)
    {
        if (enableLowOverheadPerformanceMeasurement ||
            (!enablePerFrameConvergenceDiagnostics && !enablePressureShadowMatrix))
            return;

        _frameConvergenceCumulativeIntegrationMilliseconds += Mathf.Max(0f, integrationMilliseconds);
        FrameConvergenceRow row = new FrameConvergenceRow
        {
            AttemptOrdinal = attemptOrdinal,
            IntegratedOrdinal = integratedOrdinal,
            RawFrameIndex = rawFrameIndex,
            Integrated = integrated,
            IntegrationMilliseconds = integrationMilliseconds,
            ReferenceClassicIntegrationMilliseconds = LastReferenceClassicIntegrationMilliseconds,
            InputSamples = LastInputSampleCount,
            AcceptedSamples = LastIntegratedSampleCount,
            UpdatedVoxels = LastUpdatedVoxelCount
        };

        double diagnosticStart = Time.realtimeSinceStartupAsDouble;
        byte[] currentStates;
        bool captureCheckpoint = integrated && enablePressureShadowMatrix &&
                                 IsPressureShadowCheckpoint(integratedOrdinal, _frameConvergenceTargetFrames);
        CaptureTsdfStateSignature(
            true,
            out currentStates,
            out row.WeightedVoxels,
            out row.PositiveVoxels,
            out row.NegativeVoxels,
            out row.NearZeroVoxels,
            out row.StateHash,
            _frameConvergenceScratchStates);
        CompareFrameConvergenceStates(
            _frameConvergencePreviousStates, currentStates,
            out row.StateChangedVoxels,
            out row.SignChangedVoxels,
            out row.NearZeroChangedVoxels);
        row.WeightedDelta = row.WeightedVoxels - _frameConvergencePreviousWeightedVoxels;
        _frameConvergencePreviousWeightedVoxels = row.WeightedVoxels;

        if (captureCheckpoint && currentStates != null)
        {
            // Checkpoints survive until export.  Keep the two live scan buffers reusable so
            // per-frame diagnostics do not allocate a full voxel-state array every frame.
            byte[] checkpointStates = new byte[currentStates.Length];
            System.Buffer.BlockCopy(currentStates, 0, checkpointStates, 0, currentStates.Length);
            _pressureShadowCheckpoints.Add(new PressureShadowCheckpoint
            {
                FrameOrdinal = integratedOrdinal,
                RawFrameIndex = rawFrameIndex,
                VoxelStates = checkpointStates,
                ZeroCrossCells = BuildZeroCrossCellSet(checkpointStates),
                WeightedVoxels = row.WeightedVoxels,
                PositiveVoxels = row.PositiveVoxels,
                NegativeVoxels = row.NegativeVoxels,
                NearZeroVoxels = row.NearZeroVoxels,
                StateHash = row.StateHash,
                CumulativeIntegrationMilliseconds = _frameConvergenceCumulativeIntegrationMilliseconds,
                CumulativeAcceptedSamples = SumFrameConvergenceAcceptedSamples() + row.AcceptedSamples,
                CumulativeUpdatedVoxels = SumFrameConvergenceUpdatedVoxels() + row.UpdatedVoxels
            });
        }

        byte[] reusableStates = _frameConvergencePreviousStates;
        _frameConvergencePreviousStates = currentStates;
        _frameConvergenceScratchStates = reusableStates;

        row.DiagnosticMilliseconds =
            (float)((Time.realtimeSinceStartupAsDouble - diagnosticStart) * 1000.0);
        LastFrameConvergenceDiagnosticMilliseconds += row.DiagnosticMilliseconds;
        _frameConvergenceRows.Add(row);
        LastFrameConvergenceObservedFrameCount = _frameConvergenceRows.Count;
    }

    private void FinalizePressureShadowMatrix(int integratedFrames)
    {
        if (enableLowOverheadPerformanceMeasurement ||
            !enablePressureShadowMatrix || integratedFrames <= 0 ||
            _tsdf == null || _weights == null)
            return;
        PressureShadowCheckpoint final = FindPressureShadowCheckpoint(integratedFrames);
        if (final == null)
        {
            double diagnosticStart = Time.realtimeSinceStartupAsDouble;
            CaptureTsdfStateSignature(
                true, out byte[] states,
                out int weighted, out int positive, out int negative, out int nearZero,
                out ulong stateHash);
            final = new PressureShadowCheckpoint
            {
                FrameOrdinal = integratedFrames,
                RawFrameIndex = LastRawFrameIndex,
                VoxelStates = states,
                ZeroCrossCells = BuildZeroCrossCellSet(states),
                WeightedVoxels = weighted,
                PositiveVoxels = positive,
                NegativeVoxels = negative,
                NearZeroVoxels = nearZero,
                StateHash = stateHash,
                CumulativeIntegrationMilliseconds = _frameConvergenceCumulativeIntegrationMilliseconds,
                CumulativeAcceptedSamples = SumFrameConvergenceAcceptedSamples(),
                CumulativeUpdatedVoxels = SumFrameConvergenceUpdatedVoxels()
            };
            _pressureShadowCheckpoints.Add(final);
            LastFrameConvergenceDiagnosticMilliseconds +=
                (float)((Time.realtimeSinceStartupAsDouble - diagnosticStart) * 1000.0);
        }

        LastFrameConvergenceEarliestStableFrame = 0;
        for (int i = 0; i < _pressureShadowCheckpoints.Count; i++)
        {
            PressureShadowCheckpoint checkpoint = _pressureShadowCheckpoints[i];
            GetPressureShadowAgreement(
                checkpoint, final,
                out float weightedRecall, out _, out float signAgreement,
                out _, out float zeroCrossJaccard,
                out _, out _, out _, out _, out _, out _);
            if (weightedRecall >= pressureShadowWeightedCoverageThreshold &&
                signAgreement >= pressureShadowSignAgreementThreshold &&
                zeroCrossJaccard >= pressureShadowZeroCrossJaccardThreshold)
            {
                LastFrameConvergenceEarliestStableFrame = checkpoint.FrameOrdinal;
                break;
            }
        }
    }

    private bool IsPressureShadowCheckpoint(int frameOrdinal, int targetFrames)
    {
        return frameOrdinal == 4 || frameOrdinal == 6 || frameOrdinal == 8 ||
               frameOrdinal == 10 || frameOrdinal == 12 || frameOrdinal == targetFrames;
    }

    private void CaptureTsdfStateSignature(
        bool retainStates,
        out byte[] retainedStates,
        out int weighted,
        out int positive,
        out int negative,
        out int nearZero,
        out ulong stateHash,
        byte[] reusableStates = null)
    {
        retainedStates = retainStates && _weights != null
            ? reusableStates != null && reusableStates.Length == _weights.Length
                ? reusableStates
                : new byte[_weights.Length]
            : null;
        weighted = positive = negative = nearZero = 0;
        stateHash = 1469598103934665603UL;
        if (_tsdf == null || _weights == null)
            return;
        float nearZeroLimit = Mathf.Clamp(pressureShadowNearZeroTsdfThreshold, 0.05f, 0.5f);
        int count = Mathf.Min(_tsdf.Length, _weights.Length);
        for (int i = 0; i < count; i++)
        {
            byte weight = _weights[i];
            byte state = 0;
            int quantizedTsdf = 0;
            if (weight > 0 && !float.IsNaN(_tsdf[i]) && !float.IsInfinity(_tsdf[i]))
            {
                weighted++;
                state = 1;
                if (_tsdf[i] < 0f)
                {
                    negative++;
                    state |= 2;
                }
                else
                    positive++;
                if (Mathf.Abs(_tsdf[i]) <= nearZeroLimit)
                {
                    nearZero++;
                    state |= 4;
                }
                quantizedTsdf = Mathf.RoundToInt(Mathf.Clamp(_tsdf[i], -1f, 1f) * 32767f);
            }
            if (retainedStates != null)
                retainedStates[i] = state;
            unchecked
            {
                stateHash ^= (ulong)(state | (weight << 8));
                stateHash *= 1099511628211UL;
                stateHash ^= (ulong)(uint)quantizedTsdf;
                stateHash *= 1099511628211UL;
            }
        }
    }

    private HashSet<int> BuildZeroCrossCellSet(byte[] states)
    {
        HashSet<int> cells = new HashSet<int>();
        if (states == null || _dimX < 2 || _dimY < 2 || _dimZ < 2)
            return cells;
        int cellX = _dimX - 1;
        int cellY = _dimY - 1;
        for (int z = 0; z < _dimZ - 1; z++)
        for (int y = 0; y < _dimY - 1; y++)
        for (int x = 0; x < _dimX - 1; x++)
        {
            bool hasPositive = false;
            bool hasNegative = false;
            for (int corner = 0; corner < 8; corner++)
            {
                byte state = states[Index(
                    x + CornerOffsetX[corner],
                    y + CornerOffsetY[corner],
                    z + CornerOffsetZ[corner])];
                if ((state & 1) == 0)
                    continue;
                if ((state & 2) != 0)
                    hasNegative = true;
                else
                    hasPositive = true;
            }
            if (hasPositive && hasNegative)
                cells.Add(x + cellX * (y + cellY * z));
        }
        return cells;
    }

    private PressureShadowCheckpoint FindPressureShadowCheckpoint(int frameOrdinal)
    {
        for (int i = 0; i < _pressureShadowCheckpoints.Count; i++)
            if (_pressureShadowCheckpoints[i].FrameOrdinal == frameOrdinal)
                return _pressureShadowCheckpoints[i];
        return null;
    }

    private int SumFrameConvergenceAcceptedSamples()
    {
        int total = 0;
        for (int i = 0; i < _frameConvergenceRows.Count; i++)
            total += _frameConvergenceRows[i].AcceptedSamples;
        return total;
    }

    private int SumFrameConvergenceUpdatedVoxels()
    {
        int total = 0;
        for (int i = 0; i < _frameConvergenceRows.Count; i++)
            total += _frameConvergenceRows[i].UpdatedVoxels;
        return total;
    }

    private static void CompareFrameConvergenceStates(
        byte[] previous,
        byte[] current,
        out int stateChanged,
        out int signChanged,
        out int nearZeroChanged)
    {
        stateChanged = signChanged = nearZeroChanged = 0;
        if (previous == null || current == null)
            return;
        int count = Mathf.Min(previous.Length, current.Length);
        for (int i = 0; i < count; i++)
        {
            byte before = previous[i];
            byte after = current[i];
            if (before != after)
                stateChanged++;
            bool beforeWeighted = (before & 1) != 0;
            bool afterWeighted = (after & 1) != 0;
            if (beforeWeighted && afterWeighted && (before & 2) != (after & 2))
                signChanged++;
            if ((before & 4) != (after & 4))
                nearZeroChanged++;
        }
        stateChanged += Mathf.Abs(previous.Length - current.Length);
    }

    private void ReleasePressureShadowSnapshots()
    {
        for (int i = 0; i < _pressureShadowCheckpoints.Count; i++)
        {
            _pressureShadowCheckpoints[i].VoxelStates = null;
            _pressureShadowCheckpoints[i].ZeroCrossCells = null;
        }
        _pressureShadowCheckpoints.Clear();
        _frameConvergencePreviousStates = null;
        _frameConvergenceScratchStates = null;
    }

    private StringBuilder BuildFrameConvergenceCsv()
    {
        StringBuilder csv = new StringBuilder(4096);
        csv.AppendLine("schema,batch_target,attempt_ordinal,integrated_ordinal,raw_frame_index,integrated,integration_ms,reference_classic_integration_ms,diagnostic_ms,input_samples,accepted_samples,updated_voxels,weighted_voxels,weighted_delta,positive_voxels,negative_voxels,near_zero_voxels,state_changed_voxels,sign_changed_voxels,near_zero_changed_voxels,state_hash");
        for (int i = 0; i < _frameConvergenceRows.Count; i++)
        {
            FrameConvergenceRow row = _frameConvergenceRows[i];
            csv.Append("frame_convergence_v1,").Append(_frameConvergenceTargetFrames).Append(',')
                .Append(row.AttemptOrdinal).Append(',').Append(row.IntegratedOrdinal).Append(',')
                .Append(row.RawFrameIndex).Append(',').Append(row.Integrated ? 1 : 0).Append(',')
                .Append(row.IntegrationMilliseconds.ToString("F3", CultureInfo.InvariantCulture)).Append(',')
                .Append(row.ReferenceClassicIntegrationMilliseconds.ToString("F3", CultureInfo.InvariantCulture)).Append(',')
                .Append(row.DiagnosticMilliseconds.ToString("F3", CultureInfo.InvariantCulture)).Append(',')
                .Append(row.InputSamples).Append(',').Append(row.AcceptedSamples).Append(',')
                .Append(row.UpdatedVoxels).Append(',').Append(row.WeightedVoxels).Append(',')
                .Append(row.WeightedDelta).Append(',').Append(row.PositiveVoxels).Append(',')
                .Append(row.NegativeVoxels).Append(',').Append(row.NearZeroVoxels).Append(',')
                .Append(row.StateChangedVoxels).Append(',').Append(row.SignChangedVoxels).Append(',')
                .Append(row.NearZeroChangedVoxels).Append(',')
                .Append(row.StateHash.ToString("X16", CultureInfo.InvariantCulture)).AppendLine();
        }
        return csv;
    }

    private StringBuilder BuildPressureShadowMatrixCsv()
    {
        StringBuilder csv = new StringBuilder(4096);
        csv.AppendLine("schema,read_only,checkpoint_frame,final_frame,raw_frame_index,weighted_checkpoint,weighted_final,weighted_intersection,checkpoint_only,final_only,weighted_recall,weighted_precision,sign_agreement,near_zero_jaccard,zero_cross_checkpoint,zero_cross_final,zero_cross_intersection,zero_cross_union,zero_cross_jaccard,cumulative_integration_ms,estimated_saved_integration_ms,estimated_saved_percent,cumulative_accepted_samples,cumulative_updated_voxels,state_hash,stable_by_thresholds");
        if (_pressureShadowCheckpoints.Count == 0)
            return csv;
        PressureShadowCheckpoint final = _pressureShadowCheckpoints[_pressureShadowCheckpoints.Count - 1];
        for (int i = 0; i < _pressureShadowCheckpoints.Count; i++)
        {
            PressureShadowCheckpoint checkpoint = _pressureShadowCheckpoints[i];
            GetPressureShadowAgreement(
                checkpoint, final,
                out float weightedRecall, out float weightedPrecision, out float signAgreement,
                out float nearZeroJaccard, out float zeroCrossJaccard,
                out int weightedIntersection, out int checkpointOnly, out int finalOnly,
                out int zeroIntersection, out int zeroUnion, out int nearZeroUnion);
            bool stable = weightedRecall >= pressureShadowWeightedCoverageThreshold &&
                          signAgreement >= pressureShadowSignAgreementThreshold &&
                          zeroCrossJaccard >= pressureShadowZeroCrossJaccardThreshold;
            float savedMilliseconds = Mathf.Max(0f,
                final.CumulativeIntegrationMilliseconds - checkpoint.CumulativeIntegrationMilliseconds);
            float savedPercent = final.CumulativeIntegrationMilliseconds > 0f
                ? savedMilliseconds / final.CumulativeIntegrationMilliseconds * 100f : 0f;
            csv.Append("pressure_shadow_v1,1,").Append(checkpoint.FrameOrdinal).Append(',')
                .Append(final.FrameOrdinal).Append(',').Append(checkpoint.RawFrameIndex).Append(',')
                .Append(checkpoint.WeightedVoxels).Append(',').Append(final.WeightedVoxels).Append(',')
                .Append(weightedIntersection).Append(',').Append(checkpointOnly).Append(',')
                .Append(finalOnly).Append(',')
                .Append(weightedRecall.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(weightedPrecision.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(signAgreement.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(nearZeroJaccard.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(checkpoint.ZeroCrossCells != null ? checkpoint.ZeroCrossCells.Count : 0).Append(',')
                .Append(final.ZeroCrossCells != null ? final.ZeroCrossCells.Count : 0).Append(',')
                .Append(zeroIntersection).Append(',').Append(zeroUnion).Append(',')
                .Append(zeroCrossJaccard.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(checkpoint.CumulativeIntegrationMilliseconds.ToString("F3", CultureInfo.InvariantCulture)).Append(',')
                .Append(savedMilliseconds.ToString("F3", CultureInfo.InvariantCulture)).Append(',')
                .Append(savedPercent.ToString("F3", CultureInfo.InvariantCulture)).Append(',')
                .Append(checkpoint.CumulativeAcceptedSamples).Append(',')
                .Append(checkpoint.CumulativeUpdatedVoxels).Append(',')
                .Append(checkpoint.StateHash.ToString("X16", CultureInfo.InvariantCulture)).Append(',')
                .Append(stable ? 1 : 0).AppendLine();
        }
        return csv;
    }

    private void GetPressureShadowAgreement(
        PressureShadowCheckpoint checkpoint,
        PressureShadowCheckpoint final,
        out float weightedRecall,
        out float weightedPrecision,
        out float signAgreement,
        out float nearZeroJaccard,
        out float zeroCrossJaccard,
        out int weightedIntersection,
        out int checkpointOnly,
        out int finalOnly,
        out int zeroIntersection,
        out int zeroUnion,
        out int nearZeroUnion)
    {
        weightedIntersection = checkpointOnly = finalOnly = zeroIntersection = zeroUnion = nearZeroUnion = 0;
        int signMatches = 0;
        int nearZeroIntersection = 0;
        byte[] a = checkpoint.VoxelStates;
        byte[] b = final.VoxelStates;
        int count = a != null && b != null ? Mathf.Min(a.Length, b.Length) : 0;
        for (int i = 0; i < count; i++)
        {
            bool weightedA = (a[i] & 1) != 0;
            bool weightedB = (b[i] & 1) != 0;
            if (weightedA && weightedB)
            {
                weightedIntersection++;
                if ((a[i] & 2) == (b[i] & 2))
                    signMatches++;
            }
            else if (weightedA)
                checkpointOnly++;
            else if (weightedB)
                finalOnly++;
            bool nearA = (a[i] & 4) != 0;
            bool nearB = (b[i] & 4) != 0;
            if (nearA || nearB)
                nearZeroUnion++;
            if (nearA && nearB)
                nearZeroIntersection++;
        }
        weightedRecall = final.WeightedVoxels > 0
            ? (float)weightedIntersection / final.WeightedVoxels : 1f;
        weightedPrecision = checkpoint.WeightedVoxels > 0
            ? (float)weightedIntersection / checkpoint.WeightedVoxels : 1f;
        signAgreement = weightedIntersection > 0
            ? (float)signMatches / weightedIntersection : 1f;
        nearZeroJaccard = nearZeroUnion > 0
            ? (float)nearZeroIntersection / nearZeroUnion : 1f;

        HashSet<int> zeroA = checkpoint.ZeroCrossCells;
        HashSet<int> zeroB = final.ZeroCrossCells;
        if (zeroA != null && zeroB != null)
        {
            HashSet<int> smaller = zeroA.Count <= zeroB.Count ? zeroA : zeroB;
            HashSet<int> larger = zeroA.Count <= zeroB.Count ? zeroB : zeroA;
            foreach (int cell in smaller)
                if (larger.Contains(cell))
                    zeroIntersection++;
            zeroUnion = zeroA.Count + zeroB.Count - zeroIntersection;
        }
        zeroCrossJaccard = zeroUnion > 0 ? (float)zeroIntersection / zeroUnion : 1f;
    }

    private void IntegrateReferenceClassicSnapshot(
        ScanCoverDepthGridPointCloud.RawDepthFrameSnapshot snapshot,
        Vector3[] positions,
        Vector3[] normals,
        Color[] meta,
        int width,
        int height)
    {
        if (!enableReferenceClassicTsdf)
            return;

        if (!_referenceClassicTsdf.IsCompatible(_dimX, _dimY, _dimZ, _volumeOriginWorld, voxelSizeMeters))
            _referenceClassicTsdf.Reset(_dimX, _dimY, _dimZ, _volumeOriginWorld, voxelSizeMeters);

        Vector3 captureCamera = snapshot.hasSnapshotCameraPose
            ? snapshot.snapshotCameraPosition
            : GetCameraPosition();
        _referenceClassicTsdf.IntegrateFrame(
            positions, normals, meta, width, height, Mathf.Max(1, sampleStridePixels), captureCamera,
            minDepthMeters, maxDepthMeters, truncationMeters,
            referenceClassicMaxVoxelWeight,
            referenceClassicMinimumAngleWeight,
            referenceClassicMinimumDistanceWeight);
        LastReferenceClassicInputSampleCount = _referenceClassicTsdf.LastInputSamples;
        LastReferenceClassicValidSampleCount = _referenceClassicTsdf.LastValidSamples;
        LastReferenceClassicGrazingSampleCount = _referenceClassicTsdf.LastGrazingSamples;
        LastReferenceClassicBandWriteCount = _referenceClassicTsdf.LastBandVoxelWrites;
        LastReferenceClassicMeanObservationWeight = _referenceClassicTsdf.LastMeanObservationWeight;
    }

    private bool IntegrateSnapshot(ScanCoverDepthGridPointCloud.RawDepthFrameSnapshot snapshot)
    {
        double integrationWallStart = Time.realtimeSinceStartupAsDouble;
        IEnumerator routine = IntegrateSnapshotBudgetedRoutine(snapshot, false);
        while (routine.MoveNext())
        {
        }
        LastBudgetedFusionWallMilliseconds =
            (float)((Time.realtimeSinceStartupAsDouble - integrationWallStart) * 1000.0);
        return _budgetedSnapshotIntegratedResult;
    }

    private IEnumerator IntegrateSnapshotBudgetedRoutine(
        ScanCoverDepthGridPointCloud.RawDepthFrameSnapshot snapshot,
        bool allowYields)
    {
        _budgetedSnapshotIntegratedResult = false;
        LastBudgetedFusionYieldCount = 0;
        LastBudgetedFusionComputeMilliseconds = 0f;
        LastBudgetedFusionWallMilliseconds = 0f;
        LastBudgetedFusionMaxSliceMilliseconds = 0f;
        LastBudgetedFusionUniqueSurfaceVoxelWriteCount = 0;
        LastBudgetedFusionMergedSurfaceVoxelWriteCount = 0;
        LastReferenceClassicPausedForPerformance = false;
        _budgetedFusionSurfaceVoxelWrites.Clear();
        _budgetedFusionRepresentativeBySurfaceVoxel.Clear();
        _budgetedFusionRawHitsBySurfaceVoxel.Clear();
        _budgetedFusionRepresentativeScoreBySurfaceVoxel.Clear();
        double completedComputeSeconds = 0d;
        double computeSliceStart = Time.realtimeSinceStartupAsDouble;

        if (snapshot == null ||
            snapshot.worldPositions == null ||
            snapshot.worldPositions.Length <= 0 ||
            snapshot.resolutionWidth <= 1 ||
            snapshot.resolutionHeight <= 1)
        {
            _budgetedSnapshotIntegratedResult = Warn("Raw depth snapshot is empty.");
            LastBudgetedFusionComputeMilliseconds =
                (float)((Time.realtimeSinceStartupAsDouble - computeSliceStart) * 1000.0);
            yield break;
        }

        EnsureVolumeInitialized();
        BeginFastFusionDecisionJournal(snapshot.frameIndex);

        Vector3 cameraPosition = GetCameraPosition();
        _rawCoverageCaptureCameraPosition = snapshot.hasSnapshotCameraPose
            ? snapshot.snapshotCameraPosition
            : cameraPosition;
        _rawCoverageCaptureCameraValid = true;
        double integrationRealtime = Time.realtimeSinceStartupAsDouble;
        float posePositionDelta = snapshot.hasSnapshotCameraPose
            ? Vector3.Distance(snapshot.snapshotCameraPosition, cameraPosition)
            : -1f;
        Quaternion integrationRotation = Camera.main != null ? Camera.main.transform.rotation : Quaternion.identity;
        float poseAngleDelta = snapshot.hasSnapshotCameraPose
            ? Quaternion.Angle(snapshot.snapshotCameraRotation, integrationRotation)
            : -1f;
        float snapshotLatencyMs = snapshot.snapshotRealtimeSeconds > 0d
            ? (float)((integrationRealtime - snapshot.snapshotRealtimeSeconds) * 1000d)
            : -1f;
        ResetFrameReferenceAudit();
        Vector3[] positions = snapshot.worldPositions;
        Vector3[] normals = snapshot.worldNormals;
        Color[] meta = snapshot.observationMeta;
        int width = snapshot.resolutionWidth;
        int height = snapshot.resolutionHeight;
        int expected = Mathf.Min(width * height, positions.Length);
        LastReferenceClassicPausedForPerformance =
            enableLowOverheadPerformanceMeasurement &&
            pauseReferenceClassicDuringLowOverheadMeasurement;
        if (LastReferenceClassicPausedForPerformance)
        {
            LastReferenceClassicIntegrationMilliseconds = 0f;
        }
        else
        {
            double referenceClassicIntegrationStart = Time.realtimeSinceStartupAsDouble;
            IntegrateReferenceClassicSnapshot(snapshot, positions, normals, meta, width, height);
            LastReferenceClassicIntegrationMilliseconds =
                (float)((Time.realtimeSinceStartupAsDouble - referenceClassicIntegrationStart) * 1000.0);
        }
        BeginVoteHistoryFrame();
        int stride = Mathf.Max(1, sampleStridePixels);
        int halfBandSteps = Mathf.Max(1, Mathf.CeilToInt(truncationMeters / voxelSizeMeters));
        int workItemsInSlice = 0;
        double budgetMilliseconds = Mathf.Max(0.25f, fusionWorkBudgetMillisecondsPerRenderFrame);

        LastRawFrameIndex = snapshot.frameIndex;
        LastInputSampleCount = 0;
        LastIntegratedSampleCount = 0;
        LastUpdatedVoxelCount = 0;
        LastNeighborFilledSampleCount = 0;
        ResetRejectCounters();

        if (mergeSameFrameSurfaceVoxelWrites &&
            selectSurfaceVoxelRepresentativeBeforeHeavyFusion)
        {
            float inverseVoxelSizeSquared =
                1f / Mathf.Max(0.000001f, voxelSizeMeters * voxelSizeMeters);
            for (int preY = 0; preY < height; preY += stride)
            {
                for (int preX = 0; preX < width; preX += stride)
                {
                    if (allowYields &&
                        enableBudgetedFusionWorkQueue &&
                        workItemsInSlice > 0)
                    {
                        double budgetCheck = Time.realtimeSinceStartupAsDouble;
                        if ((budgetCheck - computeSliceStart) * 1000.0 >= budgetMilliseconds)
                        {
                            double completedSliceSeconds = budgetCheck - computeSliceStart;
                            completedComputeSeconds += completedSliceSeconds;
                            LastBudgetedFusionMaxSliceMilliseconds = Mathf.Max(
                                LastBudgetedFusionMaxSliceMilliseconds,
                                (float)(completedSliceSeconds * 1000.0));
                            LastBudgetedFusionYieldCount++;
                            yield return null;
                            computeSliceStart = Time.realtimeSinceStartupAsDouble;
                            workItemsInSlice = 0;
                        }
                    }
                    workItemsInSlice++;

                    int preIndex = preY * width + preX;
                    if (preIndex < 0 || preIndex >= expected)
                        continue;
                    if (!TryGetUsableSampleNoRejectCount(
                            preIndex, positions, normals, meta, cameraPosition,
                            out Vector3 representativePoint,
                            out Vector3 representativeNormal,
                            out float representativeWeight))
                        continue;
                    if (!TryWorldToVoxel(
                            representativePoint,
                            out int representativeVx,
                            out int representativeVy,
                            out int representativeVz))
                        continue;

                    int representativeVoxelIndex =
                        Index(representativeVx, representativeVy, representativeVz);
                    _budgetedFusionRawHitsBySurfaceVoxel.TryGetValue(
                        representativeVoxelIndex, out int rawHits);
                    _budgetedFusionRawHitsBySurfaceVoxel[representativeVoxelIndex] = rawHits + 1;

                    float centerDistanceScore =
                        (representativePoint -
                         VoxelCenter(representativeVx, representativeVy, representativeVz)).sqrMagnitude *
                        inverseVoxelSizeSquared;
                    float facingScore = representativeNormal.sqrMagnitude > 0.0001f
                        ? Mathf.Abs(Vector3.Dot(
                            representativeNormal.normalized,
                            (cameraPosition - representativePoint).normalized))
                        : 0f;
                    float representativeScore =
                        representativeWeight * 4f + facingScore - centerDistanceScore;
                    if (!_budgetedFusionRepresentativeScoreBySurfaceVoxel.TryGetValue(
                            representativeVoxelIndex, out float previousScore) ||
                        representativeScore > previousScore)
                    {
                        _budgetedFusionRepresentativeScoreBySurfaceVoxel[representativeVoxelIndex] =
                            representativeScore;
                        _budgetedFusionRepresentativeBySurfaceVoxel[representativeVoxelIndex] =
                            preIndex;
                    }
                }
            }
        }

        for (int y = 0; y < height; y += stride)
        {
            for (int x = 0; x < width; x += stride)
            {
                if (allowYields &&
                    enableBudgetedFusionWorkQueue &&
                    workItemsInSlice > 0)
                {
                    double budgetCheck = Time.realtimeSinceStartupAsDouble;
                    if ((budgetCheck - computeSliceStart) * 1000.0 >= budgetMilliseconds)
                    {
                        double completedSliceSeconds = budgetCheck - computeSliceStart;
                        completedComputeSeconds += completedSliceSeconds;
                        LastBudgetedFusionMaxSliceMilliseconds = Mathf.Max(
                            LastBudgetedFusionMaxSliceMilliseconds,
                            (float)(completedSliceSeconds * 1000.0));
                        LastBudgetedFusionYieldCount++;
                        yield return null;
                        computeSliceStart = Time.realtimeSinceStartupAsDouble;
                        workItemsInSlice = 0;
                    }
                }
                workItemsInSlice++;

                int index = y * width + x;
                if (index < 0 || index >= expected)
                    continue;

                LastInputSampleCount++;
                _activeLedgerSampleIndex = index;
                _activeLedgerPixelX = x;
                _activeLedgerPixelY = y;
                bool auditThisSample = ShouldAuditSample(index);
                BeginConfidenceAuditSample(auditThisSample);
                Vector3 rawPoint = positions[index];
                int mergedRawSampleMultiplicity = 1;
                if (mergeSameFrameSurfaceVoxelWrites &&
                    selectSurfaceVoxelRepresentativeBeforeHeavyFusion &&
                    Finite(rawPoint) &&
                    TryWorldToVoxel(rawPoint, out int rawVx, out int rawVy, out int rawVz))
                {
                    int rawVoxelIndex = Index(rawVx, rawVy, rawVz);
                    if (_budgetedFusionRepresentativeBySurfaceVoxel.TryGetValue(
                            rawVoxelIndex, out int representativeIndex))
                    {
                        if (representativeIndex != index)
                        {
                            LastBudgetedFusionMergedSurfaceVoxelWriteCount++;
                            AppendConfidenceAuditRow(
                                snapshot.frameIndex, index, x, y, rawPoint, 0f,
                                0, 0, 0f, 0f, 0, 0,
                                "merge", "early_surface_voxel_representative_merge",
                                auditThisSample);
                            continue;
                        }
                        if (_budgetedFusionRawHitsBySurfaceVoxel.TryGetValue(
                                rawVoxelIndex, out int rawHits))
                            mergedRawSampleMultiplicity = Mathf.Max(1, rawHits);
                    }
                }

                if (!TryGetUsableSampleOrNeighbor(x, y, width, height, positions, normals, meta, cameraPosition, out Vector3 point, out Vector3 normal, out float sampleWeight))
                {
                    SetObservationVote(ObservationVoteState.Reject, 0f, "invalid_or_basic_filter");
                    RecordRawCoverageGridSample(positions[index], RawDepthDebugKind.Rejected, false, RawCoverageDecisionStage.BasicFilter);
                    CacheRawDepthDebugSample(positions[index], RawDepthDebugKind.Rejected);
                    AppendConfidenceAuditRow(snapshot.frameIndex, index, x, y, rawPoint, 0f, 0, 0, 0f, 0f, 0, 0, "discard", "invalid_or_basic_filter", auditThisSample);
                    continue;
                }

                _auditSampleNormal = normal.sqrMagnitude > 0.0001f ? normal.normalized : Vector3.zero;
                Vector3 initialAuditViewDirection = (cameraPosition - point).normalized;
                _auditSampleViewFacing = _auditSampleNormal.sqrMagnitude > 0.0001f
                    ? Mathf.Abs(Vector3.Dot(_auditSampleNormal, initialAuditViewDirection))
                    : -1f;

                if (!PassDepthNeighborhoodConsistency(x, y, width, height, positions, normals, cameraPosition, point, normal, out int checkedDepthNeighbors, out int consistentDepthNeighbors))
                {
                    SetObservationVote(ObservationVoteState.Reject, 0.05f, "depth_discontinuity");
                    LastRejectedDepthDiscontinuityCount++;
                    RecordRawCoverageGridSample(point, RawDepthDebugKind.DepthEdge, false, RawCoverageDecisionStage.DepthNeighborhood);
                    CacheRawDepthDebugSample(point, RawDepthDebugKind.DepthEdge);
                    AppendConfidenceAuditRow(snapshot.frameIndex, index, x, y, point, sampleWeight, checkedDepthNeighbors, consistentDepthNeighbors, 0f, 0f, 0, 0, "discard", "depth_discontinuity", auditThisSample);
                    continue;
                }

                Vector3 pointBeforeRobust = point;
                if (!ApplyRobustDepthPrefilter(x, y, width, height, positions, normals, cameraPosition, normal, ref point, ref sampleWeight))
                {
                    SetObservationVote(ObservationVoteState.Reject, 0.10f, "robust_depth_outlier");
                    LastRejectedRobustDepthCount++;
                    RecordRawCoverageGridSample(point, RawDepthDebugKind.Robust, false, RawCoverageDecisionStage.RobustPrefilter);
                    CacheRawDepthDebugSample(point, RawDepthDebugKind.Robust);
                    AppendConfidenceAuditRow(snapshot.frameIndex, index, x, y, point, sampleWeight, checkedDepthNeighbors, consistentDepthNeighbors, Vector3.Distance(pointBeforeRobust, point), 0f, 0, 0, "discard", "robust_depth_outlier", auditThisSample);
                    continue;
                }
                _auditSampleSupportRatio = checkedDepthNeighbors > 0 ? (float)consistentDepthNeighbors / checkedDepthNeighbors : 0f;
                _auditSampleRobustShiftMeters = Vector3.Distance(pointBeforeRobust, point);
                Vector3 auditViewDirection = (cameraPosition - point).normalized;
                _auditSampleViewFacing = normal.sqrMagnitude > 0.0001f
                    ? Mathf.Abs(Vector3.Dot(normal.normalized, auditViewDirection))
                    : 0f;
                _auditSampleNormal = normal.sqrMagnitude > 0.0001f ? normal.normalized : Vector3.zero;
                MeasureTemporalVoteFeatures(cameraPosition, point, _auditSampleNormal);
                MeasureHistoricalTsdfVoteFeatures(point);
                MeasureTsdfBandVoteFeatures(cameraPosition, point, _auditSampleNormal, halfBandSteps);
                MeasureCrossFrameCleanSurfaceConflict(point, _auditSampleNormal);
                RecordCurrentFrameRawVoteSample(point, _auditSampleNormal);
                MarkSurfaceObservationState(point, 1);

                if (!PassTsdfDepthSupport(checkedDepthNeighbors, consistentDepthNeighbors))
                {
                    SetObservationVote(ObservationVoteState.Reject, 0.15f, "insufficient_depth_support");
                    LastRejectedTsdfDepthSupportCount++;
                    RecordRawCoverageGridSample(point, RawDepthDebugKind.Support, false, RawCoverageDecisionStage.TsdfSupport);
                    CacheRawDepthDebugSample(point, RawDepthDebugKind.Support);
                    AppendConfidenceAuditRow(snapshot.frameIndex, index, x, y, point, sampleWeight, checkedDepthNeighbors, consistentDepthNeighbors, Vector3.Distance(pointBeforeRobust, point), 0f, 0, 0, "discard", "insufficient_depth_support", auditThisSample);
                    continue;
                }
                ObservationVoteState observationVote = EvaluateObservationVote(sampleWeight);
                if (observationVote == ObservationVoteState.Accept &&
                    WouldAtomicAcceptCreateDuplicateLayer(point, _auditSampleNormal))
                {
                    observationVote = ObservationVoteState.Pending;
                    LastAtomicAcceptDuplicateDowngradeCount++;
                    DowngradeCurrentObservationVoteToPending("duplicate_layer_guard");
                }
                if (observationVote == ObservationVoteState.Accept && gateFormalAcceptByStableSignCompatibility)
                {
                    ShadowAcceptCompatibilityInfo compatibility = ClassifyFormalAcceptCompatibility(
                        cameraPosition, point, normal, halfBandSteps);
                    LastFormalAcceptCompatibilityCheckedCount++;
                    if (compatibility.CriticalConflictVoxels > 0)
                        LastFormalAcceptCompatibilityCriticalConflictCount++;
                    switch (compatibility.Compatibility)
                    {
                        case ShadowAcceptCompatibility.Aligned:
                            LastFormalAcceptCompatibilityAlignedCount++;
                            break;
                        case ShadowAcceptCompatibility.NewSpace:
                            LastFormalAcceptCompatibilityNewSpaceCount++;
                            break;
                        case ShadowAcceptCompatibility.Mixed:
                            if (compatibility.ConflictRatio > Mathf.Clamp(formalAcceptMixedConflictPendingThreshold, 0.5f, 0.9f))
                            {
                                observationVote = ObservationVoteState.Pending;
                                LastFormalAcceptCompatibilityMixedDowngradedCount++;
                                DowngradeCurrentObservationVoteToPending("formal_accept_mixed_conflict_gate");
                                break;
                            }
                            if (gateFormalMixedBySequentialTopology)
                            {
                                LastFormalMixedTopologyCheckedCount++;
                                if (WouldFormalMixedObservationDestroyZeroCross(
                                        cameraPosition, point, normal, sampleWeight, halfBandSteps,
                                        out int destroyedZeroCells))
                                {
                                    observationVote = ObservationVoteState.Pending;
                                    LastFormalMixedTopologyDowngradedCount++;
                                    LastFormalMixedTopologyProtectedZeroCrossCellCount += destroyedZeroCells;
                                    DowngradeCurrentObservationVoteToPending("formal_accept_mixed_topology_gate");
                                    break;
                                }
                            }
                            if (compatibility.ConflictRatio <= 0.25f)
                                LastFormalAcceptCompatibilityMixedLowCount++;
                            else
                                LastFormalAcceptCompatibilityMixedObserveCount++;
                            break;
                        case ShadowAcceptCompatibility.Conflict:
                            observationVote = ObservationVoteState.Pending;
                            LastFormalAcceptCompatibilityConflictDowngradedCount++;
                            DowngradeCurrentObservationVoteToPending("formal_accept_sign_conflict_gate");
                            break;
                    }
                }
                MarkSurfaceObservationState(point, observationVote == ObservationVoteState.Accept ? (byte)3 : observationVote == ObservationVoteState.Pending ? (byte)2 : (byte)4);
                if (observationVote == ObservationVoteState.Accept)
                    RecordMergedVoteHistorySample(
                        point, _auditSampleNormal, mergedRawSampleMultiplicity);
                if (observationVote == ObservationVoteState.Reject &&
                    (useAtomicObservationTsdfBands || enforceObservationWriteGate || observationVoteMode == ObservationVoteMode.RejectOnly))
                {
                    RecordShadowBlockObservation(cameraPosition, point, normal, sampleWeight, halfBandSteps, observationVote, false);
                    MarkRejectedObservationBand(cameraPosition, point, normal, halfBandSteps);
                    TryMetabolizeOldCleanTsdfBand(cameraPosition, point, sampleWeight, halfBandSteps);
                    RecordRawCoverageGridSample(point, RawDepthDebugKind.Rejected, false, RawCoverageDecisionStage.VoteReject);
                    CacheRawDepthDebugSample(point, RawDepthDebugKind.Rejected);
                    AppendConfidenceAuditRow(snapshot.frameIndex, index, x, y, point, sampleWeight, checkedDepthNeighbors, consistentDepthNeighbors, Vector3.Distance(pointBeforeRobust, point), 0f, 0, 0, "discard", "vote_reject", auditThisSample);
                    continue;
                }
                if (!useAtomicObservationTsdfBands &&
                    observationVote == ObservationVoteState.Pending &&
                    enforceObservationWriteGate &&
                    holdUnconfirmedPendingWrites)
                {
                    if (!PendingObservationHasWriteSupport(sampleWeight, out bool bootstrapWrite, out bool sameFrameProvisionalWrite, out bool strongSampleSeedWrite))
                    {
                        LastVotePendingHoldCount++;
                        if (HasSameFrameEntryConflict())
                            LastSameFrameEntryHeldCount++;
                        RecordRawCoverageGridSample(point, RawDepthDebugKind.Pending, false, RawCoverageDecisionStage.PendingHold);
                        CacheRawDepthDebugSample(point, RawDepthDebugKind.Rejected);
                        AppendConfidenceAuditRow(snapshot.frameIndex, index, x, y, point, sampleWeight, checkedDepthNeighbors, consistentDepthNeighbors, Vector3.Distance(pointBeforeRobust, point), 0f, 0, 0, "hold", "vote_pending_hold", auditThisSample);
                        continue;
                    }
                    if (strongSampleSeedWrite)
                    {
                        _auditStrongSampleSeedWrite = true;
                        sampleWeight *= Mathf.Clamp(strongSampleSeedWeightScale, 0.05f, 0.5f);
                        LastStrongSampleSeedWriteCount++;
                        if (bootstrapWrite)
                            LastVotePendingBootstrapWriteCount++;
                    }
                    else if (sameFrameProvisionalWrite)
                    {
                        sampleWeight *= Mathf.Clamp(sameFrameEntryProvisionalWeightScale, 0.05f, 0.6f);
                        LastSameFrameEntryProvisionalWriteCount++;
                    }
                    else if (bootstrapWrite)
                    {
                        sampleWeight *= Mathf.Clamp(pendingBootstrapWeightScale, 0.05f, 0.5f);
                        LastVotePendingBootstrapWriteCount++;
                    }
                    else
                    {
                        sampleWeight *= Mathf.Clamp(confirmedPendingWriteWeightScale, 0.05f, 1f);
                        LastVotePendingConfirmedWriteCount++;
                    }
                    RecordMergedVoteHistorySample(
                        point, _auditSampleNormal, mergedRawSampleMultiplicity);
                }
                else if (useAtomicObservationTsdfBands && observationVote == ObservationVoteState.Pending)
                {
                    sampleWeight *= Mathf.Clamp(atomicProvisionalBandWeightScale, 0.05f, 0.5f);
                    RecordMergedVoteHistorySample(
                        point, _auditSampleNormal, mergedRawSampleMultiplicity);
                }
                AccumulateFrameReferenceAudit(point);
                if (mergedRawSampleMultiplicity > 1)
                {
                    float mergedWeightScale = Mathf.Min(
                        Mathf.Max(1f, maximumMergedSurfaceVoxelWeightScale),
                        Mathf.Sqrt(mergedRawSampleMultiplicity));
                    sampleWeight *= mergedWeightScale;
                }

                int mergedVx = 0;
                int mergedVy = 0;
                int mergedVz = 0;
                bool hasSurfaceVoxelWriteKey =
                    mergeSameFrameSurfaceVoxelWrites &&
                    TryWorldToVoxel(point, out mergedVx, out mergedVy, out mergedVz);
                int mergedVoxelIndex = hasSurfaceVoxelWriteKey
                    ? Index(mergedVx, mergedVy, mergedVz)
                    : -1;
                if (hasSurfaceVoxelWriteKey &&
                    _budgetedFusionSurfaceVoxelWrites.Contains(mergedVoxelIndex))
                {
                    LastBudgetedFusionMergedSurfaceVoxelWriteCount++;
                    AppendConfidenceAuditRow(
                        snapshot.frameIndex, index, x, y, point, sampleWeight,
                        checkedDepthNeighbors, consistentDepthNeighbors,
                        Vector3.Distance(pointBeforeRobust, point), 0f, 0, 0,
                        "merge", "same_frame_surface_voxel_write_merged", auditThisSample);
                    continue;
                }

                float oldTsdfAtSurface = 0f;
                int oldWeightAtSurface = 0;
                int oldPendingHitsAtSurface = 0;
                if (TryWorldToVoxel(point, out int auditVx, out int auditVy, out int auditVz))
                {
                    int auditVoxelIndex = Index(auditVx, auditVy, auditVz);
                    oldTsdfAtSurface = _tsdf[auditVoxelIndex];
                    oldWeightAtSurface = _weights[auditVoxelIndex];
                    if (_correctionTsdfHits != null && auditVoxelIndex >= 0 && auditVoxelIndex < _correctionTsdfHits.Length)
                        oldPendingHitsAtSurface = _correctionTsdfHits[auditVoxelIndex];
                }
                int dirtyReplaceBeforeSample = LastReplacedDirtyTsdfCount;
                int dirtyCleanBeforeSample = LastCleanedDirtyTsdfNeighborCount;
                int dirtyQuarantineBeforeSample = LastDirtyTsdfQuarantineCount;
                bool touchedDenseTsdf;
                _activeAtomicBandWrite = useAtomicObservationTsdfBands;
                _activeAtomicBandVote = observationVote;
                _activeSurfaceObservationState = observationVote == ObservationVoteState.Accept ? (byte)3 : (byte)2;
                bool allowClearingRay = observationVote == ObservationVoteState.Accept && ShouldCarveFreeSpaceAtPixel(x, y, stride);
                RecordShadowBlockObservation(cameraPosition, point, normal, sampleWeight, halfBandSteps, observationVote, allowClearingRay);
                try
                {
                    touchedDenseTsdf = useProjectiveTsdfIntegration
                        ? IntegrateProjectiveTsdfBand(cameraPosition, point, sampleWeight, halfBandSteps, allowClearingRay)
                        : IntegrateNormalTsdfBand(point, normal, sampleWeight, halfBandSteps);
                }
                finally
                {
                    _activeAtomicBandWrite = false;
                    _activeAtomicBandVote = ObservationVoteState.Unassessed;
                    _activeSurfaceObservationState = 0;
                }
                if (!touchedDenseTsdf)
                {
                    LastRejectedOutsideVolumeCount++;
                    RecordRawCoverageGridSample(point, RawDepthDebugKind.Outside, false, RawCoverageDecisionStage.OutsideVolume);
                    CacheRawDepthDebugSample(point, RawDepthDebugKind.Outside);
                    AppendConfidenceAuditRow(snapshot.frameIndex, index, x, y, point, sampleWeight, checkedDepthNeighbors, consistentDepthNeighbors, Vector3.Distance(pointBeforeRobust, point), oldTsdfAtSurface, oldWeightAtSurface, oldPendingHitsAtSurface, "discard", "outside_tsdf_volume", auditThisSample);
                    continue;
                }

                if (hasSurfaceVoxelWriteKey &&
                    _budgetedFusionSurfaceVoxelWrites.Add(mergedVoxelIndex))
                    LastBudgetedFusionUniqueSurfaceVoxelWriteCount++;
                LastIntegratedSampleCount++;
                bool sampleHitDirtyRepair =
                    LastReplacedDirtyTsdfCount > dirtyReplaceBeforeSample ||
                    LastCleanedDirtyTsdfNeighborCount > dirtyCleanBeforeSample ||
                    LastDirtyTsdfQuarantineCount > dirtyQuarantineBeforeSample;
                if (sampleHitDirtyRepair)
                {
                    LastBlockedDirtyLightCoverSampleCount++;
                    TotalBlockedDirtyLightCoverSampleCount++;
                    RecordRawCoverageGridSample(point, RawDepthKindFromAuditOutcome(), false, RawCoverageDecisionStage.AuditOutcome);
                    CacheRawDepthDebugSample(point, RawDepthKindFromAuditOutcome());
                    string repairReason = LastReplacedDirtyTsdfCount > dirtyReplaceBeforeSample ? "dirty_replaced" :
                        (LastDirtyTsdfQuarantineCount > dirtyQuarantineBeforeSample ? "dirty_quarantined" : "dirty_neighbor_cleaned");
                    AppendConfidenceAuditRow(snapshot.frameIndex, index, x, y, point, sampleWeight, checkedDepthNeighbors, consistentDepthNeighbors, Vector3.Distance(pointBeforeRobust, point), oldTsdfAtSurface, oldWeightAtSurface, oldPendingHitsAtSurface, "repair", repairReason, auditThisSample);
                }
                else if (!addFallbackOnlyAfterTsdfSupport || sampleWeight >= minFallbackSurfaceSampleWeight)
                {
                    AddFallbackSurfaceSample(point, normal);
                    RawDepthDebugKind outcomeKind = RawDepthKindFromAuditOutcome();
                    string decision = _auditCenterOutcome == "pending_correction" || _auditCenterOutcome == "pending_stability"
                        ? "pending"
                        : (_auditCenterOutcome == "rejected_conflict" ? "discard" : "accept");
                    RecordRawCoverageGridSample(point, outcomeKind, observationVote == ObservationVoteState.Accept, RawCoverageDecisionStage.Integrated);
                    CacheRawDepthDebugSample(point, outcomeKind);
                    string reason = _auditCenterOutcome;
                    AppendConfidenceAuditRow(snapshot.frameIndex, index, x, y, point, sampleWeight, checkedDepthNeighbors, consistentDepthNeighbors, Vector3.Distance(pointBeforeRobust, point), oldTsdfAtSurface, oldWeightAtSurface, oldPendingHitsAtSurface, decision, reason, auditThisSample);
                }
                else
                {
                    LastRejectedFallbackWeakCount++;
                    RecordRawCoverageGridSample(point, RawDepthDebugKind.Rejected, false, RawCoverageDecisionStage.FallbackWeak);
                    CacheRawDepthDebugSample(point, RawDepthDebugKind.Rejected);
                    AppendConfidenceAuditRow(snapshot.frameIndex, index, x, y, point, sampleWeight, checkedDepthNeighbors, consistentDepthNeighbors, Vector3.Distance(pointBeforeRobust, point), oldTsdfAtSurface, oldWeightAtSurface, oldPendingHitsAtSurface, "discard", "fallback_weight_weak", auditThisSample);
                }
            }
        }

        FinalizeRawCoverageGridDiagnostics();
        AppendConfidenceAuditFrame(snapshot.frameIndex, snapshotLatencyMs, posePositionDelta, poseAngleDelta, cameraPosition);
        EndVoteHistoryFrame();
        _activeLedgerSampleIndex = -1;
        _activeLedgerPixelX = -1;
        _activeLedgerPixelY = -1;
        IntegratedFrameCount++;
        _confidenceAuditIntegratedFrames++;
        _fastFusionDecisionJournalOpen = false;
        UpdateDirtyTsdfLifecycleDiagnostics();
        double finalSliceSeconds = Time.realtimeSinceStartupAsDouble - computeSliceStart;
        LastBudgetedFusionMaxSliceMilliseconds = Mathf.Max(
            LastBudgetedFusionMaxSliceMilliseconds,
            (float)(finalSliceSeconds * 1000.0));
        LastBudgetedFusionComputeMilliseconds =
            (float)((completedComputeSeconds + finalSliceSeconds) * 1000.0);
        if (debugLog)
        {
            Debug.Log(
                $"[ScanCoverTsdfSingleShellPrototype] Integrated raw frame={snapshot.frameIndex} resolution={width}x{height} stride={stride} input={LastInputSampleCount} accepted={LastIntegratedSampleCount} acceptRatio={(LastInputSampleCount > 0 ? (float)LastIntegratedSampleCount / LastInputSampleCount : 0f):P1} voxelUpdates={LastUpdatedVoxelCount} budgetComputeMs={LastBudgetedFusionComputeMilliseconds:F1} yields={LastBudgetedFusionYieldCount} uniqueSurfaceWrites={LastBudgetedFusionUniqueSurfaceVoxelWriteCount} mergedSurfaceWrites={LastBudgetedFusionMergedSurfaceVoxelWriteCount} fallback={GetFallbackSurfaceSampleCount()}/{maxFallbackSurfaceSamples} chunks={LastSurfaceChunkCount}/{maxSurfaceChunks} uniqueVoxels={_fallbackSurfaceVoxels.Count} rejects invalid={LastRejectedInvalidPositionCount} depth={LastRejectedDepthRangeCount} edge={LastRejectedDepthDiscontinuityCount} robust={LastRejectedRobustDepthCount}/{LastRobustDepthDownweightedCount}/{LastRobustDepthCorrectedCount} edgeErode={LastRejectedDepthEdgeErosionCount}/{LastDepthEdgeDownweightedCount} support={LastRejectedTsdfDepthSupportCount} normal={LastRejectedNormalCount} facing={LastRejectedFacingCount} confidence={LastRejectedConfidenceCount} tsdfConflict={LastRejectedTsdfConflictCount} stable={LastPendingStableTsdfCount} corrWait={LastPendingTsdfCorrectionCount} corrected={LastCorrectedTsdfCount} dirtyReplace={LastReplacedDirtyTsdfCount} dirtyClean={LastCleanedDirtyTsdfNeighborCount} dirtyQ={LastDirtyTsdfQuarantineCount} carve={LastCarvedFreeSpaceVoxelCount} outsideVolume={LastRejectedOutsideVolumeCount} fbWeak={LastRejectedFallbackWeakCount} fallbackReplaced={LastSkippedFallbackCapacityCount} volume={_dimX}x{_dimY}x{_dimZ} origin={_volumeOriginWorld:F2} size={volumeSizeMeters:F1}",
                this);
        }

        _budgetedSnapshotIntegratedResult = LastIntegratedSampleCount > 0;
    }

