            "snapshot,eye,stereo_enabled,render_target_width,render_target_height,viewport_pixel_width,viewport_pixel_height,viewport_offset_x,viewport_offset_y,pixel_rect_x,pixel_rect_y,pixel_rect_w,pixel_rect_h,near_m,far_m,fov_deg,aspect,pos_x,pos_y,pos_z,rot_x,rot_y,rot_z,rot_w,view_m00,view_m01,view_m02,view_m03,view_m10,view_m11,view_m12,view_m13,view_m20,view_m21,view_m22,view_m23,view_m30,view_m31,view_m32,view_m33,proj_m00,proj_m01,proj_m02,proj_m03,proj_m10,proj_m11,proj_m12,proj_m13,proj_m20,proj_m21,proj_m22,proj_m23,proj_m30,proj_m31,proj_m32,proj_m33");
    }

    private void EndSurfaceProfileDiagnostics(int integratedFrames, string status)
    {
        if (!writeHoleAndLayerDiagnosticsOnCapture || _tsdf == null || _weights == null)
        {
            ReleasePressureShadowSnapshots();
            return;
        }

        try
        {
            string directory = ResolveConfidenceAuditDirectory();
            Directory.CreateDirectory(directory);
            string timestamp = System.DateTime.Now.ToString("yyyyMMdd_HHmmss_fff", AuditCulture);
            string stem = $"surface_profile_{timestamp}_{_surfaceDiagnosticCaptureIndex:D3}";
            string holePath = Path.Combine(directory, stem + "_holes.csv");
            string holeLifecyclePath = Path.Combine(directory, stem + "_hole_cell_lifecycle.csv");
            string rayPath = Path.Combine(directory, stem + "_rays.csv");
            string layerPath = Path.Combine(directory, stem + "_layers.csv");
            string pairPath = Path.Combine(directory, stem + "_layer_pairs.csv");
            string shadowPath = Path.Combine(directory, stem + "_shadow_blocks.csv");
            string quadTopologyPath = Path.Combine(directory, stem + "_quad_topology.csv");
            string quadHeldEvidencePath = Path.Combine(directory, stem + "_quad_shadow_held_evidence.csv");
            string newbornPholdCompetitionPath = Path.Combine(directory, stem + "_newborn_phold_competition.csv");
            string newbornPholdProbationPath = Path.Combine(directory, stem + "_newborn_phold_probation.csv");
            string spatialRupturePath = Path.Combine(directory, stem + "_spatial_ruptures.csv");
            string referenceClassicBoundaryPath = Path.Combine(directory, stem + "_reference_classic_boundaries.csv");
            string referenceClassicCompletionTrialPath = Path.Combine(directory, stem + "_reference_classic_completion_trials.csv");
            string referenceClassicCompletionGroupPath = Path.Combine(directory, stem + "_reference_classic_completion_groups.csv");
            string creaseRepairPath = Path.Combine(directory, stem + "_crease_repairs.csv");
            string incrementalPatchShadowPath = Path.Combine(directory, stem + "_incremental_patch_shadow.csv");
            string stablePlaneRegistryPath = Path.Combine(directory, stem + "_stable_plane_registry.csv");
            string stablePlaneDiagnosticsPath = Path.Combine(directory, stem + "_stable_plane_diagnostics.csv");
            string authoritativeBlockTopologyPath = Path.Combine(directory, stem + "_authoritative_block_topology.csv");
            string authoritativeCyanContinuityPath = Path.Combine(directory, stem + "_authoritative_cyan_continuity.csv");
            string authoritativeCyanPlaneSnapPath = Path.Combine(directory, stem + "_authoritative_cyan_plane_snap.csv");
            string authoritativeCyanPlaneEdgeClassPath = Path.Combine(directory, stem + "_authoritative_cyan_plane_edge_classes.csv");
            string authoritativeCyanPlanePatchPromotionPath = Path.Combine(directory, stem + "_authoritative_cyan_plane_patch_promotion.csv");
            string authoritativeCyanStructuralPlanePath = Path.Combine(directory, stem + "_authoritative_cyan_structural_planes.csv");
            string authoritativeCyanLocalSupportPath = Path.Combine(directory, stem + "_authoritative_cyan_local_support.csv");
            string planeConstrainedZeroCrossShadowPath = Path.Combine(
                directory, stem + "_plane_constrained_zero_cross_shadow.csv");
            string planeConstrainedZeroCrossByPlanePath = Path.Combine(
                directory, stem + "_plane_constrained_zero_cross_by_plane.csv");
            string planeConstrainedZeroCrossTriangleLedgerPath = Path.Combine(
                directory, stem + "_plane_constrained_zero_cross_triangle_ledger.csv");
            string planeConstrainedZeroCrossTriangleScreenPath = Path.Combine(
                directory, stem + "_plane_constrained_zero_cross_triangle_screen.csv");
            string heldToProvisionalPath = Path.Combine(
                directory, stem + "_held_to_provisional.csv");
            string complexCandidateProbationPath = Path.Combine(
                directory, stem + "_complex_candidate_probation.csv");
            string heldRescueKeepDecisionPath = Path.Combine(
                directory, stem + "_held_rescue_keep_decisions.csv");
            string planeConstrainedZeroCrossComponentPath = Path.Combine(
                directory, stem + "_plane_constrained_zero_cross_components.csv");
            string planeConstrainedZeroCrossComponentScreenPath = Path.Combine(
                directory, stem + "_plane_constrained_zero_cross_component_screen.csv");
            string stablePlaneIdentityPlanesPath = Path.Combine(
                directory, stem + "_stable_plane_identity_planes.csv");
            string stablePlaneIdentityPairsPath = Path.Combine(
                directory, stem + "_stable_plane_identity_pairs.csv");
            string planeSupportCellLedgerPath = Path.Combine(
                directory, stem + "_plane_support_cell_ledger.csv");
            string planeSupportCellScreenPath = Path.Combine(
                directory, stem + "_plane_support_cell_screen.csv");
            string planeDiagnosticCameraPath = Path.Combine(
                directory, stem + "_plane_diagnostic_camera.csv");
            string frameConvergencePath = Path.Combine(
                directory, stem + "_frame_convergence.csv");
            string pressureShadowMatrixPath = Path.Combine(
                directory, stem + "_pressure_shadow_matrix.csv");
            string fastFusionShadowFramePath = Path.Combine(
                directory, stem + "_fast_fusion_shadow_frames.csv");
