            _contributionLedgerWriter.Write(',');
            _contributionLedgerWriter.Write(_activeLedgerPixelX);
            _contributionLedgerWriter.Write(',');
            _contributionLedgerWriter.Write(_activeLedgerPixelY);
            _contributionLedgerWriter.Write(',');
            _contributionLedgerWriter.Write(index);
            _contributionLedgerWriter.Write(',');
