    private void RecordRawCoverageGridSample(Vector3 point, RawDepthDebugKind kind, bool accepted,
        RawCoverageDecisionStage decisionStage = RawCoverageDecisionStage.Other)
    {
        if (!enableRawCoverageGridDiagnostics || !Finite(point))
            return;

        LastRawCoverageGridSampleCount++;
        Vector3Int key = RawCoverageGridKey(point);
        if (!_rawCoverageGridCells.TryGetValue(key, out RawCoverageGridCell cell))
        {
            if (_rawCoverageGridCells.Count >= Mathf.Max(1, maxRawCoverageGridCells))
            {
                LastRawCoverageGridDroppedSampleCount++;
                return;
            }

            cell = new RawCoverageGridCell
            {
                PositionSum = Vector3.zero,
                AcceptedCount = 0,
                ProblemCount = 0,
                WorstKind = kind
            };
        }

        cell.PositionSum += point;
        if (_rawCoverageCaptureCameraValid)
        {
            cell.CameraDistanceSum += Vector3.Distance(_rawCoverageCaptureCameraPosition, point);
            cell.CameraDistanceCount++;
        }
        float captureViewFacing = -1f;
        if (_rawCoverageCaptureCameraValid && _auditSampleNormal.sqrMagnitude > 0.0001f)
        {
            Vector3 toCamera = _rawCoverageCaptureCameraPosition - point;
            if (toCamera.sqrMagnitude > 0.000001f)
                captureViewFacing = Mathf.Abs(Vector3.Dot(_auditSampleNormal.normalized, toCamera.normalized));
        }
        if (captureViewFacing >= 0f)
        {
            captureViewFacing = Mathf.Clamp01(captureViewFacing);
            cell.ViewFacingSum += captureViewFacing;
            cell.ViewFacingCount++;
            LastRawCoverageAngleKnownSampleCount++;
            if (captureViewFacing >= 0.7071068f)
            {
                cell.FrontCount++;
                LastRawCoverageFrontSampleCount++;
                if (accepted) { cell.FrontAcceptedCount++; LastRawCoverageFrontAcceptedCount++; }
            }
            else if (captureViewFacing >= 0.5f)
            {
                cell.ObliqueCount++;
                LastRawCoverageObliqueSampleCount++;
                if (accepted) { cell.ObliqueAcceptedCount++; LastRawCoverageObliqueAcceptedCount++; }
            }
            else if (captureViewFacing >= 0.2f)
            {
                cell.GrazingCount++;
                LastRawCoverageGrazingSampleCount++;
                if (accepted) { cell.GrazingAcceptedCount++; LastRawCoverageGrazingAcceptedCount++; }
            }
            else
            {
                cell.ExtremeCount++;
                LastRawCoverageExtremeSampleCount++;
                if (accepted) { cell.ExtremeAcceptedCount++; LastRawCoverageExtremeAcceptedCount++; }
            }
        }
        if (accepted)
            cell.AcceptedCount++;
        else
        {
            cell.ProblemCount++;
            switch (kind)
            {
                case RawDepthDebugKind.DepthEdge: cell.DepthEdgeCount++; break;
                case RawDepthDebugKind.Robust: cell.RobustCount++; break;
                case RawDepthDebugKind.Support: cell.SupportCount++; break;
                case RawDepthDebugKind.Pending:
                case RawDepthDebugKind.StableBand: cell.PendingCount++; break;
                case RawDepthDebugKind.ConflictEdge: cell.ConflictEdgeCount++; break;
                case RawDepthDebugKind.ConflictView: cell.ConflictViewCount++; break;
                case RawDepthDebugKind.ConflictLocked: cell.ConflictLockedCount++; break;
                case RawDepthDebugKind.Outside: cell.OutsideCount++; break;
                default: cell.BasicRejectCount++; break;
            }
        }
        if (_auditGrazingSamePlaneFrameExempted)
            cell.GrazingSamePlaneFrameExemptedCount++;
        if (_auditGrazingSamePlaneFrameConflictCleared)
        {
            cell.GrazingSamePlaneFrameConflictClearedCount++;
            cell.GrazingSamePlaneClearedPositionSum += point;
            if (_auditSampleNormal.sqrMagnitude > 0.0001f)
                cell.GrazingSamePlaneClearedNormalSum += _auditSampleNormal.normalized;
        }

        switch (decisionStage)
        {
            case RawCoverageDecisionStage.BasicFilter:
                cell.BasicFilterCount++;
                LastRawCoverageBasicFilterCount++;
                break;
            case RawCoverageDecisionStage.DepthNeighborhood:
                cell.DepthNeighborhoodStageCount++;
                LastRawCoverageDepthEdgeStageCount++;
                break;
            case RawCoverageDecisionStage.RobustPrefilter:
                cell.RobustPrefilterStageCount++;
                LastRawCoverageRobustStageCount++;
                break;
            case RawCoverageDecisionStage.TsdfSupport:
                cell.TsdfSupportStageCount++;
                LastRawCoverageSupportStageCount++;
                break;
            case RawCoverageDecisionStage.VoteReject:
                cell.VoteRejectCount++;
                LastRawCoverageVoteRejectCount++;
                break;
            case RawCoverageDecisionStage.PendingHold:
                cell.PendingHoldCount++;
                LastRawCoveragePendingHoldCount++;
                break;
            case RawCoverageDecisionStage.OutsideVolume:
                cell.OutsideVolumeStageCount++;
                LastRawCoverageOutsideVolumeStageCount++;
                break;
            case RawCoverageDecisionStage.AuditOutcome:
                cell.AuditOutcomeStageCount++;
                LastRawCoverageAuditOutcomeStageCount++;
                break;
            case RawCoverageDecisionStage.FallbackWeak:
                cell.FallbackWeakStageCount++;
                LastRawCoverageFallbackWeakStageCount++;
                break;
            case RawCoverageDecisionStage.Other:
                if (!accepted) cell.OtherRejectCount++;
                break;
        }

        if (_auditGrazingPlaneActuallyRescued &&
            decisionStage != RawCoverageDecisionStage.BasicFilter)
        {
            cell.RescuedGrazingFinalCount++;
            LastRescuedGrazingFinalCount++;
            if (decisionStage == RawCoverageDecisionStage.VoteReject)
            {
                cell.RescuedGrazingVoteRejectCount++;
                LastRescuedGrazingVoteRejectCount++;
                CountRescuedGrazingVoteRejectReasons(ref cell);
            }
            else if (decisionStage == RawCoverageDecisionStage.Integrated && accepted)
            {
                cell.RescuedGrazingAcceptedCount++;
                LastRescuedGrazingAcceptedCount++;
            }
            else if (decisionStage == RawCoverageDecisionStage.PendingHold ||
                     decisionStage == RawCoverageDecisionStage.Integrated)
            {
                cell.RescuedGrazingPendingCount++;
                LastRescuedGrazingPendingCount++;
            }
            else if (decisionStage == RawCoverageDecisionStage.DepthNeighborhood)
            {
                cell.RescuedGrazingDepthEdgeCount++;
                LastRescuedGrazingDepthEdgeCount++;
            }
            else if (decisionStage == RawCoverageDecisionStage.RobustPrefilter)
            {
                cell.RescuedGrazingRobustCount++;
                LastRescuedGrazingRobustCount++;
            }
            else if (decisionStage == RawCoverageDecisionStage.TsdfSupport)
            {
                cell.RescuedGrazingSupportCount++;
                LastRescuedGrazingSupportCount++;
            }
            else if (decisionStage == RawCoverageDecisionStage.OutsideVolume)
            {
                cell.RescuedGrazingOutsideVolumeCount++;
                LastRescuedGrazingOutsideVolumeCount++;
            }
            else if (decisionStage == RawCoverageDecisionStage.AuditOutcome)
            {
                cell.RescuedGrazingAuditOutcomeCount++;
                LastRescuedGrazingAuditOutcomeCount++;
            }
            else if (decisionStage == RawCoverageDecisionStage.FallbackWeak)
            {
                cell.RescuedGrazingFallbackWeakCount++;
                LastRescuedGrazingFallbackWeakCount++;
            }
            else
            {
                cell.RescuedGrazingOtherCount++;
                LastRescuedGrazingOtherCount++;
            }
        }

        if (RawDepthDebugPriority(kind) > RawDepthDebugPriority(cell.WorstKind))
            cell.WorstKind = kind;

        _rawCoverageGridCells[key] = cell;
        _rawCoverageGridVersion++;
        _rawCoverageOverlayBuildVersion = -1;
    }

    private void CountRescuedGrazingVoteRejectReasons(ref RawCoverageGridCell cell)
    {
        string reasons = _auditVoteReasons ?? string.Empty;
        if (reasons.Contains("weak_support")) { cell.RescuedVoteWeakSupportCount++; LastRescuedVoteWeakSupportCount++; }
        if (reasons.Contains("depth_shift")) { cell.RescuedVoteDepthShiftCount++; LastRescuedVoteDepthShiftCount++; }
        if (reasons.Contains("grazing_view")) { cell.RescuedVoteGrazingViewCount++; LastRescuedVoteGrazingViewCount++; }
        if (reasons.Contains("low_weight")) { cell.RescuedVoteLowWeightCount++; LastRescuedVoteLowWeightCount++; }
        if (reasons.Contains("temporal_depth_jump")) { cell.RescuedVoteTemporalJumpCount++; LastRescuedVoteTemporalJumpCount++; }
        if (reasons.Contains("off_history_surface")) { cell.RescuedVoteOffHistoryCount++; LastRescuedVoteOffHistoryCount++; }
        if (reasons.Contains("old_tsdf_residual")) { cell.RescuedVoteOldTsdfCount++; LastRescuedVoteOldTsdfCount++; }
        if (reasons.Contains("weak_history")) { cell.RescuedVoteWeakHistoryCount++; LastRescuedVoteWeakHistoryCount++; }
        if (reasons.Contains("band_conflict")) { cell.RescuedVoteBandConflictCount++; LastRescuedVoteBandConflictCount++; }
        if (reasons.Contains("band_residual")) { cell.RescuedVoteBandResidualCount++; LastRescuedVoteBandResidualCount++; }
        if (reasons.Contains("same_frame"))
        {
            cell.RescuedVoteSameFrameConflictCount++;
            LastRescuedVoteSameFrameConflictCount++;
            if (_auditSameFrameNormalDeltaDegrees < 0f)
            {
                cell.RescuedVoteSameFrameUnknownPlaneCount++;
                LastRescuedVoteSameFrameUnknownPlaneCount++;
            }
            else
            {
                float normalDot = Mathf.Cos(_auditSameFrameNormalDeltaDegrees * Mathf.Deg2Rad);
                bool samePlaneGrazing = _auditGrazingPlaneSupported &&
                    normalDot >= Mathf.Clamp01(minGrazingPlaneNeighborNormalDot);
                if (samePlaneGrazing)
                {
                    cell.RescuedVoteSameFrameSamePlaneGrazingCount++;
                    LastRescuedVoteSameFrameSamePlaneGrazingCount++;
                }
                else
                {
                    cell.RescuedVoteSameFrameCrossPlaneCount++;
                    LastRescuedVoteSameFrameCrossPlaneCount++;
                }
            }
        }
        if (reasons.Contains("cross_frame_clean_conflict")) { cell.RescuedVoteCrossFrameConflictCount++; LastRescuedVoteCrossFrameConflictCount++; }
    }

    private Vector3Int RawCoverageGridKey(Vector3 point)
    {
        float cellSize = Mathf.Max(0.03f, rawCoverageGridCellSizeMeters);
        return new Vector3Int(
            Mathf.FloorToInt(point.x / cellSize),
            Mathf.FloorToInt(point.y / cellSize),
            Mathf.FloorToInt(point.z / cellSize));
    }

    private void FinalizeRawCoverageGridDiagnostics()
    {
        if (!enableRawCoverageGridDiagnostics)
            return;

        LastRawCoverageGridCellCount = _rawCoverageGridCells.Count;
        HashSet<Vector3Int> acceptedCells = new HashSet<Vector3Int>();
        HashSet<Vector3Int> problemCells = new HashSet<Vector3Int>();
        LastRawCoverageAcceptedCellCount = 0;
        LastRawCoverageProblemCellCount = 0;
        LastRawCoverageMixedCellCount = 0;

        foreach (KeyValuePair<Vector3Int, RawCoverageGridCell> pair in _rawCoverageGridCells)
        {
            bool hasAccepted = pair.Value.AcceptedCount > 0;
            bool hasProblem = pair.Value.ProblemCount > 0;
            if (hasAccepted)
            {
                acceptedCells.Add(pair.Key);
                LastRawCoverageAcceptedCellCount++;
            }
            if (hasProblem)
            {
                problemCells.Add(pair.Key);
                LastRawCoverageProblemCellCount++;
            }
            if (hasAccepted && hasProblem)
                LastRawCoverageMixedCellCount++;
        }

        LastRawCoverageAcceptedComponentCount = CountRawCoverageComponents(acceptedCells, out int largestAccepted);
        LastRawCoverageLargestAcceptedComponentCells = largestAccepted;
        LastRawCoverageProblemComponentCount = CountRawCoverageComponents(problemCells, out int largestProblem);
        LastRawCoverageLargestProblemComponentCells = largestProblem;
    }

    private int CountRawCoverageComponents(HashSet<Vector3Int> cells, out int largest)
    {
        largest = 0;
        if (cells == null || cells.Count <= 0)
            return 0;

        int components = 0;
        HashSet<Vector3Int> visited = new HashSet<Vector3Int>();
        Queue<Vector3Int> queue = new Queue<Vector3Int>();
        Vector3Int[] offsets =
        {
            new Vector3Int(1, 0, 0), new Vector3Int(-1, 0, 0),
            new Vector3Int(0, 1, 0), new Vector3Int(0, -1, 0),
            new Vector3Int(0, 0, 1), new Vector3Int(0, 0, -1)
        };

        foreach (Vector3Int seed in cells)
        {
            if (visited.Contains(seed))
                continue;

            components++;
            int size = 0;
            visited.Add(seed);
            queue.Enqueue(seed);
            while (queue.Count > 0)
            {
                Vector3Int current = queue.Dequeue();
                size++;
                for (int i = 0; i < offsets.Length; i++)
                {
                    Vector3Int next = current + offsets[i];
                    if (!cells.Contains(next) || visited.Contains(next))
                        continue;
                    visited.Add(next);
                    queue.Enqueue(next);
                }
            }

            if (size > largest)
                largest = size;
        }

        return components;
    }

    private void BuildRawCoverageGridDebugCache()
    {
        if (!enableRawCoverageGridDiagnostics || !showRawCoverageGridOverlay)
            return;
        if (_rawCoverageOverlayBuildVersion == _rawCoverageGridVersion)
            return;

        ClearRawDepthDebugCache();
        int limit = Mathf.Max(1, maxRawDepthDebugSamples);
        int acceptedStride = Mathf.Max(1, rawCoverageAcceptedDisplayStride);
        int acceptedCounter = 0;
        foreach (KeyValuePair<Vector3Int, RawCoverageGridCell> pair in _rawCoverageGridCells)
        {
            RawCoverageGridCell cell = pair.Value;
            bool hasAccepted = cell.AcceptedCount > 0;
            bool hasProblem = cell.ProblemCount > 0;
            RawDepthDebugKind kind = hasProblem ? cell.WorstKind : RawDepthDebugKind.Accepted;
            if (hasAccepted && !hasProblem)
            {
                acceptedCounter++;
                if (acceptedCounter % acceptedStride != 0)
                    continue;
            }

            int total = Mathf.Max(1, cell.AcceptedCount + cell.ProblemCount);
            _rawDepthDebugPoints.Add(cell.PositionSum / total);
            _rawDepthDebugKinds.Add(kind);
            if (_rawDepthDebugPoints.Count >= limit)
                break;
        }

        LastRawCoverageRenderedCellCount = _rawDepthDebugPoints.Count;
        _rawCoverageOverlayBuildVersion = _rawCoverageGridVersion;
    }

    private void CacheRawDepthDebugSample(Vector3 point, RawDepthDebugKind kind)
    {
        if (!showRawDepthDebugView || !Finite(point))
            return;
        const int classifierRevision = 6;
        if (_rawDepthDebugClassifierRevision != classifierRevision)
        {
            ClearRawDepthDebugCache();
            _rawDepthDebugClassifierRevision = classifierRevision;
        }
        if (restrictRawDepthDebugToNearTsdfSurface && !RawDepthDebugPointTouchesNearTsdfSurface(point))
            return;
        if (kind == RawDepthDebugKind.Accepted)
        {
            if (!showAcceptedRawDepthDebugSamples)
                return;
            _acceptedRawDepthDebugCounter++;
            if (_acceptedRawDepthDebugCounter % Mathf.Max(1, acceptedRawDepthDebugSampleStride) != 0)
                return;
        }
        else if (kind == RawDepthDebugKind.DepthEdge)
        {
            _rawDepthDebugDepthEdgeCounter++;
            if (_rawDepthDebugDepthEdgeCounter % Mathf.Max(1, rawDepthDebugDepthEdgeSampleStride) != 0)
                return;
        }
        else if (kind == RawDepthDebugKind.Robust)
        {
            _rawDepthDebugRobustCounter++;
            if (_rawDepthDebugRobustCounter % Mathf.Max(1, rawDepthDebugRobustSampleStride) != 0)
                return;
        }
        else if (kind == RawDepthDebugKind.Rejected)
        {
            _rawDepthDebugRejectedCounter++;
            if (_rawDepthDebugRejectedCounter % Mathf.Max(1, rawDepthDebugRejectedSampleStride) != 0)
                return;
        }

        int limit = Mathf.Max(1, maxRawDepthDebugSamples);
        if (_rawDepthDebugPoints.Count < limit)
        {
            _rawDepthDebugPoints.Add(point);
            _rawDepthDebugKinds.Add(kind);
            return;
        }

        int index = FindRawDepthDebugReplacementIndex(kind, limit);
        _rawDepthDebugPoints[index] = point;
        _rawDepthDebugKinds[index] = kind;
        _rawDepthDebugReplaceCursor = (index + 1) % limit;
    }

    private int FindRawDepthDebugReplacementIndex(RawDepthDebugKind incomingKind, int limit)
    {
        limit = Mathf.Max(1, Mathf.Min(limit, _rawDepthDebugKinds.Count));
        int incomingPriority = RawDepthDebugPriority(incomingKind);
        int start = Mathf.Abs(_rawDepthDebugReplaceCursor) % limit;
        int best = start;
        int bestPriority = int.MaxValue;
        for (int i = 0; i < limit; i++)
        {
            int index = (start + i) % limit;
            int priority = RawDepthDebugPriority(_rawDepthDebugKinds[index]);
            if (priority < incomingPriority)
                return index;
            if (priority < bestPriority)
            {
                best = index;
                bestPriority = priority;
            }
        }

        return bestPriority <= incomingPriority ? best : start;
    }

    private static int RawDepthDebugPriority(RawDepthDebugKind kind)
    {
        switch (kind)
        {
            case RawDepthDebugKind.Dirty:
                return 6;
            case RawDepthDebugKind.ConflictLocked:
            case RawDepthDebugKind.ConflictView:
            case RawDepthDebugKind.ConflictEdge:
                return 6;
            case RawDepthDebugKind.Pending:
                return 5;
            case RawDepthDebugKind.StableBand:
                return 2;
            case RawDepthDebugKind.Support:
                return 4;
            case RawDepthDebugKind.Outside:
                return 3;
            case RawDepthDebugKind.Robust:
                return 2;
            case RawDepthDebugKind.DepthEdge:
                return 1;
            case RawDepthDebugKind.Rejected:
            case RawDepthDebugKind.Accepted:
            default:
                return 0;
        }
    }

    private bool RawDepthDebugPointTouchesNearTsdfSurface(Vector3 point)
    {
        if (_tsdf == null || _weights == null || !TryWorldToVoxel(point, out int x, out int y, out int z))
            return false;

        int radius = Mathf.Clamp(rawDepthDebugDirtyRadiusVoxels, 0, 2);
        float maxAbsTsdf = Mathf.Clamp(rawDepthDebugNearSurfaceAbsTsdf, 0.01f, 0.8f);
        for (int dz = -radius; dz <= radius; dz++)
        {
            int vz = z + dz;
            if (vz < 0 || vz >= _dimZ)
                continue;
            for (int dy = -radius; dy <= radius; dy++)
            {
                int vy = y + dy;
                if (vy < 0 || vy >= _dimY)
                    continue;
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int vx = x + dx;
                    if (vx < 0 || vx >= _dimX)
                        continue;

                    int index = Index(vx, vy, vz);
                    if (_weights[index] < minSurfaceCornerWeight)
                        continue;
                    if (Mathf.Abs(_tsdf[index]) <= maxAbsTsdf)
                        return true;
                    if (VoxelHasPendingTsdfCorrection(index) || VoxelIsDirtyQuarantined(index))
                        return true;
                }
            }
        }

        return false;
    }

    private bool TryGetRawDepthDebugDirtyKind(Vector3 point, out RawDepthDebugKind kind)
    {
        kind = RawDepthDebugKind.Rejected;
        if (_tsdf == null || _weights == null || !TryWorldToVoxel(point, out int x, out int y, out int z))
            return false;

        int radius = Mathf.Clamp(rawDepthDebugNearSurfaceRadiusVoxels, 0, 3);
        bool pending = false;
        for (int dz = -radius; dz <= radius; dz++)
        {
            int vz = z + dz;
            if (vz < 0 || vz >= _dimZ)
                continue;
            for (int dy = -radius; dy <= radius; dy++)
            {
                int vy = y + dy;
                if (vy < 0 || vy >= _dimY)
                    continue;
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int vx = x + dx;
                    if (vx < 0 || vx >= _dimX)
                        continue;

                    int index = Index(vx, vy, vz);
                    if (VoxelIsDirtyQuarantined(index))
                    {
                        kind = RawDepthDebugKind.Dirty;
                        return true;
                    }
                    if (VoxelHasPendingTsdfCorrection(index))
                        pending = true;
                }
            }
        }

        if (pending)
        {
            kind = RawDepthDebugKind.Pending;
            return true;
        }

        return false;
    }

    private void AddRawDepthDebugSample(
        List<Vector3> vertices,
        List<int> triangles,
        List<Color> colors,
        Vector3 point,
        Vector3 cameraPosition,
        RawDepthDebugKind kind)
    {
        if ((!showRawDepthDebugView && !showRawCoverageGridOverlay) || vertices == null || triangles == null || colors == null)
            return;
        if (LastRawDepthDebugRenderedCount >= Mathf.Max(1, maxRawDepthDebugSamples))
            return;
        if (!Finite(point))
            return;

        Color color = RawDepthDebugColor(kind);
        color.a = Mathf.Clamp01(rawDepthDebugAlpha);

        Vector3 view = point - cameraPosition;
        if (!Finite(view) || view.sqrMagnitude < 0.0001f)
            view = Vector3.forward;
        view.Normalize();

        Vector3 tangent = Vector3.Cross(Vector3.up, view);
        if (tangent.sqrMagnitude < 0.0001f)
            tangent = Vector3.Cross(Vector3.right, view);
        tangent.Normalize();
        Vector3 bitangent = Vector3.Cross(view, tangent).normalized;

        float half = Mathf.Max(0.001f, rawDepthDebugSampleSizeMeters) * 0.5f;
        int baseIndex = vertices.Count;
        vertices.Add(point - tangent * half - bitangent * half);
        vertices.Add(point + tangent * half - bitangent * half);
        vertices.Add(point + tangent * half + bitangent * half);
        vertices.Add(point - tangent * half + bitangent * half);
        AddVertexColors(colors, color, 4);

        triangles.Add(baseIndex);
        triangles.Add(baseIndex + 1);
        triangles.Add(baseIndex + 2);
        triangles.Add(baseIndex);
        triangles.Add(baseIndex + 2);
        triangles.Add(baseIndex + 3);

        LastRawDepthDebugRenderedCount++;
        switch (kind)
        {
            case RawDepthDebugKind.Accepted:
                LastRawDepthDebugAcceptedCount++;
                break;
            case RawDepthDebugKind.Dirty:
                LastRawDepthDebugDirtyCount++;
                break;
            case RawDepthDebugKind.Pending:
                LastRawDepthDebugPendingCount++;
                break;
            case RawDepthDebugKind.StableBand:
                LastRawDepthDebugStableBandCount++;
                break;
            case RawDepthDebugKind.ConflictEdge:
                LastRawDepthDebugConflictEdgeCount++;
                break;
            case RawDepthDebugKind.ConflictView:
                LastRawDepthDebugConflictViewCount++;
                break;
            case RawDepthDebugKind.ConflictLocked:
                LastRawDepthDebugConflictLockedCount++;
                break;
            case RawDepthDebugKind.DepthEdge:
                LastRawDepthDebugDepthEdgeCount++;
                break;
            case RawDepthDebugKind.Robust:
                LastRawDepthDebugRobustCount++;
                break;
            case RawDepthDebugKind.Support:
                LastRawDepthDebugSupportCount++;
                break;
            case RawDepthDebugKind.Outside:
                LastRawDepthDebugOutsideCount++;
                break;
            case RawDepthDebugKind.Rejected:
            default:
                LastRawDepthDebugRejectedCount++;
                break;
        }
    }

    private void AddRawDepthDebugCubeSample(
        List<Vector3> vertices,
        List<int> triangles,
        List<Color> colors,
        Vector3 point,
        RawDepthDebugKind kind)
    {
        if ((!showRawDepthDebugView && !showRawCoverageGridOverlay) || vertices == null || triangles == null || colors == null)
            return;
        if (LastRawDepthDebugRenderedCount >= Mathf.Max(1, maxRawDepthDebugSamples))
            return;
        if (!Finite(point))
            return;

        Color color = RawDepthDebugColor(kind);
        color.a = Mathf.Clamp01(rawDepthDebugAlpha);

        float half = Mathf.Max(0.001f, rawDepthDebugSampleSizeMeters) * 0.5f;
        int baseIndex = vertices.Count;
        vertices.Add(point + new Vector3(-half, -half, -half));
        vertices.Add(point + new Vector3( half, -half, -half));
        vertices.Add(point + new Vector3( half,  half, -half));
        vertices.Add(point + new Vector3(-half,  half, -half));
        vertices.Add(point + new Vector3(-half, -half,  half));
        vertices.Add(point + new Vector3( half, -half,  half));
        vertices.Add(point + new Vector3( half,  half,  half));
        vertices.Add(point + new Vector3(-half,  half,  half));
        AddVertexColors(colors, color, 8);

        AddCubeFace(triangles, baseIndex, 0, 2, 1, 3);
        AddCubeFace(triangles, baseIndex, 4, 5, 6, 7);
        AddCubeFace(triangles, baseIndex, 0, 1, 5, 4);
        AddCubeFace(triangles, baseIndex, 2, 3, 7, 6);
        AddCubeFace(triangles, baseIndex, 1, 2, 6, 5);
        AddCubeFace(triangles, baseIndex, 3, 0, 4, 7);

        LastRawDepthDebugRenderedCount++;
        switch (kind)
        {
            case RawDepthDebugKind.Accepted:
                LastRawDepthDebugAcceptedCount++;
                break;
            case RawDepthDebugKind.Dirty:
                LastRawDepthDebugDirtyCount++;
                break;
            case RawDepthDebugKind.Pending:
                LastRawDepthDebugPendingCount++;
                break;
            case RawDepthDebugKind.StableBand:
                LastRawDepthDebugStableBandCount++;
                break;
            case RawDepthDebugKind.ConflictEdge:
                LastRawDepthDebugConflictEdgeCount++;
                break;
            case RawDepthDebugKind.ConflictView:
                LastRawDepthDebugConflictViewCount++;
                break;
            case RawDepthDebugKind.ConflictLocked:
                LastRawDepthDebugConflictLockedCount++;
                break;
            case RawDepthDebugKind.DepthEdge:
                LastRawDepthDebugDepthEdgeCount++;
                break;
            case RawDepthDebugKind.Robust:
                LastRawDepthDebugRobustCount++;
                break;
            case RawDepthDebugKind.Support:
                LastRawDepthDebugSupportCount++;
                break;
            case RawDepthDebugKind.Outside:
                LastRawDepthDebugOutsideCount++;
                break;
            case RawDepthDebugKind.Rejected:
            default:
                LastRawDepthDebugRejectedCount++;
                break;
        }
    }

    private static void AddCubeFace(List<int> triangles, int baseIndex, int a, int b, int c, int d)
    {
        triangles.Add(baseIndex + a);
        triangles.Add(baseIndex + b);
        triangles.Add(baseIndex + c);
        triangles.Add(baseIndex + a);
        triangles.Add(baseIndex + c);
        triangles.Add(baseIndex + d);
    }

    private Color RawDepthDebugColor(RawDepthDebugKind kind)
    {
        switch (kind)
        {
            case RawDepthDebugKind.Accepted:
                return rawDepthDebugAcceptedColor;
            case RawDepthDebugKind.Dirty:
                return rawDepthDebugDirtyColor;
            case RawDepthDebugKind.Pending:
                return rawDepthDebugPendingColor;
            case RawDepthDebugKind.StableBand:
                return rawDepthDebugStableBandColor;
            case RawDepthDebugKind.ConflictEdge:
                return rawDepthDebugConflictEdgeColor;
            case RawDepthDebugKind.ConflictView:
                return rawDepthDebugConflictViewColor;
            case RawDepthDebugKind.ConflictLocked:
                return rawDepthDebugConflictLockedColor;
            case RawDepthDebugKind.DepthEdge:
                return rawDepthDebugDepthEdgeColor;
            case RawDepthDebugKind.Robust:
                return rawDepthDebugRobustColor;
            case RawDepthDebugKind.Support:
                return rawDepthDebugSupportColor;
            case RawDepthDebugKind.Outside:
                return rawDepthDebugOutsideColor;
            case RawDepthDebugKind.Rejected:
            default:
                return rawDepthDebugRejectedColor;
        }
    }

