    private void BuildFallbackSurfaceSampleMesh(List<Vector3> vertices, List<int> triangles, List<Color> colors)
    {
        if (!showFallbackSurfaceSamples)
            return;
        if (useChunkedSurfaceSamples)
        {
            BuildChunkedFallbackSurfaceSampleMesh(vertices, triangles, colors);
            return;
        }
        if (_fallbackSurfacePoints.Count <= 0)
            return;

        float halfSize = GetCoverageTileHalfSize();
        int count = Mathf.Min(_fallbackSurfacePoints.Count, Mathf.Max(1, maxFallbackSurfaceSamples));
        for (int i = 0; i < count; i++)
        {
            Vector3 normal = i < _fallbackSurfaceNormals.Count ? _fallbackSurfaceNormals[i] : Vector3.up;
            if (!Finite(normal) || normal.sqrMagnitude < 0.0001f)
                normal = Vector3.up;
            normal.Normalize();

            Vector3 tangent = Vector3.Cross(normal, Vector3.up);
            if (tangent.sqrMagnitude < 0.0001f)
                tangent = Vector3.Cross(normal, Vector3.right);
            tangent.Normalize();
            Vector3 bitangent = Vector3.Cross(normal, tangent).normalized;
            Vector3 center = _fallbackSurfacePoints[i] + normal * 0.004f;

            int baseIndex = vertices.Count;
            vertices.Add(center - tangent * halfSize - bitangent * halfSize);
            vertices.Add(center + tangent * halfSize - bitangent * halfSize);
            vertices.Add(center + tangent * halfSize + bitangent * halfSize);
            vertices.Add(center - tangent * halfSize + bitangent * halfSize);
            AddVertexColors(colors, cleanCoverCellColor, 4);

            triangles.Add(baseIndex);
            triangles.Add(baseIndex + 1);
            triangles.Add(baseIndex + 2);
            triangles.Add(baseIndex);
            triangles.Add(baseIndex + 2);
            triangles.Add(baseIndex + 3);

            if (!doubleSidedTriangles)
                continue;

            triangles.Add(baseIndex + 2);
            triangles.Add(baseIndex + 1);
            triangles.Add(baseIndex);
            triangles.Add(baseIndex + 3);
            triangles.Add(baseIndex + 2);
            triangles.Add(baseIndex);
        }
    }

    private void BuildChunkedFallbackSurfaceSampleMesh(List<Vector3> vertices, List<int> triangles, List<Color> colors)
    {
        LastRenderedFallbackSampleCount = 0;
        LastPlanarCoverTileCount = 0;
        LastSkippedDirtyLightCoverCellCount = 0;
        LastSkippedUnstableLightCoverCellCount = 0;
        LastCleanLightCoverCellCount = 0;
        LastUnstableLightCoverCellCount = 0;
        LastRiskLightCoverCellCount = 0;
        if (_surfaceChunks.Count <= 0)
            return;

        if (renderStableCellsAsPlanarMeshCover && useConnectedPlanarCoverMesh)
        {
            BuildConnectedPlanarCoverageMesh(vertices, triangles, colors);
            return;
        }

        float halfSize = GetCoverageTileHalfSize();
        int renderBudget = GetLightCoverRenderBudget();
        int storedCellCount = GetFallbackSurfaceSampleCount();
        if (storedCellCount <= 0)
            return;

        float sampleStep = storedCellCount > renderBudget ? (float)storedCellCount / renderBudget : 1f;
        float nextEmitIndex = 0f;
        int visitedCellIndex = 0;

        for (int orderIndex = 0; orderIndex < _surfaceChunkOrder.Count && LastRenderedFallbackSampleCount < renderBudget; orderIndex++)
        {
            Vector3Int chunkKey = _surfaceChunkOrder[orderIndex];
            if (!_surfaceChunks.TryGetValue(chunkKey, out SurfaceChunk chunk))
                continue;

            foreach (KeyValuePair<Vector3Int, SurfaceCell> pair in chunk.Cells)
            {
                if (visitedCellIndex + 0.0001f < nextEmitIndex)
                {
                    visitedCellIndex++;
                    continue;
                }

                SurfaceCell cell = pair.Value;
                LightCoverCellRisk risk = ClassifyLightCoverCell(cell);
                if (!ShouldRenderLightCoverCell(risk))
                {
                    visitedCellIndex++;
                    continue;
                }
                CountRenderedLightCoverRisk(risk);

                if (renderStableCellsAsPlanarMeshCover)
                    AddPlanarCoverageTile(pair.Key, cell, vertices, triangles, colors, ColorForLightCoverRisk(risk));
                else
                    AddFallbackQuad(cell.Point, cell.Normal, halfSize, vertices, triangles, colors, ColorForLightCoverRisk(risk));
                LastRenderedFallbackSampleCount++;
                nextEmitIndex += sampleStep;
                visitedCellIndex++;
                if (LastRenderedFallbackSampleCount >= renderBudget)
                    break;
            }
        }
    }

    private void BuildConnectedPlanarCoverageMesh(List<Vector3> vertices, List<int> triangles, List<Color> colors)
    {
        int renderBudget = GetLightCoverRenderBudget();
        int storedCellCount = GetFallbackSurfaceSampleCount();
        if (storedCellCount <= 0)
            return;

        Dictionary<CoverVertexKey, int> vertexLookup = new Dictionary<CoverVertexKey, int>(Mathf.Min(storedCellCount * 2, renderBudget * 2));
        float sampleStep = storedCellCount > renderBudget ? (float)storedCellCount / renderBudget : 1f;
        float nextEmitIndex = 0f;
        int visitedCellIndex = 0;

        for (int orderIndex = 0; orderIndex < _surfaceChunkOrder.Count && LastRenderedFallbackSampleCount < renderBudget; orderIndex++)
        {
            Vector3Int chunkKey = _surfaceChunkOrder[orderIndex];
            if (!_surfaceChunks.TryGetValue(chunkKey, out SurfaceChunk chunk))
                continue;

            foreach (KeyValuePair<Vector3Int, SurfaceCell> pair in chunk.Cells)
            {
                LightCoverCellRisk risk = ClassifyLightCoverCell(pair.Value);
                if (!ShouldRenderLightCoverCell(risk))
                {
                    visitedCellIndex++;
                    continue;
                }

                if (visitedCellIndex + 0.0001f < nextEmitIndex)
                {
                    visitedCellIndex++;
                    continue;
                }

                CountRenderedLightCoverRisk(risk);
                AddConnectedPlanarCoverageCell(pair.Value, vertexLookup, vertices, triangles, colors, ColorForLightCoverRisk(risk));
                LastRenderedFallbackSampleCount++;
                nextEmitIndex += sampleStep;
                visitedCellIndex++;
                if (LastRenderedFallbackSampleCount >= renderBudget)
                    break;
            }
        }
    }

    private int GetLightCoverRenderBudget()
    {
        return Mathf.Clamp(maxRenderedLightCoverTiles, 256, Mathf.Max(256, maxFallbackSurfaceSamples));
    }

    private LightCoverCellRisk ClassifyLightCoverCell(SurfaceCell cell)
    {
        if (renderOnlyStableLightCoverCells &&
            cell.Hits < Mathf.Max(1, minLightCoverCellHits))
        {
            return LightCoverCellRisk.Unstable;
        }

        if (renderOnlyCleanLightCoverCells && !LightCoverCellHasCleanTsdf(cell))
        {
            return LightCoverCellRisk.Risk;
        }

        return LightCoverCellRisk.Clean;
    }

    private bool ShouldRenderLightCoverCell(LightCoverCellRisk risk)
    {
        if (risk == LightCoverCellRisk.Unstable && !showUnstableLightCoverRiskCells)
        {
            LastSkippedUnstableLightCoverCellCount++;
            return false;
        }

        if (risk == LightCoverCellRisk.Risk && !showDirtyLightCoverRiskCells)
        {
            LastSkippedDirtyLightCoverCellCount++;
            return false;
        }

        return true;
    }

    private void CountRenderedLightCoverRisk(LightCoverCellRisk risk)
    {
        if (risk == LightCoverCellRisk.Risk)
            LastRiskLightCoverCellCount++;
        else if (risk == LightCoverCellRisk.Unstable)
            LastUnstableLightCoverCellCount++;
        else
            LastCleanLightCoverCellCount++;
    }

    private Color ColorForLightCoverRisk(LightCoverCellRisk risk)
    {
        if (risk == LightCoverCellRisk.Risk)
            return riskCoverCellColor;
        if (risk == LightCoverCellRisk.Unstable)
            return unstableCoverCellColor;
        return cleanCoverCellColor;
    }

    private bool LightCoverCellHasCleanTsdf(SurfaceCell cell)
    {
        if (_tsdf == null || _weights == null || !TryWorldToVoxel(cell.Point, out int x, out int y, out int z))
            return false;

        int radius = Mathf.Clamp(cleanLightCoverCheckRadiusVoxels, 0, 3);
        int minWeight = Mathf.Max(1, minCleanLightCoverVoxelWeight);
        float maxAbsTsdf = Mathf.Clamp(maxCleanLightCoverAbsTsdf, 0.01f, 0.8f);
        int supportedNearSurface = 0;
        bool requireNearZero = requireNearZeroTsdfForLightCover;

        for (int dz = -radius; dz <= radius; dz++)
        {
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int vx = x + dx;
                    int vy = y + dy;
                    int vz = z + dz;
                    if (vx < 0 || vy < 0 || vz < 0 || vx >= _dimX || vy >= _dimY || vz >= _dimZ)
                        continue;

                    int index = Index(vx, vy, vz);
                    if (VoxelIsDirtyQuarantined(index))
                        return false;
                    if (VoxelHasPendingTsdfCorrection(index))
                        return false;
                    if (!requireNearZero)
                        continue;

                    if (_weights[index] < minWeight)
                        continue;

                    if (Mathf.Abs(_tsdf[index]) <= maxAbsTsdf)
                        supportedNearSurface++;
                }
            }
        }

        return !requireNearZero || supportedNearSurface > 0;
    }

    private void AddConnectedPlanarCoverageCell(
        SurfaceCell cell,
        Dictionary<CoverVertexKey, int> vertexLookup,
        List<Vector3> vertices,
        List<int> triangles,
        List<Color> colors,
        Color color)
    {
        Vector3 normal = cell.Normal;
        if (!Finite(normal) || normal.sqrMagnitude < 0.0001f)
            normal = Vector3.up;
        normal.Normalize();

        int axis = DominantAxis(normal);
        int sign = GetAxis(normal, axis) >= 0f ? 1 : -1;
        int uAxis;
        int vAxis;
        GetCoverUvAxes(axis, out uAxis, out vAxis);

        float pitch = Mathf.Max(0.005f, voxelSizeMeters * Mathf.Clamp(planarCoverTileScale, 0.6f, 1.8f));
        int plane = Mathf.RoundToInt(GetAxis(cell.Point, axis) / pitch);
        int centerU = Mathf.RoundToInt(GetAxis(cell.Point, uAxis) / pitch);
        int centerV = Mathf.RoundToInt(GetAxis(cell.Point, vAxis) / pitch);

        CoverVertexKey k00 = new CoverVertexKey(axis, sign, plane, centerU * 2 - 1, centerV * 2 - 1);
        CoverVertexKey k10 = new CoverVertexKey(axis, sign, plane, centerU * 2 + 1, centerV * 2 - 1);
        CoverVertexKey k11 = new CoverVertexKey(axis, sign, plane, centerU * 2 + 1, centerV * 2 + 1);
        CoverVertexKey k01 = new CoverVertexKey(axis, sign, plane, centerU * 2 - 1, centerV * 2 + 1);

        int i00 = GetOrAddCoverVertex(k00, pitch, vertexLookup, vertices, colors, color);
        int i10 = GetOrAddCoverVertex(k10, pitch, vertexLookup, vertices, colors, color);
        int i11 = GetOrAddCoverVertex(k11, pitch, vertexLookup, vertices, colors, color);
        int i01 = GetOrAddCoverVertex(k01, pitch, vertexLookup, vertices, colors, color);

        Vector3 a = vertices[i00];
        Vector3 b = vertices[i10];
        Vector3 c = vertices[i11];
        if (Vector3.Dot(Vector3.Cross(b - a, c - a), normal) >= 0f)
        {
            triangles.Add(i00);
            triangles.Add(i10);
            triangles.Add(i11);
            triangles.Add(i00);
            triangles.Add(i11);
            triangles.Add(i01);
            if (doubleSidedTriangles)
            {
                triangles.Add(i11);
                triangles.Add(i10);
                triangles.Add(i00);
                triangles.Add(i01);
                triangles.Add(i11);
                triangles.Add(i00);
            }
        }
        else
        {
            triangles.Add(i11);
            triangles.Add(i10);
            triangles.Add(i00);
            triangles.Add(i01);
            triangles.Add(i11);
            triangles.Add(i00);
            if (doubleSidedTriangles)
            {
                triangles.Add(i00);
                triangles.Add(i10);
                triangles.Add(i11);
                triangles.Add(i00);
                triangles.Add(i11);
                triangles.Add(i01);
            }
        }

        LastPlanarCoverTileCount++;
    }

    private int GetOrAddCoverVertex(
        CoverVertexKey key,
        float pitch,
        Dictionary<CoverVertexKey, int> vertexLookup,
        List<Vector3> vertices,
        List<Color> colors,
        Color color)
    {
        if (vertexLookup.TryGetValue(key, out int index))
        {
            PromoteCoverVertexColor(colors, index, color);
            return index;
        }

        int uAxis;
        int vAxis;
        GetCoverUvAxes(key.Axis, out uAxis, out vAxis);

        Vector3 position = Vector3.zero;
        SetAxis(ref position, key.Axis, key.Plane * pitch + key.Sign * 0.004f);
        SetAxis(ref position, uAxis, key.U * pitch * 0.5f);
        SetAxis(ref position, vAxis, key.V * pitch * 0.5f);

        index = vertices.Count;
        vertices.Add(position);
        colors.Add(color);
        vertexLookup.Add(key, index);
        return index;
    }

    private void AddPlanarCoverageTile(Vector3Int cellKey, SurfaceCell cell, List<Vector3> vertices, List<int> triangles, List<Color> colors, Color color)
    {
        Vector3 normal = cell.Normal;
        if (!Finite(normal) || normal.sqrMagnitude < 0.0001f)
            normal = Vector3.up;
        normal.Normalize();

        int axis = DominantAxis(normal);
        Vector3 tangent;
        Vector3 bitangent;
        if (axis == 0)
        {
            tangent = Vector3.forward;
            bitangent = Vector3.up;
        }
        else if (axis == 1)
        {
            tangent = Vector3.right;
            bitangent = Vector3.forward;
        }
        else
        {
            tangent = Vector3.right;
            bitangent = Vector3.up;
        }

        if (Vector3.Dot(Vector3.Cross(tangent, bitangent), normal) < 0f)
        {
            Vector3 swap = tangent;
            tangent = bitangent;
            bitangent = swap;
        }

        float halfSize = Mathf.Max(0.001f, voxelSizeMeters * Mathf.Clamp(planarCoverTileScale, 0.6f, 1.8f)) * 0.5f;
        Vector3 center = cell.Point + normal * 0.004f;
        int baseIndex = vertices.Count;
        vertices.Add(center - tangent * halfSize - bitangent * halfSize);
        vertices.Add(center + tangent * halfSize - bitangent * halfSize);
        vertices.Add(center + tangent * halfSize + bitangent * halfSize);
        vertices.Add(center - tangent * halfSize + bitangent * halfSize);
        AddVertexColors(colors, color, 4);

        triangles.Add(baseIndex);
        triangles.Add(baseIndex + 1);
        triangles.Add(baseIndex + 2);
        triangles.Add(baseIndex);
        triangles.Add(baseIndex + 2);
        triangles.Add(baseIndex + 3);

        if (doubleSidedTriangles)
        {
            triangles.Add(baseIndex + 2);
            triangles.Add(baseIndex + 1);
            triangles.Add(baseIndex);
            triangles.Add(baseIndex + 3);
            triangles.Add(baseIndex + 2);
            triangles.Add(baseIndex);
        }

        LastPlanarCoverTileCount++;
    }

    private void RebuildWireOverlay(List<Vector3> sourceVertices, List<int> sourceTriangles)
    {
        if (showMeshEdgeWireOverlay)
        {
            RebuildMeshEdgeWireOverlay(sourceVertices, sourceTriangles);
            return;
        }

        RebuildPlanarCoverWireOverlay();
    }

    private void RebuildMeshEdgeWireOverlay(List<Vector3> sourceVertices, List<int> sourceTriangles)
    {
        LastWireSegmentCount = 0;
        if (_wireMesh == null)
            return;

        _wireMesh.Clear();

        if (sourceVertices == null || sourceTriangles == null || sourceVertices.Count <= 0 || sourceTriangles.Count < 3)
        {
            if (_wireObject != null)
                _wireObject.SetActive(false);
            return;
        }

        List<int> indices = new List<int>(sourceTriangles.Count * 2);
        HashSet<ulong> edgeKeys = new HashSet<ulong>();
        for (int i = 0; i + 2 < sourceTriangles.Count; i += 3)
        {
            AddUniqueWireEdge(sourceTriangles[i], sourceTriangles[i + 1], sourceVertices.Count, edgeKeys, indices);
            AddUniqueWireEdge(sourceTriangles[i + 1], sourceTriangles[i + 2], sourceVertices.Count, edgeKeys, indices);
            AddUniqueWireEdge(sourceTriangles[i + 2], sourceTriangles[i], sourceVertices.Count, edgeKeys, indices);
        }

        _wireMesh.indexFormat = sourceVertices.Count > 65535 ? IndexFormat.UInt32 : IndexFormat.UInt16;
        _wireMesh.SetVertices(sourceVertices);
        _wireMesh.SetIndices(indices, MeshTopology.Lines, 0, true);
        _wireMesh.RecalculateBounds();
        LastWireSegmentCount = indices.Count / 2;
        if (_wireObject != null)
            _wireObject.SetActive(indices.Count > 0);
    }

    private static void AddUniqueWireEdge(int a, int b, int vertexCount, HashSet<ulong> edgeKeys, List<int> indices)
    {
        if (a < 0 || b < 0 || a >= vertexCount || b >= vertexCount || a == b)
            return;

        uint min = (uint)Mathf.Min(a, b);
        uint max = (uint)Mathf.Max(a, b);
        ulong key = ((ulong)min << 32) | max;
        if (!edgeKeys.Add(key))
            return;

        indices.Add(a);
        indices.Add(b);
    }

    private IReadOnlyDictionary<Vector3Int, ScanCoverIncrementalPatchShadow.PatchDirtyReason>
        MergeFastFusionPhaseOneDirtySchedule(
            IReadOnlyDictionary<Vector3Int, ScanCoverIncrementalPatchShadow.PatchDirtyReason> baseline,
            int patchVoxels)
    {
        _fastFusionPhaseOneScheduledPatchCount = 0;
        if (!_fastFusionPhaseOnePromoted || _fastFusionPhaseOneDirtyBlocks.Count == 0)
            return baseline;

        Dictionary<Vector3Int, ScanCoverIncrementalPatchShadow.PatchDirtyReason> merged =
            new Dictionary<Vector3Int, ScanCoverIncrementalPatchShadow.PatchDirtyReason>();
        if (baseline != null)
        {
            foreach (KeyValuePair<Vector3Int, ScanCoverIncrementalPatchShadow.PatchDirtyReason> pair
                     in baseline)
                merged[pair.Key] = pair.Value;
        }
        int fastBlockVoxels = Mathf.Clamp(fastFusionShadowBlockVoxels, 4, 16);
        patchVoxels = Mathf.Max(1, patchVoxels);
        foreach (Vector3Int block in _fastFusionPhaseOneDirtyBlocks)
        {
            int minX = Mathf.FloorToInt((float)(block.x * fastBlockVoxels) / patchVoxels);
            int minY = Mathf.FloorToInt((float)(block.y * fastBlockVoxels) / patchVoxels);
            int minZ = Mathf.FloorToInt((float)(block.z * fastBlockVoxels) / patchVoxels);
            int maxX = Mathf.FloorToInt(
                (float)(((block.x + 1) * fastBlockVoxels) - 1) / patchVoxels);
            int maxY = Mathf.FloorToInt(
                (float)(((block.y + 1) * fastBlockVoxels) - 1) / patchVoxels);
            int maxZ = Mathf.FloorToInt(
                (float)(((block.z + 1) * fastBlockVoxels) - 1) / patchVoxels);
            for (int z = minZ; z <= maxZ; z++)
            for (int y = minY; y <= maxY; y++)
            for (int x = minX; x <= maxX; x++)
            {
                Vector3Int patch = new Vector3Int(x, y, z);
                if (!merged.ContainsKey(patch))
                {
                    merged.Add(
                        patch,
                        ScanCoverIncrementalPatchShadow.PatchDirtyReason.GeometryChanged);
                    _fastFusionPhaseOneScheduledPatchCount++;
                }
            }
        }
        return merged;
    }

    private void RebuildIncrementalPatchShadow(
        List<Vector3> sourceVertices,
        List<int> sourceTriangles,
        List<Color> sourceColors)
    {
        ResetIncrementalPatchShadowDiagnostics();
        EnsureIncrementalPatchShadowObjects();
        if (_incrementalPatchShadowMesh == null || _incrementalPatchShadowObject == null)
            return;
        _incrementalPatchShadowMesh.Clear();
        if (!enableIncrementalPatchShadow ||
            sourceVertices == null || sourceTriangles == null ||
            sourceVertices.Count < 3 || sourceTriangles.Count < 3)
        {
            _incrementalPatchShadowObject.SetActive(false);
            return;
        }

        ScanCoverIncrementalPatchShadow.Settings settings = new ScanCoverIncrementalPatchShadow.Settings
        {
            // The shadow pipeline consumes the canonical logical view, even while
            // the production renderer continues to use reverse-winding copies.
            DoubleSidedTriangles = false,
            ExternalDirtyIsAuthoritative = incrementalTsdfDirtyIsAuthoritative,
            DirectAtomicBlockPublication = incrementalDirectAtomicBlockPublication,
            LocalExtractionPaddingPatches = incrementalPatchLocalExtractionPadding,
            PatchSizeMeters = voxelSizeMeters * Mathf.Clamp(incrementalPatchSizeVoxels, 2, 12),
            ConfirmRebuilds = incrementalPatchConfirmRebuilds,
            ReplacementConfirmRebuilds = incrementalPatchReplacementConfirmRebuilds,
            CorrectionConfirmRebuilds = incrementalPatchCorrectionConfirmRebuilds,
            CorrectionTrialRebuilds = incrementalPatchCorrectionTrialRebuilds,
            CorrectionMaxResidualRegressionMeters = incrementalPatchCorrectionMaxResidualRegressionMeters,
            CorrectionMaxCoherenceRegression = incrementalPatchCorrectionMaxCoherenceRegression,
            RetireMissingRebuilds = incrementalPatchRetireMissingRebuilds,
            MaxPatches = incrementalPatchMaxPatches,
            MaxTrianglesPerPatch = incrementalPatchMaxTrianglesPerPatch,
            StableCentroidDistanceMeters = incrementalPatchStableCentroidDistanceMeters,
            StableNormalDot = incrementalPatchStableNormalDot,
            StableTriangleRatio = incrementalPatchStableTriangleRatio,
            PlanarResidualMeters = incrementalPatchPlanarResidualMeters,
            PlanarNormalCoherence = incrementalPatchPlanarNormalCoherence,
            ReplacementResidualSlackMeters = incrementalPatchReplacementResidualSlackMeters,
            ReplacementBoundarySlackRatio = incrementalPatchReplacementBoundarySlackRatio,
            MaturePlaneConstraints = _stablePlaneRegistry.GetMatureConstraints(),
            PlanePatchMinResidualMeters = incrementalPatchPlaneMinResidualMeters,
            PlanePatchMinNormalDot = incrementalPatchPlaneMinNormalDot,
            PlanePatchMaxCentroidDistanceMeters = incrementalPatchPlaneMaxCentroidDistanceMeters,
            PlanePatchTangentialPaddingMeters = incrementalPatchPlaneTangentialPaddingMeters,
            PlanePatchMaxVertexMoveMeters = incrementalPatchPlaneMaxVertexMoveMeters,
            PlanePatchMinTriangleAreaRatio = incrementalPatchPlaneMinTriangleAreaRatio,
            PlanePatchMinTriangleNormalDot = incrementalPatchPlaneMinTriangleNormalDot,
            PlanePatchAmbiguityScoreMargin = incrementalPatchPlaneAmbiguityScoreMargin,
            PlaneRejectMaxHoldRebuilds = incrementalPatchPlaneRejectMaxHoldRebuilds,
            PlaneRejectWithdrawResidualMeters = incrementalPatchPlaneRejectWithdrawResidualMeters
        };
        IReadOnlyDictionary<Vector3Int, ScanCoverIncrementalPatchShadow.PatchDirtyReason> tsdfSurfaceDirty = null;
        if (enableIncrementalTsdfSurfaceDirty &&
            _tsdf != null && _weights != null && _dimX > 1 && _dimY > 1 && _dimZ > 1)
        {
            ScanCoverTsdfSurfaceDirtyTracker.Settings dirtySettings = new ScanCoverTsdfSurfaceDirtyTracker.Settings
            {
                PatchSizeMeters = settings.PatchSizeMeters,
                StableCrossingRatio = incrementalTsdfDirtyStableCrossingRatio,
                StableCentroidDistanceMeters = incrementalTsdfDirtyCentroidMeters,
                StableBoundsDistanceMeters = incrementalTsdfDirtyBoundsMeters,
                StableNormalDot = incrementalTsdfDirtyNormalDot,
                MinCrossingsForNormal = incrementalTsdfDirtyMinCrossingsForNormal,
                RetireMissingRebuilds = incrementalTsdfDirtyRetireMissingRebuilds
            };
            float[] dirtyTsdf = enableAuthoritativeTsdfBlockExtraction ? _authoritativeReadTsdf : _tsdf;
            byte[] dirtyWeights = enableAuthoritativeTsdfBlockExtraction ? _authoritativeReadWeights : _weights;
            ScanCoverTsdfSurfaceDirtyTracker.Result dirtyResult = _incrementalTsdfSurfaceDirtyTracker.Update(
                dirtyTsdf,
                dirtyWeights,
                _dimX,
                _dimY,
                _dimZ,
                _volumeOriginWorld,
                voxelSizeMeters,
                dirtySettings);
            tsdfSurfaceDirty = _incrementalTsdfSurfaceDirtyTracker.DirtyReasons;
            LastIncrementalTsdfDirtyBlockCount = dirtyResult.DirtyBlocks;
            LastIncrementalTsdfDirtyCurrentBlockCount = dirtyResult.CurrentBlocks;
            LastIncrementalTsdfDirtyCrossingCount = dirtyResult.CurrentCrossings;
            LastIncrementalTsdfDirtyCleanBlockCount = dirtyResult.CleanBlocks;
            LastIncrementalTsdfDirtyNewBlockCount = dirtyResult.NewBlocks;
            LastIncrementalTsdfDirtyChangedBlockCount = dirtyResult.ChangedBlocks;
            LastIncrementalTsdfDirtyMissingBlockCount = dirtyResult.MissingBlocks;
            LastIncrementalTsdfDirtyRetiredBlockCount = dirtyResult.RetiredBlocks;
        }
        tsdfSurfaceDirty = MergeFastFusionPhaseOneDirtySchedule(
            tsdfSurfaceDirty,
            Mathf.Clamp(incrementalPatchSizeVoxels, 2, 12));
        ScanCoverIncrementalPatchShadow.Result result = _incrementalPatchShadow.Update(
            sourceVertices,
            sourceTriangles,
            sourceColors,
            _volumeOriginWorld,
            settings,
            tsdfSurfaceDirty,
            out List<Vector3> publishedVertices,
            out List<int> publishedTriangles,
            out List<Color> publishedColors);
        LastIncrementalPatchRebuildSequence = result.RebuildSequence;
        LastIncrementalPatchCandidateCount = result.CandidatePatches;
        LastIncrementalPatchCandidateTriangleCount = result.CandidateTriangles;
        LastIncrementalPatchNewCount = result.NewPatches;
