        LastIncrementalPatchCleanReusedCount = result.CleanReusedPatches;
        LastIncrementalPatchDirtyClusterCount = result.DirtyClusterCount;
        LastIncrementalPatchLargestDirtyClusterCount = result.LargestDirtyClusterPatches;
        LastIncrementalPatchLargestLocalClusterCount = result.LargestLocalClusterPatches;
