        LastIncrementalPatchCreaseTransitionFamilyChangedCount = result.CreaseTransitionFamilyChangedPatches;
        LastIncrementalPatchCreaseTransitionFamilyLostCount = result.CreaseTransitionFamilyLostPatches;
