        LastIncrementalPatchCreaseRegionalAggregatedCount = result.CreaseRegionalAggregatedPatches;
        LastIncrementalPatchCreaseRegionalMigratedCount = result.CreaseRegionalMigratedPatches;
        LastIncrementalPatchCreaseRegionalReadyCount = result.CreaseRegionalReadyPatches;
