        LastIncrementalPatchDirtyBoundsMin = result.DirtyBoundsMin;
        LastIncrementalPatchDirtyBoundsMax = result.DirtyBoundsMax;

        if (enableAuthoritativeTsdfBlockExtraction && tsdfSurfaceDirty != null)
        {
            RebuildAuthoritativeTsdfBlockShadow(
                tsdfSurfaceDirty,
                Mathf.Clamp(incrementalPatchSizeVoxels, 2, 12),
                out List<Vector3> authoritativeVertices,
                out List<int> authoritativeTriangles,
                out List<Color> authoritativeColors);
            publishedVertices = authoritativeVertices;
            publishedTriangles = authoritativeTriangles;
            publishedColors = authoritativeColors;
        }

        if (!showIncrementalPatchShadowWire ||
            publishedVertices == null || publishedTriangles == null ||
            publishedVertices.Count < 3 || publishedTriangles.Count < 3)
        {
            _incrementalPatchShadowObject.SetActive(false);
            return;
        }

        // The authoritative cyan mesh is the measured surface.  A camera-facing
        // presentation offset makes a correct plane look one centimetre off-wall.
        float displayOffset = showAuthoritativeCyanOnly && enableAuthoritativeTsdfBlockExtraction
            ? 0f
            : Mathf.Clamp(incrementalPatchShadowDisplayOffsetMeters, 0f, 0.03f);
        if (displayOffset > 0f)
        {
            Vector3 cameraPosition = Camera.main != null
                ? Camera.main.transform.position
                : GetCameraPosition();
            for (int i = 0; i < publishedVertices.Count; i++)
            {
                Vector3 towardCamera = cameraPosition - publishedVertices[i];
                if (towardCamera.sqrMagnitude > 0.000001f)
                    publishedVertices[i] += towardCamera.normalized * displayOffset;
            }
        }

        List<int> lineIndices = new List<int>(publishedTriangles.Count * 2);
        HashSet<ulong> edges = new HashSet<ulong>();
        for (int i = 0; i + 2 < publishedTriangles.Count; i += 3)
        {
            AddUniqueWireEdge(publishedTriangles[i], publishedTriangles[i + 1], publishedVertices.Count, edges, lineIndices);
            AddUniqueWireEdge(publishedTriangles[i + 1], publishedTriangles[i + 2], publishedVertices.Count, edges, lineIndices);
            AddUniqueWireEdge(publishedTriangles[i + 2], publishedTriangles[i], publishedVertices.Count, edges, lineIndices);
        }
        _incrementalPatchShadowMesh.indexFormat = publishedVertices.Count > 65535
            ? IndexFormat.UInt32
            : IndexFormat.UInt16;
        _incrementalPatchShadowMesh.SetVertices(publishedVertices);
        _incrementalPatchShadowMesh.SetIndices(lineIndices, MeshTopology.Lines, 0, true);
        _incrementalPatchShadowMesh.RecalculateBounds();
        _incrementalPatchShadowObject.SetActive(
            lineIndices.Count > 0 && !showPlaneReferenceAndZeroCrossShadowOnly);
    }

    private bool RebuildAuthoritativeTsdfBlockShadow(
        IReadOnlyDictionary<Vector3Int, ScanCoverIncrementalPatchShadow.PatchDirtyReason> dirtyReasons,
        int blockVoxels,
        out List<Vector3> publishedVertices,
        out List<int> publishedTriangles,
        out List<Color> publishedColors,
        bool allowContinuityAudit = true)
    {
        AuthoritativeBlockRebuildState state = new AuthoritativeBlockRebuildState();
        IEnumerator routine = RebuildAuthoritativeTsdfBlockShadowRoutine(
            dirtyReasons, blockVoxels, state, null, allowContinuityAudit);
        while (routine.MoveNext())
        {
        }
        publishedVertices = state.Vertices;
        publishedTriangles = state.Triangles;
        publishedColors = state.Colors;
        return state.Result;
    }

    private IEnumerator RebuildAuthoritativeTsdfBlockShadowRoutine(
        IReadOnlyDictionary<Vector3Int, ScanCoverIncrementalPatchShadow.PatchDirtyReason> dirtyReasons,
        int blockVoxels,
        AuthoritativeBlockRebuildState state,
        CooperativeRebuildBudget budget,
        bool allowContinuityAudit = true)
    {
        LastAuthoritativeBlockDirtyAttemptCount = 0;
        LastAuthoritativeBlockDependencyAttemptCount = 0;
        LastAuthoritativeBlockDependencyCandidateCount = 0;
        LastAuthoritativeBlockDependencyPrunedCount = 0;
        LastAuthoritativePlaneChangedCount = 0;
        LastAuthoritativePlaneInvalidatedBlockCount = 0;
        LastAuthoritativeBlockRebuiltCount = 0;
        LastAuthoritativeBlockRollbackCount = 0;
        LastAuthoritativeBlockDirectEmptyCount = 0;
        LastAuthoritativeBlockDependencyEmptyCount = 0;
        LastAuthoritativeBlockEmptyReplacementCount = 0;
        LastAuthoritativeBlockDirectTopologyRollbackCount = 0;
        LastAuthoritativeBlockDependencyTopologyRollbackCount = 0;
        LastAuthoritativeBlockMultiComponentCellCount = 0;
        LastAuthoritativeBlockSplitVertexCount = 0;
        LastAuthoritativeMc33CellCount = 0;
        LastAuthoritativeMc33AmbiguousFaceCount = 0;
        LastAuthoritativeMc33InteriorTestCount = 0;
        LastAuthoritativeMc33FallbackCellCount = 0;
        LastAuthoritativeMc33FailureCount = 0;
        LastAuthoritativeBlockRejectedNonManifoldEdgeCount = 0;
        LastAuthoritativeBlockRejectedMaxEdgeIncidence = 0;
        LastAuthoritativeBlockRejectedDuplicateTriangleCount = 0;
        LastAuthoritativeBlockRejectedDegenerateTriangleCount = 0;
        LastAuthoritativeBlockRejectedMixedAxisEdgeCount = 0;
        ResetAuthoritativeCyanPlaneSnapDiagnostics();
        ResetAuthoritativeCyanContinuityDiagnostics();
        _authoritativeBlockTopologyRows = new StringBuilder(2048);
        _authoritativeBlockTopologyRows.AppendLine(
            "snapshot,block_x,block_y,block_z,direct,reason,vertices,triangles,multi_component_cells,split_vertices,nonmanifold_edges,max_edge_incidence,duplicate_triangles,degenerate_triangles,mixed_axis_edges");
        _authoritativeCyanPlaneSnapRows = new StringBuilder(2048);
        _authoritativeCyanPlaneSnapRows.AppendLine(
            "snapshot,block_x,block_y,block_z,direct,mature_planes,triangles,matched_triangles,moved_vertices,crease_locked_vertices,reject_normal,reject_distance,reject_extent,reject_ambiguity,residual_before_m,residual_after_m,max_move_m,applied,rollback,rollback_reason");
