        _heldToProvisionalRows = new StringBuilder(8192);
        _heldToProvisionalRows.AppendLine(
            "snapshot,triangle_id,block_x,block_y,block_z,target_plane_id,plane_kind,atomic_class,legacy_reason,held_origin_reason,assigned_vertices,applied_vertices,distinct_applied_plane_families,rescue_evidence,independent_status,independent_checked,independent_plane_id,independent_qualification,independent_reason,independent_distance_m,independent_normal_dot,independent_score,target_global_qualified,target_local_qualified,target_qualification,target_qualification_reject,max_raw_plane_distance_m,plane_distance_limit_m,raw_normal_dot,normal_dot_limit,projected_area_m2,projected_area_limit_m2,candidate_evaluation_reason,raw_centroid_x,raw_centroid_y,raw_centroid_z,relaxed_centroid_x,relaxed_centroid_y,relaxed_centroid_z,held_keep_decision,held_keep_action,working_publish_eligible,final_relaxed_class");
        _planeConstrainedZeroCrossComponentRows = new StringBuilder(8192);
        _planeConstrainedZeroCrossComponentRows.AppendLine(
            "snapshot,scope,component_id,plane_ids,atomic_classes,dispositions,triangles,problem_triangles,suspect_triangles,boundary_triangles,ledger_id_min,ledger_id_max,area_m2,center_x,center_y,center_z,min_x,min_y,min_z,max_x,max_y,max_z,min_u,max_u,min_v,max_v,max_abs_distance_before_m,max_abs_distance_after_m");
        _planeConstrainedZeroCrossComponentScreenRows = new StringBuilder(8192);
        _planeConstrainedZeroCrossComponentScreenRows.AppendLine(
            "snapshot,scope,component_id,eye,stereo_enabled,render_target_width,render_target_height,viewport_pixel_width,viewport_pixel_height,viewport_offset_x,viewport_offset_y,front_vertices,visible_vertices,intersects_viewport,viewport_min_u,viewport_min_v,viewport_max_u,viewport_max_v,pixel_min_x,pixel_min_y_bottom,pixel_max_x,pixel_max_y_bottom,pixel_min_y_top,pixel_max_y_top,min_depth_m,max_depth_m");
        _stablePlaneIdentityPlaneRows = new StringBuilder(2048);
        _stablePlaneIdentityPlaneRows.AppendLine(
            "snapshot,plane_id,plane_kind,center_x,center_y,center_z,normal_x,normal_y,normal_z,offset_m,radius_m,rms_m,total_inliers,consecutive_batches,published_structural_total_triangles,published_healthy_triangles,published_suspect_triangles,held_triangles,published_nonplanar_triangles,nonplanar_candidate_triangles,boundary_triangles,published_islands,area_m2,mean_edge_m,max_edge_m,mean_aspect,max_aspect,mean_abs_before_m,max_abs_before_m,mean_abs_after_m,max_abs_after_m");
        _stablePlaneIdentityPairRows = new StringBuilder(2048);
        _stablePlaneIdentityPairRows.AppendLine(
            "snapshot,plane_a,kind_a,plane_b,kind_b,normal_dot,angle_deg,offset_separation_m,a_center_to_b_m,b_center_to_a_m,tangent_center_distance_m,overlap_ratio,published_a,published_b,mixed_triangles,shared_edge_adjacencies,min_centroid_distance_m,spatially_observed,relation,suspected_split");
        _planeSupportCellLedgerRows = new StringBuilder(16384);
        _planeSupportCellLedgerRows.AppendLine(
            "snapshot,support_cell_id,plane_id,plane_kind,qualification,global_reject,support_source,tile_state,tile_u,tile_v,sub_u,sub_v,block_x,block_y,block_z,display_class,reason,formal_structural_triangles,provisional_structural_triangles,pending_triangles,complex_triangles,wrong_plane_triangles,hard_illegal_triangles,unclassified_triangles,any_triangles,direct_evidence,direct_last_snapshot,direct_samples,direct_total_samples,direct_missing_batches,center_x,center_y,center_z,min_u,max_u,min_v,max_v,a_x,a_y,a_z,b_x,b_y,b_z,c_x,c_y,c_z,d_x,d_y,d_z");
        _planeSupportCellScreenRows = new StringBuilder(16384);
        _planeSupportCellScreenRows.AppendLine(
            "snapshot,support_cell_id,plane_id,plane_kind,qualification,support_source,display_class,reason,direct_evidence,direct_samples,direct_total_samples,direct_missing_batches,eye,stereo_enabled,render_target_width,render_target_height,viewport_pixel_width,viewport_pixel_height,viewport_offset_x,viewport_offset_y,front_corners,visible_corners,intersects_viewport,viewport_min_u,viewport_min_v,viewport_max_u,viewport_max_v,pixel_min_x,pixel_min_y_bottom,pixel_max_x,pixel_max_y_bottom,pixel_min_y_top,pixel_max_y_top,min_depth_m,max_depth_m");
        ResetPlaneConstrainedZeroCrossShadowDiagnostics();
        LastAuthoritativeBlockRetiredCount = 0;
        List<Vector3> publishedVertices = state.Vertices;
        List<int> publishedTriangles = state.Triangles;
        List<Color> publishedColors = state.Colors;
        publishedVertices.Clear();
        publishedTriangles.Clear();
        publishedColors.Clear();
        if (_authoritativeReadTsdf == null || _authoritativeReadWeights == null || dirtyReasons == null)
        {
            state.Result = false;
            yield break;
        }

        int retireMissing = Mathf.Clamp(incrementalTsdfDirtyRetireMissingRebuilds, 2, 16);
        HashSet<Vector3Int> missingKeys = new HashSet<Vector3Int>();
        HashSet<Vector3Int> rebuildKeys = new HashSet<Vector3Int>();
        HashSet<Vector3Int> clearedResultLedgerKeys = new HashSet<Vector3Int>();
        double dependencyScheduleStart = budget != null
            ? budget.GetComputeSecondsSnapshot()
            : Time.realtimeSinceStartupAsDouble;
        IReadOnlyDictionary<Vector3Int, int> dependencyBoundaryMasks =
            _incrementalTsdfSurfaceDirtyTracker.DependencyBoundaryMasks;
        foreach (KeyValuePair<Vector3Int, ScanCoverIncrementalPatchShadow.PatchDirtyReason> pair in dirtyReasons)
        {
            if (budget != null && budget.ShouldYield())
            {
                budget.CompleteSliceForYield();
                yield return null;
                budget.Resume();
            }
            if (pair.Value == ScanCoverIncrementalPatchShadow.PatchDirtyReason.Missing)
            {
                missingKeys.Add(pair.Key);
                if (!_authoritativeTsdfBlocks.TryGetValue(pair.Key, out AuthoritativeTsdfBlockMesh missingBlock))
                {
                    if (_persistentResultLedgerByBlock.ContainsKey(pair.Key))
                        clearedResultLedgerKeys.Add(pair.Key);
                    continue;
                }
                missingBlock.MissingRebuilds++;
                if (missingBlock.MissingRebuilds < retireMissing)
                    continue;
                _authoritativeTsdfBlocks.Remove(pair.Key);
                clearedResultLedgerKeys.Add(pair.Key);
                LastAuthoritativeBlockRetiredCount++;
                continue;
            }
            rebuildKeys.Add(pair.Key);
            // Surface-net vertices on a block boundary read cells from the one-voxel halo.
            // Cached 26-neighbours therefore share a hard data dependency and must be
            // invalidated with the dirty core. This is dependency propagation, not
            // geometric evidence migration.
            for (int z = -1; z <= 1; z++)
            for (int y = -1; y <= 1; y++)
            for (int x = -1; x <= 1; x++)
            {
                if (x == 0 && y == 0 && z == 0)
                    continue;
                Vector3Int neighbour = pair.Key + new Vector3Int(x, y, z);
                if (!_authoritativeTsdfBlocks.ContainsKey(neighbour))
                    continue;
                LastAuthoritativeBlockDependencyCandidateCount++;
                if (localizeAuthoritativeHaloDependencies &&
                    !AuthoritativeDirtyBoundaryTouchesNeighbour(
                        pair.Key, x, y, z, dependencyBoundaryMasks))
                {
                    LastAuthoritativeBlockDependencyPrunedCount++;
                    continue;
                }
                rebuildKeys.Add(neighbour);
            }
        }

        // Plane constraints are persistent state.  Rebuilding every cached block merely
        // because at least one mature plane exists turns the incremental route back into
        // a full-scene rebuild.  Only a newly-added, removed or materially-moved plane
        // invalidates clean cached blocks, and then only inside that plane's footprint.
        List<ScanCoverStablePlaneRegistry.PlaneConstraint> maturePlanes =
            _stablePlaneRegistry.GetMatureConstraints();
        LastAuthoritativePlaneChangedCount = 0;
        LastAuthoritativePlaneInvalidatedBlockCount = 0;
        if (enableAuthoritativeCyanPlaneSnap && maturePlanes.Count > 0 ||
            _lastAuthoritativePlaneConstraints.Count > 0)
        {
            List<ScanCoverStablePlaneRegistry.PlaneConstraint> changedPlanes =
                CollectChangedAuthoritativePlanes(maturePlanes);
            LastAuthoritativePlaneChangedCount = changedPlanes.Count;
            if (!localizeStablePlaneInvalidation && changedPlanes.Count > 0)
            {
                foreach (Vector3Int cachedKey in _authoritativeTsdfBlocks.Keys)
                {
                    if (budget != null && budget.ShouldYield())
                    {
                        budget.CompleteSliceForYield();
                        yield return null;
                        budget.Resume();
                    }
                    if (!missingKeys.Contains(cachedKey) && rebuildKeys.Add(cachedKey))
                        LastAuthoritativePlaneInvalidatedBlockCount++;
                }
            }
            else
            {
                float patchSize = voxelSizeMeters * Mathf.Clamp(blockVoxels, 2, 12);
                foreach (Vector3Int cachedKey in _authoritativeTsdfBlocks.Keys)
                {
                    if (budget != null && budget.ShouldYield())
                    {
                        budget.CompleteSliceForYield();
                        yield return null;
                        budget.Resume();
                    }
                    if (missingKeys.Contains(cachedKey) ||
                        !AuthoritativeBlockTouchesChangedPlane(cachedKey, patchSize, changedPlanes))
                        continue;
                    if (rebuildKeys.Add(cachedKey))
                        LastAuthoritativePlaneInvalidatedBlockCount++;
                }
            }
            // Keep the last *applied* snapshot when motion is below threshold so
            // several tiny updates still accumulate into a later invalidation.
            if (changedPlanes.Count > 0)
                SnapshotAuthoritativePlaneConstraints(maturePlanes);
        }
        LastAuthoritativeBlockDependencyScheduleMilliseconds =
            (float)(((budget != null
                ? budget.GetComputeSecondsSnapshot()
                : Time.realtimeSinceStartupAsDouble) - dependencyScheduleStart) * 1000.0);

        Dictionary<Vector3Int, AuthoritativeTsdfBlockMesh> extractedCandidates =
            new Dictionary<Vector3Int, AuthoritativeTsdfBlockMesh>(rebuildKeys.Count);
        Dictionary<Vector3Int, bool> directAttempts = new Dictionary<Vector3Int, bool>(rebuildKeys.Count);
        Dictionary<Vector3Int, ScanCoverIncrementalPatchShadow.PatchDirtyReason> directReasons =
            new Dictionary<Vector3Int, ScanCoverIncrementalPatchShadow.PatchDirtyReason>(rebuildKeys.Count);
        double extractionStart = budget != null
            ? budget.GetComputeSecondsSnapshot()
            : Time.realtimeSinceStartupAsDouble;
        foreach (Vector3Int key in rebuildKeys)
        {
            if (budget != null && budget.ShouldYield())
            {
                budget.CompleteSliceForYield();
                yield return null;
                budget.Resume();
            }
            if (missingKeys.Contains(key))
                continue;
            LastAuthoritativeBlockDirtyAttemptCount++;
            bool directAttempt = dirtyReasons.TryGetValue(key, out ScanCoverIncrementalPatchShadow.PatchDirtyReason directReason) &&
                                 directReason != ScanCoverIncrementalPatchShadow.PatchDirtyReason.None;
            if (!directAttempt)
                LastAuthoritativeBlockDependencyAttemptCount++;
            bool hasSurface = TryExtractAuthoritativeTsdfBlock(
                key, blockVoxels, out AuthoritativeTsdfBlockMesh candidate);
            LastAuthoritativeBlockMultiComponentCellCount += candidate.MultiComponentCells;
            LastAuthoritativeBlockSplitVertexCount += candidate.SplitVertices;
            if (!hasSurface || candidate.Triangles.Count < 3)
            {
                if (directAttempt)
                    LastAuthoritativeBlockDirectEmptyCount++;
                else
                    LastAuthoritativeBlockDependencyEmptyCount++;
                // An empty extraction is a valid atomic replacement, not a failed
                // rebuild.  Remove stale cached geometry instead of calling it a rollback.
                if (_authoritativeTsdfBlocks.Remove(key))
                    LastAuthoritativeBlockEmptyReplacementCount++;
                clearedResultLedgerKeys.Add(key);
                continue;
            }
            extractedCandidates[key] = candidate;
            directAttempts[key] = directAttempt;
            directReasons[key] = directReason;
        }
        LastAuthoritativeBlockExtractionMilliseconds =
            (float)(((budget != null
                ? budget.GetComputeSecondsSnapshot()
                : Time.realtimeSinceStartupAsDouble) - extractionStart) * 1000.0);

        Dictionary<Vector3Int, AuthoritativeTsdfBlockMesh> relaxedRawCandidates =
            enableLegacyRelaxedCandidateShadow
                ? CloneAuthoritativeTsdfBlockMeshes(extractedCandidates)
                : null;
        double semanticFinalizeStart = budget != null
            ? budget.GetComputeSecondsSnapshot()
            : Time.realtimeSinceStartupAsDouble;
        if (budget != null && budget.ShouldYield())
        {
            budget.CompleteSliceForYield();
            yield return null;
            budget.Resume();
        }
        IEnumerator planeBootstrapRoutine = UpdateIncrementalStablePlaneRegistryRoutine(
            extractedCandidates, budget);
        while (planeBootstrapRoutine.MoveNext())
            yield return planeBootstrapRoutine.Current;
        if (budget != null && budget.ShouldYield())
        {
            budget.CompleteSliceForYield();
            yield return null;
            budget.Resume();
        }
        ApplyAuthoritativeCyanGlobalPlaneConstraints(extractedCandidates, directAttempts);
        if (budget != null && budget.ShouldYield())
        {
            budget.CompleteSliceForYield();
            yield return null;
            budget.Resume();
        }
        IEnumerator semanticRoutine = BuildPlaneConstrainedZeroCrossShadowRoutine(
            extractedCandidates, relaxedRawCandidates, directAttempts,
            clearedResultLedgerKeys, blockVoxels, budget);
        while (semanticRoutine.MoveNext())
            yield return semanticRoutine.Current;
        LastAuthoritativeBlockSemanticFinalizeMilliseconds =
            (float)(((budget != null
                ? budget.GetComputeSecondsSnapshot()
                : Time.realtimeSinceStartupAsDouble) - semanticFinalizeStart) * 1000.0);

        double cacheMergeStart = budget != null
            ? budget.GetComputeSecondsSnapshot()
            : Time.realtimeSinceStartupAsDouble;
        foreach (KeyValuePair<Vector3Int, AuthoritativeTsdfBlockMesh> pair in extractedCandidates)
        {
            if (budget != null && budget.ShouldYield())
            {
                budget.CompleteSliceForYield();
                yield return null;
                budget.Resume();
            }
            Vector3Int key = pair.Key;
            AuthoritativeTsdfBlockMesh candidate = pair.Value;
            bool directAttempt = directAttempts[key];
            ScanCoverIncrementalPatchShadow.PatchDirtyReason directReason = directReasons[key];
            AuthoritativeBlockTopologyStats topology = AnalyzeAuthoritativeBlockTopology(candidate);
            if (topology.NonManifoldEdges > 0)
            {
                LastAuthoritativeBlockRollbackCount++;
                LastAuthoritativeBlockRejectedNonManifoldEdgeCount += topology.NonManifoldEdges;
                LastAuthoritativeBlockRejectedMaxEdgeIncidence = Mathf.Max(
                    LastAuthoritativeBlockRejectedMaxEdgeIncidence, topology.MaxEdgeIncidence);
                LastAuthoritativeBlockRejectedDuplicateTriangleCount += topology.DuplicateTriangles;
                LastAuthoritativeBlockRejectedDegenerateTriangleCount += topology.DegenerateTriangles;
                LastAuthoritativeBlockRejectedMixedAxisEdgeCount += topology.MixedAxisEdges;
                if (directAttempt)
                    LastAuthoritativeBlockDirectTopologyRollbackCount++;
                else
                    LastAuthoritativeBlockDependencyTopologyRollbackCount++;
                AppendAuthoritativeBlockTopologyRow(
                    key, directAttempt, directReason, candidate, topology);
                continue;
            }
            candidate.MissingRebuilds = 0;
            _authoritativeTsdfBlocks[key] = candidate;
            LastAuthoritativeBlockRebuiltCount++;
        }

        List<Vector3Int> keys = new List<Vector3Int>(_authoritativeTsdfBlocks.Keys);
        keys.Sort((a, b) =>
        {
            int z = a.z.CompareTo(b.z);
            if (z != 0) return z;
            int y = a.y.CompareTo(b.y);
            return y != 0 ? y : a.x.CompareTo(b.x);
        });
        for (int keyIndex = 0; keyIndex < keys.Count; keyIndex++)
        {
            if (budget != null && budget.ShouldYield())
            {
                budget.CompleteSliceForYield();
                yield return null;
                budget.Resume();
            }
            AuthoritativeTsdfBlockMesh block = _authoritativeTsdfBlocks[keys[keyIndex]];
            int baseVertex = publishedVertices.Count;
            publishedVertices.AddRange(block.Vertices);
            for (int i = 0; i < block.Vertices.Count; i++)
                publishedColors.Add(incrementalPatchShadowWireColor);
            for (int i = 0; i < block.Triangles.Count; i++)
                publishedTriangles.Add(baseVertex + block.Triangles[i]);
        }

        LastAuthoritativeBlockCachedCount = _authoritativeTsdfBlocks.Count;
        LastAuthoritativeBlockTriangleCount = publishedTriangles.Count / 3;
        CountMeshEdgeTopology(publishedTriangles,
            out int boundaryEdges,
            out int nonManifoldEdges);
        LastAuthoritativeBlockBoundaryEdgeCount = boundaryEdges;
        LastAuthoritativeBlockNonManifoldEdgeCount = nonManifoldEdges;
        if (runAuthoritativeCyanContinuityAudit && allowContinuityAudit)
            AuditAuthoritativeCyanContinuity(keys, blockVoxels);
        else
            RebuildAuthoritativeCyanCrackOverlay(null, null);
        LastAuthoritativeBlockCacheMergeMilliseconds =
            (float)(((budget != null
                ? budget.GetComputeSecondsSnapshot()
                : Time.realtimeSinceStartupAsDouble) - cacheMergeStart) * 1000.0);
        state.Result = publishedTriangles.Count >= 3;
    }

    private static bool AuthoritativeDirtyBoundaryTouchesNeighbour(
        Vector3Int dirtyKey,
        int offsetX,
        int offsetY,
        int offsetZ,
        IReadOnlyDictionary<Vector3Int, int> dependencyBoundaryMasks)
    {
        // Unknown external schedules remain conservative. The geometry-only tracker
        // supplies a mask containing both the preceding and current zero-crossing
        // footprint for every ordinary New/Changed dirty block.
        if (dependencyBoundaryMasks == null ||
            !dependencyBoundaryMasks.TryGetValue(dirtyKey, out int mask))
            return true;

        int required = 0;
        if (offsetX < 0)
            required |= ScanCoverTsdfSurfaceDirtyTracker.BoundaryNegativeX;
        else if (offsetX > 0)
            required |= ScanCoverTsdfSurfaceDirtyTracker.BoundaryPositiveX;
        if (offsetY < 0)
            required |= ScanCoverTsdfSurfaceDirtyTracker.BoundaryNegativeY;
        else if (offsetY > 0)
            required |= ScanCoverTsdfSurfaceDirtyTracker.BoundaryPositiveY;
        if (offsetZ < 0)
            required |= ScanCoverTsdfSurfaceDirtyTracker.BoundaryNegativeZ;
        else if (offsetZ > 0)
            required |= ScanCoverTsdfSurfaceDirtyTracker.BoundaryPositiveZ;
        return required == 0 || (mask & required) == required;
    }

    private List<ScanCoverStablePlaneRegistry.PlaneConstraint> CollectChangedAuthoritativePlanes(
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> current)
    {
        List<ScanCoverStablePlaneRegistry.PlaneConstraint> changed = new List<ScanCoverStablePlaneRegistry.PlaneConstraint>();
        Dictionary<int, ScanCoverStablePlaneRegistry.PlaneConstraint> previousById =
            new Dictionary<int, ScanCoverStablePlaneRegistry.PlaneConstraint>(_lastAuthoritativePlaneConstraints.Count);
        for (int i = 0; i < _lastAuthoritativePlaneConstraints.Count; i++)
            previousById[_lastAuthoritativePlaneConstraints[i].Id] = _lastAuthoritativePlaneConstraints[i];

        HashSet<int> currentIds = new HashSet<int>();
        for (int i = 0; i < current.Count; i++)
        {
            ScanCoverStablePlaneRegistry.PlaneConstraint plane = current[i];
            currentIds.Add(plane.Id);
            if (!previousById.TryGetValue(plane.Id, out ScanCoverStablePlaneRegistry.PlaneConstraint previous))
            {
                changed.Add(plane);
                continue;
            }

            float normalDot = Mathf.Abs(Vector3.Dot(previous.Normal.normalized, plane.Normal.normalized));
            float planeDistance = Mathf.Abs(previous.Offset - plane.Offset);
            float centerNormalDistance = Mathf.Abs(Vector3.Dot(plane.Center - previous.Center, previous.Normal.normalized));
            if (normalDot < stablePlaneInvalidationNormalDot ||
                Mathf.Max(planeDistance, centerNormalDistance) > stablePlaneInvalidationDistanceMeters ||
                Mathf.Abs(previous.Radius - plane.Radius) > stablePlaneInvalidationRadiusMeters)
            {
                // Include both footprints so a moved or contracted plane also releases
                // geometry that belonged only to its preceding position.
                changed.Add(previous);
                changed.Add(plane);
            }
        }

        for (int i = 0; i < _lastAuthoritativePlaneConstraints.Count; i++)
        {
            ScanCoverStablePlaneRegistry.PlaneConstraint previous = _lastAuthoritativePlaneConstraints[i];
            if (!currentIds.Contains(previous.Id))
                changed.Add(previous);
        }
        return changed;
    }

    private bool AuthoritativeBlockTouchesChangedPlane(
        Vector3Int blockKey,
        float patchSize,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> changedPlanes)
    {
        if (changedPlanes == null || changedPlanes.Count == 0)
            return false;
        Vector3 blockCenter = _volumeOriginWorld + new Vector3(
            (blockKey.x + 0.5f) * patchSize,
            (blockKey.y + 0.5f) * patchSize,
            (blockKey.z + 0.5f) * patchSize);
        float halfDiagonal = patchSize * 0.866026f;
        for (int i = 0; i < changedPlanes.Count; i++)
        {
            ScanCoverStablePlaneRegistry.PlaneConstraint plane = changedPlanes[i];
            Vector3 normal = plane.Normal.sqrMagnitude > 0.000001f ? plane.Normal.normalized : Vector3.up;
            Vector3 delta = blockCenter - plane.Center;
            float normalDistance = Mathf.Abs(Vector3.Dot(delta, normal));
            if (normalDistance > authoritativeCyanPlaneMaxDistanceMeters + halfDiagonal)
                continue;
            Vector3 tangent = delta - normal * Vector3.Dot(delta, normal);
            if (tangent.magnitude <= plane.Radius + authoritativeCyanPlaneTangentialPaddingMeters + halfDiagonal)
                return true;
        }
        return false;
    }

    private void SnapshotAuthoritativePlaneConstraints(
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> current)
    {
        _lastAuthoritativePlaneConstraints.Clear();
        if (current == null)
            return;
        for (int i = 0; i < current.Count; i++)
            _lastAuthoritativePlaneConstraints.Add(current[i]);
    }

