    private IEnumerator BuildPlaneConstrainedZeroCrossShadowRoutine(
        IReadOnlyDictionary<Vector3Int, AuthoritativeTsdfBlockMesh> extractedCandidates,
        IReadOnlyDictionary<Vector3Int, AuthoritativeTsdfBlockMesh> relaxedRawCandidates,
        IReadOnlyDictionary<Vector3Int, bool> directAttempts,
        IReadOnlyCollection<Vector3Int> clearedBlockKeys,
        int blockVoxels,
        CooperativeRebuildBudget budget)
    {
        if (!enablePlaneConstrainedZeroCrossShadow ||
            extractedCandidates == null || directAttempts == null)
            yield break;

        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes =
            GetIncrementalPlaneConstraintsWithColdStartCandidates();
        if (planes == null || planes.Count == 0)
            yield break;
        if (_authoritativeCyanLastPlaneByVertex.Count == 0)
        {
            // No new plane ownership is available this batch.  Preserve and
            // re-audit the existing scene ledger instead of replacing it with raw
            // unowned geometry or making RESULT disappear for one frame.
            IEnumerator preservedCommitRoutine = CommitPersistentResultLedgerRoutine(
                null, null, clearedBlockKeys, planes, blockVoxels, budget);
            while (preservedCommitRoutine.MoveNext())
                yield return preservedCommitRoutine.Current;
            yield break;
        }

        // The trial is deliberately local: Dirty blocks plus the one-block halo
        // required by Surface Nets. Cached blocks elsewhere remain untouched.
        HashSet<Vector3Int> localKeys = new HashSet<Vector3Int>();
        foreach (KeyValuePair<Vector3Int, bool> pair in directAttempts)
        {
            if (!pair.Value)
                continue;
            for (int z = -1; z <= 1; z++)
            for (int y = -1; y <= 1; y++)
            for (int x = -1; x <= 1; x++)
            {
                Vector3Int key = pair.Key + new Vector3Int(x, y, z);
                if (extractedCandidates.ContainsKey(key))
                    localKeys.Add(key);
            }
        }
        // The old policy's wider intake is restored only into this shadow ledger.
        // It does not bypass the authoritative block commit or any hard topology gate.
        if (enableLegacyRelaxedCandidateShadow)
        {
            foreach (Vector3Int key in extractedCandidates.Keys)
                localKeys.Add(key);
        }
        List<Vector3> shadowVertices = new List<Vector3>(4096);
        List<int> shadowTriangles = new List<int>(8192);
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> triangleLedger =
            new List<PlaneConstrainedZeroCrossTriangleLedgerEntry>(8192);
        Dictionary<AuthoritativeCellComponentKey, Vector3> rawPositionSums =
            new Dictionary<AuthoritativeCellComponentKey, Vector3>();
        Dictionary<AuthoritativeCellComponentKey, int> rawPositionCounts =
            new Dictionary<AuthoritativeCellComponentKey, int>();
        foreach (Vector3Int localKey in localKeys)
        {
            if (budget != null && budget.ShouldYield())
            {
                budget.CompleteSliceForYield();
                yield return null;
                budget.Resume();
            }
            AuthoritativeTsdfBlockMesh rawBlock = relaxedRawCandidates != null &&
                                                   relaxedRawCandidates.TryGetValue(localKey, out AuthoritativeTsdfBlockMesh relaxedRaw)
                ? relaxedRaw
                : extractedCandidates[localKey];
            for (int vertexIndex = 0;
                 vertexIndex < rawBlock.Vertices.Count && vertexIndex < rawBlock.VertexKeys.Count;
                 vertexIndex++)
            {
                AuthoritativeCellComponentKey vertexKey = rawBlock.VertexKeys[vertexIndex];
                rawPositionSums.TryGetValue(vertexKey, out Vector3 sum);
                rawPositionSums[vertexKey] = sum + rawBlock.Vertices[vertexIndex];
                rawPositionCounts.TryGetValue(vertexKey, out int count);
                rawPositionCounts[vertexKey] = count + 1;
            }
        }
        float residualBeforeSum = 0f;
        float residualAfterSum = 0f;
        int residualSamples = 0;

        foreach (Vector3Int key in localKeys)
        {
            if (budget != null && budget.ShouldYield())
            {
                budget.CompleteSliceForYield();
                yield return null;
                budget.Resume();
            }
            LastPlaneConstrainedZeroCrossShadowAttemptedBlockCount++;
            bool direct = directAttempts.TryGetValue(key, out bool directValue) && directValue;
            AuthoritativeTsdfBlockMesh raw = relaxedRawCandidates != null &&
                                              relaxedRawCandidates.TryGetValue(key, out AuthoritativeTsdfBlockMesh relaxedRaw)
                ? relaxedRaw
                : extractedCandidates[key];
            AuthoritativeBlockTopologyStats rawTopology = AnalyzeAuthoritativeBlockTopology(raw);
            PlaneConstrainedZeroCrossShadowStats stats = new PlaneConstrainedZeroCrossShadowStats();
            bool hasShadow = TryExtractAuthoritativeTsdfBlock(
                key, blockVoxels, out AuthoritativeTsdfBlockMesh constrained,
                _authoritativeCyanLastPlaneByVertex, planes, stats, false);

            int unownedTriangles = 0;
            int mixedOneTriangles = 0;
            int mixedTwoTriangles = 0;
            int fullyOwnedTriangles = 0;
            int baselineUnownedTriangles = 0;
            int baselineMixedOneTriangles = 0;
            int baselineMixedTwoTriangles = 0;
            int baselineFullyOwnedTriangles = 0;
            for (int i = 0; i + 2 < raw.Triangles.Count; i += 3)
            {
                int owned = 0;
                if (_authoritativeCyanLastAppliedPlaneKeys.Contains(raw.VertexKeys[raw.Triangles[i]])) owned++;
                if (_authoritativeCyanLastAppliedPlaneKeys.Contains(raw.VertexKeys[raw.Triangles[i + 1]])) owned++;
                if (_authoritativeCyanLastAppliedPlaneKeys.Contains(raw.VertexKeys[raw.Triangles[i + 2]])) owned++;
                if (owned == 0) baselineUnownedTriangles++;
                else if (owned == 1) baselineMixedOneTriangles++;
                else if (owned == 2) baselineMixedTwoTriangles++;
                else baselineFullyOwnedTriangles++;
            }
            if (hasShadow)
            {
                for (int i = 0; i + 2 < constrained.Triangles.Count; i += 3)
                {
                    AuthoritativeCellComponentKey keyA = constrained.VertexKeys[constrained.Triangles[i]];
                    AuthoritativeCellComponentKey keyB = constrained.VertexKeys[constrained.Triangles[i + 1]];
                    AuthoritativeCellComponentKey keyC = constrained.VertexKeys[constrained.Triangles[i + 2]];
                    int planeA = GetAppliedZeroCrossShadowPlaneId(keyA, stats, planes);
                    int planeB = GetAppliedZeroCrossShadowPlaneId(keyB, stats, planes);
                    int planeC = GetAppliedZeroCrossShadowPlaneId(keyC, stats, planes);
                    int owned = (planeA >= 0 ? 1 : 0) + (planeB >= 0 ? 1 : 0) + (planeC >= 0 ? 1 : 0);
                    if (owned == 0) unownedTriangles++;
                    else if (owned == 1) mixedOneTriangles++;
                    else if (owned == 2) mixedTwoTriangles++;
                    else fullyOwnedTriangles++;

                    if (planeA >= 0 && planeA == planeB && planeB == planeC)
                    {
                        stats.GetPlane(planeA).FullTriangles++;
                    }
                    else
                    {
                        if (planeA >= 0) stats.GetPlane(planeA).MixedTriangles++;
                        if (planeB >= 0 && planeB != planeA) stats.GetPlane(planeB).MixedTriangles++;
                        if (planeC >= 0 && planeC != planeA && planeC != planeB)
                            stats.GetPlane(planeC).MixedTriangles++;
                    }
                }
            }

            AuthoritativeBlockTopologyStats shadowTopology = hasShadow
                ? AnalyzeAuthoritativeBlockTopology(constrained)
                : new AuthoritativeBlockTopologyStats();
            bool accepted = hasShadow && shadowTopology.NonManifoldEdges == 0 &&
                            shadowTopology.DuplicateTriangles == 0 &&
                            shadowTopology.DegenerateTriangles == 0;
            string rollbackReason = !hasShadow
                ? "empty"
                : shadowTopology.NonManifoldEdges > 0
                    ? "nonmanifold"
                    : shadowTopology.DuplicateTriangles > 0
                        ? "duplicate"
                        : shadowTopology.DegenerateTriangles > 0 ? "degenerate" : "none";

            LastPlaneConstrainedZeroCrossShadowOwnedVertexCount += stats.OwnedVertices;
            LastPlaneConstrainedZeroCrossShadowMovedVertexCount += stats.MovedVertices;
            LastPlaneConstrainedZeroCrossShadowOverflowVertexCount += stats.OverflowVertices;
            LastPlaneConstrainedZeroCrossBaselineMixedOneTriangleCount += baselineMixedOneTriangles;
            LastPlaneConstrainedZeroCrossBaselineMixedTwoTriangleCount += baselineMixedTwoTriangles;
            residualBeforeSum += stats.ResidualBeforeSum;
            residualAfterSum += stats.ResidualAfterSum;
            residualSamples += stats.OwnedVertices;
            if (accepted)
            {
                LastPlaneConstrainedZeroCrossShadowAcceptedBlockCount++;
                LastPlaneConstrainedZeroCrossShadowTriangleCount += constrained.Triangles.Count / 3;
                LastPlaneConstrainedZeroCrossShadowMixedOneTriangleCount += mixedOneTriangles;
                LastPlaneConstrainedZeroCrossShadowMixedTwoTriangleCount += mixedTwoTriangles;
                LastPlaneConstrainedZeroCrossShadowFullyOwnedTriangleCount += fullyOwnedTriangles;
                int baseVertex = shadowVertices.Count;
                shadowVertices.AddRange(constrained.Vertices);
                for (int i = 0; i < constrained.Triangles.Count; i++)
                    shadowTriangles.Add(baseVertex + constrained.Triangles[i]);
                CollectPlaneConstrainedZeroCrossTriangleLedger(
                    triangleLedger, key, direct, constrained, planes, stats,
                    rawPositionSums, rawPositionCounts, "strict_constrained", "none");
            }
            else
            {
                LastPlaneConstrainedZeroCrossShadowRollbackBlockCount++;
                // Preserve rejected/empty broad candidates for diagnosis.  Topology
                // failures are forced red; an empty constrained re-extraction may
                // still become an orange atomic plane projection after hard audit.
                string forcedHardReject = rollbackReason == "nonmanifold" ||
                                          rollbackReason == "duplicate" ||
                                          rollbackReason == "degenerate"
                    ? "block_" + rollbackReason
                    : "none";
                CollectPlaneConstrainedZeroCrossTriangleLedger(
                    triangleLedger, key, direct, raw, planes, stats,
                    rawPositionSums, rawPositionCounts,
                    "legacy_relaxed_" + rollbackReason, forcedHardReject);
            }

            if (_planeConstrainedZeroCrossShadowRows != null)
            {
                _planeConstrainedZeroCrossShadowRows
                    .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
                    .Append(key.x).Append(',').Append(key.y).Append(',').Append(key.z).Append(',')
                    .Append(direct ? 1 : 0).Append(',')
                    .Append(raw.Triangles.Count / 3).Append(',')
                    .Append(hasShadow ? constrained.Triangles.Count / 3 : 0).Append(',')
                    .Append(rawTopology.BoundaryEdges).Append(',')
                    .Append(hasShadow ? shadowTopology.BoundaryEdges : 0).Append(',')
                    .Append(rawTopology.NonManifoldEdges).Append(',')
                    .Append(hasShadow ? shadowTopology.NonManifoldEdges : 0).Append(',')
                    .Append(stats.OwnedVertices).Append(',').Append(stats.MovedVertices).Append(',')
                    .Append(stats.OverflowVertices).Append(',')
                    .Append(baselineUnownedTriangles).Append(',')
                    .Append(baselineMixedOneTriangles).Append(',')
                    .Append(baselineMixedTwoTriangles).Append(',')
                    .Append(baselineFullyOwnedTriangles).Append(',')
                    .Append(unownedTriangles).Append(',')
                    .Append(mixedOneTriangles).Append(',').Append(mixedTwoTriangles).Append(',')
                    .Append(fullyOwnedTriangles).Append(',')
                    .Append((stats.OwnedVertices > 0 ? stats.ResidualBeforeSum / stats.OwnedVertices : 0f)
                        .ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                    .Append((stats.OwnedVertices > 0 ? stats.ResidualAfterSum / stats.OwnedVertices : 0f)
                        .ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                    .Append(accepted ? 1 : 0).Append(',').Append(rollbackReason).AppendLine();
            }
            AppendPlaneConstrainedZeroCrossByPlaneRows(
                key, direct, planes, stats, accepted, rollbackReason);
        }

        LastPlaneConstrainedZeroCrossShadowResidualBeforeMeters = residualSamples > 0
            ? residualBeforeSum / residualSamples : 0f;
        LastPlaneConstrainedZeroCrossShadowResidualAfterMeters = residualSamples > 0
            ? residualAfterSum / residualSamples : 0f;
        CountMeshEdgeTopology(shadowTriangles,
            out int boundaryEdges, out int nonManifoldEdges);
        LastPlaneConstrainedZeroCrossShadowBoundaryEdgeCount = boundaryEdges;
        LastPlaneConstrainedZeroCrossShadowNonManifoldEdgeCount = nonManifoldEdges;
        IEnumerator commitRoutine = CommitPersistentResultLedgerRoutine(
            triangleLedger, localKeys, clearedBlockKeys, planes, blockVoxels, budget);
        while (commitRoutine.MoveNext())
            yield return commitRoutine.Current;
    }

    private int CountPersistentResultLedgerTriangles()
    {
        int count = 0;
        foreach (List<PlaneConstrainedZeroCrossTriangleLedgerEntry> blockLedger
                 in _persistentResultLedgerByBlock.Values)
            count += blockLedger != null ? blockLedger.Count : 0;
        return count;
    }

    private IEnumerator CommitPersistentResultLedgerRoutine(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> batchLedger,
        IReadOnlyCollection<Vector3Int> replacedBlockKeys,
        IReadOnlyCollection<Vector3Int> clearedBlockKeys,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        int blockVoxels,
        CooperativeRebuildBudget budget)
    {
        LastPersistentResultLedgerBlocksBefore = _persistentResultLedgerByBlock.Count;
        LastPersistentResultLedgerTrianglesBefore = CountPersistentResultLedgerTriangles();
        LastPersistentResultLedgerBlocksReplaced = 0;
        LastPersistentResultLedgerBlocksRemoved = 0;
        HashSet<Vector3Int> beforeKeys =
            new HashSet<Vector3Int>(_persistentResultLedgerByBlock.Keys);
        HashSet<Vector3Int> mutatedKeys = new HashSet<Vector3Int>();

        if (clearedBlockKeys != null)
        {
            foreach (Vector3Int key in clearedBlockKeys)
            {
                if (budget != null && budget.ShouldYield())
                {
                    budget.CompleteSliceForYield();
                    yield return null;
                    budget.Resume();
                }
                if (_persistentResultLedgerByBlock.Remove(key))
                {
                    LastPersistentResultLedgerBlocksRemoved++;
                    mutatedKeys.Add(key);
                }
            }
        }

        Dictionary<Vector3Int, List<PlaneConstrainedZeroCrossTriangleLedgerEntry>> batchByBlock =
            new Dictionary<Vector3Int, List<PlaneConstrainedZeroCrossTriangleLedgerEntry>>();
        if (batchLedger != null)
        {
            for (int i = 0; i < batchLedger.Count; i++)
            {
                if ((i & 127) == 0 && budget != null && budget.ShouldYield())
                {
                    budget.CompleteSliceForYield();
                    yield return null;
                    budget.Resume();
                }
                PlaneConstrainedZeroCrossTriangleLedgerEntry entry = batchLedger[i];
                if (!batchByBlock.TryGetValue(entry.Block,
                        out List<PlaneConstrainedZeroCrossTriangleLedgerEntry> blockEntries))
                {
                    blockEntries = new List<PlaneConstrainedZeroCrossTriangleLedgerEntry>();
                    batchByBlock[entry.Block] = blockEntries;
                }
                blockEntries.Add(entry);
            }
        }

        if (replacedBlockKeys != null)
        {
            foreach (Vector3Int key in replacedBlockKeys)
            {
                if (budget != null && budget.ShouldYield())
                {
                    budget.CompleteSliceForYield();
                    yield return null;
                    budget.Resume();
                }
                if (batchByBlock.TryGetValue(key,
                        out List<PlaneConstrainedZeroCrossTriangleLedgerEntry> replacement) &&
                    replacement.Count > 0)
                {
                    _persistentResultLedgerByBlock[key] = replacement;
                    LastPersistentResultLedgerBlocksReplaced++;
                    mutatedKeys.Add(key);
                }
                else if (_persistentResultLedgerByBlock.Remove(key))
                {
                    // A successfully re-extracted empty block is an atomic deletion.
                    LastPersistentResultLedgerBlocksRemoved++;
                    mutatedKeys.Add(key);
                }
            }
        }

        LastPersistentResultLedgerBlocksAfter = _persistentResultLedgerByBlock.Count;
        LastPersistentResultLedgerBlocksPreserved = 0;
        foreach (Vector3Int key in beforeKeys)
        {
            if (budget != null && budget.ShouldYield())
            {
                budget.CompleteSliceForYield();
                yield return null;
                budget.Resume();
            }
            if (!mutatedKeys.Contains(key) && _persistentResultLedgerByBlock.ContainsKey(key))
                LastPersistentResultLedgerBlocksPreserved++;
        }
        LastPersistentResultLedgerTrianglesAfter = CountPersistentResultLedgerTriangles();

        List<Vector3Int> sortedKeys = new List<Vector3Int>(_persistentResultLedgerByBlock.Keys);
        sortedKeys.Sort((a, b) =>
        {
            int z = a.z.CompareTo(b.z);
            if (z != 0) return z;
            int y = a.y.CompareTo(b.y);
            return y != 0 ? y : a.x.CompareTo(b.x);
        });
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> fullLedger =
            new List<PlaneConstrainedZeroCrossTriangleLedgerEntry>(LastPersistentResultLedgerTrianglesAfter);
        for (int keyIndex = 0; keyIndex < sortedKeys.Count; keyIndex++)
        {
            if (budget != null && budget.ShouldYield())
            {
                budget.CompleteSliceForYield();
                yield return null;
                budget.Resume();
            }
            List<PlaneConstrainedZeroCrossTriangleLedgerEntry> blockEntries =
                _persistentResultLedgerByBlock[sortedKeys[keyIndex]];
            for (int entryIndex = 0; entryIndex < blockEntries.Count; entryIndex++)
            {
                if ((entryIndex & 127) == 0 &&
                    budget != null && budget.ShouldYield())
                {
                    budget.CompleteSliceForYield();
                    yield return null;
                    budget.Resume();
                }
                PlaneConstrainedZeroCrossTriangleLedgerEntry clone =
                    blockEntries[entryIndex].CloneForFinalization();
                clone.LedgerId = fullLedger.Count;
                fullLedger.Add(clone);
            }
        }
        LastPersistentResultLedgerClosureDelta =
            LastPersistentResultLedgerTrianglesAfter - fullLedger.Count;
        IEnumerator finalizeRoutine =
            FinalizePlaneConstrainedZeroCrossTriangleLedgerRoutine(
                fullLedger, planes, blockVoxels, budget);
        while (finalizeRoutine.MoveNext())
            yield return finalizeRoutine.Current;
        IEnumerator publishRoutine =
            RebuildPlaneConstrainedZeroCrossShadowWireBudgetedRoutine(
                fullLedger, budget);
        while (publishRoutine.MoveNext())
            yield return publishRoutine.Current;
    }

    private int GetAppliedZeroCrossShadowPlaneId(
        AuthoritativeCellComponentKey key,
        PlaneConstrainedZeroCrossShadowStats stats,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes)
    {
        if (stats == null || !stats.AppliedKeys.Contains(key) ||
            !_authoritativeCyanLastPlaneByVertex.TryGetValue(key, out int planeIndex) ||
            planes == null || planeIndex < 0 || planeIndex >= planes.Count)
            return -1;
        return planes[planeIndex].Id;
    }

    private void AppendPlaneConstrainedZeroCrossByPlaneRows(
        Vector3Int blockKey,
        bool direct,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        PlaneConstrainedZeroCrossShadowStats stats,
        bool accepted,
        string rollbackReason)
    {
        if (_planeConstrainedZeroCrossByPlaneRows == null || stats == null)
            return;
        foreach (PlaneConstrainedZeroCrossPerPlaneStats planeStats in stats.PerPlane.Values)
        {
            string kind = "unknown";
            for (int i = 0; planes != null && i < planes.Count; i++)
            {
                if (planes[i].Id != planeStats.PlaneId)
                    continue;
                IsAuthoritativeCyanStructuralPlane(planes[i], out kind, out _);
                break;
            }
            planeStats.SignedDistances.Sort();
            float medianSigned = planeStats.SignedDistances.Count > 0
                ? planeStats.SignedDistances[planeStats.SignedDistances.Count / 2]
                : 0f;
            int count = Mathf.Max(1, planeStats.OwnedVertices);
            _planeConstrainedZeroCrossByPlaneRows
                .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
                .Append(planeStats.PlaneId).Append(',').Append(kind).Append(',')
                .Append(blockKey.x).Append(',').Append(blockKey.y).Append(',').Append(blockKey.z).Append(',')
                .Append(direct ? 1 : 0).Append(',')
                .Append(planeStats.OwnedVertices).Append(',')
                .Append(planeStats.MovedVertices).Append(',')
                .Append(planeStats.OverflowVertices).Append(',')
                .Append(planeStats.PositiveSideVertices).Append(',')
                .Append(planeStats.NegativeSideVertices).Append(',')
                .Append((planeStats.SignedDistanceSum / count).ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(medianSigned.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append((planeStats.AbsDistanceBeforeSum / count).ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append((planeStats.AbsDistanceAfterSum / count).ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(planeStats.MaxMove.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(planeStats.FullTriangles).Append(',')
                .Append(planeStats.MixedTriangles).Append(',')
                .Append(accepted ? 1 : 0).Append(',')
                .Append(rollbackReason).AppendLine();
        }
    }

    private void CollectPlaneConstrainedZeroCrossTriangleLedger(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger,
        Vector3Int blockKey,
        bool direct,
        AuthoritativeTsdfBlockMesh mesh,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        PlaneConstrainedZeroCrossShadowStats stats,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, Vector3> rawPositionSums,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, int> rawPositionCounts,
        string candidateSource,
        string forcedHardRejectReason)
    {
        if (ledger == null || mesh == null || planes == null)
            return;
        for (int triangleOffset = 0; triangleOffset + 2 < mesh.Triangles.Count; triangleOffset += 3)
        {
            int ia = mesh.Triangles[triangleOffset];
            int ib = mesh.Triangles[triangleOffset + 1];
            int ic = mesh.Triangles[triangleOffset + 2];
            if (ia < 0 || ib < 0 || ic < 0 ||
                ia >= mesh.Vertices.Count || ib >= mesh.Vertices.Count || ic >= mesh.Vertices.Count ||
                ia >= mesh.VertexKeys.Count || ib >= mesh.VertexKeys.Count || ic >= mesh.VertexKeys.Count)
                continue;

            PlaneConstrainedZeroCrossTriangleLedgerEntry entry =
                new PlaneConstrainedZeroCrossTriangleLedgerEntry
                {
                    LedgerId = ledger.Count,
                    Block = blockKey,
                    Direct = direct,
                    LocalTriangle = triangleOffset / 3,
                    KeyA = mesh.VertexKeys[ia],
                    KeyB = mesh.VertexKeys[ib],
                    KeyC = mesh.VertexKeys[ic],
                    A = mesh.Vertices[ia],
                    B = mesh.Vertices[ib],
                    C = mesh.Vertices[ic],
                    CandidateSource = string.IsNullOrEmpty(candidateSource)
                        ? "strict_constrained" : candidateSource,
                    ForcedHardRejectReason = string.IsNullOrEmpty(forcedHardRejectReason)
                        ? "none" : forcedHardRejectReason
                };
            entry.RawA = GetPlaneLedgerRawPosition(entry.KeyA, entry.A, rawPositionSums, rawPositionCounts);
            entry.RawB = GetPlaneLedgerRawPosition(entry.KeyB, entry.B, rawPositionSums, rawPositionCounts);
            entry.RawC = GetPlaneLedgerRawPosition(entry.KeyC, entry.C, rawPositionSums, rawPositionCounts);
            int sourceIndex = triangleOffset / 3;
            if (sourceIndex >= 0 && sourceIndex < mesh.TriangleSources.Count)
            {
                entry.SourceEdgeStart = mesh.TriangleSources[sourceIndex].EdgeStart;
                entry.SourceAxis = mesh.TriangleSources[sourceIndex].Axis;
            }
            entry.PlaneA = GetAssignedZeroCrossPlaneId(entry.KeyA, planes);
            entry.PlaneB = GetAssignedZeroCrossPlaneId(entry.KeyB, planes);
            entry.PlaneC = GetAssignedZeroCrossPlaneId(entry.KeyC, planes);
            entry.AppliedPlaneA = GetAppliedZeroCrossShadowPlaneId(entry.KeyA, stats, planes);
            entry.AppliedPlaneB = GetAppliedZeroCrossShadowPlaneId(entry.KeyB, stats, planes);
            entry.AppliedPlaneC = GetAppliedZeroCrossShadowPlaneId(entry.KeyC, stats, planes);
            entry.VertexReasonA = GetZeroCrossVertexLedgerReason(entry.KeyA, entry.AppliedPlaneA, stats);
            entry.VertexReasonB = GetZeroCrossVertexLedgerReason(entry.KeyB, entry.AppliedPlaneB, stats);
            entry.VertexReasonC = GetZeroCrossVertexLedgerReason(entry.KeyC, entry.AppliedPlaneC, stats);
            entry.Centroid = (entry.A + entry.B + entry.C) / 3f;
            Vector3 cross = Vector3.Cross(entry.B - entry.A, entry.C - entry.A);
            entry.Area = cross.magnitude * 0.5f;
            entry.Normal = cross.sqrMagnitude > 0.000000001f ? cross.normalized : Vector3.zero;

            int appliedCount = (entry.AppliedPlaneA >= 0 ? 1 : 0) +
                               (entry.AppliedPlaneB >= 0 ? 1 : 0) +
                               (entry.AppliedPlaneC >= 0 ? 1 : 0);
            bool overflow = stats != null &&
                            (stats.OverflowKeys.Contains(entry.KeyA) ||
                             stats.OverflowKeys.Contains(entry.KeyB) ||
                             stats.OverflowKeys.Contains(entry.KeyC));
            bool assignedDifferent = HasDifferentNonNegativePlaneIds(
                entry.PlaneA, entry.PlaneB, entry.PlaneC);
            if (appliedCount == 3 && entry.AppliedPlaneA == entry.AppliedPlaneB &&
                entry.AppliedPlaneB == entry.AppliedPlaneC)
            {
                entry.AtomicClass = "full_same_plane";
                entry.TargetPlaneId = entry.AppliedPlaneA;
                entry.Disposition = "publish_plane";
            }
            else if (overflow)
            {
                entry.AtomicClass = "overflow";
                entry.TargetPlaneId = FirstNonNegative(entry.PlaneA, entry.PlaneB, entry.PlaneC);
                entry.Disposition = "hold_reextract";
                entry.Reason = "vertex_move_overflow";
            }
            else if (assignedDifferent)
            {
                entry.AtomicClass = "cross_plane";
                entry.Disposition = "junction_reextract";
                entry.Reason = "multiple_plane_families";
            }
            else if (appliedCount == 1 || appliedCount == 2)
            {
                entry.AtomicClass = appliedCount == 1 ? "mixed_one" : "mixed_two";
                entry.TargetPlaneId = FirstNonNegative(
                    entry.AppliedPlaneA, entry.AppliedPlaneB, entry.AppliedPlaneC);
                entry.Disposition = "hold_reextract";
                entry.Reason = "partial_plane_application";
            }
            else if (entry.PlaneA >= 0 || entry.PlaneB >= 0 || entry.PlaneC >= 0)
            {
                entry.AtomicClass = "assigned_unapplied";
                entry.TargetPlaneId = FirstNonNegative(entry.PlaneA, entry.PlaneB, entry.PlaneC);
                entry.Disposition = "hold_reextract";
                entry.Reason = "assigned_vertices_not_applied";
            }

            FindNearestStructuralPlaneForLedger(
                entry.Centroid, entry.Normal, planes,
                out int nearestPlaneId, out string nearestKind,
                out float nearestDistance, out float nearestNormalDot,
                out bool nearestInsideExtent, out bool nearestInsideBand);
            entry.NearestPlaneId = nearestPlaneId;
            if (entry.TargetPlaneId < 0 && !assignedDifferent)
                entry.TargetPlaneId = nearestPlaneId;
            if (entry.AtomicClass == "unclassified")
            {
                bool nearStructural = nearestPlaneId >= 0 && nearestInsideExtent && nearestInsideBand;
                entry.AtomicClass = nearStructural ? "unowned_near_structural" : "unowned_nonstructural";
                entry.Disposition = nearStructural ? "hold_reextract" : "publish_nonplanar";
                entry.Reason = nearStructural
                    ? CombineVertexLedgerReasons(entry.VertexReasonA, entry.VertexReasonB, entry.VertexReasonC)
                    : "outside_structural_support";
            }

            if (TryGetPlaneById(planes, entry.TargetPlaneId,
                    out ScanCoverStablePlaneRegistry.PlaneConstraint targetPlane,
                    out string targetKind))
            {
                entry.PlaneKind = targetKind;
                FillPlaneLedgerGeometry(entry, targetPlane);
            }
            else
            {
                entry.PlaneKind = nearestKind;
                entry.NormalDot = nearestNormalDot;
                entry.MeanAbsDistanceBefore = nearestDistance;
                entry.MeanAbsDistanceAfter = nearestDistance;
            }
            ClassifyPlaneLedgerNonplanarCandidate(entry, planes);
            ledger.Add(entry);
        }
    }

    private void ClassifyPlaneLedgerNonplanarCandidate(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes)
    {
        // Confirmed plane-assignment failures are already red. This second channel
        // audits geometry that was published as non-planar near a mature structural
        // candidate which narrowly failed only its coverage qualification.
        if (entry == null || entry.AtomicClass != "unowned_nonstructural" ||
            planes == null || entry.Normal.sqrMagnitude < 0.5f)
            return;

        float bestDistance = float.PositiveInfinity;
        float bestNormalDot = 0f;
        int bestPlaneId = -1;
        string bestKind = "none";
        string bestReject = "none";
        float bestThreshold = planeConstrainedGeometricSuspectMinDistanceMeters;
        for (int i = 0; i < planes.Count; i++)
        {
            ScanCoverStablePlaneRegistry.PlaneConstraint candidate = planes[i];
            bool qualified = IsAuthoritativeCyanStructuralPlane(
                candidate, out string kind, out string reject);
            bool coverageOnlyReject = reject == "horizontal_radius" ||
                                      reject == "horizontal_inliers" ||
                                      reject == "wall_radius" ||
                                      reject == "wall_inliers";
            if ((!qualified && !coverageOnlyReject) || candidate.Normal.sqrMagnitude < 0.5f)
                continue;
            Vector3 normal = candidate.Normal.normalized;
            Vector3 fromCenter = entry.Centroid - candidate.Center;
            float signed = Vector3.Dot(normal, entry.Centroid) + candidate.Offset;
            float distance = Mathf.Abs(signed);
            Vector3 tangent = fromCenter - normal * Vector3.Dot(normal, fromCenter);
            if (tangent.magnitude > candidate.Radius +
                planeConstrainedGeometricSuspectExtentPaddingMeters ||
                distance > planeConstrainedGeometricSuspectMaxDistanceMeters ||
                distance >= bestDistance)
                continue;
            bestDistance = distance;
            bestNormalDot = Mathf.Abs(Vector3.Dot(entry.Normal.normalized, normal));
            bestPlaneId = candidate.Id;
            bestKind = kind;
            bestReject = qualified ? "qualified_unowned" : reject;
            bestThreshold = Mathf.Max(
                planeConstrainedGeometricSuspectMinDistanceMeters,
                Mathf.Max(0f, candidate.Rms) * 3f);
        }

        if (bestPlaneId < 0 ||
            (bestDistance < bestThreshold &&
             bestNormalDot >= planeConstrainedGeometricSuspectMinNormalDot))
            return;
        entry.NonplanarCandidate = true;
        entry.NonplanarCandidatePlaneId = bestPlaneId;
        entry.NonplanarCandidatePlaneKind = bestKind;
        entry.NonplanarCandidateDistance = bestDistance;
        entry.NonplanarCandidateNormalDot = bestNormalDot;
        bool displaced = bestDistance >= bestThreshold;
        bool tilted = bestNormalDot < planeConstrainedGeometricSuspectMinNormalDot;
        entry.NonplanarCandidateReason = displaced && tilted
            ? bestReject + "|distance|normal"
            : displaced ? bestReject + "|distance" : bestReject + "|normal";
    }

    private static Vector3 GetPlaneLedgerRawPosition(
        AuthoritativeCellComponentKey key,
        Vector3 fallback,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, Vector3> sums,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, int> counts)
    {
        if (sums != null && counts != null && sums.TryGetValue(key, out Vector3 sum) &&
            counts.TryGetValue(key, out int count) && count > 0)
            return sum / count;
        return fallback;
    }

    private int GetAssignedZeroCrossPlaneId(
        AuthoritativeCellComponentKey key,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes)
    {
        if (!_authoritativeCyanLastPlaneByVertex.TryGetValue(key, out int planeIndex) ||
            planes == null || planeIndex < 0 || planeIndex >= planes.Count)
            return -1;
        return planes[planeIndex].Id;
    }

    private string GetZeroCrossVertexLedgerReason(
        AuthoritativeCellComponentKey key,
        int appliedPlaneId,
        PlaneConstrainedZeroCrossShadowStats stats)
    {
        if (appliedPlaneId >= 0)
            return "applied";
        if (stats != null && stats.OverflowKeys.Contains(key))
            return "overflow";
        if (_authoritativeCyanLastPlaneByVertex.ContainsKey(key))
            return "assigned_unapplied";
        return _authoritativeCyanLastRejectByVertex.TryGetValue(key, out string reject)
            ? reject
            : "no_plane_evidence";
    }

    private static bool HasDifferentNonNegativePlaneIds(int a, int b, int c)
    {
        int first = FirstNonNegative(a, b, c);
        if (first < 0)
            return false;
        return (a >= 0 && a != first) || (b >= 0 && b != first) || (c >= 0 && c != first);
    }

    private static int FirstNonNegative(int a, int b, int c)
    {
        return a >= 0 ? a : b >= 0 ? b : c;
    }

    private static string CombineVertexLedgerReasons(string a, string b, string c)
    {
        if (a == b && b == c)
            return a;
        return a + "|" + b + "|" + c;
    }

    private bool TryGetPlaneById(
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        int planeId,
        out ScanCoverStablePlaneRegistry.PlaneConstraint plane,
        out string kind)
    {
        plane = default;
        kind = "none";
        for (int i = 0; planes != null && i < planes.Count; i++)
        {
            if (planes[i].Id != planeId)
                continue;
            plane = planes[i];
            IsAuthoritativeCyanStructuralPlane(plane, out kind, out _);
            return true;
        }
        return false;
    }

    private void FindNearestStructuralPlaneForLedger(
        Vector3 point,
        Vector3 surfaceNormal,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        out int planeId,
        out string kind,
        out float distance,
        out float normalDot,
        out bool insideExtent,
        out bool insideBand)
    {
        planeId = -1;
        kind = "none";
        distance = float.PositiveInfinity;
        normalDot = 0f;
        insideExtent = false;
        insideBand = false;
        for (int i = 0; planes != null && i < planes.Count; i++)
        {
            ScanCoverStablePlaneRegistry.PlaneConstraint candidate = planes[i];
            if (!IsAuthoritativeCyanPlaneQualifiedAtPoint(
                    candidate, point, out string candidateKind, out _) ||
                candidate.Normal.sqrMagnitude < 0.5f)
                continue;
            Vector3 normal = candidate.Normal.normalized;
            float candidateDistance = Mathf.Abs(Vector3.Dot(normal, point) + candidate.Offset);
            if (candidateDistance >= distance)
                continue;
            Vector3 fromCenter = point - candidate.Center;
            Vector3 tangent = fromCenter - normal * Vector3.Dot(normal, fromCenter);
            planeId = candidate.Id;
            kind = candidateKind;
            distance = candidateDistance;
            normalDot = surfaceNormal.sqrMagnitude > 0.5f
                ? Mathf.Abs(Vector3.Dot(surfaceNormal.normalized, normal))
                : 0f;
            insideExtent = tangent.magnitude <=
                           candidate.Radius + authoritativeCyanPlaneTangentialPaddingMeters;
            insideBand = candidateDistance <= GetAuthoritativeCyanPlaneDistanceLimit(candidate, true);
        }
    }

    private static void FillPlaneLedgerGeometry(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry,
        ScanCoverStablePlaneRegistry.PlaneConstraint plane)
    {
        Vector3 normal = plane.Normal.sqrMagnitude > 0.5f ? plane.Normal.normalized : Vector3.up;
        Vector3 reference = Mathf.Abs(Vector3.Dot(normal, Vector3.up)) < 0.9f
            ? Vector3.up
            : Vector3.right;
        Vector3 uAxis = Vector3.Cross(reference, normal).normalized;
        Vector3 vAxis = Vector3.Cross(normal, uAxis).normalized;
        Vector3 fromCenter = entry.Centroid - plane.Center;
        entry.PlaneU = Vector3.Dot(fromCenter, uAxis);
        entry.PlaneV = Vector3.Dot(fromCenter, vAxis);
        float da = Vector3.Dot(normal, entry.RawA) + plane.Offset;
        float db = Vector3.Dot(normal, entry.RawB) + plane.Offset;
        float dc = Vector3.Dot(normal, entry.RawC) + plane.Offset;
        float aa = Vector3.Dot(normal, entry.A) + plane.Offset;
        float ab = Vector3.Dot(normal, entry.B) + plane.Offset;
        float ac = Vector3.Dot(normal, entry.C) + plane.Offset;
        entry.MeanSignedDistanceBefore = (da + db + dc) / 3f;
        entry.MinSignedDistanceBefore = Mathf.Min(da, Mathf.Min(db, dc));
        entry.MaxSignedDistanceBefore = Mathf.Max(da, Mathf.Max(db, dc));
        entry.MeanAbsDistanceBefore = (Mathf.Abs(da) + Mathf.Abs(db) + Mathf.Abs(dc)) / 3f;
        entry.MeanAbsDistanceAfter = (Mathf.Abs(aa) + Mathf.Abs(ab) + Mathf.Abs(ac)) / 3f;
        entry.NormalDot = entry.Normal.sqrMagnitude > 0.5f
            ? Mathf.Abs(Vector3.Dot(entry.Normal, normal))
            : 0f;
    }

    private IEnumerator FinalizePlaneConstrainedZeroCrossTriangleLedgerRoutine(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        int blockVoxels,
        CooperativeRebuildBudget budget)
    {
        if (ledger == null)
            ledger = new List<PlaneConstrainedZeroCrossTriangleLedgerEntry>();
        LastPlaneConstrainedZeroCrossLedgerTriangleCount = ledger != null ? ledger.Count : 0;
        double semanticSubphaseStart = Time.realtimeSinceStartupAsDouble;

        Dictionary<AuthoritativeCanonicalEdgeKey, List<int>> edgeTriangles =
            new Dictionary<AuthoritativeCanonicalEdgeKey, List<int>>(ledger.Count * 2);
        for (int i = 0; i < ledger.Count; i++)
        {
            AddPlaneLedgerEdge(edgeTriangles, MakeAuthoritativeCanonicalEdge(ledger[i].KeyA, ledger[i].KeyB), i);
            AddPlaneLedgerEdge(edgeTriangles, MakeAuthoritativeCanonicalEdge(ledger[i].KeyB, ledger[i].KeyC), i);
            AddPlaneLedgerEdge(edgeTriangles, MakeAuthoritativeCanonicalEdge(ledger[i].KeyC, ledger[i].KeyA), i);
        }

        int[] meshParents = CreatePlaneLedgerParents(ledger.Count);
        int[] issueParents = CreatePlaneLedgerParents(ledger.Count);
        foreach (List<int> attached in edgeTriangles.Values)
        {
            if (attached.Count == 1)
            {
                ledger[attached[0]].Boundary = true;
                continue;
            }
            for (int i = 1; i < attached.Count; i++)
            {
                UnionPlaneLedger(meshParents, attached[0], attached[i]);
                if (SamePlaneLedgerIssueFamily(ledger[attached[0]], ledger[attached[i]]))
                    UnionPlaneLedger(issueParents, attached[0], attached[i]);
            }
        }

        Dictionary<int, int> meshComponentIds = new Dictionary<int, int>();
        Dictionary<int, int> issueComponentIds = new Dictionary<int, int>();
        for (int i = 0; i < ledger.Count; i++)
        {
            int meshRoot = FindPlaneLedgerRoot(meshParents, i);
            if (!meshComponentIds.TryGetValue(meshRoot, out int meshComponent))
            {
                meshComponent = meshComponentIds.Count;
                meshComponentIds[meshRoot] = meshComponent;
            }
            ledger[i].MeshComponentId = meshComponent;

            int issueRoot = FindPlaneLedgerRoot(issueParents, i);
            if (!issueComponentIds.TryGetValue(issueRoot, out int issueComponent))
            {
                issueComponent = issueComponentIds.Count;
                issueComponentIds[issueRoot] = issueComponent;
            }
            ledger[i].IssueComponentId = issueComponent;
            if (ledger[i].Boundary)
                LastPlaneConstrainedZeroCrossLedgerBoundaryTriangleCount++;
        }

        LastPlaneLedgerTopologyMilliseconds =
            (float)((Time.realtimeSinceStartupAsDouble - semanticSubphaseStart) * 1000.0);
        if (budget != null && budget.ShouldYield())
        {
            budget.CompleteSliceForYield();
            yield return null;
            budget.Resume();
        }
        semanticSubphaseStart = Time.realtimeSinceStartupAsDouble;
        AuditIndependentStructuralEvidence(ledger, planes);
        LastPlaneLedgerIndependentAuditMilliseconds =
            (float)((Time.realtimeSinceStartupAsDouble - semanticSubphaseStart) * 1000.0);
        if (budget != null && budget.ShouldYield())
        {
            budget.CompleteSliceForYield();
            yield return null;
            budget.Resume();
        }
        semanticSubphaseStart = Time.realtimeSinceStartupAsDouble;
        AuditPublishedYellowFallback(ledger, edgeTriangles);
        AuditPublishedYellowIsolatedComponents(ledger, edgeTriangles);
        AuditPublishedNonplanarNearestCandidates(ledger, planes);
        LastPlaneLedgerYellowAuditMilliseconds =
            (float)((Time.realtimeSinceStartupAsDouble - semanticSubphaseStart) * 1000.0);
        if (budget != null && budget.ShouldYield())
        {
            budget.CompleteSliceForYield();
            yield return null;
            budget.Resume();
        }
        semanticSubphaseStart = Time.realtimeSinceStartupAsDouble;
        double relaxedAuditComputeStart = budget != null
            ? budget.GetComputeSecondsSnapshot()
            : semanticSubphaseStart;
        IEnumerator relaxedAuditRoutine = AuditLegacyRelaxedCandidateShadowRoutine(
            ledger, planes, edgeTriangles, budget);
        while (relaxedAuditRoutine.MoveNext())
            yield return relaxedAuditRoutine.Current;
        RebuildConfirmedComplexLeaseLedger(ledger);
        LastPlaneLedgerRelaxedAuditMilliseconds =
            budget != null
                ? (float)((budget.GetComputeSecondsSnapshot() - relaxedAuditComputeStart) * 1000.0)
                : (float)((Time.realtimeSinceStartupAsDouble - semanticSubphaseStart) * 1000.0);
        if (budget != null && budget.ShouldYield())
        {
            budget.CompleteSliceForYield();
            yield return null;
            budget.Resume();
        }
        semanticSubphaseStart = Time.realtimeSinceStartupAsDouble;
        for (int i = 0; i < ledger.Count; i++)
        {
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[i];
            if (IsPlaneLedgerProblem(entry))
            {
                LastPlaneConstrainedZeroCrossLedgerProblemTriangleCount++;
                LastPlaneConstrainedZeroCrossHeldTriangleCount++;
            }
            if (entry.Disposition == "publish_plane")
            {
                LastPlaneConstrainedZeroCrossPublishedStructuralTriangleCount++;
                if (entry.GeometricSuspect)
                    LastPlaneConstrainedZeroCrossPublishedSuspectTriangleCount++;
                else
                    LastPlaneConstrainedZeroCrossPublishedHealthyTriangleCount++;
            }
            else if (entry.Disposition == "publish_nonplanar")
            {
                LastPlaneConstrainedZeroCrossPublishedNonplanarTriangleCount++;
                if (entry.NonplanarCandidate)
                    LastPlaneConstrainedZeroCrossNonplanarCandidateTriangleCount++;
            }
            else if (!IsPlaneLedgerProblem(entry))
            {
                LastPlaneConstrainedZeroCrossUnclassifiedTriangleCount++;
            }
            if (entry.GeometricSuspect)
                LastPlaneConstrainedZeroCrossLedgerGeometricSuspectTriangleCount++;
        }
        LastPlaneConstrainedZeroCrossLedgerMeshComponentCount = meshComponentIds.Count;
        LastPlaneConstrainedZeroCrossLedgerProblemComponentCount = CountPlaneLedgerProblemComponents(ledger);
        int classified = LastPlaneConstrainedZeroCrossPublishedHealthyTriangleCount +
                         LastPlaneConstrainedZeroCrossPublishedSuspectTriangleCount +
                         LastPlaneConstrainedZeroCrossHeldTriangleCount +
                         LastPlaneConstrainedZeroCrossPublishedNonplanarTriangleCount +
                         LastPlaneConstrainedZeroCrossUnclassifiedTriangleCount;
        LastPlaneConstrainedZeroCrossClassificationClosureDelta = ledger.Count - classified;

        List<PlaneSupportCellLedgerEntry> supportCells =
            enableLowOverheadPerformanceMeasurement
                ? new List<PlaneSupportCellLedgerEntry>()
                : BuildPlaneSupportCellLedger(ledger, planes, blockVoxels);

        // Keep the finalized, read-only presentation inputs so an A-button view change
        // can rebuild only the small wire meshes without touching reconstruction state.
        _lastOutputDisplayTriangleLedger = ledger;
        _lastOutputDisplaySupportCellLedger = supportCells;
        LastPlaneLedgerClassificationMilliseconds =
            (float)((Time.realtimeSinceStartupAsDouble - semanticSubphaseStart) * 1000.0);
        semanticSubphaseStart = Time.realtimeSinceStartupAsDouble;

        if (!enableLowOverheadPerformanceMeasurement)
        {
            AppendPlaneDiagnosticCameraRows(Camera.main);
            AppendPlaneConstrainedZeroCrossTriangleLedgerRows(ledger);
            AppendHeldToProvisionalRows(ledger);
            AppendPlaneConstrainedZeroCrossTriangleScreenRows(ledger);
            AppendPlaneConstrainedZeroCrossComponentRows(ledger, false);
            AppendPlaneConstrainedZeroCrossComponentRows(ledger, true);
            BuildStablePlaneIdentityAudit(ledger, planes, edgeTriangles);
            AppendPlaneSupportCellLedgerRows(supportCells);
            RebuildStablePlaneSupportReferenceWire(planes, supportCells);
            RebuildPlaneConstrainedZeroCrossIssueOverlay(ledger, supportCells);
        }
        else if (showPlaneConstrainedZeroCrossIssueOverlay)
        {
            RebuildPlaneConstrainedZeroCrossIssueOverlay(ledger, supportCells);
        }
        LastPlaneLedgerPresentationMilliseconds =
            (float)((Time.realtimeSinceStartupAsDouble - semanticSubphaseStart) * 1000.0);
    }

    private IEnumerator AuditLegacyRelaxedCandidateShadowRoutine(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        Dictionary<AuthoritativeCanonicalEdgeKey, List<int>> edgeTriangles,
        CooperativeRebuildBudget budget)
    {
        if (ledger == null)
            yield break;
        LastRelaxedCandidateShadowTriangleCount = ledger.Count;
        _claimedConfirmedComplexLeaseKeys.Clear();
        _claimedComplexCandidateProbation.Clear();
        _complexCandidateProbationEpoch++;
        LastConfirmedComplexLeaseBeforeCount = CountConfirmedComplexLeases();
        LastConfirmedComplexNewAdmissionCount = 0;
        LastConfirmedComplexRenewedCount = 0;
        LastConfirmedComplexRenewalMissCount = 0;
        LastConfirmedComplexLeaseGraceRetainedCount = 0;
        LastConfirmedComplexLeaseGraceReacquiredCount = 0;
        LastConfirmedComplexRenewedDespiteCandidateCount = 0;
        LastComplexCandidateProbationBeforeCount = CountComplexCandidateProbation();
        LastComplexCandidateProbationObservedCount = 0;
        LastComplexCandidateProbationPromotedCount = 0;
        LastComplexCandidateProbationAfterCount = LastComplexCandidateProbationBeforeCount;
        LastComplexCandidateProbationExpiredCount = 0;
        LastSafeCoverageStructuralObservedCount = 0;
        LastSafeCoverageStructuralPromotedCount = 0;
        LastSafeCoverageComplexObservedCount = 0;
        LastSafeCoverageComplexPromotedCount = 0;
        LastProvisionalStructuralPromotionObservedCount = 0;
        LastProvisionalStructuralPromotedCount = 0;
        for (int i = 0; i < ledger.Count; i++)
        {
            if ((i & 31) == 0 && budget != null && budget.ShouldYield())
            {
                budget.CompleteSliceForYield();
                yield return null;
                budget.Resume();
            }
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[i];
            entry.HardAuditChecked = true;
            entry.HardLegal = true;
            entry.HardRejectReason = "none";
            entry.RelaxedClass = "pending";
            entry.CandidateEvaluationReason = "none";
            entry.HeldReason = "not_member";
            entry.ProvisionalReason = "not_member";
            entry.UnclassifiedReason = "not_member";
            entry.HeldOriginReason = "not_member";
            entry.HeldAssignedVertexCount = 0;
            entry.HeldAppliedVertexCount = 0;
            entry.HeldDistinctAppliedPlaneFamilies = 0;
            entry.HeldRescueEvidence = "not_member";
            entry.HeldRescueIndependentStatus = "not_member";
            entry.HeldKeepDecision = "not_member";
            entry.HeldKeepAction = "not_member";
            entry.HeldRescueMaxRawPlaneDistance = 0f;
            entry.HeldRescuePlaneDistanceLimit = 0f;
            entry.HeldRescueRawNormalDot = 0f;
            entry.HeldRescueNormalDotLimit = 0f;
            entry.HeldRescueProjectedArea = 0f;
            entry.HeldRescueProjectedAreaLimit = 0f;
            entry.WorkingPublishEligible = false;
            entry.HasRelaxedProjection = false;
            entry.RelaxedA = entry.A;
            entry.RelaxedB = entry.B;
            entry.RelaxedC = entry.C;
            entry.ComplexLeaseRenewed = false;
            entry.ComplexLeaseMatch = "none";
            entry.ComplexLeaseCentroidDelta = 0f;
            entry.ComplexLeaseNormalDot = 0f;
            entry.ComplexLeaseAreaRatio = 0f;
            entry.ComplexProbationRounds = 0;
            entry.ComplexProbationStatus = "not_checked";
            entry.CoverageProbationLane = "none";
            entry.ComplexProbationCentroidDelta = 0f;
            entry.ComplexProbationNormalDot = 0f;
            entry.ComplexProbationAreaRatio = 0f;

            if (!enableLegacyRelaxedCandidateShadow)
            {
                if (entry.Disposition == "publish_plane")
                    entry.RelaxedClass = entry.GeometricSuspect ? "provisional_structural" : "formal_structural";
                else if (entry.Disposition == "publish_nonplanar")
                    entry.RelaxedClass = "confirmed_complex";
                else if (IsPlaneLedgerProblem(entry))
                    entry.RelaxedClass = "pending";
                else
                    entry.RelaxedClass = "unclassified";
                entry.WorkingPublishEligible = entry.RelaxedClass == "formal_structural" ||
                                               entry.RelaxedClass == "provisional_structural" ||
                                               entry.RelaxedClass == "confirmed_complex";
                entry.CandidateEvaluationReason = "audit_disabled_" + entry.RelaxedClass;
                CountRelaxedCandidateClass(entry.RelaxedClass);
                continue;
            }

            if (entry.ForcedHardRejectReason != "none")
            {
                MarkRelaxedCandidateIllegal(entry, entry.ForcedHardRejectReason);
                CountRelaxedCandidateClass(entry.RelaxedClass);
                continue;
            }
            if (!Finite(entry.A) || !Finite(entry.B) || !Finite(entry.C) ||
                !Finite(entry.RawA) || !Finite(entry.RawB) || !Finite(entry.RawC))
            {
                MarkRelaxedCandidateIllegal(entry, "nonfinite_geometry");
                CountRelaxedCandidateClass(entry.RelaxedClass);
                continue;
            }
            if (HasRelaxedCandidateNonManifoldEdge(entry, edgeTriangles))
            {
                MarkRelaxedCandidateIllegal(entry, "nonmanifold_edge");
                CountRelaxedCandidateClass(entry.RelaxedClass);
                continue;
            }
            if (entry.AtomicClass == "cross_plane" || entry.Disposition == "junction_reextract")
            {
                MarkRelaxedCandidateIllegal(entry, "wrong_or_cross_plane");
                CountRelaxedCandidateClass(entry.RelaxedClass);
                continue;
            }
            if (entry.AtomicClass == "overflow" || entry.Reason == "vertex_move_overflow")
            {
                MarkRelaxedCandidateIllegal(entry, "vertex_move_overflow");
                CountRelaxedCandidateClass(entry.RelaxedClass);
                continue;
            }
            if (entry.IndependentAuditChecked && !entry.IndependentAuditDiagnosticOnly &&
                entry.IndependentPlaneId >= 0 &&
                entry.TargetPlaneId >= 0 && entry.IndependentPlaneId != entry.TargetPlaneId &&
                entry.IndependentQualification != "none")
            {
                MarkRelaxedCandidateIllegal(entry, "independent_wrong_plane");
                CountRelaxedCandidateClass(entry.RelaxedClass);
                continue;
            }

            if (entry.Disposition == "publish_nonplanar")
            {
                // A previously confirmed hard-legal surface gets first right of
                // renewal. NonplanarCandidate is a noisy per-batch interpretation,
                // not a hard revocation signal; forcing renewed geometry back through
                // probation caused the visible green regression in batch 003.
                if (enableConfirmedComplexCrossRoundRenewal &&
                    TryRenewConfirmedComplexLease(entry))
                {
                    entry.RelaxedClass = "confirmed_complex";
                    entry.CandidateEvaluationReason = "confirmed_complex_renewed|" +
                                                      entry.ComplexLeaseMatch;
                    entry.WorkingPublishEligible = true;
                    LastConfirmedComplexRenewedCount++;
                    if (entry.NonplanarCandidate)
                        LastConfirmedComplexRenewedDespiteCandidateCount++;
                }
                else if (entry.NonplanarCandidate)
                {
                    if (!TryHandleSafeNonplanarCoverageRelease(entry, planes))
                        MarkRelaxedCandidateIllegal(
                            entry,
                            "nonplanar_structural_conflict|" + entry.NonplanarCandidateReason);
                }
                else if (entry.Direct)
                {
                    entry.RelaxedClass = "confirmed_complex";
                    entry.CandidateEvaluationReason = "confirmed_complex_direct_new";
                    entry.WorkingPublishEligible = true;
                    LastConfirmedComplexNewAdmissionCount++;
                }
                else if (enableComplexCandidateCrossRoundProbation &&
                         AdvanceComplexCandidateProbation(
                             entry,
                             "ordinary_complex",
                             complexCandidateProbationRequiredRounds))
                {
                    entry.RelaxedClass = "confirmed_complex";
                    entry.CandidateEvaluationReason = "confirmed_complex_probation_promoted";
                    entry.WorkingPublishEligible = true;
                    LastConfirmedComplexNewAdmissionCount++;
                    LastComplexCandidateProbationPromotedCount++;
                }
                else
                {
                    entry.RelaxedClass = "unclassified";
                    entry.CandidateEvaluationReason = enableComplexCandidateCrossRoundProbation
                        ? "complex_probation_wait|" + entry.ComplexProbationStatus
                        : "non_direct_complex|" + entry.ComplexLeaseMatch;
                    LastConfirmedComplexRenewalMissCount++;
                }
                CountRelaxedCandidateClass(entry.RelaxedClass);
                continue;
            }

            bool structuralCandidate = entry.Disposition == "publish_plane" ||
                                       entry.Disposition == "hold_reextract";
            if (!structuralCandidate)
            {
                entry.RelaxedClass = IsPlaneLedgerProblem(entry) ? "pending" : "unclassified";
                entry.CandidateEvaluationReason = "not_structural_candidate";
                CountRelaxedCandidateClass(entry.RelaxedClass);
                continue;
            }
            if (entry.TargetPlaneId < 0)
            {
                entry.RelaxedClass = IsPlaneLedgerProblem(entry) ? "pending" : "unclassified";
                entry.CandidateEvaluationReason = "missing_target_plane";
                CountRelaxedCandidateClass(entry.RelaxedClass);
                continue;
            }
            if (!TryGetPlaneById(planes, entry.TargetPlaneId,
                    out ScanCoverStablePlaneRegistry.PlaneConstraint targetPlane, out _))
            {
                entry.RelaxedClass = IsPlaneLedgerProblem(entry) ? "pending" : "unclassified";
                entry.CandidateEvaluationReason = "target_plane_not_registered";
                CountRelaxedCandidateClass(entry.RelaxedClass);
                continue;
            }

            if (!TryBuildHardLegalRelaxedProjection(entry, targetPlane, out string projectionReject,
                    out bool outsideExtent))
            {
                entry.CandidateEvaluationReason = projectionReject;
                if (outsideExtent)
                    entry.RelaxedClass = "pending";
                else
                    MarkRelaxedCandidateIllegal(entry, projectionReject);
                CountRelaxedCandidateClass(entry.RelaxedClass);
                continue;
            }

            if (entry.Disposition == "hold_reextract" && enforceHeldRescueKeepPolicy)
            {
                ApplyHeldRescueKeepPolicy(entry);
                TryPromoteProvisionalStructuralAcrossRounds(entry);
                CountRelaxedCandidateClass(entry.RelaxedClass);
                continue;
            }

            bool softEvidenceOnly = entry.GeometricSuspect ||
                                    entry.Disposition != "publish_plane" ||
                                    !entry.IndependentSupportsTarget;
            entry.RelaxedClass = softEvidenceOnly
                ? "provisional_structural" : "formal_structural";
            entry.CandidateEvaluationReason = softEvidenceOnly
                ? BuildProvisionalCandidateReason(entry)
                : "formal_supported";
            entry.WorkingPublishEligible = true;
            TryPromoteProvisionalStructuralAcrossRounds(entry);
            CountRelaxedCandidateClass(entry.RelaxedClass);
        }
        FinalizeComplexCandidateProbationEpoch();
        ClassifyCandidateReasonMemberships(ledger);
        int classified = LastRelaxedCandidateFormalTriangleCount +
                         LastRelaxedCandidateProvisionalTriangleCount +
                         LastRelaxedCandidateComplexTriangleCount +
                         LastRelaxedCandidatePendingTriangleCount +
                         LastRelaxedCandidateIllegalTriangleCount +
                         LastRelaxedCandidateUnclassifiedTriangleCount;
        LastRelaxedCandidateClassificationClosureDelta = ledger.Count - classified;
    }

    private bool TryHandleSafeNonplanarCoverageRelease(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes)
    {
        if (!enableSafeCoverageCrossRoundRelease || entry == null ||
            !entry.NonplanarCandidate)
            return false;

        string reason = entry.NonplanarCandidateReason ?? "none";
        int requiredRounds = Mathf.Clamp(safeCoverageReleaseRequiredRounds, 2, 5);
        if (reason == "near_mature_plane_observation")
        {
            if (entry.NonplanarCandidatePlaneId < 0 ||
                !TryGetPlaneById(
                    planes,
                    entry.NonplanarCandidatePlaneId,
                    out ScanCoverStablePlaneRegistry.PlaneConstraint targetPlane,
                    out string targetKind))
                return false;

            entry.TargetPlaneId = entry.NonplanarCandidatePlaneId;
            entry.PlaneKind = targetKind;
            if (!TryBuildHardLegalRelaxedProjection(
                    entry, targetPlane, out _, out _))
                return false;

            LastSafeCoverageStructuralObservedCount++;
            if (AdvanceComplexCandidateProbation(
                    entry, "safe_near_plane_to_provisional", requiredRounds))
            {
                entry.RelaxedClass = "provisional_structural";
                entry.CandidateEvaluationReason =
                    "safe_coverage_promoted_to_provisional|near_mature_plane_observation";
                entry.WorkingPublishEligible = true;
                LastSafeCoverageStructuralPromotedCount++;
            }
            else
            {
                entry.RelaxedClass = "unclassified";
                entry.CandidateEvaluationReason =
                    "safe_coverage_probation_wait|near_mature_plane_observation|" +
                    entry.ComplexProbationStatus;
            }
            return true;
        }

        bool displacedAndTilted =
            reason.EndsWith("|distance|normal", System.StringComparison.Ordinal);
        if (!displacedAndTilted)
            return false;

        LastSafeCoverageComplexObservedCount++;
        if (AdvanceComplexCandidateProbation(
                entry, "safe_conflict_to_complex", requiredRounds))
        {
            entry.RelaxedClass = "confirmed_complex";
            entry.CandidateEvaluationReason =
                "safe_coverage_promoted_to_complex|" + reason;
            entry.WorkingPublishEligible = true;
            LastSafeCoverageComplexPromotedCount++;
            LastConfirmedComplexNewAdmissionCount++;
        }
        else
        {
            entry.RelaxedClass = "unclassified";
            entry.CandidateEvaluationReason =
                "safe_coverage_probation_wait|" + reason + "|" +
                entry.ComplexProbationStatus;
        }
        return true;
    }

    private void TryPromoteProvisionalStructuralAcrossRounds(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        if (!enableProvisionalStructuralCrossRoundPromotion || entry == null ||
            entry.RelaxedClass != "provisional_structural" ||
            !entry.HardLegal || !entry.WorkingPublishEligible)
            return;

        bool strongHeldRescue =
            entry.Disposition == "hold_reextract" &&
            entry.HeldKeepDecision == "keep" &&
            entry.IndependentSupportsTarget;
        bool cleanGeometricSuspect =
            entry.Disposition == "publish_plane" &&
            entry.CandidateEvaluationReason == "geometric_suspect";
        if (!strongHeldRescue && !cleanGeometricSuspect)
            return;

        LastProvisionalStructuralPromotionObservedCount++;
        if (!AdvanceComplexCandidateProbation(
                entry,
                "provisional_to_formal",
                provisionalStructuralPromotionRequiredRounds))
            return;

        entry.RelaxedClass = "formal_structural";
        entry.CandidateEvaluationReason += "|provisional_cross_round_promoted";
        LastProvisionalStructuralPromotedCount++;
    }

    private int CountConfirmedComplexLeases()
    {
        int count = 0;
        foreach (List<ConfirmedComplexLeaseEntry> leases in _confirmedComplexLeasesByBlock.Values)
            count += leases != null ? leases.Count : 0;
        return count;
    }

    private int CountComplexCandidateProbation()
    {
        int count = 0;
        foreach (List<ComplexCandidateProbationEntry> entries in _complexCandidateProbationByBlock.Values)
            count += entries != null ? entries.Count : 0;
        return count;
    }

    private bool AdvanceComplexCandidateProbation(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry,
        string lane,
        int requiredRounds)
    {
        LastComplexCandidateProbationObservedCount++;
        entry.CoverageProbationLane = string.IsNullOrEmpty(lane)
            ? "ordinary_complex" : lane;
        if (!_complexCandidateProbationByBlock.TryGetValue(
                entry.Block, out List<ComplexCandidateProbationEntry> candidates))
        {
            candidates = new List<ComplexCandidateProbationEntry>();
            _complexCandidateProbationByBlock[entry.Block] = candidates;
        }

        float centroidLimit = Mathf.Max(0.0001f,
            voxelSizeMeters * Mathf.Clamp(confirmedComplexRenewalCentroidToleranceVoxels, 0.25f, 2f));
        float normalLimit = Mathf.Clamp(confirmedComplexRenewalNormalDot, 0.5f, 1f);
        float areaLimit = Mathf.Clamp(confirmedComplexRenewalMinimumAreaRatio, 0.05f, 1f);
        ComplexCandidateProbationEntry best = null;
        float bestScore = float.PositiveInfinity;
        float bestCentroid = 0f;
        float bestNormal = 0f;
        float bestArea = 0f;
        for (int i = 0; i < candidates.Count; i++)
        {
            ComplexCandidateProbationEntry candidate = candidates[i];
            if (candidate.Lane != entry.CoverageProbationLane ||
                candidate.LastSeenEpoch != _complexCandidateProbationEpoch - 1 ||
                _claimedComplexCandidateProbation.Contains(candidate))
                continue;
            float centroid = Vector3.Distance(entry.Centroid, candidate.Centroid);
            float normal = entry.Normal.sqrMagnitude > 0.000001f &&
                           candidate.Normal.sqrMagnitude > 0.000001f
                ? Mathf.Abs(Vector3.Dot(entry.Normal.normalized, candidate.Normal.normalized)) : 0f;
            float maxArea = Mathf.Max(entry.Area, candidate.Area);
            float area = maxArea > 0.00000001f
                ? Mathf.Min(entry.Area, candidate.Area) / maxArea : 0f;
            if (centroid > centroidLimit || normal < normalLimit || area < areaLimit)
                continue;
            bool exact = entry.SourceAxis == candidate.SourceAxis &&
                         entry.SourceEdgeStart == candidate.SourceEdgeStart &&
                         entry.LocalTriangle == candidate.LocalTriangle;
            float score = centroid / centroidLimit + (1f - normal) + (1f - area) - (exact ? 2f : 0f);
            if (score >= bestScore) continue;
            best = candidate;
            bestScore = score;
            bestCentroid = centroid;
            bestNormal = normal;
            bestArea = area;
        }

        bool promoted = false;
        if (best == null)
        {
            best = new ComplexCandidateProbationEntry
            {
                Lane = entry.CoverageProbationLane,
                ConsecutiveRounds = 1
            };
            candidates.Add(best);
            entry.ComplexProbationStatus = "new_trial";
        }
        else
        {
            _claimedComplexCandidateProbation.Add(best);
            best.ConsecutiveRounds++;
            entry.ComplexProbationStatus = "continued_trial";
            promoted = best.ConsecutiveRounds >= Mathf.Clamp(requiredRounds, 2, 5);
            if (promoted) entry.ComplexProbationStatus = "promoted";
        }
        best.SourceEdgeStart = entry.SourceEdgeStart;
        best.SourceAxis = entry.SourceAxis;
        best.LocalTriangle = entry.LocalTriangle;
        best.Centroid = entry.Centroid;
        best.Normal = entry.Normal;
        best.Area = entry.Area;
        best.LastSeenEpoch = _complexCandidateProbationEpoch;
        entry.ComplexProbationRounds = best.ConsecutiveRounds;
        entry.ComplexProbationCentroidDelta = bestCentroid;
        entry.ComplexProbationNormalDot = bestNormal;
        entry.ComplexProbationAreaRatio = bestArea;
        AppendComplexCandidateProbationRow(entry);
        if (promoted)
            candidates.Remove(best);
        return promoted;
    }

    private void FinalizeComplexCandidateProbationEpoch()
    {
        int before = CountComplexCandidateProbation();
        List<Vector3Int> empty = new List<Vector3Int>();
        foreach (KeyValuePair<Vector3Int, List<ComplexCandidateProbationEntry>> pair in
                 _complexCandidateProbationByBlock)
        {
            pair.Value.RemoveAll(candidate =>
                candidate.LastSeenEpoch != _complexCandidateProbationEpoch);
            if (pair.Value.Count == 0) empty.Add(pair.Key);
        }
        for (int i = 0; i < empty.Count; i++)
            _complexCandidateProbationByBlock.Remove(empty[i]);
        LastComplexCandidateProbationAfterCount = CountComplexCandidateProbation();
        LastComplexCandidateProbationExpiredCount = Mathf.Max(
            0, before - LastComplexCandidateProbationAfterCount);
    }

    private void AppendComplexCandidateProbationRow(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        if (_complexCandidateProbationRows == null) return;
        _complexCandidateProbationRows
            .Append(_surfaceDiagnosticCaptureIndex).Append(',')
            .Append(entry.LedgerId).Append(',')
            .Append(entry.CoverageProbationLane).Append(',')
            .Append(entry.Block.x).Append(',').Append(entry.Block.y).Append(',').Append(entry.Block.z).Append(',')
            .Append(entry.SourceEdgeStart.x).Append(',').Append(entry.SourceEdgeStart.y).Append(',')
            .Append(entry.SourceEdgeStart.z).Append(',').Append(entry.SourceAxis).Append(',')
            .Append(entry.LocalTriangle).Append(',').Append(entry.ComplexProbationRounds).Append(',')
            .Append(entry.ComplexProbationStatus).Append(',')
            .Append(AuditFloat(entry.ComplexProbationCentroidDelta)).Append(',')
            .Append(AuditFloat(entry.ComplexProbationNormalDot)).Append(',')
            .Append(AuditFloat(entry.ComplexProbationAreaRatio)).Append(',')
            .Append(AuditFloat(entry.Centroid.x)).Append(',').Append(AuditFloat(entry.Centroid.y)).Append(',')
            .Append(AuditFloat(entry.Centroid.z)).AppendLine();
    }

    private bool TryRenewConfirmedComplexLease(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        if (entry == null || _confirmedComplexLeasesByBlock.Count == 0)
        {
            if (entry != null)
                entry.ComplexLeaseMatch = "no_prior_lease";
            return false;
        }

        float centroidLimit = Mathf.Max(
            0.0001f,
            voxelSizeMeters * Mathf.Clamp(
                confirmedComplexRenewalCentroidToleranceVoxels, 0.25f, 2f));
        float normalLimit = Mathf.Clamp(confirmedComplexRenewalNormalDot, 0.5f, 1f);
        float areaLimit = Mathf.Clamp(confirmedComplexRenewalMinimumAreaRatio, 0.05f, 1f);
        int bestIndex = -1;
        Vector3Int bestBlock = entry.Block;
        ConfirmedComplexLeaseEntry bestLease = null;
        bool bestExactIdentity = false;
        float bestScore = float.PositiveInfinity;
        float bestCentroidDelta = 0f;
        float bestNormalDot = 0f;
        float bestAreaRatio = 0f;
        for (int dz = -1; dz <= 1; dz++)
        for (int dy = -1; dy <= 1; dy++)
        for (int dx = -1; dx <= 1; dx++)
        {
            Vector3Int leaseBlock = entry.Block + new Vector3Int(dx, dy, dz);
            if (!_confirmedComplexLeasesByBlock.TryGetValue(
                    leaseBlock, out List<ConfirmedComplexLeaseEntry> leases) ||
                leases == null)
                continue;
            for (int leaseIndex = 0; leaseIndex < leases.Count; leaseIndex++)
            {
                string claimKey =
                    BuildConfirmedComplexLeaseClaimKey(leaseBlock, leaseIndex);
                if (_claimedConfirmedComplexLeaseKeys.Contains(claimKey))
                    continue;
                ConfirmedComplexLeaseEntry lease = leases[leaseIndex];
                float centroidDelta = Vector3.Distance(entry.Centroid, lease.Centroid);
                float normalDot = entry.Normal.sqrMagnitude > 0.000001f &&
                                  lease.Normal.sqrMagnitude > 0.000001f
                    ? Mathf.Abs(Vector3.Dot(entry.Normal.normalized, lease.Normal.normalized))
                    : 0f;
                float maxArea = Mathf.Max(entry.Area, lease.Area);
                float areaRatio = maxArea > 0.00000001f
                    ? Mathf.Min(entry.Area, lease.Area) / maxArea
                    : 0f;
                if (centroidDelta > centroidLimit ||
                    normalDot < normalLimit ||
                    areaRatio < areaLimit)
                    continue;
                bool exactIdentity =
                    entry.SourceAxis == lease.SourceAxis &&
                    entry.SourceEdgeStart == lease.SourceEdgeStart &&
                    entry.LocalTriangle == lease.LocalTriangle;
                float score =
                    centroidDelta / centroidLimit + (1f - normalDot) + (1f - areaRatio);
                if (exactIdentity)
                    score -= 2f;
                if (bestLease != null && score >= bestScore)
                    continue;
                bestIndex = leaseIndex;
                bestBlock = leaseBlock;
                bestLease = lease;
                bestExactIdentity = exactIdentity;
                bestScore = score;
                bestCentroidDelta = centroidDelta;
                bestNormalDot = normalDot;
                bestAreaRatio = areaRatio;
            }
        }

        if (bestLease == null || bestIndex < 0)
        {
            entry.ComplexLeaseMatch = "nearby_lease_no_geometric_match";
            return false;
        }

        _claimedConfirmedComplexLeaseKeys.Add(
            BuildConfirmedComplexLeaseClaimKey(bestBlock, bestIndex));
        entry.ComplexLeaseRenewed = true;
        bool sameBlock = bestBlock == entry.Block;
        if (bestLease.MissingRounds > 0)
        {
            entry.ComplexLeaseMatch = sameBlock
                ? "grace_reacquired_same_block"
                : "grace_reacquired_neighbor_block";
            LastConfirmedComplexLeaseGraceReacquiredCount++;
        }
        else if (bestExactIdentity)
            entry.ComplexLeaseMatch = "exact_identity_and_geometry";
        else
            entry.ComplexLeaseMatch = sameBlock
                ? "geometric_same_block"
                : "geometric_neighbor_block";
        entry.ComplexLeaseCentroidDelta = bestCentroidDelta;
        entry.ComplexLeaseNormalDot = bestNormalDot;
        entry.ComplexLeaseAreaRatio = bestAreaRatio;
        return true;
    }

    private static string BuildConfirmedComplexLeaseClaimKey(
        Vector3Int block, int leaseIndex)
    {
        return block.x + ":" + block.y + ":" + block.z + ":" + leaseIndex;
    }

    private void RebuildConfirmedComplexLeaseLedger(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger)
    {
        int before = CountConfirmedComplexLeases();
        Dictionary<Vector3Int, List<ConfirmedComplexLeaseEntry>> next =
            new Dictionary<Vector3Int, List<ConfirmedComplexLeaseEntry>>();
        if (ledger != null)
        {
            for (int i = 0; i < ledger.Count; i++)
            {
                PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[i];
                if (!entry.HardLegal || !entry.WorkingPublishEligible ||
                    entry.RelaxedClass != "confirmed_complex")
                    continue;
                if (!next.TryGetValue(entry.Block, out List<ConfirmedComplexLeaseEntry> leases))
                {
                    leases = new List<ConfirmedComplexLeaseEntry>();
                    next[entry.Block] = leases;
                }
                leases.Add(new ConfirmedComplexLeaseEntry
                {
                    SourceEdgeStart = entry.SourceEdgeStart,
                    SourceAxis = entry.SourceAxis,
                    LocalTriangle = entry.LocalTriangle,
                    Centroid = entry.Centroid,
                    Normal = entry.Normal,
                    Area = entry.Area,
                    MissingRounds = 0
                });
            }
        }
        int graceRounds = Mathf.Clamp(confirmedComplexLeaseMissingGraceRounds, 0, 3);
        if (graceRounds > 0)
        {
            foreach (KeyValuePair<Vector3Int, List<ConfirmedComplexLeaseEntry>> pair
                     in _confirmedComplexLeasesByBlock)
            {
                if (pair.Value == null ||
                    !_persistentResultLedgerByBlock.ContainsKey(pair.Key))
                    continue;
                for (int leaseIndex = 0; leaseIndex < pair.Value.Count; leaseIndex++)
                {
                    if (_claimedConfirmedComplexLeaseKeys.Contains(
                            BuildConfirmedComplexLeaseClaimKey(pair.Key, leaseIndex)))
                        continue;
                    ConfirmedComplexLeaseEntry prior = pair.Value[leaseIndex];
                    if (prior.MissingRounds >= graceRounds)
                        continue;
                    if (!next.TryGetValue(
                            pair.Key, out List<ConfirmedComplexLeaseEntry> retained))
                    {
                        retained = new List<ConfirmedComplexLeaseEntry>();
                        next[pair.Key] = retained;
                    }
                    retained.Add(new ConfirmedComplexLeaseEntry
                    {
                        SourceEdgeStart = prior.SourceEdgeStart,
                        SourceAxis = prior.SourceAxis,
                        LocalTriangle = prior.LocalTriangle,
                        Centroid = prior.Centroid,
                        Normal = prior.Normal,
                        Area = prior.Area,
                        MissingRounds = prior.MissingRounds + 1
                    });
                    LastConfirmedComplexLeaseGraceRetainedCount++;
                }
            }
        }
        _confirmedComplexLeasesByBlock.Clear();
        foreach (KeyValuePair<Vector3Int, List<ConfirmedComplexLeaseEntry>> pair in next)
            _confirmedComplexLeasesByBlock[pair.Key] = pair.Value;
        LastConfirmedComplexLeaseAfterCount = CountConfirmedComplexLeases();
        LastConfirmedComplexLeaseExpiredCount = Mathf.Max(
            0,
            before -
            LastConfirmedComplexRenewedCount -
            LastConfirmedComplexLeaseGraceRetainedCount);
    }

    private void ApplyHeldRescueKeepPolicy(PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        LastHeldRescueCandidateTriangleCount++;
        entry.HeldRescueIndependentStatus = BuildHeldRescueIndependentStatus(entry);
        entry.HeldRescueEvidence = BuildHeldRescueEvidence(entry);
        if (entry.IndependentSupportsTarget)
        {
            entry.HeldKeepDecision = "keep";
            entry.HeldKeepAction = "provisional_trial";
            entry.RelaxedClass = "provisional_structural";
            entry.CandidateEvaluationReason = "held_rescue_keep|independent_raw_support";
            entry.WorkingPublishEligible = true;
            LastHeldRescueKeptTriangleCount++;
            return;
        }

        entry.HeldKeepDecision = "do_not_keep";
        entry.RelaxedClass = "pending";
        entry.WorkingPublishEligible = false;
        LastHeldRescueNotKeptTriangleCount++;
        string status = entry.HeldRescueIndependentStatus;
        if (entry.IndependentReason == "raw_triangle_degenerate")
        {
            entry.HeldKeepAction = "local_reextract_raw_degenerate";
            LastHeldRescueDegenerateTriangleCount++;
        }
        else if (status == "conflicting_plane_identity")
        {
            entry.HeldKeepAction = "local_reextract_plane_identity";
            LastHeldRescueIdentityConflictTriangleCount++;
        }
        else if (status == "target_not_qualified")
        {
            entry.HeldKeepAction = "local_reextract_target_unqualified";
            LastHeldRescueTargetUnqualifiedTriangleCount++;
        }
        else if (status == "near_tie")
        {
            entry.HeldKeepAction = "wait_plane_identity";
            LastHeldRescueNearTieTriangleCount++;
        }
        else if (status == "no_support")
        {
            entry.HeldKeepAction = "wait_independent_support";
            LastHeldRescueNoSupportTriangleCount++;
        }
        else
        {
            entry.HeldKeepAction = "wait_independent_audit";
            LastHeldRescueNotCheckedTriangleCount++;
        }
        entry.CandidateEvaluationReason =
            "held_rescue_do_not_keep|" + entry.HeldKeepAction + "|" + status;
    }

    private bool TryBuildHardLegalRelaxedProjection(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry,
        ScanCoverStablePlaneRegistry.PlaneConstraint plane,
        out string rejectReason,
        out bool outsideExtent)
    {
        rejectReason = "none";
        outsideExtent = false;
        Vector3 planeNormal = plane.Normal.sqrMagnitude > 0.5f
            ? plane.Normal.normalized : Vector3.up;
        Vector3 rawCenter = (entry.RawA + entry.RawB + entry.RawC) / 3f;
        Vector3 fromCenter = rawCenter - plane.Center;
        Vector3 tangent = fromCenter - planeNormal * Vector3.Dot(planeNormal, fromCenter);
        outsideExtent = tangent.magnitude >
                        plane.Radius + authoritativeCyanPlaneTangentialPaddingMeters;
        if (outsideExtent)
        {
            rejectReason = "outside_plane_extent";
            return false;
        }

        float da = Mathf.Abs(Vector3.Dot(planeNormal, entry.RawA) + plane.Offset);
        float db = Mathf.Abs(Vector3.Dot(planeNormal, entry.RawB) + plane.Offset);
        float dc = Mathf.Abs(Vector3.Dot(planeNormal, entry.RawC) + plane.Offset);
        float maxDistance = Mathf.Max(da, Mathf.Max(db, dc));
        float hardDistance = Mathf.Min(
            Mathf.Clamp(legacyRelaxedHardMaxPlaneDistanceMeters, 0.02f, 0.18f),
            Mathf.Max(voxelSizeMeters * 1.5f, GetAuthoritativeCyanPlaneDistanceLimit(plane, true)));
        if (entry.Disposition == "hold_reextract")
        {
            entry.HeldAssignedVertexCount = CountNonNegativePlaneIds(
                entry.PlaneA, entry.PlaneB, entry.PlaneC);
            entry.HeldAppliedVertexCount = CountNonNegativePlaneIds(
                entry.AppliedPlaneA, entry.AppliedPlaneB, entry.AppliedPlaneC);
            entry.HeldDistinctAppliedPlaneFamilies = CountDistinctPlaneFamilies(
                entry.AppliedPlaneA, entry.AppliedPlaneB, entry.AppliedPlaneC);
            entry.HeldRescueMaxRawPlaneDistance = maxDistance;
            entry.HeldRescuePlaneDistanceLimit = hardDistance;
            entry.HeldRescueNormalDotLimit = Mathf.Clamp01(legacyRelaxedHardMinPlaneNormalDot);
            entry.HeldRescueProjectedAreaLimit = Mathf.Max(
                0.0000001f, legacyRelaxedHardMinProjectedAreaM2);
        }
        if (maxDistance > hardDistance)
        {
            rejectReason = "off_plane";
            return false;
        }

        Vector3 rawCross = Vector3.Cross(entry.RawB - entry.RawA, entry.RawC - entry.RawA);
        if (rawCross.sqrMagnitude > 0.0000000001f)
        {
            float rawNormalDot = Mathf.Abs(Vector3.Dot(rawCross.normalized, planeNormal));
            if (entry.Disposition == "hold_reextract")
                entry.HeldRescueRawNormalDot = rawNormalDot;
            if (rawNormalDot < Mathf.Clamp01(legacyRelaxedHardMinPlaneNormalDot))
            {
                rejectReason = "tilted_from_plane";
                return false;
            }
        }

        Vector3 projectedA = entry.RawA - planeNormal * (Vector3.Dot(planeNormal, entry.RawA) + plane.Offset);
        Vector3 projectedB = entry.RawB - planeNormal * (Vector3.Dot(planeNormal, entry.RawB) + plane.Offset);
        Vector3 projectedC = entry.RawC - planeNormal * (Vector3.Dot(planeNormal, entry.RawC) + plane.Offset);
        Vector3 projectedCross = Vector3.Cross(projectedB - projectedA, projectedC - projectedA);
        float projectedArea = projectedCross.magnitude * 0.5f;
        if (entry.Disposition == "hold_reextract")
            entry.HeldRescueProjectedArea = projectedArea;
        if (projectedArea < Mathf.Max(0.0000001f, legacyRelaxedHardMinProjectedAreaM2))
        {
            rejectReason = "projected_degenerate";
            return false;
        }
        if (rawCross.sqrMagnitude > 0.0000000001f &&
            Vector3.Dot(rawCross, projectedCross) <= 0f)
        {
            rejectReason = "projected_winding_flip";
            return false;
        }

        entry.RelaxedA = projectedA;
        entry.RelaxedB = projectedB;
        entry.RelaxedC = projectedC;
        entry.HasRelaxedProjection = true;
        return true;
    }

    private static bool HasRelaxedCandidateNonManifoldEdge(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry,
        Dictionary<AuthoritativeCanonicalEdgeKey, List<int>> edgeTriangles)
    {
        if (entry == null || edgeTriangles == null)
            return false;
        return RelaxedCandidateEdgeIncidence(edgeTriangles, entry.KeyA, entry.KeyB) > 2 ||
               RelaxedCandidateEdgeIncidence(edgeTriangles, entry.KeyB, entry.KeyC) > 2 ||
               RelaxedCandidateEdgeIncidence(edgeTriangles, entry.KeyC, entry.KeyA) > 2;
    }

    private static int RelaxedCandidateEdgeIncidence(
        Dictionary<AuthoritativeCanonicalEdgeKey, List<int>> edgeTriangles,
        AuthoritativeCellComponentKey a,
        AuthoritativeCellComponentKey b)
    {
        return edgeTriangles.TryGetValue(MakeAuthoritativeCanonicalEdge(a, b), out List<int> attached)
            ? attached.Count : 0;
    }

    private static void MarkRelaxedCandidateIllegal(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry,
        string reason)
    {
        entry.HardLegal = false;
        entry.HardRejectReason = string.IsNullOrEmpty(reason) ? "hard_gate" : reason;
        entry.CandidateEvaluationReason = entry.HardRejectReason;
        entry.RelaxedClass = "hard_illegal";
        entry.WorkingPublishEligible = false;
    }

    private static string BuildProvisionalCandidateReason(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        string reason = string.Empty;
        if (entry.GeometricSuspect)
            reason = AppendCandidateReason(reason, "geometric_suspect");
        if (entry.Disposition != "publish_plane")
            reason = AppendCandidateReason(reason, "recovered_held");
        if (!entry.IndependentAuditChecked)
            reason = AppendCandidateReason(reason, "independent_not_checked");
        else if (!entry.IndependentSupportsTarget)
            reason = AppendCandidateReason(reason, "independent_" + entry.IndependentReason);
        return string.IsNullOrEmpty(reason) ? "soft_evidence" : reason;
    }

    private static string AppendCandidateReason(string existing, string reason)
    {
        return string.IsNullOrEmpty(existing) ? reason : existing + "|" + reason;
    }

    private void ClassifyCandidateReasonMemberships(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger)
    {
        LastCandidateHeldReasonMembershipCount = 0;
        LastCandidateProvisionalReasonMembershipCount = 0;
        LastCandidateUnclassifiedReasonMembershipCount = 0;
        LastCandidateReasonOverlapTriangleCount = 0;
        LastHeldToProvisionalTriangleCount = 0;
        _candidateReasonCounts.Clear();
        _heldToProvisionalBreakdownCounts.Clear();
        if (ledger == null)
            return;

        for (int i = 0; i < ledger.Count; i++)
        {
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[i];
            int memberships = 0;
            if (IsPlaneLedgerProblem(entry))
            {
                entry.HeldOriginReason = BuildHeldOriginReason(entry);
                entry.HeldReason = BuildHeldCandidateReason(entry);
                LastCandidateHeldReasonMembershipCount++;
                CountCandidateReason("held", entry.HeldReason);
                memberships++;
            }
            if (entry.RelaxedClass == "provisional_structural")
            {
                entry.ProvisionalReason = string.IsNullOrEmpty(entry.CandidateEvaluationReason)
                    ? "soft_evidence" : entry.CandidateEvaluationReason;
                LastCandidateProvisionalReasonMembershipCount++;
                CountCandidateReason("provisional", entry.ProvisionalReason);
                memberships++;
            }
            if (entry.RelaxedClass == "unclassified")
            {
                entry.UnclassifiedReason = string.IsNullOrEmpty(entry.CandidateEvaluationReason)
                    ? "no_structural_route" : entry.CandidateEvaluationReason;
                LastCandidateUnclassifiedReasonMembershipCount++;
                CountCandidateReason("unclassified", entry.UnclassifiedReason);
                memberships++;
            }
            if (memberships > 1)
                LastCandidateReasonOverlapTriangleCount++;
            if (entry.Disposition == "hold_reextract" && entry.HasRelaxedProjection)
            {
                CountHeldToProvisionalBreakdown("keep_decision", entry.HeldKeepDecision);
                CountHeldToProvisionalBreakdown("keep_action", entry.HeldKeepAction);
            }
            if (entry.Disposition == "hold_reextract" &&
                entry.RelaxedClass == "provisional_structural")
            {
                entry.HeldRescueIndependentStatus = BuildHeldRescueIndependentStatus(entry);
                entry.HeldRescueEvidence = BuildHeldRescueEvidence(entry);
                LastHeldToProvisionalTriangleCount++;
                CountHeldToProvisionalBreakdown("origin", entry.HeldOriginReason);
                CountHeldToProvisionalBreakdown("rescue", entry.HeldRescueEvidence);
                CountHeldToProvisionalBreakdown("independent", entry.HeldRescueIndependentStatus);
                CountHeldToProvisionalBreakdown(
                    "cross", entry.HeldOriginReason + "__" + entry.HeldRescueIndependentStatus);
            }
        }
    }

    private static string BuildHeldOriginReason(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        if (entry == null || entry.Disposition != "hold_reextract")
            return "not_member";
        if (entry.AtomicClass == "mixed_one")
            return "partial_application_one_of_three";
        if (entry.AtomicClass == "mixed_two")
            return "partial_application_two_of_three";
        if (entry.AtomicClass == "assigned_unapplied")
            return "assigned_but_zero_applied";
        if (entry.AtomicClass == "unowned_near_structural")
            return "unowned_near_registered_structure";
        if (entry.AtomicClass == "overflow" || entry.Reason == "vertex_move_overflow")
            return "vertex_move_overflow";
        return string.IsNullOrEmpty(entry.Reason)
            ? "other_held" : entry.AtomicClass + "|" + entry.Reason;
    }

    private static string BuildHeldRescueIndependentStatus(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        if (entry == null || entry.Disposition != "hold_reextract")
            return "not_member";
        if (!entry.IndependentAuditChecked)
            return "not_checked";
        if (entry.IndependentSupportsTarget)
            return "supports_target";
        if (entry.IndependentReason == "independent_plane_identity_conflict")
            return "conflicting_plane_identity";
        if (entry.IndependentReason == "independent_near_tie")
            return "near_tie";
        if (entry.IndependentReason == "no_independent_structural_support" ||
            entry.IndependentReason == "raw_triangle_degenerate")
            return "no_support";
        if (entry.IndependentReason == "target_plane_missing" ||
            entry.IndependentReason == "target_not_qualified_at_raw_triangle")
            return "target_not_qualified";
        return string.IsNullOrEmpty(entry.IndependentReason)
            ? "unknown" : entry.IndependentReason;
    }

    private static string BuildHeldRescueEvidence(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        if (entry == null || entry.Disposition != "hold_reextract" ||
            !entry.HasRelaxedProjection)
            return "not_member";
        string evidence = "registered_target|hard_projection_pass";
        evidence = AppendCandidateReason(evidence,
            "applied_vertices_" + entry.HeldAppliedVertexCount);
        evidence = AppendCandidateReason(evidence,
            "independent_" + BuildHeldRescueIndependentStatus(entry));
        return evidence;
    }

    private static string BuildHeldCandidateReason(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        if (entry.RelaxedClass == "provisional_structural")
            return "recovered_to_provisional";
        if (entry.RelaxedClass == "hard_illegal")
            return "hard_illegal|" + entry.HardRejectReason;
        if (entry.RelaxedClass == "pending")
        {
            if (entry.CandidateEvaluationReason == "outside_plane_extent")
                return "outside_plane_extent";
            if (entry.CandidateEvaluationReason == "missing_target_plane" ||
                entry.CandidateEvaluationReason == "target_plane_not_registered")
                return "missing_structural_plane|" + entry.CandidateEvaluationReason;
            return "evidence_or_projection_pending|" + entry.CandidateEvaluationReason;
        }
        return "legacy_problem|" + entry.CandidateEvaluationReason;
    }

    private void CountCandidateReason(string membership, string reason)
    {
        string key = SanitizeCandidateReasonKey(membership + "_" + reason);
        _candidateReasonCounts.TryGetValue(key, out int count);
        _candidateReasonCounts[key] = count + 1;
    }

    private void CountHeldToProvisionalBreakdown(string axis, string value)
    {
        string key = SanitizeCandidateReasonKey(axis + "_" + value);
        _heldToProvisionalBreakdownCounts.TryGetValue(key, out int count);
        _heldToProvisionalBreakdownCounts[key] = count + 1;
    }

    private static string SanitizeCandidateReasonKey(string value)
    {
        if (string.IsNullOrEmpty(value))
            return "none";
        StringBuilder result = new StringBuilder(value.Length);
        bool previousUnderscore = false;
        for (int i = 0; i < value.Length; i++)
        {
            char c = char.ToLowerInvariant(value[i]);
            bool accepted = (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9');
            if (accepted)
            {
                result.Append(c);
                previousUnderscore = false;
            }
            else if (!previousUnderscore)
            {
                result.Append('_');
                previousUnderscore = true;
            }
        }
        return result.ToString().Trim('_');
    }

    private void CountRelaxedCandidateClass(string relaxedClass)
    {
        switch (relaxedClass)
        {
            case "formal_structural": LastRelaxedCandidateFormalTriangleCount++; break;
            case "provisional_structural": LastRelaxedCandidateProvisionalTriangleCount++; break;
            case "confirmed_complex": LastRelaxedCandidateComplexTriangleCount++; break;
            case "pending": LastRelaxedCandidatePendingTriangleCount++; break;
            case "hard_illegal": LastRelaxedCandidateIllegalTriangleCount++; break;
            default: LastRelaxedCandidateUnclassifiedTriangleCount++; break;
        }
    }

    private void AuditPublishedYellowFallback(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger,
        Dictionary<AuthoritativeCanonicalEdgeKey, List<int>> edgeTriangles)
    {
        if (!enablePlaneConstrainedPublishedFallbackAudit || ledger == null || edgeTriangles == null)
            return;
        int minAdjacent = Mathf.Clamp(planeConstrainedFallbackMinAdjacentTriangles, 2, 8);
        float minCoherence = Mathf.Clamp(planeConstrainedFallbackMinNeighborCoherence, 0.5f, 1f);
        Dictionary<int, PlaneFallbackAdaptiveStats> statsByPlane =
            new Dictionary<int, PlaneFallbackAdaptiveStats>();
        PlaneFallbackAdaptiveStats globalStats = new PlaneFallbackAdaptiveStats();
        for (int triangleIndex = 0; triangleIndex < ledger.Count; triangleIndex++)
        {
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[triangleIndex];
            if (entry.Disposition != "publish_plane")
                continue;
            entry.FallbackAuditChecked = true;
            LastPlaneConstrainedZeroCrossFallbackCheckedTriangleCount++;
            HashSet<int> neighbours = new HashSet<int>();
            AddPlaneLedgerAdjacentTriangles(neighbours, edgeTriangles,
                MakeAuthoritativeCanonicalEdge(entry.KeyA, entry.KeyB), triangleIndex);
            AddPlaneLedgerAdjacentTriangles(neighbours, edgeTriangles,
                MakeAuthoritativeCanonicalEdge(entry.KeyB, entry.KeyC), triangleIndex);
            AddPlaneLedgerAdjacentTriangles(neighbours, edgeTriangles,
                MakeAuthoritativeCanonicalEdge(entry.KeyC, entry.KeyA), triangleIndex);
            entry.FallbackNeighborCount = neighbours.Count;
            if (neighbours.Count < minAdjacent || entry.Normal.sqrMagnitude < 0.5f)
            {
                entry.FallbackAuditReason = "insufficient_adjacent_support";
                continue;
            }

            Vector3 alignedNormalSum = Vector3.zero;
            Vector3 neighbourCenterSum = Vector3.zero;
            int valid = 0;
            foreach (int neighbourIndex in neighbours)
            {
                if (neighbourIndex < 0 || neighbourIndex >= ledger.Count)
                    continue;
                PlaneConstrainedZeroCrossTriangleLedgerEntry neighbour = ledger[neighbourIndex];
                if (neighbour.Disposition != "publish_plane" ||
                    neighbour.TargetPlaneId != entry.TargetPlaneId ||
                    neighbour.Normal.sqrMagnitude < 0.5f)
                    continue;
                Vector3 normal = neighbour.Normal.normalized;
                if (valid > 0 && Vector3.Dot(alignedNormalSum, normal) < 0f)
                    normal = -normal;
                alignedNormalSum += normal;
                neighbourCenterSum += neighbour.Centroid;
                valid++;
            }
            if (valid < minAdjacent || alignedNormalSum.sqrMagnitude < 0.000001f)
            {
                entry.FallbackAuditReason = "insufficient_valid_adjacent_support";
                continue;
            }
            entry.FallbackNeighborCoherence = alignedNormalSum.magnitude / valid;
            if (entry.FallbackNeighborCoherence < minCoherence)
            {
                entry.FallbackAuditReason = "neighbour_crease_or_mixed_surface";
                continue;
            }
            Vector3 consensusNormal = alignedNormalSum.normalized;
            Vector3 neighbourCenter = neighbourCenterSum / valid;
            entry.FallbackDistance = Mathf.Abs(Vector3.Dot(
                consensusNormal, entry.Centroid - neighbourCenter));
            entry.FallbackNormalDot = Mathf.Abs(Vector3.Dot(
                entry.Normal.normalized, consensusNormal));
            int planeId = entry.TargetPlaneId >= 0 ? entry.TargetPlaneId : entry.NearestPlaneId;
            if (!statsByPlane.TryGetValue(planeId, out PlaneFallbackAdaptiveStats stats))
            {
                stats = new PlaneFallbackAdaptiveStats();
                statsByPlane[planeId] = stats;
            }
            stats.TriangleIndices.Add(triangleIndex);
            stats.Distances.Add(entry.FallbackDistance);
            stats.NormalDeviations.Add(1f - entry.FallbackNormalDot);
            globalStats.Distances.Add(entry.FallbackDistance);
            globalStats.NormalDeviations.Add(1f - entry.FallbackNormalDot);
        }

        int minAdaptiveSamples = Mathf.Clamp(
            planeConstrainedFallbackAdaptiveMinSamples, 6, 128);
        foreach (KeyValuePair<int, PlaneFallbackAdaptiveStats> pair in statsByPlane)
        {
            PlaneFallbackAdaptiveStats planeStats = pair.Value;
            PlaneFallbackAdaptiveStats thresholdSource =
                planeStats.Distances.Count >= minAdaptiveSamples ? planeStats : globalStats;
            ComputePlaneFallbackAdaptiveThresholds(planeStats, thresholdSource);
            for (int i = 0; i < planeStats.TriangleIndices.Count; i++)
            {
                PlaneConstrainedZeroCrossTriangleLedgerEntry entry =
                    ledger[planeStats.TriangleIndices[i]];
                entry.FallbackThresholdPlaneId = pair.Key;
                entry.FallbackThresholdSampleCount = thresholdSource.Distances.Count;
                entry.FallbackDistanceThreshold = planeStats.DistanceThreshold;
                entry.FallbackNormalDotThreshold = planeStats.NormalDotThreshold;
                bool displaced = entry.FallbackDistance > planeStats.DistanceThreshold;
                bool tilted = entry.FallbackNormalDot < planeStats.NormalDotThreshold;
                if (!displaced && !tilted)
                {
                    entry.FallbackAuditReason = "local_consistent";
                    continue;
                }
                entry.FallbackAuditReason = displaced && tilted
                    ? "local_displacement|local_normal_outlier"
                    : displaced ? "local_displacement" : "local_normal_outlier";
                if (displaced) LastPlaneConstrainedZeroCrossFallbackDisplacedTriangleCount++;
                if (tilted) LastPlaneConstrainedZeroCrossFallbackTiltedTriangleCount++;
                MarkPlaneLedgerFallbackSuspect(entry, entry.FallbackAuditReason);
            }
        }
        AuditPublishedYellowAgainstStablePlanes(ledger, statsByPlane, globalStats);
    }

    private void AuditIndependentStructuralEvidence(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes)
    {
        if (!enableIndependentStructuralEvidenceAudit || ledger == null || planes == null)
            return;
        float minNormalDot = Mathf.Clamp(independentStructuralEvidenceMinNormalDot, 0.5f, 1f);
        float identityMargin = Mathf.Max(0.001f, independentStructuralIdentityMarginMeters);
        float extentPadding = Mathf.Max(0f, independentStructuralExtentPaddingMeters);
        for (int triangleIndex = 0; triangleIndex < ledger.Count; triangleIndex++)
        {
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[triangleIndex];
            bool diagnosticOnlyHeld = entry.Disposition == "hold_reextract";
            if (entry.Disposition != "publish_plane" && !diagnosticOnlyHeld)
                continue;
            entry.IndependentAuditChecked = true;
            entry.IndependentAuditDiagnosticOnly = diagnosticOnlyHeld;
            LastIndependentStructuralCheckedTriangleCount++;
            entry.TargetVertexVotes = CountMatchingPlaneVotes(
                entry.TargetPlaneId, entry.PlaneA, entry.PlaneB, entry.PlaneC);
            entry.DistinctAssignedPlaneFamilies = CountDistinctPlaneFamilies(
                entry.PlaneA, entry.PlaneB, entry.PlaneC);

            Vector3 rawCentroid = (entry.RawA + entry.RawB + entry.RawC) / 3f;
            Vector3 rawNormal = Vector3.Cross(entry.RawB - entry.RawA, entry.RawC - entry.RawA);
            if (rawNormal.sqrMagnitude > 0.000001f)
                rawNormal.Normalize();

            ScanCoverStablePlaneRegistry.PlaneConstraint target = default;
            bool hasTarget = false;
            for (int planeIndex = 0; planeIndex < planes.Count; planeIndex++)
            {
                if (planes[planeIndex].Id != entry.TargetPlaneId)
                    continue;
                target = planes[planeIndex];
                hasTarget = true;
                break;
            }
            if (hasTarget)
            {
                entry.TargetGloballyQualified = IsAuthoritativeCyanStructuralPlane(
                    target, out _, out string targetReject);
                entry.TargetQualificationReject = targetReject;
                if (!entry.TargetGloballyQualified &&
                    IsAuthoritativeCyanLocalStructuralCandidate(target, out _, out _, out _) &&
                    IsAuthoritativeCyanPointLocallyQualified(
                        target, rawCentroid, out AuthoritativeCyanLocalSupportState localState))
                {
                    entry.TargetLocallyQualified = true;
                    entry.TargetQualification = localState == AuthoritativeCyanLocalSupportState.GlobalQualified
                        ? "global" : "local";
                }
                else
                {
                    entry.TargetQualification = entry.TargetGloballyQualified ? "global" : "none";
                }
            }

            float bestScore = float.PositiveInfinity;
            float secondScore = float.PositiveInfinity;
            float bestDistance = float.PositiveInfinity;
            float bestNormalDot = 0f;
            int bestPlaneId = -1;
            string bestKind = "none";
            string bestQualification = "none";
            for (int planeIndex = 0; planeIndex < planes.Count; planeIndex++)
            {
                ScanCoverStablePlaneRegistry.PlaneConstraint candidate = planes[planeIndex];
                if (candidate.Normal.sqrMagnitude < 0.5f || rawNormal.sqrMagnitude < 0.5f)
                    continue;
                bool global = IsAuthoritativeCyanStructuralPlane(
                    candidate, out string kind, out _);
                bool local = !global &&
                             IsAuthoritativeCyanLocalStructuralCandidate(candidate, out _, out kind, out _) &&
                             IsAuthoritativeCyanPointLocallyQualified(
                                 candidate, rawCentroid, out AuthoritativeCyanLocalSupportState localState) &&
                             localState != AuthoritativeCyanLocalSupportState.Candidate;
                if (!global && !local)
                    continue;
                Vector3 normal = candidate.Normal.normalized;
                float normalDot = Mathf.Abs(Vector3.Dot(rawNormal, normal));
                if (normalDot < minNormalDot)
                    continue;
                float distance = Mathf.Abs(Vector3.Dot(normal, rawCentroid) + candidate.Offset);
                float distanceLimit = GetAuthoritativeCyanPlaneDistanceLimit(candidate, false);
                if (distance > distanceLimit)
                    continue;
                Vector3 tangent = rawCentroid - candidate.Center;
                tangent -= normal * Vector3.Dot(normal, tangent);
                if (tangent.magnitude > candidate.Radius + extentPadding)
                    continue;
                float score = distance / Mathf.Max(0.001f, distanceLimit) + (1f - normalDot);
                if (score < bestScore)
                {
                    secondScore = bestScore;
                    bestScore = score;
                    bestPlaneId = candidate.Id;
                    bestKind = kind;
                    bestQualification = global ? "global" : "local";
                    bestDistance = distance;
                    bestNormalDot = normalDot;
                }
                else if (score < secondScore)
                {
                    secondScore = score;
                }
            }

            entry.IndependentPlaneId = bestPlaneId;
            entry.IndependentPlaneKind = bestKind;
            entry.IndependentQualification = bestQualification;
            entry.IndependentDistance = float.IsPositiveInfinity(bestDistance) ? 0f : bestDistance;
            entry.IndependentNormalDot = bestNormalDot;
            entry.IndependentScore = float.IsPositiveInfinity(bestScore) ? 0f : bestScore;
            entry.IndependentSecondScore = float.IsPositiveInfinity(secondScore) ? 0f : secondScore;

            if (!hasTarget || (!entry.TargetGloballyQualified && !entry.TargetLocallyQualified))
            {
                entry.IndependentReason = !hasTarget
                    ? "target_plane_missing" : "target_not_qualified_at_raw_triangle";
                LastIndependentStructuralQualificationFailureTriangleCount++;
                if (!diagnosticOnlyHeld)
                    MarkPlaneLedgerIndependentSuspect(entry, entry.IndependentReason,
                        entry.IndependentDistance, entry.IndependentNormalDot);
                continue;
            }
            if (bestPlaneId < 0)
            {
                entry.IndependentReason = rawNormal.sqrMagnitude < 0.5f
                    ? "raw_triangle_degenerate" : "no_independent_structural_support";
                LastIndependentStructuralNoSupportTriangleCount++;
                if (!diagnosticOnlyHeld)
                    MarkPlaneLedgerIndependentSuspect(entry, entry.IndependentReason, 0f, 0f);
                continue;
            }
            if (bestPlaneId != entry.TargetPlaneId)
            {
                float targetDistance = hasTarget && target.Normal.sqrMagnitude > 0.5f
                    ? Mathf.Abs(Vector3.Dot(target.Normal.normalized, rawCentroid) + target.Offset)
                    : float.PositiveInfinity;
                if (targetDistance - bestDistance > identityMargin || entry.TargetVertexVotes < 3)
                {
                    entry.IndependentReason = "independent_plane_identity_conflict";
                    LastIndependentStructuralIdentityConflictTriangleCount++;
                    if (!diagnosticOnlyHeld)
                        MarkPlaneLedgerIndependentSuspect(entry, entry.IndependentReason,
                            targetDistance, bestNormalDot);
                    continue;
                }
            }
            entry.IndependentSupportsTarget = bestPlaneId == entry.TargetPlaneId;
            entry.IndependentReason = entry.IndependentSupportsTarget
                ? "independent_raw_support" : "independent_near_tie";
            LastIndependentStructuralSupportedTriangleCount++;
        }
    }

    private static int CountMatchingPlaneVotes(int target, int a, int b, int c)
    {
        return (a == target ? 1 : 0) + (b == target ? 1 : 0) + (c == target ? 1 : 0);
    }

    private static int CountNonNegativePlaneIds(int a, int b, int c)
    {
        return (a >= 0 ? 1 : 0) + (b >= 0 ? 1 : 0) + (c >= 0 ? 1 : 0);
    }

    private static int CountDistinctPlaneFamilies(int a, int b, int c)
    {
        int count = 0;
        if (a >= 0) count++;
        if (b >= 0 && b != a) count++;
        if (c >= 0 && c != a && c != b) count++;
        return count;
    }

    private static void MarkPlaneLedgerIndependentSuspect(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry,
        string reason,
        float distance,
        float normalDot)
    {
        if (entry == null)
            return;
        string tagged = reason.StartsWith("independent_", System.StringComparison.Ordinal)
            ? reason : "independent_" + reason;
        if (!entry.GeometricSuspect)
        {
            entry.GeometricSuspect = true;
            entry.GeometricSuspectReason = tagged;
            entry.GeometricSuspectPlaneId = entry.TargetPlaneId;
            entry.GeometricSuspectPlaneKind = entry.PlaneKind;
            entry.GeometricSuspectDistance = distance;
            entry.GeometricSuspectNormalDot = normalDot;
        }
        else if (!entry.GeometricSuspectReason.Contains(tagged))
        {
            entry.GeometricSuspectReason += "|" + tagged;
        }
    }

    private void AuditPublishedNonplanarNearestCandidates(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes)
    {
        if (ledger == null || planes == null)
            return;
        float maxBand = Mathf.Clamp(
            planeConstrainedFallbackAbsoluteMaxBandMeters, 0.02f, 0.12f);
        float minNormalDot = Mathf.Clamp(
            planeConstrainedFallbackAbsoluteMinNormalDot, 0.75f, 0.99f);
        float extentPadding = Mathf.Max(
            0f, planeConstrainedFallbackAbsoluteExtentPaddingMeters);
        for (int i = 0; i < ledger.Count; i++)
        {
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[i];
            if (entry.Disposition != "publish_nonplanar")
                continue;
            Vector3 rawCentroid = (entry.RawA + entry.RawB + entry.RawC) / 3f;
            Vector3 rawNormal = Vector3.Cross(entry.RawB - entry.RawA, entry.RawC - entry.RawA);
            if (rawNormal.sqrMagnitude < 0.000001f)
                rawNormal = entry.Normal;
            if (rawNormal.sqrMagnitude > 0.000001f)
                rawNormal.Normalize();
            float bestDistance = float.PositiveInfinity;
            float bestNormalDot = 0f;
            int bestPlaneId = -1;
            string bestKind = "none";
            for (int planeIndex = 0; planeIndex < planes.Count; planeIndex++)
            {
                ScanCoverStablePlaneRegistry.PlaneConstraint plane = planes[planeIndex];
                if (plane.Normal.sqrMagnitude < 0.5f)
                    continue;
                Vector3 normal = plane.Normal.normalized;
                float normalDot = rawNormal.sqrMagnitude > 0.5f
                    ? Mathf.Abs(Vector3.Dot(rawNormal, normal)) : 0f;
                if (normalDot < minNormalDot)
                    continue;
                Vector3 tangent = rawCentroid - plane.Center;
                tangent -= normal * Vector3.Dot(normal, tangent);
                if (tangent.magnitude > plane.Radius + extentPadding)
                    continue;
                float distance = Mathf.Abs(Vector3.Dot(normal, rawCentroid) + plane.Offset);
                if (distance > maxBand || distance >= bestDistance)
                    continue;
                bestDistance = distance;
                bestNormalDot = normalDot;
                bestPlaneId = plane.Id;
                IsAuthoritativeCyanStructuralPlane(plane, out bestKind, out _);
            }
            if (bestPlaneId < 0)
                continue;
            entry.NonplanarCandidate = true;
            entry.NonplanarCandidateReason = "near_mature_plane_observation";
            entry.NonplanarCandidatePlaneId = bestPlaneId;
            entry.NonplanarCandidatePlaneKind = bestKind;
            entry.NonplanarCandidateDistance = bestDistance;
            entry.NonplanarCandidateNormalDot = bestNormalDot;
        }
    }

    private void BuildStablePlaneIdentityAudit(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        Dictionary<AuthoritativeCanonicalEdgeKey, List<int>> edgeTriangles)
    {
        if (ledger == null || planes == null ||
            _stablePlaneIdentityPlaneRows == null || _stablePlaneIdentityPairRows == null)
            return;

        Dictionary<int, StablePlaneIdentityPlaneStats> perPlane =
            new Dictionary<int, StablePlaneIdentityPlaneStats>();
        Dictionary<ulong, StablePlaneIdentityPairStats> perPair =
            new Dictionary<ulong, StablePlaneIdentityPairStats>();
        for (int i = 0; i < planes.Count; i++)
            perPlane[planes[i].Id] = new StablePlaneIdentityPlaneStats();

        for (int i = 0; i < ledger.Count; i++)
        {
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[i];
            int planeId = entry.TargetPlaneId;
            if (planeId >= 0 && perPlane.TryGetValue(planeId, out StablePlaneIdentityPlaneStats stats))
            {
                if (entry.Disposition == "publish_plane")
                {
                    stats.PublishedTriangles++;
                    stats.PublishedCentroids.Add(entry.Centroid);
                    stats.Area += entry.Area;
                    float ab = Vector3.Distance(entry.A, entry.B);
                    float bc = Vector3.Distance(entry.B, entry.C);
                    float ca = Vector3.Distance(entry.C, entry.A);
                    stats.EdgeSum += ab + bc + ca;
                    stats.EdgeSamples += 3;
                    stats.MaxEdge = Mathf.Max(stats.MaxEdge, Mathf.Max(ab, Mathf.Max(bc, ca)));
                    float minEdge = Mathf.Min(ab, Mathf.Min(bc, ca));
                    float maxEdge = Mathf.Max(ab, Mathf.Max(bc, ca));
                    if (minEdge > 0.000001f)
                    {
                        float aspect = maxEdge / minEdge;
                        stats.AspectSum += aspect;
                        stats.AspectSamples++;
                        stats.MaxAspect = Mathf.Max(stats.MaxAspect, aspect);
                    }
                    stats.AbsBeforeSum += entry.MeanAbsDistanceBefore;
                    stats.MaxAbsBefore = Mathf.Max(stats.MaxAbsBefore, entry.MeanAbsDistanceBefore);
                    stats.AbsAfterSum += entry.MeanAbsDistanceAfter;
                    stats.MaxAbsAfter = Mathf.Max(stats.MaxAbsAfter, entry.MeanAbsDistanceAfter);
                    if (entry.Boundary) stats.BoundaryTriangles++;
                }
                if (IsPlaneLedgerProblem(entry)) stats.ProblemTriangles++;
                if (entry.GeometricSuspect) stats.SuspectTriangles++;
                if (entry.Disposition == "publish_nonplanar") stats.NonplanarTriangles++;
                if (entry.NonplanarCandidate) stats.NonplanarCandidateTriangles++;
            }

            int[] ids = { entry.PlaneA, entry.PlaneB, entry.PlaneC };
            HashSet<ulong> mixedPairsInTriangle = new HashSet<ulong>();
            for (int a = 0; a < ids.Length; a++)
            for (int b = a + 1; b < ids.Length; b++)
            {
                if (ids[a] < 0 || ids[b] < 0 || ids[a] == ids[b])
                    continue;
                ulong mixedPairKey = MakeStablePlaneIdentityPairKey(ids[a], ids[b]);
                if (!mixedPairsInTriangle.Add(mixedPairKey))
                    continue;
                StablePlaneIdentityPairStats pair = GetStablePlaneIdentityPairStats(perPair, ids[a], ids[b]);
                pair.MixedTriangles++;
            }
        }

        if (edgeTriangles != null)
        {
            foreach (List<int> attached in edgeTriangles.Values)
            {
                for (int a = 0; a < attached.Count; a++)
                for (int b = a + 1; b < attached.Count; b++)
                {
                    PlaneConstrainedZeroCrossTriangleLedgerEntry ta = ledger[attached[a]];
                    PlaneConstrainedZeroCrossTriangleLedgerEntry tb = ledger[attached[b]];
                    if (ta.TargetPlaneId < 0 || tb.TargetPlaneId < 0 ||
                        ta.TargetPlaneId == tb.TargetPlaneId)
                        continue;
                    GetStablePlaneIdentityPairStats(
                        perPair, ta.TargetPlaneId, tb.TargetPlaneId).SharedEdgeAdjacencies++;
                }
            }
        }

        int[] publishedParents = CreatePlaneLedgerParents(ledger.Count);
        if (edgeTriangles != null)
        {
            foreach (List<int> attached in edgeTriangles.Values)
            {
                for (int a = 0; a < attached.Count; a++)
                for (int b = a + 1; b < attached.Count; b++)
                {
                    PlaneConstrainedZeroCrossTriangleLedgerEntry ta = ledger[attached[a]];
                    PlaneConstrainedZeroCrossTriangleLedgerEntry tb = ledger[attached[b]];
                    if (ta.Disposition == "publish_plane" && tb.Disposition == "publish_plane" &&
                        ta.TargetPlaneId >= 0 && ta.TargetPlaneId == tb.TargetPlaneId)
                        UnionPlaneLedger(publishedParents, attached[a], attached[b]);
                }
            }
        }
        Dictionary<int, HashSet<int>> publishedIslandRoots =
            new Dictionary<int, HashSet<int>>();
        for (int i = 0; i < ledger.Count; i++)
        {
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[i];
            if (entry.Disposition != "publish_plane" || entry.TargetPlaneId < 0)
                continue;
            if (!publishedIslandRoots.TryGetValue(entry.TargetPlaneId, out HashSet<int> roots))
            {
                roots = new HashSet<int>();
                publishedIslandRoots[entry.TargetPlaneId] = roots;
            }
            roots.Add(FindPlaneLedgerRoot(publishedParents, i));
        }

        for (int i = 0; i < planes.Count; i++)
        {
            ScanCoverStablePlaneRegistry.PlaneConstraint plane = planes[i];
            StablePlaneIdentityPlaneStats stats = perPlane[plane.Id];
            int publishedIslands = publishedIslandRoots.TryGetValue(plane.Id, out HashSet<int> roots)
                ? roots.Count : 0;
            IsAuthoritativeCyanStructuralPlane(plane, out string kind, out _);
            int published = Mathf.Max(1, stats.PublishedTriangles);
            _stablePlaneIdentityPlaneRows
                .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
                .Append(plane.Id).Append(',').Append(kind).Append(',')
                .Append(plane.Center.x.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(plane.Center.y.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(plane.Center.z.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(plane.Normal.x.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(plane.Normal.y.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(plane.Normal.z.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(plane.Offset.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(plane.Radius.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(plane.Rms.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(plane.TotalInliers).Append(',').Append(plane.ConsecutiveBatches).Append(',')
                .Append(stats.PublishedTriangles).Append(',')
                .Append(Mathf.Max(0, stats.PublishedTriangles - stats.SuspectTriangles)).Append(',')
                .Append(stats.SuspectTriangles).Append(',')
                .Append(stats.ProblemTriangles).Append(',').Append(stats.NonplanarTriangles).Append(',')
                .Append(stats.NonplanarCandidateTriangles).Append(',').Append(stats.BoundaryTriangles).Append(',')
                .Append(publishedIslands).Append(',')
                .Append(stats.Area.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append((stats.EdgeSamples > 0 ? stats.EdgeSum / stats.EdgeSamples : 0f).ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(stats.MaxEdge.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append((stats.AspectSamples > 0 ? stats.AspectSum / stats.AspectSamples : 0f).ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(stats.MaxAspect.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append((stats.AbsBeforeSum / published).ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(stats.MaxAbsBefore.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append((stats.AbsAfterSum / published).ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(stats.MaxAbsAfter.ToString("F6", CultureInfo.InvariantCulture)).AppendLine();
        }

        for (int i = 0; i < planes.Count; i++)
        for (int j = i + 1; j < planes.Count; j++)
        {
            ScanCoverStablePlaneRegistry.PlaneConstraint a = planes[i];
            ScanCoverStablePlaneRegistry.PlaneConstraint b = planes[j];
            IsAuthoritativeCyanStructuralPlane(a, out string kindA, out _);
            IsAuthoritativeCyanStructuralPlane(b, out string kindB, out _);
            float signedDot = Vector3.Dot(a.Normal.normalized, b.Normal.normalized);
            float normalDot = Mathf.Abs(signedDot);
            float angle = Mathf.Acos(Mathf.Clamp(normalDot, 0f, 1f)) * Mathf.Rad2Deg;
            float alignedOffsetB = signedDot >= 0f ? b.Offset : -b.Offset;
            float separation = Mathf.Abs(a.Offset - alignedOffsetB);
            float aToB = Mathf.Abs(Vector3.Dot(b.Normal.normalized, a.Center) + b.Offset);
            float bToA = Mathf.Abs(Vector3.Dot(a.Normal.normalized, b.Center) + a.Offset);
            Vector3 delta = b.Center - a.Center;
            float tangentDistance = (delta - a.Normal.normalized * Vector3.Dot(delta, a.Normal.normalized)).magnitude;
            float overlapRatio = (a.Radius + b.Radius - tangentDistance) /
                                 Mathf.Max(0.01f, Mathf.Min(a.Radius, b.Radius));
            ulong pairKey = MakeStablePlaneIdentityPairKey(a.Id, b.Id);
            perPair.TryGetValue(pairKey, out StablePlaneIdentityPairStats evidence);
            int mixed = evidence != null ? evidence.MixedTriangles : 0;
            int shared = evidence != null ? evidence.SharedEdgeAdjacencies : 0;
            float minCentroid = FindStablePlaneIdentityMinCentroidDistance(
                perPlane[a.Id].PublishedCentroids, perPlane[b.Id].PublishedCentroids);
            bool spatiallyObserved = mixed > 0 || shared > 0 ||
                                     (minCentroid >= 0f && minCentroid <= 0.25f);
            bool sameKind = kindA == kindB && kindA != "unknown";
            bool closeSupport = overlapRatio >= -0.25f ||
                                (minCentroid >= 0f && minCentroid <= 0.25f);
            bool suspectedSplit = sameKind && spatiallyObserved && closeSupport &&
                                  angle <= 25f && Mathf.Max(aToB, bToA) <= 0.15f;
            string relation;
            if (suspectedSplit && angle <= 6f && separation <= 0.03f)
                relation = "canonical_duplicate_candidate";
            else if (suspectedSplit)
                relation = "tilted_same_family_split_candidate";
            else if (spatiallyObserved && angle >= 35f)
                relation = "structural_crease";
            else if (spatiallyObserved && angle <= 6f && separation > 0.03f)
                relation = "parallel_layer";
            else
                relation = spatiallyObserved ? "distinct_observed" : "not_spatially_observed";

            LastStablePlaneIdentityPairCount++;
            if (spatiallyObserved) LastStablePlaneIdentityObservedPairCount++;
            if (suspectedSplit) LastStablePlaneIdentitySuspectedSplitPairCount++;
            if (relation == "structural_crease") LastStablePlaneIdentityCreasePairCount++;
            _stablePlaneIdentityPairRows
                .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
                .Append(a.Id).Append(',').Append(kindA).Append(',')
                .Append(b.Id).Append(',').Append(kindB).Append(',')
                .Append(normalDot.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(angle.ToString("F3", CultureInfo.InvariantCulture)).Append(',')
                .Append(separation.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(aToB.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(bToA.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(tangentDistance.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(overlapRatio.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(perPlane[a.Id].PublishedTriangles).Append(',')
                .Append(perPlane[b.Id].PublishedTriangles).Append(',')
                .Append(mixed).Append(',').Append(shared).Append(',')
                .Append(minCentroid.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(spatiallyObserved ? 1 : 0).Append(',').Append(relation).Append(',')
                .Append(suspectedSplit ? 1 : 0).AppendLine();
        }
    }

    private static StablePlaneIdentityPairStats GetStablePlaneIdentityPairStats(
        Dictionary<ulong, StablePlaneIdentityPairStats> pairs, int a, int b)
    {
        ulong key = MakeStablePlaneIdentityPairKey(a, b);
        if (!pairs.TryGetValue(key, out StablePlaneIdentityPairStats stats))
        {
            stats = new StablePlaneIdentityPairStats();
            pairs[key] = stats;
        }
        return stats;
    }

    private static ulong MakeStablePlaneIdentityPairKey(int a, int b)
    {
        uint lo = (uint)Mathf.Min(a, b);
        uint hi = (uint)Mathf.Max(a, b);
        return ((ulong)lo << 32) | hi;
    }

    private static float FindStablePlaneIdentityMinCentroidDistance(
        List<Vector3> a, List<Vector3> b)
    {
        if (a == null || b == null || a.Count == 0 || b.Count == 0)
            return -1f;
        float bestSquared = float.PositiveInfinity;
        for (int i = 0; i < a.Count; i++)
        for (int j = 0; j < b.Count; j++)
        {
            float squared = (a[i] - b[j]).sqrMagnitude;
            if (squared < bestSquared) bestSquared = squared;
        }
        return Mathf.Sqrt(bestSquared);
    }

    private void AuditPublishedYellowAgainstStablePlanes(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger,
        Dictionary<int, PlaneFallbackAdaptiveStats> statsByPlane,
        PlaneFallbackAdaptiveStats globalStats)
    {
        if (!enablePlaneConstrainedFallbackAbsolutePlaneAudit || ledger == null)
            return;
        List<ScanCoverStablePlaneRegistry.PlaneConstraint> constraints =
            _stablePlaneRegistry.GetMatureConstraints();
        if (constraints == null || constraints.Count == 0)
            return;
        Dictionary<int, ScanCoverStablePlaneRegistry.PlaneConstraint> byId =
            new Dictionary<int, ScanCoverStablePlaneRegistry.PlaneConstraint>();
        for (int i = 0; i < constraints.Count; i++)
            byId[constraints[i].Id] = constraints[i];

        PlaneFallbackAdaptiveStats globalThreshold = new PlaneFallbackAdaptiveStats();
        ComputePlaneFallbackAdaptiveThresholds(globalThreshold, globalStats);
        float maxBand = Mathf.Max(
            planeConstrainedFallbackAdaptiveMinDistanceMeters,
            planeConstrainedFallbackAbsoluteMaxBandMeters);
        float minNormalDot = Mathf.Clamp(
            planeConstrainedFallbackAbsoluteMinNormalDot, 0.75f, 0.99f);
        float identityMargin = Mathf.Max(
            0.001f, planeConstrainedFallbackPlaneIdentityMarginMeters);
        float extentPadding = Mathf.Max(
            0f, planeConstrainedFallbackAbsoluteExtentPaddingMeters);

        for (int i = 0; i < ledger.Count; i++)
        {
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[i];
            if (entry.Disposition != "publish_plane")
                continue;
            int planeId = entry.TargetPlaneId >= 0 ? entry.TargetPlaneId : entry.NearestPlaneId;
            if (!byId.TryGetValue(planeId,
                    out ScanCoverStablePlaneRegistry.PlaneConstraint target) ||
                target.Normal.sqrMagnitude < 0.5f)
                continue;

            float threshold = statsByPlane != null &&
                              statsByPlane.TryGetValue(planeId, out PlaneFallbackAdaptiveStats planeStats)
                ? planeStats.DistanceThreshold : globalThreshold.DistanceThreshold;
            if (threshold <= 0f)
                threshold = Mathf.Max(0.001f, planeConstrainedFallbackAdaptiveMinDistanceMeters);
            Vector3 targetNormal = target.Normal.normalized;
            Vector3 tangent = entry.Centroid - target.Center;
            tangent -= targetNormal * Vector3.Dot(targetNormal, tangent);
            bool insideTargetExtent = tangent.magnitude <= target.Radius + extentPadding;
            entry.FallbackAbsoluteChecked = true;
            entry.FallbackAbsolutePlaneThreshold = threshold;
            entry.FallbackAbsolutePlaneDistance = Mathf.Abs(
                Vector3.Dot(targetNormal, entry.Centroid) + target.Offset);
            entry.FallbackAbsolutePlaneNormalDot = entry.Normal.sqrMagnitude > 0.5f
                ? Mathf.Abs(Vector3.Dot(entry.Normal.normalized, targetNormal)) : 0f;

            Vector3 rawCentroid = (entry.RawA + entry.RawB + entry.RawC) / 3f;
            Vector3 rawNormal = Vector3.Cross(entry.RawB - entry.RawA, entry.RawC - entry.RawA);
            if (rawNormal.sqrMagnitude < 0.000001f)
                rawNormal = entry.Normal;
            if (rawNormal.sqrMagnitude > 0.000001f)
                rawNormal.Normalize();
            entry.FallbackRawTargetPlaneDistance = Mathf.Abs(
                Vector3.Dot(targetNormal, rawCentroid) + target.Offset);
            entry.FallbackRawNearestPlaneDistance = float.PositiveInfinity;
            for (int planeIndex = 0; planeIndex < constraints.Count; planeIndex++)
            {
                ScanCoverStablePlaneRegistry.PlaneConstraint candidate = constraints[planeIndex];
                if (candidate.Normal.sqrMagnitude < 0.5f)
                    continue;
                Vector3 candidateNormal = candidate.Normal.normalized;
                if (rawNormal.sqrMagnitude > 0.5f &&
                    Mathf.Abs(Vector3.Dot(rawNormal, candidateNormal)) < minNormalDot)
                    continue;
                Vector3 candidateTangent = rawCentroid - candidate.Center;
                candidateTangent -= candidateNormal * Vector3.Dot(candidateNormal, candidateTangent);
                if (candidateTangent.magnitude > candidate.Radius + extentPadding)
                    continue;
                float distance = Mathf.Abs(
                    Vector3.Dot(candidateNormal, rawCentroid) + candidate.Offset);
                if (distance >= entry.FallbackRawNearestPlaneDistance)
                    continue;
                entry.FallbackRawNearestPlaneDistance = distance;
                entry.FallbackRawNearestPlaneId = candidate.Id;
            }
            if (float.IsPositiveInfinity(entry.FallbackRawNearestPlaneDistance))
                entry.FallbackRawNearestPlaneDistance = 0f;

            bool absoluteOffset = insideTargetExtent &&
                                  entry.FallbackAbsolutePlaneNormalDot >= minNormalDot &&
                                  entry.FallbackAbsolutePlaneDistance > threshold &&
                                  entry.FallbackAbsolutePlaneDistance <= maxBand;
            bool identityConflict = entry.FallbackRawNearestPlaneId >= 0 &&
                                    entry.FallbackRawNearestPlaneId != planeId &&
                                    entry.FallbackRawNearestPlaneDistance <= maxBand &&
                                    entry.FallbackRawTargetPlaneDistance -
                                    entry.FallbackRawNearestPlaneDistance > identityMargin;
            if (!absoluteOffset && !identityConflict)
                continue;
            if (absoluteOffset)
            {
                AppendPlaneFallbackReason(entry, "absolute_plane_offset");
                LastPlaneConstrainedZeroCrossFallbackAbsoluteOffsetTriangleCount++;
            }
            if (identityConflict)
            {
                AppendPlaneFallbackReason(entry, "plane_identity_conflict");
                LastPlaneConstrainedZeroCrossFallbackPlaneIdentityConflictTriangleCount++;
            }
            MarkPlaneLedgerFallbackSuspect(
                entry,
                absoluteOffset && identityConflict
                    ? "absolute_plane_offset|plane_identity_conflict"
                    : absoluteOffset ? "absolute_plane_offset" : "plane_identity_conflict",
                absoluteOffset ? entry.FallbackAbsolutePlaneDistance :
                    entry.FallbackRawTargetPlaneDistance,
                entry.FallbackAbsolutePlaneNormalDot);
        }
    }

    private static void AppendPlaneFallbackReason(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry,
        string reason)
    {
        if (entry.FallbackAuditReason == "none" ||
            entry.FallbackAuditReason == "local_consistent")
            entry.FallbackAuditReason = reason;
        else if (!entry.FallbackAuditReason.Contains(reason))
            entry.FallbackAuditReason += "|" + reason;
    }

    private void ComputePlaneFallbackAdaptiveThresholds(
        PlaneFallbackAdaptiveStats output,
        PlaneFallbackAdaptiveStats source)
    {
        float legacyDistance = Mathf.Max(
            planeConstrainedFallbackMaxLocalDistanceMeters, voxelSizeMeters * 0.30f);
        float legacyNormalDot = Mathf.Clamp(
            planeConstrainedFallbackMinNormalDot, 0.2f, 1f);
        if (!enablePlaneConstrainedFallbackAdaptiveThresholds || source == null ||
            source.Distances.Count == 0 || source.NormalDeviations.Count == 0)
        {
            output.DistanceThreshold = legacyDistance;
            output.NormalDotThreshold = legacyNormalDot;
            return;
        }

        // This is a visible-surface diagnostic, not an extraction stability gate.
        // Do not let a coarse TSDF voxel raise an 8 mm lesion threshold to 12+ mm.
        float minDistance = Mathf.Max(
            0.001f, planeConstrainedFallbackAdaptiveMinDistanceMeters);
        float maxDistance = Mathf.Max(
            minDistance, planeConstrainedFallbackAdaptiveMaxDistanceMeters);
        float distanceMedian = MedianOfListCopy(source.Distances);
        float distanceMad = MedianAbsoluteDeviation(source.Distances, distanceMedian);
        float robustDistance = distanceMedian +
            Mathf.Max(1f, planeConstrainedFallbackAdaptiveDistanceMadScale) * 1.4826f * distanceMad;
        output.DistanceThreshold = Mathf.Clamp(robustDistance, minDistance, maxDistance);

        float deviationMedian = MedianOfListCopy(source.NormalDeviations);
        float deviationMad = MedianAbsoluteDeviation(source.NormalDeviations, deviationMedian);
        float minimumDeviation = 1f - Mathf.Clamp(
            planeConstrainedFallbackAdaptiveMinNormalDot, 0.75f, 0.99f);
        float maximumDeviation = Mathf.Max(minimumDeviation, 1f - legacyNormalDot);
        float robustDeviation = deviationMedian +
            Mathf.Max(1f, planeConstrainedFallbackAdaptiveNormalMadScale) * 1.4826f * deviationMad;
        output.NormalDotThreshold = 1f - Mathf.Clamp(
            Mathf.Max(minimumDeviation, robustDeviation), minimumDeviation, maximumDeviation);
    }

    private static float MedianOfListCopy(List<float> values)
    {
        if (values == null || values.Count == 0)
            return 0f;
        List<float> sorted = new List<float>(values);
        sorted.Sort();
        int middle = sorted.Count / 2;
        return (sorted.Count & 1) != 0
            ? sorted[middle]
            : (sorted[middle - 1] + sorted[middle]) * 0.5f;
    }

    private static float MedianAbsoluteDeviation(List<float> values, float median)
    {
        if (values == null || values.Count == 0)
            return 0f;
        List<float> deviations = new List<float>(values.Count);
        for (int i = 0; i < values.Count; i++)
            deviations.Add(Mathf.Abs(values[i] - median));
        return MedianOfListCopy(deviations);
    }

    private static void AddPlaneLedgerAdjacentTriangles(
        HashSet<int> neighbours,
        Dictionary<AuthoritativeCanonicalEdgeKey, List<int>> edgeTriangles,
        AuthoritativeCanonicalEdgeKey edge,
        int self)
    {
        if (!edgeTriangles.TryGetValue(edge, out List<int> attached))
            return;
        for (int i = 0; i < attached.Count; i++)
            if (attached[i] != self) neighbours.Add(attached[i]);
    }

    private void AuditPublishedYellowIsolatedComponents(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger,
        Dictionary<AuthoritativeCanonicalEdgeKey, List<int>> edgeTriangles)
    {
        if (!enablePlaneConstrainedPublishedFallbackAudit || ledger == null || edgeTriangles == null)
            return;
        int[] parents = CreatePlaneLedgerParents(ledger.Count);
        foreach (List<int> attached in edgeTriangles.Values)
        {
            for (int a = 0; a < attached.Count; a++)
            for (int b = a + 1; b < attached.Count; b++)
            {
                PlaneConstrainedZeroCrossTriangleLedgerEntry ta = ledger[attached[a]];
                PlaneConstrainedZeroCrossTriangleLedgerEntry tb = ledger[attached[b]];
                if (ta.Disposition == "publish_plane" && tb.Disposition == "publish_plane" &&
                    ta.TargetPlaneId >= 0 && ta.TargetPlaneId == tb.TargetPlaneId)
                    UnionPlaneLedger(parents, attached[a], attached[b]);
            }
        }
        Dictionary<int, int> componentSizes = new Dictionary<int, int>();
        for (int i = 0; i < ledger.Count; i++)
        {
            if (ledger[i].Disposition != "publish_plane")
                continue;
            int root = FindPlaneLedgerRoot(parents, i);
            componentSizes.TryGetValue(root, out int count);
            componentSizes[root] = count + 1;
        }
        int maxIsolated = Mathf.Clamp(planeConstrainedFallbackMaxIsolatedComponentTriangles, 1, 16);
        for (int i = 0; i < ledger.Count; i++)
        {
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[i];
            if (entry.Disposition != "publish_plane" ||
                !componentSizes.TryGetValue(FindPlaneLedgerRoot(parents, i), out int size) || size > maxIsolated)
                continue;
            entry.FallbackAuditChecked = true;
            entry.FallbackAuditReason = entry.FallbackAuditReason == "none" ||
                                        entry.FallbackAuditReason == "insufficient_adjacent_support"
                ? "isolated_published_component"
                : entry.FallbackAuditReason + "|isolated_published_component";
            LastPlaneConstrainedZeroCrossFallbackIsolatedTriangleCount++;
            MarkPlaneLedgerFallbackSuspect(entry, "isolated_published_component");
        }
    }

    private static void MarkPlaneLedgerFallbackSuspect(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry,
        string reason,
        float diagnosticDistance = -1f,
        float diagnosticNormalDot = -1f)
    {
        if (entry == null)
            return;
        string taggedReason = reason.StartsWith("fallback_", System.StringComparison.Ordinal)
            ? reason : "fallback_" + reason;
        if (!entry.GeometricSuspect)
        {
            entry.GeometricSuspect = true;
            entry.GeometricSuspectReason = taggedReason;
            entry.GeometricSuspectPlaneId = entry.TargetPlaneId >= 0
                ? entry.TargetPlaneId : entry.NearestPlaneId;
            entry.GeometricSuspectPlaneKind = entry.PlaneKind;
            entry.GeometricSuspectDistance = diagnosticDistance >= 0f
                ? diagnosticDistance : entry.FallbackDistance;
            entry.GeometricSuspectNormalDot = diagnosticNormalDot >= 0f
                ? diagnosticNormalDot : entry.FallbackNormalDot;
        }
        else if (!entry.GeometricSuspectReason.Contains(taggedReason))
        {
            entry.GeometricSuspectReason += "|" + taggedReason;
        }
    }

    private static AuthoritativeCanonicalEdgeKey MakeAuthoritativeCanonicalEdge(
        AuthoritativeCellComponentKey a,
        AuthoritativeCellComponentKey b)
    {
        if (CompareAuthoritativeCellComponentKey(a, b) <= 0)
            return new AuthoritativeCanonicalEdgeKey { A = a, B = b };
        return new AuthoritativeCanonicalEdgeKey { A = b, B = a };
    }

    private static int CompareAuthoritativeCellComponentKey(
        AuthoritativeCellComponentKey a,
        AuthoritativeCellComponentKey b)
    {
        int compare = a.Cell.x.CompareTo(b.Cell.x);
        if (compare != 0) return compare;
        compare = a.Cell.y.CompareTo(b.Cell.y);
        if (compare != 0) return compare;
        compare = a.Cell.z.CompareTo(b.Cell.z);
        return compare != 0 ? compare : a.Component.CompareTo(b.Component);
    }

    private static void AddPlaneLedgerEdge(
        Dictionary<AuthoritativeCanonicalEdgeKey, List<int>> edges,
        AuthoritativeCanonicalEdgeKey edge,
        int triangle)
    {
        if (!edges.TryGetValue(edge, out List<int> attached))
        {
            attached = new List<int>(2);
            edges[edge] = attached;
        }
        attached.Add(triangle);
    }

    private static int[] CreatePlaneLedgerParents(int count)
    {
        int[] parents = new int[count];
        for (int i = 0; i < count; i++) parents[i] = i;
        return parents;
    }

    private static int FindPlaneLedgerRoot(int[] parents, int value)
    {
        int root = value;
        while (parents[root] != root) root = parents[root];
        while (parents[value] != value)
        {
            int next = parents[value];
            parents[value] = root;
            value = next;
        }
        return root;
    }

    private static void UnionPlaneLedger(int[] parents, int a, int b)
    {
        int rootA = FindPlaneLedgerRoot(parents, a);
        int rootB = FindPlaneLedgerRoot(parents, b);
        if (rootA != rootB) parents[rootB] = rootA;
    }

    private static string PlaneLedgerIssueFamily(PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        if (entry.AtomicClass == "full_same_plane") return "clean_plane";
        if (entry.AtomicClass == "cross_plane") return "junction";
        if (entry.AtomicClass == "unowned_nonstructural") return "nonplanar";
        return "plane_problem";
    }

    private static bool SamePlaneLedgerIssueFamily(
        PlaneConstrainedZeroCrossTriangleLedgerEntry a,
        PlaneConstrainedZeroCrossTriangleLedgerEntry b)
    {
        return a.TargetPlaneId == b.TargetPlaneId &&
               PlaneLedgerIssueFamily(a) == PlaneLedgerIssueFamily(b);
    }

    private static bool IsPlaneLedgerProblem(PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        return entry.Disposition == "hold_reextract" ||
               entry.Disposition == "junction_reextract";
    }

    private static string GetPlaneLedgerDisplayClass(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        if (entry == null) return "none";
        if (entry.HardAuditChecked)
        {
            if (entry.RelaxedClass == "formal_structural") return "structural_formal_yellow";
            if (entry.RelaxedClass == "provisional_structural") return "structural_provisional_orange";
            if (entry.RelaxedClass == "confirmed_complex") return "complex_confirmed_green";
            if (entry.RelaxedClass == "hard_illegal") return "hard_illegal_red";
            if (entry.RelaxedClass == "pending") return "held_reextract_magenta";
            return "unclassified_gray";
        }
        if (entry.Disposition == "publish_plane")
            return entry.GeometricSuspect ? "structural_provisional_orange" : "structural_formal_yellow";
        if (IsPlaneLedgerProblem(entry)) return "held_reextract_magenta";
        if (entry.Disposition == "publish_nonplanar") return "complex_confirmed_green";
        return "observe_hidden";
    }

    private static bool IsRelaxedCandidatePending(PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        return entry != null && entry.HardAuditChecked
            ? entry.RelaxedClass == "pending"
            : IsPlaneLedgerProblem(entry);
    }

    private static Vector3 RelaxedDisplayA(PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        return entry != null && entry.HasRelaxedProjection ? entry.RelaxedA : entry.A;
    }

    private static Vector3 RelaxedDisplayB(PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        return entry != null && entry.HasRelaxedProjection ? entry.RelaxedB : entry.B;
    }

    private static Vector3 RelaxedDisplayC(PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        return entry != null && entry.HasRelaxedProjection ? entry.RelaxedC : entry.C;
    }

    private static int CountPlaneLedgerProblemComponents(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger)
    {
        HashSet<int> ids = new HashSet<int>();
        for (int i = 0; i < ledger.Count; i++)
            if (IsPlaneLedgerProblem(ledger[i])) ids.Add(ledger[i].IssueComponentId);
        return ids.Count;
    }

    private List<PlaneSupportCellLedgerEntry> BuildPlaneSupportCellLedger(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        int blockVoxels)
    {
        List<PlaneSupportCellLedgerEntry> cells = new List<PlaneSupportCellLedgerEntry>();
        if (!enablePlaneSupportCellLedger || ledger == null || planes == null ||
            _authoritativeCyanPlaneSupportTiles.Count == 0)
            return cells;

        Dictionary<int, ScanCoverStablePlaneRegistry.PlaneConstraint> planesById =
            new Dictionary<int, ScanCoverStablePlaneRegistry.PlaneConstraint>();
        for (int i = 0; i < planes.Count; i++)
            planesById[planes[i].Id] = planes[i];

        Dictionary<int, HashSet<int>> candidateIndicesByPlane =
            new Dictionary<int, HashSet<int>>();
        for (int i = 0; i < ledger.Count; i++)
        {
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[i];
            AddPlaneSupportCandidate(candidateIndicesByPlane, entry.TargetPlaneId, i);
            AddPlaneSupportCandidate(candidateIndicesByPlane, entry.NearestPlaneId, i);
            AddPlaneSupportCandidate(candidateIndicesByPlane, entry.IndependentPlaneId, i);
            AddPlaneSupportCandidate(candidateIndicesByPlane, entry.NonplanarCandidatePlaneId, i);
            AddPlaneSupportCandidate(candidateIndicesByPlane, entry.PlaneA, i);
            AddPlaneSupportCandidate(candidateIndicesByPlane, entry.PlaneB, i);
            AddPlaneSupportCandidate(candidateIndicesByPlane, entry.PlaneC, i);
        }

        int maxCells = Mathf.Clamp(maxPlaneSupportDiagnosticCells, 256, 32768);
        float tileSize = Mathf.Clamp(authoritativeCyanLocalSupportTileSizeMeters, 0.20f, 0.50f);
        int subdivisions = Mathf.Clamp(
            Mathf.CeilToInt(tileSize / Mathf.Clamp(
                planeSupportDiagnosticCellSizeMeters, 0.05f, 0.20f)), 1, 10);
        float cellSize = tileSize / subdivisions;
        float nearPlaneBand = Mathf.Max(voxelSizeMeters * 1.25f,
            authoritativeCyanAdaptivePlaneMaxDistanceMeters);

        int cellsPerTile = subdivisions * subdivisions;
        int maxDiagnosticTiles = Mathf.Max(1, maxCells / Mathf.Max(1, cellsPerTile));
        List<AuthoritativeCyanPlaneTileKey> tileKeys =
            BuildPlaneSupportDiagnosticTileDomain(
                planesById, maxDiagnosticTiles,
                out HashSet<AuthoritativeCyanPlaneTileKey> inferredTileKeys);
        Dictionary<AuthoritativeCyanPlaneTileKey, int> tilePriorities =
            new Dictionary<AuthoritativeCyanPlaneTileKey, int>();
        for (int i = 0; i < tileKeys.Count; i++)
        {
            AuthoritativeCyanPlaneTileKey key = tileKeys[i];
            if (inferredTileKeys.Contains(key))
            {
                tilePriorities[key] = 1;
                continue;
            }
            bool qualified = false;
            if (planesById.TryGetValue(
                    key.PlaneId, out ScanCoverStablePlaneRegistry.PlaneConstraint candidatePlane))
                qualified = IsAuthoritativeCyanStructuralPlane(candidatePlane, out _, out _);
            if (_authoritativeCyanPlaneSupportTiles.TryGetValue(
                    key, out AuthoritativeCyanPlaneSupportTile candidateTile) &&
                candidateTile != null &&
                candidateTile.State != AuthoritativeCyanLocalSupportState.Candidate &&
                planesById.TryGetValue(key.PlaneId, out candidatePlane) &&
                IsAuthoritativeCyanLocalStructuralCandidate(
                    candidatePlane, out _, out _, out _))
                qualified = true;
            tilePriorities[key] = qualified ? 0 : 2;
        }
        tileKeys.Sort((a, b) =>
        {
            int compare = tilePriorities[a].CompareTo(tilePriorities[b]);
            if (compare != 0) return compare;
            compare = a.PlaneId.CompareTo(b.PlaneId);
            if (compare != 0) return compare;
            compare = a.U.CompareTo(b.U);
            return compare != 0 ? compare : a.V.CompareTo(b.V);
        });
        for (int tileIndex = 0; tileIndex < tileKeys.Count; tileIndex++)
        {
            AuthoritativeCyanPlaneTileKey tileKey = tileKeys[tileIndex];
            bool inferredTile = inferredTileKeys.Contains(tileKey);
            _authoritativeCyanPlaneSupportTiles.TryGetValue(
                tileKey, out AuthoritativeCyanPlaneSupportTile tile);
            if ((!inferredTile && tile == null) ||
                !planesById.TryGetValue(tileKey.PlaneId,
                    out ScanCoverStablePlaneRegistry.PlaneConstraint plane) ||
                plane.Normal.sqrMagnitude < 0.5f)
                continue;
            AuthoritativeCyanPlaneSupportFrame frame = GetOrCreatePlaneSupportFrame(plane);
            bool globallyQualified = IsAuthoritativeCyanStructuralPlane(
                plane, out string globalKind, out string globalReject);
            bool localEligible = IsAuthoritativeCyanLocalStructuralCandidate(
                plane, out _, out string localKind, out _);
            string kind = tile == null || string.IsNullOrEmpty(tile.PlaneKind) || tile.PlaneKind == "none"
                ? (localKind == "none" ? globalKind : localKind) : tile.PlaneKind;
            AuthoritativeCyanLocalSupportState tileState = inferredTile
                ? (globallyQualified
                    ? AuthoritativeCyanLocalSupportState.GlobalQualified
                    : AuthoritativeCyanLocalSupportState.LocalQualified)
                : tile.State;
            bool locallyQualified = localEligible &&
                tileState != AuthoritativeCyanLocalSupportState.Candidate;
            string qualification = globallyQualified ? "global" :
                locallyQualified ? (inferredTile ? "local_inferred" : "local") : "candidate";
            float tileMinU = tileKey.U * tileSize;
            float tileMinV = tileKey.V * tileSize;
            candidateIndicesByPlane.TryGetValue(tileKey.PlaneId, out HashSet<int> candidateIndices);
            for (int subV = 0; subV < subdivisions; subV++)
            for (int subU = 0; subU < subdivisions; subU++)
            {
                if (cells.Count >= maxCells)
                {
                    LastPlaneSupportTruncatedCellCount++;
                    continue;
                }
                float minU = tileMinU + subU * cellSize;
                float maxU = minU + cellSize;
                float minV = tileMinV + subV * cellSize;
                float maxV = minV + cellSize;
                PlaneSupportCellLedgerEntry cell = new PlaneSupportCellLedgerEntry
                {
                    LedgerId = cells.Count,
                    PlaneId = tileKey.PlaneId,
                    PlaneKind = kind,
                    Qualification = qualification,
                    GlobalReject = globallyQualified ? "none" : globalReject,
                    SupportSource = inferredTile ? "inferred_enclosed_tile" : "observed_tile",
                    TileState = tileState,
                    TileU = tileKey.U,
                    TileV = tileKey.V,
                    SubU = subU,
                    SubV = subV,
                    MinU = minU,
                    MaxU = maxU,
                    MinV = minV,
                    MaxV = maxV
                };
                int directCellU = tileKey.U * subdivisions + subU;
                int directCellV = tileKey.V * subdivisions + subV;
                cell.DirectEvidence = TryGetAuthoritativeCyanDirectSupport(
                    tileKey.PlaneId, directCellU, directCellV,
                    out AuthoritativeCyanPlaneDirectSupportCell directSupport);
                if (directSupport != null)
                {
                    cell.DirectLastSnapshot = directSupport.LastObservedSnapshot;
                    cell.DirectSampleCount = directSupport.LastSampleCount;
                    cell.DirectTotalSamples = directSupport.TotalSamples;
                    cell.DirectMissingBatches = directSupport.MissingBatches;
                }
                if (cell.DirectEvidence)
                {
                    LastPlaneSupportDirectEvidenceCellCount++;
                    cell.SupportSource = cell.DirectLastSnapshot ==
                        LastAuthoritativeReadSnapshotSequence
                        ? "direct_depth_current" : "direct_depth_history";
                }
                else
                {
                    LastPlaneSupportUnobservedCellCount++;
                    cell.SupportSource = inferredTile
                        ? "inferred_enclosed_unobserved"
                        : "tile_without_direct_depth";
                }
                if (inferredTile)
                    LastPlaneSupportInferredCellCount++;
                cell.CornerA = BuildPlaneSupportPointOnCurrentPlane(plane, frame, minU, minV);
                cell.CornerB = BuildPlaneSupportPointOnCurrentPlane(plane, frame, maxU, minV);
                cell.CornerC = BuildPlaneSupportPointOnCurrentPlane(plane, frame, maxU, maxV);
                cell.CornerD = BuildPlaneSupportPointOnCurrentPlane(plane, frame, minU, maxV);
                cell.Center = (cell.CornerA + cell.CornerB + cell.CornerC + cell.CornerD) * 0.25f;
                cell.Block = AuthoritativeBlockKey(
                    cell.Center, Mathf.Max(0.001f, voxelSizeMeters * Mathf.Max(1, blockVoxels)));

                if (candidateIndices != null)
                {
                    foreach (int triangleIndex in candidateIndices)
                    {
                        if (triangleIndex < 0 || triangleIndex >= ledger.Count)
                            continue;
                        PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[triangleIndex];
                        if (!PlaneLedgerRawTriangleOverlapsSupportCell(
                                entry, plane, frame, cell, nearPlaneBand))
                            continue;
                        cell.AnyTriangles++;
                        if (entry.HardAuditChecked &&
                            (entry.RelaxedClass == "formal_structural" ||
                             entry.RelaxedClass == "provisional_structural"))
                        {
                            if (entry.TargetPlaneId == cell.PlaneId)
                            {
                                if (entry.RelaxedClass == "provisional_structural") cell.SuspectStructuralTriangles++;
                                else cell.HealthyStructuralTriangles++;
                            }
                            else if (entry.IndependentPlaneId == cell.PlaneId ||
                                     entry.FallbackRawNearestPlaneId == cell.PlaneId)
                            {
                                cell.WrongPlaneTriangles++;
                            }
                        }
                        else if (entry.HardAuditChecked && entry.RelaxedClass == "hard_illegal")
                        {
                            cell.IllegalTriangles++;
                        }
                        else if (IsRelaxedCandidatePending(entry))
                        {
                            cell.HeldTriangles++;
                        }
                        else if (entry.HardAuditChecked && entry.RelaxedClass == "confirmed_complex")
                        {
                            cell.NonplanarTriangles++;
                        }
                        else if (entry.HardAuditChecked && entry.RelaxedClass == "unclassified")
                        {
                            cell.UnclassifiedTriangles++;
                        }
                    }
                }

                int published = cell.HealthyStructuralTriangles + cell.SuspectStructuralTriangles;
                if (!cell.DirectEvidence)
                {
                    cell.Classification = "support_unknown_unobserved";
                    cell.Reason = inferredTile
                        ? "inferred_without_direct_depth_evidence"
                        : "tile_without_direct_depth_evidence";
                    LastPlaneSupportUnknownCellCount++;
                    if (cell.AnyTriangles > 0) LastPlaneSupportUnknownWithTrianglesCount++;
                    else LastPlaneSupportUnknownEmptyCount++;
                }
                else if (!globallyQualified && !locallyQualified)
                {
                    cell.Classification = "support_unknown_candidate";
                    cell.Reason = cell.AnyTriangles > 0
                        ? "candidate_support_with_triangles" : "candidate_support_without_triangles";
                    LastPlaneSupportUnknownCellCount++;
                    if (cell.AnyTriangles > 0) LastPlaneSupportUnknownWithTrianglesCount++;
                    else LastPlaneSupportUnknownEmptyCount++;
                }
                else if (published > 0)
                {
                    bool mixedSuspect = cell.SuspectStructuralTriangles > 0 ||
                                        cell.WrongPlaneTriangles > 0;
                    cell.Classification = mixedSuspect
                        ? "support_covered_orange_provisional" : "support_covered_yellow";
                    cell.Reason = cell.WrongPlaneTriangles > 0
                        ? "covered_with_wrong_plane_overlap"
                        : cell.SuspectStructuralTriangles > 0
                            ? "covered_with_suspect_structural_triangles"
                            : "healthy_structural_coverage";
                    LastPlaneSupportQualifiedCellCount++;
                    LastPlaneSupportCoveredCellCount++;
                }
                else
                {
                    LastPlaneSupportQualifiedCellCount++;
                    cell.Gap = true;
                    cell.Classification = "support_gap_red";
                    LastPlaneSupportGapCellCount++;
                    if (cell.IllegalTriangles > 0)
                    {
                        cell.Reason = "hard_illegal_candidate";
                        LastPlaneSupportGapIllegalCount++;
                    }
                    else if (cell.WrongPlaneTriangles > 0)
                    {
                        cell.Reason = "wrong_plane_assignment";
                        LastPlaneSupportGapWrongPlaneCount++;
                    }
                    else if (cell.HeldTriangles > 0)
                    {
                        cell.Reason = "held_reextract_only";
                        LastPlaneSupportGapHeldCount++;
                    }
                    else if (cell.NonplanarTriangles > 0)
                    {
                        cell.Reason = "classified_nonplanar_only";
                        LastPlaneSupportGapNonplanarCount++;
                    }
                    else
                    {
                        cell.Reason = "no_zero_cross_triangle";
                        LastPlaneSupportGapNoTriangleCount++;
                    }
                }
                cells.Add(cell);
            }
        }
        LastPlaneSupportCellCount = cells.Count;
        LastPlaneSupportClassificationClosureDelta = cells.Count -
            LastPlaneSupportCoveredCellCount - LastPlaneSupportGapCellCount -
            LastPlaneSupportUnknownCellCount;
        return cells;
    }

    private List<AuthoritativeCyanPlaneTileKey> BuildPlaneSupportDiagnosticTileDomain(
        Dictionary<int, ScanCoverStablePlaneRegistry.PlaneConstraint> planesById,
        int maxDiagnosticTiles,
        out HashSet<AuthoritativeCyanPlaneTileKey> inferredTileKeys)
    {
        HashSet<AuthoritativeCyanPlaneTileKey> domain =
            new HashSet<AuthoritativeCyanPlaneTileKey>(
                _authoritativeCyanPlaneSupportTiles.Keys);
        inferredTileKeys = new HashSet<AuthoritativeCyanPlaneTileKey>();
        Dictionary<long, Vector2Int> rowBounds = new Dictionary<long, Vector2Int>();
        Dictionary<long, Vector2Int> columnBounds = new Dictionary<long, Vector2Int>();
        Dictionary<int, int[]> planeBounds = new Dictionary<int, int[]>();
        int qualifiedObservedTiles = 0;
        foreach (KeyValuePair<AuthoritativeCyanPlaneTileKey, AuthoritativeCyanPlaneSupportTile> pair
                 in _authoritativeCyanPlaneSupportTiles)
        {
            AuthoritativeCyanPlaneTileKey key = pair.Key;
            AuthoritativeCyanPlaneSupportTile tile = pair.Value;
            if (tile == null || !planesById.TryGetValue(
                    key.PlaneId, out ScanCoverStablePlaneRegistry.PlaneConstraint plane))
                continue;
            bool global = IsAuthoritativeCyanStructuralPlane(plane, out _, out _);
            bool localEligible = IsAuthoritativeCyanLocalStructuralCandidate(
                plane, out _, out _, out _);
            bool qualified = global ||
                             (localEligible &&
                              tile.State != AuthoritativeCyanLocalSupportState.Candidate);
            if (!qualified)
                continue;
            qualifiedObservedTiles++;
            ExpandPlaneSupportAxisBounds(
                rowBounds, MakePlaneSupportAxisKey(key.PlaneId, key.V), key.U);
            ExpandPlaneSupportAxisBounds(
                columnBounds, MakePlaneSupportAxisKey(key.PlaneId, key.U), key.V);
            if (!planeBounds.TryGetValue(key.PlaneId, out int[] bounds))
            {
                bounds = new[] { key.U, key.U, key.V, key.V };
                planeBounds[key.PlaneId] = bounds;
            }
            else
            {
                bounds[0] = Mathf.Min(bounds[0], key.U);
                bounds[1] = Mathf.Max(bounds[1], key.U);
                bounds[2] = Mathf.Min(bounds[2], key.V);
                bounds[3] = Mathf.Max(bounds[3], key.V);
            }
        }

        int inferredBudget = Mathf.Max(0, maxDiagnosticTiles - qualifiedObservedTiles);
        List<int> planeIds = new List<int>(planeBounds.Keys);
        planeIds.Sort();
        for (int planeIndex = 0;
             planeIndex < planeIds.Count && inferredTileKeys.Count < inferredBudget;
             planeIndex++)
        {
            int planeId = planeIds[planeIndex];
            int[] bounds = planeBounds[planeId];
            for (int v = bounds[2];
                 v <= bounds[3] && inferredTileKeys.Count < inferredBudget;
                 v++)
            {
                if (!rowBounds.TryGetValue(
                        MakePlaneSupportAxisKey(planeId, v), out Vector2Int row))
                    continue;
                for (int u = row.x;
                     u <= row.y && inferredTileKeys.Count < inferredBudget;
                     u++)
                {
                    AuthoritativeCyanPlaneTileKey key = new AuthoritativeCyanPlaneTileKey
                    {
                        PlaneId = planeId,
                        U = u,
                        V = v
                    };
                    if (domain.Contains(key) ||
                        !columnBounds.TryGetValue(
                            MakePlaneSupportAxisKey(planeId, u), out Vector2Int column) ||
                        v < column.x || v > column.y)
                        continue;
                    domain.Add(key);
                    inferredTileKeys.Add(key);
                }
            }
        }
        return new List<AuthoritativeCyanPlaneTileKey>(domain);
    }

    private static long MakePlaneSupportAxisKey(int planeId, int coordinate)
    {
        return ((long)planeId << 32) ^ (uint)coordinate;
    }

    private static void ExpandPlaneSupportAxisBounds(
        Dictionary<long, Vector2Int> boundsByAxis,
        long key,
        int coordinate)
    {
        if (!boundsByAxis.TryGetValue(key, out Vector2Int bounds))
        {
            boundsByAxis[key] = new Vector2Int(coordinate, coordinate);
            return;
        }
        bounds.x = Mathf.Min(bounds.x, coordinate);
        bounds.y = Mathf.Max(bounds.y, coordinate);
        boundsByAxis[key] = bounds;
    }

    private static void AddPlaneSupportCandidate(
        Dictionary<int, HashSet<int>> indicesByPlane, int planeId, int triangleIndex)
    {
        if (planeId < 0)
            return;
        if (!indicesByPlane.TryGetValue(planeId, out HashSet<int> indices))
        {
            indices = new HashSet<int>();
            indicesByPlane[planeId] = indices;
        }
        indices.Add(triangleIndex);
    }

    private AuthoritativeCyanPlaneSupportFrame GetOrCreatePlaneSupportFrame(
        ScanCoverStablePlaneRegistry.PlaneConstraint plane)
    {
        if (_authoritativeCyanPlaneSupportFrames.TryGetValue(
                plane.Id, out AuthoritativeCyanPlaneSupportFrame frame))
            return frame;
        Vector3 normal = CanonicalizeAuthoritativeCyanPlaneNormal(plane.Normal);
        Vector3 reference = Mathf.Abs(Vector3.Dot(normal, Vector3.up)) < 0.9f
            ? Vector3.up : Vector3.right;
        frame = new AuthoritativeCyanPlaneSupportFrame
        {
            Normal = normal,
            UAxis = Vector3.Cross(reference, normal).normalized
        };
        frame.VAxis = Vector3.Cross(normal, frame.UAxis).normalized;
        _authoritativeCyanPlaneSupportFrames[plane.Id] = frame;
        return frame;
    }

    private static Vector3 BuildPlaneSupportPointOnCurrentPlane(
        ScanCoverStablePlaneRegistry.PlaneConstraint plane,
        AuthoritativeCyanPlaneSupportFrame frame,
        float u,
        float v)
    {
        Vector3 point = frame.UAxis * u + frame.VAxis * v;
        Vector3 currentNormal = plane.Normal.sqrMagnitude > 0.5f
            ? plane.Normal.normalized : frame.Normal;
        return point - currentNormal * (Vector3.Dot(currentNormal, point) + plane.Offset);
    }

    private static bool PlaneLedgerRawTriangleOverlapsSupportCell(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry,
        ScanCoverStablePlaneRegistry.PlaneConstraint plane,
        AuthoritativeCyanPlaneSupportFrame frame,
        PlaneSupportCellLedgerEntry cell,
        float nearPlaneBand)
    {
        Vector3 currentNormal = plane.Normal.sqrMagnitude > 0.5f
            ? plane.Normal.normalized : frame.Normal;
        float da = Vector3.Dot(currentNormal, entry.RawA) + plane.Offset;
        float db = Vector3.Dot(currentNormal, entry.RawB) + plane.Offset;
        float dc = Vector3.Dot(currentNormal, entry.RawC) + plane.Offset;
        float minDistance = Mathf.Min(Mathf.Abs(da), Mathf.Min(Mathf.Abs(db), Mathf.Abs(dc)));
        float minSigned = Mathf.Min(da, Mathf.Min(db, dc));
        float maxSigned = Mathf.Max(da, Mathf.Max(db, dc));
        if (minDistance > nearPlaneBand && !(minSigned <= 0f && maxSigned >= 0f))
            return false;
        Vector2 a = new Vector2(Vector3.Dot(entry.RawA, frame.UAxis), Vector3.Dot(entry.RawA, frame.VAxis));
        Vector2 b = new Vector2(Vector3.Dot(entry.RawB, frame.UAxis), Vector3.Dot(entry.RawB, frame.VAxis));
        Vector2 c = new Vector2(Vector3.Dot(entry.RawC, frame.UAxis), Vector3.Dot(entry.RawC, frame.VAxis));
        return TriangleOverlapsRectangle2D(a, b, c, cell.MinU, cell.MaxU, cell.MinV, cell.MaxV);
    }

    private static bool TriangleOverlapsRectangle2D(
        Vector2 a, Vector2 b, Vector2 c,
        float minX, float maxX, float minY, float maxY)
    {
        if (Mathf.Max(a.x, Mathf.Max(b.x, c.x)) < minX ||
            Mathf.Min(a.x, Mathf.Min(b.x, c.x)) > maxX ||
            Mathf.Max(a.y, Mathf.Max(b.y, c.y)) < minY ||
            Mathf.Min(a.y, Mathf.Min(b.y, c.y)) > maxY)
            return false;
        if (PointInsideRectangle2D(a, minX, maxX, minY, maxY) ||
            PointInsideRectangle2D(b, minX, maxX, minY, maxY) ||
            PointInsideRectangle2D(c, minX, maxX, minY, maxY))
            return true;
        Vector2 r0 = new Vector2(minX, minY);
        Vector2 r1 = new Vector2(maxX, minY);
        Vector2 r2 = new Vector2(maxX, maxY);
        Vector2 r3 = new Vector2(minX, maxY);
        if (PointInsideTriangle2D(r0, a, b, c) || PointInsideTriangle2D(r1, a, b, c) ||
            PointInsideTriangle2D(r2, a, b, c) || PointInsideTriangle2D(r3, a, b, c))
            return true;
        return SegmentsIntersect2D(a, b, r0, r1) || SegmentsIntersect2D(a, b, r1, r2) ||
               SegmentsIntersect2D(a, b, r2, r3) || SegmentsIntersect2D(a, b, r3, r0) ||
               SegmentsIntersect2D(b, c, r0, r1) || SegmentsIntersect2D(b, c, r1, r2) ||
               SegmentsIntersect2D(b, c, r2, r3) || SegmentsIntersect2D(b, c, r3, r0) ||
               SegmentsIntersect2D(c, a, r0, r1) || SegmentsIntersect2D(c, a, r1, r2) ||
               SegmentsIntersect2D(c, a, r2, r3) || SegmentsIntersect2D(c, a, r3, r0);
    }

    private static bool PointInsideRectangle2D(
        Vector2 point, float minX, float maxX, float minY, float maxY)
    {
        return point.x >= minX && point.x <= maxX && point.y >= minY && point.y <= maxY;
    }

    private static bool PointInsideTriangle2D(Vector2 point, Vector2 a, Vector2 b, Vector2 c)
    {
        float d1 = Cross2D(point - b, a - b);
        float d2 = Cross2D(point - c, b - c);
        float d3 = Cross2D(point - a, c - a);
        bool hasNegative = d1 < -0.000001f || d2 < -0.000001f || d3 < -0.000001f;
        bool hasPositive = d1 > 0.000001f || d2 > 0.000001f || d3 > 0.000001f;
        return !(hasNegative && hasPositive);
    }

    private static bool SegmentsIntersect2D(Vector2 a, Vector2 b, Vector2 c, Vector2 d)
    {
        const float epsilon = 0.000001f;
        float abC = Cross2D(b - a, c - a);
        float abD = Cross2D(b - a, d - a);
        float cdA = Cross2D(d - c, a - c);
        float cdB = Cross2D(d - c, b - c);
        bool properIntersection =
            ((abC > epsilon && abD < -epsilon) || (abC < -epsilon && abD > epsilon)) &&
            ((cdA > epsilon && cdB < -epsilon) || (cdA < -epsilon && cdB > epsilon));
        if (properIntersection)
            return true;
        return Mathf.Abs(abC) <= epsilon && PointOnSegment2D(c, a, b, epsilon) ||
               Mathf.Abs(abD) <= epsilon && PointOnSegment2D(d, a, b, epsilon) ||
               Mathf.Abs(cdA) <= epsilon && PointOnSegment2D(a, c, d, epsilon) ||
               Mathf.Abs(cdB) <= epsilon && PointOnSegment2D(b, c, d, epsilon);
    }

    private static bool PointOnSegment2D(
        Vector2 point, Vector2 start, Vector2 end, float epsilon)
    {
        return point.x >= Mathf.Min(start.x, end.x) - epsilon &&
               point.x <= Mathf.Max(start.x, end.x) + epsilon &&
               point.y >= Mathf.Min(start.y, end.y) - epsilon &&
               point.y <= Mathf.Max(start.y, end.y) + epsilon;
    }

    private static float Cross2D(Vector2 a, Vector2 b)
    {
        return a.x * b.y - a.y * b.x;
    }

    private void AppendPlaneSupportCellLedgerRows(
        List<PlaneSupportCellLedgerEntry> cells)
    {
        if (cells == null)
            return;
        if (_planeSupportCellLedgerRows != null)
        {
            for (int i = 0; i < cells.Count; i++)
            {
                PlaneSupportCellLedgerEntry cell = cells[i];
                _planeSupportCellLedgerRows
                    .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
                    .Append(cell.LedgerId).Append(',').Append(cell.PlaneId).Append(',')
                    .Append(cell.PlaneKind).Append(',').Append(cell.Qualification).Append(',')
                    .Append(cell.GlobalReject).Append(',')
                    .Append(cell.SupportSource).Append(',')
                    .Append(cell.TileState.ToString().ToLowerInvariant()).Append(',')
                    .Append(cell.TileU).Append(',').Append(cell.TileV).Append(',')
                    .Append(cell.SubU).Append(',').Append(cell.SubV).Append(',')
                    .Append(cell.Block.x).Append(',').Append(cell.Block.y).Append(',')
                    .Append(cell.Block.z).Append(',').Append(cell.Classification).Append(',')
                    .Append(cell.Reason).Append(',')
                    .Append(cell.HealthyStructuralTriangles).Append(',')
                    .Append(cell.SuspectStructuralTriangles).Append(',')
                    .Append(cell.HeldTriangles).Append(',')
                    .Append(cell.NonplanarTriangles).Append(',')
                    .Append(cell.WrongPlaneTriangles).Append(',')
                    .Append(cell.IllegalTriangles).Append(',')
                    .Append(cell.UnclassifiedTriangles).Append(',')
                    .Append(cell.AnyTriangles).Append(',')
                    .Append(cell.DirectEvidence ? 1 : 0).Append(',')
                    .Append(cell.DirectLastSnapshot).Append(',')
                    .Append(cell.DirectSampleCount).Append(',')
                    .Append(cell.DirectTotalSamples).Append(',')
                    .Append(cell.DirectMissingBatches).Append(',');
                AppendPlaneSupportVector(_planeSupportCellLedgerRows, cell.Center);
                _planeSupportCellLedgerRows.Append(',')
                    .Append(cell.MinU.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                    .Append(cell.MaxU.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                    .Append(cell.MinV.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                    .Append(cell.MaxV.ToString("F6", CultureInfo.InvariantCulture)).Append(',');
                AppendPlaneSupportVector(_planeSupportCellLedgerRows, cell.CornerA);
                _planeSupportCellLedgerRows.Append(',');
                AppendPlaneSupportVector(_planeSupportCellLedgerRows, cell.CornerB);
                _planeSupportCellLedgerRows.Append(',');
                AppendPlaneSupportVector(_planeSupportCellLedgerRows, cell.CornerC);
                _planeSupportCellLedgerRows.Append(',');
                AppendPlaneSupportVector(_planeSupportCellLedgerRows, cell.CornerD);
                _planeSupportCellLedgerRows.AppendLine();
            }
        }

        Camera camera = Camera.main;
        if (_planeSupportCellScreenRows == null || camera == null)
            return;
        for (int i = 0; i < cells.Count; i++)
        {
            AppendPlaneSupportCellScreenRow(
                cells[i], camera, Camera.MonoOrStereoscopicEye.Mono);
            if (!camera.stereoEnabled)
                continue;
            try
            {
                AppendPlaneSupportCellScreenRow(
                    cells[i], camera, Camera.MonoOrStereoscopicEye.Left);
                AppendPlaneSupportCellScreenRow(
                    cells[i], camera, Camera.MonoOrStereoscopicEye.Right);
            }
            catch (System.Exception)
            {
                // Center-eye output remains valid while an XR provider is changing
                // stereo matrices during capture finalization.
            }
        }
    }

    private static void AppendPlaneSupportVector(StringBuilder rows, Vector3 value)
    {
        rows.Append(value.x.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(value.y.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(value.z.ToString("F6", CultureInfo.InvariantCulture));
    }

    private void AppendPlaneSupportCellScreenRow(
        PlaneSupportCellLedgerEntry cell,
        Camera camera,
        Camera.MonoOrStereoscopicEye eye)
    {
        float minU = float.PositiveInfinity, minV = float.PositiveInfinity;
        float maxU = float.NegativeInfinity, maxV = float.NegativeInfinity;
        float minDepth = float.PositiveInfinity, maxDepth = float.NegativeInfinity;
        int front = 0, visible = 0;
        AccumulatePlaneDiagnosticViewportPoint(camera, eye, cell.CornerA,
            ref minU, ref minV, ref maxU, ref maxV, ref minDepth, ref maxDepth,
            ref front, ref visible);
        AccumulatePlaneDiagnosticViewportPoint(camera, eye, cell.CornerB,
            ref minU, ref minV, ref maxU, ref maxV, ref minDepth, ref maxDepth,
            ref front, ref visible);
        AccumulatePlaneDiagnosticViewportPoint(camera, eye, cell.CornerC,
            ref minU, ref minV, ref maxU, ref maxV, ref minDepth, ref maxDepth,
            ref front, ref visible);
        AccumulatePlaneDiagnosticViewportPoint(camera, eye, cell.CornerD,
            ref minU, ref minV, ref maxU, ref maxV, ref minDepth, ref maxDepth,
            ref front, ref visible);
        bool intersects = front > 0 && maxU >= 0f && minU <= 1f &&
                          maxV >= 0f && minV <= 1f;
        if (front == 0)
            minU = minV = maxU = maxV = minDepth = maxDepth = 0f;
        GetPlaneDiagnosticViewportPixels(
            camera, eye, out int viewportWidth, out int viewportHeight,
            out int viewportOffsetX, out int viewportOffsetY);
        float pixelMinX = minU * viewportWidth;
        float pixelMaxX = maxU * viewportWidth;
        float pixelMinY = minV * viewportHeight;
        float pixelMaxY = maxV * viewportHeight;
        float pixelTopMinY = viewportHeight - pixelMaxY;
        float pixelTopMaxY = viewportHeight - pixelMinY;
        _planeSupportCellScreenRows
            .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
            .Append(cell.LedgerId).Append(',').Append(cell.PlaneId).Append(',')
            .Append(cell.PlaneKind).Append(',').Append(cell.Qualification).Append(',')
            .Append(cell.SupportSource).Append(',')
            .Append(cell.Classification).Append(',').Append(cell.Reason).Append(',')
            .Append(cell.DirectEvidence ? 1 : 0).Append(',')
            .Append(cell.DirectSampleCount).Append(',')
            .Append(cell.DirectTotalSamples).Append(',')
            .Append(cell.DirectMissingBatches).Append(',')
            .Append(eye.ToString().ToLowerInvariant()).Append(',')
            .Append(camera.stereoEnabled ? 1 : 0).Append(',')
            .Append(camera.pixelWidth).Append(',').Append(camera.pixelHeight).Append(',')
            .Append(viewportWidth).Append(',').Append(viewportHeight).Append(',')
            .Append(viewportOffsetX).Append(',').Append(viewportOffsetY).Append(',')
            .Append(front).Append(',').Append(visible).Append(',')
            .Append(intersects ? 1 : 0).Append(',')
            .Append(minU.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(minV.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(maxU.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(maxV.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelMinX.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelMinY.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelMaxX.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelMaxY.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelTopMinY.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelTopMaxY.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(minDepth.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(maxDepth.ToString("F6", CultureInfo.InvariantCulture)).AppendLine();
    }

    private void RebuildStablePlaneSupportReferenceWire(
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        List<PlaneSupportCellLedgerEntry> cells)
    {
        if (showStablePlaneShadowWire)
            EnsureStablePlaneShadowObjects();
        if (_stablePlaneShadowMesh != null)
            _stablePlaneShadowMesh.Clear();
        if (!showStablePlaneShadowWire || planes == null || cells == null ||
            cells.Count == 0 || _stablePlaneShadowMesh == null ||
            _stablePlaneShadowObject == null)
        {
            if (_stablePlaneShadowObject != null)
                _stablePlaneShadowObject.SetActive(false);
            return;
        }

        HashSet<int> validPlaneIds = new HashSet<int>();
        for (int i = 0; i < planes.Count; i++)
            validPlaneIds.Add(planes[i].Id);
        List<Vector3> vertices = new List<Vector3>(cells.Count * 8);
        List<int> lines = new List<int>(cells.Count * 8);
        for (int i = 0; i < cells.Count; i++)
        {
            PlaneSupportCellLedgerEntry cell = cells[i];
            if (!validPlaneIds.Contains(cell.PlaneId) ||
                cell.Qualification == "candidate" || !cell.DirectEvidence)
                continue;
            AddPlaneIssueLine(vertices, lines, cell.CornerA, cell.CornerB);
            AddPlaneIssueLine(vertices, lines, cell.CornerB, cell.CornerC);
            AddPlaneIssueLine(vertices, lines, cell.CornerC, cell.CornerD);
            AddPlaneIssueLine(vertices, lines, cell.CornerD, cell.CornerA);
        }
        if (lines.Count == 0)
        {
            _stablePlaneShadowObject.SetActive(false);
            return;
        }
        _stablePlaneShadowMesh.indexFormat =
            vertices.Count > 65535 ? IndexFormat.UInt32 : IndexFormat.UInt16;
        _stablePlaneShadowMesh.SetVertices(vertices);
        _stablePlaneShadowMesh.SetIndices(lines, MeshTopology.Lines, 0, false);
        _stablePlaneShadowMesh.RecalculateBounds();
        _stablePlaneShadowObject.SetActive(true);
    }

