    private void AppendPlaneConstrainedZeroCrossTriangleScreenRows(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger)
    {
        Camera camera = Camera.main;
        if (_planeConstrainedZeroCrossTriangleScreenRows == null ||
            camera == null || ledger == null)
            return;
        for (int i = 0; i < ledger.Count; i++)
        {
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[i];
            AppendPlaneConstrainedZeroCrossTriangleScreenRow(
                entry, camera, Camera.MonoOrStereoscopicEye.Mono);
            if (!camera.stereoEnabled)
                continue;
            try
            {
                AppendPlaneConstrainedZeroCrossTriangleScreenRow(
                    entry, camera, Camera.MonoOrStereoscopicEye.Left);
                AppendPlaneConstrainedZeroCrossTriangleScreenRow(
                    entry, camera, Camera.MonoOrStereoscopicEye.Right);
            }
            catch (System.Exception)
            {
                // Mono rows remain directly usable by Quest casting captures.
            }
        }
    }

