    private void AppendPlaneConstrainedZeroCrossTriangleScreenRow(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry,
        Camera camera,
        Camera.MonoOrStereoscopicEye eye)
    {
        float minU = float.PositiveInfinity, minV = float.PositiveInfinity;
        float maxU = float.NegativeInfinity, maxV = float.NegativeInfinity;
        float minDepth = float.PositiveInfinity, maxDepth = float.NegativeInfinity;
        int front = 0, visible = 0;
        Vector3 displayA = RelaxedDisplayA(entry);
        Vector3 displayB = RelaxedDisplayB(entry);
        Vector3 displayC = RelaxedDisplayC(entry);
        AccumulatePlaneDiagnosticViewportPoint(camera, eye, displayA,
            ref minU, ref minV, ref maxU, ref maxV, ref minDepth, ref maxDepth,
            ref front, ref visible);
        AccumulatePlaneDiagnosticViewportPoint(camera, eye, displayB,
            ref minU, ref minV, ref maxU, ref maxV, ref minDepth, ref maxDepth,
            ref front, ref visible);
        AccumulatePlaneDiagnosticViewportPoint(camera, eye, displayC,
            ref minU, ref minV, ref maxU, ref maxV, ref minDepth, ref maxDepth,
            ref front, ref visible);
        bool intersects = front > 0 && maxU >= 0f && minU <= 1f &&
                          maxV >= 0f && minV <= 1f;
        if (front == 0)
            minU = minV = maxU = maxV = minDepth = maxDepth = 0f;
        GetPlaneDiagnosticViewportPixels(
            camera, eye, out int viewportWidth, out int viewportHeight,
            out int viewportOffsetX, out int viewportOffsetY);
        float pixelMinX = minU * viewportWidth;
        float pixelMaxX = maxU * viewportWidth;
        float pixelMinY = minV * viewportHeight;
        float pixelMaxY = maxV * viewportHeight;
        Vector3 centroidViewport = camera.WorldToViewportPoint(
            (displayA + displayB + displayC) / 3f, eye);
        bool centroidInFront = Finite(centroidViewport) && centroidViewport.z > 0f;
        float centroidPixelX = centroidInFront ? centroidViewport.x * viewportWidth : 0f;
        float centroidPixelY = centroidInFront ? centroidViewport.y * viewportHeight : 0f;
        _planeConstrainedZeroCrossTriangleScreenRows
            .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
            .Append(entry.LedgerId).Append(',').Append(GetPlaneLedgerDisplayClass(entry)).Append(',')
            .Append(entry.Disposition).Append(',').Append(entry.TargetPlaneId).Append(',')
            .Append(entry.IndependentPlaneId).Append(',')
            .Append(entry.GeometricSuspectReason).Append(',')
            .Append(entry.CandidateSource).Append(',')
            .Append(entry.HardLegal ? 1 : 0).Append(',')
            .Append(entry.HardRejectReason).Append(',')
            .Append(entry.RelaxedClass).Append(',')
            .Append(entry.CandidateEvaluationReason).Append(',')
            .Append(entry.HeldReason).Append(',')
            .Append(entry.ProvisionalReason).Append(',')
            .Append(entry.UnclassifiedReason).Append(',')
            .Append(entry.HeldOriginReason).Append(',')
            .Append(entry.HeldRescueEvidence).Append(',')
            .Append(entry.HeldRescueIndependentStatus).Append(',')
            .Append(entry.HeldKeepDecision).Append(',')
            .Append(entry.HeldKeepAction).Append(',')
            .Append(entry.WorkingPublishEligible ? 1 : 0).Append(',')
            .Append(eye.ToString().ToLowerInvariant()).Append(',')
            .Append(camera.stereoEnabled ? 1 : 0).Append(',')
            .Append(camera.pixelWidth).Append(',').Append(camera.pixelHeight).Append(',')
            .Append(viewportWidth).Append(',').Append(viewportHeight).Append(',')
            .Append(viewportOffsetX).Append(',').Append(viewportOffsetY).Append(',')
            .Append(front).Append(',').Append(visible).Append(',')
            .Append(intersects ? 1 : 0).Append(',')
            .Append(minU.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(minV.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(maxU.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(maxV.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelMinX.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelMinY.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelMaxX.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelMaxY.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append((viewportHeight - pixelMaxY).ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append((viewportHeight - pixelMinY).ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(centroidPixelX.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(centroidPixelY.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append((centroidInFront ? viewportHeight - centroidPixelY : 0f)
                .ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(minDepth.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(maxDepth.ToString("F6", CultureInfo.InvariantCulture)).AppendLine();
    }

    private void AppendPlaneConstrainedZeroCrossComponentRows(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger,
        bool issueScope)
    {
        if (_planeConstrainedZeroCrossComponentRows == null)
            return;
        Dictionary<int, List<PlaneConstrainedZeroCrossTriangleLedgerEntry>> groups =
            new Dictionary<int, List<PlaneConstrainedZeroCrossTriangleLedgerEntry>>();
        for (int i = 0; i < ledger.Count; i++)
        {
            int id = issueScope ? ledger[i].IssueComponentId : ledger[i].MeshComponentId;
            if (!groups.TryGetValue(id, out List<PlaneConstrainedZeroCrossTriangleLedgerEntry> group))
            {
                group = new List<PlaneConstrainedZeroCrossTriangleLedgerEntry>();
                groups[id] = group;
            }
            group.Add(ledger[i]);
        }
        foreach (KeyValuePair<int, List<PlaneConstrainedZeroCrossTriangleLedgerEntry>> pair in groups)
        {
            List<PlaneConstrainedZeroCrossTriangleLedgerEntry> group = pair.Value;
            if (group.Count == 0) continue;
            HashSet<int> planeIds = new HashSet<int>();
            HashSet<string> classes = new HashSet<string>();
            HashSet<string> dispositions = new HashSet<string>();
            Vector3 min = new Vector3(float.PositiveInfinity, float.PositiveInfinity, float.PositiveInfinity);
            Vector3 max = new Vector3(float.NegativeInfinity, float.NegativeInfinity, float.NegativeInfinity);
            Vector3 centerSum = Vector3.zero;
            float area = 0f, maxBefore = 0f, maxAfter = 0f;
            float minU = float.PositiveInfinity, maxU = float.NegativeInfinity;
            float minV = float.PositiveInfinity, maxV = float.NegativeInfinity;
            int boundary = 0, problem = 0, suspect = 0;
            int minLedgerId = int.MaxValue, maxLedgerId = int.MinValue;
            for (int i = 0; i < group.Count; i++)
            {
                PlaneConstrainedZeroCrossTriangleLedgerEntry e = group[i];
                if (e.TargetPlaneId >= 0) planeIds.Add(e.TargetPlaneId);
                classes.Add(e.AtomicClass);
                dispositions.Add(e.Disposition);
                min = Vector3.Min(min, Vector3.Min(e.A, Vector3.Min(e.B, e.C)));
                max = Vector3.Max(max, Vector3.Max(e.A, Vector3.Max(e.B, e.C)));
                centerSum += e.Centroid;
                area += e.Area;
                maxBefore = Mathf.Max(maxBefore, e.MeanAbsDistanceBefore);
                maxAfter = Mathf.Max(maxAfter, e.MeanAbsDistanceAfter);
                minU = Mathf.Min(minU, e.PlaneU); maxU = Mathf.Max(maxU, e.PlaneU);
                minV = Mathf.Min(minV, e.PlaneV); maxV = Mathf.Max(maxV, e.PlaneV);
                if (e.Boundary) boundary++;
                if (IsPlaneLedgerProblem(e)) problem++;
                if (e.GeometricSuspect) suspect++;
                minLedgerId = Mathf.Min(minLedgerId, e.LedgerId);
                maxLedgerId = Mathf.Max(maxLedgerId, e.LedgerId);
            }
            Vector3 center = centerSum / group.Count;
            _planeConstrainedZeroCrossComponentRows
                .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
                .Append(issueScope ? "issue" : "mesh").Append(',').Append(pair.Key).Append(',')
                .Append(JoinPlaneLedgerInts(planeIds)).Append(',')
                .Append(JoinPlaneLedgerStrings(classes)).Append(',')
                .Append(JoinPlaneLedgerStrings(dispositions)).Append(',')
                .Append(group.Count).Append(',').Append(problem).Append(',').Append(suspect).Append(',')
                .Append(boundary).Append(',').Append(minLedgerId).Append(',').Append(maxLedgerId).Append(',')
                .Append(area.ToString("F8", CultureInfo.InvariantCulture)).Append(',')
                .Append(center.x.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(center.y.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(center.z.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(min.x.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(min.y.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(min.z.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(max.x.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(max.y.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(max.z.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(minU.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(maxU.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(minV.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(maxV.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(maxBefore.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(maxAfter.ToString("F6", CultureInfo.InvariantCulture)).AppendLine();
            AppendPlaneConstrainedZeroCrossComponentScreenRows(
                group, issueScope ? "issue" : "mesh", pair.Key);
        }
    }

    private static string JoinPlaneLedgerInts(HashSet<int> values)
    {
        List<int> sorted = new List<int>(values);
        sorted.Sort();
        return string.Join("|", sorted);
    }

    private void AppendPlaneDiagnosticCameraRows(Camera camera)
    {
        if (_planeDiagnosticCameraRows == null || camera == null)
            return;
        AppendPlaneDiagnosticCameraRow(
            camera, Camera.MonoOrStereoscopicEye.Mono,
            camera.worldToCameraMatrix, camera.projectionMatrix);
        if (!camera.stereoEnabled)
            return;
        try
        {
            AppendPlaneDiagnosticCameraRow(
                camera, Camera.MonoOrStereoscopicEye.Left,
                camera.GetStereoViewMatrix(Camera.StereoscopicEye.Left),
                camera.GetStereoProjectionMatrix(Camera.StereoscopicEye.Left));
            AppendPlaneDiagnosticCameraRow(
                camera, Camera.MonoOrStereoscopicEye.Right,
                camera.GetStereoViewMatrix(Camera.StereoscopicEye.Right),
                camera.GetStereoProjectionMatrix(Camera.StereoscopicEye.Right));
        }
        catch (System.Exception)
        {
            // Some XR providers report stereo enabled before matrices are available.
            // The mono row remains a valid center-eye diagnostic fallback.
        }
    }

    private void AppendPlaneDiagnosticCameraRow(
        Camera camera,
        Camera.MonoOrStereoscopicEye eye,
        Matrix4x4 view,
        Matrix4x4 projection)
    {
        Rect rect = camera.pixelRect;
        GetPlaneDiagnosticViewportPixels(
            camera, eye, out int viewportWidth, out int viewportHeight,
            out int viewportOffsetX, out int viewportOffsetY);
        Vector3 position = camera.transform.position;
        Quaternion rotation = camera.transform.rotation;
        _planeDiagnosticCameraRows
            .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
            .Append(eye.ToString().ToLowerInvariant()).Append(',')
            .Append(camera.stereoEnabled ? 1 : 0).Append(',')
            .Append(camera.pixelWidth).Append(',').Append(camera.pixelHeight).Append(',')
            .Append(viewportWidth).Append(',').Append(viewportHeight).Append(',')
            .Append(viewportOffsetX).Append(',').Append(viewportOffsetY).Append(',')
            .Append(rect.x.ToString("F3", CultureInfo.InvariantCulture)).Append(',')
            .Append(rect.y.ToString("F3", CultureInfo.InvariantCulture)).Append(',')
            .Append(rect.width.ToString("F3", CultureInfo.InvariantCulture)).Append(',')
            .Append(rect.height.ToString("F3", CultureInfo.InvariantCulture)).Append(',')
            .Append(camera.nearClipPlane.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(camera.farClipPlane.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(camera.fieldOfView.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(camera.aspect.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(position.x.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(position.y.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(position.z.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(rotation.x.ToString("F8", CultureInfo.InvariantCulture)).Append(',')
            .Append(rotation.y.ToString("F8", CultureInfo.InvariantCulture)).Append(',')
            .Append(rotation.z.ToString("F8", CultureInfo.InvariantCulture)).Append(',')
            .Append(rotation.w.ToString("F8", CultureInfo.InvariantCulture)).Append(',');
        AppendPlaneDiagnosticMatrix(_planeDiagnosticCameraRows, view);
        _planeDiagnosticCameraRows.Append(',');
        AppendPlaneDiagnosticMatrix(_planeDiagnosticCameraRows, projection);
        _planeDiagnosticCameraRows.AppendLine();
    }

    private static void AppendPlaneDiagnosticMatrix(StringBuilder rows, Matrix4x4 matrix)
    {
        for (int row = 0; row < 4; row++)
        for (int column = 0; column < 4; column++)
        {
            if (row != 0 || column != 0)
                rows.Append(',');
            rows.Append(matrix[row, column].ToString("F9", CultureInfo.InvariantCulture));
        }
    }

    private void AppendPlaneConstrainedZeroCrossComponentScreenRows(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> group,
        string scope,
        int componentId)
    {
        Camera camera = Camera.main;
        if (_planeConstrainedZeroCrossComponentScreenRows == null ||
            camera == null || group == null || group.Count == 0)
            return;
        AppendPlaneConstrainedZeroCrossComponentScreenRow(
            group, scope, componentId, camera, Camera.MonoOrStereoscopicEye.Mono);
        if (!camera.stereoEnabled)
            return;
        try
        {
            AppendPlaneConstrainedZeroCrossComponentScreenRow(
                group, scope, componentId, camera, Camera.MonoOrStereoscopicEye.Left);
            AppendPlaneConstrainedZeroCrossComponentScreenRow(
                group, scope, componentId, camera, Camera.MonoOrStereoscopicEye.Right);
        }
        catch (System.Exception)
        {
            // Keep the center-eye projection if the XR provider has not exposed
            // per-eye matrices during this frame.
        }
    }

    private void AppendPlaneConstrainedZeroCrossComponentScreenRow(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> group,
        string scope,
        int componentId,
        Camera camera,
        Camera.MonoOrStereoscopicEye eye)
    {
        float minU = float.PositiveInfinity, minV = float.PositiveInfinity;
        float maxU = float.NegativeInfinity, maxV = float.NegativeInfinity;
        float minDepth = float.PositiveInfinity, maxDepth = float.NegativeInfinity;
        int front = 0, visible = 0;
        for (int i = 0; i < group.Count; i++)
        {
            AccumulatePlaneDiagnosticViewportPoint(camera, eye, group[i].A,
                ref minU, ref minV, ref maxU, ref maxV, ref minDepth, ref maxDepth,
                ref front, ref visible);
            AccumulatePlaneDiagnosticViewportPoint(camera, eye, group[i].B,
                ref minU, ref minV, ref maxU, ref maxV, ref minDepth, ref maxDepth,
                ref front, ref visible);
            AccumulatePlaneDiagnosticViewportPoint(camera, eye, group[i].C,
                ref minU, ref minV, ref maxU, ref maxV, ref minDepth, ref maxDepth,
                ref front, ref visible);
        }
        bool intersects = front > 0 && maxU >= 0f && minU <= 1f && maxV >= 0f && minV <= 1f;
        if (front == 0)
        {
            minU = minV = maxU = maxV = minDepth = maxDepth = 0f;
        }
        GetPlaneDiagnosticViewportPixels(
            camera, eye, out int viewportWidth, out int viewportHeight,
            out int viewportOffsetX, out int viewportOffsetY);
        float pixelMinX = minU * viewportWidth;
        float pixelMaxX = maxU * viewportWidth;
        float pixelMinY = minV * viewportHeight;
        float pixelMaxY = maxV * viewportHeight;
        float pixelTopMinY = viewportHeight - pixelMaxY;
        float pixelTopMaxY = viewportHeight - pixelMinY;
        _planeConstrainedZeroCrossComponentScreenRows
            .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
            .Append(scope).Append(',').Append(componentId).Append(',')
            .Append(eye.ToString().ToLowerInvariant()).Append(',')
            .Append(camera.stereoEnabled ? 1 : 0).Append(',')
            .Append(camera.pixelWidth).Append(',').Append(camera.pixelHeight).Append(',')
            .Append(viewportWidth).Append(',').Append(viewportHeight).Append(',')
            .Append(viewportOffsetX).Append(',').Append(viewportOffsetY).Append(',')
            .Append(front).Append(',').Append(visible).Append(',').Append(intersects ? 1 : 0).Append(',')
            .Append(minU.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(minV.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(maxU.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(maxV.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelMinX.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelMinY.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelMaxX.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelMaxY.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelTopMinY.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(pixelTopMaxY.ToString("F2", CultureInfo.InvariantCulture)).Append(',')
            .Append(minDepth.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(maxDepth.ToString("F6", CultureInfo.InvariantCulture)).AppendLine();
    }

    private static void GetPlaneDiagnosticViewportPixels(
        Camera camera,
        Camera.MonoOrStereoscopicEye eye,
        out int viewportWidth,
        out int viewportHeight,
        out int viewportOffsetX,
        out int viewportOffsetY)
    {
        int renderWidth = Mathf.Max(1, camera != null ? camera.pixelWidth : Screen.width);
        int renderHeight = Mathf.Max(1, camera != null ? camera.pixelHeight : Screen.height);
        bool stereoEye = camera != null && camera.stereoEnabled &&
                         eye != Camera.MonoOrStereoscopicEye.Mono;
        // Quest casting captures one eye. In double-wide stereo the Camera reports
        // the combined target, while WorldToViewportPoint(eye) is normalized to a
        // single eye. Export eye-local pixels so a 2064-wide cast is not compared
        // against the 4128-wide combined render target.
        bool doubleWide = stereoEye && renderWidth >= renderHeight * 1.5f;
        viewportWidth = doubleWide ? Mathf.Max(1, renderWidth / 2) : renderWidth;
        viewportHeight = renderHeight;
        viewportOffsetX = doubleWide && eye == Camera.MonoOrStereoscopicEye.Right
            ? viewportWidth : 0;
        viewportOffsetY = 0;
    }

    private static void AccumulatePlaneDiagnosticViewportPoint(
        Camera camera,
        Camera.MonoOrStereoscopicEye eye,
        Vector3 point,
        ref float minU,
        ref float minV,
        ref float maxU,
        ref float maxV,
        ref float minDepth,
        ref float maxDepth,
        ref int front,
        ref int visible)
    {
        Vector3 viewport = camera.WorldToViewportPoint(point, eye);
        if (!Finite(viewport) || viewport.z <= 0f)
            return;
        front++;
        minU = Mathf.Min(minU, viewport.x);
        minV = Mathf.Min(minV, viewport.y);
        maxU = Mathf.Max(maxU, viewport.x);
        maxV = Mathf.Max(maxV, viewport.y);
        minDepth = Mathf.Min(minDepth, viewport.z);
        maxDepth = Mathf.Max(maxDepth, viewport.z);
        if (viewport.x >= 0f && viewport.x <= 1f && viewport.y >= 0f && viewport.y <= 1f)
            visible++;
    }

    private static string JoinPlaneLedgerStrings(HashSet<string> values)
    {
        List<string> sorted = new List<string>(values);
        sorted.Sort(System.StringComparer.Ordinal);
        return string.Join("|", sorted);
    }

    private bool IsOutputResultPromotionEligible(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        if (entry == null || !entry.HardAuditChecked || !entry.HardLegal ||
            !entry.WorkingPublishEligible)
            return false;

        if (entry.RelaxedClass == "formal_structural")
            return true;
        if (entry.RelaxedClass == "confirmed_complex")
            return promoteConfirmedComplexToResult;
        if (entry.RelaxedClass != "provisional_structural" ||
            !promoteProvisionalStructuralToResult)
            return false;

        // A recovered HELD face is allowed into RESULT only after its independent
        // evidence audit explicitly chose keep.  Ordinary provisional structural
        // faces do not carry a HELD decision and use the regular hard/working gates.
        return entry.Disposition != "hold_reextract" ||
               entry.HeldKeepDecision == "keep";
    }

    private IEnumerator RebuildPlaneConstrainedZeroCrossShadowWireBudgetedRoutine(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger,
        CooperativeRebuildBudget budget)
    {
        if (ShouldUsePersistentResultChunkPublishing())
        {
            IEnumerator persistentRoutine =
                RebuildPersistentResultChunksRoutine(ledger, budget);
            while (persistentRoutine.MoveNext())
                yield return persistentRoutine.Current;
            yield break;
        }

        RebuildPlaneConstrainedZeroCrossShadowWire(ledger);
    }

    private void RebuildPlaneConstrainedZeroCrossShadowWire(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger)
    {
        if (ShouldUsePersistentResultChunkPublishing())
        {
            RebuildPersistentResultChunks(ledger);
            return;
        }

        LastOutputResultFormalTriangleCount = 0;
        LastOutputResultProvisionalTriangleCount = 0;
        LastOutputResultComplexTriangleCount = 0;
        LastOutputResultHeldRescueTriangleCount = 0;
        LastOutputResultPromotedTriangleCount = 0;
        LastOutputResultRejectedTriangleCount = 0;
        LastOutputDiagnosticPendingTriangleCount = 0;
        LastOutputDiagnosticIllegalTriangleCount = 0;
        LastOutputDiagnosticUnclassifiedTriangleCount = 0;
        LastOutputDiagnosticPromotionBlockedTriangleCount = 0;
        if (showPlaneConstrainedZeroCrossShadowWire)
            EnsurePlaneConstrainedZeroCrossShadowObjects();
        if (!showPlaneConstrainedZeroCrossShadowWire ||
            ledger == null || ledger.Count == 0 ||
            _planeConstrainedZeroCrossShadowMesh == null ||
            _planeConstrainedZeroCrossShadowObject == null)
        {
            if (_planeConstrainedZeroCrossShadowObject != null)
                _planeConstrainedZeroCrossShadowObject.SetActive(false);
            return;
        }

        List<Vector3> vertices = new List<Vector3>(ledger.Count * 4);
        List<int> structuralLines = new List<int>(ledger.Count * 4);
        List<int> nonplanarLines = new List<int>(ledger.Count * 2);
        List<int> provisionalLines = new List<int>(ledger.Count * 2);
        List<int> unclassifiedLines = new List<int>(ledger.Count);
        HashSet<AuthoritativeCanonicalEdgeKey> structuralEdges =
            new HashSet<AuthoritativeCanonicalEdgeKey>();
        HashSet<AuthoritativeCanonicalEdgeKey> nonplanarEdges =
            new HashSet<AuthoritativeCanonicalEdgeKey>();
        HashSet<AuthoritativeCanonicalEdgeKey> provisionalEdges =
            new HashSet<AuthoritativeCanonicalEdgeKey>();
        HashSet<AuthoritativeCanonicalEdgeKey> unclassifiedEdges =
            new HashSet<AuthoritativeCanonicalEdgeKey>();
        for (int i = 0; i < ledger.Count; i++)
        {
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[i];
            List<int> lines;
            HashSet<AuthoritativeCanonicalEdgeKey> edges;
            bool promoted = IsOutputResultPromotionEligible(entry);
            if (promoted && entry.RelaxedClass == "formal_structural")
            {
                lines = structuralLines;
                edges = structuralEdges;
                LastOutputResultFormalTriangleCount++;
            }
            else if (promoted && entry.RelaxedClass == "provisional_structural")
            {
                // Orange remains a backend lifecycle label. In the headset it is
                // fused into the yellow structural grid from its first safe publish.
                lines = structuralLines;
                edges = structuralEdges;
                LastOutputResultProvisionalTriangleCount++;
                if (entry.Disposition == "hold_reextract")
                    LastOutputResultHeldRescueTriangleCount++;
            }
            else if (promoted && entry.RelaxedClass == "confirmed_complex")
            {
                lines = nonplanarLines;
                edges = nonplanarEdges;
                LastOutputResultComplexTriangleCount++;
            }
            else if (entry.HardAuditChecked && entry.RelaxedClass == "pending")
            {
                LastOutputDiagnosticPendingTriangleCount++;
                LastOutputResultRejectedTriangleCount++;
                continue;
            }
            else if (entry.HardAuditChecked && entry.RelaxedClass == "hard_illegal")
            {
                LastOutputDiagnosticIllegalTriangleCount++;
                LastOutputResultRejectedTriangleCount++;
                continue;
            }
            else if (entry.HardAuditChecked &&
                     (entry.RelaxedClass == "formal_structural" ||
                      entry.RelaxedClass == "provisional_structural" ||
                      entry.RelaxedClass == "confirmed_complex"))
            {
                lines = unclassifiedLines;
                edges = unclassifiedEdges;
                LastOutputDiagnosticPromotionBlockedTriangleCount++;
                LastOutputResultRejectedTriangleCount++;
            }
            else
            {
                // Unclassified entries and otherwise legal classes blocked by a
                // configurable promotion gate stay visible in DIAG, never RESULT.
                lines = unclassifiedLines;
                edges = unclassifiedEdges;
                LastOutputDiagnosticUnclassifiedTriangleCount++;
                LastOutputResultRejectedTriangleCount++;
            }
            Vector3 a = RelaxedDisplayA(entry);
            Vector3 b = RelaxedDisplayB(entry);
            Vector3 c = RelaxedDisplayC(entry);
            AddPlaneLedgerWireEdge(vertices, lines, edges, entry.KeyA, entry.KeyB, a, b);
            AddPlaneLedgerWireEdge(vertices, lines, edges, entry.KeyB, entry.KeyC, b, c);
            AddPlaneLedgerWireEdge(vertices, lines, edges, entry.KeyC, entry.KeyA, c, a);
        }
        LastOutputResultPromotedTriangleCount =
            LastOutputResultFormalTriangleCount +
            LastOutputResultProvisionalTriangleCount +
            LastOutputResultComplexTriangleCount;
        _planeConstrainedZeroCrossShadowMesh.indexFormat =
            vertices.Count > 65535 ? IndexFormat.UInt32 : IndexFormat.UInt16;
        _planeConstrainedZeroCrossShadowMesh.SetVertices(vertices);
        _planeConstrainedZeroCrossShadowMesh.subMeshCount = 4;
        ReplaceOutputDisplayLineIndices(_outputDisplayStructuralLines, structuralLines);
        ReplaceOutputDisplayLineIndices(_outputDisplayComplexLines, nonplanarLines);
        ReplaceOutputDisplayLineIndices(_outputDisplayProvisionalLines, provisionalLines);
        ReplaceOutputDisplayLineIndices(_outputDisplayUnclassifiedLines, unclassifiedLines);
        ApplyOutputDisplayShadowSubmeshFilter();
        _planeConstrainedZeroCrossShadowMesh.RecalculateBounds();
        _planeConstrainedZeroCrossShadowObject.SetActive(
            structuralLines.Count > 0 || nonplanarLines.Count > 0 ||
            unclassifiedLines.Count > 0);
        // Mesh rebuilding resets renderer state. Re-apply the selected display gear
        // so a new capture cannot silently jump back to the aggregate view.
        ApplyOutputDisplayLayerVisibility();
    }

    private bool ShouldUsePersistentResultChunkPublishing()
    {
        return enablePersistentResultChunkPublishing &&
               enableAuthoritativeIncrementalProductionRebuild &&
               outputDisplayPipeline == OutputDisplayPipeline.CurrentDiagnosticComposite &&
               showPlaneConstrainedZeroCrossShadowWire;
    }

    private void RebuildPersistentResultChunks(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger)
    {
        IEnumerator routine = RebuildPersistentResultChunksRoutine(ledger, null);
        while (routine.MoveNext())
        {
        }
    }

    private IEnumerator RebuildPersistentResultChunksRoutine(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger,
        CooperativeRebuildBudget budget)
    {
        double publishStart = budget != null
            ? budget.GetComputeSecondsSnapshot()
            : Time.realtimeSinceStartupAsDouble;
        LastPersistentResultChunkUpdatedCount = 0;
        LastPersistentResultChunkPreservedCount = 0;
        LastPersistentResultChunkRemovedCount = 0;
        EnsurePlaneConstrainedZeroCrossShadowObjects();
        EnsurePersistentResultChunkRoot();

        // An empty transient RESULT is not an instruction to erase the last safe
        // foreground. Preserve the published chunks (or the preceding aggregate
        // bootstrap mesh) until a non-empty finalized ledger replaces them.
        if (ledger == null || ledger.Count == 0)
        {
            ApplyOutputDisplayLayerVisibility();
            LastPersistentResultChunkActiveCount = CountActivePersistentResultChunks();
            LastPersistentResultChunkPublishMilliseconds =
                (float)(((budget != null
                    ? budget.GetComputeSecondsSnapshot()
                    : Time.realtimeSinceStartupAsDouble) - publishStart) * 1000.0);
            yield break;
        }

        bool hasPromotedForeground = false;
        for (int i = 0; i < ledger.Count; i++)
        {
            if ((i & 127) == 0 && budget != null && budget.ShouldYield())
            {
                budget.CompleteSliceForYield();
                yield return null;
                budget.Resume();
            }
            if (!IsOutputResultPromotionEligible(ledger[i]))
                continue;
            hasPromotedForeground = true;
            break;
        }
        if (!hasPromotedForeground && HasPublishedResultForeground())
        {
            // A temporary classification gap must not erase an already-safe RESULT.
            // This is the chunked equivalent of nvblox-style persistent mesh blocks.
            ApplyOutputDisplayLayerVisibility();
            LastPersistentResultChunkActiveCount = CountActivePersistentResultChunks();
            LastPersistentResultChunkPublishMilliseconds =
                (float)(((budget != null
                    ? budget.GetComputeSecondsSnapshot()
                    : Time.realtimeSinceStartupAsDouble) - publishStart) * 1000.0);
            yield break;
        }

        Dictionary<Vector3Int, List<PlaneConstrainedZeroCrossTriangleLedgerEntry>> byBlock =
            new Dictionary<Vector3Int, List<PlaneConstrainedZeroCrossTriangleLedgerEntry>>();
        for (int i = 0; i < ledger.Count; i++)
        {
            if ((i & 127) == 0 && budget != null && budget.ShouldYield())
            {
                budget.CompleteSliceForYield();
                yield return null;
                budget.Resume();
            }
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[i];
            if (!byBlock.TryGetValue(
                    entry.Block,
                    out List<PlaneConstrainedZeroCrossTriangleLedgerEntry> entries))
            {
                entries = new List<PlaneConstrainedZeroCrossTriangleLedgerEntry>();
                byBlock[entry.Block] = entries;
            }
            entries.Add(entry);
        }
        if (budget != null && budget.ShouldYield())
        {
            budget.CompleteSliceForYield();
            yield return null;
            budget.Resume();
        }
        PersistentResultEdgeOwners edgeOwners =
            BuildPersistentResultEdgeOwners(ledger);
        if (budget != null && budget.ShouldYield())
        {
            budget.CompleteSliceForYield();
            yield return null;
            budget.Resume();
        }

        List<Vector3Int> removed = new List<Vector3Int>();
        foreach (Vector3Int key in _persistentResultChunks.Keys)
        {
            if (budget != null && budget.ShouldYield())
            {
                budget.CompleteSliceForYield();
                yield return null;
                budget.Resume();
            }
            if (!byBlock.ContainsKey(key))
                removed.Add(key);
        }
        for (int i = 0; i < removed.Count; i++)
        {
            if (budget != null && budget.ShouldYield())
            {
                budget.CompleteSliceForYield();
                yield return null;
                budget.Resume();
            }
            Vector3Int key = removed[i];
            DestroyPersistentResultChunk(_persistentResultChunks[key]);
            _persistentResultChunks.Remove(key);
            LastPersistentResultChunkRemovedCount++;
        }

        foreach (KeyValuePair<Vector3Int, List<PlaneConstrainedZeroCrossTriangleLedgerEntry>>
                 pair in byBlock)
        {
            if (budget != null && budget.ShouldYield())
            {
                budget.CompleteSliceForYield();
                yield return null;
                budget.Resume();
            }
            ulong signature = ComputePersistentResultChunkSignature(
                pair.Key, pair.Value, edgeOwners);
            if (_persistentResultChunks.TryGetValue(
                    pair.Key, out PersistentResultChunk existing) &&
                existing.Signature == signature)
            {
                LastPersistentResultChunkPreservedCount++;
                continue;
            }

            PersistentResultChunk chunk = existing ?? CreatePersistentResultChunk(pair.Key);
            RebuildPersistentResultChunkMesh(
                pair.Key, chunk, pair.Value, edgeOwners, signature);
            _persistentResultChunks[pair.Key] = chunk;
            LastPersistentResultChunkUpdatedCount++;
            if (budget != null)
                ApplyPersistentResultChunkVisibility();
        }

        RecountPersistentResultChunkOutput();
        ApplyOutputDisplayLayerVisibility();
        LastPersistentResultChunkActiveCount = CountActivePersistentResultChunks();
        LastPersistentResultChunkPublishMilliseconds =
            (float)(((budget != null
                ? budget.GetComputeSecondsSnapshot()
                : Time.realtimeSinceStartupAsDouble) - publishStart) * 1000.0);
    }

    private void EnsurePersistentResultChunkRoot()
    {
        if (_persistentResultChunkRoot == null)
            _persistentResultChunkRoot =
                new GameObject("[ScanCover] Persistent RESULT Wire Chunks");
        if (forceWorldSpaceDisplay)
        {
            _persistentResultChunkRoot.transform.SetParent(null, true);
            _persistentResultChunkRoot.transform.SetPositionAndRotation(
                Vector3.zero, Quaternion.identity);
            _persistentResultChunkRoot.transform.localScale = Vector3.one;
        }
        else if (_persistentResultChunkRoot.transform.parent != displayRoot)
        {
            _persistentResultChunkRoot.transform.SetParent(displayRoot, false);
            _persistentResultChunkRoot.transform.localPosition = Vector3.zero;
            _persistentResultChunkRoot.transform.localRotation = Quaternion.identity;
            _persistentResultChunkRoot.transform.localScale = Vector3.one;
        }
    }

    private PersistentResultChunk CreatePersistentResultChunk(Vector3Int key)
    {
        EnsurePersistentResultChunkRoot();
        PersistentResultChunk chunk = new PersistentResultChunk();
        chunk.Object = new GameObject(
            $"RESULT Chunk {key.x},{key.y},{key.z}");
        chunk.Object.transform.SetParent(_persistentResultChunkRoot.transform, false);
        chunk.Object.transform.localPosition = Vector3.zero;
        chunk.Object.transform.localRotation = Quaternion.identity;
        chunk.Object.transform.localScale = Vector3.one;
        chunk.Filter = chunk.Object.AddComponent<MeshFilter>();
        chunk.Renderer = chunk.Object.AddComponent<MeshRenderer>();
        chunk.Mesh = new Mesh
        {
            name = $"ScanCover_RESULT_Chunk_{key.x}_{key.y}_{key.z}",
            indexFormat = IndexFormat.UInt32
        };
        chunk.Mesh.MarkDynamic();
        chunk.Filter.sharedMesh = chunk.Mesh;
        chunk.Renderer.sharedMaterials = ResolvePersistentResultChunkMaterials();
        chunk.Renderer.sortingOrder = 105;
        chunk.Object.SetActive(false);
        return chunk;
    }

    private Material[] ResolvePersistentResultChunkMaterials()
    {
        return new[]
        {
            _planeConstrainedZeroCrossShadowMaterial != null
                ? _planeConstrainedZeroCrossShadowMaterial : ResolveWireMaterial(),
            _planeConstrainedZeroCrossNonplanarMaterial != null
                ? _planeConstrainedZeroCrossNonplanarMaterial : ResolveWireMaterial(),
            _planeConstrainedZeroCrossProvisionalMaterial != null
                ? _planeConstrainedZeroCrossProvisionalMaterial : ResolveWireMaterial(),
            _planeConstrainedZeroCrossUnclassifiedMaterial != null
                ? _planeConstrainedZeroCrossUnclassifiedMaterial : ResolveWireMaterial()
        };
    }

    private void RebuildPersistentResultChunkMesh(
        Vector3Int blockKey,
        PersistentResultChunk chunk,
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> entries,
        PersistentResultEdgeOwners edgeOwners,
        ulong signature)
    {
        chunk.StructuralLines.Clear();
        chunk.ComplexLines.Clear();
        chunk.UnclassifiedLines.Clear();
        chunk.FormalTriangles = 0;
        chunk.ProvisionalTriangles = 0;
        chunk.ComplexTriangles = 0;
        chunk.HeldRescueTriangles = 0;
        chunk.RejectedTriangles = 0;
        chunk.PendingTriangles = 0;
        chunk.IllegalTriangles = 0;
        chunk.UnclassifiedTriangles = 0;
        chunk.PromotionBlockedTriangles = 0;

        List<Vector3> vertices = new List<Vector3>(entries.Count * 4);
        HashSet<AuthoritativeCanonicalEdgeKey> structuralEdges =
            new HashSet<AuthoritativeCanonicalEdgeKey>();
        HashSet<AuthoritativeCanonicalEdgeKey> complexEdges =
            new HashSet<AuthoritativeCanonicalEdgeKey>();
        HashSet<AuthoritativeCanonicalEdgeKey> unclassifiedEdges =
            new HashSet<AuthoritativeCanonicalEdgeKey>();
        for (int i = 0; i < entries.Count; i++)
        {
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = entries[i];
            List<int> lines;
            HashSet<AuthoritativeCanonicalEdgeKey> edges;
            int outputCategory;
            bool promoted = IsOutputResultPromotionEligible(entry);
            if (promoted && entry.RelaxedClass == "formal_structural")
            {
                lines = chunk.StructuralLines;
                edges = structuralEdges;
                outputCategory = 0;
                chunk.FormalTriangles++;
            }
            else if (promoted && entry.RelaxedClass == "provisional_structural")
            {
                lines = chunk.StructuralLines;
                edges = structuralEdges;
                outputCategory = 0;
                chunk.ProvisionalTriangles++;
                if (entry.Disposition == "hold_reextract")
                    chunk.HeldRescueTriangles++;
            }
            else if (promoted && entry.RelaxedClass == "confirmed_complex")
            {
                lines = chunk.ComplexLines;
                edges = complexEdges;
                outputCategory = 1;
                chunk.ComplexTriangles++;
            }
            else if (entry.HardAuditChecked && entry.RelaxedClass == "pending")
            {
                chunk.PendingTriangles++;
                chunk.RejectedTriangles++;
                continue;
            }
            else if (entry.HardAuditChecked && entry.RelaxedClass == "hard_illegal")
            {
                chunk.IllegalTriangles++;
                chunk.RejectedTriangles++;
                continue;
            }
            else
            {
                lines = chunk.UnclassifiedLines;
                edges = unclassifiedEdges;
                outputCategory = 2;
                if (entry.HardAuditChecked &&
                    (entry.RelaxedClass == "formal_structural" ||
                     entry.RelaxedClass == "provisional_structural" ||
                     entry.RelaxedClass == "confirmed_complex"))
                    chunk.PromotionBlockedTriangles++;
                else
                    chunk.UnclassifiedTriangles++;
                chunk.RejectedTriangles++;
            }

            Vector3 a = RelaxedDisplayA(entry);
            Vector3 b = RelaxedDisplayB(entry);
            Vector3 c = RelaxedDisplayC(entry);
            AddPersistentResultChunkEdge(
                blockKey, outputCategory, edgeOwners, vertices, lines, edges,
                entry.KeyA, entry.KeyB, a, b);
            AddPersistentResultChunkEdge(
                blockKey, outputCategory, edgeOwners, vertices, lines, edges,
                entry.KeyB, entry.KeyC, b, c);
            AddPersistentResultChunkEdge(
                blockKey, outputCategory, edgeOwners, vertices, lines, edges,
                entry.KeyC, entry.KeyA, c, a);
        }

        chunk.Mesh.Clear();
        chunk.Mesh.indexFormat =
            vertices.Count > 65535 ? IndexFormat.UInt32 : IndexFormat.UInt16;
        chunk.Mesh.SetVertices(vertices);
        chunk.Mesh.subMeshCount = 4;
        if (vertices.Count > 0)
            chunk.Mesh.RecalculateBounds();
        chunk.Signature = signature;
        chunk.AppliedView = -1;
    }

    private ulong ComputePersistentResultChunkSignature(
        Vector3Int blockKey,
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> entries,
        PersistentResultEdgeOwners edgeOwners)
    {
        unchecked
        {
            ulong hash = 1469598103934665603UL;
            for (int i = 0; i < entries.Count; i++)
            {
                PlaneConstrainedZeroCrossTriangleLedgerEntry entry = entries[i];
                hash = PersistentResultHash(hash, entry.KeyA.GetHashCode());
                hash = PersistentResultHash(hash, entry.KeyB.GetHashCode());
                hash = PersistentResultHash(hash, entry.KeyC.GetHashCode());
                hash = PersistentResultHash(hash, entry.RelaxedClass != null
                    ? entry.RelaxedClass.GetHashCode() : 0);
                hash = PersistentResultHash(hash, entry.Disposition != null
                    ? entry.Disposition.GetHashCode() : 0);
                hash = PersistentResultHash(hash, entry.HeldKeepDecision != null
                    ? entry.HeldKeepDecision.GetHashCode() : 0);
                hash = PersistentResultHash(hash, entry.HardAuditChecked ? 1 : 0);
                hash = PersistentResultHash(hash, entry.HardLegal ? 1 : 0);
                hash = PersistentResultHash(hash, entry.WorkingPublishEligible ? 1 : 0);
                hash = PersistentResultHash(hash, RelaxedDisplayA(entry).GetHashCode());
                hash = PersistentResultHash(hash, RelaxedDisplayB(entry).GetHashCode());
                hash = PersistentResultHash(hash, RelaxedDisplayC(entry).GetHashCode());
                int outputCategory = GetPersistentResultOutputCategory(entry);
                hash = PersistentResultHash(
                    hash, IsPersistentResultEdgeOwner(
                        blockKey, outputCategory, edgeOwners, entry.KeyA, entry.KeyB) ? 1 : 0);
                hash = PersistentResultHash(
                    hash, IsPersistentResultEdgeOwner(
                        blockKey, outputCategory, edgeOwners, entry.KeyB, entry.KeyC) ? 1 : 0);
                hash = PersistentResultHash(
                    hash, IsPersistentResultEdgeOwner(
                        blockKey, outputCategory, edgeOwners, entry.KeyC, entry.KeyA) ? 1 : 0);
            }
            return hash;
        }
    }

    private PersistentResultEdgeOwners BuildPersistentResultEdgeOwners(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger)
    {
        PersistentResultEdgeOwners owners = new PersistentResultEdgeOwners();
        for (int i = 0; i < ledger.Count; i++)
        {
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[i];
            int outputCategory = GetPersistentResultOutputCategory(entry);
            if (outputCategory < 0)
                continue;
            RegisterPersistentResultEdgeOwner(
                PersistentResultOwnerMap(owners, outputCategory),
                MakeAuthoritativeCanonicalEdge(entry.KeyA, entry.KeyB), entry.Block);
            RegisterPersistentResultEdgeOwner(
                PersistentResultOwnerMap(owners, outputCategory),
                MakeAuthoritativeCanonicalEdge(entry.KeyB, entry.KeyC), entry.Block);
            RegisterPersistentResultEdgeOwner(
                PersistentResultOwnerMap(owners, outputCategory),
                MakeAuthoritativeCanonicalEdge(entry.KeyC, entry.KeyA), entry.Block);
        }
        return owners;
    }

    private int GetPersistentResultOutputCategory(
        PlaneConstrainedZeroCrossTriangleLedgerEntry entry)
    {
        bool promoted = IsOutputResultPromotionEligible(entry);
        if (promoted && (entry.RelaxedClass == "formal_structural" ||
                         entry.RelaxedClass == "provisional_structural"))
            return 0;
        if (promoted && entry.RelaxedClass == "confirmed_complex")
            return 1;
        if (entry.HardAuditChecked &&
            (entry.RelaxedClass == "pending" ||
             entry.RelaxedClass == "hard_illegal"))
            return -1;
        return 2;
    }

    private static Dictionary<AuthoritativeCanonicalEdgeKey, Vector3Int>
        PersistentResultOwnerMap(PersistentResultEdgeOwners owners, int outputCategory)
    {
        if (outputCategory == 0)
            return owners.Structural;
        if (outputCategory == 1)
            return owners.Complex;
        return owners.Unclassified;
    }

    private static void RegisterPersistentResultEdgeOwner(
        Dictionary<AuthoritativeCanonicalEdgeKey, Vector3Int> owners,
        AuthoritativeCanonicalEdgeKey edge,
        Vector3Int candidate)
    {
        if (!owners.TryGetValue(edge, out Vector3Int current) ||
            ComparePersistentResultBlockKeys(candidate, current) < 0)
            owners[edge] = candidate;
    }

    private static int ComparePersistentResultBlockKeys(Vector3Int a, Vector3Int b)
    {
        int z = a.z.CompareTo(b.z);
        if (z != 0)
            return z;
        int y = a.y.CompareTo(b.y);
        return y != 0 ? y : a.x.CompareTo(b.x);
    }

    private static bool IsPersistentResultEdgeOwner(
        Vector3Int blockKey,
        int outputCategory,
        PersistentResultEdgeOwners edgeOwners,
        AuthoritativeCellComponentKey a,
        AuthoritativeCellComponentKey b)
    {
        if (outputCategory < 0 || edgeOwners == null)
            return false;
        AuthoritativeCanonicalEdgeKey edge = MakeAuthoritativeCanonicalEdge(a, b);
        Dictionary<AuthoritativeCanonicalEdgeKey, Vector3Int> owners =
            PersistentResultOwnerMap(edgeOwners, outputCategory);
        return owners.TryGetValue(edge, out Vector3Int owner) &&
               owner == blockKey;
    }

    private static void AddPersistentResultChunkEdge(
        Vector3Int blockKey,
        int outputCategory,
        PersistentResultEdgeOwners edgeOwners,
        List<Vector3> vertices,
        List<int> indices,
        HashSet<AuthoritativeCanonicalEdgeKey> edges,
        AuthoritativeCellComponentKey aKey,
        AuthoritativeCellComponentKey bKey,
        Vector3 a,
        Vector3 b)
    {
        if (!IsPersistentResultEdgeOwner(
                blockKey, outputCategory, edgeOwners, aKey, bKey))
            return;
        AddPlaneLedgerWireEdge(vertices, indices, edges, aKey, bKey, a, b);
    }

    private static ulong PersistentResultHash(ulong hash, int value)
    {
        unchecked
        {
            hash ^= (uint)value;
            return hash * 1099511628211UL;
        }
    }

    private void RecountPersistentResultChunkOutput()
    {
        LastOutputResultFormalTriangleCount = 0;
        LastOutputResultProvisionalTriangleCount = 0;
        LastOutputResultComplexTriangleCount = 0;
        LastOutputResultHeldRescueTriangleCount = 0;
        LastOutputResultRejectedTriangleCount = 0;
        LastOutputDiagnosticPendingTriangleCount = 0;
        LastOutputDiagnosticIllegalTriangleCount = 0;
        LastOutputDiagnosticUnclassifiedTriangleCount = 0;
        LastOutputDiagnosticPromotionBlockedTriangleCount = 0;
        foreach (PersistentResultChunk chunk in _persistentResultChunks.Values)
        {
            LastOutputResultFormalTriangleCount += chunk.FormalTriangles;
            LastOutputResultProvisionalTriangleCount += chunk.ProvisionalTriangles;
            LastOutputResultComplexTriangleCount += chunk.ComplexTriangles;
            LastOutputResultHeldRescueTriangleCount += chunk.HeldRescueTriangles;
            LastOutputResultRejectedTriangleCount += chunk.RejectedTriangles;
            LastOutputDiagnosticPendingTriangleCount += chunk.PendingTriangles;
            LastOutputDiagnosticIllegalTriangleCount += chunk.IllegalTriangles;
            LastOutputDiagnosticUnclassifiedTriangleCount += chunk.UnclassifiedTriangles;
            LastOutputDiagnosticPromotionBlockedTriangleCount +=
                chunk.PromotionBlockedTriangles;
        }
        LastOutputResultPromotedTriangleCount =
            LastOutputResultFormalTriangleCount +
            LastOutputResultProvisionalTriangleCount +
            LastOutputResultComplexTriangleCount;
    }

    private void ApplyPersistentResultChunkVisibility()
    {
        bool showResult = outputDisplayLayerView == OutputDisplayLayerView.Result;
        bool showDiagnostic = outputDisplayLayerView == OutputDisplayLayerView.Diagnostic;
        bool showShadow = showResult || showDiagnostic;
        int appliedView = (int)outputDisplayLayerView;
        foreach (PersistentResultChunk chunk in _persistentResultChunks.Values)
        {
            if (chunk.Mesh == null || chunk.Object == null)
                continue;
            if (chunk.AppliedView != appliedView)
            {
                chunk.Mesh.SetIndices(
                    showResult ? chunk.StructuralLines : EmptyOutputDisplayLineIndices,
                    MeshTopology.Lines, 0, false);
                chunk.Mesh.SetIndices(
                    showResult ? chunk.ComplexLines : EmptyOutputDisplayLineIndices,
                    MeshTopology.Lines, 1, false);
                chunk.Mesh.SetIndices(
                    EmptyOutputDisplayLineIndices, MeshTopology.Lines, 2, false);
                chunk.Mesh.SetIndices(
                    showDiagnostic ? chunk.UnclassifiedLines : EmptyOutputDisplayLineIndices,
                    MeshTopology.Lines, 3, false);
                chunk.AppliedView = appliedView;
            }
            bool hasVisible = showResult
                ? chunk.StructuralLines.Count > 0 || chunk.ComplexLines.Count > 0
                : showDiagnostic && chunk.UnclassifiedLines.Count > 0;
            chunk.Object.SetActive(
                showPlaneConstrainedZeroCrossShadowWire && showShadow && hasVisible);
        }
        if (_persistentResultChunkRoot != null)
            _persistentResultChunkRoot.SetActive(
                showPlaneConstrainedZeroCrossShadowWire && showShadow &&
                _persistentResultChunks.Count > 0);
    }

    private int CountActivePersistentResultChunks()
    {
        int count = 0;
        foreach (PersistentResultChunk chunk in _persistentResultChunks.Values)
        {
            if (chunk.Object != null && chunk.Object.activeSelf)
                count++;
        }
        return count;
    }

    private void DestroyPersistentResultChunk(PersistentResultChunk chunk)
    {
        if (chunk == null)
            return;
        if (chunk.Mesh != null)
            Destroy(chunk.Mesh);
        if (chunk.Object != null)
            Destroy(chunk.Object);
    }

    private void ClearPersistentResultChunks(bool destroyRoot)
    {
        foreach (PersistentResultChunk chunk in _persistentResultChunks.Values)
            DestroyPersistentResultChunk(chunk);
        _persistentResultChunks.Clear();
        LastPersistentResultChunkUpdatedCount = 0;
        LastPersistentResultChunkPreservedCount = 0;
        LastPersistentResultChunkRemovedCount = 0;
        LastPersistentResultChunkActiveCount = 0;
        LastPersistentResultChunkPublishMilliseconds = 0f;
        if (!destroyRoot || _persistentResultChunkRoot == null)
        {
            if (_persistentResultChunkRoot != null)
                _persistentResultChunkRoot.SetActive(false);
            return;
        }
        Destroy(_persistentResultChunkRoot);
        _persistentResultChunkRoot = null;
    }

    private static void AddPlaneLedgerWireEdge(
        List<Vector3> vertices,
        List<int> indices,
        HashSet<AuthoritativeCanonicalEdgeKey> edges,
        AuthoritativeCellComponentKey keyA,
        AuthoritativeCellComponentKey keyB,
        Vector3 a,
        Vector3 b)
    {
        AuthoritativeCanonicalEdgeKey edge = MakeAuthoritativeCanonicalEdge(keyA, keyB);
        if (!edges.Add(edge))
            return;
        AddPlaneIssueLine(vertices, indices, a, b);
    }

    private void RebuildPlaneConstrainedZeroCrossIssueOverlay(
        List<PlaneConstrainedZeroCrossTriangleLedgerEntry> ledger,
        List<PlaneSupportCellLedgerEntry> supportCells)
    {
        if (showPlaneConstrainedZeroCrossIssueOverlay)
            EnsurePlaneConstrainedZeroCrossIssueObjects();
        bool hasLedger = ledger != null && ledger.Count > 0;
        bool hasSupportCells = supportCells != null && supportCells.Count > 0;
        if (!showPlaneConstrainedZeroCrossIssueOverlay || (!hasLedger && !hasSupportCells) ||
            _planeConstrainedZeroCrossIssueMesh == null ||
            _planeConstrainedZeroCrossIssueObject == null)
        {
            if (_planeConstrainedZeroCrossIssueObject != null)
                _planeConstrainedZeroCrossIssueObject.SetActive(false);
            return;
        }

        if (ledger == null)
            ledger = new List<PlaneConstrainedZeroCrossTriangleLedgerEntry>();
        int gapCellCapacity = showPlaneSupportGapOverlay
            ? LastPlaneSupportGapCellCount : 0;
        List<Vector3> vertices = new List<Vector3>(
            LastPlaneConstrainedZeroCrossLedgerProblemTriangleCount * 8 + gapCellCapacity * 8);
        List<int> problemLines = new List<int>(LastPlaneConstrainedZeroCrossLedgerProblemTriangleCount * 6);
        List<int> boundsLines = new List<int>(LastPlaneConstrainedZeroCrossLedgerProblemComponentCount * 24);
        List<int> hardIllegalLines = new List<int>(
            LastPlaneConstrainedZeroCrossLedgerGeometricSuspectTriangleCount * 6);
        List<int> supportGapLines = new List<int>(gapCellCapacity * 8);
        Dictionary<int, List<PlaneConstrainedZeroCrossTriangleLedgerEntry>> issueGroups =
            new Dictionary<int, List<PlaneConstrainedZeroCrossTriangleLedgerEntry>>();

        for (int i = 0; i < ledger.Count; i++)
        {
            PlaneConstrainedZeroCrossTriangleLedgerEntry entry = ledger[i];
            if (showPlaneConstrainedPublishedSuspectOverlay &&
                entry.HardAuditChecked && entry.RelaxedClass == "hard_illegal")
            {
                AddPlaneIssueLine(vertices, hardIllegalLines, RelaxedDisplayA(entry), RelaxedDisplayB(entry));
                AddPlaneIssueLine(vertices, hardIllegalLines, RelaxedDisplayB(entry), RelaxedDisplayC(entry));
                AddPlaneIssueLine(vertices, hardIllegalLines, RelaxedDisplayC(entry), RelaxedDisplayA(entry));
            }
            bool showAsPending = IsRelaxedCandidatePending(entry);
            if (!showPlaneConstrainedHeldOverlay || !showAsPending)
                continue;
            AddPlaneIssueLine(vertices, problemLines, entry.A, entry.B);
            AddPlaneIssueLine(vertices, problemLines, entry.B, entry.C);
            AddPlaneIssueLine(vertices, problemLines, entry.C, entry.A);
            if (!issueGroups.TryGetValue(entry.IssueComponentId,
                    out List<PlaneConstrainedZeroCrossTriangleLedgerEntry> group))
            {
                group = new List<PlaneConstrainedZeroCrossTriangleLedgerEntry>();
                issueGroups[entry.IssueComponentId] = group;
            }
            group.Add(entry);
        }

        if (showPlaneSupportGapOverlay && supportCells != null)
        {
            for (int i = 0; i < supportCells.Count; i++)
            {
                PlaneSupportCellLedgerEntry cell = supportCells[i];
                if (!cell.Gap)
                    continue;
                AddPlaneIssueLine(vertices, supportGapLines, cell.CornerA, cell.CornerB);
                AddPlaneIssueLine(vertices, supportGapLines, cell.CornerB, cell.CornerC);
                AddPlaneIssueLine(vertices, supportGapLines, cell.CornerC, cell.CornerD);
                AddPlaneIssueLine(vertices, supportGapLines, cell.CornerD, cell.CornerA);
            }
        }

        foreach (List<PlaneConstrainedZeroCrossTriangleLedgerEntry> group in issueGroups.Values)
        {
            if (group.Count < minPlaneConstrainedIssueTrianglesForBounds)
                continue;
            Vector3 min = new Vector3(float.PositiveInfinity, float.PositiveInfinity, float.PositiveInfinity);
            Vector3 max = new Vector3(float.NegativeInfinity, float.NegativeInfinity, float.NegativeInfinity);
            for (int i = 0; i < group.Count; i++)
            {
                min = Vector3.Min(min, Vector3.Min(group[i].A, Vector3.Min(group[i].B, group[i].C)));
                max = Vector3.Max(max, Vector3.Max(group[i].A, Vector3.Max(group[i].B, group[i].C)));
            }
            Vector3 padding = Vector3.one * planeConstrainedIssueBoundsPaddingMeters;
            AddPlaneIssueBounds(vertices, boundsLines, min - padding, max + padding);
        }

        _planeConstrainedZeroCrossIssueMesh.Clear();
        _outputDisplayPendingIssueLines.Clear();
        _outputDisplayBoundsIssueLines.Clear();
        _outputDisplayHardAuditLines.Clear();
        _outputDisplaySupportGapLines.Clear();
        if (problemLines.Count == 0 && hardIllegalLines.Count == 0 && supportGapLines.Count == 0)
        {
            _planeConstrainedZeroCrossIssueObject.SetActive(false);
            return;
        }
        _planeConstrainedZeroCrossIssueMesh.indexFormat =
            vertices.Count > 65535 ? IndexFormat.UInt32 : IndexFormat.UInt16;
        _planeConstrainedZeroCrossIssueMesh.SetVertices(vertices);
        _planeConstrainedZeroCrossIssueMesh.subMeshCount = 4;
        ReplaceOutputDisplayLineIndices(_outputDisplayPendingIssueLines, problemLines);
        ReplaceOutputDisplayLineIndices(_outputDisplayBoundsIssueLines, boundsLines);
        ReplaceOutputDisplayLineIndices(_outputDisplayHardAuditLines, hardIllegalLines);
        ReplaceOutputDisplayLineIndices(_outputDisplaySupportGapLines, supportGapLines);
        ApplyOutputDisplayIssueSubmeshFilter();
        _planeConstrainedZeroCrossIssueMesh.RecalculateBounds();
        ApplyOutputDisplayLayerVisibility();
    }

    private static void AddPlaneIssueLine(
        List<Vector3> vertices, List<int> indices, Vector3 a, Vector3 b)
    {
        int start = vertices.Count;
        vertices.Add(a);
        vertices.Add(b);
        indices.Add(start);
        indices.Add(start + 1);
    }

    private static void AddPlaneIssueBounds(
        List<Vector3> vertices, List<int> indices, Vector3 min, Vector3 max)
    {
        Vector3[] corners =
        {
            new Vector3(min.x, min.y, min.z), new Vector3(max.x, min.y, min.z),
            new Vector3(max.x, max.y, min.z), new Vector3(min.x, max.y, min.z),
            new Vector3(min.x, min.y, max.z), new Vector3(max.x, min.y, max.z),
            new Vector3(max.x, max.y, max.z), new Vector3(min.x, max.y, max.z)
        };
        int[,] edges =
        {
            { 0, 1 }, { 1, 2 }, { 2, 3 }, { 3, 0 },
            { 4, 5 }, { 5, 6 }, { 6, 7 }, { 7, 4 },
            { 0, 4 }, { 1, 5 }, { 2, 6 }, { 3, 7 }
        };
        for (int i = 0; i < edges.GetLength(0); i++)
            AddPlaneIssueLine(vertices, indices, corners[edges[i, 0]], corners[edges[i, 1]]);
    }

