        LastAuthoritativeCyanPlaneEdgeNoAnchorOutsideRegistryCount = 0;
        LastAuthoritativeCyanPlaneEdgePartialInsufficientCornersCount = 0;
        LastAuthoritativeCyanPlaneEdgePartialDirectionalGapCount = 0;
        LastAuthoritativeCyanPlaneEdgePartialMixedGateCount = 0;
        LastAuthoritativeCyanPlanePropagationOrphanExcludedCount = 0;
        LastAuthoritativeCyanPlaneEdgeNearPlanePromotionShadowCount = 0;
        LastAuthoritativeCyanPlaneEdgeWrongVotePromotionShadowCount = 0;
        LastAuthoritativeCyanNearPlaneProbationHeldCount = 0;
        LastAuthoritativeCyanNearPlaneProbationPromotedCount = 0;
        LastAuthoritativeCyanNearPlaneProbationRevokedCount = 0;
        LastAuthoritativeCyanNearPlaneProbationActiveCount = 0;
        LastAuthoritativeCyanNearPlanePatchCandidateCount = 0;
        LastAuthoritativeCyanNearPlanePatchPromotedCount = 0;
        LastAuthoritativeCyanNearPlanePatchPromotedVertexCount = 0;
        LastAuthoritativeCyanNearPlanePatchBlockedAnchorCount = 0;
        LastAuthoritativeCyanNearPlanePatchAtomicLockCount = 0;
        LastAuthoritativeCyanNearPlanePatchWrongVoteCandidateCount = 0;
        LastAuthoritativeCyanNearPlanePatchBilateralAnchorCount = 0;
        LastAuthoritativeCyanStructuralPlaneQualifiedCount = 0;
        LastAuthoritativeCyanStructuralPlaneRejectedCount = 0;
        LastAuthoritativeCyanStructuralWallPlaneCount = 0;
        LastAuthoritativeCyanStructuralHorizontalPlaneCount = 0;
        LastAuthoritativeCyanAdaptiveBandCandidateCount = 0;
        LastAuthoritativeCyanAdaptiveBandAcceptedCount = 0;
        LastAuthoritativeCyanAdaptiveBandRejectedNonStructuralCount = 0;
        LastAuthoritativeCyanNonStructuralProtectedSampleCount = 0;
        LastAuthoritativeCyanPlaneResidualBeforeMeters = 0f;
        LastAuthoritativeCyanPlaneResidualAfterMeters = 0f;
        LastAuthoritativeCyanPlaneMaxMoveMeters = 0f;
    }

    private void ApplyAuthoritativeCyanGlobalPlaneConstraints(
        IReadOnlyDictionary<Vector3Int, AuthoritativeTsdfBlockMesh> blocks,
        IReadOnlyDictionary<Vector3Int, bool> directAttempts)
    {
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes =
            GetIncrementalPlaneConstraintsWithColdStartCandidates();
        LastAuthoritativeCyanPlaneMatureCount =
            _stablePlaneRegistry.GetMatureConstraints().Count;
        if (!enableAuthoritativeCyanPlaneSnap || blocks == null || blocks.Count == 0 ||
            planes == null || planes.Count == 0)
        {
            foreach (AuthoritativeCyanNearPlaneProbation probation in
                     _authoritativeCyanNearPlaneProbation.Values)
            {
                if (probation.ConsecutiveSnapshots >=
                    Mathf.Clamp(authoritativeCyanNearPlaneProbationRequiredSnapshots, 2, 4))
                    LastAuthoritativeCyanNearPlaneProbationRevokedCount++;
            }
            _authoritativeCyanNearPlaneProbation.Clear();
            return;
        }

        AuditAuthoritativeCyanStructuralPlanes(planes);

        LastAuthoritativeCyanPlaneCandidateBlockCount = blocks.Count;
        Dictionary<AuthoritativeCellComponentKey, Vector3> pointSums =
            new Dictionary<AuthoritativeCellComponentKey, Vector3>();
        Dictionary<AuthoritativeCellComponentKey, int> pointCounts =
            new Dictionary<AuthoritativeCellComponentKey, int>();
        Dictionary<AuthoritativeCellComponentKey, Vector3> normalSums =
            new Dictionary<AuthoritativeCellComponentKey, Vector3>();
        Dictionary<AuthoritativeCellComponentKey, Vector3> rawNormalSums =
            new Dictionary<AuthoritativeCellComponentKey, Vector3>();
        Dictionary<AuthoritativeCellComponentKey, int> normalContributionCounts =
            new Dictionary<AuthoritativeCellComponentKey, int>();

        foreach (AuthoritativeTsdfBlockMesh block in blocks.Values)
        {
            if (block.VertexKeys.Count != block.Vertices.Count)
                continue;
            for (int i = 0; i < block.Vertices.Count; i++)
            {
                AuthoritativeCellComponentKey key = block.VertexKeys[i];
                pointSums.TryGetValue(key, out Vector3 pointSum);
                pointSums[key] = pointSum + block.Vertices[i];
                pointCounts.TryGetValue(key, out int pointCount);
                pointCounts[key] = pointCount + 1;
            }
            for (int i = 0; i + 2 < block.Triangles.Count; i += 3)
            {
                int a = block.Triangles[i];
                int b = block.Triangles[i + 1];
                int c = block.Triangles[i + 2];
                Vector3 cross = Vector3.Cross(
                    block.Vertices[b] - block.Vertices[a],
                    block.Vertices[c] - block.Vertices[a]);
                if (cross.sqrMagnitude <= 0.0000000001f)
                    continue;
                Vector3 normal = cross.normalized;
                AccumulateAuthoritativeCyanGlobalNormal(block.VertexKeys[a], normal, normalSums);
                AccumulateAuthoritativeCyanGlobalNormal(block.VertexKeys[b], normal, normalSums);
                AccumulateAuthoritativeCyanGlobalNormal(block.VertexKeys[c], normal, normalSums);
                AccumulateAuthoritativeCyanRawNormalEvidence(
                    block.VertexKeys[a], normal, rawNormalSums, normalContributionCounts);
                AccumulateAuthoritativeCyanRawNormalEvidence(
                    block.VertexKeys[b], normal, rawNormalSums, normalContributionCounts);
                AccumulateAuthoritativeCyanRawNormalEvidence(
                    block.VertexKeys[c], normal, rawNormalSums, normalContributionCounts);
            }
        }

        Dictionary<AuthoritativeCellComponentKey, int> planeByVertex =
            new Dictionary<AuthoritativeCellComponentKey, int>(pointSums.Count);
        Dictionary<AuthoritativeCellComponentKey, string> rejectByVertex =
            new Dictionary<AuthoritativeCellComponentKey, string>(pointSums.Count);
        foreach (KeyValuePair<AuthoritativeCellComponentKey, Vector3> pair in pointSums)
        {
            AuthoritativeCellComponentKey key = pair.Key;
            Vector3 point = pair.Value / Mathf.Max(1, pointCounts[key]);
            if (!normalSums.TryGetValue(key, out Vector3 normal) || normal.sqrMagnitude < 0.000001f)
            {
                rejectByVertex[key] = "normal";
                continue;
            }
            int plane = MatchAuthoritativeCyanPlane(point, normal.normalized, planes, out string rejectReason);
            if (plane >= 0)
                planeByVertex[key] = plane;
            else
                rejectByVertex[key] = rejectReason;
        }

        PropagateAuthoritativeCyanPlaneSupport(
            planes, pointSums, pointCounts, normalSums, rawNormalSums,
            normalContributionCounts, planeByVertex, rejectByVertex,
            out Dictionary<AuthoritativeCellComponentKey, int> promotedPatchByVertex);

        foreach (KeyValuePair<AuthoritativeCellComponentKey, int> pair in planeByVertex)
            _authoritativeCyanLastPlaneByVertex[pair.Key] = pair.Value;
        foreach (KeyValuePair<AuthoritativeCellComponentKey, string> pair in rejectByVertex)
        {
            if (!planeByVertex.ContainsKey(pair.Key))
                _authoritativeCyanLastRejectByVertex[pair.Key] = pair.Value;
        }

        foreach (string reject in rejectByVertex.Values)
        {
            if (reject == "normal") LastAuthoritativeCyanPlaneRejectedNormalCount++;
            else if (reject == "distance") LastAuthoritativeCyanPlaneRejectedDistanceCount++;
            else if (reject == "extent") LastAuthoritativeCyanPlaneRejectedExtentCount++;
            else if (reject == "ambiguous") LastAuthoritativeCyanPlaneRejectedAmbiguityCount++;
        }

        // Locks are global canonical keys. If one block discovers that moving a
        // shared vertex would fold a triangle, every block keeps that vertex raw.
        HashSet<AuthoritativeCellComponentKey> locked = new HashSet<AuthoritativeCellComponentKey>();
        int geometryLockEvents = 0;
        for (int pass = 0; pass < 4; pass++)
        {
            bool addedLock = false;
            foreach (AuthoritativeTsdfBlockMesh block in blocks.Values)
            {
                if (block.VertexKeys.Count != block.Vertices.Count)
                    continue;
                List<Vector3> projected = BuildAuthoritativeCyanGloballyProjectedVertices(
                    block, planes, planeByVertex, locked, out List<int> moveOverflowVertices);
                for (int i = 0; i < moveOverflowVertices.Count; i++)
                {
                    AuthoritativeCellComponentKey key = block.VertexKeys[moveOverflowVertices[i]];
                    if (LockAuthoritativeCyanVertexOrPromotedPatch(
                            key, promotedPatchByVertex, locked))
                    {
                        LastAuthoritativeCyanPlaneRejectedMoveCount++;
                        addedLock = true;
                    }
                }
                for (int i = 0; i + 2 < block.Triangles.Count; i += 3)
                {
                    int a = block.Triangles[i];
                    int b = block.Triangles[i + 1];
                    int c = block.Triangles[i + 2];
                    if (AuthoritativeCyanProjectedTriangleSafe(block.Vertices, projected, a, b, c))
                        continue;
                    bool triangleAddedLock = false;
                    if (planeByVertex.ContainsKey(block.VertexKeys[a]) &&
                        LockAuthoritativeCyanVertexOrPromotedPatch(block.VertexKeys[a], promotedPatchByVertex, locked))
                        triangleAddedLock = true;
                    if (planeByVertex.ContainsKey(block.VertexKeys[b]) &&
                        LockAuthoritativeCyanVertexOrPromotedPatch(block.VertexKeys[b], promotedPatchByVertex, locked))
                        triangleAddedLock = true;
                    if (planeByVertex.ContainsKey(block.VertexKeys[c]) &&
                        LockAuthoritativeCyanVertexOrPromotedPatch(block.VertexKeys[c], promotedPatchByVertex, locked))
                        triangleAddedLock = true;
                    if (triangleAddedLock)
                    {
                        geometryLockEvents++;
                        addedLock = true;
                    }
                }
            }
            if (!addedLock)
                break;
        }
        LastAuthoritativeCyanPlaneRejectedGeometryCount = geometryLockEvents;

        int residualSamples = 0;
        float residualBeforeSum = 0f;
        float residualAfterSum = 0f;
        foreach (KeyValuePair<Vector3Int, AuthoritativeTsdfBlockMesh> pair in blocks)
        {
            AuthoritativeTsdfBlockMesh block = pair.Value;
            bool direct = directAttempts != null && directAttempts.TryGetValue(pair.Key, out bool isDirect) && isDirect;
            int matchedTriangles = 0;
            int localRejectNormal = 0;
            int localRejectDistance = 0;
            int localRejectExtent = 0;
            int localRejectAmbiguity = 0;
            int localLocked = 0;
            HashSet<AuthoritativeCellComponentKey> localRejected = new HashSet<AuthoritativeCellComponentKey>();
            for (int i = 0; i < block.VertexKeys.Count; i++)
            {
                AuthoritativeCellComponentKey key = block.VertexKeys[i];
                if (locked.Contains(key) && planeByVertex.ContainsKey(key))
                    localLocked++;
                if (!localRejected.Add(key) || !rejectByVertex.TryGetValue(key, out string reject))
                    continue;
                if (reject == "normal") localRejectNormal++;
                else if (reject == "distance") localRejectDistance++;
                else if (reject == "extent") localRejectExtent++;
                else if (reject == "ambiguous") localRejectAmbiguity++;
            }
            for (int i = 0; i + 2 < block.Triangles.Count; i += 3)
            {
                int a = block.Triangles[i];
                int b = block.Triangles[i + 1];
                int c = block.Triangles[i + 2];
                if (planeByVertex.TryGetValue(block.VertexKeys[a], out int pa) &&
                    planeByVertex.TryGetValue(block.VertexKeys[b], out int pb) &&
                    planeByVertex.TryGetValue(block.VertexKeys[c], out int pc) && pa == pb && pb == pc)
                    matchedTriangles++;
            }

            List<Vector3> projected = BuildAuthoritativeCyanGloballyProjectedVertices(
                block, planes, planeByVertex, locked, out List<int> finalOverflows);
            bool safe = finalOverflows.Count == 0;
            for (int i = 0; safe && i + 2 < block.Triangles.Count; i += 3)
                safe = AuthoritativeCyanProjectedTriangleSafe(
                    block.Vertices, projected, block.Triangles[i], block.Triangles[i + 1], block.Triangles[i + 2]);

            int movedVertices = 0;
            float blockBefore = 0f;
            float blockAfter = 0f;
            float blockMaxMove = 0f;
            if (safe)
            {
                for (int i = 0; i < block.Vertices.Count; i++)
                {
                    if (!planeByVertex.TryGetValue(block.VertexKeys[i], out int planeIndex) ||
                        locked.Contains(block.VertexKeys[i]))
                        continue;
                    Vector3 normal = planes[planeIndex].Normal.normalized;
                    float before = Mathf.Abs(Vector3.Dot(normal, block.Vertices[i]) + planes[planeIndex].Offset);
                    float after = Mathf.Abs(Vector3.Dot(normal, projected[i]) + planes[planeIndex].Offset);
                    blockBefore += before;
                    blockAfter += after;
                    blockMaxMove = Mathf.Max(blockMaxMove, before);
                    movedVertices++;
                }
            }

            bool applied = safe && movedVertices > 0;
            string rollbackReason = safe ? "none" : "geometry";
            if (applied)
            {
                for (int i = 0; i < block.VertexKeys.Count; i++)
                {
                    AuthoritativeCellComponentKey key = block.VertexKeys[i];
                    if (planeByVertex.ContainsKey(key) && !locked.Contains(key))
                        _authoritativeCyanLastAppliedPlaneKeys.Add(key);
                }
                block.Vertices.Clear();
                block.Vertices.AddRange(projected);
                LastAuthoritativeCyanPlaneAppliedBlockCount++;
                LastAuthoritativeCyanPlaneMovedVertexCount += movedVertices;
                residualBeforeSum += blockBefore;
                residualAfterSum += blockAfter;
                residualSamples += movedVertices;
                LastAuthoritativeCyanPlaneMaxMoveMeters = Mathf.Max(
                    LastAuthoritativeCyanPlaneMaxMoveMeters, blockMaxMove);
            }
            else if (!safe)
            {
                LastAuthoritativeCyanPlaneRollbackBlockCount++;
            }
            LastAuthoritativeCyanPlaneMatchedTriangleCount += matchedTriangles;
            LastAuthoritativeCyanPlaneCreaseLockedVertexCount += localLocked;
            AppendAuthoritativeCyanPlaneSnapRow(
                pair.Key, direct, block, planes.Count, matchedTriangles, movedVertices,
                localLocked, localRejectNormal, localRejectDistance, localRejectExtent, localRejectAmbiguity,
                movedVertices > 0 ? blockBefore / movedVertices : 0f,
                movedVertices > 0 ? blockAfter / movedVertices : 0f,
                blockMaxMove, applied, rollbackReason);
        }
        LastAuthoritativeCyanPlaneResidualBeforeMeters = residualSamples > 0
            ? residualBeforeSum / residualSamples : 0f;
        LastAuthoritativeCyanPlaneResidualAfterMeters = residualSamples > 0
            ? residualAfterSum / residualSamples : 0f;

        Dictionary<AuthoritativeCellComponentKey, Vector3> firstPublishedPosition =
            new Dictionary<AuthoritativeCellComponentKey, Vector3>();
        HashSet<AuthoritativeCellComponentKey> countedSharedKeys =
            new HashSet<AuthoritativeCellComponentKey>();
        float sharedTolerance = Mathf.Max(0.00001f, authoritativeCyanWeldToleranceMeters);
        foreach (AuthoritativeTsdfBlockMesh block in blocks.Values)
        {
            for (int i = 0; i < block.Vertices.Count && i < block.VertexKeys.Count; i++)
            {
                AuthoritativeCellComponentKey key = block.VertexKeys[i];
                if (!firstPublishedPosition.TryGetValue(key, out Vector3 first))
                {
                    firstPublishedPosition[key] = block.Vertices[i];
                    continue;
                }
                if (countedSharedKeys.Add(key))
                    LastAuthoritativeCyanPlaneSharedVertexKeyCount++;
                if (Vector3.Distance(first, block.Vertices[i]) > sharedTolerance)
                    LastAuthoritativeCyanPlaneSharedPositionMismatchCount++;
            }
        }
    }

    private void PropagateAuthoritativeCyanPlaneSupport(
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, Vector3> pointSums,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, int> pointCounts,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, Vector3> normalSums,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, Vector3> rawNormalSums,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, int> normalContributionCounts,
        Dictionary<AuthoritativeCellComponentKey, int> planeByVertex,
        Dictionary<AuthoritativeCellComponentKey, string> rejectByVertex,
        out Dictionary<AuthoritativeCellComponentKey, int> promotedPatchByVertex)
    {
        promotedPatchByVertex = new Dictionary<AuthoritativeCellComponentKey, int>();
        if (!enableAuthoritativeCyanPlaneEdgePropagation || planes == null || planes.Count == 0)
            return;

        Dictionary<Vector3Int, List<AuthoritativeCellComponentKey>> keysByCell =
            new Dictionary<Vector3Int, List<AuthoritativeCellComponentKey>>();
        List<AuthoritativeCellComponentKey> candidates = new List<AuthoritativeCellComponentKey>();
        foreach (KeyValuePair<AuthoritativeCellComponentKey, Vector3> pair in pointSums)
        {
            bool referencedBySurface =
                normalContributionCounts.TryGetValue(pair.Key, out int normalContributions) &&
                normalContributions > 0;
            if (!referencedBySurface)
            {
                if (rejectByVertex.TryGetValue(pair.Key, out string orphanReject) && orphanReject == "normal")
                    LastAuthoritativeCyanPlanePropagationOrphanExcludedCount++;
                continue;
            }
            if (!keysByCell.TryGetValue(pair.Key.Cell, out List<AuthoritativeCellComponentKey> cellKeys))
            {
                cellKeys = new List<AuthoritativeCellComponentKey>(2);
                keysByCell[pair.Key.Cell] = cellKeys;
            }
            cellKeys.Add(pair.Key);
            if (rejectByVertex.TryGetValue(pair.Key, out string reject) && reject == "normal")
                candidates.Add(pair.Key);
        }
        LastAuthoritativeCyanPlanePropagationCandidateCount = candidates.Count;
        if (candidates.Count == 0)
            return;

        Vector3Int[] directions =
        {
            new Vector3Int(1, 0, 0), new Vector3Int(-1, 0, 0),
            new Vector3Int(0, 1, 0), new Vector3Int(0, -1, 0),
            new Vector3Int(0, 0, 1), new Vector3Int(0, 0, -1)
        };
        Dictionary<AuthoritativeCellComponentKey, string> lastReject =
            new Dictionary<AuthoritativeCellComponentKey, string>();
        int maxPasses = Mathf.Clamp(authoritativeCyanPlaneEdgePropagationPasses, 1, 4);
        for (int pass = 0; pass < maxPasses; pass++)
        {
            List<KeyValuePair<AuthoritativeCellComponentKey, int>> staged =
                new List<KeyValuePair<AuthoritativeCellComponentKey, int>>();
            for (int candidateIndex = 0; candidateIndex < candidates.Count; candidateIndex++)
            {
                AuthoritativeCellComponentKey key = candidates[candidateIndex];
                if (planeByVertex.ContainsKey(key))
                    continue;
                Dictionary<int, int> votes = new Dictionary<int, int>();
                Dictionary<int, int> axisMasks = new Dictionary<int, int>();
                int totalVotes = 0;
                for (int directionIndex = 0; directionIndex < directions.Length; directionIndex++)
                {
                    if (!keysByCell.TryGetValue(key.Cell + directions[directionIndex],
                            out List<AuthoritativeCellComponentKey> neighbours))
                        continue;
                    int axisBit = 1 << (directionIndex / 2);
                    for (int neighbourIndex = 0; neighbourIndex < neighbours.Count; neighbourIndex++)
                    {
                        if (!planeByVertex.TryGetValue(neighbours[neighbourIndex], out int neighbourPlane))
                            continue;
                        votes.TryGetValue(neighbourPlane, out int count);
                        votes[neighbourPlane] = count + 1;
                        axisMasks.TryGetValue(neighbourPlane, out int mask);
                        axisMasks[neighbourPlane] = mask | axisBit;
                        totalVotes++;
                    }
                }

                int bestPlane = -1;
                int bestVotes = 0;
                int secondVotes = 0;
                foreach (KeyValuePair<int, int> vote in votes)
                {
                    if (vote.Value > bestVotes)
                    {
                        secondVotes = bestVotes;
                        bestVotes = vote.Value;
                        bestPlane = vote.Key;
                    }
                    else if (vote.Value > secondVotes)
                    {
                        secondVotes = vote.Value;
                    }
                }
                int axisCount = bestPlane >= 0 && axisMasks.TryGetValue(bestPlane, out int bestMask)
                    ? ((bestMask & 1) != 0 ? 1 : 0) + ((bestMask & 2) != 0 ? 1 : 0) + ((bestMask & 4) != 0 ? 1 : 0)
                    : 0;
                if (bestVotes < authoritativeCyanPlaneEdgePropagationMinVotes || axisCount < 2)
                {
                    lastReject[key] = "votes";
                    continue;
                }
                float dominance = bestVotes / (float)Mathf.Max(1, totalVotes);
                if (secondVotes > 0 && dominance < authoritativeCyanPlaneEdgePropagationMinDominance)
                {
                    lastReject[key] = "ambiguity";
                    continue;
                }

                ScanCoverStablePlaneRegistry.PlaneConstraint plane = planes[bestPlane];
                Vector3 normal = plane.Normal.normalized;
                Vector3 point = pointSums[key] / Mathf.Max(1, pointCounts[key]);
                float distance = Mathf.Abs(Vector3.Dot(normal, point) + plane.Offset);
                float distanceLimit = GetAuthoritativeCyanPlaneDistanceLimit(plane, true);
                bool usesAdaptiveBand = distance > authoritativeCyanPlaneEdgePropagationMaxDistanceMeters &&
                                        distance <= distanceLimit;
                if (usesAdaptiveBand)
                    LastAuthoritativeCyanAdaptiveBandCandidateCount++;
                if (distance > distanceLimit)
                {
                    lastReject[key] = "distance";
                    continue;
                }
                Vector3 fromCenter = point - plane.Center;
                Vector3 tangent = fromCenter - normal * Vector3.Dot(normal, fromCenter);
                if (tangent.magnitude > plane.Radius + authoritativeCyanPlaneTangentialPaddingMeters)
                {
                    lastReject[key] = "distance";
                    continue;
                }
                if (!normalSums.TryGetValue(key, out Vector3 surfaceNormal) ||
                    surfaceNormal.sqrMagnitude < 0.000001f ||
                    Mathf.Abs(Vector3.Dot(surfaceNormal.normalized, normal)) <
                    authoritativeCyanPlaneEdgePropagationMinNormalDot)
                {
                    lastReject[key] = "normal";
                    continue;
                }
                staged.Add(new KeyValuePair<AuthoritativeCellComponentKey, int>(key, bestPlane));
                if (usesAdaptiveBand)
                    LastAuthoritativeCyanAdaptiveBandAcceptedCount++;
            }

            if (staged.Count == 0)
                break;
            LastAuthoritativeCyanPlanePropagationPassCount = pass + 1;
            for (int i = 0; i < staged.Count; i++)
            {
                planeByVertex[staged[i].Key] = staged[i].Value;
                rejectByVertex.Remove(staged[i].Key);
                lastReject.Remove(staged[i].Key);
                LastAuthoritativeCyanPlanePropagationAcceptedCount++;
            }
        }

        foreach (AuthoritativeCellComponentKey key in candidates)
        {
            if (planeByVertex.ContainsKey(key))
                continue;
            string reason = lastReject.TryGetValue(key, out string value) ? value : "votes";
            if (reason == "votes") LastAuthoritativeCyanPlanePropagationRejectedVotesCount++;
            else if (reason == "ambiguity") LastAuthoritativeCyanPlanePropagationRejectedAmbiguityCount++;
            else if (reason == "distance") LastAuthoritativeCyanPlanePropagationRejectedDistanceCount++;
            else if (reason == "normal") LastAuthoritativeCyanPlanePropagationRejectedNormalCount++;
        }
            Dictionary<AuthoritativeCellComponentKey, int> patchEligible =
                new Dictionary<AuthoritativeCellComponentKey, int>();
            Dictionary<AuthoritativeCellComponentKey, string> patchReason =
                new Dictionary<AuthoritativeCellComponentKey, string>();
            HashSet<AuthoritativeCellComponentKey> adaptivePatchEligible =
                new HashSet<AuthoritativeCellComponentKey>();
            ClassifyAuthoritativeCyanPlaneVoteShortfall(
                planes, pointSums, pointCounts, normalSums, rawNormalSums,
                normalContributionCounts, planeByVertex, keysByCell,
                directions, candidates, lastReject, patchEligible, patchReason,
                adaptivePatchEligible);
            PromoteAuthoritativeCyanNearPlanePatches(
                planes, keysByCell, directions, patchEligible, patchReason,
                adaptivePatchEligible,
                planeByVertex, promotedPatchByVertex);
    }

    private void ClassifyAuthoritativeCyanPlaneVoteShortfall(
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, Vector3> pointSums,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, int> pointCounts,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, Vector3> normalSums,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, Vector3> rawNormalSums,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, int> normalContributionCounts,
        Dictionary<AuthoritativeCellComponentKey, int> planeByVertex,
        IReadOnlyDictionary<Vector3Int, List<AuthoritativeCellComponentKey>> keysByCell,
        IReadOnlyList<Vector3Int> directions,
        IReadOnlyList<AuthoritativeCellComponentKey> candidates,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, string> lastReject,
        Dictionary<AuthoritativeCellComponentKey, int> patchEligible,
        Dictionary<AuthoritativeCellComponentKey, string> patchReason,
        HashSet<AuthoritativeCellComponentKey> adaptivePatchEligible)
    {
        HashSet<AuthoritativeCellComponentKey> probationSeen =
            new HashSet<AuthoritativeCellComponentKey>();
        HashSet<AuthoritativeCellComponentKey> voteShortfall =
            new HashSet<AuthoritativeCellComponentKey>();
        for (int i = 0; i < candidates.Count; i++)
        {
            AuthoritativeCellComponentKey key = candidates[i];
            if (!planeByVertex.ContainsKey(key) &&
                lastReject.TryGetValue(key, out string reason) && reason == "votes")
                voteShortfall.Add(key);
        }
        if (voteShortfall.Count == 0)
        {
            FinalizeAuthoritativeCyanNearPlaneProbation(probationSeen, planeByVertex, planes);
            return;
        }

        Dictionary<AuthoritativeCellComponentKey, int> componentSizes =
            new Dictionary<AuthoritativeCellComponentKey, int>(voteShortfall.Count);
        HashSet<AuthoritativeCellComponentKey> visited = new HashSet<AuthoritativeCellComponentKey>();
        foreach (AuthoritativeCellComponentKey start in voteShortfall)
        {
            if (!visited.Add(start))
                continue;
            Queue<AuthoritativeCellComponentKey> queue = new Queue<AuthoritativeCellComponentKey>();
            List<AuthoritativeCellComponentKey> component = new List<AuthoritativeCellComponentKey>();
            queue.Enqueue(start);
            while (queue.Count > 0)
            {
                AuthoritativeCellComponentKey current = queue.Dequeue();
                component.Add(current);
                for (int directionIndex = 0; directionIndex < directions.Count; directionIndex++)
                {
                    if (!keysByCell.TryGetValue(current.Cell + directions[directionIndex],
                            out List<AuthoritativeCellComponentKey> neighbours))
                        continue;
                    for (int neighbourIndex = 0; neighbourIndex < neighbours.Count; neighbourIndex++)
                    {
                        AuthoritativeCellComponentKey neighbour = neighbours[neighbourIndex];
                        if (voteShortfall.Contains(neighbour) && visited.Add(neighbour))
                            queue.Enqueue(neighbour);
                    }
                }
            }
            for (int i = 0; i < component.Count; i++)
                componentSizes[component[i]] = component.Count;
        }

        foreach (AuthoritativeCellComponentKey key in voteShortfall)
        {
            Dictionary<int, int> votes = new Dictionary<int, int>();
            Dictionary<int, int> axisMasks = new Dictionary<int, int>();
            int totalVotes = 0;
            for (int directionIndex = 0; directionIndex < directions.Count; directionIndex++)
            {
                if (!keysByCell.TryGetValue(key.Cell + directions[directionIndex],
                        out List<AuthoritativeCellComponentKey> neighbours))
                    continue;
                int axisBit = 1 << (directionIndex / 2);
                for (int neighbourIndex = 0; neighbourIndex < neighbours.Count; neighbourIndex++)
                {
                    if (!planeByVertex.TryGetValue(neighbours[neighbourIndex], out int plane))
                        continue;
                    votes.TryGetValue(plane, out int count);
                    votes[plane] = count + 1;
                    axisMasks.TryGetValue(plane, out int mask);
                    axisMasks[plane] = mask | axisBit;
                    totalVotes++;
                }
            }

            int bestPlane = -1;
            int bestVotes = 0;
            foreach (KeyValuePair<int, int> vote in votes)
            {
                if (vote.Value > bestVotes)
                {
                    bestVotes = vote.Value;
                    bestPlane = vote.Key;
                }
            }
            int axisCount = bestPlane >= 0 && axisMasks.TryGetValue(bestPlane, out int maskValue)
                ? ((maskValue & 1) != 0 ? 1 : 0) + ((maskValue & 2) != 0 ? 1 : 0) + ((maskValue & 4) != 0 ? 1 : 0)
                : 0;
            Vector3 point = pointSums[key] / Mathf.Max(1, pointCounts[key]);
            float planeDistance = 0f;
            float bestPlaneDistanceLimit = authoritativeCyanPlaneEdgePropagationMaxDistanceMeters;
            float normalDot = 0f;
            Vector3 referenceNormal = Vector3.zero;
            if (bestPlane >= 0)
            {
                Vector3 planeNormal = planes[bestPlane].Normal.normalized;
                referenceNormal = planeNormal;
                planeDistance = Mathf.Abs(Vector3.Dot(planeNormal, point) + planes[bestPlane].Offset);
                bestPlaneDistanceLimit = GetAuthoritativeCyanPlaneDistanceLimit(planes[bestPlane], true);
                if (normalSums.TryGetValue(key, out Vector3 surfaceNormal) && surfaceNormal.sqrMagnitude > 0.000001f)
                    normalDot = Mathf.Abs(Vector3.Dot(surfaceNormal.normalized, planeNormal));
            }
            else if (normalSums.TryGetValue(key, out Vector3 fallbackNormal) && fallbackNormal.sqrMagnitude > 0.000001f)
            {
                referenceNormal = fallbackNormal.normalized;
            }
            AuthoritativeDirectionalFrontierStats frontier =
                AnalyzeAuthoritativeDirectionalFrontier(key.Cell, referenceNormal, keysByCell);

            int componentSize = componentSizes.TryGetValue(key, out int size) ? size : 1;
            string classification;
            if (votes.Count >= 2)
            {
                classification = "crease_boundary";
                LastAuthoritativeCyanPlaneEdgeCreaseBoundaryCount++;
            }
            else if (totalVotes == 0 && componentSize <= 8)
            {
                classification = "isolated_island";
                LastAuthoritativeCyanPlaneEdgeIsolatedIslandCount++;
            }
            else if (frontier.IsViewFrontier)
            {
                classification = "view_frontier";
                LastAuthoritativeCyanPlaneEdgeViewFrontierCount++;
            }
            else if (bestPlane >= 0 &&
                     planeDistance <= bestPlaneDistanceLimit &&
                     normalDot >= authoritativeCyanPlaneEdgePropagationMinNormalDot)
            {
                classification = "single_anchor";
                LastAuthoritativeCyanPlaneEdgeSingleAnchorCount++;
            }
            else
            {
                classification = "unresolved";
                LastAuthoritativeCyanPlaneEdgeUnresolvedCount++;
            }

            bool fullDirectionalSupport =
                frontier.CurrentUsableCorners == 8 && frontier.TangentMissingDirections == 0;
            bool normalConflict = bestPlane >= 0 &&
                normalDot < authoritativeCyanPlaneEdgePropagationMinNormalDot;
            bool distanceConflict = bestPlane >= 0 &&
                planeDistance > bestPlaneDistanceLimit;
            string unresolvedCause = string.Empty;
            if (classification == "unresolved")
            {
                if (bestPlane < 0)
                {
                    unresolvedCause = "no_plane_anchor";
                    LastAuthoritativeCyanPlaneEdgeNoPlaneAnchorCount++;
                }
                else if (!fullDirectionalSupport)
                {
                    unresolvedCause = "partial_ambiguous";
                    LastAuthoritativeCyanPlaneEdgePartialAmbiguousCount++;
                }
                else if (distanceConflict)
                {
                    unresolvedCause = "supported_plane_distance";
                    LastAuthoritativeCyanPlaneEdgeSupportedPlaneDistanceCount++;
                }
                else if (normalConflict)
                {
                    unresolvedCause = "supported_normal_conflict";
                    LastAuthoritativeCyanPlaneEdgeSupportedNormalConflictCount++;
                }
                else
                {
                    // Defensive bucket: every unresolved anchored and fully-supported
                    // sample should have failed either the distance or normal gate.
                    unresolvedCause = "partial_ambiguous";
                    LastAuthoritativeCyanPlaneEdgePartialAmbiguousCount++;
                }
            }

            normalContributionCounts.TryGetValue(key, out int normalContributions);
            normalSums.TryGetValue(key, out Vector3 alignedNormalSum);
            rawNormalSums.TryGetValue(key, out Vector3 rawNormalSum);
            float alignedNormalCoherence = normalContributions > 0
                ? alignedNormalSum.magnitude / normalContributions
                : 0f;
            float rawNormalCoherence = normalContributions > 0
                ? rawNormalSum.magnitude / normalContributions
                : 0f;
            bool normalAvailable = normalContributions > 0 &&
                alignedNormalSum.sqrMagnitude >= 0.000001f;

            int nearestPlane = -1;
            float nearestPlaneDistance = float.PositiveInfinity;
            float nearestPlaneNormalDot = 0f;
            for (int planeIndex = 0; planeIndex < planes.Count; planeIndex++)
            {
                if (!IsAuthoritativeCyanPlaneQualifiedAtPoint(
                        planes[planeIndex], point, out _, out _))
                    continue;
                Vector3 planeNormal = planes[planeIndex].Normal.normalized;
                float distance = Mathf.Abs(Vector3.Dot(planeNormal, point) + planes[planeIndex].Offset);
                if (distance >= nearestPlaneDistance)
                    continue;
                nearestPlane = planeIndex;
                nearestPlaneDistance = distance;
                nearestPlaneNormalDot = normalAvailable
                    ? Mathf.Abs(Vector3.Dot(alignedNormalSum.normalized, planeNormal))
                    : 0f;
            }
            bool nearestPlaneWithinExtent = false;
            float nearestPlaneDistanceLimit = authoritativeCyanPlaneEdgePropagationMaxDistanceMeters;
            if (nearestPlane >= 0)
            {
                nearestPlaneDistanceLimit = GetAuthoritativeCyanPlaneDistanceLimit(planes[nearestPlane], true);
                Vector3 nearestNormal = planes[nearestPlane].Normal.normalized;
                Vector3 nearestFromCenter = point - planes[nearestPlane].Center;
                Vector3 nearestTangent = nearestFromCenter -
                    nearestNormal * Vector3.Dot(nearestNormal, nearestFromCenter);
                nearestPlaneWithinExtent = nearestTangent.magnitude <=
                    planes[nearestPlane].Radius + authoritativeCyanPlaneTangentialPaddingMeters;
            }

            string normalSubcause = string.Empty;
            string distanceSubcause = string.Empty;
            string noAnchorSubcause = string.Empty;
            string partialSubcause = string.Empty;
            if (unresolvedCause == "supported_normal_conflict")
            {
                if (!normalAvailable)
                {
                    normalSubcause = "normal_missing";
                    LastAuthoritativeCyanPlaneEdgeNormalMissingCount++;
                }
                else if (rawNormalCoherence < authoritativeCyanPlaneEdgePropagationMinNormalDot &&
                         alignedNormalCoherence >= authoritativeCyanPlaneEdgePropagationMinNormalDot)
                {
                    normalSubcause = "winding_cancellation";
                    LastAuthoritativeCyanPlaneEdgeNormalWindingCancellationCount++;
                }
                else
                {
                    normalSubcause = "direction_conflict";
                    LastAuthoritativeCyanPlaneEdgeNormalDirectionConflictCount++;
                }
            }
            else if (unresolvedCause == "supported_plane_distance")
            {
                bool wrongPlaneVote = nearestPlane >= 0 && nearestPlane != bestPlane &&
                    nearestPlaneDistance <= nearestPlaneDistanceLimit &&
                    nearestPlaneNormalDot >= authoritativeCyanPlaneEdgePropagationMinNormalDot;
                if (wrongPlaneVote)
                {
                    distanceSubcause = "wrong_plane_vote";
                    LastAuthoritativeCyanPlaneEdgeDistanceWrongPlaneVoteCount++;
                }
                else
                {
                    distanceSubcause = "outside_all_planes";
                    LastAuthoritativeCyanPlaneEdgeDistanceOutsideAllPlanesCount++;
                }
            }
            else if (unresolvedCause == "no_plane_anchor")
            {
                bool nearPlane = nearestPlane >= 0 &&
                    nearestPlaneDistance <= nearestPlaneDistanceLimit &&
                    nearestPlaneNormalDot >= authoritativeCyanPlaneEdgePropagationMinNormalDot;
                if (nearPlane)
                {
                    noAnchorSubcause = "near_plane_no_vote";
                    LastAuthoritativeCyanPlaneEdgeNoAnchorNearPlaneCount++;
                }
                else
                {
                    noAnchorSubcause = "outside_registry";
                    LastAuthoritativeCyanPlaneEdgeNoAnchorOutsideRegistryCount++;
                }
            }
            else if (unresolvedCause == "partial_ambiguous")
            {
                if (frontier.CurrentUsableCorners < 8)
                {
                    partialSubcause = "insufficient_corners";
                    LastAuthoritativeCyanPlaneEdgePartialInsufficientCornersCount++;
                }
                else if (frontier.TangentMissingDirections > 0)
                {
                    partialSubcause = "directional_gap";
                    LastAuthoritativeCyanPlaneEdgePartialDirectionalGapCount++;
                }
                else
                {
                    partialSubcause = "mixed_gate";
                    LastAuthoritativeCyanPlaneEdgePartialMixedGateCount++;
                }
            }

            bool promotionShadow = false;
            int promotionShadowPlane = -1;
            string promotionShadowReason = string.Empty;
            int probationStreak = 0;
            string probationStatus = string.Empty;
            bool strictNearestPlaneEvidence = nearestPlane >= 0 && normalAvailable &&
                fullDirectionalSupport && nearestPlaneWithinExtent &&
                nearestPlaneDistance <= nearestPlaneDistanceLimit &&
                nearestPlaneNormalDot >= authoritativeCyanPlaneEdgePropagationMinNormalDot;
            bool usesAdaptiveNearestBand = strictNearestPlaneEvidence &&
                nearestPlaneDistance > authoritativeCyanPlaneEdgePropagationMaxDistanceMeters;
            if (noAnchorSubcause == "near_plane_no_vote" && strictNearestPlaneEvidence)
            {
                promotionShadow = true;
                promotionShadowPlane = nearestPlane;
                promotionShadowReason = "near_plane_no_vote";
                LastAuthoritativeCyanPlaneEdgeNearPlanePromotionShadowCount++;
                patchEligible[key] = nearestPlane;
                patchReason[key] = "near_plane_no_vote";
                if (usesAdaptiveNearestBand && adaptivePatchEligible.Add(key))
                    LastAuthoritativeCyanAdaptiveBandCandidateCount++;
            }
            else if (distanceSubcause == "wrong_plane_vote" && strictNearestPlaneEvidence)
            {
                promotionShadow = true;
                promotionShadowPlane = nearestPlane;
                promotionShadowReason = "wrong_plane_vote";
                LastAuthoritativeCyanPlaneEdgeWrongVotePromotionShadowCount++;
                // A wrong neighbour vote is still safe to trial when the point is
                // fully surrounded and independently matches one mature plane.
                // Keep it in the same atomic patch path as a missing-anchor cell;
                // points outside every registered plane remain excluded.
                patchEligible[key] = nearestPlane;
                patchReason[key] = "wrong_plane_vote";
                if (usesAdaptiveNearestBand && adaptivePatchEligible.Add(key))
                    LastAuthoritativeCyanAdaptiveBandCandidateCount++;
                LastAuthoritativeCyanNearPlanePatchWrongVoteCandidateCount++;
            }

            if (enableAuthoritativeCyanNearPlaneProbation &&
                promotionShadowReason == "near_plane_no_vote" && promotionShadowPlane >= 0)
            {
                probationSeen.Add(key);
                probationStreak = UpdateAuthoritativeCyanNearPlaneProbation(
                    key, planes[promotionShadowPlane].Id, LastAuthoritativeReadSnapshotSequence);
                int requiredSnapshots = Mathf.Clamp(
                    authoritativeCyanNearPlaneProbationRequiredSnapshots, 2, 4);
                if (probationStreak >= requiredSnapshots &&
                    !authoritativeCyanNearPlaneExactProbationDiagnosticOnly)
                {
                    planeByVertex[key] = promotionShadowPlane;
                    probationStatus = "promoted";
                    classification = "near_plane_promoted";
                    LastAuthoritativeCyanNearPlaneProbationPromotedCount++;
                    LastAuthoritativeCyanPlanePropagationRejectedVotesCount = Mathf.Max(
                        0, LastAuthoritativeCyanPlanePropagationRejectedVotesCount - 1);
                    LastAuthoritativeCyanPlaneEdgeUnresolvedCount = Mathf.Max(
                        0, LastAuthoritativeCyanPlaneEdgeUnresolvedCount - 1);
                    LastAuthoritativeCyanPlaneEdgeNoPlaneAnchorCount = Mathf.Max(
                        0, LastAuthoritativeCyanPlaneEdgeNoPlaneAnchorCount - 1);
                    LastAuthoritativeCyanPlaneEdgeNoAnchorNearPlaneCount = Mathf.Max(
                        0, LastAuthoritativeCyanPlaneEdgeNoAnchorNearPlaneCount - 1);
                }
                else
                {
                    probationStatus = probationStreak >= requiredSnapshots ? "validated" : "held";
                    LastAuthoritativeCyanNearPlaneProbationHeldCount++;
                }
            }

            if (_authoritativeCyanPlaneEdgeClassRows != null)
            {
                int bestPlaneId = bestPlane >= 0 ? planes[bestPlane].Id : -1;
                int nearestPlaneId = nearestPlane >= 0 ? planes[nearestPlane].Id : -1;
                _authoritativeCyanPlaneEdgeClassRows
                    .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
                    .Append(key.Cell.x).Append(',').Append(key.Cell.y).Append(',').Append(key.Cell.z).Append(',')
                    .Append(key.Component).Append(',').Append(classification).Append(',')
                    .Append(unresolvedCause).Append(',')
                    .Append(normalSubcause).Append(',')
                    .Append(distanceSubcause).Append(',')
                    .Append(noAnchorSubcause).Append(',')
                    .Append(partialSubcause).Append(',')
                    .Append(promotionShadow ? 1 : 0).Append(',')
                    .Append(promotionShadowPlane >= 0 ? planes[promotionShadowPlane].Id : -1).Append(',')
                    .Append(promotionShadowReason).Append(',')
                    .Append(probationStreak).Append(',')
                    .Append(probationStatus).Append(',')
                    .Append(componentSize).Append(',').Append(frontier.LocallyComplete ? 1 : 0).Append(',')
                    .Append(fullDirectionalSupport ? 1 : 0).Append(',')
                    .Append(normalConflict ? 1 : 0).Append(',')
                    .Append(distanceConflict ? 1 : 0).Append(',')
                    .Append(normalContributions).Append(',')
                    .Append(alignedNormalCoherence.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                    .Append(rawNormalCoherence.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                    .Append(votes.Count).Append(',').Append(totalVotes).Append(',')
                    .Append(bestPlaneId).Append(',').Append(bestVotes).Append(',').Append(axisCount).Append(',')
                    .Append(planeDistance.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                    .Append(bestPlaneDistanceLimit.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                    .Append(normalDot.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                    .Append(bestPlane >= 0 ? ClassifyAuthoritativePlaneGeometry(planes[bestPlane].Normal) : "none").Append(',')
                    .Append(nearestPlaneId).Append(',')
                    .Append((nearestPlane >= 0 ? nearestPlaneDistance : 0f).ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                    .Append(nearestPlaneDistanceLimit.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                    .Append(nearestPlaneNormalDot.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                    .Append(nearestPlane >= 0 ? ClassifyAuthoritativePlaneGeometry(planes[nearestPlane].Normal) : "none").Append(',')
                    .Append(frontier.CurrentUsableCorners).Append(',')
                    .Append(frontier.CurrentCrossingEdges).Append(',')
                    .Append(frontier.TangentDirections).Append(',')
                    .Append(frontier.TangentSupportedDirections).Append(',')
                    .Append(frontier.TangentMissingDirections).Append(',')
                    .Append(frontier.TangentSurfaceDirections).AppendLine();
            }
        }
        FinalizeAuthoritativeCyanNearPlaneProbation(probationSeen, planeByVertex, planes);
    }

    private void PromoteAuthoritativeCyanNearPlanePatches(
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        IReadOnlyDictionary<Vector3Int, List<AuthoritativeCellComponentKey>> keysByCell,
        IReadOnlyList<Vector3Int> directions,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, int> patchEligible,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, string> patchReason,
        HashSet<AuthoritativeCellComponentKey> adaptivePatchEligible,
        Dictionary<AuthoritativeCellComponentKey, int> planeByVertex,
        Dictionary<AuthoritativeCellComponentKey, int> promotedPatchByVertex)
    {
        if (!enableAuthoritativeCyanNearPlanePatchPromotion || patchEligible == null ||
            patchEligible.Count == 0)
            return;

        HashSet<AuthoritativeCellComponentKey> remaining =
            new HashSet<AuthoritativeCellComponentKey>();
        foreach (KeyValuePair<AuthoritativeCellComponentKey, int> pair in patchEligible)
        {
            if (!planeByVertex.ContainsKey(pair.Key))
                remaining.Add(pair.Key);
        }

        int patchId = 0;
        int radius = Mathf.Clamp(authoritativeCyanNearPlanePatchAnchorRadiusCells, 1, 4);
        int minAnchors = Mathf.Clamp(authoritativeCyanNearPlanePatchMinAnchors, 2, 8);
        int minAxes = Mathf.Clamp(authoritativeCyanNearPlanePatchMinAnchorAxes, 1, 3);
        while (remaining.Count > 0)
        {
            AuthoritativeCellComponentKey start = default;
            foreach (AuthoritativeCellComponentKey candidate in remaining)
            {
                start = candidate;
                break;
            }
            int planeIndex = patchEligible[start];
            string reason = patchReason != null && patchReason.TryGetValue(start, out string startReason)
                ? startReason : "near_plane_no_vote";
            Queue<AuthoritativeCellComponentKey> queue = new Queue<AuthoritativeCellComponentKey>();
            List<AuthoritativeCellComponentKey> members = new List<AuthoritativeCellComponentKey>();
            remaining.Remove(start);
            queue.Enqueue(start);
            while (queue.Count > 0)
            {
                AuthoritativeCellComponentKey current = queue.Dequeue();
                members.Add(current);
                for (int directionIndex = 0; directionIndex < directions.Count; directionIndex++)
                {
                    if (!keysByCell.TryGetValue(current.Cell + directions[directionIndex],
                            out List<AuthoritativeCellComponentKey> neighbours))
                        continue;
                    for (int neighbourIndex = 0; neighbourIndex < neighbours.Count; neighbourIndex++)
                    {
                        AuthoritativeCellComponentKey neighbour = neighbours[neighbourIndex];
                        if (!remaining.Contains(neighbour) ||
                            !patchEligible.TryGetValue(neighbour, out int neighbourPlane) ||
                            neighbourPlane != planeIndex)
                            continue;
                        remaining.Remove(neighbour);
                        queue.Enqueue(neighbour);
                    }
                }
            }

            patchId++;
            LastAuthoritativeCyanNearPlanePatchCandidateCount++;
            HashSet<AuthoritativeCellComponentKey> memberSet =
                new HashSet<AuthoritativeCellComponentKey>(members);
            HashSet<AuthoritativeCellComponentKey> anchors =
                new HashSet<AuthoritativeCellComponentKey>();
            int tangentDirectionMask = 0;
            Vector3 planeNormal = planes[planeIndex].Normal.normalized;
            Vector3 tangentReference = Mathf.Abs(Vector3.Dot(planeNormal, Vector3.up)) < 0.9f
                ? Vector3.up : Vector3.right;
            Vector3 tangentU = Vector3.Cross(planeNormal, tangentReference).normalized;
            Vector3 tangentV = Vector3.Cross(planeNormal, tangentU).normalized;
            Vector3Int minCell = members[0].Cell;
            Vector3Int maxCell = members[0].Cell;
            for (int memberIndex = 0; memberIndex < members.Count; memberIndex++)
            {
                AuthoritativeCellComponentKey member = members[memberIndex];
                minCell = Vector3Int.Min(minCell, member.Cell);
                maxCell = Vector3Int.Max(maxCell, member.Cell);
                for (int z = -radius; z <= radius; z++)
                for (int y = -radius; y <= radius; y++)
                for (int x = -radius; x <= radius; x++)
                {
                    if (x == 0 && y == 0 && z == 0)
                        continue;
                    Vector3Int delta = new Vector3Int(x, y, z);
                    if (!keysByCell.TryGetValue(member.Cell + delta,
                            out List<AuthoritativeCellComponentKey> nearby))
                        continue;
                    for (int nearbyIndex = 0; nearbyIndex < nearby.Count; nearbyIndex++)
                    {
                        AuthoritativeCellComponentKey anchor = nearby[nearbyIndex];
                        if (memberSet.Contains(anchor) ||
                            !planeByVertex.TryGetValue(anchor, out int anchorPlane) ||
                            anchorPlane != planeIndex)
                            continue;
                        anchors.Add(anchor);
                        Vector3 deltaWorld = new Vector3(x, y, z);
                        float alongU = Vector3.Dot(deltaWorld, tangentU);
                        float alongV = Vector3.Dot(deltaWorld, tangentV);
                        if (Mathf.Abs(alongU) >= Mathf.Abs(alongV) && Mathf.Abs(alongU) > 0.001f)
                            tangentDirectionMask |= alongU >= 0f ? 1 : 2;
                        else if (Mathf.Abs(alongV) > 0.001f)
                            tangentDirectionMask |= alongV >= 0f ? 4 : 8;
                    }
                }
            }
            int anchorAxes = ((tangentDirectionMask & 3) != 0 ? 1 : 0) +
                             ((tangentDirectionMask & 12) != 0 ? 1 : 0);
            bool bilateralSupport = (tangentDirectionMask & 3) == 3 ||
                                    (tangentDirectionMask & 12) == 12;
            // Interior cracks often have anchors on opposite sides of one
            // tangent axis. A true view frontier is one-sided. This plane-local
            // test therefore fills the former without extrapolating the latter.
            bool promote = anchors.Count >= minAnchors &&
                           (anchorAxes >= minAxes || bilateralSupport);
            string status = promote ? "promoted" : "blocked_anchor";
            if (promote)
            {
                if (bilateralSupport)
                    LastAuthoritativeCyanNearPlanePatchBilateralAnchorCount++;
                LastAuthoritativeCyanNearPlanePatchPromotedCount++;
                LastAuthoritativeCyanNearPlanePatchPromotedVertexCount += members.Count;
                for (int memberIndex = 0; memberIndex < members.Count; memberIndex++)
                {
                    AuthoritativeCellComponentKey member = members[memberIndex];
                    planeByVertex[member] = planeIndex;
                    promotedPatchByVertex[member] = patchId;
                    if (adaptivePatchEligible != null && adaptivePatchEligible.Contains(member))
                        LastAuthoritativeCyanAdaptiveBandAcceptedCount++;
                }
                LastAuthoritativeCyanPlanePropagationRejectedVotesCount = Mathf.Max(
                    0, LastAuthoritativeCyanPlanePropagationRejectedVotesCount - members.Count);
                LastAuthoritativeCyanPlaneEdgeUnresolvedCount = Mathf.Max(
                    0, LastAuthoritativeCyanPlaneEdgeUnresolvedCount - members.Count);
                LastAuthoritativeCyanPlaneEdgeNoPlaneAnchorCount = Mathf.Max(
                    0, LastAuthoritativeCyanPlaneEdgeNoPlaneAnchorCount - members.Count);
                LastAuthoritativeCyanPlaneEdgeNoAnchorNearPlaneCount = Mathf.Max(
                    0, LastAuthoritativeCyanPlaneEdgeNoAnchorNearPlaneCount - members.Count);
            }
            else
            {
                LastAuthoritativeCyanNearPlanePatchBlockedAnchorCount++;
            }

            if (_authoritativeCyanPlanePatchPromotionRows != null)
            {
                _authoritativeCyanPlanePatchPromotionRows
                    .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
                    .Append(patchId).Append(',').Append(planes[planeIndex].Id).Append(',')
                    .Append(reason).Append(',').Append(status).Append(',').Append(members.Count).Append(',')
                    .Append(anchors.Count).Append(',').Append(anchorAxes).Append(',')
                    .Append(bilateralSupport ? 1 : 0).Append(',')
                    .Append(minCell.x).Append(',').Append(minCell.y).Append(',').Append(minCell.z).Append(',')
                    .Append(maxCell.x).Append(',').Append(maxCell.y).Append(',').Append(maxCell.z).AppendLine();
            }
        }
    }

    private int UpdateAuthoritativeCyanNearPlaneProbation(
        AuthoritativeCellComponentKey key, int planeId, int snapshot)
    {
        AuthoritativeCyanNearPlaneProbation probation;
        if (_authoritativeCyanNearPlaneProbation.TryGetValue(key, out probation) &&
            probation.PlaneId == planeId)
        {
            if (probation.LastSnapshot == snapshot - 1)
                probation.ConsecutiveSnapshots++;
            else if (probation.LastSnapshot != snapshot)
                probation.ConsecutiveSnapshots = 1;
        }
        else
        {
            probation = new AuthoritativeCyanNearPlaneProbation
            {
                PlaneId = planeId,
                ConsecutiveSnapshots = 1,
                LastSnapshot = snapshot
            };
        }
        probation.PlaneId = planeId;
        probation.LastSnapshot = snapshot;
        _authoritativeCyanNearPlaneProbation[key] = probation;
        return probation.ConsecutiveSnapshots;
    }

    private void FinalizeAuthoritativeCyanNearPlaneProbation(
        HashSet<AuthoritativeCellComponentKey> seen,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, int> planeByVertex,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes)
    {
        int requiredSnapshots = Mathf.Clamp(
            authoritativeCyanNearPlaneProbationRequiredSnapshots, 2, 4);
        List<AuthoritativeCellComponentKey> remove = new List<AuthoritativeCellComponentKey>();
        foreach (KeyValuePair<AuthoritativeCellComponentKey, AuthoritativeCyanNearPlaneProbation> pair in
                 _authoritativeCyanNearPlaneProbation)
        {
            if (seen.Contains(pair.Key))
                continue;
            bool hasStandardAssignment = planeByVertex.TryGetValue(pair.Key, out int planeIndex) &&
                planeIndex >= 0 && planeIndex < planes.Count &&
                planes[planeIndex].Id == pair.Value.PlaneId;
            if (!hasStandardAssignment && pair.Value.ConsecutiveSnapshots >= requiredSnapshots)
                LastAuthoritativeCyanNearPlaneProbationRevokedCount++;
            remove.Add(pair.Key);
        }
        for (int i = 0; i < remove.Count; i++)
            _authoritativeCyanNearPlaneProbation.Remove(remove[i]);

        int active = 0;
        foreach (AuthoritativeCyanNearPlaneProbation probation in
                 _authoritativeCyanNearPlaneProbation.Values)
        {
            if (probation.ConsecutiveSnapshots >= requiredSnapshots)
                active++;
        }
        LastAuthoritativeCyanNearPlaneProbationActiveCount = active;
    }

    private AuthoritativeDirectionalFrontierStats AnalyzeAuthoritativeDirectionalFrontier(
        Vector3Int cell,
        Vector3 referenceNormal,
        IReadOnlyDictionary<Vector3Int, List<AuthoritativeCellComponentKey>> keysByCell)
    {
        AuthoritativeDirectionalFrontierStats stats = default;
        GetAuthoritativeCellDirectionalSupport(
            cell, out stats.CurrentUsableCorners, out stats.CurrentCrossingEdges);
        stats.LocallyComplete = stats.CurrentUsableCorners == 8 && stats.CurrentCrossingEdges > 0;
        Vector3Int[] directions =
        {
            Vector3Int.right, Vector3Int.left,
            Vector3Int.up, Vector3Int.down,
            new Vector3Int(0, 0, 1), new Vector3Int(0, 0, -1)
        };
        bool hasReferenceNormal = referenceNormal.sqrMagnitude > 0.000001f;
        if (hasReferenceNormal)
            referenceNormal.Normalize();
        for (int i = 0; i < directions.Length; i++)
        {
            Vector3 direction = new Vector3(directions[i].x, directions[i].y, directions[i].z);
            if (hasReferenceNormal && Mathf.Abs(Vector3.Dot(direction, referenceNormal)) > 0.72f)
                continue;
            stats.TangentDirections++;
            Vector3Int neighbour = cell + directions[i];
            GetAuthoritativeCellDirectionalSupport(neighbour, out int usableCorners, out int crossingEdges);
            if (usableCorners >= 6)
                stats.TangentSupportedDirections++;
            else
                stats.TangentMissingDirections++;
            if (crossingEdges > 0 || (keysByCell != null && keysByCell.ContainsKey(neighbour)))
                stats.TangentSurfaceDirections++;
        }
        // A frontier is directional: the current cell is supported, at least one
        // tangential side remains observed, and another tangential side loses voxel
        // support. An internal crack keeps TSDF support on both sides and is not a
        // view frontier merely because its triangle is missing.
        stats.IsViewFrontier = stats.CurrentUsableCorners >= 6 &&
                               stats.TangentSupportedDirections > 0 &&
                               stats.TangentMissingDirections > 0;
        return stats;
    }

    private void GetAuthoritativeCellDirectionalSupport(
        Vector3Int cell,
        out int usableCorners,
        out int crossingEdges)
    {
        usableCorners = 0;
        crossingEdges = 0;
        if (_authoritativeReadTsdf == null || _authoritativeReadWeights == null ||
            _authoritativeReadEligibility == null ||
            cell.x < 0 || cell.y < 0 || cell.z < 0 ||
            cell.x >= _dimX - 1 || cell.y >= _dimY - 1 || cell.z >= _dimZ - 1)
            return;
        bool[] usable = new bool[8];
        float[] values = new float[8];
        int minWeight = Mathf.Max(1, authoritativeTsdfBlockMinWeight);
        for (int corner = 0; corner < 8; corner++)
        {
            int index = Index(
                cell.x + CornerOffsetX[corner],
                cell.y + CornerOffsetY[corner],
                cell.z + CornerOffsetZ[corner]);
            usable[corner] = AuthoritativeVoxelUsable(index, minWeight);
            values[corner] = _authoritativeReadTsdf[index];
            if (usable[corner])
                usableCorners++;
        }
        for (int edge = 0; edge < 12; edge++)
        {
            int a = CubeEdges[edge, 0];
            int b = CubeEdges[edge, 1];
            if (usable[a] && usable[b] &&
                ((values[a] < 0f && values[b] > 0f) || (values[a] > 0f && values[b] < 0f)))
                crossingEdges++;
        }
    }

    private static void AccumulateAuthoritativeCyanGlobalNormal(
        AuthoritativeCellComponentKey key,
        Vector3 normal,
        Dictionary<AuthoritativeCellComponentKey, Vector3> sums)
    {
        if (sums.TryGetValue(key, out Vector3 sum))
        {
            if (sum.sqrMagnitude > 0.000001f && Vector3.Dot(sum, normal) < 0f)
                normal = -normal;
            sums[key] = sum + normal;
        }
        else
        {
            sums[key] = normal;
        }
    }

    private static void AccumulateAuthoritativeCyanRawNormalEvidence(
        AuthoritativeCellComponentKey key,
        Vector3 normal,
        Dictionary<AuthoritativeCellComponentKey, Vector3> rawSums,
        Dictionary<AuthoritativeCellComponentKey, int> counts)
    {
        rawSums.TryGetValue(key, out Vector3 rawSum);
        rawSums[key] = rawSum + normal;
        counts.TryGetValue(key, out int count);
        counts[key] = count + 1;
    }

    private static string ClassifyAuthoritativePlaneGeometry(Vector3 normal)
    {
        if (normal.sqrMagnitude < 0.5f)
            return "invalid";
        float verticalAlignment = Mathf.Abs(normal.normalized.y);
        if (verticalAlignment >= 0.75f)
            return "floor_ceiling";
        if (verticalAlignment <= 0.35f)
            return "wall";
        return "sloped";
    }

    private List<Vector3> BuildAuthoritativeCyanGloballyProjectedVertices(
        AuthoritativeTsdfBlockMesh block,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, int> planeByVertex,
        HashSet<AuthoritativeCellComponentKey> locked,
        out List<int> moveOverflowVertices)
    {
        List<Vector3> projected = new List<Vector3>(block.Vertices);
        moveOverflowVertices = new List<int>();
        for (int i = 0; i < projected.Count; i++)
        {
            AuthoritativeCellComponentKey key = block.VertexKeys[i];
            if (locked.Contains(key) || !planeByVertex.TryGetValue(key, out int planeIndex))
                continue;
            ScanCoverStablePlaneRegistry.PlaneConstraint plane = planes[planeIndex];
            Vector3 normal = plane.Normal.normalized;
            float signedDistance = Vector3.Dot(normal, projected[i]) + plane.Offset;
            if (Mathf.Abs(signedDistance) > authoritativeCyanPlaneMaxVertexMoveMeters)
            {
                moveOverflowVertices.Add(i);
                continue;
            }
            Vector3 snapped = projected[i] - normal * signedDistance;
            if (!Finite(snapped))
            {
                moveOverflowVertices.Add(i);
                continue;
            }
            projected[i] = snapped;
        }
        return projected;
    }

    private bool LockAuthoritativeCyanVertexOrPromotedPatch(
        AuthoritativeCellComponentKey key,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, int> promotedPatchByVertex,
        HashSet<AuthoritativeCellComponentKey> locked)
    {
        if (promotedPatchByVertex == null ||
            !promotedPatchByVertex.TryGetValue(key, out int patchId))
            return locked.Add(key);

        bool added = false;
        foreach (KeyValuePair<AuthoritativeCellComponentKey, int> pair in promotedPatchByVertex)
        {
            if (pair.Value == patchId && locked.Add(pair.Key))
                added = true;
        }
        if (added)
            LastAuthoritativeCyanNearPlanePatchAtomicLockCount++;
        return added;
    }

    private bool AuthoritativeCyanProjectedTriangleSafe(
        IReadOnlyList<Vector3> original,
        IReadOnlyList<Vector3> projected,
        int a, int b, int c)
    {
        Vector3 oldCross = Vector3.Cross(original[b] - original[a], original[c] - original[a]);
        Vector3 newCross = Vector3.Cross(projected[b] - projected[a], projected[c] - projected[a]);
        float oldArea = oldCross.magnitude;
        float newArea = newCross.magnitude;
        float normalDot = oldArea > 0.000001f && newArea > 0.000001f
            ? Vector3.Dot(oldCross / oldArea, newCross / newArea)
            : -1f;
        return Finite(projected[a]) && Finite(projected[b]) && Finite(projected[c]) &&
               newArea >= oldArea * authoritativeCyanPlaneMinTriangleAreaRatio &&
               normalDot >= authoritativeCyanPlaneMinTriangleNormalDot;
    }

    private bool TryApplyAuthoritativeCyanPlaneConstraint(
        Vector3Int blockKey,
        bool directAttempt,
        AuthoritativeTsdfBlockMesh block)
    {
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes =
            _stablePlaneRegistry.GetMatureConstraints();
        LastAuthoritativeCyanPlaneMatureCount = planes != null ? planes.Count : 0;
        if (!enableAuthoritativeCyanPlaneSnap || block == null || block.Vertices.Count < 3 ||
            block.Triangles.Count < 3 || planes == null || planes.Count == 0)
            return false;

        LastAuthoritativeCyanPlaneCandidateBlockCount++;
        int triangleCount = block.Triangles.Count / 3;
        int[] vertexPlane = new int[block.Vertices.Count];
        bool[] vertexLocked = new bool[block.Vertices.Count];
        for (int i = 0; i < vertexPlane.Length; i++)
            vertexPlane[i] = -2;

        int matchedTriangles = 0;
        int rejectNormal = 0;
        int rejectDistance = 0;
        int rejectExtent = 0;
        int rejectAmbiguity = 0;
        for (int triangle = 0; triangle < triangleCount; triangle++)
        {
            int offset = triangle * 3;
            int a = block.Triangles[offset];
            int b = block.Triangles[offset + 1];
            int c = block.Triangles[offset + 2];
            if (a < 0 || b < 0 || c < 0 ||
                a >= block.Vertices.Count || b >= block.Vertices.Count || c >= block.Vertices.Count)
                continue;
            Vector3 cross = Vector3.Cross(
                block.Vertices[b] - block.Vertices[a],
                block.Vertices[c] - block.Vertices[a]);
            Vector3 centroid = (block.Vertices[a] + block.Vertices[b] + block.Vertices[c]) / 3f;
            string rejectReason = "normal";
            int planeIndex = -1;
            if (cross.sqrMagnitude > 0.0000000001f)
                planeIndex = MatchAuthoritativeCyanPlane(centroid, cross.normalized, planes, out rejectReason);
            if (planeIndex < 0)
            {
                vertexLocked[a] = vertexLocked[b] = vertexLocked[c] = true;
                if (rejectReason == "normal") rejectNormal++;
                else if (rejectReason == "distance") rejectDistance++;
                else if (rejectReason == "extent") rejectExtent++;
                else if (rejectReason == "ambiguous") rejectAmbiguity++;
                continue;
            }

            matchedTriangles++;
            AssignAuthoritativeCyanVertexPlane(a, planeIndex, vertexPlane, vertexLocked);
            AssignAuthoritativeCyanVertexPlane(b, planeIndex, vertexPlane, vertexLocked);
            AssignAuthoritativeCyanVertexPlane(c, planeIndex, vertexPlane, vertexLocked);
        }

        int creaseLocked = 0;
        for (int i = 0; i < vertexLocked.Length; i++)
        {
            if (vertexLocked[i] && vertexPlane[i] >= 0)
                creaseLocked++;
        }

        List<Vector3> projected = new List<Vector3>(block.Vertices);
        int movedVertices = 0;
        float residualBeforeSum = 0f;
        float residualAfterSum = 0f;
        float maxMove = 0f;
        string rollbackReason = "none";
        for (int i = 0; i < projected.Count; i++)
        {
            int planeIndex = vertexPlane[i];
            if (planeIndex < 0 || vertexLocked[i])
                continue;
            ScanCoverStablePlaneRegistry.PlaneConstraint plane = planes[planeIndex];
            Vector3 normal = plane.Normal.normalized;
            float signedDistance = Vector3.Dot(normal, projected[i]) + plane.Offset;
            float move = Mathf.Abs(signedDistance);
            if (move > authoritativeCyanPlaneMaxVertexMoveMeters)
            {
                rollbackReason = "move";
                LastAuthoritativeCyanPlaneRejectedMoveCount++;
                break;
            }
            Vector3 snapped = projected[i] - normal * signedDistance;
            if (!Finite(snapped))
            {
                rollbackReason = "move";
                LastAuthoritativeCyanPlaneRejectedMoveCount++;
                break;
            }
            projected[i] = snapped;
            residualBeforeSum += move;
            residualAfterSum += Mathf.Abs(Vector3.Dot(normal, snapped) + plane.Offset);
            maxMove = Mathf.Max(maxMove, move);
            movedVertices++;
        }

        if (rollbackReason == "none" && movedVertices > 0)
        {
            for (int i = 0; i + 2 < block.Triangles.Count; i += 3)
            {
                int a = block.Triangles[i];
                int b = block.Triangles[i + 1];
                int c = block.Triangles[i + 2];
                Vector3 oldCross = Vector3.Cross(
                    block.Vertices[b] - block.Vertices[a], block.Vertices[c] - block.Vertices[a]);
                Vector3 newCross = Vector3.Cross(
                    projected[b] - projected[a], projected[c] - projected[a]);
                float oldArea = oldCross.magnitude;
                float newArea = newCross.magnitude;
                float normalDot = oldArea > 0.000001f && newArea > 0.000001f
                    ? Vector3.Dot(oldCross / oldArea, newCross / newArea)
                    : -1f;
                if (!Finite(projected[a]) || !Finite(projected[b]) || !Finite(projected[c]) ||
                    newArea < oldArea * authoritativeCyanPlaneMinTriangleAreaRatio ||
                    normalDot < authoritativeCyanPlaneMinTriangleNormalDot)
                {
                    rollbackReason = "geometry";
                    LastAuthoritativeCyanPlaneRejectedGeometryCount++;
                    break;
                }
            }
        }

        bool applied = rollbackReason == "none" && movedVertices > 0;
        if (applied)
        {
            int previousMoved = LastAuthoritativeCyanPlaneMovedVertexCount;
            block.Vertices.Clear();
            block.Vertices.AddRange(projected);
            LastAuthoritativeCyanPlaneAppliedBlockCount++;
            LastAuthoritativeCyanPlaneMovedVertexCount += movedVertices;
            LastAuthoritativeCyanPlaneResidualBeforeMeters =
                (LastAuthoritativeCyanPlaneResidualBeforeMeters * previousMoved + residualBeforeSum) /
                Mathf.Max(1, previousMoved + movedVertices);
            LastAuthoritativeCyanPlaneResidualAfterMeters =
                (LastAuthoritativeCyanPlaneResidualAfterMeters * previousMoved + residualAfterSum) /
                Mathf.Max(1, previousMoved + movedVertices);
            LastAuthoritativeCyanPlaneMaxMoveMeters = Mathf.Max(
                LastAuthoritativeCyanPlaneMaxMoveMeters, maxMove);
        }
        else if (rollbackReason != "none")
        {
            LastAuthoritativeCyanPlaneRollbackBlockCount++;
        }

        LastAuthoritativeCyanPlaneMatchedTriangleCount += matchedTriangles;
        LastAuthoritativeCyanPlaneCreaseLockedVertexCount += creaseLocked;
        LastAuthoritativeCyanPlaneRejectedNormalCount += rejectNormal;
        LastAuthoritativeCyanPlaneRejectedDistanceCount += rejectDistance;
        LastAuthoritativeCyanPlaneRejectedExtentCount += rejectExtent;
        LastAuthoritativeCyanPlaneRejectedAmbiguityCount += rejectAmbiguity;
        AppendAuthoritativeCyanPlaneSnapRow(
            blockKey, directAttempt, block, planes.Count, matchedTriangles, movedVertices,
            creaseLocked, rejectNormal, rejectDistance, rejectExtent, rejectAmbiguity,
            movedVertices > 0 ? residualBeforeSum / movedVertices : 0f,
            movedVertices > 0 ? residualAfterSum / movedVertices : 0f,
            maxMove, applied, rollbackReason);
        return applied;
    }

    private void PrepareAuthoritativeCyanHorizontalExtrema(
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes)
    {
        _authoritativeCyanHorizontalExtremaValid = false;
        _authoritativeCyanLowestHorizontalY = float.PositiveInfinity;
        _authoritativeCyanHighestHorizontalY = float.NegativeInfinity;
        if (planes == null)
            return;
        int minBatches = Mathf.Clamp(authoritativeCyanStructuralMinBatches, 1, 6);
        for (int i = 0; i < planes.Count; i++)
        {
            ScanCoverStablePlaneRegistry.PlaneConstraint plane = planes[i];
            if (plane.Normal.sqrMagnitude < 0.5f || plane.ConsecutiveBatches < minBatches)
                continue;
            float upDot = Mathf.Abs(Vector3.Dot(plane.Normal.normalized, Vector3.up));
            if (upDot < authoritativeCyanStructuralHorizontalMinUpDot)
                continue;
            _authoritativeCyanLowestHorizontalY = Mathf.Min(
                _authoritativeCyanLowestHorizontalY, plane.Center.y);
            _authoritativeCyanHighestHorizontalY = Mathf.Max(
                _authoritativeCyanHighestHorizontalY, plane.Center.y);
            _authoritativeCyanHorizontalExtremaValid = true;
        }
    }

    private bool IsAuthoritativeCyanStructuralPlane(
        ScanCoverStablePlaneRegistry.PlaneConstraint plane,
        out string kind,
        out string rejectReason)
    {
        kind = "none";
        rejectReason = "none";
        if (!enableAuthoritativeCyanStructuralPlaneGate)
        {
            kind = "ungated";
            return true;
        }
        if (plane.Normal.sqrMagnitude < 0.5f)
        {
            rejectReason = "invalid_normal";
            return false;
        }
        if (plane.ConsecutiveBatches < Mathf.Clamp(authoritativeCyanStructuralMinBatches, 1, 6))
        {
            rejectReason = "insufficient_batches";
            return false;
        }

        float upDot = Mathf.Abs(Vector3.Dot(plane.Normal.normalized, Vector3.up));
        if (upDot <= authoritativeCyanStructuralWallMaxUpDot)
        {
            kind = "wall";
            if (plane.Radius < authoritativeCyanStructuralWallMinRadiusMeters)
            {
                rejectReason = "wall_radius";
                return false;
            }
            if (plane.TotalInliers < authoritativeCyanStructuralWallMinInliers)
            {
                rejectReason = "wall_inliers";
                return false;
            }
            return true;
        }

        if (upDot >= authoritativeCyanStructuralHorizontalMinUpDot)
        {
            kind = "horizontal";
            if (!_authoritativeCyanHorizontalExtremaValid)
            {
                rejectReason = "horizontal_no_extrema";
                return false;
            }
            float tolerance = Mathf.Max(0.02f,
                authoritativeCyanStructuralHorizontalExtremeToleranceMeters);
            bool isLowest = Mathf.Abs(plane.Center.y - _authoritativeCyanLowestHorizontalY) <= tolerance;
            bool isHighest = Mathf.Abs(plane.Center.y - _authoritativeCyanHighestHorizontalY) <= tolerance;
            if (!isLowest && !isHighest)
            {
                rejectReason = "horizontal_middle_layer";
                return false;
            }
            // The highest horizontal surface in a partial capture is often a bed or
            // table.  It may only be called a ceiling when a separately established
            // floor is far enough below it to describe a room-scale enclosure.
            if (isLowest)
            {
                kind = "floor";
            }
            else
            {
                float separation = plane.Center.y - _authoritativeCyanLowestHorizontalY;
                if (separation < Mathf.Clamp(
                        authoritativeCyanStructuralMinFloorCeilingSeparationMeters,
                        1.2f, 3.5f))
                {
                    kind = "horizontal_object";
                    rejectReason = "ceiling_floor_separation";
                    return false;
                }
                kind = "ceiling";
            }
            if (plane.Radius < authoritativeCyanStructuralHorizontalMinRadiusMeters)
            {
                rejectReason = "horizontal_radius";
                return false;
            }
            if (plane.TotalInliers < GetAuthoritativeCyanStructuralMinInliers(plane, kind))
            {
                rejectReason = "horizontal_inliers";
                return false;
            }
            return true;
        }

        kind = "oblique";
        rejectReason = "oblique_nonstructural";
        return false;
    }

    private static bool IsAuthoritativeCyanCoverageOnlyStructuralReject(string rejectReason)
    {
        return rejectReason == "horizontal_radius" ||
               rejectReason == "horizontal_inliers" ||
               rejectReason == "wall_radius" ||
               rejectReason == "wall_inliers";
    }

    private bool IsAuthoritativeCyanLocalStructuralCandidate(
        ScanCoverStablePlaneRegistry.PlaneConstraint plane,
        out bool globallyQualified,
        out string kind,
        out string rejectReason)
    {
        globallyQualified = IsAuthoritativeCyanStructuralPlane(plane, out kind, out rejectReason);
        if (globallyQualified)
            return true;
        return enableAuthoritativeCyanLocalStructuralQualification &&
               IsAuthoritativeCyanCoverageOnlyStructuralReject(rejectReason);
    }

    private static Vector3 CanonicalizeAuthoritativeCyanPlaneNormal(Vector3 normal)
    {
        if (normal.sqrMagnitude < 0.000001f)
            return Vector3.up;
        normal.Normalize();
        Vector3 absolute = new Vector3(Mathf.Abs(normal.x), Mathf.Abs(normal.y), Mathf.Abs(normal.z));
        float dominant = absolute.x;
        float signedDominant = normal.x;
        if (absolute.y > dominant)
        {
            dominant = absolute.y;
            signedDominant = normal.y;
        }
        if (absolute.z > dominant)
            signedDominant = normal.z;
        return signedDominant < 0f ? -normal : normal;
    }

    private void GetAuthoritativeCyanPlaneTileCoordinates(
        ScanCoverStablePlaneRegistry.PlaneConstraint plane,
        Vector3 point,
        out int tileU,
        out int tileV)
    {
        if (!_authoritativeCyanPlaneSupportFrames.TryGetValue(
                plane.Id, out AuthoritativeCyanPlaneSupportFrame frame))
        {
            Vector3 normal = CanonicalizeAuthoritativeCyanPlaneNormal(plane.Normal);
            Vector3 reference = Mathf.Abs(Vector3.Dot(normal, Vector3.up)) < 0.9f
                ? Vector3.up
                : Vector3.right;
            frame = new AuthoritativeCyanPlaneSupportFrame
            {
                Normal = normal,
                UAxis = Vector3.Cross(reference, normal).normalized
            };
            frame.VAxis = Vector3.Cross(normal, frame.UAxis).normalized;
            _authoritativeCyanPlaneSupportFrames[plane.Id] = frame;
        }
        float tileSize = Mathf.Clamp(authoritativeCyanLocalSupportTileSizeMeters, 0.20f, 0.50f);
        // World-origin UV coordinates keep tile identities stable while the tracked
        // plane center and fitted normal are refined between batches. The axes are
        // frozen per plane_id so a small normal update cannot relabel every tile.
        tileU = Mathf.FloorToInt(Vector3.Dot(point, frame.UAxis) / tileSize);
        tileV = Mathf.FloorToInt(Vector3.Dot(point, frame.VAxis) / tileSize);
    }

    private float GetAuthoritativeCyanDirectSupportCellSize(out int subdivisions)
    {
        float tileSize = Mathf.Clamp(
            authoritativeCyanLocalSupportTileSizeMeters, 0.20f, 0.50f);
        subdivisions = Mathf.Clamp(
            Mathf.CeilToInt(tileSize / Mathf.Clamp(
                planeSupportDiagnosticCellSizeMeters, 0.05f, 0.20f)), 1, 10);
        return tileSize / subdivisions;
    }

    private void GetAuthoritativeCyanPlaneDirectCellCoordinates(
        ScanCoverStablePlaneRegistry.PlaneConstraint plane,
        Vector3 point,
        out int cellU,
        out int cellV)
    {
        AuthoritativeCyanPlaneSupportFrame frame = GetOrCreatePlaneSupportFrame(plane);
        float cellSize = GetAuthoritativeCyanDirectSupportCellSize(out _);
        cellU = Mathf.FloorToInt(Vector3.Dot(point, frame.UAxis) / cellSize);
        cellV = Mathf.FloorToInt(Vector3.Dot(point, frame.VAxis) / cellSize);
    }

    private bool TryGetAuthoritativeCyanDirectSupport(
        int planeId,
        int cellU,
        int cellV,
        out AuthoritativeCyanPlaneDirectSupportCell direct)
    {
        AuthoritativeCyanPlaneTileKey key = new AuthoritativeCyanPlaneTileKey
        {
            PlaneId = planeId,
            U = cellU,
            V = cellV
        };
        if (!_authoritativeCyanPlaneDirectSupportCells.TryGetValue(key, out direct) ||
            direct == null)
            return false;
        int minSamples = Mathf.Clamp(authoritativeCyanDirectCellMinSamplesPerBatch, 1, 16);
        int retainMissing = Mathf.Clamp(authoritativeCyanDirectCellRetainMissingBatches, 0, 6);
        bool currentEvidence = direct.LastObservedSnapshot == LastAuthoritativeReadSnapshotSequence &&
                               direct.LastSampleCount >= minSamples;
        bool retainedEvidence = direct.TotalSamples >= minSamples &&
                                direct.MissingBatches <= retainMissing;
        return currentEvidence || retainedEvidence;
    }

    private bool HasAuthoritativeCyanDirectSupportAtPoint(
        ScanCoverStablePlaneRegistry.PlaneConstraint plane,
        Vector3 point)
    {
        GetAuthoritativeCyanPlaneDirectCellCoordinates(
            plane, point, out int cellU, out int cellV);
        return TryGetAuthoritativeCyanDirectSupport(
            plane.Id, cellU, cellV, out _);
    }

    private bool IsAuthoritativeCyanPointLocallyQualified(
        ScanCoverStablePlaneRegistry.PlaneConstraint plane,
        Vector3 point,
        out AuthoritativeCyanLocalSupportState state)
    {
        state = AuthoritativeCyanLocalSupportState.Candidate;
        if (!enableAuthoritativeCyanLocalStructuralQualification)
            return false;
        if (authoritativeCyanLocalSupportRequireDirectCellEvidence &&
            !HasAuthoritativeCyanDirectSupportAtPoint(plane, point))
            return false;
        GetAuthoritativeCyanPlaneTileCoordinates(plane, point, out int tileU, out int tileV);
        // Direct 10 cm evidence is the spatial authority.  Neighbouring 30 cm tiles
        // may no longer lend their qualification across an occluder boundary.
        int radius = authoritativeCyanLocalSupportRequireDirectCellEvidence
            ? 0 : Mathf.Clamp(authoritativeCyanLocalSupportNeighborTileRadius, 0, 2);
        for (int v = -radius; v <= radius; v++)
        for (int u = -radius; u <= radius; u++)
        {
            AuthoritativeCyanPlaneTileKey key = new AuthoritativeCyanPlaneTileKey
            {
                PlaneId = plane.Id,
                U = tileU + u,
                V = tileV + v
            };
            if (!_authoritativeCyanPlaneSupportTiles.TryGetValue(
                    key, out AuthoritativeCyanPlaneSupportTile tile) ||
                tile.State == AuthoritativeCyanLocalSupportState.Candidate)
                continue;
            state = tile.State;
            return true;
        }
        return false;
    }

    private bool IsAuthoritativeCyanPlaneQualifiedAtPoint(
        ScanCoverStablePlaneRegistry.PlaneConstraint plane,
        Vector3 point,
        out string kind,
        out AuthoritativeCyanLocalSupportState state)
    {
        if (IsAuthoritativeCyanStructuralPlane(plane, out kind, out _))
        {
            state = AuthoritativeCyanLocalSupportState.GlobalQualified;
            return true;
        }
        if (!IsAuthoritativeCyanLocalStructuralCandidate(
                plane, out _, out kind, out _))
        {
            state = AuthoritativeCyanLocalSupportState.Candidate;
            return false;
        }
        return IsAuthoritativeCyanPointLocallyQualified(plane, point, out state);
    }

    private void UpdateAuthoritativeCyanLocalStructuralSupport(
        IReadOnlyList<Vector3> samplePoints,
        IReadOnlyList<Vector3> sampleNormals,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes)
    {
        // A capture can rebuild more than once. Preserve capture-wide totals;
        // otherwise a later empty rebuild overwrites valid support evidence with 0.
        LastAuthoritativeCyanLocalSupportInputSampleCount +=
            samplePoints != null ? samplePoints.Count : 0;
        if (!enableAuthoritativeCyanLocalStructuralQualification ||
            samplePoints == null || sampleNormals == null || planes == null)
        {
            RecountAuthoritativeCyanLocalSupportTiles();
            return;
        }

        PrepareAuthoritativeCyanHorizontalExtrema(planes);
        Dictionary<AuthoritativeCyanPlaneTileKey, AuthoritativeCyanPlaneSupportAccumulator> accumulators =
            new Dictionary<AuthoritativeCyanPlaneTileKey, AuthoritativeCyanPlaneSupportAccumulator>();
        Dictionary<AuthoritativeCyanPlaneTileKey, int> directCellAccumulators =
            new Dictionary<AuthoritativeCyanPlaneTileKey, int>();
        int sampleCount = Mathf.Min(samplePoints.Count, sampleNormals.Count);
        float minNormalDot = Mathf.Clamp(authoritativeCyanLocalSupportMinNormalDot, 0.5f, 1f);
        for (int sampleIndex = 0; sampleIndex < sampleCount; sampleIndex++)
        {
            Vector3 point = samplePoints[sampleIndex];
            Vector3 sampleNormal = sampleNormals[sampleIndex];
            if (!Finite(point) || !Finite(sampleNormal) || sampleNormal.sqrMagnitude < 0.0001f)
                continue;
            sampleNormal.Normalize();
            int bestPlane = -1;
            float bestScore = float.PositiveInfinity;
            float bestResidual = 0f;
            float bestNormalDot = 0f;
            bool bestGlobal = false;
            string bestKind = "none";
            string bestReject = "none";
            for (int planeIndex = 0; planeIndex < planes.Count; planeIndex++)
            {
                ScanCoverStablePlaneRegistry.PlaneConstraint plane = planes[planeIndex];
                if (!IsAuthoritativeCyanLocalStructuralCandidate(
                        plane, out bool globallyQualified, out string kind, out string reject) ||
                    plane.Normal.sqrMagnitude < 0.5f)
                    continue;
                Vector3 normal = plane.Normal.normalized;
                float normalDot = Mathf.Abs(Vector3.Dot(sampleNormal, normal));
                if (normalDot < minNormalDot)
                    continue;
                float residual = Mathf.Abs(Vector3.Dot(normal, point) + plane.Offset);
                float distanceLimit = Mathf.Min(0.08f, Mathf.Max(
                    authoritativeCyanLocalSupportSampleDistanceMeters,
                    Mathf.Max(0f, plane.Rms) * 3f));
                if (residual > distanceLimit)
                    continue;
                Vector3 fromCenter = point - plane.Center;
                Vector3 tangent = fromCenter - normal * Vector3.Dot(normal, fromCenter);
                if (tangent.magnitude > plane.Radius + stablePlaneShadowPatchPaddingMeters)
                    continue;
                float score = residual / Mathf.Max(0.001f, distanceLimit) + (1f - normalDot);
                if (score >= bestScore)
                    continue;
                bestScore = score;
                bestPlane = planeIndex;
                bestResidual = residual;
                bestNormalDot = normalDot;
                bestGlobal = globallyQualified;
                bestKind = kind;
                bestReject = reject;
            }
            if (bestPlane < 0)
                continue;
            ScanCoverStablePlaneRegistry.PlaneConstraint matchedPlane = planes[bestPlane];
            GetAuthoritativeCyanPlaneTileCoordinates(matchedPlane, point, out int tileU, out int tileV);
            AuthoritativeCyanPlaneTileKey key = new AuthoritativeCyanPlaneTileKey
            {
                PlaneId = matchedPlane.Id,
                U = tileU,
                V = tileV
            };
            if (!accumulators.TryGetValue(key, out AuthoritativeCyanPlaneSupportAccumulator accumulator))
            {
                accumulator = new AuthoritativeCyanPlaneSupportAccumulator
                {
                    PlaneKind = bestKind,
                    GlobalReject = bestReject,
                    GloballyQualified = bestGlobal
                };
                accumulators[key] = accumulator;
            }
            accumulator.Samples++;
            accumulator.SquaredResidualSum += bestResidual * bestResidual;
            accumulator.NormalDotSum += bestNormalDot;
            GetAuthoritativeCyanPlaneDirectCellCoordinates(
                matchedPlane, point, out int directU, out int directV);
            AuthoritativeCyanPlaneTileKey directKey = new AuthoritativeCyanPlaneTileKey
            {
                PlaneId = matchedPlane.Id,
                U = directU,
                V = directV
            };
            directCellAccumulators.TryGetValue(directKey, out int directSamples);
            directCellAccumulators[directKey] = directSamples + 1;
            LastAuthoritativeCyanLocalSupportMatchedSampleCount++;
        }

        int snapshot = LastAuthoritativeReadSnapshotSequence;
        HashSet<int> livePlaneIds = new HashSet<int>();
        Dictionary<int, bool> globallyQualifiedPlanes = new Dictionary<int, bool>();
        Dictionary<int, bool> locallyEligiblePlanes = new Dictionary<int, bool>();
        for (int i = 0; i < planes.Count; i++)
        {
            livePlaneIds.Add(planes[i].Id);
            globallyQualifiedPlanes[planes[i].Id] =
                IsAuthoritativeCyanStructuralPlane(planes[i], out _, out _);
            locallyEligiblePlanes[planes[i].Id] =
                IsAuthoritativeCyanLocalStructuralCandidate(
                    planes[i], out _, out _, out _);
        }

        int configuredPromoteBatches = Mathf.Clamp(
            authoritativeCyanLocalSupportPromoteBatches, 2, 4);
        // Every plane passed to this method is already mature in the persistent
        // registry.  Requiring a second, independent tile probation duplicates the
        // same delay and made a valid floor appear only in round three.
        int promoteBatches = authoritativeCyanLocalSupportAvoidDoubleProbation
            ? 1 : configuredPromoteBatches;
        int retainMissing = Mathf.Clamp(authoritativeCyanLocalSupportRetainMissingBatches, 1, 6);
        int minSamples = Mathf.Clamp(authoritativeCyanLocalSupportMinSamplesPerBatch, 4, 128);
        float maxRms = Mathf.Clamp(authoritativeCyanLocalSupportMaxRmsMeters, 0.005f, 0.05f);
        foreach (KeyValuePair<AuthoritativeCyanPlaneTileKey, AuthoritativeCyanPlaneSupportAccumulator> pair in accumulators)
        {
            if (!_authoritativeCyanPlaneSupportTiles.TryGetValue(
                    pair.Key, out AuthoritativeCyanPlaneSupportTile tile))
            {
                tile = new AuthoritativeCyanPlaneSupportTile();
                _authoritativeCyanPlaneSupportTiles[pair.Key] = tile;
            }
            AuthoritativeCyanLocalSupportState previous = tile.State;
            AuthoritativeCyanPlaneSupportAccumulator accumulator = pair.Value;
            float rms = accumulator.Samples > 0
                ? Mathf.Sqrt(accumulator.SquaredResidualSum / accumulator.Samples)
                : 0f;
            bool batchQualified = accumulator.Samples >= minSamples && rms <= maxRms;
            tile.LastSnapshot = snapshot;
            tile.LastSampleCount = accumulator.Samples;
            tile.TotalSamples += accumulator.Samples;
            tile.LastRms = rms;
            tile.LastMeanNormalDot = accumulator.Samples > 0
                ? accumulator.NormalDotSum / accumulator.Samples : 0f;
            tile.PlaneKind = accumulator.PlaneKind;
            tile.GlobalReject = accumulator.GlobalReject;
            if (accumulator.GloballyQualified)
            {
                tile.State = AuthoritativeCyanLocalSupportState.GlobalQualified;
                tile.ConsecutiveQualifiedBatches = Mathf.Max(
                    tile.ConsecutiveQualifiedBatches + (batchQualified ? 1 : 0), promoteBatches);
                tile.MissingBatches = 0;
            }
            else if (batchQualified)
            {
                tile.ConsecutiveQualifiedBatches++;
                tile.MissingBatches = 0;
                tile.State = tile.ConsecutiveQualifiedBatches >= promoteBatches
                    ? AuthoritativeCyanLocalSupportState.LocalQualified
                    : AuthoritativeCyanLocalSupportState.Candidate;
            }
            else
            {
                tile.ConsecutiveQualifiedBatches = 0;
                tile.MissingBatches++;
                if (tile.MissingBatches > retainMissing)
                    tile.State = AuthoritativeCyanLocalSupportState.Candidate;
            }
            if (previous == AuthoritativeCyanLocalSupportState.Candidate &&
                tile.State != AuthoritativeCyanLocalSupportState.Candidate)
                LastAuthoritativeCyanLocalSupportPromotedTileCount++;
            else if (previous != AuthoritativeCyanLocalSupportState.Candidate &&
                     tile.State == AuthoritativeCyanLocalSupportState.Candidate)
                LastAuthoritativeCyanLocalSupportDemotedTileCount++;
            AppendAuthoritativeCyanLocalSupportRow(pair.Key, tile, previous);
        }

        List<AuthoritativeCyanPlaneTileKey> remove = new List<AuthoritativeCyanPlaneTileKey>();
        foreach (KeyValuePair<AuthoritativeCyanPlaneTileKey, AuthoritativeCyanPlaneSupportTile> pair in
                 _authoritativeCyanPlaneSupportTiles)
        {
            if (accumulators.ContainsKey(pair.Key))
                continue;
            AuthoritativeCyanPlaneSupportTile tile = pair.Value;
            AuthoritativeCyanLocalSupportState previous = tile.State;
            tile.LastSampleCount = 0;
            tile.LastRms = 0f;
            tile.LastMeanNormalDot = 0f;
            tile.MissingBatches++;
            bool planeGlobal = globallyQualifiedPlanes.TryGetValue(pair.Key.PlaneId, out bool global) && global;
            bool planeLocalEligible = locallyEligiblePlanes.TryGetValue(
                pair.Key.PlaneId, out bool localEligible) && localEligible;
            if (!planeLocalEligible)
            {
                // A semantic rejection (for example a bed formerly mistaken for a
                // ceiling) must revoke stale local tiles immediately.
                tile.State = AuthoritativeCyanLocalSupportState.Candidate;
                tile.ConsecutiveQualifiedBatches = 0;
            }
            else if (planeGlobal)
                tile.State = AuthoritativeCyanLocalSupportState.GlobalQualified;
            else if (tile.State == AuthoritativeCyanLocalSupportState.GlobalQualified)
                tile.State = tile.ConsecutiveQualifiedBatches >= promoteBatches
                    ? AuthoritativeCyanLocalSupportState.LocalQualified
                    : AuthoritativeCyanLocalSupportState.Candidate;
            if (tile.MissingBatches > retainMissing)
                tile.State = AuthoritativeCyanLocalSupportState.Candidate;
            if (previous != AuthoritativeCyanLocalSupportState.Candidate &&
                tile.State == AuthoritativeCyanLocalSupportState.Candidate)
                LastAuthoritativeCyanLocalSupportDemotedTileCount++;
            AppendAuthoritativeCyanLocalSupportRow(pair.Key, tile, previous);
            if (!livePlaneIds.Contains(pair.Key.PlaneId) ||
                (tile.State == AuthoritativeCyanLocalSupportState.Candidate &&
                 tile.MissingBatches > retainMissing + 6))
                remove.Add(pair.Key);
        }
        for (int i = 0; i < remove.Count; i++)
        {
            int planeId = remove[i].PlaneId;
            _authoritativeCyanPlaneSupportTiles.Remove(remove[i]);
            bool planeStillHasTiles = false;
            foreach (AuthoritativeCyanPlaneTileKey remaining in _authoritativeCyanPlaneSupportTiles.Keys)
            {
                if (remaining.PlaneId != planeId)
                    continue;
                planeStillHasTiles = true;
                break;
            }
            if (!planeStillHasTiles && !livePlaneIds.Contains(planeId))
                _authoritativeCyanPlaneSupportFrames.Remove(planeId);
        }
        UpdateAuthoritativeCyanDirectSupportCells(
            directCellAccumulators, livePlaneIds, snapshot);
        RecountAuthoritativeCyanLocalSupportTiles();
    }

    private void UpdateAuthoritativeCyanDirectSupportCells(
        Dictionary<AuthoritativeCyanPlaneTileKey, int> accumulators,
        HashSet<int> livePlaneIds,
        int snapshot)
    {
        if (accumulators == null)
            return;
        foreach (KeyValuePair<AuthoritativeCyanPlaneTileKey, int> pair in accumulators)
        {
            if (!_authoritativeCyanPlaneDirectSupportCells.TryGetValue(
                    pair.Key, out AuthoritativeCyanPlaneDirectSupportCell direct))
            {
                direct = new AuthoritativeCyanPlaneDirectSupportCell();
                _authoritativeCyanPlaneDirectSupportCells[pair.Key] = direct;
            }
            int samples = Mathf.Max(0, pair.Value);
            if (direct.LastEvaluatedSnapshot != snapshot)
            {
                direct.ConsecutiveObservedBatches = direct.LastObservedSnapshot == snapshot - 1
                    ? direct.ConsecutiveObservedBatches + 1 : 1;
                direct.TotalSamples += samples;
                direct.LastSampleCount = samples;
            }
            else
            {
                direct.TotalSamples += Mathf.Max(0, samples - direct.LastSampleCount);
                direct.LastSampleCount = Mathf.Max(direct.LastSampleCount, samples);
            }
            direct.LastObservedSnapshot = snapshot;
            direct.LastEvaluatedSnapshot = snapshot;
            direct.MissingBatches = 0;
        }

        List<AuthoritativeCyanPlaneTileKey> remove =
            new List<AuthoritativeCyanPlaneTileKey>();
        int retain = Mathf.Clamp(authoritativeCyanDirectCellRetainMissingBatches, 0, 6);
        foreach (KeyValuePair<AuthoritativeCyanPlaneTileKey, AuthoritativeCyanPlaneDirectSupportCell>
                 pair in _authoritativeCyanPlaneDirectSupportCells)
        {
            AuthoritativeCyanPlaneDirectSupportCell direct = pair.Value;
            if (direct.LastEvaluatedSnapshot == snapshot)
                continue;
            direct.LastEvaluatedSnapshot = snapshot;
            direct.LastSampleCount = 0;
            direct.MissingBatches++;
            direct.ConsecutiveObservedBatches = 0;
            if (!livePlaneIds.Contains(pair.Key.PlaneId) || direct.MissingBatches > retain)
                remove.Add(pair.Key);
        }
        for (int i = 0; i < remove.Count; i++)
            _authoritativeCyanPlaneDirectSupportCells.Remove(remove[i]);
    }

    private void AppendAuthoritativeCyanLocalSupportRow(
        AuthoritativeCyanPlaneTileKey key,
        AuthoritativeCyanPlaneSupportTile tile,
        AuthoritativeCyanLocalSupportState previous)
    {
        if (_authoritativeCyanLocalSupportRows == null || tile == null)
            return;
        string transition = previous == tile.State
            ? "hold"
            : previous.ToString() + "_to_" + tile.State.ToString();
        _authoritativeCyanLocalSupportRows
            .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
            .Append(key.PlaneId).Append(',').Append(key.U).Append(',').Append(key.V).Append(',')
            .Append(tile.State).Append(',').Append(transition).Append(',')
            .Append(tile.PlaneKind).Append(',').Append(tile.GlobalReject).Append(',')
            .Append(tile.LastSampleCount).Append(',')
            .Append(tile.LastRms.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(tile.LastMeanNormalDot.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(tile.ConsecutiveQualifiedBatches).Append(',').Append(tile.MissingBatches).Append(',')
            .Append(tile.TotalSamples).Append(',')
            .Append(authoritativeCyanLocalSupportTileSizeMeters.ToString("F3", CultureInfo.InvariantCulture))
            .AppendLine();
    }

    private void RecountAuthoritativeCyanLocalSupportTiles()
    {
        LastAuthoritativeCyanLocalSupportCandidateTileCount = 0;
        LastAuthoritativeCyanLocalSupportQualifiedTileCount = 0;
        LastAuthoritativeCyanLocalSupportGlobalTileCount = 0;
        foreach (AuthoritativeCyanPlaneSupportTile tile in _authoritativeCyanPlaneSupportTiles.Values)
        {
            if (tile.State == AuthoritativeCyanLocalSupportState.GlobalQualified)
                LastAuthoritativeCyanLocalSupportGlobalTileCount++;
            else if (tile.State == AuthoritativeCyanLocalSupportState.LocalQualified)
                LastAuthoritativeCyanLocalSupportQualifiedTileCount++;
            else
                LastAuthoritativeCyanLocalSupportCandidateTileCount++;
        }
    }

    private bool HasAuthoritativeCyanLocallyQualifiedTiles(int planeId)
    {
        foreach (KeyValuePair<AuthoritativeCyanPlaneTileKey, AuthoritativeCyanPlaneSupportTile> pair in
                 _authoritativeCyanPlaneSupportTiles)
        {
            if (pair.Key.PlaneId == planeId &&
                pair.Value.State != AuthoritativeCyanLocalSupportState.Candidate)
                return true;
        }
        return false;
    }

    private int GetAuthoritativeCyanStructuralMinInliers(
        ScanCoverStablePlaneRegistry.PlaneConstraint plane,
        string kind)
    {
        if (kind == "wall")
            return Mathf.Max(stablePlaneShadowMinInliers,
                authoritativeCyanStructuralWallMinInliers);
        if (kind == "floor" || kind == "ceiling" || kind == "horizontal_extreme" ||
            kind == "horizontal")
        {
            // Plane extraction already enforces a minimum inlier count. Structural
            // qualification should not impose a harsher orientation-specific sample
            // quota than walls; horizontal extrema and their larger radius gate are
            // the semantic protection against beds, tables, and other middle layers.
            int stableEvidenceFloor = Mathf.Max(stablePlaneShadowMinInliers * 4,
                authoritativeCyanStructuralWallMinInliers);
            return Mathf.Min(authoritativeCyanStructuralHorizontalMinInliers,
                stableEvidenceFloor);
        }
        return Mathf.Max(stablePlaneShadowMinInliers,
            authoritativeCyanStructuralWallMinInliers);
    }

    private float GetAuthoritativeCyanPlaneDistanceLimit(
        ScanCoverStablePlaneRegistry.PlaneConstraint plane,
        bool edgePropagation)
    {
        float baseDistance = edgePropagation
            ? authoritativeCyanPlaneEdgePropagationMaxDistanceMeters
            : authoritativeCyanPlaneMaxDistanceMeters;
        if (!enableAuthoritativeCyanAdaptivePlaneDistance)
            return baseDistance;
        float cap = Mathf.Max(baseDistance, authoritativeCyanAdaptivePlaneMaxDistanceMeters);
        return Mathf.Min(cap, baseDistance +
            Mathf.Max(0f, plane.Rms) * Mathf.Max(0f, authoritativeCyanAdaptivePlaneRmsScale));
    }

    private void AuditAuthoritativeCyanStructuralPlanes(
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes)
    {
        if (planes == null)
            return;
        PrepareAuthoritativeCyanHorizontalExtrema(planes);
        for (int i = 0; i < planes.Count; i++)
        {
            ScanCoverStablePlaneRegistry.PlaneConstraint plane = planes[i];
            bool qualified = IsAuthoritativeCyanStructuralPlane(plane, out string kind, out string reject);
            if (qualified)
            {
                LastAuthoritativeCyanStructuralPlaneQualifiedCount++;
                if (kind == "wall") LastAuthoritativeCyanStructuralWallPlaneCount++;
                else if (kind == "floor" || kind == "ceiling" || kind == "horizontal_extreme")
                    LastAuthoritativeCyanStructuralHorizontalPlaneCount++;
            }
            else
            {
                LastAuthoritativeCyanStructuralPlaneRejectedCount++;
            }
            if (_authoritativeCyanStructuralPlaneRows == null)
                continue;
            float upDot = plane.Normal.sqrMagnitude > 0.5f
                ? Mathf.Abs(Vector3.Dot(plane.Normal.normalized, Vector3.up)) : 0f;
            _authoritativeCyanStructuralPlaneRows
                .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
                .Append(plane.Id).Append(',').Append(qualified ? 1 : 0).Append(',')
                .Append(kind).Append(',').Append(reject).Append(',')
                .Append(plane.Center.y.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append((_authoritativeCyanHorizontalExtremaValid ? _authoritativeCyanLowestHorizontalY : 0f)
                    .ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append((_authoritativeCyanHorizontalExtremaValid ? _authoritativeCyanHighestHorizontalY : 0f)
                    .ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append((_authoritativeCyanHorizontalExtremaValid
                        ? plane.Center.y - _authoritativeCyanLowestHorizontalY : 0f)
                    .ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(authoritativeCyanStructuralMinFloorCeilingSeparationMeters
                    .ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(upDot.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(plane.Radius.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(plane.Rms.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(plane.TotalInliers).Append(',')
                .Append(GetAuthoritativeCyanStructuralMinInliers(plane, kind)).Append(',')
                .Append(plane.ConsecutiveBatches).Append(',')
                .Append(authoritativeCyanPlaneMaxDistanceMeters.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(GetAuthoritativeCyanPlaneDistanceLimit(plane, false).ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(authoritativeCyanPlaneEdgePropagationMaxDistanceMeters.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(GetAuthoritativeCyanPlaneDistanceLimit(plane, true).ToString("F6", CultureInfo.InvariantCulture)).AppendLine();
        }
    }

    private int MatchAuthoritativeCyanPlane(
        Vector3 point,
        Vector3 surfaceNormal,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        out string rejectReason)
    {
        rejectReason = "normal";
        int bestIndex = -1;
        int secondIndex = -1;
        float bestScore = float.PositiveInfinity;
        float secondScore = float.PositiveInfinity;
        bool passedNormal = false;
        bool passedDistance = false;
        bool sawNonStructuralNormalMatch = false;
        bool bestUsedAdaptiveBand = false;
        bool bestUsedLocalSupport = false;
        for (int i = 0; i < planes.Count; i++)
        {
            ScanCoverStablePlaneRegistry.PlaneConstraint plane = planes[i];
            if (plane.Normal.sqrMagnitude < 0.5f)
                continue;
            Vector3 normal = plane.Normal.normalized;
            float normalDot = Mathf.Abs(Vector3.Dot(surfaceNormal, normal));
            if (normalDot < authoritativeCyanPlaneMinNormalDot)
                continue;
            bool locallyEligible = IsAuthoritativeCyanLocalStructuralCandidate(
                plane, out bool globallyQualified, out _, out _);
            bool locallyQualified = locallyEligible && !globallyQualified &&
                IsAuthoritativeCyanPointLocallyQualified(plane, point, out _);
            if (!globallyQualified && !locallyQualified)
            {
                sawNonStructuralNormalMatch = true;
                LastAuthoritativeCyanAdaptiveBandRejectedNonStructuralCount++;
                continue;
            }
            passedNormal = true;
            float distance = Mathf.Abs(Vector3.Dot(normal, point) + plane.Offset);
            float distanceLimit = GetAuthoritativeCyanPlaneDistanceLimit(plane, false);
            bool usesAdaptiveBand = distance > authoritativeCyanPlaneMaxDistanceMeters &&
                                    distance <= distanceLimit;
            if (usesAdaptiveBand)
                LastAuthoritativeCyanAdaptiveBandCandidateCount++;
            if (distance > distanceLimit)
                continue;
            passedDistance = true;
            Vector3 fromCenter = point - plane.Center;
            Vector3 tangent = fromCenter - normal * Vector3.Dot(normal, fromCenter);
            if (tangent.magnitude > plane.Radius + authoritativeCyanPlaneTangentialPaddingMeters)
                continue;
            float score = distance / Mathf.Max(0.001f, distanceLimit) +
                          (1f - normalDot);
            if (score < bestScore)
            {
                secondScore = bestScore;
                secondIndex = bestIndex;
                bestScore = score;
                bestIndex = i;
                bestUsedAdaptiveBand = usesAdaptiveBand;
                bestUsedLocalSupport = locallyQualified;
            }
            else if (score < secondScore)
            {
                secondScore = score;
                secondIndex = i;
            }
        }
        if (bestIndex < 0)
        {
            if (!passedNormal && sawNonStructuralNormalMatch)
            {
                rejectReason = "nonstructural";
                LastAuthoritativeCyanNonStructuralProtectedSampleCount++;
            }
            else
            {
                rejectReason = !passedNormal ? "normal" : !passedDistance ? "distance" : "extent";
            }
            return -1;
        }
        if (secondIndex >= 0 && secondScore - bestScore < authoritativeCyanPlaneAmbiguityScoreMargin &&
            Mathf.Abs(Vector3.Dot(planes[bestIndex].Normal.normalized, planes[secondIndex].Normal.normalized)) < 0.95f)
        {
            rejectReason = "ambiguous";
            return -1;
        }
        if (bestUsedAdaptiveBand)
            LastAuthoritativeCyanAdaptiveBandAcceptedCount++;
        if (bestUsedLocalSupport)
            LastAuthoritativeCyanLocalSupportMatchedTriangleCount++;
        rejectReason = "none";
        return bestIndex;
    }

    private static void AssignAuthoritativeCyanVertexPlane(
        int vertex,
        int plane,
        int[] vertexPlanes,
        bool[] vertexLocked)
    {
        if (vertexPlanes[vertex] == -2)
            vertexPlanes[vertex] = plane;
        else if (vertexPlanes[vertex] != plane)
            vertexLocked[vertex] = true;
    }

    private void AppendAuthoritativeCyanPlaneSnapRow(
        Vector3Int key, bool direct, AuthoritativeTsdfBlockMesh block, int maturePlanes,
        int matchedTriangles, int movedVertices, int creaseLockedVertices,
        int rejectNormal, int rejectDistance, int rejectExtent, int rejectAmbiguity,
        float residualBefore, float residualAfter, float maxMove, bool applied, string rollbackReason)
    {
        if (_authoritativeCyanPlaneSnapRows == null)
            return;
        _authoritativeCyanPlaneSnapRows
            .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
            .Append(key.x).Append(',').Append(key.y).Append(',').Append(key.z).Append(',')
            .Append(direct ? 1 : 0).Append(',').Append(maturePlanes).Append(',')
            .Append(block.Triangles.Count / 3).Append(',').Append(matchedTriangles).Append(',')
            .Append(movedVertices).Append(',').Append(creaseLockedVertices).Append(',')
            .Append(rejectNormal).Append(',').Append(rejectDistance).Append(',')
            .Append(rejectExtent).Append(',').Append(rejectAmbiguity).Append(',')
            .Append(residualBefore.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(residualAfter.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(maxMove.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(applied ? 1 : 0).Append(',').Append(rollbackReason == "none" ? 0 : 1).Append(',')
            .Append(rollbackReason).AppendLine();
    }

    private void ResetAuthoritativeCyanContinuityDiagnostics()
    {
        LastAuthoritativeCyanWeldedVertexCount = 0;
        LastAuthoritativeCyanGlobalComponentCount = 0;
        LastAuthoritativeCyanLargestComponentRatio = 0f;
        LastAuthoritativeCyanGlobalBoundaryEdgeCount = 0;
        LastAuthoritativeCyanGlobalNonManifoldEdgeCount = 0;
        LastAuthoritativeCyanCrossBlockSeamEdgeCount = 0;
        LastAuthoritativeCyanInternalCrackEdgeCount = 0;
        LastAuthoritativeCyanSparseFrontierEdgeCount = 0;
        LastAuthoritativeCyanOuterFrontierEdgeCount = 0;
        LastAuthoritativeCyanClosedHoleLoopCount = 0;
        LastAuthoritativeCyanClosedHolePerimeterMeters = 0f;
        _authoritativeCyanContinuityRows = new StringBuilder(4096);
        _authoritativeCyanContinuityRows.AppendLine(
            "snapshot,class,edge_ax,edge_ay,edge_az,edge_bx,edge_by,edge_bz,length_m,owner_block_x,owner_block_y,owner_block_z,source_edge_x,source_edge_y,source_edge_z,source_axis,locally_complete,loop_id,closed_loop");
    }

    private void AuditAuthoritativeCyanContinuity(List<Vector3Int> orderedBlocks, int blockVoxels)
    {
        ResetAuthoritativeCyanContinuityDiagnostics();
        if (orderedBlocks == null || orderedBlocks.Count == 0)
        {
            RebuildAuthoritativeCyanCrackOverlay(null, null);
            return;
        }

        float weldTolerance = Mathf.Clamp(authoritativeCyanWeldToleranceMeters, 0.0002f, 0.02f);
        float seamTolerance = Mathf.Max(
            weldTolerance * 2f,
            Mathf.Clamp(authoritativeCyanSeamMatchToleranceMeters, 0.001f, 0.05f));
        List<Vector3> weldedVertices = new List<Vector3>(4096);
        List<int> weldedParent = new List<int>(4096);
        Dictionary<Vector3Int, List<int>> weldBuckets = new Dictionary<Vector3Int, List<int>>(4096);
        Dictionary<ulong, AuthoritativeCyanEdgeRecord> edges =
            new Dictionary<ulong, AuthoritativeCyanEdgeRecord>(8192);
        List<AuthoritativeCyanTriangleAudit> triangles = new List<AuthoritativeCyanTriangleAudit>(4096);
        HashSet<Vector3Int> blockSet = new HashSet<Vector3Int>(orderedBlocks);

        for (int blockIndex = 0; blockIndex < orderedBlocks.Count; blockIndex++)
        {
            Vector3Int owner = orderedBlocks[blockIndex];
            if (!_authoritativeTsdfBlocks.TryGetValue(owner, out AuthoritativeTsdfBlockMesh block))
                continue;
            int[] localToGlobal = new int[block.Vertices.Count];
            for (int vertex = 0; vertex < block.Vertices.Count; vertex++)
            {
                localToGlobal[vertex] = FindOrAddAuthoritativeCyanWeldedVertex(
                    block.Vertices[vertex], weldTolerance,
                    weldedVertices, weldedParent, weldBuckets);
            }
            for (int index = 0, triangleIndex = 0; index + 2 < block.Triangles.Count; index += 3, triangleIndex++)
            {
                int localA = block.Triangles[index];
                int localB = block.Triangles[index + 1];
                int localC = block.Triangles[index + 2];
                if (localA < 0 || localB < 0 || localC < 0 ||
                    localA >= localToGlobal.Length || localB >= localToGlobal.Length || localC >= localToGlobal.Length)
                    continue;
                int a = localToGlobal[localA];
                int b = localToGlobal[localB];
                int c = localToGlobal[localC];
                if (a == b || b == c || c == a)
                    continue;
                float area = Vector3.Cross(
                    weldedVertices[b] - weldedVertices[a],
                    weldedVertices[c] - weldedVertices[a]).magnitude * 0.5f;
                if (area <= 0.00000001f)
                    continue;
                UnionAuthoritativeCyanVertices(weldedParent, a, b);
                UnionAuthoritativeCyanVertices(weldedParent, b, c);
                triangles.Add(new AuthoritativeCyanTriangleAudit { Vertex = a, Area = area });
                AuthoritativeTriangleSource source = triangleIndex < block.TriangleSources.Count
                    ? block.TriangleSources[triangleIndex]
                    : new AuthoritativeTriangleSource { EdgeStart = Vector3Int.zero, Axis = -1 };
                AddAuthoritativeCyanAuditEdge(edges, a, b, owner, source);
                AddAuthoritativeCyanAuditEdge(edges, b, c, owner, source);
                AddAuthoritativeCyanAuditEdge(edges, c, a, owner, source);
            }
        }

        LastAuthoritativeCyanWeldedVertexCount = weldedVertices.Count;
        Dictionary<int, float> componentAreas = new Dictionary<int, float>();
        float totalArea = 0f;
        float largestArea = 0f;
        for (int i = 0; i < triangles.Count; i++)
        {
            int root = FindAuthoritativeCyanVertexRoot(weldedParent, triangles[i].Vertex);
            if (root < 0)
                continue;
            componentAreas.TryGetValue(root, out float area);
            area += triangles[i].Area;
            componentAreas[root] = area;
            totalArea += triangles[i].Area;
            largestArea = Mathf.Max(largestArea, area);
        }
        LastAuthoritativeCyanGlobalComponentCount = componentAreas.Count;
        LastAuthoritativeCyanLargestComponentRatio = totalArea > 0.000001f
            ? largestArea / totalArea
            : 0f;

        List<AuthoritativeCyanEdgeRecord> boundaries = new List<AuthoritativeCyanEdgeRecord>();
        foreach (AuthoritativeCyanEdgeRecord edge in edges.Values)
        {
            if (edge.Incidence == 1)
                boundaries.Add(edge);
            else if (edge.Incidence > 2)
                LastAuthoritativeCyanGlobalNonManifoldEdgeCount++;
        }
        LastAuthoritativeCyanGlobalBoundaryEdgeCount = boundaries.Count;
        MatchAuthoritativeCyanCrossBlockSeams(boundaries, weldedVertices, seamTolerance);

        float patchSize = Mathf.Max(0.001f, blockVoxels * voxelSizeMeters);
        for (int i = 0; i < boundaries.Count; i++)
        {
            AuthoritativeCyanEdgeRecord edge = boundaries[i];
            Vector3 midpoint = (weldedVertices[edge.A] + weldedVertices[edge.B]) * 0.5f;
            edge.LocallyComplete = IsAuthoritativeCyanLocallyComplete(midpoint);
            if (edge.Classification == AuthoritativeCyanBoundaryClass.CrossBlockSeam)
            {
                LastAuthoritativeCyanCrossBlockSeamEdgeCount++;
            }
            else if (edge.LocallyComplete)
            {
                edge.Classification = AuthoritativeCyanBoundaryClass.InternalCrack;
                LastAuthoritativeCyanInternalCrackEdgeCount++;
            }
            else if (IsAuthoritativeCyanOuterFrontier(midpoint, edge.OwnerBlock, patchSize, blockSet))
            {
                edge.Classification = AuthoritativeCyanBoundaryClass.OuterFrontier;
                LastAuthoritativeCyanOuterFrontierEdgeCount++;
            }
            else
            {
                edge.Classification = AuthoritativeCyanBoundaryClass.SparseFrontier;
                LastAuthoritativeCyanSparseFrontierEdgeCount++;
            }
        }

        ClassifyAuthoritativeCyanBoundaryLoops(boundaries, weldedVertices);
        BuildAuthoritativeCyanContinuityRows(boundaries, weldedVertices);
        BuildAuthoritativeCyanCrackOverlay(boundaries, weldedVertices);
    }

    private static Vector3Int AuthoritativeCyanBucket(Vector3 point, float size)
    {
        float inverse = 1f / Mathf.Max(0.000001f, size);
        return new Vector3Int(
            Mathf.FloorToInt(point.x * inverse),
            Mathf.FloorToInt(point.y * inverse),
            Mathf.FloorToInt(point.z * inverse));
    }

    private static int FindOrAddAuthoritativeCyanWeldedVertex(
        Vector3 point,
        float tolerance,
        List<Vector3> vertices,
        List<int> parent,
        Dictionary<Vector3Int, List<int>> buckets)
    {
        Vector3Int bucket = AuthoritativeCyanBucket(point, tolerance);
        float toleranceSquared = tolerance * tolerance;
        for (int z = -1; z <= 1; z++)
        for (int y = -1; y <= 1; y++)
        for (int x = -1; x <= 1; x++)
        {
            Vector3Int neighbour = bucket + new Vector3Int(x, y, z);
            if (!buckets.TryGetValue(neighbour, out List<int> candidates))
                continue;
            for (int i = 0; i < candidates.Count; i++)
            {
                int candidate = candidates[i];
                if ((vertices[candidate] - point).sqrMagnitude <= toleranceSquared)
                    return candidate;
            }
        }
        int index = vertices.Count;
        vertices.Add(point);
        parent.Add(index);
        if (!buckets.TryGetValue(bucket, out List<int> list))
        {
            list = new List<int>(2);
            buckets[bucket] = list;
        }
        list.Add(index);
        return index;
    }

    private static int FindAuthoritativeCyanVertexRoot(List<int> parent, int vertex)
    {
        if (vertex < 0 || vertex >= parent.Count)
            return -1;
        int root = vertex;
        while (parent[root] != root)
            root = parent[root];
        while (parent[vertex] != vertex)
        {
            int next = parent[vertex];
            parent[vertex] = root;
            vertex = next;
        }
        return root;
    }

    private static void UnionAuthoritativeCyanVertices(List<int> parent, int a, int b)
    {
        int rootA = FindAuthoritativeCyanVertexRoot(parent, a);
        int rootB = FindAuthoritativeCyanVertexRoot(parent, b);
        if (rootA >= 0 && rootB >= 0 && rootA != rootB)
            parent[rootB] = rootA;
    }

    private static void AddAuthoritativeCyanAuditEdge(
        Dictionary<ulong, AuthoritativeCyanEdgeRecord> edges,
        int a,
        int b,
        Vector3Int owner,
        AuthoritativeTriangleSource source)
    {
        uint min = (uint)Mathf.Min(a, b);
        uint max = (uint)Mathf.Max(a, b);
        ulong key = ((ulong)min << 32) | max;
        if (!edges.TryGetValue(key, out AuthoritativeCyanEdgeRecord edge))
        {
            edge = new AuthoritativeCyanEdgeRecord
            {
                A = (int)min,
                B = (int)max,
                OwnerBlock = owner,
                Source = source
            };
            edges[key] = edge;
        }
        edge.Incidence++;
    }

    private static void MatchAuthoritativeCyanCrossBlockSeams(
        List<AuthoritativeCyanEdgeRecord> boundaries,
        List<Vector3> vertices,
        float tolerance)
    {
        Dictionary<Vector3Int, List<int>> buckets = new Dictionary<Vector3Int, List<int>>();
        float toleranceSquared = tolerance * tolerance;
        for (int edgeIndex = 0; edgeIndex < boundaries.Count; edgeIndex++)
        {
            AuthoritativeCyanEdgeRecord edge = boundaries[edgeIndex];
            Vector3 midpoint = (vertices[edge.A] + vertices[edge.B]) * 0.5f;
            Vector3Int bucket = AuthoritativeCyanBucket(midpoint, tolerance);
            for (int z = -1; z <= 1; z++)
            for (int y = -1; y <= 1; y++)
            for (int x = -1; x <= 1; x++)
            {
                if (!buckets.TryGetValue(bucket + new Vector3Int(x, y, z), out List<int> candidates))
                    continue;
                for (int i = 0; i < candidates.Count; i++)
                {
                    AuthoritativeCyanEdgeRecord other = boundaries[candidates[i]];
                    if (other.OwnerBlock == edge.OwnerBlock)
                        continue;
                    bool sameDirection =
                        (vertices[edge.A] - vertices[other.A]).sqrMagnitude <= toleranceSquared &&
                        (vertices[edge.B] - vertices[other.B]).sqrMagnitude <= toleranceSquared;
                    bool reverseDirection =
                        (vertices[edge.A] - vertices[other.B]).sqrMagnitude <= toleranceSquared &&
                        (vertices[edge.B] - vertices[other.A]).sqrMagnitude <= toleranceSquared;
                    if (!sameDirection && !reverseDirection)
                        continue;
                    edge.Classification = AuthoritativeCyanBoundaryClass.CrossBlockSeam;
                    other.Classification = AuthoritativeCyanBoundaryClass.CrossBlockSeam;
                }
            }
            if (!buckets.TryGetValue(bucket, out List<int> list))
            {
                list = new List<int>(2);
                buckets[bucket] = list;
            }
            list.Add(edgeIndex);
        }
    }

    private bool IsAuthoritativeCyanLocallyComplete(Vector3 point)
    {
        if (_authoritativeReadTsdf == null || _authoritativeReadWeights == null ||
            _authoritativeReadEligibility == null)
            return false;
        Vector3 local = (point - _volumeOriginWorld) / Mathf.Max(0.0001f, voxelSizeMeters);
        int baseX = Mathf.FloorToInt(local.x);
        int baseY = Mathf.FloorToInt(local.y);
        int baseZ = Mathf.FloorToInt(local.z);
        int minWeight = Mathf.Max(1, authoritativeTsdfBlockMinWeight);
        for (int z = baseZ - 1; z <= baseZ + 1; z++)
        for (int y = baseY - 1; y <= baseY + 1; y++)
        for (int x = baseX - 1; x <= baseX + 1; x++)
        {
            if (x < 0 || y < 0 || z < 0 || x >= _dimX - 1 || y >= _dimY - 1 || z >= _dimZ - 1)
                continue;
            bool allUsable = true;
            bool positive = false;
            bool negative = false;
            for (int corner = 0; corner < 8; corner++)
            {
                int index = Index(
                    x + CornerOffsetX[corner],
                    y + CornerOffsetY[corner],
                    z + CornerOffsetZ[corner]);
                if (!AuthoritativeVoxelUsable(index, minWeight))
                {
                    allUsable = false;
                    break;
                }
                positive |= _authoritativeReadTsdf[index] > 0f;
                negative |= _authoritativeReadTsdf[index] < 0f;
            }
            if (allUsable && positive && negative)
                return true;
        }
        return false;
    }

    private bool IsAuthoritativeCyanOuterFrontier(
        Vector3 point,
        Vector3Int owner,
        float patchSize,
        HashSet<Vector3Int> blocks)
    {
        Vector3 blockOrigin = _volumeOriginWorld + new Vector3(
            owner.x * patchSize,
            owner.y * patchSize,
            owner.z * patchSize);
        Vector3 local = point - blockOrigin;
        float margin = Mathf.Max(voxelSizeMeters * 1.5f, authoritativeCyanSeamMatchToleranceMeters * 2f);
        return
            (local.x <= margin && !blocks.Contains(owner + Vector3Int.left)) ||
            (local.x >= patchSize - margin && !blocks.Contains(owner + Vector3Int.right)) ||
            (local.y <= margin && !blocks.Contains(owner + Vector3Int.down)) ||
            (local.y >= patchSize - margin && !blocks.Contains(owner + Vector3Int.up)) ||
            (local.z <= margin && !blocks.Contains(owner + new Vector3Int(0, 0, -1))) ||
            (local.z >= patchSize - margin && !blocks.Contains(owner + new Vector3Int(0, 0, 1)));
    }

    private void ClassifyAuthoritativeCyanBoundaryLoops(
        List<AuthoritativeCyanEdgeRecord> boundaries,
        List<Vector3> vertices)
    {
        Dictionary<int, List<int>> vertexEdges = new Dictionary<int, List<int>>();
        for (int edgeIndex = 0; edgeIndex < boundaries.Count; edgeIndex++)
        {
            AddAuthoritativeCyanVertexEdge(vertexEdges, boundaries[edgeIndex].A, edgeIndex);
            AddAuthoritativeCyanVertexEdge(vertexEdges, boundaries[edgeIndex].B, edgeIndex);
        }
        bool[] visited = new bool[boundaries.Count];
        int loopId = 0;
        for (int start = 0; start < boundaries.Count; start++)
        {
            if (visited[start])
                continue;
            Queue<int> queue = new Queue<int>();
            List<int> component = new List<int>();
            Dictionary<int, int> degree = new Dictionary<int, int>();
            queue.Enqueue(start);
            visited[start] = true;
            while (queue.Count > 0)
            {
                int edgeIndex = queue.Dequeue();
                component.Add(edgeIndex);
                AuthoritativeCyanEdgeRecord edge = boundaries[edgeIndex];
                degree.TryGetValue(edge.A, out int degreeA);
                degree.TryGetValue(edge.B, out int degreeB);
                degree[edge.A] = degreeA + 1;
                degree[edge.B] = degreeB + 1;
                EnqueueAuthoritativeCyanAdjacentEdges(edge.A, vertexEdges, visited, queue);
                EnqueueAuthoritativeCyanAdjacentEdges(edge.B, vertexEdges, visited, queue);
            }
            bool closed = component.Count >= 3;
            foreach (int value in degree.Values)
                closed &= value == 2;
            bool allOuter = true;
            float perimeter = 0f;
            for (int i = 0; i < component.Count; i++)
            {
                AuthoritativeCyanEdgeRecord edge = boundaries[component[i]];
                edge.LoopId = loopId;
                edge.ClosedLoop = closed;
                allOuter &= edge.Classification == AuthoritativeCyanBoundaryClass.OuterFrontier;
                perimeter += Vector3.Distance(vertices[edge.A], vertices[edge.B]);
            }
            if (closed && !allOuter)
            {
                LastAuthoritativeCyanClosedHoleLoopCount++;
                LastAuthoritativeCyanClosedHolePerimeterMeters += perimeter;
            }
            loopId++;
        }
    }

    private static void AddAuthoritativeCyanVertexEdge(
        Dictionary<int, List<int>> vertexEdges, int vertex, int edge)
    {
        if (!vertexEdges.TryGetValue(vertex, out List<int> list))
        {
            list = new List<int>(2);
            vertexEdges[vertex] = list;
        }
        list.Add(edge);
    }

    private static void EnqueueAuthoritativeCyanAdjacentEdges(
        int vertex,
        Dictionary<int, List<int>> vertexEdges,
        bool[] visited,
        Queue<int> queue)
    {
        if (!vertexEdges.TryGetValue(vertex, out List<int> adjacent))
            return;
        for (int i = 0; i < adjacent.Count; i++)
        {
            int edge = adjacent[i];
            if (visited[edge])
                continue;
            visited[edge] = true;
            queue.Enqueue(edge);
        }
    }

    private void BuildAuthoritativeCyanContinuityRows(
        List<AuthoritativeCyanEdgeRecord> boundaries,
        List<Vector3> vertices)
    {
        if (_authoritativeCyanContinuityRows == null)
            return;
        for (int i = 0; i < boundaries.Count; i++)
        {
            AuthoritativeCyanEdgeRecord edge = boundaries[i];
            Vector3 a = vertices[edge.A];
            Vector3 b = vertices[edge.B];
            _authoritativeCyanContinuityRows
                .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
                .Append(edge.Classification).Append(',')
                .Append(a.x.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(a.y.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(a.z.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(b.x.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(b.y.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(b.z.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(Vector3.Distance(a, b).ToString("F6", CultureInfo.InvariantCulture)).Append(',')
                .Append(edge.OwnerBlock.x).Append(',').Append(edge.OwnerBlock.y).Append(',').Append(edge.OwnerBlock.z).Append(',')
                .Append(edge.Source.EdgeStart.x).Append(',').Append(edge.Source.EdgeStart.y).Append(',').Append(edge.Source.EdgeStart.z).Append(',')
                .Append(edge.Source.Axis).Append(',')
                .Append(edge.LocallyComplete ? 1 : 0).Append(',')
                .Append(edge.LoopId).Append(',')
                .Append(edge.ClosedLoop ? 1 : 0).AppendLine();
        }
    }

    private void BuildAuthoritativeCyanCrackOverlay(
        List<AuthoritativeCyanEdgeRecord> boundaries,
        List<Vector3> weldedVertices)
    {
        if (!showAuthoritativeCyanCrackOverlay || boundaries == null || weldedVertices == null)
        {
            RebuildAuthoritativeCyanCrackOverlay(null, null);
            return;
        }
        List<Vector3> vertices = new List<Vector3>(boundaries.Count * 2);
        List<int>[] indices = { new List<int>(), new List<int>(), new List<int>(), new List<int>() };
        float displayOffset = showAuthoritativeCyanOnly && enableAuthoritativeTsdfBlockExtraction
            ? 0f
            : Mathf.Clamp(incrementalPatchShadowDisplayOffsetMeters, 0f, 0.03f);
        Vector3 cameraPosition = Camera.main != null ? Camera.main.transform.position : GetCameraPosition();
        for (int i = 0; i < boundaries.Count; i++)
        {
            AuthoritativeCyanEdgeRecord edge = boundaries[i];
            int submesh = edge.Classification == AuthoritativeCyanBoundaryClass.OuterFrontier ? 0 :
                          edge.Classification == AuthoritativeCyanBoundaryClass.SparseFrontier ? 1 :
                          edge.Classification == AuthoritativeCyanBoundaryClass.CrossBlockSeam ? 2 : 3;
            int baseVertex = vertices.Count;
            Vector3 a = weldedVertices[edge.A];
            Vector3 b = weldedVertices[edge.B];
            if (displayOffset > 0f)
            {
                Vector3 towardA = cameraPosition - a;
                Vector3 towardB = cameraPosition - b;
                if (towardA.sqrMagnitude > 0.000001f) a += towardA.normalized * displayOffset;
                if (towardB.sqrMagnitude > 0.000001f) b += towardB.normalized * displayOffset;
            }
            vertices.Add(a);
            vertices.Add(b);
            indices[submesh].Add(baseVertex);
            indices[submesh].Add(baseVertex + 1);
        }
        RebuildAuthoritativeCyanCrackOverlay(vertices, indices);
    }

    private void RebuildAuthoritativeCyanCrackOverlay(List<Vector3> vertices, List<int>[] indices)
    {
        EnsureAuthoritativeCyanCrackObjects();
        if (_authoritativeCyanCrackMesh == null || _authoritativeCyanCrackObject == null)
            return;
        _authoritativeCyanCrackMesh.Clear();
        if (vertices == null || indices == null || vertices.Count < 2)
        {
            _authoritativeCyanCrackObject.SetActive(false);
            return;
        }
        _authoritativeCyanCrackMesh.indexFormat = vertices.Count > 65535 ? IndexFormat.UInt32 : IndexFormat.UInt16;
        _authoritativeCyanCrackMesh.SetVertices(vertices);
        _authoritativeCyanCrackMesh.subMeshCount = 4;
        for (int submesh = 0; submesh < 4; submesh++)
            _authoritativeCyanCrackMesh.SetIndices(indices[submesh], MeshTopology.Lines, submesh, false);
        _authoritativeCyanCrackMesh.RecalculateBounds();
        _authoritativeCyanCrackObject.SetActive(
            showAuthoritativeCyanCrackOverlay && !showPlaneReferenceAndZeroCrossShadowOnly);
    }

    private bool TryExtractAuthoritativeTsdfBlock(
        Vector3Int blockKey,
        int blockVoxels,
        out AuthoritativeTsdfBlockMesh block,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, int> planeOwnership = null,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes = null,
        PlaneConstrainedZeroCrossShadowStats shadowStats = null,
        bool recordExtractionDiagnostics = true)
    {
        block = new AuthoritativeTsdfBlockMesh();
        Dictionary<AuthoritativeCellComponentKey, int> cellVertices =
            new Dictionary<AuthoritativeCellComponentKey, int>(256);
        Dictionary<Vector3Int, AuthoritativeCellTopology> cellTopologies =
            new Dictionary<Vector3Int, AuthoritativeCellTopology>(256);
        HashSet<Vector3Int> splitCells = new HashSet<Vector3Int>();
        float patchSize = Mathf.Max(0.001f, blockVoxels * voxelSizeMeters);
        int minX = Mathf.Max(0, blockKey.x * blockVoxels - 1);
        int minY = Mathf.Max(0, blockKey.y * blockVoxels - 1);
        int minZ = Mathf.Max(0, blockKey.z * blockVoxels - 1);
        int maxX = Mathf.Min(_dimX - 1, (blockKey.x + 1) * blockVoxels + 1);
        int maxY = Mathf.Min(_dimY - 1, (blockKey.y + 1) * blockVoxels + 1);
        int maxZ = Mathf.Min(_dimZ - 1, (blockKey.z + 1) * blockVoxels + 1);

        for (int z = minZ; z <= maxZ; z++)
        for (int y = minY; y <= maxY; y++)
        for (int x = minX; x <= maxX; x++)
        {
            int index = Index(x, y, z);
            if (x + 1 < _dimX &&
                TryGetAuthoritativeZeroCrossing(x, y, z, x + 1, y, z, index, Index(x + 1, y, z), out Vector3 xCross) &&
                AuthoritativeBlockKey(xCross, patchSize) == blockKey)
            {
                AddAuthoritativeBlockQuad(
                    new Vector3Int(x, y, z), new Vector3Int(x, y - 1, z),
                    new Vector3Int(x, y - 1, z - 1), new Vector3Int(x, y, z - 1),
                    StableQuadTsdfWinding(new StableQuadKey { X = x, Y = y, Z = z, Axis = 0 }),
                    new Vector3Int(x, y, z), 0,
                    cellVertices, cellTopologies, splitCells, block,
                    planeOwnership, planes, shadowStats, recordExtractionDiagnostics);
            }
            if (y + 1 < _dimY &&
                TryGetAuthoritativeZeroCrossing(x, y, z, x, y + 1, z, index, Index(x, y + 1, z), out Vector3 yCross) &&
                AuthoritativeBlockKey(yCross, patchSize) == blockKey)
            {
                AddAuthoritativeBlockQuad(
                    new Vector3Int(x, y, z), new Vector3Int(x, y, z - 1),
                    new Vector3Int(x - 1, y, z - 1), new Vector3Int(x - 1, y, z),
                    StableQuadTsdfWinding(new StableQuadKey { X = x, Y = y, Z = z, Axis = 1 }),
                    new Vector3Int(x, y, z), 1,
                    cellVertices, cellTopologies, splitCells, block,
                    planeOwnership, planes, shadowStats, recordExtractionDiagnostics);
            }
            if (z + 1 < _dimZ &&
                TryGetAuthoritativeZeroCrossing(x, y, z, x, y, z + 1, index, Index(x, y, z + 1), out Vector3 zCross) &&
                AuthoritativeBlockKey(zCross, patchSize) == blockKey)
            {
                AddAuthoritativeBlockQuad(
                    new Vector3Int(x, y, z), new Vector3Int(x - 1, y, z),
                    new Vector3Int(x - 1, y - 1, z), new Vector3Int(x, y - 1, z),
                    StableQuadTsdfWinding(new StableQuadKey { X = x, Y = y, Z = z, Axis = 2 }),
                    new Vector3Int(x, y, z), 2,
                    cellVertices, cellTopologies, splitCells, block,
                    planeOwnership, planes, shadowStats, recordExtractionDiagnostics);
            }
        }
        block.MultiComponentCells = splitCells.Count;
        foreach (AuthoritativeCellComponentKey key in cellVertices.Keys)
        {
            if (splitCells.Contains(key.Cell))
                block.SplitVertices++;
        }
        return block.Triangles.Count >= 3;
    }

    private void AddAuthoritativeBlockQuad(
        Vector3Int ca, Vector3Int cb, Vector3Int cc, Vector3Int cd,
        int winding,
        Vector3Int edgeStart,
        int edgeAxis,
        Dictionary<AuthoritativeCellComponentKey, int> cellVertices,
        Dictionary<Vector3Int, AuthoritativeCellTopology> cellTopologies,
        HashSet<Vector3Int> splitCells,
        AuthoritativeTsdfBlockMesh block,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, int> planeOwnership,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        PlaneConstrainedZeroCrossShadowStats shadowStats,
        bool recordExtractionDiagnostics)
    {
        int a = GetAuthoritativeBlockCellVertex(ca, edgeStart, edgeAxis, cellVertices, cellTopologies, splitCells, block,
            planeOwnership, planes, shadowStats, recordExtractionDiagnostics);
        int b = GetAuthoritativeBlockCellVertex(cb, edgeStart, edgeAxis, cellVertices, cellTopologies, splitCells, block,
            planeOwnership, planes, shadowStats, recordExtractionDiagnostics);
        int c = GetAuthoritativeBlockCellVertex(cc, edgeStart, edgeAxis, cellVertices, cellTopologies, splitCells, block,
            planeOwnership, planes, shadowStats, recordExtractionDiagnostics);
        int d = GetAuthoritativeBlockCellVertex(cd, edgeStart, edgeAxis, cellVertices, cellTopologies, splitCells, block,
            planeOwnership, planes, shadowStats, recordExtractionDiagnostics);
        if (a < 0 || b < 0 || c < 0 || d < 0 ||
            !(recordExtractionDiagnostics
                ? PassExtractedQuadGeometryGate(a, b, c, d, block.Vertices)
                : EvaluateExtractedQuadGeometry(a, b, c, d, block.Vertices) ==
                  ExtractedQuadGeometryRejectReason.None))
            return;
        if (winding >= 0)
        {
            block.Triangles.Add(a); block.Triangles.Add(b); block.Triangles.Add(c);
            block.Triangles.Add(a); block.Triangles.Add(c); block.Triangles.Add(d);
        }
        else
        {
            block.Triangles.Add(c); block.Triangles.Add(b); block.Triangles.Add(a);
            block.Triangles.Add(d); block.Triangles.Add(c); block.Triangles.Add(a);
        }
        AuthoritativeTriangleSource source = new AuthoritativeTriangleSource
        {
            EdgeStart = edgeStart,
            Axis = edgeAxis
        };
        block.TriangleSources.Add(source);
        block.TriangleSources.Add(source);
    }

    private int GetAuthoritativeBlockCellVertex(
        Vector3Int cell,
        Vector3Int edgeStart,
        int edgeAxis,
        Dictionary<AuthoritativeCellComponentKey, int> cellVertices,
        Dictionary<Vector3Int, AuthoritativeCellTopology> cellTopologies,
        HashSet<Vector3Int> splitCells,
        AuthoritativeTsdfBlockMesh block,
        IReadOnlyDictionary<AuthoritativeCellComponentKey, int> planeOwnership,
        IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> planes,
        PlaneConstrainedZeroCrossShadowStats shadowStats,
        bool recordExtractionDiagnostics)
    {
        if (cell.x < 0 || cell.y < 0 || cell.z < 0 ||
            cell.x >= _dimX - 1 || cell.y >= _dimY - 1 || cell.z >= _dimZ - 1)
            return -1;
        if (!cellTopologies.TryGetValue(cell, out AuthoritativeCellTopology topology))
        {
            topology = BuildAuthoritativeCellTopology(cell, recordExtractionDiagnostics);
            cellTopologies[cell] = topology;
            if (topology.ComponentCount > 1)
                splitCells.Add(cell);
        }
        int localEdge = FindAuthoritativeLocalCubeEdge(cell, edgeStart, edgeAxis);
        if (localEdge < 0 || topology.EdgeComponents[localEdge] < 0)
            return -1;
        AuthoritativeCellComponentKey key = new AuthoritativeCellComponentKey
        {
            Cell = cell,
            Component = topology.EdgeComponents[localEdge]
        };
        if (cellVertices.TryGetValue(key, out int existing))
            return existing;
        if (!TryBuildAuthoritativeBlockCellVertex(cell, key.Component, topology, out Vector3 vertex))
        {
            cellVertices[key] = -1;
            return -1;
        }
        if (planeOwnership != null && planes != null &&
            planeOwnership.TryGetValue(key, out int planeIndex) &&
            planeIndex >= 0 && planeIndex < planes.Count)
        {
            // This happens before the quad geometry gate and before any triangle is
            // emitted. Orthogonal plane projection is linear, so projecting the
            // averaged component vertex is exactly equivalent to projecting every
            // contributing zero crossing to the same plane and then averaging them.
            ScanCoverStablePlaneRegistry.PlaneConstraint plane = planes[planeIndex];
            Vector3 normal = plane.Normal.normalized;
            float signedDistance = Vector3.Dot(normal, vertex) + plane.Offset;
            PlaneConstrainedZeroCrossPerPlaneStats planeStats = shadowStats != null
                ? shadowStats.GetPlane(plane.Id)
                : null;
            if (shadowStats != null)
            {
                shadowStats.OwnedVertices++;
                shadowStats.ResidualBeforeSum += Mathf.Abs(signedDistance);
                planeStats.OwnedVertices++;
                planeStats.SignedDistanceSum += signedDistance;
                planeStats.AbsDistanceBeforeSum += Mathf.Abs(signedDistance);
                planeStats.SignedDistances.Add(signedDistance);
                if (signedDistance >= 0f) planeStats.PositiveSideVertices++;
                else planeStats.NegativeSideVertices++;
                planeStats.MaxMove = Mathf.Max(planeStats.MaxMove, Mathf.Abs(signedDistance));
            }
            if (Mathf.Abs(signedDistance) <= authoritativeCyanPlaneMaxVertexMoveMeters)
            {
                Vector3 constrained = vertex - normal * signedDistance;
                if (Finite(constrained))
                {
                    vertex = constrained;
                    if (shadowStats != null)
                    {
                        shadowStats.MovedVertices++;
                        shadowStats.AppliedKeys.Add(key);
                        shadowStats.ResidualAfterSum +=
                            Mathf.Abs(Vector3.Dot(normal, vertex) + plane.Offset);
                        planeStats.MovedVertices++;
                        planeStats.AbsDistanceAfterSum +=
                            Mathf.Abs(Vector3.Dot(normal, vertex) + plane.Offset);
                    }
                }
            }
            else if (shadowStats != null)
            {
                shadowStats.OverflowVertices++;
                shadowStats.OverflowKeys.Add(key);
                shadowStats.ResidualAfterSum += Mathf.Abs(signedDistance);
                planeStats.OverflowVertices++;
                planeStats.AbsDistanceAfterSum += Mathf.Abs(signedDistance);
            }
        }
        int index = block.Vertices.Count;
        block.Vertices.Add(vertex);
        block.VertexKeys.Add(key);
        cellVertices[key] = index;
        return index;
    }

    private bool TryBuildAuthoritativeBlockCellVertex(
        Vector3Int cell,
        int component,
        AuthoritativeCellTopology topology,
        out Vector3 vertex)
    {
        vertex = Vector3.zero;
        Vector3 sum = Vector3.zero;
        int crossings = 0;

        for (int edge = 0; edge < 12; edge++)
        {
            if (topology.EdgeComponents[edge] != component)
                continue;
            int aCorner = CubeEdges[edge, 0];
            int bCorner = CubeEdges[edge, 1];
            int ax = cell.x + CornerOffsetX[aCorner];
            int ay = cell.y + CornerOffsetY[aCorner];
            int az = cell.z + CornerOffsetZ[aCorner];
            int bx = cell.x + CornerOffsetX[bCorner];
            int by = cell.y + CornerOffsetY[bCorner];
            int bz = cell.z + CornerOffsetZ[bCorner];
            if (!TryGetAuthoritativeZeroCrossing(
                    ax, ay, az, bx, by, bz,
                    Index(ax, ay, az), Index(bx, by, bz), out Vector3 crossing))
                continue;
            sum += crossing;
            crossings++;
        }
        if (crossings < 1)
            return false;
        vertex = sum / crossings;
        return Finite(vertex);
    }

    private AuthoritativeCellTopology BuildAuthoritativeCellTopology(
        Vector3Int cell,
        bool recordDiagnostics = true)
    {
        AuthoritativeCellTopology topology = new AuthoritativeCellTopology();
        int[] parent = new int[12];
        bool[] activeEdges = new bool[12];
        float[] cornerValues = new float[8];
        bool allCornersUsable = true;
        int minWeight = Mathf.Max(1, authoritativeTsdfBlockMinWeight);
        for (int corner = 0; corner < 8; corner++)
        {
            int cornerIndex = Index(
                cell.x + CornerOffsetX[corner],
                cell.y + CornerOffsetY[corner],
                cell.z + CornerOffsetZ[corner]);
            if (!AuthoritativeVoxelUsable(cornerIndex, minWeight))
                allCornersUsable = false;
            cornerValues[corner] = _authoritativeReadTsdf[cornerIndex];
        }
        for (int edge = 0; edge < 12; edge++)
        {
            topology.EdgeComponents[edge] = -1;
            parent[edge] = -1;
            int aCorner = CubeEdges[edge, 0];
            int bCorner = CubeEdges[edge, 1];
            int ax = cell.x + CornerOffsetX[aCorner];
            int ay = cell.y + CornerOffsetY[aCorner];
            int az = cell.z + CornerOffsetZ[aCorner];
            int bx = cell.x + CornerOffsetX[bCorner];
            int by = cell.y + CornerOffsetY[bCorner];
            int bz = cell.z + CornerOffsetZ[bCorner];
            if (TryGetAuthoritativeZeroCrossing(
                    ax, ay, az, bx, by, bz,
                    Index(ax, ay, az), Index(bx, by, bz), out _))
            {
                parent[edge] = edge;
                activeEdges[edge] = true;
            }
        }

        // A fully observed cell uses the corrected MC33 topology oracle.  Only its
        // edge-component map is consumed; Surface Nets still owns vertex positions.
        if (allCornersUsable)
        {
            if (ScanCoverMc33Topology.TryBuildComponents(
                    cornerValues, activeEdges, topology.EdgeComponents,
                    out ScanCoverMc33Topology.Result mc33))
            {
                topology.ComponentCount = mc33.ComponentCount;
                if (recordDiagnostics)
                {
                    LastAuthoritativeMc33CellCount++;
                    LastAuthoritativeMc33AmbiguousFaceCount += mc33.AmbiguousFaces;
                    LastAuthoritativeMc33InteriorTestCount += mc33.InteriorTests;
                }
                return topology;
            }
            if (recordDiagnostics)
                LastAuthoritativeMc33FailureCount++;
        }
        else
        {
            // MC33 assumes one valid trilinear scalar cell.  Sparse/partially eligible
            // cells retain the conservative face-only fallback instead of inventing
            // missing corner values.
            if (recordDiagnostics)
                LastAuthoritativeMc33FallbackCellCount++;
        }

        for (int face = 0; face < 6; face++)
        {
            int crossingCount = 0;
            int first = -1;
            int second = -1;
            for (int i = 0; i < 4; i++)
            {
                int edge = CubeFaceEdges[face, i];
                if (parent[edge] < 0)
                    continue;
                if (crossingCount == 0) first = edge;
                else if (crossingCount == 1) second = edge;
                crossingCount++;
            }
            if (crossingCount == 2)
            {
                UnionAuthoritativeCellEdges(parent, first, second);
                continue;
            }
            if (crossingCount != 4)
                continue;

            float[] faceValues = new float[4];
            for (int i = 0; i < 4; i++)
            {
                int corner = CubeFaceCorners[face, i];
                faceValues[i] = cornerValues[corner];
            }
            // True asymptotic decider for the bilinear face.  The former arithmetic
            // centre average can choose the wrong diagonal when magnitudes differ.
            float determinant = faceValues[0] * faceValues[2] -
                                faceValues[1] * faceValues[3];
            bool centerPositive;
            if (Mathf.Abs(determinant) > 0.0000001f)
                centerPositive = faceValues[0] * determinant > 0f;
            else
                centerPositive = faceValues[0] + faceValues[1] +
                                 faceValues[2] + faceValues[3] >= 0f;
            for (int i = 0; i < 4; i++)
            {
                int corner = CubeFaceCorners[face, i];
                float value = cornerValues[corner];
                if ((value > 0f) == centerPositive)
                    continue;
                int previousEdge = CubeFaceEdges[face, (i + 3) & 3];
                int nextEdge = CubeFaceEdges[face, i];
                UnionAuthoritativeCellEdges(parent, previousEdge, nextEdge);
            }
        }

        Dictionary<int, int> components = new Dictionary<int, int>(4);
        for (int edge = 0; edge < 12; edge++)
        {
            if (parent[edge] < 0)
                continue;
            int root = FindAuthoritativeCellEdgeRoot(parent, edge);
            if (!components.TryGetValue(root, out int component))
            {
                component = components.Count;
                components[root] = component;
            }
            topology.EdgeComponents[edge] = component;
        }
        topology.ComponentCount = components.Count;
        return topology;
    }

    private static int FindAuthoritativeCellEdgeRoot(int[] parent, int edge)
    {
        if (edge < 0 || edge >= parent.Length || parent[edge] < 0)
            return -1;
        int root = edge;
        while (parent[root] != root)
            root = parent[root];
        while (parent[edge] != edge)
        {
            int next = parent[edge];
            parent[edge] = root;
            edge = next;
        }
        return root;
    }

    private static void UnionAuthoritativeCellEdges(int[] parent, int a, int b)
    {
        int rootA = FindAuthoritativeCellEdgeRoot(parent, a);
        int rootB = FindAuthoritativeCellEdgeRoot(parent, b);
        if (rootA >= 0 && rootB >= 0 && rootA != rootB)
            parent[rootB] = rootA;
    }

    private static int FindAuthoritativeLocalCubeEdge(Vector3Int cell, Vector3Int edgeStart, int axis)
    {
        for (int edge = 0; edge < 12; edge++)
        {
            int a = CubeEdges[edge, 0];
            int b = CubeEdges[edge, 1];
            int ax = cell.x + CornerOffsetX[a];
            int ay = cell.y + CornerOffsetY[a];
            int az = cell.z + CornerOffsetZ[a];
            int bx = cell.x + CornerOffsetX[b];
            int by = cell.y + CornerOffsetY[b];
            int bz = cell.z + CornerOffsetZ[b];
            int localAxis = ax != bx ? 0 : (ay != by ? 1 : 2);
            if (localAxis == axis &&
                Mathf.Min(ax, bx) == edgeStart.x &&
                Mathf.Min(ay, by) == edgeStart.y &&
                Mathf.Min(az, bz) == edgeStart.z)
                return edge;
        }
        return -1;
    }

    private static AuthoritativeBlockTopologyStats AnalyzeAuthoritativeBlockTopology(
        AuthoritativeTsdfBlockMesh block)
    {
        AuthoritativeBlockTopologyStats stats = new AuthoritativeBlockTopologyStats();
        Dictionary<ulong, int> triangleKeys = new Dictionary<ulong, int>(block.Triangles.Count / 3);
        Dictionary<ulong, List<int>> edgeTriangles = new Dictionary<ulong, List<int>>(block.Triangles.Count);
        for (int i = 0; i + 2 < block.Triangles.Count; i += 3)
        {
            int a = block.Triangles[i];
            int b = block.Triangles[i + 1];
            int c = block.Triangles[i + 2];
            if (a == b || b == c || c == a)
                stats.DegenerateTriangles++;
            int x = Mathf.Min(a, Mathf.Min(b, c));
            int z = Mathf.Max(a, Mathf.Max(b, c));
            int y = a + b + c - x - z;
            ulong triangleKey = ((ulong)(uint)x << 42) | ((ulong)(uint)y << 21) | (uint)z;
            if (triangleKeys.ContainsKey(triangleKey))
                stats.DuplicateTriangles++;
            else
                triangleKeys[triangleKey] = i / 3;
            AddAuthoritativeTopologyEdge(a, b, i / 3, edgeTriangles);
            AddAuthoritativeTopologyEdge(b, c, i / 3, edgeTriangles);
            AddAuthoritativeTopologyEdge(c, a, i / 3, edgeTriangles);
        }
        foreach (KeyValuePair<ulong, List<int>> pair in edgeTriangles)
        {
            int incidence = pair.Value.Count;
            stats.MaxEdgeIncidence = Mathf.Max(stats.MaxEdgeIncidence, incidence);
            if (incidence == 1)
                stats.BoundaryEdges++;
            if (incidence <= 2)
                continue;
            stats.NonManifoldEdges++;
            int axisMask = 0;
            for (int i = 0; i < pair.Value.Count; i++)
            {
                int triangle = pair.Value[i];
                if (triangle >= 0 && triangle < block.TriangleSources.Count)
                    axisMask |= 1 << Mathf.Clamp(block.TriangleSources[triangle].Axis, 0, 2);
            }
            if ((axisMask & (axisMask - 1)) != 0)
                stats.MixedAxisEdges++;
        }
        return stats;
    }

    private static void AddAuthoritativeTopologyEdge(
        int a, int b, int triangle, Dictionary<ulong, List<int>> edgeTriangles)
    {
        uint min = (uint)Mathf.Min(a, b);
        uint max = (uint)Mathf.Max(a, b);
        ulong key = ((ulong)min << 32) | max;
        if (!edgeTriangles.TryGetValue(key, out List<int> triangles))
        {
            triangles = new List<int>(4);
            edgeTriangles[key] = triangles;
        }
        triangles.Add(triangle);
    }

    private void AppendAuthoritativeBlockTopologyRow(
        Vector3Int key,
        bool direct,
        ScanCoverIncrementalPatchShadow.PatchDirtyReason reason,
        AuthoritativeTsdfBlockMesh block,
        AuthoritativeBlockTopologyStats stats)
    {
        if (_authoritativeBlockTopologyRows == null)
            return;
        _authoritativeBlockTopologyRows
            .Append(LastAuthoritativeReadSnapshotSequence).Append(',')
            .Append(key.x).Append(',').Append(key.y).Append(',').Append(key.z).Append(',')
            .Append(direct ? 1 : 0).Append(',').Append(reason).Append(',')
            .Append(block.Vertices.Count).Append(',').Append(block.Triangles.Count / 3).Append(',')
            .Append(block.MultiComponentCells).Append(',').Append(block.SplitVertices).Append(',')
            .Append(stats.NonManifoldEdges).Append(',').Append(stats.MaxEdgeIncidence).Append(',')
            .Append(stats.DuplicateTriangles).Append(',').Append(stats.DegenerateTriangles).Append(',')
            .Append(stats.MixedAxisEdges).AppendLine();
    }

    private bool TryGetAuthoritativeZeroCrossing(
        int ax, int ay, int az, int bx, int by, int bz,
        int aIndex, int bIndex,
        out Vector3 crossing)
    {
        crossing = Vector3.zero;
        int minWeight = Mathf.Max(1, authoritativeTsdfBlockMinWeight);
        if (!AuthoritativeVoxelUsable(aIndex, minWeight) || !AuthoritativeVoxelUsable(bIndex, minWeight))
            return false;
        float a = _authoritativeReadTsdf[aIndex];
        float b = _authoritativeReadTsdf[bIndex];
        if (!((a < 0f && b > 0f) || (a > 0f && b < 0f)) || Mathf.Abs(a - b) < 0.000001f)
            return false;
        float t = Mathf.Clamp01(a / (a - b));
        crossing = Vector3.Lerp(VoxelCenter(ax, ay, az), VoxelCenter(bx, by, bz), t);
        return Finite(crossing);
    }

    private bool AuthoritativeVoxelUsable(int index, int minWeight)
    {
        return _authoritativeReadTsdf != null && _authoritativeReadWeights != null &&
               _authoritativeReadEligibility != null &&
               index >= 0 && index < _authoritativeReadTsdf.Length &&
               index < _authoritativeReadWeights.Length && index < _authoritativeReadEligibility.Length &&
               _authoritativeReadWeights[index] >= minWeight &&
               _authoritativeReadEligibility[index] != 0 &&
               !float.IsNaN(_authoritativeReadTsdf[index]) &&
               !float.IsInfinity(_authoritativeReadTsdf[index]);
    }

    private Vector3Int AuthoritativeBlockKey(Vector3 point, float patchSize)
    {
        Vector3 local = (point - _volumeOriginWorld) / Mathf.Max(0.001f, patchSize);
        return new Vector3Int(
            Mathf.FloorToInt(local.x),
            Mathf.FloorToInt(local.y),
            Mathf.FloorToInt(local.z));
    }

    private static int CountNonManifoldEdges(List<int> triangles)
    {
        Dictionary<ulong, int> counts = new Dictionary<ulong, int>(triangles.Count);
        for (int i = 0; i + 2 < triangles.Count; i += 3)
        {
            CountEdge(triangles[i], triangles[i + 1], counts);
            CountEdge(triangles[i + 1], triangles[i + 2], counts);
            CountEdge(triangles[i + 2], triangles[i], counts);
        }
        int nonManifold = 0;
        foreach (int count in counts.Values)
        {
            if (count > 2)
                nonManifold++;
        }
        return nonManifold;
    }

    private static void CountEdge(int a, int b, Dictionary<ulong, int> counts)
    {
        uint min = (uint)Mathf.Min(a, b);
        uint max = (uint)Mathf.Max(a, b);
        ulong key = ((ulong)min << 32) | max;
        counts.TryGetValue(key, out int count);
        counts[key] = count + 1;
    }

