    private StringBuilder BuildStablePlaneDiagnosticsCsv()
    {
        StringBuilder csv = new StringBuilder(1024);
        csv.AppendLine("rebuild,provenance_samples,surface_cell_samples,input_samples,extraction_attempts,max_active_samples,valid_hypotheses,best_distance_inliers,best_normal_inliers,reject_insufficient_active,reject_no_hypothesis,reject_min_inliers,reject_normal_consistency,reject_refined_inliers,reject_rms,maturity_blocked_rms,proposals,candidate_planes,mature_planes,assigned_vertices,moved_vertices,reverted_vertices,publication_applied,min_inliers,fit_distance_m,min_sample_normal_dot,render_triangles,logical_triangles,reverse_pairs_removed,same_winding_duplicates_removed,unpaired_logical_triangles,winding_conflicts,invalid_triangles,canonical_merge_count,canonical_merged_tracks,canonical_merge_max_distance_m,canonical_merge_min_normal_dot,parallel_duplicate_suppressed");
        csv.Append(LastIncrementalPatchRebuildSequence).Append(',')
            .Append(LastStablePlaneDepthProvenanceSampleCount).Append(',')
            .Append(LastStablePlaneDepthSurfaceCellSampleCount).Append(',')
            .Append(LastStablePlaneShadowInputSampleCount).Append(',')
            .Append(LastStablePlaneExtractionAttemptCount).Append(',')
            .Append(LastStablePlaneMaxActiveSampleCount).Append(',')
            .Append(LastStablePlaneRansacValidHypothesisCount).Append(',')
            .Append(LastStablePlaneMaxBestDistanceInlierCount).Append(',')
            .Append(LastStablePlaneMaxBestNormalInlierCount).Append(',')
            .Append(LastStablePlaneRejectedInsufficientActiveCount).Append(',')
            .Append(LastStablePlaneRejectedNoHypothesisCount).Append(',')
            .Append(LastStablePlaneRejectedMinInlierCount).Append(',')
            .Append(LastStablePlaneRejectedNormalConsistencyCount).Append(',')
            .Append(LastStablePlaneRejectedRefinedInlierCount).Append(',')
            .Append(LastStablePlaneRejectedRmsCount).Append(',')
            .Append(LastStablePlaneMaturityBlockedRmsCount).Append(',')
            .Append(LastStablePlaneShadowProposalCount).Append(',')
            .Append(LastStablePlaneShadowCandidatePlaneCount).Append(',')
            .Append(LastStablePlaneShadowMaturePlaneCount).Append(',')
            .Append(LastStablePlaneShadowAssignedVertexCount).Append(',')
            .Append(LastStablePlaneShadowMovedVertexCount).Append(',')
            .Append(LastStablePlaneShadowRevertedVertexCount).Append(',')
            .Append(LastStablePlaneConstrainedPatchPublication).Append(',')
            .Append(stablePlaneShadowMinInliers).Append(',')
            .Append(stablePlaneShadowFitDistanceMeters.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(stablePlaneShadowMinSampleNormalDot.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(LastLogicalRenderTriangleCount).Append(',')
            .Append(LastLogicalTriangleCount).Append(',')
            .Append(LastLogicalReversePairRemovedCount).Append(',')
            .Append(LastLogicalSameWindingDuplicateRemovedCount).Append(',')
            .Append(LastLogicalUnpairedTriangleCount).Append(',')
            .Append(LastLogicalWindingConflictCount).Append(',')
            .Append(LastLogicalInvalidTriangleCount).Append(',')
            .Append(LastStablePlaneCanonicalMergeCount).Append(',')
            .Append(LastStablePlaneCanonicalMergedTrackCount).Append(',')
            .Append(LastStablePlaneCanonicalMergeMaxDistanceMeters.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(LastStablePlaneCanonicalMergeMinNormalDot.ToString("F6", CultureInfo.InvariantCulture)).Append(',')
            .Append(LastStablePlaneParallelDuplicateSuppressedCount).AppendLine();
        return csv;
    }

    private static bool IsStablePlaneDepthSurfaceOperation(string operation)
    {
        return operation == "integrate" ||
               operation == "atomic_accept_band" ||
               operation == "strong_current_promote";
    }

    private ScanCoverStablePlaneRegistry.Settings BuildStablePlaneRegistrySettings(
        int maxSamples,
        int ransacIterations)
    {
        return new ScanCoverStablePlaneRegistry.Settings
        {
            MaxSamples = maxSamples,
            MaxPlanes = stablePlaneShadowMaxPlanes,
            RansacIterations = ransacIterations,
            MinInliers = stablePlaneShadowMinInliers,
            FitDistanceMeters = stablePlaneShadowFitDistanceMeters,
            MinSampleNormalDot = stablePlaneShadowMinSampleNormalDot,
            MatchNormalDot = stablePlaneShadowMatchNormalDot,
            MatchPlaneDistanceMeters = stablePlaneShadowMatchDistanceMeters,
            MatchTangentialPaddingMeters = stablePlaneShadowPatchPaddingMeters,
            MatureBatches = stablePlaneShadowMatureBatches,
            RetireMissingBatches = stablePlaneShadowRetireMissingBatches,
            MatureHoldMissingBatches = stablePlaneMatureHoldMissingBatches,
            MatureDemoteBadRmsBatches = stablePlaneMatureDemoteBadRmsBatches,
            VertexNormalDot = stablePlaneShadowVertexNormalDot,
            MaxVertexPlaneDistanceMeters = stablePlaneShadowMaxProjectionMeters,
            PatchPaddingMeters = stablePlaneShadowPatchPaddingMeters,
            MaxVertexMoveMeters = stablePlaneShadowMaxProjectionMeters,
            MinTriangleAreaRatio = 0.20f,
            MinTriangleNormalDot = 0.35f,
            CanonicalMergeNormalDot = stablePlaneCanonicalMergeNormalDot,
            CanonicalMergePlaneDistanceMeters = stablePlaneCanonicalMergeDistanceMeters,
            CanonicalMergeMinOverlapRatio = stablePlaneCanonicalMergeMinOverlapRatio,
            ParallelDuplicateMaxDistanceMeters = stablePlaneParallelDuplicateMaxDistanceMeters,
            ParallelDuplicateMaxSigma = stablePlaneParallelDuplicateMaxSigma,
            ParallelDuplicateMinOverlapRatio = stablePlaneParallelDuplicateMinOverlapRatio
        };
    }

    private List<ScanCoverStablePlaneRegistry.PlaneConstraint>
        GetIncrementalPlaneConstraintsWithColdStartCandidates()
    {
        List<ScanCoverStablePlaneRegistry.PlaneConstraint> mature =
            _stablePlaneRegistry.GetMatureConstraints();
        if (mature.Count > 0 || !enableIncrementalStablePlaneBootstrap)
            return mature;
        return _stablePlaneRegistry.GetCurrentCandidateConstraints();
    }

    private void ApplyStablePlaneRegistryDiagnostics(ScanCoverStablePlaneRegistry.Result result)
    {
        LastStablePlaneShadowInputSampleCount = result.InputSamples;
        LastStablePlaneExtractionAttemptCount = result.ExtractionAttempts;
        LastStablePlaneMaxActiveSampleCount = result.MaxActiveSamples;
        LastStablePlaneRansacValidHypothesisCount = result.RansacValidHypotheses;
        LastStablePlaneMaxBestDistanceInlierCount = result.MaxBestDistanceInliers;
        LastStablePlaneMaxBestNormalInlierCount = result.MaxBestNormalInliers;
        LastStablePlaneRejectedInsufficientActiveCount = result.RejectedInsufficientActiveSamples;
        LastStablePlaneRejectedNoHypothesisCount = result.RejectedNoValidHypothesis;
        LastStablePlaneCanonicalMergeCount = result.CanonicalMergeCount;
        LastStablePlaneCanonicalMergedTrackCount = result.CanonicalMergedTrackCount;
        LastStablePlaneCanonicalMergeMaxDistanceMeters = result.CanonicalMergeMaxPlaneDistanceMeters;
        LastStablePlaneCanonicalMergeMinNormalDot = result.CanonicalMergeMinNormalDot;
        LastStablePlaneParallelDuplicateSuppressedCount = result.ParallelDuplicateSuppressedCount;
        LastStablePlaneRejectedMinInlierCount = result.RejectedMinInliers;
        LastStablePlaneRejectedNormalConsistencyCount = result.RejectedByNormalConsistency;
        LastStablePlaneRejectedRefinedInlierCount = result.RejectedRefinedMinInliers;
        LastStablePlaneRejectedRmsCount = result.RejectedRms;
        LastStablePlaneMaturityBlockedRmsCount = result.MaturityBlockedRms;
        LastStablePlaneShadowProposalCount = result.ProposalCount;
        LastStablePlaneShadowCandidatePlaneCount = result.CandidatePlaneCount;
        LastStablePlaneShadowMaturePlaneCount = result.MaturePlaneCount;
        LastStablePlaneShadowAssignedVertexCount = result.AssignedVertexCount;
        LastStablePlaneShadowMovedVertexCount = result.MovedVertexCount;
        LastStablePlaneShadowRevertedVertexCount = result.RevertedVertexCount;
        LastStablePlaneShadowResidualBeforeMeters = result.MeanResidualBeforeMeters;
        LastStablePlaneShadowResidualAfterMeters = result.MeanResidualAfterMeters;
        LastStablePlaneShadowMaxDisplacementMeters = result.MaxDisplacementMeters;
    }

    private IEnumerator UpdateIncrementalStablePlaneRegistryRoutine(
        IReadOnlyDictionary<Vector3Int, AuthoritativeTsdfBlockMesh> extractedCandidates,
        CooperativeRebuildBudget budget)
    {
        if (!enableIncrementalStablePlaneBootstrap ||
            !enableStablePlaneShadowTrial ||
            extractedCandidates == null || extractedCandidates.Count == 0)
            yield break;

        LastIncrementalStablePlaneBootstrapAttempted = 1;
        ResetStablePlaneShadowDiagnostics();
        int maxSamples = Mathf.Clamp(
            incrementalStablePlaneBootstrapMaxSamples, 512, stablePlaneShadowMaxSamples);
        int maxCollectedSamples = Mathf.Max(256, maxSamples * 2);
        List<Vector3> samplePoints = new List<Vector3>(maxCollectedSamples);
        List<Vector3> sampleNormals = new List<Vector3>(maxCollectedSamples);
        HashSet<int> seenSamples = new HashSet<int>();

        foreach (KeyValuePair<int, VoxelWriteProvenance> pair in _voxelWriteProvenance)
        {
            if (budget != null && budget.ShouldYield())
            {
                budget.CompleteSliceForYield();
                yield return null;
                budget.Resume();
            }
            VoxelWriteProvenance provenance = pair.Value;
            if (!IsStablePlaneDepthSurfaceOperation(provenance.LastOperation) ||
                provenance.SurfaceDepth <= 0f ||
                !Finite(provenance.SurfacePoint) || !Finite(provenance.SurfaceNormal) ||
                provenance.SurfaceNormal.sqrMagnitude < 0.0001f)
                continue;
            unchecked
            {
                int sampleKey = provenance.Frame;
                sampleKey = sampleKey * 397 ^ provenance.Sample;
                sampleKey = sampleKey * 397 ^ provenance.PixelX;
                sampleKey = sampleKey * 397 ^ provenance.PixelY;
                if (!seenSamples.Add(sampleKey))
                    continue;
            }
            samplePoints.Add(provenance.SurfacePoint);
            sampleNormals.Add(provenance.SurfaceNormal.normalized);
            if (samplePoints.Count >= maxCollectedSamples)
                break;
        }
        LastStablePlaneDepthProvenanceSampleCount = samplePoints.Count;

        if (samplePoints.Count < maxCollectedSamples && useChunkedSurfaceSamples)
        {
            foreach (KeyValuePair<Vector3Int, SurfaceChunk> chunkPair in _surfaceChunks)
            {
                foreach (KeyValuePair<Vector3Int, SurfaceCell> cellPair in chunkPair.Value.Cells)
                {
                    if (budget != null && budget.ShouldYield())
                    {
                        budget.CompleteSliceForYield();
                        yield return null;
                        budget.Resume();
                    }
                    if (samplePoints.Count >= maxCollectedSamples)
                        break;
                    SurfaceCell cell = cellPair.Value;
                    if (cell == null || cell.Hits < 2 ||
                        !Finite(cell.Point) || !Finite(cell.Normal) ||
                        cell.Normal.sqrMagnitude < 0.0001f)
                        continue;
                    samplePoints.Add(cell.Point);
                    sampleNormals.Add(cell.Normal.normalized);
                    LastStablePlaneDepthSurfaceCellSampleCount++;
                }
                if (samplePoints.Count >= maxCollectedSamples)
                    break;
            }
        }
        else if (samplePoints.Count < maxCollectedSamples)
        {
            int count = Mathf.Min(_fallbackSurfacePoints.Count, _fallbackSurfaceNormals.Count);
            for (int i = 0; i < count && samplePoints.Count < maxCollectedSamples; i++)
            {
                if (budget != null && budget.ShouldYield())
                {
                    budget.CompleteSliceForYield();
                    yield return null;
                    budget.Resume();
                }
                Vector3 point = _fallbackSurfacePoints[i];
                Vector3 normal = _fallbackSurfaceNormals[i];
                if (!Finite(point) || !Finite(normal) || normal.sqrMagnitude < 0.0001f)
                    continue;
                samplePoints.Add(point);
                sampleNormals.Add(normal.normalized);
                LastStablePlaneDepthSurfaceCellSampleCount++;
            }
        }

        if (samplePoints.Count < stablePlaneShadowMinInliers)
            yield break;
        if (budget != null && budget.ShouldYield())
        {
            budget.CompleteSliceForYield();
            yield return null;
            budget.Resume();
        }

        double updateStart = Time.realtimeSinceStartupAsDouble;
        ScanCoverStablePlaneRegistry.Settings settings = BuildStablePlaneRegistrySettings(
            maxSamples,
            Mathf.Min(stablePlaneShadowRansacIterations,
                incrementalStablePlaneBootstrapRansacIterations));
        bool updated = _stablePlaneRegistry.UpdateTracksOnly(
            samplePoints,
            sampleNormals,
            settings,
            out ScanCoverStablePlaneRegistry.Result result);
        LastIncrementalStablePlaneBootstrapMilliseconds =
            (float)((Time.realtimeSinceStartupAsDouble - updateStart) * 1000.0);
        LastIncrementalStablePlaneBootstrapUpdated = updated ? 1 : 0;
        ApplyStablePlaneRegistryDiagnostics(result);
        UpdateAuthoritativeCyanLocalStructuralSupport(
            samplePoints, sampleNormals, _stablePlaneRegistry.GetMatureConstraints());
    }

    private List<Vector3> RebuildStablePlaneShadow(List<Vector3> sourceVertices, List<int> sourceTriangles)
    {
        ResetStablePlaneShadowDiagnostics();
        if (showStablePlaneShadowWire)
            EnsureStablePlaneShadowObjects();
        if (_stablePlaneShadowMesh != null)
            _stablePlaneShadowMesh.Clear();
        if (!enableStablePlaneShadowTrial ||
            sourceVertices == null || sourceTriangles == null ||
            sourceVertices.Count < 3 || sourceTriangles.Count < 3)
        {
            if (_stablePlaneShadowObject != null)
                _stablePlaneShadowObject.SetActive(false);
            return null;
        }

        List<Vector3> samplePoints = new List<Vector3>(Mathf.Min(stablePlaneShadowMaxSamples * 2, _voxelWriteProvenance.Count));
        List<Vector3> sampleNormals = new List<Vector3>(samplePoints.Capacity);
        HashSet<int> seenSamples = new HashSet<int>();
        foreach (KeyValuePair<int, VoxelWriteProvenance> pair in _voxelWriteProvenance)
        {
            VoxelWriteProvenance provenance = pair.Value;
            if (!IsStablePlaneDepthSurfaceOperation(provenance.LastOperation) ||
                provenance.SurfaceDepth <= 0f ||
                !Finite(provenance.SurfacePoint) || !Finite(provenance.SurfaceNormal) ||
                provenance.SurfaceNormal.sqrMagnitude < 0.0001f)
                continue;
            unchecked
            {
                int sampleKey = provenance.Frame;
                sampleKey = sampleKey * 397 ^ provenance.Sample;
                sampleKey = sampleKey * 397 ^ provenance.PixelX;
                sampleKey = sampleKey * 397 ^ provenance.PixelY;
                if (!seenSamples.Add(sampleKey))
                    continue;
            }
            samplePoints.Add(provenance.SurfacePoint);
            sampleNormals.Add(provenance.SurfaceNormal.normalized);
        }
        LastStablePlaneDepthProvenanceSampleCount = samplePoints.Count;
        int maxDepthSamples = Mathf.Max(256, stablePlaneShadowMaxSamples * 2);
        if (useChunkedSurfaceSamples)
        {
            foreach (KeyValuePair<Vector3Int, SurfaceChunk> chunkPair in _surfaceChunks)
            {
                foreach (KeyValuePair<Vector3Int, SurfaceCell> cellPair in chunkPair.Value.Cells)
                {
                    if (samplePoints.Count >= maxDepthSamples)
                        break;
                    SurfaceCell cell = cellPair.Value;
                    if (cell == null || cell.Hits < 2 ||
                        !Finite(cell.Point) || !Finite(cell.Normal) ||
                        cell.Normal.sqrMagnitude < 0.0001f)
                        continue;
                    samplePoints.Add(cell.Point);
                    sampleNormals.Add(cell.Normal.normalized);
                    LastStablePlaneDepthSurfaceCellSampleCount++;
                }
                if (samplePoints.Count >= maxDepthSamples)
                    break;
            }
        }
        else
        {
            int count = Mathf.Min(_fallbackSurfacePoints.Count, _fallbackSurfaceNormals.Count);
            for (int i = 0; i < count && samplePoints.Count < maxDepthSamples; i++)
            {
                Vector3 point = _fallbackSurfacePoints[i];
                Vector3 normal = _fallbackSurfaceNormals[i];
                if (!Finite(point) || !Finite(normal) || normal.sqrMagnitude < 0.0001f)
                    continue;
                samplePoints.Add(point);
                sampleNormals.Add(normal.normalized);
                LastStablePlaneDepthSurfaceCellSampleCount++;
            }
        }

        ScanCoverStablePlaneRegistry.Settings settings = BuildStablePlaneRegistrySettings(
            stablePlaneShadowMaxSamples,
            stablePlaneShadowRansacIterations);
        bool allowCandidatePlanes = stablePlaneShadowUseCandidatePlanes &&
                                    !stablePlaneConstrainedPublicationRequireMature;
        bool built = _stablePlaneRegistry.UpdateAndBuildShadow(
            samplePoints,
            sampleNormals,
            sourceVertices,
            sourceTriangles,
            settings,
            allowCandidatePlanes,
            out List<Vector3> shadowVertices,
            out ScanCoverStablePlaneRegistry.Result result);

        ApplyStablePlaneRegistryDiagnostics(result);
        UpdateAuthoritativeCyanLocalStructuralSupport(
            samplePoints, sampleNormals, _stablePlaneRegistry.GetMatureConstraints());
        bool canConstrainPatchPublication = enableStablePlaneConstrainedPatchPublication &&
                                            result.MaturePlaneCount > 0 &&
                                            built &&
                                            shadowVertices != null &&
                                            shadowVertices.Count == sourceVertices.Count;
        LastStablePlaneConstrainedPatchPublication = canConstrainPatchPublication ? 1 : 0;
        List<Vector3> constrainedPatchVertices = canConstrainPatchPublication
            ? new List<Vector3>(shadowVertices)
            : null;
        if (!built || shadowVertices == null || shadowVertices.Count != sourceVertices.Count)
        {
            if (_stablePlaneShadowObject != null)
                _stablePlaneShadowObject.SetActive(false);
            return constrainedPatchVertices;
        }

        if (!showStablePlaneShadowWire ||
            _stablePlaneShadowMesh == null || _stablePlaneShadowObject == null)
        {
            if (_stablePlaneShadowObject != null)
                _stablePlaneShadowObject.SetActive(false);
            return constrainedPatchVertices;
        }

        // Mature-plane comparison must remain at its actual spatial position.
        float displayOffset = stablePlaneConstrainedPublicationRequireMature
            ? 0f
            : Mathf.Clamp(stablePlaneShadowDisplayOffsetMeters, 0f, 0.02f);
        if (displayOffset > 0f)
        {
            Vector3 cameraPosition = Camera.main != null
                ? Camera.main.transform.position
                : GetCameraPosition();
            for (int i = 0; i < shadowVertices.Count; i++)
            {
                Vector3 towardCamera = cameraPosition - shadowVertices[i];
                if (towardCamera.sqrMagnitude > 0.000001f)
                    shadowVertices[i] += towardCamera.normalized * displayOffset;
            }
        }

        List<int> lineIndices = new List<int>(sourceTriangles.Count * 2);
        HashSet<ulong> edges = new HashSet<ulong>();
        Dictionary<int, ScanCoverStablePlaneRegistry.PlaneConstraint> structuralPlanes = null;
        if (showPlaneReferenceAndZeroCrossShadowOnly)
        {
            structuralPlanes = new Dictionary<int, ScanCoverStablePlaneRegistry.PlaneConstraint>();
            IReadOnlyList<ScanCoverStablePlaneRegistry.PlaneConstraint> maturePlanes =
                _stablePlaneRegistry.GetMatureConstraints();
            PrepareAuthoritativeCyanHorizontalExtrema(maturePlanes);
            for (int planeIndex = 0; planeIndex < maturePlanes.Count; planeIndex++)
            {
                ScanCoverStablePlaneRegistry.PlaneConstraint plane = maturePlanes[planeIndex];
                if (IsAuthoritativeCyanStructuralPlane(plane, out _, out _) ||
                    HasAuthoritativeCyanLocallyQualifiedTiles(plane.Id))
                    structuralPlanes[plane.Id] = plane;
            }
        }
        for (int i = 0; i + 2 < sourceTriangles.Count; i += 3)
        {
            int a = sourceTriangles[i];
            int b = sourceTriangles[i + 1];
            int c = sourceTriangles[i + 2];
            int pa = _stablePlaneRegistry.GetLastVertexPlaneId(a);
            int pb = _stablePlaneRegistry.GetLastVertexPlaneId(b);
            int pc = _stablePlaneRegistry.GetLastVertexPlaneId(c);
            // White is an evaluation view of the actual mature constraints, not a
            // copy of the raw mesh with a few vertices moved.  Mixed/raw triangles
            // would make the reference itself look wavy and are deliberately hidden.
            if (pa < 0 || pa != pb || pb != pc)
                continue;
            if (structuralPlanes != null)
            {
                if (!structuralPlanes.TryGetValue(pa,
                        out ScanCoverStablePlaneRegistry.PlaneConstraint displayPlane))
                    continue;
                Vector3 centroid = (shadowVertices[a] + shadowVertices[b] + shadowVertices[c]) / 3f;
                if (!IsAuthoritativeCyanPlaneQualifiedAtPoint(displayPlane, centroid, out _, out _))
                    continue;
            }
            AddUniqueWireEdge(a, b, shadowVertices.Count, edges, lineIndices);
            AddUniqueWireEdge(b, c, shadowVertices.Count, edges, lineIndices);
            AddUniqueWireEdge(c, a, shadowVertices.Count, edges, lineIndices);
        }
        _stablePlaneShadowMesh.indexFormat = shadowVertices.Count > 65535 ? IndexFormat.UInt32 : IndexFormat.UInt16;
        _stablePlaneShadowMesh.SetVertices(shadowVertices);
        _stablePlaneShadowMesh.SetIndices(lineIndices, MeshTopology.Lines, 0, true);
        _stablePlaneShadowMesh.RecalculateBounds();
        _stablePlaneShadowObject.SetActive(lineIndices.Count > 0);
        return constrainedPatchVertices;
    }

    private static void AppendStablePlaneMeshFallbackSamples(
        List<Vector3> vertices,
        List<int> triangles,
        int maxSamples,
        List<Vector3> points,
        List<Vector3> normals)
    {
        if (vertices == null || triangles == null || points == null || normals == null)
            return;
        int triangleCount = triangles.Count / 3;
        int stride = Mathf.Max(1, Mathf.CeilToInt(triangleCount / (float)Mathf.Max(1, maxSamples)));
        for (int triangle = 0; triangle < triangleCount; triangle += stride)
        {
            int offset = triangle * 3;
            int ia = triangles[offset];
            int ib = triangles[offset + 1];
            int ic = triangles[offset + 2];
            if (ia < 0 || ib < 0 || ic < 0 ||
                ia >= vertices.Count || ib >= vertices.Count || ic >= vertices.Count)
                continue;
            Vector3 a = vertices[ia];
            Vector3 b = vertices[ib];
            Vector3 c = vertices[ic];
            Vector3 normal = Vector3.Cross(b - a, c - a);
            if (!Finite(a) || !Finite(b) || !Finite(c) || normal.sqrMagnitude < 0.000001f)
                continue;
            points.Add((a + b + c) / 3f);
            normals.Add(normal.normalized);
            if (points.Count >= maxSamples)
                break;
        }
    }

    private void ResetStablePlaneShadowDiagnostics()
    {
        LastStablePlaneShadowInputSampleCount = 0;
        LastStablePlaneDepthProvenanceSampleCount = 0;
        LastStablePlaneDepthSurfaceCellSampleCount = 0;
        LastStablePlaneExtractionAttemptCount = 0;
        LastStablePlaneMaxActiveSampleCount = 0;
        LastStablePlaneRansacValidHypothesisCount = 0;
        LastStablePlaneMaxBestDistanceInlierCount = 0;
        LastStablePlaneMaxBestNormalInlierCount = 0;
        LastStablePlaneRejectedInsufficientActiveCount = 0;
        LastStablePlaneRejectedNoHypothesisCount = 0;
        LastStablePlaneCanonicalMergeCount = 0;
        LastStablePlaneCanonicalMergedTrackCount = 0;
        LastStablePlaneCanonicalMergeMaxDistanceMeters = 0f;
        LastStablePlaneCanonicalMergeMinNormalDot = 0f;
        LastStablePlaneParallelDuplicateSuppressedCount = 0;
        LastStablePlaneRejectedMinInlierCount = 0;
        LastStablePlaneRejectedNormalConsistencyCount = 0;
        LastStablePlaneRejectedRefinedInlierCount = 0;
        LastStablePlaneRejectedRmsCount = 0;
        LastStablePlaneMaturityBlockedRmsCount = 0;
        LastStablePlaneShadowProposalCount = 0;
        LastStablePlaneShadowCandidatePlaneCount = 0;
        LastStablePlaneShadowMaturePlaneCount = 0;
        LastStablePlaneShadowAssignedVertexCount = 0;
        LastStablePlaneShadowMovedVertexCount = 0;
        LastStablePlaneShadowRevertedVertexCount = 0;
        LastStablePlaneShadowUsedMeshFallback = 0;
        LastStablePlaneConstrainedPatchPublication = 0;
        LastStablePlaneShadowResidualBeforeMeters = 0f;
        LastStablePlaneShadowResidualAfterMeters = 0f;
        LastStablePlaneShadowMaxDisplacementMeters = 0f;
    }

    private void RebuildPlanarCoverWireOverlay()
    {
        LastWireSegmentCount = 0;
        if (_wireMesh == null)
            return;

        _wireMesh.Clear();

        if (!showPlanarCoverWireOverlay || !renderStableCellsAsPlanarMeshCover || !useChunkedSurfaceSamples || _surfaceChunks.Count <= 0)
        {
            if (_wireObject != null)
                _wireObject.SetActive(false);
            return;
        }

        int renderBudget = Mathf.Max(1, maxFallbackSurfaceSamples);
        int storedCellCount = GetFallbackSurfaceSampleCount();
        if (storedCellCount <= 0)
        {
            if (_wireObject != null)
                _wireObject.SetActive(false);
            return;
        }

        List<Vector3> vertices = new List<Vector3>(Mathf.Min(storedCellCount, renderBudget) * 4);
        List<int> indices = new List<int>(Mathf.Min(storedCellCount, renderBudget) * 8);
        float sampleStep = storedCellCount > renderBudget ? (float)storedCellCount / renderBudget : 1f;
        float nextEmitIndex = 0f;
        int visitedCellIndex = 0;
        int emitted = 0;

        for (int orderIndex = 0; orderIndex < _surfaceChunkOrder.Count && emitted < renderBudget; orderIndex++)
        {
            Vector3Int chunkKey = _surfaceChunkOrder[orderIndex];
            if (!_surfaceChunks.TryGetValue(chunkKey, out SurfaceChunk chunk))
                continue;

            foreach (KeyValuePair<Vector3Int, SurfaceCell> pair in chunk.Cells)
            {
                if (visitedCellIndex + 0.0001f < nextEmitIndex)
                {
                    visitedCellIndex++;
                    continue;
                }

                AddPlanarCoverageWireTile(pair.Value, vertices, indices);
                emitted++;
                nextEmitIndex += sampleStep;
                visitedCellIndex++;
                if (emitted >= renderBudget)
                    break;
            }
        }

        _wireMesh.indexFormat = vertices.Count > 65535 ? IndexFormat.UInt32 : IndexFormat.UInt16;
        _wireMesh.SetVertices(vertices);
        _wireMesh.SetIndices(indices, MeshTopology.Lines, 0, true);
        _wireMesh.RecalculateBounds();
        if (_wireObject != null)
            _wireObject.SetActive(vertices.Count > 0);
    }

    private void AddPlanarCoverageWireTile(SurfaceCell cell, List<Vector3> vertices, List<int> indices)
    {
        Vector3 normal = cell.Normal;
        if (!Finite(normal) || normal.sqrMagnitude < 0.0001f)
            normal = Vector3.up;
        normal.Normalize();

        int axis = DominantAxis(normal);
        Vector3 tangent;
        Vector3 bitangent;
        if (axis == 0)
        {
            tangent = Vector3.forward;
            bitangent = Vector3.up;
        }
        else if (axis == 1)
        {
            tangent = Vector3.right;
            bitangent = Vector3.forward;
        }
        else
        {
            tangent = Vector3.right;
            bitangent = Vector3.up;
        }

        if (Vector3.Dot(Vector3.Cross(tangent, bitangent), normal) < 0f)
        {
            Vector3 swap = tangent;
            tangent = bitangent;
            bitangent = swap;
        }

        float halfSize = Mathf.Max(0.004f, voxelSizeMeters * Mathf.Clamp(wireTileScale, 0.6f, 1.5f)) * 0.5f;
        Vector3 center = cell.Point + normal * 0.007f;
        int start = vertices.Count;
        vertices.Add(center - tangent * halfSize - bitangent * halfSize);
        vertices.Add(center + tangent * halfSize - bitangent * halfSize);
        vertices.Add(center + tangent * halfSize + bitangent * halfSize);
        vertices.Add(center - tangent * halfSize + bitangent * halfSize);

        indices.Add(start);
        indices.Add(start + 1);
        indices.Add(start + 1);
        indices.Add(start + 2);
        indices.Add(start + 2);
        indices.Add(start + 3);
        indices.Add(start + 3);
        indices.Add(start);
        LastWireSegmentCount += 4;
    }

    private void AddFallbackQuad(Vector3 point, Vector3 normal, float halfSize, List<Vector3> vertices, List<int> triangles, List<Color> colors, Color color)
    {
        if (!Finite(normal) || normal.sqrMagnitude < 0.0001f)
            normal = Vector3.up;
        normal.Normalize();

        Vector3 tangent = Vector3.Cross(normal, Vector3.up);
        if (tangent.sqrMagnitude < 0.0001f)
            tangent = Vector3.Cross(normal, Vector3.right);
        tangent.Normalize();
        Vector3 bitangent = Vector3.Cross(normal, tangent).normalized;
        Vector3 center = point + normal * 0.004f;

        int baseIndex = vertices.Count;
        vertices.Add(center - tangent * halfSize - bitangent * halfSize);
        vertices.Add(center + tangent * halfSize - bitangent * halfSize);
        vertices.Add(center + tangent * halfSize + bitangent * halfSize);
        vertices.Add(center - tangent * halfSize + bitangent * halfSize);
        AddVertexColors(colors, color, 4);

        triangles.Add(baseIndex);
        triangles.Add(baseIndex + 1);
        triangles.Add(baseIndex + 2);
        triangles.Add(baseIndex);
        triangles.Add(baseIndex + 2);
        triangles.Add(baseIndex + 3);

        if (!doubleSidedTriangles)
            return;

        triangles.Add(baseIndex + 2);
        triangles.Add(baseIndex + 1);
        triangles.Add(baseIndex);
        triangles.Add(baseIndex + 3);
        triangles.Add(baseIndex + 2);
        triangles.Add(baseIndex);
    }

    private static void AddVertexColors(List<Color> colors, Color color, int count)
    {
        if (colors == null)
            return;
        for (int i = 0; i < count; i++)
            colors.Add(color);
    }

    private void PromoteCoverVertexColor(List<Color> colors, int index, Color color)
    {
        if (colors == null || index < 0 || index >= colors.Count)
            return;
        if (LightCoverColorRank(color) > LightCoverColorRank(colors[index]))
            colors[index] = color;
    }

    private int LightCoverColorRank(Color color)
    {
        if (ApproximatelyColor(color, riskCoverCellColor))
            return 2;
        if (ApproximatelyColor(color, unstableCoverCellColor))
            return 1;
        return 0;
    }

    private static bool ApproximatelyColor(Color a, Color b)
    {
        return Mathf.Abs(a.r - b.r) < 0.001f &&
               Mathf.Abs(a.g - b.g) < 0.001f &&
               Mathf.Abs(a.b - b.b) < 0.001f &&
               Mathf.Abs(a.a - b.a) < 0.001f;
    }

    private float GetCoverageTileHalfSize()
    {
        float size = fallbackSurfaceSampleSizeMeters;
        if (displayFallbackAsCoverageTiles)
            size = Mathf.Max(size, Mathf.Max(0.005f, voxelSizeMeters) * Mathf.Clamp(coverageTileVoxelScale, 0.25f, 1.5f));
        return Mathf.Max(0.001f, size) * 0.5f;
    }

    private int GetFallbackSurfaceSampleCount()
    {
        if (!useChunkedSurfaceSamples)
            return _fallbackSurfacePoints.Count;

        int count = 0;
        foreach (KeyValuePair<Vector3Int, SurfaceChunk> pair in _surfaceChunks)
            count += pair.Value.Cells.Count;
        LastSurfaceChunkCount = _surfaceChunks.Count;
        return count;
    }

    private Vector3Int WorldToSurfaceChunkKey(Vector3 world)
    {
        float size = Mathf.Max(0.25f, surfaceChunkSizeMeters);
        return new Vector3Int(
            Mathf.FloorToInt(world.x / size),
            Mathf.FloorToInt(world.y / size),
            Mathf.FloorToInt(world.z / size));
    }

    private Vector3Int WorldToSurfaceLocalCell(Vector3 world, Vector3 normal)
    {
        float cell = Mathf.Max(0.005f, voxelSizeMeters);
        Vector3 keyedWorld = world;
        bool useSideAwareKey = sideAwareSurfaceCells && useSideAwareLightCoverKeys && Finite(normal) && normal.sqrMagnitude > 0.0001f;
        if (useSideAwareKey)
            keyedWorld += normal.normalized * cell * Mathf.Clamp01(surfaceSideOffsetVoxelScale);
        Vector3Int cellKey = new Vector3Int(
            Mathf.FloorToInt(keyedWorld.x / cell),
            Mathf.FloorToInt(keyedWorld.y / cell),
            Mathf.FloorToInt(keyedWorld.z / cell));
        if (useSideAwareKey)
            cellKey += SurfaceNormalBin(normal) * 1000000;
        return cellKey;
    }

    private Vector3Int SurfaceNormalBin(Vector3 normal)
    {
        if (!Finite(normal) || normal.sqrMagnitude < 0.0001f)
            return Vector3Int.zero;
        normal.Normalize();
        float ax = Mathf.Abs(normal.x);
        float ay = Mathf.Abs(normal.y);
        float az = Mathf.Abs(normal.z);
        if (ax >= ay && ax >= az)
            return normal.x >= 0f ? new Vector3Int(1, 0, 0) : new Vector3Int(-1, 0, 0);
        if (ay >= ax && ay >= az)
            return normal.y >= 0f ? new Vector3Int(0, 1, 0) : new Vector3Int(0, -1, 0);
        return normal.z >= 0f ? new Vector3Int(0, 0, 1) : new Vector3Int(0, 0, -1);
    }

    private int DominantAxis(Vector3 normal)
    {
        float ax = Mathf.Abs(normal.x);
        float ay = Mathf.Abs(normal.y);
        float az = Mathf.Abs(normal.z);
        if (ax >= ay && ax >= az)
            return 0;
        if (ay >= ax && ay >= az)
            return 1;
        return 2;
    }

    private void GetCoverUvAxes(int normalAxis, out int uAxis, out int vAxis)
    {
        if (normalAxis == 0)
        {
            uAxis = 2;
            vAxis = 1;
        }
        else if (normalAxis == 1)
        {
            uAxis = 0;
            vAxis = 2;
        }
        else
        {
            uAxis = 0;
            vAxis = 1;
        }
    }

    private float GetAxis(Vector3 value, int axis)
    {
        if (axis == 0)
            return value.x;
        if (axis == 1)
            return value.y;
        return value.z;
    }

    private void SetAxis(ref Vector3 value, int axis, float component)
    {
        if (axis == 0)
            value.x = component;
        else if (axis == 1)
            value.y = component;
        else
            value.z = component;
    }

    private void EnsureVolumeInitialized()
    {
        if (_volumeInitialized && _tsdf != null && _weights != null)
            return;

        float voxel = Mathf.Max(0.02f, voxelSizeMeters);
        _dimX = Mathf.Max(4, Mathf.CeilToInt(Mathf.Max(voxel, volumeSizeMeters.x) / voxel) + 1);
        _dimY = Mathf.Max(4, Mathf.CeilToInt(Mathf.Max(voxel, volumeSizeMeters.y) / voxel) + 1);
        _dimZ = Mathf.Max(4, Mathf.CeilToInt(Mathf.Max(voxel, volumeSizeMeters.z) / voxel) + 1);

        Vector3 center = volumeAnchor != null ? volumeAnchor.position : GetCameraPosition();
        _volumeOriginWorld = center - new Vector3((_dimX - 1) * voxel, (_dimY - 1) * voxel, (_dimZ - 1) * voxel) * 0.5f;

        int count = _dimX * _dimY * _dimZ;
        _voxelAuditLifecycle.Clear();
        _voxelWriteProvenance.Clear();
        _voxelWriteSequence = 0;
        _holeCellLifecycles.Clear();
        _activeHoleLifecycleCells.Clear();
        _previousStableQuadAuditRecords.Clear();
        _pendingStableQuadHistoryRecords.Clear();
        _stableQuadAuditRecords.Clear();
        _stableQuadAuditEdges.Clear();
        _stableQuadShadowStates.Clear();
        _stableQuadShadowStatesBeforeRebuild.Clear();
        _newbornPholdPreferredStates.Clear();
        _newbornPholdPreferredObserved.Clear();
        _newbornPholdReplacementProbations.Clear();
        _doublePlaneCreaseStates.Clear();
        _newbornLayerSwapStates.Clear();
        _samePlaneAtomicPatchCandidates.Clear();
        _samePlaneAtomicPatchStates.Clear();
        _samePlaneAtomicPatchObserved.Clear();
        _naturallyObservedStableQuadKeys.Clear();
        _newbornPholdCompetitionRebuildSequence = 0;
        _holeLifecycleRebuildSequence = 0;
        _captureAuditVoxels.Clear();
        _tsdf = new float[count];
        _weights = new byte[count];
        _atomicProvisionalBandTsdf = new float[count];
        _atomicProvisionalBandWeight = new byte[count];
        _atomicProvisionalBandRetiredLastFrame = new int[count];
        _atomicProvisionalBandRetiredSign = new byte[count];
        _surfaceBandVisitFlags = new byte[count];
        _surfaceBandAcceptSignLostFlags = new byte[count];
        _acceptedPositiveLastSequence = new int[count];
        _acceptedNegativeLastSequence = new int[count];
        _acceptedPositiveRetainedLastSequence = new int[count];
        _acceptedNegativeRetainedLastSequence = new int[count];
        _acceptedWriteSequence = 0;
        _acceptedSignRecoveryPositiveFrames = new byte[count];
        _acceptedSignRecoveryNegativeFrames = new byte[count];
        _acceptedSignRecoveryPositiveLastFrame = new int[count];
        _acceptedSignRecoveryNegativeLastFrame = new int[count];
        _surfaceObservationState = new byte[count];
        _surfaceObservationLastFrame = new int[count];
        _clearedVoxelLastFrame = new int[count];
        _pendingTsdf = new float[count];
        _pendingTsdfHits = new byte[count];
        _pendingTsdfLastFrame = new int[count];
        _correctionTsdf = new float[count];
        _correctionTsdfHits = new byte[count];
        _correctionTsdfLastFrame = new int[count];
        _dirtyTsdfLastFrame = new int[count];
        _provisionalTsdf = new byte[count];
        _provisionalTsdfLastFrame = new int[count];
        _provisionalTsdfHits = new byte[count];
        _provisionalPromotionBlockStates.Clear();
        _oldCleanConflictHits = new byte[count];
        _oldCleanConflictLastFrame = new int[count];
        _freeSpaceEvidenceHits = new byte[count];
        _freeSpaceEvidenceLastFrame = new int[count];
        for (int i = 0; i < count; i++)
        {
            _tsdf[i] = 1f;
            _atomicProvisionalBandTsdf[i] = 1f;
            _atomicProvisionalBandRetiredLastFrame[i] = int.MinValue;
            _acceptedSignRecoveryPositiveLastFrame[i] = int.MinValue;
            _acceptedSignRecoveryNegativeLastFrame[i] = int.MinValue;
            _acceptedPositiveLastSequence[i] = int.MinValue;
            _acceptedNegativeLastSequence[i] = int.MinValue;
            _acceptedPositiveRetainedLastSequence[i] = int.MinValue;
            _acceptedNegativeRetainedLastSequence[i] = int.MinValue;
            _surfaceObservationLastFrame[i] = int.MinValue;
            _clearedVoxelLastFrame[i] = int.MinValue;
            _pendingTsdfLastFrame[i] = int.MinValue;
            _correctionTsdfLastFrame[i] = int.MinValue;
            _dirtyTsdfLastFrame[i] = int.MinValue;
            _provisionalTsdfLastFrame[i] = int.MinValue;
            _oldCleanConflictLastFrame[i] = int.MinValue;
            _freeSpaceEvidenceLastFrame[i] = int.MinValue;
        }

        _hardAuditExpectedTsdf = (float[])_tsdf.Clone();
        _hardAuditExpectedWeights = (byte[])_weights.Clone();
        ResetHardTsdfWriteAuditCounters();

        _referenceClassicTsdf.Reset(_dimX, _dimY, _dimZ, _volumeOriginWorld, voxelSizeMeters);

        _authoritativeTsdfGeneration++;
        _volumeInitialized = true;
    }

    private int CountWeightedTsdfVoxels()
    {
        if (_weights == null)
            return 0;

        int count = 0;
        for (int i = 0; i < _weights.Length; i++)
        {
            if (_weights[i] > 0)
                count++;
        }
        return count;
    }

    private static int CountWeightedTsdfVoxels(byte[] weights)
    {
        if (weights == null)
            return 0;
        int count = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            if (weights[i] > 0)
                count++;
        }
        return count;
    }

    private void CaptureAuthoritativeReadSnapshot()
    {
        if (!enableAuthoritativeTsdfBlockExtraction || _tsdf == null || _weights == null)
        {
            _authoritativeReadTsdf = null;
            _authoritativeReadWeights = null;
            _authoritativeReadEligibility = null;
            LastAuthoritativeReadSnapshotWeightedVoxelCount = 0;
            LastAuthoritativeLegacyPostRepairWeightedVoxelCount = 0;
            LastAuthoritativeLegacyPostRepairWeightedDelta = 0;
            LastAuthoritativeLegacyMutationVoxelCount = 0;
            LastAuthoritativeCanonicalRestoreVoxelCount = 0;
            LastAuthoritativeCanonicalPostRestoreMismatchCount = 0;
            return;
        }

        int count = Mathf.Min(_tsdf.Length, _weights.Length);
        if (_authoritativeReadTsdf == null || _authoritativeReadTsdf.Length != _tsdf.Length)
            _authoritativeReadTsdf = new float[_tsdf.Length];
        if (_authoritativeReadWeights == null || _authoritativeReadWeights.Length != _weights.Length)
            _authoritativeReadWeights = new byte[_weights.Length];
        if (_authoritativeReadEligibility == null || _authoritativeReadEligibility.Length != count)
            _authoritativeReadEligibility = new byte[count];

        System.Array.Copy(_tsdf, _authoritativeReadTsdf, _tsdf.Length);
        System.Array.Copy(_weights, _authoritativeReadWeights, _weights.Length);
        for (int i = 0; i < count; i++)
        {
            _authoritativeReadEligibility[i] =
                !VoxelHasPendingTsdfCorrection(i) && !VoxelIsDirtyQuarantined(i) ? (byte)1 : (byte)0;
        }

        _authoritativeReadSnapshotSequence++;
        LastAuthoritativeReadSnapshotSequence = _authoritativeReadSnapshotSequence;
        LastAuthoritativeReadSnapshotWeightedVoxelCount = CountWeightedTsdfVoxels(_authoritativeReadWeights);
        LastAuthoritativeLegacyPostRepairWeightedVoxelCount = LastAuthoritativeReadSnapshotWeightedVoxelCount;
        LastAuthoritativeLegacyPostRepairWeightedDelta = 0;
        LastAuthoritativeLegacyMutationVoxelCount = 0;
        LastAuthoritativeCanonicalRestoreVoxelCount = 0;
        LastAuthoritativeCanonicalPostRestoreMismatchCount = 0;
    }

    private void AuditLegacyMutationAgainstAuthoritativeSnapshot()
    {
        if (_authoritativeReadTsdf == null || _authoritativeReadWeights == null ||
            _tsdf == null || _weights == null)
            return;

        LastAuthoritativeLegacyPostRepairWeightedVoxelCount = CountWeightedTsdfVoxels();
        LastAuthoritativeLegacyPostRepairWeightedDelta =
            LastAuthoritativeLegacyPostRepairWeightedVoxelCount - LastAuthoritativeReadSnapshotWeightedVoxelCount;
        int count = Mathf.Min(
            Mathf.Min(_authoritativeReadTsdf.Length, _authoritativeReadWeights.Length),
            Mathf.Min(_tsdf.Length, _weights.Length));
        int mutated = 0;
        for (int i = 0; i < count; i++)
        {
            if (_authoritativeReadWeights[i] != _weights[i] ||
                _authoritativeReadTsdf[i] != _tsdf[i])
                mutated++;
        }
        LastAuthoritativeLegacyMutationVoxelCount = mutated;
    }

    private void RestoreCanonicalTsdfAfterLegacyPublication()
    {
        LastAuthoritativeCanonicalRestoreVoxelCount = 0;
        LastAuthoritativeCanonicalPostRestoreMismatchCount = 0;
        if (_authoritativeReadTsdf == null || _authoritativeReadWeights == null ||
            _tsdf == null || _weights == null ||
            _authoritativeReadTsdf.Length != _tsdf.Length ||
            _authoritativeReadWeights.Length != _weights.Length)
            return;

        int count = Mathf.Min(_tsdf.Length, _weights.Length);
        for (int i = 0; i < count; i++)
        {
            if (_tsdf[i] != _authoritativeReadTsdf[i] ||
                _weights[i] != _authoritativeReadWeights[i])
                LastAuthoritativeCanonicalRestoreVoxelCount++;
        }
        System.Array.Copy(_authoritativeReadTsdf, _tsdf, _tsdf.Length);
        System.Array.Copy(_authoritativeReadWeights, _weights, _weights.Length);

        int mismatch = 0;
        for (int i = 0; i < count; i++)
        {
            if (_tsdf[i] != _authoritativeReadTsdf[i] ||
                _weights[i] != _authoritativeReadWeights[i])
                mismatch++;
        }
        LastAuthoritativeCanonicalPostRestoreMismatchCount = mismatch;
        AuditUntrackedTsdfWrites("authoritative_restore");
    }

    private bool TryBuildCellVertex(
        int x,
        int y,
        int z,
        Vector3[] cornerPositions,
        float[] cornerValues,
        byte[] cornerWeights,
        out Vector3 vertex)
    {
        _lastBuiltCellRestoredByAtomicProvisionalBacking = false;
        if (UseLegacyMeshExtraction)
            return TryBuildLegacyCellVertex(x, y, z, cornerPositions, cornerValues, cornerWeights, out vertex);

        vertex = Vector3.zero;
        bool hasPositive = false;
        bool hasNegative = false;
        bool hasNearZero = false;
        int supportedCorners = 0;
        int nearZeroCorners = 0;

        for (int i = 0; i < 8; i++)
        {
            int vx = x + CornerOffsetX[i];
            int vy = y + CornerOffsetY[i];
            int vz = z + CornerOffsetZ[i];
            int index = Index(vx, vy, vz);
            cornerPositions[i] = VoxelCenter(vx, vy, vz);
            cornerValues[i] = _tsdf[index];
            cornerWeights[i] = IsCleanMeshTsdfVoxel(index) ? _weights[index] : (byte)0;

            if (cornerWeights[i] >= minSurfaceCornerWeight)
            {
                supportedCorners++;
                if (cornerValues[i] < 0f) hasNegative = true;
                if (cornerValues[i] > 0f) hasPositive = true;
                if (Mathf.Abs(cornerValues[i]) <= nearZeroSurfaceThreshold)
                {
                    hasNearZero = true;
                    nearZeroCorners++;
                }
            }
        }

        bool hasStrictSurface = hasPositive && hasNegative;
        bool hasRelaxedSurface =
            AllowRelaxedMeshExtraction &&
            hasNearZero &&
            supportedCorners >= Mathf.Max(2, minRelaxedSurfaceSupportedCorners) &&
            nearZeroCorners >= Mathf.Max(1, minRelaxedNearZeroCorners);
        if (hasRelaxedSurface &&
            !hasStrictSurface &&
            requireRelaxedSurfaceNearStrictCell &&
            !HasStrictSurfaceNeighborCell(x, y, z, Mathf.Max(1, relaxedStrictNeighborRadiusCells)))
        {
            hasRelaxedSurface = false;
        }

        if (hasStrictSurface)
            LastStrictSurfaceCellCandidateCount++;
        else if (hasRelaxedSurface)
            LastRelaxedSurfaceCellCandidateCount++;

        if ((hasStrictSurface && supportedCorners < Mathf.Max(2, minStrictSurfaceSupportedCorners)) ||
            (!hasStrictSurface && !hasRelaxedSurface))
        {
            LastRejectedNoSurfaceCellCount++;
            return false;
        }

        if (suppressExtractionNearPendingTsdfCorrection &&
            CellTouchesPendingTsdfCorrection(x, y, z, pendingCorrectionExtractionRadiusCells))
        {
            LastRejectedCorrectionPendingCellCount++;
            return false;
        }

        if (suppressExtractionNearDirtyTsdfQuarantine &&
            CellTouchesDirtyTsdfQuarantine(x, y, z, dirtyTsdfExtractionRadiusCells))
        {
            LastRejectedDirtyQuarantineCellCount++;
            return false;
        }

        if (!PassMainShellPromotionGate(x, y, z, cornerWeights, hasStrictSurface))
        {
            LastRejectedMainGateCellCount++;
            return false;
        }

        Vector3 sum = Vector3.zero;
        int count = 0;
        int strictEdgeCount = 0;
        int relaxedEdgeCount = 0;
        for (int edge = 0; edge < 12; edge++)
        {
            int a = CubeEdges[edge, 0];
            int b = CubeEdges[edge, 1];
            if (cornerWeights[a] < minSurfaceCornerWeight || cornerWeights[b] < minSurfaceCornerWeight)
                continue;

            float va = cornerValues[a];
            float vb = cornerValues[b];
            bool strictEdge = (va < 0f && vb > 0f) || (va > 0f && vb < 0f);
            bool relaxedEdge = hasRelaxedSurface && IsRelaxedSurfaceEdge(va, vb);
            if ((!strictEdge && !relaxedEdge) || Mathf.Approximately(va, vb))
                continue;

            if (strictEdge)
                strictEdgeCount++;
            else
                relaxedEdgeCount++;

            float t = strictEdge ? Mathf.Clamp01(va / (va - vb)) : (Mathf.Abs(va) <= Mathf.Abs(vb) ? 0f : 1f);
            sum += Vector3.Lerp(cornerPositions[a], cornerPositions[b], t);
            count++;
        }

        if (count <= 0)
        {
            LastRejectedNoEdgeCellCount++;
            return false;
        }
        if (hasStrictSurface && strictEdgeCount < Mathf.Max(1, minStrictSurfaceEdgeHits))
        {
            LastRejectedEdgeCountCellCount++;
            return false;
        }
        if (!hasStrictSurface && relaxedEdgeCount < Mathf.Max(1, minRelaxedSurfaceEdgeHits))
        {
            LastRejectedEdgeCountCellCount++;
            return false;
        }

        vertex = sum / count;
        return Finite(vertex);
    }

    private void EvaluateQuestRoomScanSurfaceNetsShadow(int cellX, int cellY, int cellZ)
    {
        if (_questRoomScanShadowCellFlags == null)
            return;

        System.Array.Clear(_questRoomScanShadowCellFlags, 0, _questRoomScanShadowCellFlags.Length);
        if (!enableQuestRoomScanSurfaceNetsShadow)
            return;

        bool[] shadowCornerUnknown = new bool[8];
        float[] shadowCornerValues = new float[8];
        for (int z = 0; z < cellZ; z++)
        for (int y = 0; y < cellY; y++)
        for (int x = 0; x < cellX; x++)
        {
            int cellIndex = CellIndex(x, y, z, cellX, cellY);
            bool formalActive = _cellVertexIndices[cellIndex] >= 0;
            LastQuestRoomScanShadowCellScanCount++;

            bool shadowActive = TryClassifyQuestRoomScanShadowCell(
                x,
                y,
                z,
                out int goodCrossings,
                out int badCrossings,
                out bool touchesSingleWeight,
                out bool touchesPendingObservation,
                out bool touchesRejectedObservation,
                out bool touchesConflictHistory,
                out bool touchesDirtyQuarantined,
                out bool touchesPendingTsdfCorrection,
                out bool touchesProvisional,
                shadowCornerUnknown,
                shadowCornerValues);

            if (!shadowActive)
            {
                if (formalActive)
                    LastQuestRoomScanShadowFormalOnlyCellCount++;
                continue;
            }

            ushort shadowFlags = QrsShadowCellActiveFlag;
            if (!formalActive)
                shadowFlags |= QrsShadowCellAddedFlag;
            if (badCrossings > 0)
                shadowFlags |= QrsShadowCellUnknownAssistedFlag;
            if (touchesSingleWeight)
                shadowFlags |= QrsShadowCellSingleWeightFlag;
            if (touchesPendingObservation)
                shadowFlags |= QrsShadowCellPendingObservationFlag;
            if (touchesRejectedObservation)
                shadowFlags |= QrsShadowCellRejectedObservationFlag;
            if (touchesConflictHistory)
                shadowFlags |= QrsShadowCellConflictHistoryFlag;
            if (touchesDirtyQuarantined)
                shadowFlags |= QrsShadowCellDirtyQuarantinedFlag;
            if (touchesPendingTsdfCorrection)
                shadowFlags |= QrsShadowCellPendingTsdfCorrectionFlag;
            if (touchesProvisional)
                shadowFlags |= QrsShadowCellProvisionalFlag;
            _questRoomScanShadowCellFlags[cellIndex] = shadowFlags;
            LastQuestRoomScanShadowActiveCellCount++;
            LastQuestRoomScanShadowGoodCrossingCount += goodCrossings;
            LastQuestRoomScanShadowBadCrossingCount += badCrossings;
            if (formalActive)
                LastQuestRoomScanShadowSharedFormalCellCount++;
            else
            {
                LastQuestRoomScanShadowAddedCellCount++;
                if (badCrossings > 0)
                    LastQuestRoomScanShadowAddedUnknownAssistedCellCount++;
                else
                    LastQuestRoomScanShadowAddedAllObservedCellCount++;
                if (touchesSingleWeight)
                    LastQuestRoomScanShadowAddedSingleWeightCellCount++;
                if (touchesPendingObservation)
                    LastQuestRoomScanShadowAddedPendingObservationCellCount++;
                if (touchesRejectedObservation)
                    LastQuestRoomScanShadowAddedRejectedObservationCellCount++;
                if (touchesConflictHistory)
                    LastQuestRoomScanShadowAddedConflictHistoryCellCount++;
                bool touchesDirtyPendingProvisional = touchesDirtyQuarantined ||
                                                      touchesPendingTsdfCorrection ||
                                                      touchesProvisional;
                if (touchesDirtyPendingProvisional)
                    LastQuestRoomScanShadowAddedDirtyPendingProvisionalCellCount++;
                if (touchesDirtyQuarantined)
                    LastQuestRoomScanShadowAddedDirtyQuarantinedCellCount++;
                if (touchesPendingTsdfCorrection)
                    LastQuestRoomScanShadowAddedPendingTsdfCorrectionCellCount++;
                if (touchesProvisional)
                    LastQuestRoomScanShadowAddedProvisionalCellCount++;

                bool policyRisk = touchesPendingObservation ||
                                  touchesRejectedObservation ||
                                  touchesConflictHistory ||
                                  touchesDirtyQuarantined ||
                                  touchesPendingTsdfCorrection;
                if (policyRisk)
                    LastQuestRoomScanShadowAddedPolicyRiskCellCount++;
                else if (badCrossings > 0 || touchesSingleWeight || touchesProvisional)
                    LastQuestRoomScanShadowAddedEvidenceLimitedCellCount++;
                else
                    LastQuestRoomScanShadowAddedStrongSafeCellCount++;

                if (!policyRisk && touchesProvisional)
                {
                    LastQuestRoomScanShadowAddedCleanProvisionalCellCount++;
                    if (badCrossings <= 0)
                    {
                        if (touchesSingleWeight)
                            LastQuestRoomScanShadowAddedCleanProvisionalAllObservedSingleWeightCellCount++;
                        else
                            LastQuestRoomScanShadowAddedCleanProvisionalAllObservedMultiWeightCellCount++;
                    }
                    else if (touchesSingleWeight)
                    {
                        LastQuestRoomScanShadowAddedCleanProvisionalUnknownAssistedSingleWeightCellCount++;
                    }
                    else
                    {
                        LastQuestRoomScanShadowAddedCleanProvisionalUnknownAssistedMultiWeightCellCount++;
                    }
                }
            }
            if (badCrossings > 0)
                LastQuestRoomScanShadowUnknownAssistedCellCount++;
            else
                LastQuestRoomScanShadowAllObservedCellCount++;
            if (touchesSingleWeight)
                LastQuestRoomScanShadowSingleWeightCellCount++;
            if (touchesPendingObservation)
                LastQuestRoomScanShadowPendingObservationCellCount++;
            if (touchesRejectedObservation)
                LastQuestRoomScanShadowRejectedObservationCellCount++;
            if (touchesConflictHistory)
                LastQuestRoomScanShadowConflictHistoryCellCount++;
            bool touchesAnyDirtyPendingProvisional = touchesDirtyQuarantined ||
                                                     touchesPendingTsdfCorrection ||
                                                     touchesProvisional;
            if (touchesAnyDirtyPendingProvisional)
                LastQuestRoomScanShadowDirtyPendingProvisionalCellCount++;
            if (touchesDirtyQuarantined)
                LastQuestRoomScanShadowDirtyQuarantinedCellCount++;
            if (touchesPendingTsdfCorrection)
                LastQuestRoomScanShadowPendingTsdfCorrectionCellCount++;
            if (touchesProvisional)
                LastQuestRoomScanShadowProvisionalCellCount++;
        }

    }

