    private void RecordStableQuadTopologyAudit(StableQuadKey key, int a, int b, int c, int d, List<Vector3> vertices)
    {
        int winding = _forcedStableQuadAuditWindings.TryGetValue(key, out int forcedWinding)
            ? forcedWinding
            : StableQuadTsdfWinding(key);
        if (_stableQuadAuditRecords.TryGetValue(key, out StableQuadAuditRecord existing))
        {
            LastStableQuadAuditDuplicateKeyCount++;
            if (existing.Winding != 0 && winding != 0 && existing.Winding != winding)
                LastStableQuadAuditReverseWindingDuplicateCount++;
            return;
        }

        StableQuadAuditRecord record = new StableQuadAuditRecord
        {
            Key = key,
            A = a,
            B = b,
            C = c,
            D = d,
            Winding = winding,
            RestoredByAtomicProvisionalBacking =
                _atomicProvisionalBackingRestoredVertexIndices.Contains(a) ||
                _atomicProvisionalBackingRestoredVertexIndices.Contains(b) ||
                _atomicProvisionalBackingRestoredVertexIndices.Contains(c) ||
                _atomicProvisionalBackingRestoredVertexIndices.Contains(d)
        };
        if (record.RestoredByAtomicProvisionalBacking)
            LastAtomicProvisionalBackingRestoredQuadCount++;
        if (vertices != null && a < vertices.Count && b < vertices.Count && c < vertices.Count && d < vertices.Count)
        {
            Vector3 va = vertices[a];
            Vector3 vb = vertices[b];
            Vector3 vc = vertices[c];
            Vector3 vd = vertices[d];
            record.Center = (va + vb + vc + vd) * 0.25f;
            Vector3 normal = Vector3.Cross(vb - va, vc - va) + Vector3.Cross(vc - va, vd - va);
            record.Normal = normal.sqrMagnitude > 0.0000000001f ? normal.normalized : Vector3.zero;
        }
        CountStableQuadEndpointStates(key, ref record);
        _stableQuadAuditRecords.Add(key, record);
        AddStableQuadAuditEdge(a, b, key);
        AddStableQuadAuditEdge(b, c, key);
        AddStableQuadAuditEdge(c, d, key);
        AddStableQuadAuditEdge(d, a, key);
        LastStableQuadAuditUniqueCount = _stableQuadAuditRecords.Count;
    }

    private int StableQuadTsdfWinding(StableQuadKey key)
    {
        if (_tsdf == null || key.X < 0 || key.Y < 0 || key.Z < 0 ||
            key.X >= _dimX || key.Y >= _dimY || key.Z >= _dimZ)
            return 0;
        int bx = key.X + (key.Axis == 0 ? 1 : 0);
        int by = key.Y + (key.Axis == 1 ? 1 : 0);
        int bz = key.Z + (key.Axis == 2 ? 1 : 0);
        if (bx >= _dimX || by >= _dimY || bz >= _dimZ)
            return 0;
        float first = _tsdf[Index(key.X, key.Y, key.Z)];
        float second = _tsdf[Index(bx, by, bz)];
        if (first < 0f && second > 0f)
            return 1;
        if (first > 0f && second < 0f)
            return -1;
        return 0;
    }

    private void CountStableQuadEndpointStates(StableQuadKey key, ref StableQuadAuditRecord record)
    {
        for (int endpoint = 0; endpoint < 2; endpoint++)
        {
            int x = key.X + (endpoint == 1 && key.Axis == 0 ? 1 : 0);
            int y = key.Y + (endpoint == 1 && key.Axis == 1 ? 1 : 0);
            int z = key.Z + (endpoint == 1 && key.Axis == 2 ? 1 : 0);
            if (x < 0 || y < 0 || z < 0 || x >= _dimX || y >= _dimY || z >= _dimZ)
                continue;
            int index = Index(x, y, z);
            if (HasProvisionalTsdfMarker(index))
                record.ProvisionalCorners++;
            if (VoxelHasPendingTsdfCorrection(index))
                record.PendingCorners++;
            if (VoxelIsDirtyQuarantined(index))
                record.DirtyCorners++;
        }
    }

    private void AddStableQuadAuditEdge(int a, int b, StableQuadKey key)
    {
        ulong edge = EdgeKey(a, b);
        if (!_stableQuadAuditEdges.TryGetValue(edge, out List<StableQuadKey> quads))
        {
            quads = new List<StableQuadKey>(2);
            _stableQuadAuditEdges.Add(edge, quads);
        }
        quads.Add(key);
    }

    private void FinalizeStableQuadTopologyAudit(List<int> renderTriangles, List<Vector3> vertices)
    {
        foreach (KeyValuePair<StableQuadKey, StableQuadAuditRecord> pair in _stableQuadAuditRecords)
        {
            if (_previousStableQuadAuditRecords.TryGetValue(pair.Key, out StableQuadAuditRecord previous))
            {
                LastStableQuadAuditPersistedCount++;
                if (previous.Winding != 0 && pair.Value.Winding != 0 && previous.Winding != pair.Value.Winding)
                {
                    LastStableQuadAuditWindingChangedCount++;
                    _lastStableQuadWindingChanged.Add(pair.Key);
                }
            }
            else
            {
                LastStableQuadAuditAddedCount++;
                _lastStableQuadAdded.Add(pair.Key);
            }
        }
        foreach (StableQuadKey key in _previousStableQuadAuditRecords.Keys)
        {
            if (_stableQuadAuditRecords.ContainsKey(key))
                continue;
            LastStableQuadAuditRemovedCount++;
            _lastStableQuadRemoved.Add(key);
        }

        LastStableQuadAuditLogicalEdgeCount = _stableQuadAuditEdges.Count;
        foreach (KeyValuePair<ulong, List<StableQuadKey>> pair in _stableQuadAuditEdges)
        {
            int count = pair.Value != null ? pair.Value.Count : 0;
            LastStableQuadAuditMaxQuadsPerEdge = Mathf.Max(LastStableQuadAuditMaxQuadsPerEdge, count);
            if (count == 1)
            {
                LastStableQuadAuditBoundaryEdgeCount++;
                RecordSpatialRuptureBoundaryEdge(pair.Key, pair.Value[0], vertices);
                if (_heldProvisionalRetainedKeys.Contains(pair.Value[0]))
                    LastProvisionalHeldRetentionBoundaryEdgeCount++;
                if (_stableQuadAuditRecords.TryGetValue(pair.Value[0], out StableQuadAuditRecord boundaryQuad) &&
                    boundaryQuad.RestoredByAtomicProvisionalBacking)
                {
                    LastAtomicProvisionalBackingRestoredBoundaryEdgeCount++;
                }
            }
            else if (count == 2)
                LastStableQuadAuditManifoldEdgeCount++;
            else if (count > 2)
            {
                LastStableQuadAuditConflictEdgeCount++;
                bool positive = false;
                bool negative = false;
                bool touchesRestoredQuad = false;
                bool touchesHeldProvisional = false;
                for (int i = 0; i < pair.Value.Count; i++)
                {
                    if (!_stableQuadAuditRecords.TryGetValue(pair.Value[i], out StableQuadAuditRecord record))
                        continue;
                    positive |= record.Winding > 0;
                    negative |= record.Winding < 0;
                    touchesRestoredQuad |= record.RestoredByAtomicProvisionalBacking;
                    touchesHeldProvisional |= _heldProvisionalRetainedKeys.Contains(pair.Value[i]);
                }
                if (positive && negative)
                    LastStableQuadAuditCompetingLayerEdgeCount++;
                if (touchesRestoredQuad)
                    LastAtomicProvisionalBackingRestoredConflictEdgeCount++;
                if (touchesHeldProvisional)
                    LastProvisionalHeldRetentionConflictEdgeCount++;
            }
        }

        if (doubleSidedTriangles && renderTriangles != null)
        {
            Dictionary<ulong, int> renderEdgeUse = BuildMeshEdgeUseCounts(renderTriangles);
            foreach (int count in renderEdgeUse.Values)
            {
                if (count > 2 && count <= 4)
                    LastStableQuadAuditDoubleSidedFalsePositiveEdgeCount++;
            }
        }

        ValidateAtomicStableQuadInheritancePatches();
        bool displayBootstrap = allowStableQuadDisplayBootstrap &&
                                _previousStableQuadAuditRecords.Count == 0;
        EvaluateStableIncrementalQuadShadow(vertices);
        ApplyStableQuadShadowDisplayGate(renderTriangles, displayBootstrap);

        _pendingStableQuadHistoryRecords.Clear();
        foreach (KeyValuePair<StableQuadKey, StableQuadAuditRecord> pair in _stableQuadAuditRecords)
        {
            if (_stableQuadDisplayedKeys.Contains(pair.Key))
                _pendingStableQuadHistoryRecords.Add(pair.Key, pair.Value);
        }
        LastStableQuadHistoryPendingCount = _pendingStableQuadHistoryRecords.Count;
    }

    private void ValidateAtomicStableQuadInheritancePatches()
    {
        if (!requireAtomicStableQuadInheritancePatch || _stableQuadInheritanceMap.Count <= 0)
            return;

        Dictionary<int, List<StableQuadKey>> vertexToInherited = new Dictionary<int, List<StableQuadKey>>();
        foreach (StableQuadKey key in _stableQuadInheritanceMap.Keys)
        {
            if (!_stableQuadAuditRecords.TryGetValue(key, out StableQuadAuditRecord record))
                continue;
            AddInheritedQuadVertex(record.A, key, vertexToInherited);
            AddInheritedQuadVertex(record.B, key, vertexToInherited);
            AddInheritedQuadVertex(record.C, key, vertexToInherited);
            AddInheritedQuadVertex(record.D, key, vertexToInherited);
        }

        HashSet<StableQuadKey> visited = new HashSet<StableQuadKey>();
        Queue<StableQuadKey> queue = new Queue<StableQuadKey>();
        int minPatch = Mathf.Clamp(minAtomicStableQuadInheritancePatchQuads, 2, 8);
        foreach (StableQuadKey start in _stableQuadInheritanceMap.Keys)
        {
            if (!visited.Add(start) || !_stableQuadAuditRecords.ContainsKey(start))
                continue;

            List<StableQuadKey> patch = new List<StableQuadKey>(8);
            queue.Enqueue(start);
            while (queue.Count > 0)
            {
                StableQuadKey current = queue.Dequeue();
                patch.Add(current);
                if (!_stableQuadAuditRecords.TryGetValue(current, out StableQuadAuditRecord record))
                    continue;
                EnqueueInheritedQuadNeighbors(record.A, vertexToInherited, visited, queue);
                EnqueueInheritedQuadNeighbors(record.B, vertexToInherited, visited, queue);
                EnqueueInheritedQuadNeighbors(record.C, vertexToInherited, visited, queue);
                EnqueueInheritedQuadNeighbors(record.D, vertexToInherited, visited, queue);
            }

            LastStableQuadInheritancePatchCount++;
            if (patch.Count >= minPatch)
            {
                LastStableQuadInheritanceAtomicAcceptedCount += patch.Count;
                continue;
            }

            for (int i = 0; i < patch.Count; i++)
            {
                StableQuadKey currentKey = patch[i];
                if (!_stableQuadInheritanceMap.TryGetValue(currentKey, out StableQuadKey previousKey) ||
                    !_stableQuadShadowStates.TryGetValue(currentKey, out StableQuadShadowState migrated))
                    continue;
                _stableQuadShadowStates.Remove(currentKey);
                _stableQuadShadowStates[previousKey] = migrated;
                _stableQuadInheritedPreviousKeys.Remove(previousKey);
                LastStableQuadInheritanceAtomicRollbackCount++;
            }
        }
    }

    private static void AddInheritedQuadVertex(
        int vertex, StableQuadKey key, Dictionary<int, List<StableQuadKey>> vertexToInherited)
    {
        if (!vertexToInherited.TryGetValue(vertex, out List<StableQuadKey> keys))
        {
            keys = new List<StableQuadKey>(4);
            vertexToInherited.Add(vertex, keys);
        }
        keys.Add(key);
    }

    private static void EnqueueInheritedQuadNeighbors(
        int vertex,
        Dictionary<int, List<StableQuadKey>> vertexToInherited,
        HashSet<StableQuadKey> visited,
        Queue<StableQuadKey> queue)
    {
        if (!vertexToInherited.TryGetValue(vertex, out List<StableQuadKey> keys))
            return;
        for (int i = 0; i < keys.Count; i++)
        {
            if (visited.Add(keys[i]))
                queue.Enqueue(keys[i]);
        }
    }

    private void ApplyStableQuadShadowDisplayGate(List<int> renderTriangles, bool bootstrap)
    {
        _stableQuadDisplayedKeys.Clear();
        if (renderTriangles == null || !enableStableIncrementalQuadShadow ||
            !gateNewbornQuadDisplayByShadowMaturity)
        {
            foreach (StableQuadKey key in _stableQuadAuditRecords.Keys)
                _stableQuadDisplayedKeys.Add(key);
            return;
        }

        renderTriangles.Clear();
        foreach (KeyValuePair<StableQuadKey, StableQuadAuditRecord> pair in _stableQuadAuditRecords)
        {
            StableQuadKey key = pair.Key;
            StableQuadAuditRecord record = pair.Value;
            if (_stableQuadShadowConflictBlocked.Contains(key))
            {
                LastStableQuadDisplayWithheldConflictCount++;
                continue;
            }

            bool accepted = bootstrap;
            if (!accepted)
            {
                if (!_stableQuadShadowStates.TryGetValue(key, out StableQuadShadowState state))
                {
                    LastStableQuadDisplayWithheldMissingStateCount++;
                    continue;
                }
                if (state.Winding != 0 && record.Winding != 0 && state.Winding != record.Winding)
                {
                    LastStableQuadDisplayWithheldWindingCount++;
                    continue;
                }
                if (!state.Committed)
                {
                    LastStableQuadDisplayWithheldCandidateCount++;
                    continue;
                }
                accepted = true;
            }

            if (!accepted)
                continue;
            AddStableQuadRecordTriangles(record, renderTriangles);
            _stableQuadDisplayedKeys.Add(key);
            LastStableQuadDisplayAcceptedQuadCount++;
            if (bootstrap)
                LastStableQuadDisplayBootstrapQuadCount++;
        }
    }

    private void AddStableQuadRecordTriangles(StableQuadAuditRecord record, List<int> triangles)
    {
        triangles.Add(record.A);
        triangles.Add(record.B);
        triangles.Add(record.C);
        triangles.Add(record.A);
        triangles.Add(record.C);
        triangles.Add(record.D);
        if (!doubleSidedTriangles)
            return;
        triangles.Add(record.C);
        triangles.Add(record.B);
        triangles.Add(record.A);
        triangles.Add(record.D);
        triangles.Add(record.C);
        triangles.Add(record.A);
    }

    private void RecordSpatialRuptureBoundaryEdge(ulong edgeKey, StableQuadKey quadKey, List<Vector3> vertices)
    {
        if (!writeSpatialRuptureDiagnostics || vertices == null)
            return;
        DecodeEdgeKey(edgeKey, out int a, out int b);
        if (a < 0 || b < 0 || a >= vertices.Count || b >= vertices.Count)
            return;

        Vector3 pointA = vertices[a];
        Vector3 pointB = vertices[b];
        Vector3 midpoint = (pointA + pointB) * 0.5f;
        SpatialRuptureRecord record = new SpatialRuptureRecord
        {
            VertexA = a,
            VertexB = b,
            PointA = pointA,
            PointB = pointB,
            Midpoint = midpoint,
            Length = Vector3.Distance(pointA, pointB),
            QuadKey = quadKey
        };
        if (_stableQuadAuditRecords.TryGetValue(quadKey, out StableQuadAuditRecord quad))
            record.QuadNormal = quad.Normal;

        record.HasCoverage = TryFindNearestRawCoverageCell(midpoint, out record.CoverageKey,
            out record.CoverageLookupRadius, out record.Coverage);
        FindSpatialArbitration(midpoint, out record.Arbitration);
        if (TryWorldToVoxel(midpoint, out int vx, out int vy, out int vz))
        {
            record.VoxelX = vx;
            record.VoxelY = vy;
            record.VoxelZ = vz;
            int index = Index(vx, vy, vz);
            record.Tsdf = _tsdf[index];
            record.Weight = _weights[index];
            record.Provisional = HasProvisionalTsdfMarker(index);
            record.Pending = VoxelHasPendingTsdfCorrection(index);
            record.Dirty = VoxelIsDirtyQuarantined(index);
            record.PlaneReject = FindNearestPlaneRepairReject(vx, vy, vz);
        }
        else
        {
            record.VoxelX = record.VoxelY = record.VoxelZ = -1;
        }

        ClassifySpatialRupture(ref record);
        _spatialRuptureRecords.Add(record);
        LastSpatialRuptureBoundaryEdgeCount++;
    }

    private bool TryFindNearestRawCoverageCell(Vector3 world, out Vector3Int bestKey, out int bestRadius,
        out RawCoverageGridCell bestCell)
    {
        Vector3Int center = RawCoverageGridKey(world);
        bestKey = center;
        bestRadius = -1;
        bestCell = default;
        float bestDistance = float.PositiveInfinity;
        int maxRadius = Mathf.Clamp(spatialRuptureLookupRadiusCells, 0, 3);
        for (int radius = 0; radius <= maxRadius; radius++)
        {
            bool foundAtRadius = false;
            for (int z = -radius; z <= radius; z++)
            for (int y = -radius; y <= radius; y++)
            for (int x = -radius; x <= radius; x++)
            {
                if (radius > 0 && Mathf.Max(Mathf.Abs(x), Mathf.Abs(y), Mathf.Abs(z)) != radius)
                    continue;
                Vector3Int key = center + new Vector3Int(x, y, z);
                if (!_rawCoverageGridCells.TryGetValue(key, out RawCoverageGridCell cell))
                    continue;
                int total = cell.AcceptedCount + cell.ProblemCount;
                if (total <= 0)
                    continue;
                float distance = Vector3.SqrMagnitude(cell.PositionSum / total - world);
                if (distance >= bestDistance)
                    continue;
                bestDistance = distance;
                bestKey = key;
                bestCell = cell;
                bestRadius = radius;
                foundAtRadius = true;
            }
            if (foundAtRadius)
                return true;
        }
        return false;
    }

    private void FindSpatialArbitration(Vector3 world, out SpatialArbitrationCell result)
    {
        result = default;
        Vector3Int center = RawCoverageGridKey(world);
        int maxRadius = Mathf.Clamp(spatialRuptureLookupRadiusCells, 0, 3);
        for (int z = -maxRadius; z <= maxRadius; z++)
        for (int y = -maxRadius; y <= maxRadius; y++)
        for (int x = -maxRadius; x <= maxRadius; x++)
        {
            if (!_spatialArbitrationCells.TryGetValue(center + new Vector3Int(x, y, z), out SpatialArbitrationCell cell))
                continue;
            result.LayerCount += cell.LayerCount;
            result.TopologyCount += cell.TopologyCount;
            result.WindingCount += cell.WindingCount;
        }
    }

    private PrimaryPlaneHoleRejectReason FindNearestPlaneRepairReject(int cx, int cy, int cz)
    {
        for (int radius = 0; radius <= 1; radius++)
        for (int z = -radius; z <= radius; z++)
        for (int y = -radius; y <= radius; y++)
        for (int x = -radius; x <= radius; x++)
        {
            int vx = cx + x;
            int vy = cy + y;
            int vz = cz + z;
            if (vx < 0 || vy < 0 || vz < 0 || vx >= _dimX || vy >= _dimY || vz >= _dimZ)
                continue;
            if (_spatialPlaneRepairRejects.TryGetValue(Index(vx, vy, vz), out PrimaryPlaneHoleRejectReason reason))
                return reason;
        }
        return PrimaryPlaneHoleRejectReason.None;
    }

    private void ClassifySpatialRupture(ref SpatialRuptureRecord record)
    {
        int arbitration = record.Arbitration.LayerCount + record.Arbitration.TopologyCount + record.Arbitration.WindingCount;
        string rawCause = record.HasCoverage ? DominantRawCoverageCause(record.Coverage) : "none";
        if (arbitration > 0)
        {
            record.RootType = "mesh_arbitration";
            record.Subtype = record.Arbitration.LayerCount >= record.Arbitration.TopologyCount && record.Arbitration.LayerCount >= record.Arbitration.WindingCount
                ? "layer_block" : (record.Arbitration.TopologyCount >= record.Arbitration.WindingCount ? "topology_block" : "winding_block");
            LastSpatialRuptureArbitrationCount++;
        }
        else if (!record.HasCoverage)
        {
            record.RootType = "raw_spatial_gap";
            record.Subtype = "no_world_sample_near_boundary";
            LastSpatialRuptureRawGapCount++;
        }
        else if (rawCause != "none")
        {
            record.RootType = "raw_filter";
            record.Subtype = rawCause;
            if (rawCause == "depth_discontinuity") LastSpatialRuptureDepthEdgeCount++;
            else if (rawCause == "robust_depth_outlier") LastSpatialRuptureRobustCount++;
            else if (rawCause == "insufficient_depth_support") LastSpatialRuptureSupportCount++;
            else if (rawCause == "view_angle_conflict") LastSpatialRuptureViewConflictCount++;
            else LastSpatialRuptureOtherRawCount++;
        }
        else if (record.Weight <= 0 || record.Pending || record.Dirty || record.Provisional)
        {
            record.RootType = "tsdf_state";
            record.Subtype = record.Weight <= 0 ? "unobserved_voxel" :
                (record.Dirty ? "dirty_quarantine" : (record.Pending ? "pending_correction" : "provisional_not_promoted"));
            LastSpatialRuptureTsdfStateCount++;
        }
        else if (record.PlaneReject != PrimaryPlaneHoleRejectReason.None)
        {
            record.RootType = "plane_repair_reject";
            record.Subtype = record.PlaneReject.ToString();
            LastSpatialRupturePlaneRejectCount++;
        }
        else
        {
            record.RootType = "clean_boundary";
            record.Subtype = "zero_crossing_or_assembly_gap";
            LastSpatialRuptureTsdfStateCount++;
        }
    }

    private static string DominantRawCoverageCause(RawCoverageGridCell cell)
    {
        int best = 0;
        string cause = "none";
        if (cell.DepthEdgeCount > best) { best = cell.DepthEdgeCount; cause = "depth_discontinuity"; }
        if (cell.RobustCount > best) { best = cell.RobustCount; cause = "robust_depth_outlier"; }
        if (cell.SupportCount > best) { best = cell.SupportCount; cause = "insufficient_depth_support"; }
        if (cell.ConflictViewCount > best) { best = cell.ConflictViewCount; cause = "view_angle_conflict"; }
        if (cell.ConflictEdgeCount > best) { best = cell.ConflictEdgeCount; cause = "tsdf_depth_edge_conflict"; }
        if (cell.ConflictLockedCount > best) { best = cell.ConflictLockedCount; cause = "old_weight_locked"; }
        if (cell.PendingCount > best) { best = cell.PendingCount; cause = "pending_or_stability"; }
        if (cell.OutsideCount > best) { best = cell.OutsideCount; cause = "outside_volume"; }
        if (cell.BasicFilterCount > best) { best = cell.BasicFilterCount; cause = "basic_filter"; }
        if (cell.DepthNeighborhoodStageCount > best) { best = cell.DepthNeighborhoodStageCount; cause = "depth_neighborhood"; }
        if (cell.RobustPrefilterStageCount > best) { best = cell.RobustPrefilterStageCount; cause = "robust_prefilter"; }
        if (cell.TsdfSupportStageCount > best) { best = cell.TsdfSupportStageCount; cause = "tsdf_support"; }
        if (cell.VoteRejectCount > best) { best = cell.VoteRejectCount; cause = "vote_reject"; }
        if (cell.PendingHoldCount > best) { best = cell.PendingHoldCount; cause = "vote_pending_hold"; }
        if (cell.OutsideVolumeStageCount > best) { best = cell.OutsideVolumeStageCount; cause = "outside_volume"; }
        if (cell.AuditOutcomeStageCount > best) { best = cell.AuditOutcomeStageCount; cause = "audit_outcome"; }
        if (cell.FallbackWeakStageCount > best) { best = cell.FallbackWeakStageCount; cause = "fallback_weak"; }
        int otherBasic = Mathf.Max(0, cell.BasicRejectCount - cell.BasicFilterCount - cell.VoteRejectCount -
            cell.FallbackWeakStageCount - cell.AuditOutcomeStageCount);
        if (otherBasic > best || cell.OtherRejectCount > best) { cause = "other_reject"; }
        return cause;
    }

    private static float RawCoverageMeanDistance(RawCoverageGridCell cell)
    {
        return cell.CameraDistanceCount > 0 ? cell.CameraDistanceSum / cell.CameraDistanceCount : -1f;
    }

    private static float RawCoverageMeanViewFacing(RawCoverageGridCell cell)
    {
        return cell.ViewFacingCount > 0 ? Mathf.Clamp01(cell.ViewFacingSum / cell.ViewFacingCount) : -1f;
    }

    private static float RawCoverageMeanIncidenceDegrees(RawCoverageGridCell cell)
    {
        float facing = RawCoverageMeanViewFacing(cell);
        return facing >= 0f ? Mathf.Acos(Mathf.Clamp01(facing)) * Mathf.Rad2Deg : -1f;
    }

    private static string DominantRawCoverageAngleBand(RawCoverageGridCell cell)
    {
        int best = cell.FrontCount;
        string band = best > 0 ? "front_0_45" : "unknown";
        if (cell.ObliqueCount > best) { best = cell.ObliqueCount; band = "oblique_45_60"; }
        if (cell.GrazingCount > best) { best = cell.GrazingCount; band = "grazing_60_78"; }
        if (cell.ExtremeCount > best) { band = "extreme_78_90"; }
        return band;
    }

    private static string DominantRescuedGrazingVoteRejectReason(RawCoverageGridCell cell)
    {
        int best = 0;
        string reason = "none";
        if (cell.RescuedVoteWeakSupportCount > best) { best = cell.RescuedVoteWeakSupportCount; reason = "weak_support"; }
        if (cell.RescuedVoteDepthShiftCount > best) { best = cell.RescuedVoteDepthShiftCount; reason = "depth_shift"; }
        if (cell.RescuedVoteGrazingViewCount > best) { best = cell.RescuedVoteGrazingViewCount; reason = "grazing_view"; }
        if (cell.RescuedVoteLowWeightCount > best) { best = cell.RescuedVoteLowWeightCount; reason = "low_weight"; }
        if (cell.RescuedVoteTemporalJumpCount > best) { best = cell.RescuedVoteTemporalJumpCount; reason = "temporal_depth_jump"; }
        if (cell.RescuedVoteOffHistoryCount > best) { best = cell.RescuedVoteOffHistoryCount; reason = "off_history_surface"; }
        if (cell.RescuedVoteOldTsdfCount > best) { best = cell.RescuedVoteOldTsdfCount; reason = "old_tsdf_residual"; }
        if (cell.RescuedVoteWeakHistoryCount > best) { best = cell.RescuedVoteWeakHistoryCount; reason = "weak_history"; }
        if (cell.RescuedVoteBandConflictCount > best) { best = cell.RescuedVoteBandConflictCount; reason = "band_conflict"; }
        if (cell.RescuedVoteBandResidualCount > best) { best = cell.RescuedVoteBandResidualCount; reason = "band_residual"; }
        if (cell.RescuedVoteSameFrameConflictCount > best)
        {
            best = cell.RescuedVoteSameFrameConflictCount;
            reason = "same_frame_unknown_plane";
            int sameFrameBest = cell.RescuedVoteSameFrameUnknownPlaneCount;
            if (cell.RescuedVoteSameFrameSamePlaneGrazingCount > sameFrameBest)
            {
                sameFrameBest = cell.RescuedVoteSameFrameSamePlaneGrazingCount;
                reason = "same_frame_same_plane_grazing";
            }
            if (cell.RescuedVoteSameFrameCrossPlaneCount > sameFrameBest)
                reason = "same_frame_cross_plane";
        }
        if (cell.RescuedVoteCrossFrameConflictCount > best) { reason = "cross_frame_clean_conflict"; }
        return reason;
    }

    private void EvaluateStableIncrementalQuadShadow(List<Vector3> vertices)
    {
        if (!enableStableIncrementalQuadShadow)
            return;

        ResolveStableQuadShadowConflicts();
        ResolveStableQuadWorldSpaceConflicts(vertices);
        int promoteThreshold = Mathf.Clamp(stableQuadShadowPromoteRebuilds, 2, 6);
        int retainMissing = Mathf.Clamp(stableQuadShadowRetainMissingRebuilds, 1, 6);

        foreach (KeyValuePair<StableQuadKey, StableQuadAuditRecord> pair in _stableQuadAuditRecords)
        {
            StableQuadKey key = pair.Key;
            if (_heldProvisionalRetainedKeys.Contains(key))
                continue;
            if (_stableQuadShadowConflictBlocked.Contains(key))
                continue;

            if (!_stableQuadShadowStates.TryGetValue(key, out StableQuadShadowState state))
            {
                state.Winding = pair.Value.Winding;
            }
            else if (state.Winding != 0 && pair.Value.Winding != 0 && state.Winding != pair.Value.Winding)
            {
                LastStableQuadShadowWindingConflictCount++;
                continue;
            }

            state.Winding = pair.Value.Winding != 0 ? pair.Value.Winding : state.Winding;
            state.ConsecutivePresent++;
            state.ConsecutiveMissing = 0;
            state.TotalPresent++;
            if (!state.Committed && state.ConsecutivePresent >= promoteThreshold)
            {
                state.Committed = true;
                LastStableQuadShadowPromotedCount++;
            }
            _stableQuadShadowStates[key] = state;
            _stableQuadShadowObserved.Add(key);
        }

        List<StableQuadKey> stateKeys = new List<StableQuadKey>(_stableQuadShadowStates.Keys);
        for (int i = 0; i < stateKeys.Count; i++)
        {
            StableQuadKey key = stateKeys[i];
            if (_stableQuadShadowObserved.Contains(key))
                continue;
            StableQuadShadowState state = _stableQuadShadowStates[key];
            state.ConsecutivePresent = 0;
            state.ConsecutiveMissing++;
            if (!state.Committed)
            {
                _stableQuadShadowStates.Remove(key);
                continue;
            }
            if (state.ConsecutiveMissing > retainMissing)
            {
                _stableQuadShadowStates.Remove(key);
                LastStableQuadShadowRetiredCount++;
                continue;
            }
            _stableQuadShadowStates[key] = state;
            LastStableQuadShadowHeldMissingCount++;
            ClassifyStableQuadHeldEvidence(key, state);
        }

        foreach (StableQuadShadowState state in _stableQuadShadowStates.Values)
        {
            if (state.Committed)
                LastStableQuadShadowCommittedCount++;
            else
                LastStableQuadShadowCandidateCount++;
        }
        LastStableQuadShadowOutputQuadCount = LastStableQuadShadowCommittedCount;
    }

    private void ClassifyStableQuadHeldEvidence(StableQuadKey key, StableQuadShadowState state)
    {
        int bx = key.X + (key.Axis == 0 ? 1 : 0);
        int by = key.Y + (key.Axis == 1 ? 1 : 0);
        int bz = key.Z + (key.Axis == 2 ? 1 : 0);
        if (_tsdf == null || _weights == null || key.X < 0 || key.Y < 0 || key.Z < 0 ||
            bx < 0 || by < 0 || bz < 0 || key.X >= _dimX || key.Y >= _dimY || key.Z >= _dimZ ||
            bx >= _dimX || by >= _dimY || bz >= _dimZ)
        {
            LastStableQuadHeldUncertainCount++;
            LastStableQuadHeldTypeOtherUnsettledCount++;
            _stableQuadHeldEvidenceRecords.Add(new StableQuadHeldEvidenceRecord
            {
                Key = key,
                MissingRebuilds = state.ConsecutiveMissing,
                TotalPresent = state.TotalPresent,
                PreviousWinding = state.Winding,
                Classification = "held_other_unsettled",
                Reason = "endpoint_out_of_bounds"
            });
            return;
        }

        int indexA = Index(key.X, key.Y, key.Z);
        int indexB = Index(bx, by, bz);
        float tsdfA = _tsdf[indexA];
        float tsdfB = _tsdf[indexB];
        int weightA = _weights[indexA];
        int weightB = _weights[indexB];
        bool provisionalA = HasProvisionalTsdfMarker(indexA);
        bool provisionalB = HasProvisionalTsdfMarker(indexB);
        bool pendingA = VoxelHasPendingTsdfCorrection(indexA);
        bool pendingB = VoxelHasPendingTsdfCorrection(indexB);
        bool dirtyA = VoxelIsDirtyQuarantined(indexA);
        bool dirtyB = VoxelIsDirtyQuarantined(indexB);
        bool cleanA = IsCleanMeshTsdfVoxel(indexA);
        bool cleanB = IsCleanMeshTsdfVoxel(indexB);
        int currentWinding = StableQuadTsdfWinding(key);
        GetStableProvisionalPromotionBlock(indexA, out string promotionBlockerA, out int promotionBlockerAgeA);
        GetStableProvisionalPromotionBlock(indexB, out string promotionBlockerB, out int promotionBlockerAgeB);

        string classification;
        string reason;
        if (cleanA && cleanB && currentWinding != 0)
        {
            classification = "held_clean_assembly_loss";
            reason = provisionalA || provisionalB
                ? "clean_zero_crossing_preserved_under_atomic_provisional_not_assembled"
                : "clean_zero_crossing_not_assembled";
            LastStableQuadHeldSafeCount++;
            LastStableQuadHeldTypeCleanAssemblyLossCount++;
        }
        else if (provisionalA || provisionalB)
        {
            classification = "held_provisional_not_promoted";
            reason = currentWinding != 0 ? "provisional_crossing" : "provisional_no_crossing";
            LastStableQuadHeldUncertainCount++;
            LastStableQuadHeldTypeProvisionalNotPromotedCount++;
        }
        else if (pendingA || pendingB || dirtyA || dirtyB)
        {
            classification = "held_other_unsettled";
            reason = dirtyA || dirtyB ? "dirty_endpoint" : "pending_endpoint";
            LastStableQuadHeldUncertainCount++;
            LastStableQuadHeldTypeOtherUnsettledCount++;
        }
        else if (weightA < minSurfaceCornerWeight || weightB < minSurfaceCornerWeight)
        {
            classification = "held_other_unsettled";
            reason = "under_observed_endpoint";
            LastStableQuadHeldUncertainCount++;
            LastStableQuadHeldTypeOtherUnsettledCount++;
        }
        else if (float.IsNaN(tsdfA) || float.IsNaN(tsdfB) || float.IsInfinity(tsdfA) || float.IsInfinity(tsdfB))
        {
            classification = "held_other_unsettled";
            reason = "invalid_endpoint";
            LastStableQuadHeldUncertainCount++;
            LastStableQuadHeldTypeOtherUnsettledCount++;
        }
        else
        {
            int contradictionWeight = Mathf.Max(minSurfaceCornerWeight, minConflictVoxelWeight);
            float contradictionAbs = Mathf.Clamp01(stableQuadHeldContradictionMinAbsTsdf);
            bool sameSign = (tsdfA > 0f && tsdfB > 0f) || (tsdfA < 0f && tsdfB < 0f);
            bool strongSameSign = cleanA && cleanB && sameSign &&
                                  weightA >= contradictionWeight && weightB >= contradictionWeight &&
                                  Mathf.Abs(tsdfA) >= contradictionAbs && Mathf.Abs(tsdfB) >= contradictionAbs;
            if (strongSameSign)
            {
                classification = "held_confirmed_contradiction";
                reason = "clean_strong_same_sign";
                LastStableQuadHeldContradictedCount++;
                LastStableQuadHeldTypeConfirmedContradictionCount++;
            }
            else if (sameSign || Mathf.Approximately(tsdfA, 0f) || Mathf.Approximately(tsdfB, 0f))
            {
                classification = "held_near_zero_jitter";
                reason = "weak_or_near_surface_same_sign";
                LastStableQuadHeldUncertainCount++;
                LastStableQuadHeldTypeNearZeroJitterCount++;
            }
            else
            {
                classification = "held_other_unsettled";
                reason = "non_clean_crossing";
                LastStableQuadHeldUncertainCount++;
                LastStableQuadHeldTypeOtherUnsettledCount++;
            }
        }

        _stableQuadHeldEvidenceRecords.Add(new StableQuadHeldEvidenceRecord
        {
            Key = key,
            MissingRebuilds = state.ConsecutiveMissing,
            TotalPresent = state.TotalPresent,
            PreviousWinding = state.Winding,
            CurrentWinding = currentWinding,
            TsdfA = tsdfA,
            TsdfB = tsdfB,
            WeightA = weightA,
            WeightB = weightB,
            CleanA = cleanA,
            CleanB = cleanB,
            ProvisionalA = provisionalA,
            ProvisionalB = provisionalB,
            PendingA = pendingA,
            PendingB = pendingB,
            DirtyA = dirtyA,
            DirtyB = dirtyB,
            Classification = classification,
            Reason = reason,
            PromotionBlockerA = promotionBlockerA,
            PromotionBlockerB = promotionBlockerB,
            PromotionBlockerAgeA = promotionBlockerAgeA,
            PromotionBlockerAgeB = promotionBlockerAgeB
        });
    }

    private void GetStableProvisionalPromotionBlock(int index, out string blocker, out int ageFrames)
    {
        if (_provisionalPromotionBlockStates.TryGetValue(index, out ProvisionalPromotionBlockState state))
        {
            blocker = StableProvisionalPromotionBlockReasonName(state.ReasonCode);
            ageFrames = Mathf.Max(0, LastRawFrameIndex - state.Frame);
            return;
        }

        blocker = "no_promotion_attempt_recorded";
        ageFrames = -1;
    }

    private string GetStableQuadHeldDominantType()
    {
        string type = "none";
        int count = 0;
        if (LastStableQuadHeldTypeProvisionalNotPromotedCount > count)
        {
            type = "held_provisional_not_promoted";
            count = LastStableQuadHeldTypeProvisionalNotPromotedCount;
        }
        if (LastStableQuadHeldTypeNearZeroJitterCount > count)
        {
            type = "held_near_zero_jitter";
            count = LastStableQuadHeldTypeNearZeroJitterCount;
        }
        if (LastStableQuadHeldTypeConfirmedContradictionCount > count)
        {
            type = "held_confirmed_contradiction";
            count = LastStableQuadHeldTypeConfirmedContradictionCount;
        }
        if (LastStableQuadHeldTypeCleanAssemblyLossCount > count)
        {
            type = "held_clean_assembly_loss";
            count = LastStableQuadHeldTypeCleanAssemblyLossCount;
        }
        if (LastStableQuadHeldTypeOtherUnsettledCount > count)
            type = "held_other_unsettled";
        return type;
    }

    private void ResolveStableQuadShadowConflicts()
    {
        foreach (KeyValuePair<ulong, List<StableQuadKey>> pair in _stableQuadAuditEdges)
        {
            List<StableQuadKey> quads = pair.Value;
            if (quads == null || quads.Count <= 2)
                continue;

            LastStableQuadShadowConflictResolvedEdgeCount++;
            int bestA = -1;
            int bestB = -1;
            float bestScore = float.NegativeInfinity;
            for (int i = 0; i < quads.Count; i++)
            for (int j = i + 1; j < quads.Count; j++)
            {
                if (!_stableQuadAuditRecords.TryGetValue(quads[i], out StableQuadAuditRecord a) ||
                    !_stableQuadAuditRecords.TryGetValue(quads[j], out StableQuadAuditRecord b))
                    continue;
                float normalScore = a.Normal.sqrMagnitude > 0f && b.Normal.sqrMagnitude > 0f
                    ? Mathf.Abs(Vector3.Dot(a.Normal, b.Normal)) * 10f
                    : 0f;
                float committedScore = StableQuadShadowCommittedBonus(quads[i]) + StableQuadShadowCommittedBonus(quads[j]);
                float persistedScore = (_previousStableQuadAuditRecords.ContainsKey(quads[i]) ? 1f : 0f) +
                                       (_previousStableQuadAuditRecords.ContainsKey(quads[j]) ? 1f : 0f);
                float score = normalScore + committedScore + persistedScore;
                if (score <= bestScore)
                    continue;
                bestScore = score;
                bestA = i;
                bestB = j;
            }

            for (int i = 0; i < quads.Count; i++)
            {
                if (i == bestA || i == bestB)
                    continue;
                _stableQuadShadowConflictBlocked.Add(quads[i]);
            }
        }
        LastStableQuadShadowConflictBlockedQuadCount = _stableQuadShadowConflictBlocked.Count;
    }

    private void ResolveStableQuadWorldSpaceConflicts(List<Vector3> vertices)
    {
        if (!enableStableQuadWorldSpaceArbitration || vertices == null ||
            _stableQuadAuditRecords.Count <= 1)
            return;

        float maxCenter = voxelSizeMeters * stableQuadWorldConflictCenterVoxelScale;
        float maxCenterSq = maxCenter * maxCenter;
        float maxPlane = voxelSizeMeters * stableQuadWorldDuplicatePlaneVoxelScale;
        List<StableQuadKey> keys = new List<StableQuadKey>(_stableQuadAuditRecords.Keys);
        for (int keyIndex = 0; keyIndex < keys.Count; keyIndex++)
        {
            StableQuadKey leftKey = keys[keyIndex];
            if (!_stableQuadAuditRecords.TryGetValue(leftKey, out StableQuadAuditRecord left))
                continue;
            for (int dz = -1; dz <= 1; dz++)
            for (int dy = -1; dy <= 1; dy++)
            for (int dx = -1; dx <= 1; dx++)
            for (byte axis = 0; axis < 3; axis++)
            {
                StableQuadKey rightKey = new StableQuadKey
                {
                    X = leftKey.X + dx,
                    Y = leftKey.Y + dy,
                    Z = leftKey.Z + dz,
                    Axis = axis
                };
                if (CompareStableQuadKeys(leftKey, rightKey) >= 0 ||
                    !_stableQuadAuditRecords.TryGetValue(rightKey, out StableQuadAuditRecord right) ||
                    StableQuadRecordsShareVertex(left, right))
                    continue;

                LastStableQuadWorldPairCheckedCount++;
                Vector3 centerDelta = right.Center - left.Center;
                if (centerDelta.sqrMagnitude > maxCenterSq ||
                    !QuadBoundsOverlap(left, right, vertices, voxelSizeMeters * 0.05f))
                    continue;

                float normalDot = Mathf.Abs(Vector3.Dot(left.Normal, right.Normal));
                float planeSeparation = Mathf.Max(
                    Mathf.Abs(Vector3.Dot(centerDelta, left.Normal)),
                    Mathf.Abs(Vector3.Dot(centerDelta, right.Normal)));
                bool duplicateLayer = normalDot >= 0.9f && planeSeparation <= maxPlane;
                bool interiorIntersection = !duplicateLayer && normalDot <= 0.75f &&
                                            QuadsHaveInteriorIntersection(left, right, vertices);
                if (!duplicateLayer && !interiorIntersection)
                    continue;

                float leftPriority = StableQuadWorldPriority(leftKey, left);
                float rightPriority = StableQuadWorldPriority(rightKey, right);
                StableQuadKey loser;
                if (_stableQuadShadowConflictBlocked.Contains(leftKey))
                    loser = leftKey;
                else if (_stableQuadShadowConflictBlocked.Contains(rightKey))
                    loser = rightKey;
                else
                    loser = leftPriority > rightPriority ||
                            (Mathf.Approximately(leftPriority, rightPriority) &&
                             CompareStableQuadKeys(leftKey, rightKey) < 0)
                        ? rightKey
                        : leftKey;
                if (_stableQuadShadowConflictBlocked.Add(loser))
                    LastStableQuadWorldBlockedQuadCount++;
                if (duplicateLayer)
                    LastStableQuadWorldDuplicateConflictCount++;
                else
                    LastStableQuadWorldIntersectionConflictCount++;
            }
        }
        LastStableQuadShadowConflictBlockedQuadCount = _stableQuadShadowConflictBlocked.Count;
    }

    private float StableQuadWorldPriority(StableQuadKey key, StableQuadAuditRecord record)
    {
        float score = 0f;
        if (_stableQuadShadowStates.TryGetValue(key, out StableQuadShadowState state))
        {
            if (state.Committed)
                score += 1000f;
            score += Mathf.Min(100, state.TotalPresent) * 2f;
        }
        if (_previousStableQuadAuditRecords.ContainsKey(key))
            score += 200f;
        score -= record.DirtyCorners * 100f;
        score -= record.PendingCorners * 50f;
        score -= record.ProvisionalCorners * 20f;
        return score;
    }

    private static bool StableQuadRecordsShareVertex(StableQuadAuditRecord a, StableQuadAuditRecord b)
    {
        return a.A == b.A || a.A == b.B || a.A == b.C || a.A == b.D ||
               a.B == b.A || a.B == b.B || a.B == b.C || a.B == b.D ||
               a.C == b.A || a.C == b.B || a.C == b.C || a.C == b.D ||
               a.D == b.A || a.D == b.B || a.D == b.C || a.D == b.D;
    }

    private static bool QuadBoundsOverlap(
        StableQuadAuditRecord a, StableQuadAuditRecord b, List<Vector3> vertices, float padding)
    {
        if (!TryGetStableQuadBounds(a, vertices, out Vector3 minA, out Vector3 maxA) ||
            !TryGetStableQuadBounds(b, vertices, out Vector3 minB, out Vector3 maxB))
            return false;
        return minA.x - padding <= maxB.x && maxA.x + padding >= minB.x &&
               minA.y - padding <= maxB.y && maxA.y + padding >= minB.y &&
               minA.z - padding <= maxB.z && maxA.z + padding >= minB.z;
    }

    private static bool TryGetStableQuadBounds(
        StableQuadAuditRecord record, List<Vector3> vertices, out Vector3 min, out Vector3 max)
    {
        min = max = Vector3.zero;
        if (vertices == null || record.A < 0 || record.B < 0 || record.C < 0 || record.D < 0 ||
            record.A >= vertices.Count || record.B >= vertices.Count ||
            record.C >= vertices.Count || record.D >= vertices.Count)
            return false;
        min = Vector3.Min(Vector3.Min(vertices[record.A], vertices[record.B]),
            Vector3.Min(vertices[record.C], vertices[record.D]));
        max = Vector3.Max(Vector3.Max(vertices[record.A], vertices[record.B]),
            Vector3.Max(vertices[record.C], vertices[record.D]));
        return true;
    }

    private static bool QuadsHaveInteriorIntersection(
        StableQuadAuditRecord a, StableQuadAuditRecord b, List<Vector3> vertices)
    {
        Vector3[] qa = { vertices[a.A], vertices[a.B], vertices[a.C], vertices[a.D] };
        Vector3[] qb = { vertices[b.A], vertices[b.B], vertices[b.C], vertices[b.D] };
        for (int edge = 0; edge < 4; edge++)
        {
            Vector3 p0 = qa[edge];
            Vector3 p1 = qa[(edge + 1) & 3];
            if (SegmentIntersectsTriangleInterior(p0, p1, qb[0], qb[1], qb[2]) ||
                SegmentIntersectsTriangleInterior(p0, p1, qb[0], qb[2], qb[3]))
                return true;
            p0 = qb[edge];
            p1 = qb[(edge + 1) & 3];
            if (SegmentIntersectsTriangleInterior(p0, p1, qa[0], qa[1], qa[2]) ||
                SegmentIntersectsTriangleInterior(p0, p1, qa[0], qa[2], qa[3]))
                return true;
        }
        return false;
    }

    private static bool SegmentIntersectsTriangleInterior(
        Vector3 p0, Vector3 p1, Vector3 a, Vector3 b, Vector3 c)
    {
        Vector3 direction = p1 - p0;
        Vector3 edge1 = b - a;
        Vector3 edge2 = c - a;
        Vector3 cross = Vector3.Cross(direction, edge2);
        float determinant = Vector3.Dot(edge1, cross);
        if (Mathf.Abs(determinant) < 0.0000001f)
            return false;
        float inverse = 1f / determinant;
        Vector3 offset = p0 - a;
        float u = Vector3.Dot(offset, cross) * inverse;
        Vector3 q = Vector3.Cross(offset, edge1);
        float v = Vector3.Dot(direction, q) * inverse;
        float t = Vector3.Dot(edge2, q) * inverse;
        const float interior = 0.05f;
        return t > interior && t < 1f - interior &&
               u > interior && v > interior && u + v < 1f - interior;
    }

    private float StableQuadShadowCommittedBonus(StableQuadKey key)
    {
        return _stableQuadShadowStates.TryGetValue(key, out StableQuadShadowState state) && state.Committed ? 4f : 0f;
    }

