            csv.Append(r.NewbornKey.X).Append(',').Append(r.NewbornKey.Y).Append(',').Append(r.NewbornKey.Z).Append(',').Append(StableQuadAxisName(r.NewbornKey.Axis)).Append(',')
                .Append(r.PholdKey.X).Append(',').Append(r.PholdKey.Y).Append(',').Append(r.PholdKey.Z).Append(',').Append(StableQuadAxisName(r.PholdKey.Axis)).Append(',')
                .Append(r.EventName).AppendLine();
        }
        return csv;
    }

    private static string StableQuadAxisName(byte axis)
    {
        return axis == 0 ? "X" : (axis == 1 ? "Y" : "Z");
    }

    private bool PassExtractedQuadGeometryGate(int a, int b, int c, int d, List<Vector3> vertices)
    {
        if (!enableLegacyTentPrevention && !rejectStretchedExtractedQuads)
            return true;

        LastLegacyTentQuadCheckedCount++;
        ExtractedQuadGeometryRejectReason rejectReason = EvaluateExtractedQuadGeometry(a, b, c, d, vertices);
        if (rejectReason == ExtractedQuadGeometryRejectReason.None)
        {
            LastLegacyTentQuadAcceptedCount++;
            return true;
        }

        switch (rejectReason)
        {
            case ExtractedQuadGeometryRejectReason.Invalid:
                LastLegacyTentQuadRejectedInvalidCount++;
                break;
            case ExtractedQuadGeometryRejectReason.Edge:
                LastLegacyTentQuadRejectedEdgeCount++;
                break;
            case ExtractedQuadGeometryRejectReason.Diagonal:
                LastLegacyTentQuadRejectedDiagonalCount++;
                break;
            case ExtractedQuadGeometryRejectReason.Area:
                LastLegacyTentQuadRejectedAreaCount++;
                break;
            case ExtractedQuadGeometryRejectReason.Twist:
                LastLegacyTentQuadRejectedTwistCount++;
                break;
            case ExtractedQuadGeometryRejectReason.Plane:
                LastLegacyTentQuadRejectedPlaneCount++;
                break;
        }
        return false;
    }

    private ExtractedQuadGeometryRejectReason EvaluateExtractedQuadGeometry(
        int a, int b, int c, int d, List<Vector3> vertices)
    {
        if (vertices == null ||
            a < 0 || b < 0 || c < 0 || d < 0 ||
            a >= vertices.Count || b >= vertices.Count || c >= vertices.Count || d >= vertices.Count ||
            a == b || a == c || a == d || b == c || b == d || c == d)
            return ExtractedQuadGeometryRejectReason.Invalid;

        Vector3 va = vertices[a];
        Vector3 vb = vertices[b];
        Vector3 vc = vertices[c];
        Vector3 vd = vertices[d];
        if (!Finite(va) || !Finite(vb) || !Finite(vc) || !Finite(vd))
            return ExtractedQuadGeometryRejectReason.Invalid;

        float maxEdge = Mathf.Max(0.03f, voxelSizeMeters * maxExtractedQuadEdgeVoxelScale);
        float maxEdgeSq = maxEdge * maxEdge;
        if ((va - vb).sqrMagnitude > maxEdgeSq ||
            (vb - vc).sqrMagnitude > maxEdgeSq ||
            (vc - vd).sqrMagnitude > maxEdgeSq ||
            (vd - va).sqrMagnitude > maxEdgeSq)
            return ExtractedQuadGeometryRejectReason.Edge;

        if (enableLegacyTentPrevention)
        {
            float maxDiagonal = Mathf.Max(maxEdge, voxelSizeMeters * maxExtractedQuadDiagonalVoxelScale);
            float maxDiagonalSq = maxDiagonal * maxDiagonal;
            if ((va - vc).sqrMagnitude > maxDiagonalSq ||
                (vb - vd).sqrMagnitude > maxDiagonalSq)
                return ExtractedQuadGeometryRejectReason.Diagonal;
        }

        Vector3 cross0 = Vector3.Cross(vb - va, vc - va);
        Vector3 cross1 = Vector3.Cross(vc - va, vd - va);
        float area0 = cross0.magnitude * 0.5f;
        float area1 = cross1.magnitude * 0.5f;
        float minArea = voxelSizeMeters * voxelSizeMeters *
                        (enableLegacyTentPrevention ? minExtractedQuadTriangleAreaVoxelSquared : 0.005f);
        if (area0 < minArea || area1 < minArea)
            return ExtractedQuadGeometryRejectReason.Area;

        if (!enableLegacyTentPrevention)
            return ExtractedQuadGeometryRejectReason.None;

        Vector3 normal0 = cross0.normalized;
        Vector3 normal1 = cross1.normalized;
        if (Vector3.Dot(normal0, normal1) < minExtractedQuadTriangleNormalDot)
            return ExtractedQuadGeometryRejectReason.Twist;

        Vector3 planeNormal = cross0 + cross1;
        if (!Finite(planeNormal) || planeNormal.sqrMagnitude < 0.00000001f)
            return ExtractedQuadGeometryRejectReason.Area;
        planeNormal.Normalize();
        Vector3 center = (va + vb + vc + vd) * 0.25f;
        float maxPlaneResidual = voxelSizeMeters * maxExtractedQuadPlaneResidualVoxelScale;
        if (Mathf.Abs(Vector3.Dot(va - center, planeNormal)) > maxPlaneResidual ||
            Mathf.Abs(Vector3.Dot(vb - center, planeNormal)) > maxPlaneResidual ||
            Mathf.Abs(Vector3.Dot(vc - center, planeNormal)) > maxPlaneResidual ||
            Mathf.Abs(Vector3.Dot(vd - center, planeNormal)) > maxPlaneResidual)
            return ExtractedQuadGeometryRejectReason.Plane;

        return ExtractedQuadGeometryRejectReason.None;
    }

    private void PruneSmallExtractedMeshComponents(List<Vector3> vertices, List<int> triangles, List<Color> colors)
    {
        LastPrunedMeshComponentCount = 0;
        LastPrunedMeshTriangleCount = 0;

        int triangleCount = triangles.Count / 3;
        int minTriangles = Mathf.Max(0, minExtractedComponentTriangles);
        if (!pruneSmallExtractedMeshComponents || minTriangles <= 0 || triangleCount <= minTriangles)
            return;

        Dictionary<int, List<int>> vertexToTriangles = new Dictionary<int, List<int>>(vertices.Count);
        for (int tri = 0; tri < triangleCount; tri++)
        {
            for (int corner = 0; corner < 3; corner++)
            {
                int vertexIndex = triangles[tri * 3 + corner];
                if (vertexIndex < 0 || vertexIndex >= vertices.Count)
                    continue;

                if (!vertexToTriangles.TryGetValue(vertexIndex, out List<int> linked))
                {
                    linked = new List<int>(4);
                    vertexToTriangles.Add(vertexIndex, linked);
                }
                linked.Add(tri);
            }
        }

        bool[] visited = new bool[triangleCount];
        List<List<int>> components = new List<List<int>>();
        Queue<int> queue = new Queue<int>();

        for (int start = 0; start < triangleCount; start++)
        {
            if (visited[start])
                continue;

            List<int> component = new List<int>(64);
            visited[start] = true;
            queue.Enqueue(start);

            while (queue.Count > 0)
            {
                int tri = queue.Dequeue();
                component.Add(tri);

                for (int corner = 0; corner < 3; corner++)
                {
                    int vertexIndex = triangles[tri * 3 + corner];
                    if (!vertexToTriangles.TryGetValue(vertexIndex, out List<int> linked))
                        continue;

                    for (int i = 0; i < linked.Count; i++)
                    {
                        int neighbor = linked[i];
                        if (visited[neighbor])
                            continue;

                        visited[neighbor] = true;
                        queue.Enqueue(neighbor);
                    }
                }
            }

            components.Add(component);
        }

        if (components.Count <= 1)
            return;

        List<Vector3> compactVertices = new List<Vector3>(vertices.Count);
        List<Color> compactColors = colors != null && colors.Count == vertices.Count ? new List<Color>(vertices.Count) : null;
        List<int> compactTriangles = new List<int>(triangles.Count);
        Dictionary<int, int> compactLookup = new Dictionary<int, int>(vertices.Count);
        float minExtent = Mathf.Max(voxelSizeMeters * 2f, voxelSizeMeters * minExtractedComponentExtentVoxelScale);
        int suspectTriangleLimit = Mathf.Max(minTriangles + 1, minTriangles * Mathf.Max(1, suspectComponentTriangleMultiplier));

        for (int componentIndex = 0; componentIndex < components.Count; componentIndex++)
        {
            List<int> component = components[componentIndex];
            float componentExtent = ComputeComponentMaxExtent(vertices, triangles, component);
            bool compactSuspect = component.Count < suspectTriangleLimit && componentExtent < minExtent;
            bool keep = component.Count >= minTriangles && !compactSuspect;
            if (!keep)
            {
                LastPrunedMeshComponentCount++;
                LastPrunedMeshTriangleCount += component.Count;
                LastPrunedComponentTriangleCount += component.Count;
                continue;
            }

            for (int i = 0; i < component.Count; i++)
            {
                int tri = component[i];
                for (int corner = 0; corner < 3; corner++)
                {
                    int oldIndex = triangles[tri * 3 + corner];
                    if (!compactLookup.TryGetValue(oldIndex, out int newIndex))
                    {
                        newIndex = compactVertices.Count;
                        compactVertices.Add(vertices[oldIndex]);
                        if (compactColors != null)
                            compactColors.Add(component.Count < suspectTriangleLimit ? unstableCoverCellColor : cleanCoverCellColor);
                        compactLookup.Add(oldIndex, newIndex);
                    }
                    compactTriangles.Add(newIndex);
                }
            }
        }

        if (compactTriangles.Count <= 0)
            return;

        vertices.Clear();
        vertices.AddRange(compactVertices);
        if (compactColors != null)
        {
            colors.Clear();
            colors.AddRange(compactColors);
        }
        triangles.Clear();
        triangles.AddRange(compactTriangles);
    }

    private static float ComputeComponentMaxExtent(List<Vector3> vertices, List<int> triangles, List<int> component)
    {
        if (vertices == null || triangles == null || component == null || component.Count <= 0)
            return 0f;

        Vector3 min = new Vector3(float.PositiveInfinity, float.PositiveInfinity, float.PositiveInfinity);
        Vector3 max = new Vector3(float.NegativeInfinity, float.NegativeInfinity, float.NegativeInfinity);
        for (int i = 0; i < component.Count; i++)
        {
            int tri = component[i];
            int baseIndex = tri * 3;
            if (baseIndex + 2 >= triangles.Count)
                continue;

            for (int corner = 0; corner < 3; corner++)
            {
                int vertexIndex = triangles[baseIndex + corner];
                if (vertexIndex < 0 || vertexIndex >= vertices.Count)
                    continue;

                Vector3 p = vertices[vertexIndex];
                min = Vector3.Min(min, p);
                max = Vector3.Max(max, p);
            }
        }

        if (!Finite(min) || !Finite(max))
            return 0f;

        Vector3 extent = max - min;
        return Mathf.Max(extent.x, Mathf.Max(extent.y, extent.z));
    }

    private struct BoundaryEdgeInfo
    {
        public int A;
        public int B;
        public Vector3 Center;
        public Vector3 Direction;
        public Vector3 Normal;
        public float Length;
    }

    private void BridgeCleanCoplanarBoundaryEdges(List<Vector3> vertices, List<int> triangles, List<Color> colors)
    {
        if (!bridgeCleanCoplanarBoundaryEdges ||
            vertices == null ||
            triangles == null ||
            vertices.Count <= 0 ||
            triangles.Count < 3 ||
            maxBoundaryBridgesPerRebuild <= 0)
        {
            return;
        }

        List<BoundaryEdgeInfo> edges = CollectBoundaryEdges(vertices, triangles);
        if (edges.Count < 2)
            return;

        float maxDistance = Mathf.Max(0.01f, voxelSizeMeters * maxBoundaryBridgeDistanceVoxelScale);
        float maxDistanceSq = maxDistance * maxDistance;
        float maxPlaneDistance = Mathf.Max(0.002f, voxelSizeMeters * maxBoundaryBridgePlaneDistanceVoxelScale);
        float minNormalDot = Mathf.Clamp(minBoundaryBridgeNormalDot, 0.75f, 1f);
        HashSet<ulong> bridgedVertices = new HashSet<ulong>();
        int bridgeLimit = Mathf.Max(1, maxBoundaryBridgesPerRebuild);
        Dictionary<Vector3Int, List<int>> buckets = new Dictionary<Vector3Int, List<int>>();
        for (int i = 0; i < edges.Count; i++)
        {
            Vector3Int bucket = BoundaryBridgeBucket(edges[i].Center, maxDistance);
            if (!buckets.TryGetValue(bucket, out List<int> list))
            {
                list = new List<int>(8);
                buckets.Add(bucket, list);
            }
            list.Add(i);
        }

        for (int i = 0; i < edges.Count && LastAddedBoundaryBridgeCount < bridgeLimit; i++)
        {
            BoundaryEdgeInfo a = edges[i];
            Vector3Int bucket = BoundaryBridgeBucket(a.Center, maxDistance);
            for (int bz = -1; bz <= 1 && LastAddedBoundaryBridgeCount < bridgeLimit; bz++)
            {
                for (int by = -1; by <= 1 && LastAddedBoundaryBridgeCount < bridgeLimit; by++)
                {
                    for (int bx = -1; bx <= 1 && LastAddedBoundaryBridgeCount < bridgeLimit; bx++)
                    {
                        Vector3Int neighborBucket = new Vector3Int(bucket.x + bx, bucket.y + by, bucket.z + bz);
                        if (!buckets.TryGetValue(neighborBucket, out List<int> candidates))
                            continue;

                        for (int c = 0; c < candidates.Count && LastAddedBoundaryBridgeCount < bridgeLimit; c++)
                        {
                            int j = candidates[c];
                            if (j <= i)
                                continue;

                            BoundaryEdgeInfo b = edges[j];
                            LastBoundaryBridgeCandidateCount++;

                            if (!PassBoundaryBridgeGeometry(a, b, vertices, maxDistanceSq, maxPlaneDistance, minNormalDot, out bool flip))
                            {
                                LastRejectedBoundaryBridgeCount++;
                                continue;
                            }

                            int b0 = flip ? b.B : b.A;
                            int b1 = flip ? b.A : b.B;
                            if (SharesEndpoint(a.A, a.B, b0, b1))
                            {
                                LastRejectedBoundaryBridgeCount++;
                                continue;
                            }

                            ulong bridgeKey0 = EdgeKey(a.A, b0);
                            ulong bridgeKey1 = EdgeKey(a.B, b1);
                            if (bridgedVertices.Contains(bridgeKey0) || bridgedVertices.Contains(bridgeKey1))
                            {
                                LastRejectedBoundaryBridgeCount++;
                                continue;
                            }

                            Vector3 mid0 = (vertices[a.A] + vertices[b0]) * 0.5f;
                            Vector3 mid1 = (vertices[a.B] + vertices[b1]) * 0.5f;
                            Vector3 center = (mid0 + mid1) * 0.5f;
                            if (!BridgePathIsClean(center, mid0, mid1))
                            {
                                LastRejectedBoundaryBridgeCount++;
                                continue;
                            }

                            if (!AddBoundaryBridgeQuad(a.A, a.B, b1, b0, vertices, triangles, colors))
                            {
                                LastRejectedBoundaryBridgeCount++;
                                continue;
                            }
                            bridgedVertices.Add(bridgeKey0);
                            bridgedVertices.Add(bridgeKey1);
                            LastAddedBoundaryBridgeCount++;
                        }
                    }
                }
            }
        }
    }

    private static Vector3Int BoundaryBridgeBucket(Vector3 point, float cellSize)
    {
        float inv = 1f / Mathf.Max(0.001f, cellSize);
        return new Vector3Int(
            Mathf.FloorToInt(point.x * inv),
            Mathf.FloorToInt(point.y * inv),
            Mathf.FloorToInt(point.z * inv));
    }

    private List<BoundaryEdgeInfo> CollectBoundaryEdges(List<Vector3> vertices, List<int> triangles)
    {
        int triangleCount = triangles.Count / 3;
        Dictionary<ulong, List<int>> edgeToTriangles = new Dictionary<ulong, List<int>>(triangleCount * 3);
        Vector3[] triangleNormals = new Vector3[triangleCount];
        for (int tri = 0; tri < triangleCount; tri++)
        {
            triangleNormals[tri] = ComputeTriangleNormal(vertices, triangles, tri);
            AddEdgeTriangle(edgeToTriangles, triangles[tri * 3], triangles[tri * 3 + 1], tri);
            AddEdgeTriangle(edgeToTriangles, triangles[tri * 3 + 1], triangles[tri * 3 + 2], tri);
            AddEdgeTriangle(edgeToTriangles, triangles[tri * 3 + 2], triangles[tri * 3], tri);
        }

        List<BoundaryEdgeInfo> result = new List<BoundaryEdgeInfo>();
        foreach (KeyValuePair<ulong, List<int>> pair in edgeToTriangles)
        {
            if (pair.Value == null || pair.Value.Count != 1)
                continue;

            DecodeEdgeKey(pair.Key, out int a, out int b);
            if (a < 0 || b < 0 || a >= vertices.Count || b >= vertices.Count)
                continue;

            Vector3 va = vertices[a];
            Vector3 vb = vertices[b];
            Vector3 delta = vb - va;
            float length = delta.magnitude;
            if (length < voxelSizeMeters * 0.25f || length > voxelSizeMeters * 2.5f)
                continue;

            Vector3 normal = triangleNormals[pair.Value[0]];
            if (!Finite(normal) || normal.sqrMagnitude < 0.0001f)
                continue;

            result.Add(new BoundaryEdgeInfo
            {
                A = a,
                B = b,
                Center = (va + vb) * 0.5f,
                Direction = delta / length,
                Normal = normal.normalized,
                Length = length
            });
        }

        return result;
    }

    private List<BoundaryEdgeInfo> CollectLogicalBoundaryEdges(List<Vector3> vertices, List<int> triangles)
    {
        int triangleCount = triangles.Count / 3;
        Dictionary<ulong, List<int>> edgeToTriangles = new Dictionary<ulong, List<int>>(triangleCount * 3);
        Vector3[] triangleNormals = new Vector3[triangleCount];
        for (int tri = 0; tri < triangleCount; tri++)
        {
            triangleNormals[tri] = ComputeTriangleNormal(vertices, triangles, tri);
            AddEdgeTriangle(edgeToTriangles, triangles[tri * 3], triangles[tri * 3 + 1], tri);
            AddEdgeTriangle(edgeToTriangles, triangles[tri * 3 + 1], triangles[tri * 3 + 2], tri);
            AddEdgeTriangle(edgeToTriangles, triangles[tri * 3 + 2], triangles[tri * 3], tri);
        }

        int boundaryUse = doubleSidedTriangles ? 2 : 1;
        List<BoundaryEdgeInfo> result = new List<BoundaryEdgeInfo>();
        foreach (KeyValuePair<ulong, List<int>> pair in edgeToTriangles)
        {
            if (pair.Value == null || pair.Value.Count != boundaryUse)
                continue;
            DecodeEdgeKey(pair.Key, out int a, out int b);
            if (a < 0 || b < 0 || a >= vertices.Count || b >= vertices.Count)
                continue;
            Vector3 delta = vertices[b] - vertices[a];
            float length = delta.magnitude;
            if (length < voxelSizeMeters * 0.25f || length > voxelSizeMeters * 2.5f)
                continue;
            Vector3 normal = Vector3.zero;
            for (int i = 0; i < pair.Value.Count; i++)
            {
                Vector3 candidate = triangleNormals[pair.Value[i]];
                if (Finite(candidate) && candidate.sqrMagnitude > 0.0001f)
                {
                    normal = candidate.normalized;
                    break;
                }
            }
            if (normal.sqrMagnitude < 0.0001f)
                continue;
            result.Add(new BoundaryEdgeInfo
            {
                A = a,
                B = b,
                Center = (vertices[a] + vertices[b]) * 0.5f,
                Direction = delta / length,
                Normal = normal,
                Length = length
            });
        }
        return result;
    }

    private void RepairPersistentDoublePlaneCreases(List<Vector3> vertices, List<int> triangles, List<Color> colors)
    {
        if (!repairPersistentDoublePlaneCreases || vertices == null || triangles == null || triangles.Count < 3)
            return;
        CountMeshEdgeTopology(triangles, out int boundaryBefore, out int ignoredNonManifoldBefore);
        LastDoublePlaneCreaseBoundaryEdgesBefore = boundaryBefore;
        List<BoundaryEdgeInfo> edges = CollectLogicalBoundaryEdges(vertices, triangles);
        float maxGap = Mathf.Max(voxelSizeMeters * 2f, voxelSizeMeters * maxDoublePlaneCreaseGapVoxelScale);
        Dictionary<Vector3Int, List<int>> buckets = new Dictionary<Vector3Int, List<int>>();
        for (int i = 0; i < edges.Count; i++)
        {
            Vector3Int bucket = BoundaryBridgeBucket(edges[i].Center, maxGap);
            if (!buckets.TryGetValue(bucket, out List<int> list))
            {
                list = new List<int>(8);
                buckets.Add(bucket, list);
            }
            list.Add(i);
        }

        HashSet<int> usedEdges = new HashSet<int>();
        HashSet<CreaseCandidateKey> handledKeys = new HashSet<CreaseCandidateKey>();
        _doublePlaneCreaseObserved.Clear();
        int limit = Mathf.Max(1, maxDoublePlaneCreaseRepairsPerRebuild);
        int patchesThisRebuild = 0;
        for (int i = 0; i < edges.Count && patchesThisRebuild < limit; i++)
        {
            BoundaryEdgeInfo a = edges[i];
            Vector3Int bucket = BoundaryBridgeBucket(a.Center, maxGap);
            for (int bz = -1; bz <= 1 && patchesThisRebuild < limit; bz++)
            for (int by = -1; by <= 1 && patchesThisRebuild < limit; by++)
            for (int bx = -1; bx <= 1 && patchesThisRebuild < limit; bx++)
            {
                if (!buckets.TryGetValue(bucket + new Vector3Int(bx, by, bz), out List<int> candidates))
                    continue;
                for (int c = 0; c < candidates.Count && patchesThisRebuild < limit; c++)
                {
                    int j = candidates[c];
                    if (j <= i || usedEdges.Contains(i) || usedEdges.Contains(j))
                        continue;
                    LastDoublePlaneCreaseCandidateCount++;
                    if (!TryBuildDoublePlaneCrease(a, edges[j], vertices, maxGap,
                        out int b0, out int b1, out Vector3 crease0, out Vector3 crease1))
                    {
                        LastDoublePlaneCreaseRejectedGeometryCount++;
                        continue;
                    }
                    Vector3 evidencePoint = (a.Center + edges[j].Center) * 0.5f;
                    if (!DoublePlaneCreaseEvidenceIsSafe(evidencePoint, crease0, crease1))
                    {
                        LastDoublePlaneCreaseRejectedEvidenceCount++;
                        continue;
                    }

                    CreaseCandidateKey key = DoublePlaneCreaseKey((crease0 + crease1) * 0.5f);
                    if (!handledKeys.Add(key))
                        continue;
                    _doublePlaneCreaseStates.TryGetValue(key, out CreaseCandidateState state);
                    if (state.LastRebuildSequence != _newbornPholdCompetitionRebuildSequence)
                    {
                        state.Consecutive = state.LastRebuildSequence == _newbornPholdCompetitionRebuildSequence - 1 ||
                                            (state.Committed && state.ConsecutiveMissing <= Mathf.Clamp(doublePlaneCreaseRetainMissingRebuilds, 1, 4))
                            ? state.Consecutive + 1 : 1;
                        state.LastRebuildSequence = _newbornPholdCompetitionRebuildSequence;
                        state.ConsecutiveMissing = 0;
                    }
                    _doublePlaneCreaseObserved.Add(key);
                    bool wasCommitted = state.Committed;
                    if (!state.Committed && state.Consecutive >= Mathf.Clamp(doublePlaneCreaseConfirmRebuilds, 2, 4))
                        state.Committed = true;
                    if (!state.Committed)
                    {
                        _doublePlaneCreaseStates[key] = state;
                        LastDoublePlaneCreasePendingCount++;
                        _creaseRepairAuditRecords.Add(new CreaseRepairAuditRecord
                        {
                            Key = key, Crease0 = crease0, Crease1 = crease1, EvidencePoint = evidencePoint,
                            Status = "pending", Consecutive = state.Consecutive, Missing = 0, TotalApplied = state.TotalApplied
                        });
                        continue;
                    }

                    if (!AddDoublePlaneCreasePatch(a.A, a.B, b0, b1, crease0, crease1, vertices, triangles, colors))
                    {
                        LastDoublePlaneCreaseRejectedGeometryCount++;
                        continue;
                    }
                    usedEdges.Add(i);
                    usedEdges.Add(j);
                    patchesThisRebuild++;
                    state.TotalApplied++;
                    _doublePlaneCreaseStates[key] = state;
                    LastDoublePlaneCreaseAppliedCount++;
                    if (wasCommitted)
                        LastDoublePlaneCreaseReappliedCount++;
                    _creaseRepairAuditRecords.Add(new CreaseRepairAuditRecord
                    {
                        Key = key, Crease0 = crease0, Crease1 = crease1, EvidencePoint = evidencePoint,
                        Status = wasCommitted ? "reapplied" : "committed", Consecutive = state.Consecutive,
                        Missing = 0, TotalApplied = state.TotalApplied
                    });
                }
            }
        }

        List<CreaseCandidateKey> keys = new List<CreaseCandidateKey>(_doublePlaneCreaseStates.Keys);
        for (int i = 0; i < keys.Count; i++)
        {
            CreaseCandidateKey key = keys[i];
            if (_doublePlaneCreaseObserved.Contains(key))
                continue;
            CreaseCandidateState state = _doublePlaneCreaseStates[key];
            state.Consecutive = 0;
            state.ConsecutiveMissing++;
            if (state.ConsecutiveMissing > Mathf.Clamp(doublePlaneCreaseRetainMissingRebuilds, 1, 4))
            {
                _doublePlaneCreaseStates.Remove(key);
                LastDoublePlaneCreaseRetiredCount++;
            }
            else
            {
                _doublePlaneCreaseStates[key] = state;
            }
        }
        foreach (CreaseCandidateState state in _doublePlaneCreaseStates.Values)
            if (state.Committed)
                LastDoublePlaneCreaseCommittedLiveCount++;
        CountMeshEdgeTopology(triangles, out int boundaryAfter, out int ignoredNonManifoldAfter);
        LastDoublePlaneCreaseBoundaryEdgesAfter = boundaryAfter;
    }

    private bool TryBuildDoublePlaneCrease(BoundaryEdgeInfo a, BoundaryEdgeInfo b, List<Vector3> vertices,
        float maxGap, out int b0, out int b1, out Vector3 crease0, out Vector3 crease1)
    {
        b0 = b.A;
        b1 = b.B;
        crease0 = crease1 = Vector3.zero;
        if (SharesEndpoint(a.A, a.B, b.A, b.B))
            return false;
        float normalDot = Mathf.Abs(Vector3.Dot(a.Normal, b.Normal));
        if (normalDot > Mathf.Clamp(maxDoublePlaneCreaseNormalDot, 0f, 0.8f))
            return false;
        Vector3 cross = Vector3.Cross(a.Normal, b.Normal);
        float denominator = cross.sqrMagnitude;
        if (denominator < 0.08f)
            return false;
        Vector3 direction = cross / Mathf.Sqrt(denominator);
        if (Mathf.Abs(Vector3.Dot(direction, Vector3.up)) < Mathf.Clamp01(minDoublePlaneCreaseVerticalDot) ||
            Mathf.Abs(Vector3.Dot(a.Direction, direction)) < Mathf.Clamp01(minDoublePlaneCreaseDirectionDot) ||
            Mathf.Abs(Vector3.Dot(b.Direction, direction)) < Mathf.Clamp01(minDoublePlaneCreaseDirectionDot))
            return false;

        float same = Vector3.Distance(vertices[a.A], vertices[b.A]) + Vector3.Distance(vertices[a.B], vertices[b.B]);
        float crossed = Vector3.Distance(vertices[a.A], vertices[b.B]) + Vector3.Distance(vertices[a.B], vertices[b.A]);
        if (crossed < same)
        {
            b0 = b.B;
            b1 = b.A;
        }
        if (Vector3.Distance(vertices[a.A], vertices[b0]) > maxGap ||
            Vector3.Distance(vertices[a.B], vertices[b1]) > maxGap)
            return false;

        float d1 = Vector3.Dot(a.Normal, a.Center);
        float d2 = Vector3.Dot(b.Normal, b.Center);
        Vector3 linePoint = (d1 * Vector3.Cross(b.Normal, cross) + d2 * Vector3.Cross(cross, a.Normal)) / denominator;
        if (!Finite(linePoint))
            return false;
        float t0 = (Vector3.Dot(vertices[a.A] - linePoint, direction) + Vector3.Dot(vertices[b0] - linePoint, direction)) * 0.5f;
        float t1 = (Vector3.Dot(vertices[a.B] - linePoint, direction) + Vector3.Dot(vertices[b1] - linePoint, direction)) * 0.5f;
        crease0 = linePoint + direction * t0;
        crease1 = linePoint + direction * t1;
        float creaseLength = Vector3.Distance(crease0, crease1);
        if (!Finite(crease0) || !Finite(crease1) || creaseLength < voxelSizeMeters * 0.2f || creaseLength > voxelSizeMeters * 3f)
            return false;
        float maxProjection = maxGap * 1.25f;
        return Vector3.Distance(vertices[a.A], crease0) <= maxProjection &&
               Vector3.Distance(vertices[a.B], crease1) <= maxProjection &&
               Vector3.Distance(vertices[b0], crease0) <= maxProjection &&
               Vector3.Distance(vertices[b1], crease1) <= maxProjection;
    }

    private bool DoublePlaneCreaseEvidenceIsSafe(Vector3 gapCenter, Vector3 crease0, Vector3 crease1)
    {
        if (!TryFindNearestRawCoverageCell(gapCenter, out _, out _, out RawCoverageGridCell coverage) || coverage.ProblemCount <= 0)
            return false;
        string cause = DominantRawCoverageCause(coverage);
        if (cause != "robust_depth_outlier" && cause != "depth_discontinuity" && cause != "basic_filter_or_vote_reject")
            return false;
        Vector3[] samples = { gapCenter, crease0, crease1, (crease0 + crease1) * 0.5f };
        for (int i = 0; i < samples.Length; i++)
        {
            if (!TryWorldToVoxel(samples[i], out int x, out int y, out int z))
                return false;
            int index = Index(x, y, z);
            if (VoxelHasPendingTsdfCorrection(index) || VoxelIsDirtyQuarantined(index))
                return false;
        }
        return true;
    }

    private CreaseCandidateKey DoublePlaneCreaseKey(Vector3 world)
    {
        float scale = Mathf.Max(0.01f, voxelSizeMeters * 1.5f);
        return new CreaseCandidateKey
        {
            X = Mathf.RoundToInt(world.x / scale),
            Y = Mathf.RoundToInt(world.y / scale),
            Z = Mathf.RoundToInt(world.z / scale)
        };
    }

    private bool AddDoublePlaneCreasePatch(int a0, int a1, int b0, int b1, Vector3 crease0, Vector3 crease1,
        List<Vector3> vertices, List<int> triangles, List<Color> colors)
    {
        int c0 = vertices.Count;
        int c1 = c0 + 1;
        vertices.Add(crease0);
        vertices.Add(crease1);
        if (colors != null)
        {
            while (colors.Count < c0) colors.Add(cleanCoverCellColor);
            colors.Add(cleanCoverCellColor);
            colors.Add(cleanCoverCellColor);
        }
        AddCreaseTriangle(a0, a1, c1, triangles);
        AddCreaseTriangle(a0, c1, c0, triangles);
        AddCreaseTriangle(b0, c0, c1, triangles);
        AddCreaseTriangle(b0, c1, b1, triangles);
        LastDoublePlaneCreaseAddedTriangleCount += doubleSidedTriangles ? 8 : 4;
        return true;
    }

    private void AddCreaseTriangle(int a, int b, int c, List<int> triangles)
    {
        triangles.Add(a); triangles.Add(b); triangles.Add(c);
        if (doubleSidedTriangles)
        {
            triangles.Add(c); triangles.Add(b); triangles.Add(a);
        }
    }

    private bool PassBoundaryBridgeGeometry(
        BoundaryEdgeInfo a,
        BoundaryEdgeInfo b,
        List<Vector3> vertices,
        float maxDistanceSq,
        float maxPlaneDistance,
        float minNormalDot,
        out bool flip)
    {
        flip = false;
        float normalDot = Mathf.Abs(Vector3.Dot(a.Normal, b.Normal));
        if (normalDot < minNormalDot)
            return false;

        float dirDot = Mathf.Abs(Vector3.Dot(a.Direction, b.Direction));
        if (dirDot < 0.80f)
            return false;

        float planeAB = Mathf.Abs(Vector3.Dot(b.Center - a.Center, a.Normal));
        float planeBA = Mathf.Abs(Vector3.Dot(a.Center - b.Center, b.Normal));
        if (planeAB > maxPlaneDistance || planeBA > maxPlaneDistance)
            return false;

        float same = (vertices[a.A] - vertices[b.A]).sqrMagnitude + (vertices[a.B] - vertices[b.B]).sqrMagnitude;
        float crossed = (vertices[a.A] - vertices[b.B]).sqrMagnitude + (vertices[a.B] - vertices[b.A]).sqrMagnitude;
        flip = crossed < same;
        float pairDistance = Mathf.Min(same, crossed);
        if (pairDistance > maxDistanceSq * 2f)
            return false;

        float centerDistanceSq = (a.Center - b.Center).sqrMagnitude;
        if (centerDistanceSq > maxDistanceSq * 4f)
            return false;

        return true;
    }

    private bool BridgePathIsClean(Vector3 center, Vector3 mid0, Vector3 mid1)
    {
        return BridgePointIsClean(center) && BridgePointIsClean(mid0) && BridgePointIsClean(mid1);
    }

    private bool BridgePointIsClean(Vector3 world)
    {
        if (!TryWorldToVoxel(world, out int x, out int y, out int z))
            return false;

        int radius = Mathf.Clamp(boundaryBridgeCleanRadiusVoxels, 0, 3);
        for (int dz = -radius; dz <= radius; dz++)
        {
            int vz = z + dz;
            if (vz < 0 || vz >= _dimZ)
                continue;
            for (int dy = -radius; dy <= radius; dy++)
            {
                int vy = y + dy;
                if (vy < 0 || vy >= _dimY)
                    continue;
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int vx = x + dx;
                    if (vx < 0 || vx >= _dimX)
                        continue;

                    int index = Index(vx, vy, vz);
                    if (_weights[index] < minSurfaceCornerWeight)
                        return false;
                    if (Mathf.Abs(_tsdf[index]) > maxBoundaryBridgeAbsTsdf)
                        return false;
                    if (VoxelHasPendingTsdfCorrection(index) || VoxelIsDirtyQuarantined(index))
                        return false;
                }
            }
        }

        return true;
    }

    private bool AddBoundaryBridgeQuad(int a, int b, int c, int d, List<Vector3> vertices, List<int> triangles, List<Color> colors)
    {
        if (!PassExtractedQuadGeometryGate(a, b, c, d, vertices))
            return false;

        triangles.Add(a);
        triangles.Add(b);
        triangles.Add(c);
        triangles.Add(a);
        triangles.Add(c);
        triangles.Add(d);

        if (colors != null && colors.Count == vertices.Count)
        {
            colors[a] = cleanCoverCellColor;
            colors[b] = cleanCoverCellColor;
            colors[c] = cleanCoverCellColor;
            colors[d] = cleanCoverCellColor;
        }

        return true;
    }

    private static bool SharesEndpoint(int a0, int a1, int b0, int b1)
    {
        return a0 == b0 || a0 == b1 || a1 == b0 || a1 == b1;
    }

    private void PruneDanglingExtractedMeshTriangles(List<Vector3> vertices, List<int> triangles)
    {
        if (!pruneDanglingExtractedMeshTriangles || triangles.Count < 3)
            return;

        int minSharedEdges = Mathf.Clamp(minTriangleSharedEdgesToKeep, 0, 2);
        if (minSharedEdges <= 0)
            return;

        int iterations = Mathf.Max(1, danglingTrianglePruneIterations);
        for (int iteration = 0; iteration < iterations; iteration++)
        {
            int triangleCount = triangles.Count / 3;
            if (triangleCount <= 0)
                return;

            Dictionary<ulong, int> edgeUseCounts = new Dictionary<ulong, int>(triangleCount * 3);
            for (int tri = 0; tri < triangleCount; tri++)
            {
                AddEdgeUse(edgeUseCounts, triangles[tri * 3], triangles[tri * 3 + 1]);
                AddEdgeUse(edgeUseCounts, triangles[tri * 3 + 1], triangles[tri * 3 + 2]);
                AddEdgeUse(edgeUseCounts, triangles[tri * 3 + 2], triangles[tri * 3]);
            }

            List<int> keptTriangles = new List<int>(triangles.Count);
            int prunedThisPass = 0;
            for (int tri = 0; tri < triangleCount; tri++)
            {
                int a = triangles[tri * 3];
                int b = triangles[tri * 3 + 1];
                int c = triangles[tri * 3 + 2];
                int sharedEdges = 0;
                if (GetEdgeUseCount(edgeUseCounts, a, b) > 1)
                    sharedEdges++;
                if (GetEdgeUseCount(edgeUseCounts, b, c) > 1)
                    sharedEdges++;
                if (GetEdgeUseCount(edgeUseCounts, c, a) > 1)
                    sharedEdges++;

                if (sharedEdges < minSharedEdges)
                {
                    prunedThisPass++;
                    continue;
                }

                keptTriangles.Add(a);
                keptTriangles.Add(b);
                keptTriangles.Add(c);
            }

            if (prunedThisPass <= 0)
                return;

            LastPrunedMeshTriangleCount += prunedThisPass;
            LastPrunedDanglingTriangleCount += prunedThisPass;
            triangles.Clear();
            triangles.AddRange(keptTriangles);
        }
    }

    private void PruneSpikePatchTriangles(List<Vector3> vertices, List<int> triangles)
    {
        if (!pruneSpikePatchTriangles || vertices == null || triangles == null || triangles.Count < 3)
            return;

        int iterations = Mathf.Max(1, spikePatchPruneIterations);
        for (int iteration = 0; iteration < iterations; iteration++)
        {
            int triangleCount = triangles.Count / 3;
            if (triangleCount <= 0)
                return;

            Dictionary<ulong, List<int>> edgeToTriangles = new Dictionary<ulong, List<int>>(triangleCount * 3);
            Vector3[] triangleNormals = new Vector3[triangleCount];
            for (int tri = 0; tri < triangleCount; tri++)
            {
                triangleNormals[tri] = ComputeTriangleNormal(vertices, triangles, tri);
                AddEdgeTriangle(edgeToTriangles, triangles[tri * 3], triangles[tri * 3 + 1], tri);
                AddEdgeTriangle(edgeToTriangles, triangles[tri * 3 + 1], triangles[tri * 3 + 2], tri);
                AddEdgeTriangle(edgeToTriangles, triangles[tri * 3 + 2], triangles[tri * 3], tri);
            }

            bool[] visited = new bool[triangleCount];
            bool[] remove = new bool[triangleCount];
            int prunedThisPass = 0;
            Queue<int> queue = new Queue<int>();
            List<int> patch = new List<int>(32);
            int maxTriangles = Mathf.Max(2, maxSpikePatchTriangles);

            for (int start = 0; start < triangleCount; start++)
            {
                if (visited[start])
                    continue;

                patch.Clear();
                visited[start] = true;
                queue.Enqueue(start);
                while (queue.Count > 0)
                {
                    int tri = queue.Dequeue();
                    patch.Add(tri);
                    EnqueueSimilarNormalTriNeighbors(triangles, edgeToTriangles, triangleNormals, tri, visited, queue);
                }

                if (patch.Count <= 0 || patch.Count > maxTriangles)
                    continue;

                if (!IsSpikePatch(vertices, triangles, edgeToTriangles, patch))
                    continue;

                for (int i = 0; i < patch.Count; i++)
                {
                    int tri = patch[i];
                    if (remove[tri])
                        continue;
                    remove[tri] = true;
                    prunedThisPass++;
                }
            }

            if (prunedThisPass <= 0)
                return;

            List<int> keptTriangles = new List<int>(triangles.Count - prunedThisPass * 3);
            for (int tri = 0; tri < triangleCount; tri++)
            {
                if (remove[tri])
                    continue;
                keptTriangles.Add(triangles[tri * 3]);
                keptTriangles.Add(triangles[tri * 3 + 1]);
                keptTriangles.Add(triangles[tri * 3 + 2]);
            }

            triangles.Clear();
            triangles.AddRange(keptTriangles);
            LastPrunedMeshTriangleCount += prunedThisPass;
            LastPrunedSpikeTriangleCount += prunedThisPass;
        }
    }

    private void AnalyzeMeshDiagnostics(List<Vector3> vertices, List<int> triangles)
    {
        ResetMeshDiagnostics();
        if (!runMeshDiagnosticsOnRebuild || vertices == null || triangles == null || triangles.Count < 3)
        {
            UpdateMeshDiagnosticHotspots();
            return;
        }

        int triangleCount = triangles.Count / 3;
        Dictionary<ulong, List<int>> edgeToTriangles = new Dictionary<ulong, List<int>>(triangleCount * 3);
        Vector3[] triangleNormals = new Vector3[triangleCount];
        Vector3[] triangleCenters = new Vector3[triangleCount];
        for (int tri = 0; tri < triangleCount; tri++)
        {
            triangleNormals[tri] = ComputeTriangleNormal(vertices, triangles, tri);
            triangleCenters[tri] = ComputeTriangleCenter(vertices, triangles, tri);
            AddEdgeTriangle(edgeToTriangles, triangles[tri * 3], triangles[tri * 3 + 1], tri);
            AddEdgeTriangle(edgeToTriangles, triangles[tri * 3 + 1], triangles[tri * 3 + 2], tri);
            AddEdgeTriangle(edgeToTriangles, triangles[tri * 3 + 2], triangles[tri * 3], tri);
        }

        foreach (KeyValuePair<ulong, List<int>> pair in edgeToTriangles)
        {
            int count = pair.Value != null ? pair.Value.Count : 0;
            if (count == 1)
                LastDiagBoundaryEdgeCount++;
            else if (count > 2)
                LastDiagNonManifoldEdgeCount++;
        }

        AnalyzeMeshComponents(triangles, edgeToTriangles, triangleCount);
        AnalyzeNormalPatches(vertices, triangles, edgeToTriangles, triangleNormals, triangleCenters, triangleCount);
        SortMeshDiagnosticHotspots();
        LastDiagLikelyCause = GuessMeshDiagnosticCause(triangleCount);
        UpdateMeshDiagnosticHotspots();
    }

