    private void ApplyRawDepthDebugDisplayMode()
    {
        if (showPlaneReferenceAndZeroCrossShadowOnly)
        {
            if (_meshRenderer != null)
                _meshRenderer.enabled = false;
            if (_wireObject != null)
                _wireObject.SetActive(false);
            if (_incrementalPatchShadowObject != null)
                _incrementalPatchShadowObject.SetActive(false);
            if (_stablePlaneShadowObject != null)
                _stablePlaneShadowObject.SetActive(
                    enableStablePlaneShadowTrial && showStablePlaneShadowWire &&
                    _stablePlaneShadowMesh != null && _stablePlaneShadowMesh.vertexCount > 0);
            if (_planeConstrainedZeroCrossShadowObject != null)
                _planeConstrainedZeroCrossShadowObject.SetActive(
                    enablePlaneConstrainedZeroCrossShadow && showPlaneConstrainedZeroCrossShadowWire &&
                    _planeConstrainedZeroCrossShadowMesh != null &&
                    _planeConstrainedZeroCrossShadowMesh.vertexCount > 0);
            if (_planeConstrainedZeroCrossIssueObject != null)
                _planeConstrainedZeroCrossIssueObject.SetActive(
                    enablePlaneConstrainedZeroCrossShadow && showPlaneConstrainedZeroCrossIssueOverlay &&
                    _planeConstrainedZeroCrossIssueMesh != null &&
                    _planeConstrainedZeroCrossIssueMesh.vertexCount > 0);
            if (_referenceVolumetricObject != null)
                _referenceVolumetricObject.SetActive(false);
            if (_referenceClassicBoundaryObject != null)
                _referenceClassicBoundaryObject.SetActive(false);
            if (_rawDepthDebugObject != null)
                _rawDepthDebugObject.SetActive(false);
            if (_dirtyEvidenceObject != null)
                _dirtyEvidenceObject.SetActive(false);
            if (_holeBoundaryDiagnosticObject != null)
                _holeBoundaryDiagnosticObject.SetActive(false);
            if (_authoritativeCyanCrackObject != null)
                _authoritativeCyanCrackObject.SetActive(false);
            // Raw-display refreshes happen after captures and used to re-enable all
            // presentation meshes.  Re-assert the selected three-gear view so RESULT,
            // DIAG and REFERENCE remain mutually exclusive across rebuilds.
            ApplyOutputDisplayLayerVisibility();
            return;
        }
        bool cyanOnly = showAuthoritativeCyanOnly && enableAuthoritativeTsdfBlockExtraction;
        if (cyanOnly)
        {
            if (_meshRenderer != null)
                _meshRenderer.enabled = false;
            if (_wireObject != null)
                _wireObject.SetActive(false);
            if (_incrementalPatchShadowObject != null)
                _incrementalPatchShadowObject.SetActive(
                    enableIncrementalPatchShadow && showIncrementalPatchShadowWire &&
                    _incrementalPatchShadowMesh != null && _incrementalPatchShadowMesh.vertexCount > 0);
            if (_stablePlaneShadowObject != null)
                _stablePlaneShadowObject.SetActive(false);
            if (_planeConstrainedZeroCrossIssueObject != null)
                _planeConstrainedZeroCrossIssueObject.SetActive(false);
            if (_referenceVolumetricObject != null)
                _referenceVolumetricObject.SetActive(false);
            if (_referenceClassicBoundaryObject != null)
                _referenceClassicBoundaryObject.SetActive(false);
            if (_rawDepthDebugObject != null)
                _rawDepthDebugObject.SetActive(false);
            if (_dirtyEvidenceObject != null)
                _dirtyEvidenceObject.SetActive(false);
            if (_holeBoundaryDiagnosticObject != null)
                _holeBoundaryDiagnosticObject.SetActive(false);
            if (_authoritativeCyanCrackObject != null)
                _authoritativeCyanCrackObject.SetActive(
                    showAuthoritativeCyanCrackOverlay &&
                    _authoritativeCyanCrackMesh != null &&
                    _authoritativeCyanCrackMesh.vertexCount > 0);
            return;
        }
        bool coverageOverlay = enableRawCoverageGridDiagnostics && showRawCoverageGridOverlay;
        bool hideMeshForCoverage = coverageOverlay && hideMeshWhenRawCoverageGridOverlay;
        bool hideMeshForHoleDiagnosis = showHoleBoundaryDiagnosis && hideMeshWhileShowingHoleBoundaryDiagnosis && !showMeshBehindLayerDiagnostics;
        bool layerWireOnly = showHoleBoundaryDiagnosis && showMeshBehindLayerDiagnostics && showMeshAsWireOnlyBehindLayerDiagnostics;
        if (_meshRenderer != null)
            _meshRenderer.enabled = !showRawDepthDebugView && !hideMeshForCoverage && !hideMeshForHoleDiagnosis && !layerWireOnly && (showPlanarCoverSurfaceFill || !renderStableCellsAsPlanarMeshCover || !showPlanarCoverWireOverlay);
        if (_wireObject != null)
            _wireObject.SetActive(!showRawDepthDebugView && !hideMeshForCoverage && !hideMeshForHoleDiagnosis && (layerWireOnly || showMeshEdgeWireOverlay || showPlanarCoverWireOverlay));
        if (_incrementalPatchShadowObject != null)
            _incrementalPatchShadowObject.SetActive(
                enableIncrementalPatchShadow && showIncrementalPatchShadowWire &&
                _incrementalPatchShadowMesh != null && _incrementalPatchShadowMesh.vertexCount > 0 &&
                !showRawDepthDebugView && !hideMeshForCoverage && !hideMeshForHoleDiagnosis);
        if (_stablePlaneShadowObject != null)
            _stablePlaneShadowObject.SetActive(
                enableStablePlaneShadowTrial && showStablePlaneShadowWire &&
                _stablePlaneShadowMesh != null && _stablePlaneShadowMesh.vertexCount > 0 &&
                !showRawDepthDebugView && !hideMeshForCoverage && !hideMeshForHoleDiagnosis);
        if (_planeConstrainedZeroCrossIssueObject != null)
            _planeConstrainedZeroCrossIssueObject.SetActive(
                enablePlaneConstrainedZeroCrossShadow && showPlaneConstrainedZeroCrossIssueOverlay &&
                _planeConstrainedZeroCrossIssueMesh != null &&
                _planeConstrainedZeroCrossIssueMesh.vertexCount > 0 &&
                !showRawDepthDebugView && !hideMeshForCoverage && !hideMeshForHoleDiagnosis);
        if (_referenceVolumetricObject != null)
            _referenceVolumetricObject.SetActive(
                enableReferenceVolumetricShadow &&
                (showReferenceVolumetricShadowMesh ||
                 (showAcceptedReferenceClassicCompletionMesh && LastReferenceClassicCompletionAccepted)) &&
                !showRawDepthDebugView && !hideMeshForCoverage && !hideMeshForHoleDiagnosis);
        if (_referenceClassicBoundaryObject != null)
            _referenceClassicBoundaryObject.SetActive(
                enableReferenceClassicTsdf && showReferenceClassicBoundaryDiagnostics &&
                _referenceClassicBoundaryMesh != null && _referenceClassicBoundaryMesh.vertexCount > 0 &&
                !showRawDepthDebugView && !hideMeshForCoverage && !hideMeshForHoleDiagnosis);
        if (_rawDepthDebugObject != null)
            _rawDepthDebugObject.SetActive((showRawDepthDebugView || coverageOverlay) && LastRawDepthDebugRenderedCount > 0);
        if (_authoritativeCyanCrackObject != null)
            _authoritativeCyanCrackObject.SetActive(
                showAuthoritativeCyanCrackOverlay &&
                _authoritativeCyanCrackMesh != null &&
                _authoritativeCyanCrackMesh.vertexCount > 0 &&
                !showRawDepthDebugView && !hideMeshForCoverage && !hideMeshForHoleDiagnosis);
    }

