        _rawDepthDebugObject.SetActive((showRawDepthDebugView || (enableRawCoverageGridDiagnostics && showRawCoverageGridOverlay)) && LastRawDepthDebugRenderedCount > 0);
    }

    private void EnsureHoleBoundaryDiagnosticObjects()
    {
        if (_holeBoundaryDiagnosticObject == null)
            _holeBoundaryDiagnosticObject = new GameObject("[ScanCover] Hole Boundary Diagnosis");

        if (forceWorldSpaceDisplay)
        {
            _holeBoundaryDiagnosticObject.transform.SetParent(null, true);
            _holeBoundaryDiagnosticObject.transform.SetPositionAndRotation(Vector3.zero, Quaternion.identity);
            _holeBoundaryDiagnosticObject.transform.localScale = Vector3.one;
        }
        else if (_holeBoundaryDiagnosticObject.transform.parent != displayRoot)
        {
            _holeBoundaryDiagnosticObject.transform.SetParent(displayRoot, false);
        }

        if (_holeBoundaryDiagnosticMeshFilter == null)
            _holeBoundaryDiagnosticMeshFilter = _holeBoundaryDiagnosticObject.GetComponent<MeshFilter>();
        if (_holeBoundaryDiagnosticMeshFilter == null)
            _holeBoundaryDiagnosticMeshFilter = _holeBoundaryDiagnosticObject.AddComponent<MeshFilter>();
        if (_holeBoundaryDiagnosticRenderer == null)
            _holeBoundaryDiagnosticRenderer = _holeBoundaryDiagnosticObject.GetComponent<MeshRenderer>();
        if (_holeBoundaryDiagnosticRenderer == null)
            _holeBoundaryDiagnosticRenderer = _holeBoundaryDiagnosticObject.AddComponent<MeshRenderer>();
        if (_holeBoundaryDiagnosticMesh == null)
        {
            _holeBoundaryDiagnosticMesh = new Mesh { name = "ScanCover_HoleBoundaryDiagnosis" };
            _holeBoundaryDiagnosticMesh.indexFormat = IndexFormat.UInt32;
        }

        _holeBoundaryDiagnosticMeshFilter.sharedMesh = _holeBoundaryDiagnosticMesh;
        _holeBoundaryDiagnosticRenderer.sharedMaterial = ResolveRawDepthDebugMaterial();
        _holeBoundaryDiagnosticObject.SetActive(showHoleBoundaryDiagnosis && _holeBoundaryDiagnosticMesh.vertexCount > 0);
    }

    private void EnsureDiagnosticHud()
    {
        if (!showDiagnosticHud)
        {
            if (_hudRoot != null && _hudRoot.activeSelf)
                _hudRoot.SetActive(false);
            return;
        }

        if (_hudCanvas != null && _hudText != null)
            return;

        GameObject root = new GameObject("[ScanCover] TSDF Diagnostic HUD", typeof(RectTransform), typeof(Canvas), typeof(CanvasScaler));
        root.hideFlags = HideFlags.DontSave;
        _hudRoot = root;
        _hudCanvas = root.GetComponent<Canvas>();
        _hudCanvas.renderMode = RenderMode.WorldSpace;

        CanvasScaler scaler = root.GetComponent<CanvasScaler>();
        scaler.dynamicPixelsPerUnit = 10f;
        scaler.referencePixelsPerUnit = 100f;

        GameObject panelGO = new GameObject("Panel", typeof(RectTransform), typeof(Image));
        panelGO.transform.SetParent(root.transform, false);
        RectTransform panelRect = panelGO.GetComponent<RectTransform>();
        panelRect.sizeDelta = new Vector2(760f, 250f);
        panelRect.anchorMin = new Vector2(0.5f, 0.5f);
        panelRect.anchorMax = new Vector2(0.5f, 0.5f);
        panelRect.pivot = new Vector2(0.5f, 0.5f);
        _hudPanel = panelGO.GetComponent<Image>();
        _hudPanel.color = new Color(0f, 0.02f, 0.03f, 0.72f);
        _hudPanel.raycastTarget = false;

        GameObject textGO = new GameObject("Text", typeof(RectTransform), typeof(Text));
        textGO.transform.SetParent(panelGO.transform, false);
        RectTransform textRect = textGO.GetComponent<RectTransform>();
        textRect.anchorMin = Vector2.zero;
        textRect.anchorMax = Vector2.one;
        textRect.offsetMin = new Vector2(18f, 14f);
        textRect.offsetMax = new Vector2(-18f, -14f);

        _hudText = textGO.GetComponent<Text>();
        _hudText.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
        if (_hudText.font == null)
            _hudText.font = Resources.GetBuiltinResource<Font>("Arial.ttf");
        _hudText.fontSize = 20;
        _hudText.alignment = TextAnchor.UpperLeft;
        _hudText.horizontalOverflow = HorizontalWrapMode.Wrap;
        _hudText.verticalOverflow = VerticalWrapMode.Overflow;
        _hudText.color = hudHealthyColor;
        _hudText.raycastTarget = false;
        _hudText.text = "TSDF HUD";
    }

    private string DominantHoleCauseText()
    {
        int[] counts =
        {
            LastHoleCauseNoRawCount, LastHoleCausePendingCount, LastHoleCauseNoBandCount, LastHoleCauseNoZeroCrossCount,
            LastHoleCauseVertexRejectCount, LastHoleCauseQuadRejectCount, LastHoleCauseClearedCount,
            LastHoleCauseLocalOffsetCount, LastHoleCauseCrossFrameCount
        };
        string[] names = { "NO_RAW", "PENDING", "NO_BAND", "NO_ZERO", "VERTEX", "QUAD", "CLEARED", "LOCAL", "XFRAME" };
        int best = 0;
        for (int i = 1; i < counts.Length; i++)
            if (counts[i] > counts[best])
                best = i;
        return names[best] + "=" + counts[best];
    }

    private void UpdateDiagnosticHud()
    {
        if (!showDiagnosticHud)
        {
            if (_hudRoot != null && _hudRoot.activeSelf)
                _hudRoot.SetActive(false);
            return;
        }

        EnsureDiagnosticHud();
        if (_hudRoot == null || _hudText == null)
            return;

        Camera camera = Camera.main;
        if (camera != null)
        {
            Transform hudTransform = _hudRoot.transform;
            hudTransform.SetParent(camera.transform, false);
            hudTransform.localPosition = hudLocalPosition;
            hudTransform.localEulerAngles = hudLocalEuler;
            hudTransform.localScale = hudLocalScale;
            _hudCanvas.worldCamera = camera;
        }
        else if (_hudRoot.transform.parent != transform)
        {
            _hudRoot.transform.SetParent(transform, false);
        }

        if (!_hudRoot.activeSelf)
            _hudRoot.SetActive(true);

        if (Time.unscaledTime < _nextHudRefresh)
            return;
        _nextHudRefresh = Time.unscaledTime + Mathf.Max(0.05f, hudRefreshIntervalSeconds);

        float acceptRatio = LastInputSampleCount > 0 ? (float)LastIntegratedSampleCount / LastInputSampleCount : 0f;
        float invalidRatio = LastInputSampleCount > 0 ? (float)LastRejectedInvalidPositionCount / LastInputSampleCount : 0f;
        float outsideRatio = LastInputSampleCount > 0 ? (float)LastRejectedOutsideVolumeCount / LastInputSampleCount : 0f;
        int fallbackSampleCount = GetFallbackSurfaceSampleCount();
        float fallbackFill = maxFallbackSurfaceSamples > 0 ? (float)fallbackSampleCount / maxFallbackSurfaceSamples : 0f;
        int lightCoverBudget = GetLightCoverRenderBudget();
        float renderedFill = lightCoverBudget > 0 ? (float)LastRenderedFallbackSampleCount / lightCoverBudget : 0f;
        int totalRejects =
            LastRejectedInvalidPositionCount +
            LastRejectedDepthRangeCount +
            LastRejectedNormalCount +
            LastRejectedFacingCount +
            LastRejectedConfidenceCount +
            LastRejectedDepthDiscontinuityCount +
            LastRejectedTsdfDepthSupportCount +
            LastRejectedRobustDepthCount +
            LastRejectedTsdfConflictCount +
            LastPendingStableTsdfCount +
            LastPendingTsdfCorrectionCount +
            LastRejectedFallbackWeakCount +
            LastRejectedOutsideVolumeCount;

        bool denseOutsideIsBlocking = !useChunkedSurfaceSamples && outsideRatio > 0.08f;
        bool renderBudgetExceeded = useChunkedSurfaceSamples && fallbackSampleCount > maxFallbackSurfaceSamples;
        bool mainShellIsHolding = LastCandidateShellHeldCellCount + LastDetailCandidateHeldCellCount > Mathf.Max(128, LastMainShellPromotedCellCount);
        bool meshDiagnosticsWarning = LastDiagSuspectPatchCount > 0 || LastDiagNonManifoldEdgeCount > 0;
        bool tumorSuspectWarning = LastTumorSuspectTriangleCount > 0;
        bool warning = invalidRatio > 0.35f || denseOutsideIsBlocking || acceptRatio < 0.25f || LastSkippedFallbackCapacityCount > 0 || LastSurfaceCellConflictCount > 0 || renderBudgetExceeded || mainShellIsHolding || meshDiagnosticsWarning || tumorSuspectWarning;
        _hudText.color = warning ? hudWarningColor : hudHealthyColor;

        string likelyCause = "OK";
        if (LastInputSampleCount <= 0)
            likelyCause = "NO RAW FRAME";
        else if (LastRejectedInvalidPositionCount > Mathf.Max(64, LastIntegratedSampleCount))
            likelyCause = "RAW DEPTH HOLE";
        else if (denseOutsideIsBlocking && LastRejectedOutsideVolumeCount > Mathf.Max(32, LastIntegratedSampleCount / 8))
            likelyCause = "OUTSIDE TSDF VOLUME / START BIAS";
        else if (LastSkippedFallbackCapacityCount > 0)
            likelyCause = "SURFACE CELL CAP HIT";
        else if (LastSurfaceCellConflictCount > 0)
            likelyCause = "SURFACE SIDE CONFLICT";
        else if (tumorSuspectWarning)
            likelyCause = "MESH SUSPECT OVERLAY";
        else if (meshDiagnosticsWarning)
            likelyCause = LastDiagLikelyCause;
        else if (LastRejectedDepthDiscontinuityCount > Mathf.Max(32, LastIntegratedSampleCount / 8))
            likelyCause = "DEPTH EDGE FILTER";
        else if (LastRejectedTsdfDepthSupportCount > Mathf.Max(32, LastIntegratedSampleCount / 8))
            likelyCause = "TSDF DEPTH SUPPORT GATE";
        else if (LastRejectedTsdfConflictCount > Mathf.Max(64, LastUpdatedVoxelCount / 12))
            likelyCause = "TSDF CONFLICT GUARD";
        else if (LastCorrectedTsdfCount > 0)
            likelyCause = "TSDF OLD DEPTH CORRECTED";
        else if (LastPendingTsdfCorrectionCount > Mathf.Max(64, LastRejectedTsdfConflictCount))
            likelyCause = "WAITING OLD DEPTH CORRECTION";
        else if (LastPendingStableTsdfCount > Mathf.Max(128, LastUpdatedVoxelCount / 4))
            likelyCause = "WAITING MULTI-FRAME STABILITY";
        else if (mainShellIsHolding)
            likelyCause = "WAITING MAIN SHELL PROMOTION";
        else if (LastPrunedComponentTriangleCount > Mathf.Max(128, LastPrePruneMeshTriangleCount / 3))
            likelyCause = "MESH ISLAND COMPONENT PRUNE";
        else if (LastSurfaceQuadCandidateCount > 0 && LastAddedSurfaceQuadCount < Mathf.Max(16, LastSurfaceQuadCandidateCount / 8))
            likelyCause = "MESH QUAD ASSEMBLY WEAK";
        else if (LastBoundaryBridgeCandidateCount > 0 && LastAddedBoundaryBridgeCount <= 0)
            likelyCause = "BOUNDARY BRIDGE REJECTED";
        else if (renderBudgetExceeded)
            likelyCause = "RENDER BUDGET THINNING";
        else if (LastRejectedDepthRangeCount > Mathf.Max(32, LastIntegratedSampleCount / 6))
            likelyCause = "DEPTH RANGE FILTER";

        string mainGateText = requireMainShellPromotionGate ? minMainShellFusedFrames + "/" + minMainShellNeighborSurfaceCells : "off";
        string detailText = separateComplexDetailCandidates ? (promoteComplexDetailCandidatesToMesh ? "promote" : "hold") + ":" + minDetailCandidateFrames + "/" + minDetailCandidateNeighborSurfaceCells + "/" + minDetailPromotionNeighborSurfaceCells : "off";
        string supportGateText = gateTsdfWritesByDepthSupport ? minTsdfDepthCheckedNeighbors + "/" + minTsdfDepthConsistencyRatio.ToString("0.00") : "off";
        bool guardedMeshPreview = showExtractedSurfaceMesh && !useFallbackMeshWhenTsdfExtractionEmpty;
        bool strictMeshPreview = guardedMeshPreview && !AllowRelaxedMeshExtraction;
        string displayModeText = LastMeshUsedExtractedTsdf
            ? (useAtomicObservationTsdfBands ? "ATOMIC A/P/R VOXEL-PROJ" : (useStage03ACleanIsoSurface ? (useV08DirectBandWriteForDiagnosis ? "03A V0.8 WRITE / V0.9 MESH" : (UseLegacyMeshExtraction ? (useV09ExactCornerEligibilityForDiagnosis ? "03A V0.9 EXACT DIAG" : "03A CLEAN / V0.9 EXTRACT") : "STAGE 03A CLEAN TSDF")) : (UseLegacyMeshExtraction ? "TSDF EXTRACTION" : (strictMeshPreview ? "STRICT TSDF PREVIEW" : (guardedMeshPreview ? "GUARDED TSDF PREVIEW" : "TSDF EXTRACTION")))))
            : (renderStableCellsAsPlanarMeshCover ? "LIGHT TSDF COVER" : "FALLBACK RAW CELLS");
        bool batchActive = _captureRoutine != null;
        int hudBatchTarget = batchActive ? _activeCaptureBatchTargetFrames : LastCaptureBatchTargetFrames;
        int hudBatchIntegrated = batchActive ? _activeCaptureBatchIntegratedFrames : LastCaptureBatchIntegratedFrames;
        int hudBatchRaw = batchActive ? _activeCaptureBatchUniqueRawFrames : LastCaptureBatchUniqueRawFrames;
        int hudBatchTimeouts = batchActive ? _activeCaptureBatchTimeouts : LastCaptureBatchTimeoutCount;
        string hudBatchResult = batchActive ? "RUN" : (LastCaptureBatchComplete ? "OK" : "WAIT");
        if (compactDiagnosticHud)
        {
            bool meshVisible = _meshRenderer != null && _meshRenderer.enabled;
            bool wireVisible = _wireObject != null && _wireObject.activeSelf;
            bool cyanVisible = _incrementalPatchShadowObject != null && _incrementalPatchShadowObject.activeSelf;
            bool meshReady = (LastMeshTriangleCount > 0 && (meshVisible || wireVisible)) ||
                             (LastAuthoritativeBlockTriangleCount > 0 && cyanVisible);
            bool topologySafe = LastAuthoritativeCanonicalPostRestoreMismatchCount <= 0 &&
                                LastAuthoritativeBlockNonManifoldEdgeCount <= 0 &&
                                LastAuthoritativeBlockRollbackCount <= 0;
            string logStatus = _contributionLedgerWriteFailures > 0
                ? "FAIL"
                : (string.IsNullOrEmpty(_lastHoleDiagnosticPath) ? "OFF" : "OK");
            _hudText.color = meshReady && topologySafe && logStatus != "FAIL" ? hudHealthyColor : hudWarningColor;
            _hudText.text =
                "ScanCover AUTH TSDF\n" +
                $"View RESULT  foreground=YELLOW|GREEN  backend orange/diagnostics logged\n" +
                $"State {(_captureRoutine != null ? "FUSING" : "READY")}  Batch {hudBatchResult} {hudBatchIntegrated}/{hudBatchTarget} raw={hudBatchRaw} timeout={hudBatchTimeouts}\n" +
                $"Dirty blocks={LastIncrementalTsdfDirtyBlockCount} new/change/miss={LastIncrementalTsdfDirtyNewBlockCount}/{LastIncrementalTsdfDirtyChangedBlockCount}/{LastIncrementalTsdfDirtyMissingBlockCount}\n" +
                $"Perf path={(LastCaptureBatchUsedIncrementalProductionRebuild ? "INC" : "FULL")} fallback={(LastCaptureBatchIncrementalProductionFallback ? 1 : 0)} why={LastCaptureBatchIncrementalProductionVerdict} integrate={LastCaptureBatchIntegrationMilliseconds:0}/{LastCaptureBatchMaxFrameIntegrationMilliseconds:0}ms rebuild={LastCaptureBatchMeshRebuildMilliseconds:0}ms\n" +
                $"Fusion queue budget/max={fusionWorkBudgetMillisecondsPerRenderFrame:0.0}/{LastCaptureBatchBudgetedFusionMaxSliceMilliseconds:0.0}ms yields={LastCaptureBatchBudgetedFusionYieldCount} wall={LastCaptureBatchBudgetedFusionWallMilliseconds:0}ms writes unique/merged={LastCaptureBatchUniqueSurfaceVoxelWriteCount}/{LastCaptureBatchMergedSurfaceVoxelWriteCount} refPaused={(LastReferenceClassicPausedForPerformance ? 1 : 0)}\n" +
                $"Rebuild queue budget/max={incrementalRebuildBudgetMillisecondsPerRenderFrame:0.0}/{LastCaptureBatchBudgetedRebuildMaxSliceMilliseconds:0.0}ms yields={LastCaptureBatchBudgetedRebuildYieldCount} compute/wall={LastCaptureBatchMeshRebuildMilliseconds:0}/{LastCaptureBatchMeshRebuildWallMilliseconds:0}ms\n" +
                $"Result chunks active/up/keep/drop={LastPersistentResultChunkActiveCount}/{LastPersistentResultChunkUpdatedCount}/{LastPersistentResultChunkPreservedCount}/{LastPersistentResultChunkRemovedCount} publish={LastPersistentResultChunkPublishMilliseconds:0.0}ms\n" +
                $"Rebuild phase dirty/dep/ext/sem/merge={LastIncrementalProductionDirtyTrackingMilliseconds:0.0}/{LastAuthoritativeBlockDependencyScheduleMilliseconds:0.0}/{LastAuthoritativeBlockExtractionMilliseconds:0.0}/{LastAuthoritativeBlockSemanticFinalizeMilliseconds:0.0}/{LastAuthoritativeBlockCacheMergeMilliseconds:0.0}ms dep keep/drop={LastAuthoritativeBlockDependencyCandidateCount - LastAuthoritativeBlockDependencyPrunedCount}/{LastAuthoritativeBlockDependencyPrunedCount}\n" +
                $"Semantic topo/ind/yellow/relax/class/view={LastPlaneLedgerTopologyMilliseconds:0.0}/{LastPlaneLedgerIndependentAuditMilliseconds:0.0}/{LastPlaneLedgerYellowAuditMilliseconds:0.0}/{LastPlaneLedgerRelaxedAuditMilliseconds:0.0}/{LastPlaneLedgerClassificationMilliseconds:0.0}/{LastPlaneLedgerPresentationMilliseconds:0.0}ms\n" +
                $"Result formal/prov/complex/pending={LastRelaxedCandidateFormalTriangleCount}/{LastRelaxedCandidateProvisionalTriangleCount}/{LastRelaxedCandidateComplexTriangleCount}/{LastRelaxedCandidatePendingTriangleCount} complex lease renew/after/expired={LastConfirmedComplexRenewedCount}/{LastConfirmedComplexLeaseAfterCount}/{LastConfirmedComplexLeaseExpiredCount}\n" +
                $"Volume seq/vox={LastAuthoritativeReadSnapshotSequence}/{LastAuthoritativeReadSnapshotWeightedVoxelCount} legacyMut={LastAuthoritativeLegacyMutationVoxelCount} restore/mismatch={LastAuthoritativeCanonicalRestoreVoxelCount}/{LastAuthoritativeCanonicalPostRestoreMismatchCount}\n" +
                $"Blocks cache/try/ok/empty/rb={LastAuthoritativeBlockCachedCount}/{LastAuthoritativeBlockDirtyAttemptCount}/{LastAuthoritativeBlockRebuiltCount}/{LastAuthoritativeBlockDirectEmptyCount + LastAuthoritativeBlockDependencyEmptyCount}/{LastAuthoritativeBlockRollbackCount} planeΔ={LastAuthoritativePlaneChangedCount}/{LastAuthoritativePlaneInvalidatedBlockCount}\n" +
                $"Split cells/verts={LastAuthoritativeBlockMultiComponentCellCount}/{LastAuthoritativeBlockSplitVertexCount} reject edges/max/mix={LastAuthoritativeBlockRejectedNonManifoldEdgeCount}/{LastAuthoritativeBlockRejectedMaxEdgeIncidence}/{LastAuthoritativeBlockRejectedMixedAxisEdgeCount}\n" +
                $"Mesh tri/edge/nonM={LastAuthoritativeBlockTriangleCount}/{LastAuthoritativeBlockBoundaryEdgeCount}/{LastAuthoritativeBlockNonManifoldEdgeCount}\n" +
                $"Plane mature/app/rb={LastAuthoritativeCyanPlaneMatureCount}/{LastAuthoritativeCyanPlaneAppliedBlockCount}/{LastAuthoritativeCyanPlaneRollbackBlockCount} tri/move/lock={LastAuthoritativeCyanPlaneMatchedTriangleCount}/{LastAuthoritativeCyanPlaneMovedVertexCount}/{LastAuthoritativeCyanPlaneCreaseLockedVertexCount} prop={LastAuthoritativeCyanPlanePropagationAcceptedCount}/{LastAuthoritativeCyanPlanePropagationCandidateCount} shared/mis={LastAuthoritativeCyanPlaneSharedVertexKeyCount}/{LastAuthoritativeCyanPlaneSharedPositionMismatchCount} res={LastAuthoritativeCyanPlaneResidualBeforeMeters:F3}>{LastAuthoritativeCyanPlaneResidualAfterMeters:F3}\n" +
                $"Local support c/l/g={LastAuthoritativeCyanLocalSupportCandidateTileCount}/{LastAuthoritativeCyanLocalSupportQualifiedTileCount}/{LastAuthoritativeCyanLocalSupportGlobalTileCount} samp={LastAuthoritativeCyanLocalSupportMatchedSampleCount}/{LastAuthoritativeCyanLocalSupportInputSampleCount} +/-={LastAuthoritativeCyanLocalSupportPromotedTileCount}/{LastAuthoritativeCyanLocalSupportDemotedTileCount} tri={LastAuthoritativeCyanLocalSupportMatchedTriangleCount}\n" +
                $"Result F/P/C={LastOutputResultFormalTriangleCount}/{LastOutputResultProvisionalTriangleCount}/{LastOutputResultComplexTriangleCount} held={LastOutputResultHeldRescueTriangleCount} keep/reject={LastOutputResultPromotedTriangleCount}/{LastOutputResultRejectedTriangleCount}  Diag P/I/U/B={LastOutputDiagnosticPendingTriangleCount}/{LastOutputDiagnosticIllegalTriangleCount}/{LastOutputDiagnosticUnclassifiedTriangleCount}/{LastOutputDiagnosticPromotionBlockedTriangleCount}\n" +
                $"Audit I ok/no/id/q={LastIndependentStructuralSupportedTriangleCount}/{LastIndependentStructuralNoSupportTriangleCount}/{LastIndependentStructuralIdentityConflictTriangleCount}/{LastIndependentStructuralQualificationFailureTriangleCount} gap a/e/m/b/w/r={LastPlaneSupportGapCellCount}/{LastPlaneSupportGapNoTriangleCount}/{LastPlaneSupportGapHeldCount}/{LastPlaneSupportGapNonplanarCount}/{LastPlaneSupportGapWrongPlaneCount}/{LastPlaneSupportGapIllegalCount} dir/unobs={LastPlaneSupportDirectEvidenceCellCount}/{LastPlaneSupportUnobservedCellCount} unk={LastPlaneSupportUnknownWithTrianglesCount}/{LastPlaneSupportUnknownEmptyCount} cut={LastPlaneSupportTruncatedCellCount}\n" +
                $"Log {logStatus}  rounds={CompletedCaptureBatchCount}";
            return;
        }
        if (useStage03ACleanIsoSurface)
        {
            bool meshVisible = _meshRenderer != null && _meshRenderer.enabled;
            bool wireVisible = _wireObject != null && _wireObject.activeSelf;
            bool meshReady = LastMeshTriangleCount > 0 && (meshVisible || wireVisible);
            _hudText.color = meshReady ? hudHealthyColor : hudWarningColor;
            _hudText.text =
                "ScanCover STAGE 03A\n" +
                $"State : {(_captureRoutine != null ? "FUSING" : "READY")} / {(meshReady ? "MESH READY" : likelyCause)}  f={LastRawFrameIndex}/{IntegratedFrameCount}\n" +
                $"Batch : {hudBatchResult} {hudBatchIntegrated}/{hudBatchTarget} raw={hudBatchRaw} timeout={hudBatchTimeouts} rebuild={LastCaptureBatchMeshRebuildCount}/{LastCaptureBatchMeshRebuildMilliseconds:0}ms\n" +
                $"Input : {LastIntegratedSampleCount}/{LastInputSampleCount} {acceptRatio:P0}  updated={LastUpdatedVoxelCount}\n" +
                $"Bands : A/P={LastAtomicAcceptedBandVoxelWriteCount}/{LastAtomicProvisionalBandVoxelWriteCount}  up/down={LastAtomicPromotedProvisionalVoxelCount}/{LastAtomicRetiredProvisionalVoxelCount}\n" +
                $"Backing: keep/weak/nonA/prov={LastAtomicProvisionalMatureBackingPreservedCount}/{LastAtomicProvisionalMatureBackingWeakBlockedCount}/{LastAtomicProvisionalNonAtomicBlockedCount}/{LastAtomicProvisionalBackingProvenanceBlockedCount}\n" +
                $"BDelta : cell/quad/bound/conf/anchor={LastAtomicProvisionalBackingRestoredCellCount}/{LastAtomicProvisionalBackingRestoredQuadCount}/{LastAtomicProvisionalBackingRestoredBoundaryEdgeCount}/{LastAtomicProvisionalBackingRestoredConflictEdgeCount}/{LastAtomicProvisionalBackingPlaneAnchorAllowedCount}\n" +
                $"BArb  : cand/ok/layer/topo/wind={LastAtomicRestoredArbitrationCandidateCount}/{LastAtomicRestoredArbitrationAcceptedCount}/{LastAtomicRestoredArbitrationBlockedLayerCount}/{LastAtomicRestoredArbitrationBlockedTopologyCount}/{LastAtomicRestoredArbitrationBlockedWindingCount}\n" +
                $"NArb  : old/cand/ok/layer/topo/wind={LastNewbornArbitrationPersistedFirstCount}/{LastNewbornArbitrationCandidateCount}/{LastNewbornArbitrationAcceptedCount}/{LastNewbornArbitrationBlockedLayerCount}/{LastNewbornArbitrationBlockedTopologyCount}/{LastNewbornArbitrationBlockedWindingCount}\n" +
                $"LSwap : chk/better/evOK/elig/wait/app/drop/mat/ev/bnd/rb={LastNewbornLayerSwapCheckedCount}/{LastNewbornLayerSwapBoundaryImprovingCount}/{LastNewbornLayerSwapGroupEvidenceAcceptedCount}/{LastNewbornLayerSwapEligibleCount}/{LastNewbornLayerSwapPendingCount}/{LastNewbornLayerSwapAppliedCount}/{LastNewbornLayerSwapRemovedCount}/{LastNewbornLayerSwapBlockedMatureCount}/{LastNewbornLayerSwapBlockedEvidenceCount}/{LastNewbornLayerSwapBlockedBoundaryCount}/{LastNewbornLayerSwapRollbackCount}\n" +
                $"SPlane: chk/match/sup/norm/res/prov/score/wait/app={LastSamePlaneLayerEvidenceCheckedCount}/{LastSamePlaneLayerEvidenceMatchedCount}/{LastSamePlaneLayerEvidenceBlockedSupportCount}/{LastSamePlaneLayerEvidenceBlockedNormalCount}/{LastSamePlaneLayerEvidenceBlockedResidualCount}/{LastSamePlaneLayerEvidenceProvisionalAllowedCount}/{LastSamePlaneLayerEvidenceScoreOverrideCount}/{LastSamePlaneLayerEvidencePendingCount}/{LastSamePlaneLayerEvidenceAppliedCount}\n" +
                $"SPatch: grp/q/better/bnd/mat/ev/topo/wait/appQ/drop/rb={LastSamePlaneAtomicPatchGroupCount}/{LastSamePlaneAtomicPatchCandidateQuadCount}/{LastSamePlaneAtomicPatchBoundaryImprovingCount}/{LastSamePlaneAtomicPatchBlockedBoundaryCount}/{LastSamePlaneAtomicPatchBlockedMatureCount}/{LastSamePlaneAtomicPatchBlockedEvidenceCount}/{LastSamePlaneAtomicPatchBlockedTopologyCount}/{LastSamePlaneAtomicPatchPendingCount}/{LastSamePlaneAtomicPatchAppliedQuadCount}/{LastSamePlaneAtomicPatchRemovedBlockerCount}/{LastSamePlaneAtomicPatchRollbackCount}\n" +
                $"PHold : scan/cand/ok/contra/geom/arb={LastProvisionalHeldRetentionScannedCount}/{LastProvisionalHeldRetentionCandidateCount}/{LastProvisionalHeldRetentionAcceptedCount}/{LastProvisionalHeldRetentionBlockedContradictionCount}/{LastProvisionalHeldRetentionBlockedGeometryCount}/{LastProvisionalHeldRetentionBlockedLayerCount + LastProvisionalHeldRetentionBlockedTopologyCount + LastProvisionalHeldRetentionBlockedWindingCount}\n" +
                $"NPx   : block/pair/free/new/old/amb={LastNewbornPholdCompetitionBlockedNewbornCount}/{LastNewbornPholdCompetitionPairCount}/{LastNewbornPholdCompetitionFullyResolvableCount}/{LastNewbornPholdCompetitionNewbornPreferredCount}/{LastNewbornPholdCompetitionPholdPreferredCount}/{LastNewbornPholdCompetitionAmbiguousCount}\n" +
                $"NRep  : wait/apply/drop/rb={LastNewbornPholdReplacementPendingCount}/{LastNewbornPholdReplacementAppliedCount}/{LastNewbornPholdReplacementRemovedPholdCount}/{LastNewbornPholdReplacementRollbackCount}\n" +
                $"NProb : live/ok/rb/cand/keep/contra/geom/arb={LastNewbornPholdProbationPendingCount}/{LastNewbornPholdProbationConfirmedCount}/{LastNewbornPholdProbationRollbackTransactionCount}/{LastNewbornPholdProbationRollbackCandidateCount}/{LastNewbornPholdProbationRollbackAcceptedCount}/{LastNewbornPholdProbationRollbackContradictionBlockedCount}/{LastNewbornPholdProbationRollbackGeometryBlockedCount}/{LastNewbornPholdProbationRollbackLayerBlockedCount + LastNewbornPholdProbationRollbackTopologyBlockedCount + LastNewbornPholdProbationRollbackWindingBlockedCount}\n" +
                $"Rupt  : edge/gap/depth/rob/sup/view/raw/tsdf/plane/arb={LastSpatialRuptureBoundaryEdgeCount}/{LastSpatialRuptureRawGapCount}/{LastSpatialRuptureDepthEdgeCount}/{LastSpatialRuptureRobustCount}/{LastSpatialRuptureSupportCount}/{LastSpatialRuptureViewConflictCount}/{LastSpatialRuptureOtherRawCount}/{LastSpatialRuptureTsdfStateCount}/{LastSpatialRupturePlaneRejectCount}/{LastSpatialRuptureArbitrationCount}\n" +
                $"Angle : front/obliq/graze/ext A:T={LastRawCoverageFrontAcceptedCount}:{LastRawCoverageFrontSampleCount}/{LastRawCoverageObliqueAcceptedCount}:{LastRawCoverageObliqueSampleCount}/{LastRawCoverageGrazingAcceptedCount}:{LastRawCoverageGrazingSampleCount}/{LastRawCoverageExtremeAcceptedCount}:{LastRawCoverageExtremeSampleCount}\n" +
                $"GPlane: chk/sup/depth/edge/median={LastGrazingPlaneCheckedSampleCount}/{LastGrazingPlaneSupportedSampleCount}/{LastGrazingPlaneDepthNeighborRescueCount}/{LastGrazingPlaneEdgeExemptionCount}/{LastGrazingPlaneMedianCorrectionSkippedCount}\n" +
